    private readonly Dictionary<string, CancellationTokenSource> _installCtsById = new();
    private readonly object _installCtsLock = new();

    private (CancellationToken token, IDisposable scope) BeginCancellableOp(string progressId)
    {
        var cts = new CancellationTokenSource();
        return (cts.Token, RegisterInstallCts(progressId, cts));
    }

    private IDisposable RegisterInstallCts(string progressId, CancellationTokenSource cts)
    {
        lock (_installCtsLock)
        {
            if (_installCtsById.TryGetValue(progressId, out var prior) && !ReferenceEquals(prior, cts))
            {
                try { prior.Cancel(); } catch { }
            }
            _installCtsById[progressId] = cts;
        }
        return new CancellableScope(this, progressId, cts);
    }

    private sealed class CancellableScope : IDisposable
    {
        private readonly AppBridge _owner;
        private readonly string _id;
        private readonly CancellationTokenSource _cts;
        private int _disposed;
        public CancellableScope(AppBridge owner, string id, CancellationTokenSource cts)
        { _owner = owner; _id = id; _cts = cts; }
        public void Dispose()
        {
            if (Interlocked.Exchange(ref _disposed, 1) != 0) return;
            lock (_owner._installCtsLock)
            {
                if (_owner._installCtsById.TryGetValue(_id, out var cur) && ReferenceEquals(cur, _cts))
                    _owner._installCtsById.Remove(_id);
            }
            try { _cts.Dispose(); } catch { }
        }
    }

    public Task<bool> InstallCancelAsync(string progressId)
    {
        lock (_installCtsLock)
        {
            if (_installCtsById.TryGetValue(progressId, out var cts))
            {
                try { cts.Cancel(); return Task.FromResult(true); }
                catch (Exception ex) { Debug.WriteLine($"[install.cancel] {progressId}: {ex.Message}"); }
            }
        }
        return Task.FromResult(false);
    }

