    internal static volatile string? LastProblemDownloadUrl;

    internal void AttachEventEmitter(Action<string, object?> emit)
    {
        _emitEvent = emit;
        _emitStatic = emit;

        Services.ParallelDownloader.OnSlowDownload = (host, kbps) =>
        {
            emit("download:slow", new { host, kbps });
            _ = Task.Run(async () =>
            {
                try
                {
                    var report = await Services.NetworkDoctor.RunAsync(LastProblemDownloadUrl);
                    emit("download:diagnosis", report);
                }
                catch (Exception ex)
                {
                    Debug.WriteLine($"[doctor] авто-прогон не удался: {ex.Message}");
                }
            });
        };

        MiamiGraphics.Shell.Services.UpdateRpfMutex.GameRunning = () =>
        {
            try { emit?.Invoke("app:gtaRunning", null); } catch {}
        };

        MiamiGraphics.Shell.Services.UpdateRpfMutex.Sealing = ResealUpdateRpfSha;

        const string queuedDetail = "В очереди - ждём завершения другой установки...";
        MiamiGraphics.Shell.Services.UpdateRpfMutex.Contended = label =>
        {
            try
            {
                switch (label)
                {
                    case "trees-install":
                        EmitInstallProgress("trees-install", "Установка деревьев", "queued", 0, null, queuedDetail);
                        return;
                    case "trees-restore":
                        EmitInstallProgress("trees-restore", "Возврат стандартных деревьев", "queued", 0, null, queuedDetail);
                        return;
                    case "roads-install":
                        EmitInstallProgress("roads-install", "Установка дорог", "queued", 0, null, queuedDetail);
                        return;
                    case "roads-restore":
                        EmitInstallProgress("roads-restore", "Возврат стандартных дорог", "queued", 0, null, queuedDetail);
                        return;
                }

                int firstColon = label.IndexOf(':');
                if (firstColon < 0) return;
                string kind = label.Substring(0, firstColon);
                string tail = label.Substring(firstColon + 1);

                switch (kind)
                {
                    case "redux-install":
                    case "redux-preserve":
                    case "redux-customize":
                        EmitInstallProgress(tail, "Установка Redux",       "queued", 0, null, queuedDetail);
                        return;
                    case "redux-armorswap":
                        EmitInstallProgress(tail, "Свап брони",             "queued", 0, null, queuedDetail);
                        return;
                    case "armor-library-install":
                    case "armor-standalone":
                        EmitInstallProgress(tail, "Установка брони",        "queued", 0, null, queuedDetail);
                        return;
                    case "hnt-apply":
                        EmitInstallProgress(tail, "Применение сборки",      "queued", 0, null, queuedDetail);
                        return;
                    case "minimap-apply":
                    {
                        int c = tail.IndexOf(':');
                        string emitId = c < 0
                            ? "minimap-swap-" + tail
                            : "minimap-swap-" + tail.Substring(0, c) + "-" + tail.Substring(c + 1);
                        EmitInstallProgress(emitId, "Установка миникарты", "queued", 0, null, queuedDetail);
                        return;
                    }
                    case "reticle-apply":
                    {
                        int c = tail.IndexOf(':');
                        string emitId = c < 0
                            ? "reticle-swap-" + tail
                            : "reticle-swap-" + tail.Substring(0, c) + "-" + tail.Substring(c + 1);
                        EmitInstallProgress(emitId, "Установка прицела",   "queued", 0, null, queuedDetail);
                        return;
                    }
                    case "sound-install":
                        EmitInstallProgress("sounds-install-" + tail, "Установка звуков", "queued", 0, null, queuedDetail);
                        return;
                    case "timecycle-install":
                        EmitInstallProgress("timecycle-install-" + tail, "Установка таймцикла", "queued", 0, null, queuedDetail);
                        return;
                    case "gunpack-install-all":
                        EmitGunpackInstallProgress(tail, "queued", 0, null, queuedDetail);
                        return;
                    case "selected-guns":
                    {
                        int c = tail.LastIndexOf(':');
                        string internalName = c < 0 ? tail : tail.Substring(c + 1);
                        _emitEvent?.Invoke(Services.SelectedGunsInstaller.PROGRESS_EVENT, new
                        {
                            internalName,
                            phase         = "queued",
                            percent       = 0,
                            errorMessage  = (string?)null,
                            detailMessage = queuedDetail,
                        });
                        return;
                    }
                    case "graphics-install":
                        EmitInstallProgress("graphics-install-" + tail, "Установка графики", "queued", 0, null, queuedDetail);
                        return;
                    case "graphics-restore":
                        EmitInstallProgress("graphics-restore-" + tail, "Откат графики", "queued", 0, null, queuedDetail);
                        return;
                    default:
                        return;
                }
            }
            catch {}
        };
    }
    internal void AttachAssetCache(Services.AssetCache cache) => _assetCache = cache;

    public Task<List<bool>> AssetCacheContainsAsync(List<string> urls)
    {
        if (_assetCache is null)
            return Task.FromResult(urls.Select(_ => false).ToList());
        return Task.FromResult(urls.Select(u => _assetCache.Contains(u)).ToList());
    }

    public async Task<List<string>> GunpackAllGunPreviewUrlsAsync()
    {
        try
        {
            var rows = await _supabase.SelectAllPagedAsync<GunPreviewUrlRow>(
                "gunpack_guns", "select=preview_url&preview_url=not.is.null");
            return rows
                .Select(r => r.PreviewUrl)
                .Where(u => !string.IsNullOrWhiteSpace(u))
                .Select(u => u!)
                .Distinct()
                .ToList();
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[gunpackAllGunPreviewUrls] failed: {ex.Message}");
            return new List<string>();
        }
    }

