    public async Task<int> AssetCachePrewarmAsync(List<string> urls)
    {
        if (_assetCache is null || urls.Count == 0) return 0;

        var region = Services.ServerRegionStore.EffectiveRegion();

        using var http = new HttpClient { Timeout = TimeSpan.FromSeconds(12) };
        var fetched = 0;
        var failed = 0;
        var skipped = 0;

        var logPath = Path.Combine(
            Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
            "MiamiGraphics", "prewarm.log");
        var logLock = new object();
        try { Directory.CreateDirectory(Path.GetDirectoryName(logPath)!); File.WriteAllText(logPath, ""); } catch { }
        void Log(string s)
        {
            Debug.WriteLine(s);
            try { lock (logLock) File.AppendAllText(logPath, DateTime.Now.ToString("HH:mm:ss.fff ") + s + "\r\n"); }
            catch { }
        }
        Log($"[prewarm] starting: {urls.Count} URLs, region={region}, log={logPath}");

        using var sem = new SemaphoreSlim(24);
        var tasks = urls.Select(async url =>
        {
            if (_assetCache.Contains(url)) { Interlocked.Increment(ref skipped); return; }
            await sem.WaitAsync();
            try
            {
                var effective = RewriteForRegion(url, region);

                for (var attempt = 0; attempt < 2; attempt++)
                {
                    try
                    {
                        using var req = new HttpRequestMessage(HttpMethod.Get, effective);
                        req.Headers.TryAddWithoutValidation("User-Agent",
                            "Mozilla/5.0 (Windows NT 10.0; Win64; x64) MiamiGraphics/1.1");
                        using var resp = await http.SendAsync(req, HttpCompletionOption.ResponseContentRead);
                        if ((int)resp.StatusCode >= 400 && (int)resp.StatusCode < 500)
                        {
                            Log($"[prewarm] {(int)resp.StatusCode} {url}");
                            Interlocked.Increment(ref failed);
                            _assetCache.PutNotFoundMarker(url);
                            return;
                        }
                        if (!resp.IsSuccessStatusCode)
                        {
                            if (attempt == 1) { Interlocked.Increment(ref failed); return; }
                            continue;
                        }
                        var body = await resp.Content.ReadAsByteArrayAsync();
                        if (body.Length == 0)
                        {
                            if (attempt == 1) { Interlocked.Increment(ref failed); return; }
                            continue;
                        }
                        var ct = resp.Content.Headers.ContentType?.ToString() ?? "application/octet-stream";
                        _assetCache.Put(url, body, ct);
                        Interlocked.Increment(ref fetched);
                        return;
                    }
                    catch (Exception ex) when (attempt == 0)
                    {
                        Log($"[prewarm] {url}: attempt 1 {ex.GetType().Name}: {ex.Message}, retrying");
                    }
                    catch (Exception ex)
                    {
                        Log($"[prewarm] {url}: final {ex.GetType().Name}: {ex.Message}");
                        Interlocked.Increment(ref failed);
                        return;
                    }
                }
            }
            finally { sem.Release(); }
        });
        await Task.WhenAll(tasks);
        _assetCache.EvictIfOversize();
        Log($"[prewarm] DONE total={urls.Count} skipped={skipped} fetched={fetched} failed={failed}");
        return fetched;
    }

    private static string RewriteForRegion(string url, Services.ServerRegion region)
    {
        if (region != Services.ServerRegion.Ru) return url;
        if (!Uri.TryCreate(url, UriKind.Absolute, out var uri)) return url;
        if (!string.Equals(uri.Host, "miamigraphicsstorage.uk", StringComparison.OrdinalIgnoreCase) &&
            !string.Equals(uri.Host, "cdn.miamigraphicsstorage.uk", StringComparison.OrdinalIgnoreCase))
            return url;
        return new UriBuilder(uri) { Scheme = "https", Host = "ru.miamigraphicsstorage.uk", Port = -1 }.Uri.ToString();
    }

    public async Task<SystemInfoDto> GetSystemInfoAsync()
    {
        var gtaPath = await GetGtaPathAsync();
        return await Task.Run(() =>
        {
            var gpu = _hardwareLocator.FindGpuName();
            string? exeVersion = null;
            if (!string.IsNullOrWhiteSpace(gtaPath))
            {
                var exePath = Path.Combine(gtaPath, "GTA5.exe");
                if (File.Exists(exePath))
                    exeVersion = FileVersionInfo.GetVersionInfo(exePath).FileVersion;
            }
            return new SystemInfoDto(string.IsNullOrWhiteSpace(gtaPath) ? null : gtaPath,
                gpu, exeVersion, !string.IsNullOrWhiteSpace(gtaPath));
        });
    }

    public Task<string> GetAppVersionAsync()
    {
        var v = System.Reflection.Assembly.GetExecutingAssembly().GetName().Version;
        var s = v is null ? "0.0.0" : $"{v.Major}.{v.Minor}.{v.Build}";
        return Task.FromResult(s);
    }

