    public Task<string?> OpenFileDialogAsync(string? filterDescription, string? filterPattern)
    {
        var tcs = new TaskCompletionSource<string?>();
        Application.Current.Dispatcher.Invoke(() =>
        {
            try
            {
                var dlg = new Microsoft.Win32.OpenFileDialog
                {
                    Title = filterDescription ?? "Select file",
                    Multiselect = false,
                };
                if (!string.IsNullOrWhiteSpace(filterPattern))
                    dlg.Filter = $"{filterDescription ?? "Files"} ({filterPattern})|{filterPattern}|All files (*.*)|*.*";
                var ok = dlg.ShowDialog(Application.Current.MainWindow);
                tcs.SetResult(ok == true ? dlg.FileName : null);
            }
            catch (Exception ex) { Debug.WriteLine($"OpenFileDialog error: {ex.Message}"); tcs.SetResult(null); }
        });
        return tcs.Task;
    }

    public Task<string[]> OpenFileDialogMultiAsync(string? filterDescription, string? filterPattern)
