    private static CacheSettingsDto BuildCacheSettingsDto()
    {
        var cacheBytes  = Core.System.AppDataRoot.CacheSizeBytes();
        var backupBytes = Core.System.AppDataRoot.BackupSizeBytes();
        var workBytes   = Core.System.AppDataRoot.WorkSizeBytes();
        return new CacheSettingsDto(
            Core.System.AppDataRoot.ReuseCache,
            Core.System.AppDataRoot.Override,
            Core.System.AppDataRoot.CacheRoot,
            Core.System.AppDataRoot.DefaultCacheRoot,
            cacheBytes,
            DataRoot:           Core.System.AppDataRoot.Base,
            DefaultDataRoot:    Core.System.AppDataRoot.DefaultBase,
            BackupRoot:         Core.System.AppDataRoot.BackupRoot,
            BackupBytes:        backupBytes,
            TotalBytes:         cacheBytes + backupBytes + workBytes,
            WorkBytes:          workBytes,
            WorkRoot:           Core.System.AppDataRoot.WorkRoot,
            LimitBytes:         Core.System.AppDataRoot.LimitBytes,
            MinLimitBytes:      Core.System.AppDataRoot.MinLimitBytes,
            MaxLimitBytes:      Core.System.AppDataRoot.MaxLimitBytes,
            ProtectedBytes:     Core.System.DataQuota.ProtectedBytes(),
            FreeSpaceBytes:     Core.System.AppDataRoot.FreeSpaceBytes(Core.System.AppDataRoot.Base),
            BackupOnLegacyRoot: Core.System.AppDataRoot.BackupOnLegacyRoot,
            OtherBytes:         Core.System.DataQuota.OtherBytes(cacheBytes + backupBytes + workBytes));
    }

    public Task<CacheSettingsDto> CacheSettingsGetAsync()
        => Task.Run(BuildCacheSettingsDto);

    public Task<CacheSettingsDto> CacheSettingsSetAsync(bool enabled, string? rootOverride)
        => Task.Run(() =>
        {
            MiamiGraphics.Shell.Services.ModCacheSettings.Set(enabled, rootOverride);
            return BuildCacheSettingsDto();
        });

    public Task<CacheSettingsDto> CacheLimitSetAsync(long limitBytes)
        => Task.Run(() =>
        {
            Core.System.AppDataRoot.Set(limitBytes: limitBytes);
            Core.System.DataQuota.Sweep();
            return BuildCacheSettingsDto();
        });

    public Task<CacheCleanupResultDto> CacheCleanupNowAsync()
        => Task.Run(() =>
        {
            var r = Core.System.DataQuota.Sweep(waitForConcurrent: TimeSpan.FromSeconds(20));

            var holders = Core.System.DataQuota.ProtectedHolders()
                .Select(h => new QuotaHolderDto(h.Name, h.Bytes))
                .ToList();
            var reclaimable = Core.System.DataQuota.ReclaimableBytes();
            var other       = Core.System.DataQuota.OtherBytes(r.AfterBytes);

            return new CacheCleanupResultDto(
                r.BeforeBytes, r.AfterBytes, r.FreedBytes, r.DeletedEntries, r.StillOverLimit,
                Reason:           r.Reason,
                ProtectedBytes:   r.ProtectedBytes,
                ReclaimableBytes: reclaimable,
                OtherBytes:       other,
                Holders:          holders);
        });

    private CancellationTokenSource? _dataMoveCts;

    public async Task<DataMoveResultDto> DataRootMoveAsync(string targetDir)
    {
        var progress = new Progress<Core.System.DataMoveProgress>(p =>
            _emitEvent?.Invoke("data:moveProgress", new DataMoveProgressDto(
                p.Phase, p.Percent, p.FileName, p.BytesProcessed, p.BytesTotal, p.ErrorMessage)));

        var cts = new CancellationTokenSource();
        var prev = Interlocked.Exchange(ref _dataMoveCts, cts);
        prev?.Dispose();
        try
        {
            var r = await Core.System.DataRootMigration.MoveAsync(targetDir, progress, cts.Token);

            if (r.Success)
            {
                try { Services.SessionLog.Info("data-move", $"данные переехали в {r.EffectiveRoot} ({r.MovedBytes / (1024 * 1024)} МБ)"); }
                catch { }
            }

            return new DataMoveResultDto(r.Success, r.EffectiveRoot, r.MovedBytes, r.SourceRemoved, r.ErrorMessage);
        }
        finally
        {
            Interlocked.CompareExchange(ref _dataMoveCts, null, cts);
            cts.Dispose();
        }
    }

    public Task DataRootMoveCancelAsync()
    {
        try
        {
            _dataMoveCts?.Cancel();
            Debug.WriteLine("[data-move] отмена по кнопке");
        }
        catch (ObjectDisposedException) {}
        return Task.CompletedTask;
    }

    public Task<bool> ValidateGtaPathAsync(string path) => Task.Run(() =>
    {
        if (string.IsNullOrWhiteSpace(path)) return false;
        if (!Directory.Exists(path)) return false;
        return File.Exists(Path.Combine(path, "GTA5.exe"));
    });

    public Task OpenLogsFolderAsync() => Task.Run(() =>
    {
        try
        {
            var dir = Services.SessionLog.LogDir;
            Directory.CreateDirectory(dir);

            var logFile = Services.SessionLog.LogFile;
            var args = File.Exists(logFile) ? $"/select,\"{logFile}\"" : $"\"{dir}\"";
            Process.Start(new ProcessStartInfo
            {
                FileName = "explorer.exe",
                Arguments = args,
                UseShellExecute = true,
            });
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[logs] open folder failed: {ex.Message}");
            Services.SessionLog.Warn("logs", $"open logs folder failed: {ex.Message}");
        }
    });

    public Task<List<GunpackBatchEntryDto>> ScanGunpackBatchFolderAsync(string parentPath) => Task.Run(() =>
    {
        var result = new List<GunpackBatchEntryDto>();
        if (string.IsNullOrWhiteSpace(parentPath) || !Directory.Exists(parentPath))
            return result;

        IEnumerable<string> subDirs;
        try { subDirs = Directory.EnumerateDirectories(parentPath).OrderBy(d => d, StringComparer.OrdinalIgnoreCase); }
        catch (Exception ex)
        {
            Debug.WriteLine($"ScanGunpackBatchFolder enumerate error: {ex.Message}");
            return result;
        }

        var imageExts = new[] { ".png", ".jpg", ".jpeg", ".webp", ".gif" };

        foreach (var dir in subDirs)
        {
            var folderName = Path.GetFileName(dir);
            string? rpfPath = null;
            string? imagePath = null;

            try
            {

                var dlcRpf = Path.Combine(dir, "dlc.rpf");
                if (File.Exists(dlcRpf))
                {
                    rpfPath = dlcRpf;
                }
                else
                {
                    var firstRpf = Directory.EnumerateFiles(dir, "*.rpf", SearchOption.TopDirectoryOnly).FirstOrDefault();
                    if (firstRpf is not null) rpfPath = firstRpf;
                }

                foreach (var ext in imageExts)
                {
                    var match = Directory.EnumerateFiles(dir, "*" + ext, SearchOption.TopDirectoryOnly).FirstOrDefault();
                    if (match is not null) { imagePath = match; break; }
                }
            }
            catch (Exception ex)
            {
                Debug.WriteLine($"ScanGunpackBatchFolder scan {dir}: {ex.Message}");
            }

            result.Add(new GunpackBatchEntryDto(
                FolderName: folderName,
                FolderPath: dir,
                RpfPath:    rpfPath,
                ImagePath:  imagePath
            ));
        }

        return result;
    });

    public Task WindowMinimizeAsync() => Application.Current.Dispatcher.InvokeAsync(() =>
    {
        if (Application.Current.MainWindow is { } w) w.WindowState = WindowState.Minimized;
    }).Task;

    public Task WindowMaximizeAsync() => Application.Current.Dispatcher.InvokeAsync(() =>
    {
        if (Application.Current.MainWindow is { } w)
            w.WindowState = w.WindowState == WindowState.Maximized ? WindowState.Normal : WindowState.Maximized;
    }).Task;

    public Task WindowSetFullscreenAsync(bool on) => Application.Current.Dispatcher.InvokeAsync(() =>
