        if (Application.Current.MainWindow is MiamiGraphics.Shell.MainWindow w) w.SetFullscreen(on);
    }).Task;

    public void NotifyWindowState(bool maximized)
        => _emitEvent?.Invoke("window:state", new { maximized });

    public Task WindowCloseAsync() => Application.Current.Dispatcher.InvokeAsync(() =>
    {
        Application.Current.MainWindow?.Close();
    }).Task;

    public Task WindowStartDragAsync() => Application.Current.Dispatcher.InvokeAsync(() =>
    {
        if (Application.Current.MainWindow is not { } w) return;
        try
        {

            if (w.WindowState == WindowState.Maximized) w.WindowState = WindowState.Normal;
            var hwnd = new WindowInteropHelper(w).Handle;
            if (hwnd != IntPtr.Zero)
            {
                ReleaseCapture();
                SendMessage(hwnd, WM_NCLBUTTONDOWN, new IntPtr(HTCAPTION), IntPtr.Zero);
                return;
            }

            w.DragMove();
        }
        catch
        {

        }
    }).Task;

    public async Task<AuthResultDto> AuthenticateUserAsync(string login, string password, string? totp)
    {
        Repositories.Models.User? user;
        try
        {
            user = await _userRepo.AuthenticateAsync(login, password);
        }
        catch (SupabaseException sx)
        {

            var msg = sx.Kind switch
            {
                SupabaseErrorKind.Network        => Loc.T("errors.auth.serverUnreachable"),
                SupabaseErrorKind.NotProvisioned => Loc.T("errors.auth.dbNotProvisioned"),
                SupabaseErrorKind.Unauthorized   => Loc.T("errors.auth.apiKeyRejected"),
                _                                => Loc.T("errors.auth.serverError", ("message", sx.Message)),
            };
            throw new InvalidOperationException(msg, sx);
        }

        if (user is null)
            throw new InvalidOperationException(Loc.T("errors.auth.badCredentials"));
        return new AuthResultDto($"local-{user.Id}", user.Role, user.Username, user.TesterAccess);
    }

