    });

    public Task<bool> AttachReferralAsync(string code) => Task.Run(async () =>
    {
        var c = (code ?? string.Empty).Trim();
        if (c.Length == 0) c = Repositories.Supabase.SupabaseUserRepository.ReadInstallerPromo();
        if (c.Length == 0) return false;
        return _userRepo is Repositories.Supabase.SupabaseUserRepository sur
            && await sur.AttachReferralAsync(c);
    });

