    private static string? _hwidCache;
    private static string ComputeHwid()
    {
        if (_hwidCache is not null) return _hwidCache;
        string raw;
        try
        {
            using var key = Microsoft.Win32.Registry.LocalMachine.OpenSubKey(@"SOFTWARE\Microsoft\Cryptography");
            var guid = key?.GetValue("MachineGuid") as string ?? "";
            raw = guid + "|" + Environment.MachineName;
        }
        catch { raw = "fallback|" + Environment.MachineName; }
        using var sha = SHA256.Create();
        _hwidCache = Convert.ToHexString(sha.ComputeHash(System.Text.Encoding.UTF8.GetBytes(raw))).ToLowerInvariant();
        return _hwidCache;
    }

