    private static string MapRegisterError(SupabaseException sx)
    {
        var raw = sx.Message ?? string.Empty;
        return sx.Kind switch
        {
            SupabaseErrorKind.Network        => "Сервер недоступен. Проверьте интернет-соединение.",
            SupabaseErrorKind.NotProvisioned => "База данных не инициализирована. Примените миграции supabase/migrations.",
            SupabaseErrorKind.Unauthorized   => "Сервер отклонил API-ключ. Обратитесь к администратору.",
            SupabaseErrorKind.Conflict when raw.Contains("username_taken") => "Имя пользователя уже занято. Выберите другое.",
            SupabaseErrorKind.Conflict when raw.Contains("email_taken")    => "Пользователь с таким email уже зарегистрирован.",
            SupabaseErrorKind.Conflict       => "Email или имя пользователя уже заняты.",
            SupabaseErrorKind.BadRequest when raw.Contains("username_invalid")     => "Имя может содержать только латиницу, цифры и `_` (3–32 символа).",
            SupabaseErrorKind.BadRequest when raw.Contains("username_too_short")   => "Имя должно содержать минимум 3 символа.",
            SupabaseErrorKind.BadRequest when raw.Contains("email_invalid")        => "Некорректный email.",
            SupabaseErrorKind.BadRequest when raw.Contains("email_required")       => "Введите email.",
            SupabaseErrorKind.BadRequest when raw.Contains("password_hash_invalid")=> "Пароль должен быть не короче 8 символов.",
            SupabaseErrorKind.BadRequest when raw.Contains("code_required")        => "Введите код подтверждения.",
            SupabaseErrorKind.BadRequest when raw.Contains("code_not_found")       => "Код не найден. Запросите новое письмо.",
            SupabaseErrorKind.BadRequest when raw.Contains("code_used")            => "Код уже использован. Запросите новый.",
            SupabaseErrorKind.BadRequest when raw.Contains("code_expired")         => "Срок действия кода истёк. Запросите новый.",

            SupabaseErrorKind.BadRequest     => $"Сервер отклонил регистрацию: {raw}",
            _                                => $"Ошибка сервера: {sx.Message}",
        };
    }

