    private static string MapPwResetError(SupabaseException sx)
    {
        var body = sx.Message ?? string.Empty;
        if (sx.Kind == SupabaseErrorKind.BadRequest)
        {

            if (body.Contains("email_not_found",       StringComparison.Ordinal)) return "Аккаунт с таким email не найден.";
            if (body.Contains("email_required",        StringComparison.Ordinal)) return "Введите email.";
            if (body.Contains("code_not_found",        StringComparison.Ordinal)) return "Код не найден. Запросите новое письмо.";
            if (body.Contains("code_used",             StringComparison.Ordinal)) return "Код уже использован. Запросите новый.";
            if (body.Contains("code_expired",          StringComparison.Ordinal)) return "Срок действия кода истёк. Запросите новый.";
            if (body.Contains("password_hash_invalid", StringComparison.Ordinal)) return "Пароль должен быть не короче 8 символов.";
            if (body.Contains("code_required",         StringComparison.Ordinal)) return "Код обязателен.";
            return $"Сервер отклонил запрос: {body}";
        }
        return sx.Kind switch
        {
            SupabaseErrorKind.Network        => "Сервер недоступен.",
            SupabaseErrorKind.NotProvisioned => "Миграция 0011_password_reset.sql не применена.",
            SupabaseErrorKind.Unauthorized   => "Сервер отклонил API-ключ.",
            _                                => $"Ошибка сервера: {sx.Message}",
        };
    }

