    public async Task<string> UploadAvatarAsync(string userId, string localPath)
    {
        if (string.IsNullOrWhiteSpace(userId))
            throw new InvalidOperationException(Loc.T("errors.avatar.sessionExpired"));
        if (string.IsNullOrWhiteSpace(localPath) || !File.Exists(localPath))
            throw new InvalidOperationException(Loc.T("errors.avatar.fileNotFound"));

        var info = new FileInfo(localPath);
        const long maxBytes = 5 * 1024 * 1024;
        if (info.Length > maxBytes)
            throw new InvalidOperationException(Loc.T("errors.avatar.tooLarge"));

        var ext = Path.GetExtension(localPath).TrimStart('.').ToLowerInvariant();
        if (ext is not ("png" or "jpg" or "jpeg" or "webp" or "gif"))
            throw new InvalidOperationException(Loc.T("errors.avatar.badFormat"));

        try
        {
            var url = await _supabase.UploadAvatarViaApiAsync(userId, localPath, ext, CancellationToken.None);
            Debug.WriteLine($"[avatar.upload] api ok user={userId} url={url}");
            return url;
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[avatar.upload] api FAIL: {ex.GetType().Name}: {ex.Message} - falling back");
        }

        var r2Key = $"avatars/{userId}/{DateTimeOffset.UtcNow.ToUnixTimeSeconds()}.{ext}";
        try
        {
            var url = await _remoteStorage.UploadAsync(localPath, r2Key, progress: null, ct: CancellationToken.None);
            Debug.WriteLine($"[avatar.upload] r2 ok user={userId} key={r2Key} url={url}");
            return url;
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[avatar.upload] r2 FAIL: {ex.GetType().Name}: {ex.Message}");
            if (IsMissingR2Credentials(ex))
            {
                var inlineUrl = await BuildAvatarDataUrlAsync(localPath, ext);
                Debug.WriteLine($"[avatar.upload] R2 credentials missing, using inline data URL ({info.Length} bytes)");
                return inlineUrl;
            }

            throw new InvalidOperationException(Loc.T("errors.avatar.uploadFailed", ("message", ex.Message)), ex);
        }
    }

    private static bool IsMissingR2Credentials(Exception ex)
    {
        for (var cur = ex; cur is not null; cur = cur.InnerException)
        {
            if (cur.Message.Contains("R2 credentials are not configured", StringComparison.OrdinalIgnoreCase))
                return true;
        }

        return false;
    }

    private static async Task<(string LocalPath, string Ext, bool IsTemp)> EnsureWebPAsync(string sourcePath)
    {
        var ext = Path.GetExtension(sourcePath).ToLowerInvariant();
        if (ext != ".png" && ext != ".jpg" && ext != ".jpeg")
            return (sourcePath, ext, false);

        var tmp = Path.Combine(Path.GetTempPath(), $"miami_webp_{Guid.NewGuid():N}.webp");
        try
        {
            await Task.Run(() =>
            {
                using var img = new MagickImage(sourcePath);
                img.Quality = 85;
                img.Format  = MagickFormat.WebP;

                img.Settings.SetDefine(MagickFormat.WebP, "method", "6");
                img.Write(tmp, MagickFormat.WebP);
            });
            Debug.WriteLine($"[webp] {Path.GetFileName(sourcePath)} {new FileInfo(sourcePath).Length}B -> {new FileInfo(tmp).Length}B");
            return (tmp, ".webp", true);
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[webp] convert FAIL for {sourcePath}: {ex.GetType().Name} {ex.Message} - falling back to original");
            if (File.Exists(tmp)) try { File.Delete(tmp); } catch { }
            return (sourcePath, ext, false);
        }
    }

    private static async Task<string> BuildAvatarDataUrlAsync(string localPath, string ext)
    {
        var mime = ext switch
        {
            "png"  => "image/png",
            "jpg"  => "image/jpeg",
            "jpeg" => "image/jpeg",
            "webp" => "image/webp",
            "gif"  => "image/gif",
            _      => "application/octet-stream",
        };

        var bytes = await File.ReadAllBytesAsync(localPath);
        return $"data:{mime};base64,{Convert.ToBase64String(bytes)}";
    }

