    private static string MapInstallError(SupabaseException sx) => sx.Kind switch
    {
        SupabaseErrorKind.Network        => "Сервер недоступен.",
        SupabaseErrorKind.NotProvisioned => "Миграция 0009_install_history.sql не применена.",
        SupabaseErrorKind.Unauthorized   => "Сервер отклонил API-ключ.",
        SupabaseErrorKind.BadRequest     => $"Некорректные данные: {sx.Message}",
        _                                => $"Ошибка сервера: {sx.Message}",
    };

    private static string MapProfileError(SupabaseException sx)
    {
        var body = sx.Message ?? string.Empty;
        if (sx.Kind == SupabaseErrorKind.BadRequest)
        {
            if (body.Contains("username_length_invalid", StringComparison.Ordinal))
                return "Имя пользователя должно быть 3–32 символа.";
            if (body.Contains("username_charset_invalid", StringComparison.Ordinal))
                return "Имя пользователя - только латиница, цифры и `_`.";
            if (body.Contains("user_id_required", StringComparison.Ordinal))
                return "Сессия истекла - войдите заново.";
            return $"Сервер отклонил запрос: {body}";
        }
        if (sx.Kind == SupabaseErrorKind.Conflict || body.Contains("username_taken", StringComparison.Ordinal))
            return "Это имя пользователя уже занято.";
        return sx.Kind switch
        {
            SupabaseErrorKind.Network        => "Сервер недоступен. Проверьте интернет-соединение.",
            SupabaseErrorKind.NotProvisioned => "Миграция 0008_user_profile.sql не применена.",
            SupabaseErrorKind.Unauthorized   => "Сервер отклонил API-ключ.",
            _                                => $"Ошибка сервера: {sx.Message}",
        };
    }

    public async Task<ServerStatusDto> GetServerStatusAsync()
    {

        using var pingCts = new CancellationTokenSource(TimeSpan.FromSeconds(9));
        var reachable = await _supabase.PingAsync(pingCts.Token);
        if (!reachable)
            return new ServerStatusDto(false, false,
                "Не отвечает ни основной, ни запасной наш сервер. Обычно так выглядит " +
                "заблокированный или порезанный путь до нашего домена (провайдер, DPI, VPN), " +
                "реже - обрыв интернета. Проверь связь, а если ты в России - открой " +
                "Настройки → Серверы и сеть и выбери регион RU.");

        try
        {

            await _userRepo.AuthenticateAsync("__healthcheck__", Guid.NewGuid().ToString("N"));
            return new ServerStatusDto(true, true, "Подключено к Supabase.");
        }
        catch (SupabaseException sx) when (sx.Kind == SupabaseErrorKind.NotProvisioned)
        {
            return new ServerStatusDto(true, false, "Сервер доступен, но миграция не применена.");
        }
        catch (SupabaseException sx)
        {
            return new ServerStatusDto(true, false, $"Сервер ответил: {sx.Message}");
        }
        catch (Exception ex)
        {
            return new ServerStatusDto(true, false, $"Неожиданная ошибка: {ex.Message}");
        }
    }

    public async Task<AppUpdateInfoDto> AppUpdateCheckAsync()
    {
        var current = GetCurrentAppVersion();

        try
        {
            var rows = await _supabase.SelectAsync<AppVersionRow>(
                "app_versions",
                "select=version,installer_url,sha256,size_bytes,release_notes,is_required,published_at,installer_url_admin,sha256_admin,size_bytes_admin&is_active=eq.true&order=published_at.desc&limit=25");
            var latest = rows
                .Where(r => !string.IsNullOrWhiteSpace(r.Version) && !string.IsNullOrWhiteSpace(r.InstallerUrl))
                .OrderByDescending(r => NormalizeVersion(r.Version))
                .FirstOrDefault();
            if (latest is null)
            {
                return new AppUpdateInfoDto(false, false, current, null, null, null, null, null, null);
            }

            var hasUpdate = CompareVersions(latest.Version, current) > 0;
#if ADMIN
            if (string.IsNullOrWhiteSpace(latest.InstallerUrlAdmin))
                return new AppUpdateInfoDto(false, false, current, null, null, null, null, null, null);
            return new AppUpdateInfoDto(
                hasUpdate,
                latest.IsRequired,
                current,
                latest.Version,
                latest.InstallerUrlAdmin,
                latest.ReleaseNotes,
                latest.SizeBytesAdmin,
                latest.Sha256Admin,
                latest.PublishedAt);
#else
            return new AppUpdateInfoDto(
                hasUpdate,
                latest.IsRequired,
                current,
                latest.Version,
                latest.InstallerUrl,
                latest.ReleaseNotes,
                latest.SizeBytes,
                latest.Sha256,
                latest.PublishedAt);
#endif
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[app.update] check failed: {ex.Message}");
            return new AppUpdateInfoDto(false, false, current, null, null, null, null, null, null, ex.Message);
        }
    }

    public async Task<AppUpdateInstallResultDto> AppUpdateInstallAsync(string version)
    {
        if (string.IsNullOrWhiteSpace(version))
            return new AppUpdateInstallResultDto(false, "Version is required.", null);

        Services.SessionLog.Info("app-update", $"launcher self-update requested -> {version}");

        try
        {
            var rows = await _supabase.SelectAsync<AppVersionRow>(
                "app_versions",
                $"select=version,installer_url,sha256,size_bytes,release_notes,is_required,published_at,installer_url_admin,sha256_admin,size_bytes_admin,manifest_url,manifest_sha256&is_active=eq.true&version=eq.{Uri.EscapeDataString(version)}&limit=1");
            var row = rows.FirstOrDefault();
            if (row is null)
                return new AppUpdateInstallResultDto(false, "Update version was not found in app_versions.", null);

#if ADMIN
            if (string.IsNullOrWhiteSpace(row.InstallerUrlAdmin))
                return new AppUpdateInstallResultDto(false, "Для этой версии не опубликован админ-инсталлятор (installer_url_admin).", null);
            row = row with { InstallerUrl = row.InstallerUrlAdmin, Sha256 = row.Sha256Admin, SizeBytes = row.SizeBytesAdmin };
#endif

#if !ADMIN
            if (!string.IsNullOrWhiteSpace(row.ManifestUrl))
            {
                try
                {
                    var delta = await new Services.DeltaUpdater().TryUpdateAsync(
                        row.Version, row.ManifestUrl!, row.ManifestSha256,
                        (pct, detail) => _emitEvent?.Invoke("app:updateProgress", new { active = true, percent = pct, detail }),
                        CancellationToken.None);

                    if (delta.NoOp)
                    {
                        WriteInstalledVersionMarker(row.Version);
                        Services.SessionLog.Info("app-update", $"delta: already up to date ({version})");
                        return new AppUpdateInstallResultDto(true, null, null);
                    }
                    if (delta.Applying)
                    {
                        WriteInstalledVersionMarker(row.Version);
                        Services.SessionLog.Info("app-update",
                            $"delta applied ({version}): {delta.FilesChanged} files, {delta.DownloadedBytes / 1024} KB - restarting to swap");
                        _ = Task.Run(async () =>
                        {
                            await Task.Delay(700);
                            Application.Current?.Dispatcher.Invoke(() => Application.Current.Shutdown());
                        });
                        return new AppUpdateInstallResultDto(true, null, null);
                    }
                    Services.SessionLog.Info("app-update", $"delta unavailable ({delta.Error}) - full-installer fallback");
                }
                catch (Exception ex)
                {
                    Services.SessionLog.Error("app-update", "delta attempt threw - full-installer fallback", ex);
                }
            }
#endif

            var updateDir = Path.Combine(
                Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
                "MiamiGraphics",
                "updates");
            Directory.CreateDirectory(updateDir);

            var safeVersion = string.Concat(row.Version.Select(ch => char.IsLetterOrDigit(ch) || ch is '.' or '-' or '_' ? ch : '_'));
            var installerPath = Path.Combine(updateDir, $"Miami Installer_{safeVersion}.exe");

            var lastPct = -1;
            var usedInstallerUrl = await DownloadUpdateInstallerAsync(
                row.InstallerUrl, installerPath,
                (received, total) =>
                {
                    var pct = total > 0 ? (int)(received * 100 / total) : 0;
                    if (pct == lastPct) return;
                    lastPct = pct;
                    var mb = 1024.0 * 1024.0;
                    var detail = total > 0
                        ? $"Скачиваю установщик - {received / mb:F0} из {total / mb:F0} МБ"
                        : $"Скачиваю установщик - {received / mb:F0} МБ";
                    _emitEvent?.Invoke("app:updateProgress", new { active = true, percent = pct, detail });
                });
            Debug.WriteLine($"[app.update] downloaded installer from {usedInstallerUrl}");

            if (string.IsNullOrWhiteSpace(row.Sha256))
            {
                File.Delete(installerPath);
                return new AppUpdateInstallResultDto(false, "Update rejected: app_versions row has no sha256 (refusing to run an unverified installer).", null);
            }
            {
                _emitEvent?.Invoke("app:updateProgress",
                    new { active = true, percent = 100, detail = "Проверяю установщик…" });
                var actual = await Sha256FileAsync(installerPath);
                if (!actual.Equals(row.Sha256.Trim(), StringComparison.OrdinalIgnoreCase))
                {
                    File.Delete(installerPath);
                    return new AppUpdateInstallResultDto(false, "Installer SHA-256 does not match app_versions.", null);
                }
            }

            WriteInstalledVersionMarker(row.Version);

            var helperPath = await WriteUpdateHelperAsync(updateDir, installerPath, safeVersion);
            var psi = new ProcessStartInfo
            {
                FileName = "powershell.exe",
                Arguments = $"-NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File \"{helperPath}\"",
                UseShellExecute = false,
                CreateNoWindow = true,
                WorkingDirectory = updateDir,
            };
            Process.Start(psi);
            Services.SessionLog.Info("app-update", $"installer verified & launched ({version}) - shutting down to apply");

            _ = Task.Run(async () =>
            {
                await Task.Delay(700);
                Application.Current?.Dispatcher.Invoke(() => Application.Current.Shutdown());
            });

            return new AppUpdateInstallResultDto(true, null, installerPath);
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[app.update] install failed: {ex}");
            Services.SessionLog.Error("app-update", $"launcher self-update to {version} failed", ex);
            return new AppUpdateInstallResultDto(false, ex.Message, null);
        }
    }

    private static async Task<string> WriteUpdateHelperAsync(string updateDir, string installerPath, string safeVersion)
    {
        var helperPath = Path.Combine(updateDir, $"install_update_{safeVersion}.ps1");
        var logPath = Path.Combine(updateDir, $"install_update_{safeVersion}.log");
        var exePath = Process.GetCurrentProcess().MainModule?.FileName ?? string.Empty;
        var processId = Environment.ProcessId;

        var script = $$"""
$ErrorActionPreference = 'Stop'
$installer = {{ToPowerShellString(installerPath)}}
$log = {{ToPowerShellString(logPath)}}
$appExe = {{ToPowerShellString(exePath)}}
$pidToWait = {{processId}}

function Write-UpdateLog([string] $message) {
  try {
    $stamp = Get-Date -Format 'yyyy-MM-dd HH:mm:ss'
    Add-Content -LiteralPath $log -Value "$stamp $message"
  } catch { }
}

Write-UpdateLog "helper started"
try {
  $process = Get-Process -Id $pidToWait -ErrorAction SilentlyContinue
  if ($process) {
    Write-UpdateLog "waiting for Miami Graphics pid=$pidToWait"
    Wait-Process -Id $pidToWait -Timeout 20 -ErrorAction SilentlyContinue
  }
} catch {
  Write-UpdateLog "wait skipped: $($_.Exception.Message)"
}

Start-Sleep -Milliseconds 700

if (-not (Test-Path -LiteralPath $installer)) {
  Write-UpdateLog "installer missing: $installer"
  exit 2
}

Write-UpdateLog "starting installer"
# --silent: канонический флаг нашего WPF-инсталлера (он же принимает Inno-стиль
# /SILENT для хелперов, сгенерированных старыми лаунчерами).
$arguments = '--silent'
$started = Start-Process -FilePath $installer -ArgumentList $arguments -Verb RunAs -Wait -PassThru
Write-UpdateLog "installer exited: $($started.ExitCode)"

if ($started.ExitCode -eq 0 -and $appExe -and (Test-Path -LiteralPath $appExe)) {
  Write-UpdateLog "restarting app"
  Start-Process -FilePath $appExe | Out-Null
}
""";

        Directory.CreateDirectory(updateDir);
        await File.WriteAllTextAsync(helperPath, script);
        return helperPath;
    }

    private static string ToPowerShellString(string value)
        => "'" + (value ?? string.Empty).Replace("'", "''") + "'";

    private static async Task<string> DownloadUpdateInstallerAsync(
        string originalUrl, string installerPath, Action<long, long>? onBytes = null)
    {
        var selectedUrl = await MirrorSelector.RewriteUrlAsync(originalUrl);
        var candidates = BuildUpdateInstallerUrlCandidates(originalUrl, selectedUrl).ToArray();
        Exception? lastError = null;

        foreach (var url in candidates)
        {
            try
            {
                Debug.WriteLine($"[app.update] trying installer url {url}");
                if (File.Exists(installerPath))
                    File.Delete(installerPath);

                await ParallelDownloader.DownloadAsync(url, installerPath, onBytes, resumable: false);
                return url;
            }
            catch (Exception ex) when (ex is HttpRequestException or IOException or TaskCanceledException or InvalidOperationException)
            {
                lastError = ex;
                Debug.WriteLine($"[app.update] installer url failed {url}: {ex.Message}");
                try
                {
                    if (File.Exists(installerPath))
                        File.Delete(installerPath);
                }
                catch
                {

                }
            }
        }

        throw new HttpRequestException($"Could not download installer from any mirror. Last error: {lastError?.Message}");
    }

    private static IEnumerable<string> BuildUpdateInstallerUrlCandidates(string originalUrl, string selectedUrl)
    {
        var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

        foreach (var url in new[]
        {
            selectedUrl,
            originalUrl,
            MirrorSelector.RewriteUrl(originalUrl, new Uri("http://ru.miamigraphicsstorage.uk")),
            MirrorSelector.RewriteUrl(originalUrl, new Uri("https://cdn.miamigraphicsstorage.uk")),
            MirrorSelector.RewriteUrl(originalUrl, new Uri("https://miamigraphicsstorage.uk")),
        })
        {
            if (!string.IsNullOrWhiteSpace(url) && seen.Add(url))
                yield return url;
        }
    }

    private static string InstalledVersionMarkerPath
    {
        get
        {
            var localAppData = Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData);
            return Path.Combine(localAppData, "MiamiGraphics", "config", "installed_version.txt");
        }
    }

    private static string GetCurrentAppVersion()
    {
        var asm = Assembly.GetExecutingAssembly();
        var info = asm.GetCustomAttribute<AssemblyInformationalVersionAttribute>()?.InformationalVersion;
        var asmVersion = !string.IsNullOrWhiteSpace(info)
            ? info.Split('+')[0]
            : (asm.GetName().Version?.ToString(3) ?? "0.0.0");

        try
        {
            var path = InstalledVersionMarkerPath;
            if (File.Exists(path))
            {
                var stored = File.ReadAllText(path).Trim().Split('+')[0];
                if (!string.IsNullOrWhiteSpace(stored) && CompareVersions(stored, asmVersion) > 0)
                {
                    try { File.Delete(path); } catch { }
                }
            }
        }
        catch { }

        return asmVersion;
    }

    private static void WriteInstalledVersionMarker(string version)
    {
        try
        {
            var path = InstalledVersionMarkerPath;
            Directory.CreateDirectory(Path.GetDirectoryName(path)!);
            var tmp = path + ".tmp";
            File.WriteAllText(tmp, version);
            File.Move(tmp, path, overwrite: true);
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[app.update] WriteInstalledVersionMarker failed: {ex.Message}");
        }
    }

    private static int CompareVersions(string left, string right)
    {
        return NormalizeVersion(left).CompareTo(NormalizeVersion(right));
    }

    private static Version NormalizeVersion(string value)
    {
        var clean = (value ?? string.Empty).Split('+')[0].Split('-')[0].Trim();
        return Version.TryParse(clean, out var parsed) ? parsed : new Version(0, 0, 0);
    }

    private static async Task<string> Sha256FileAsync(string path)
    {
        await using var stream = File.OpenRead(path);
        var hash = await SHA256.HashDataAsync(stream);
        return Convert.ToHexString(hash).ToLowerInvariant();
    }

    public async Task<BackupStatusDto> BackupGetStatusAsync()
    {
