    public async Task<BackupResultDto> BackupRunFullAsync()
    {
        using var critical = Services.CriticalOperationGuard.Enter();
        using var runCts = new CancellationTokenSource();
        lock (_backupCtsLock)
        {
            if (_backupCts is not null)
                return new BackupResultDto(false, false, false, "ALREADY_RUNNING", "Backup is already running.", null);
            _backupCts = runCts;
        }

        var sw = Stopwatch.StartNew();
        long lastEmitMs = -1;
        string? lastPhase = null;

        IProgress<Core.System.BackupProgress> progress = new Progress<Core.System.BackupProgress>(p =>
        {

            var nowMs = sw.ElapsedMilliseconds;
            var phaseChanged = p.Phase != lastPhase;
            var terminal = p.Phase is "done" or "error";
            if (!phaseChanged && !terminal && nowMs - lastEmitMs < 250) return;
            lastEmitMs = nowMs;
            lastPhase = p.Phase;
            _emitEvent?.Invoke("backup:progress", new BackupProgressDto(
                p.Phase, p.Percent, p.FileName, p.BytesProcessed, p.BytesTotal, p.ErrorCode, p.ErrorMessage));
        });

        try
        {
            progress.Report(new Core.System.BackupProgress(
                "detecting", 0, null, null, null, null, null));

            var gtaPathTask = GetGtaPathAsync();
            var completed = await Task.WhenAny(gtaPathTask, Task.Delay(TimeSpan.FromSeconds(15), runCts.Token));
            if (runCts.IsCancellationRequested)
                throw new OperationCanceledException(runCts.Token);
            if (completed != gtaPathTask)
            {
                const string message = "Не удалось быстро найти папку GTA. Укажите путь к GTA вручную в настройках.";
                progress.Report(new Core.System.BackupProgress(
                    "error", 0, null, null, null, "GTA_PATH_TIMEOUT", message));
                return new BackupResultDto(false, false, false, "GTA_PATH_TIMEOUT", message, null);
            }

            string gtaPath;
            try
            {
                gtaPath = await gtaPathTask;
            }
            catch (Exception ex)
            {
                var message = $"Не удалось найти папку GTA: {ex.Message}";
                progress.Report(new Core.System.BackupProgress(
                    "error", 0, null, null, null, "GTA_PATH_INVALID", message));
                return new BackupResultDto(false, false, false, "GTA_PATH_INVALID", message, null);
            }

            var result = await _backupService.RunFullBackupAsync(gtaPath, progress, runCts.Token);
            var lockers = result.Lockers is { Count: > 0 }
                ? result.Lockers.Select(l => new LockerProcessDto(l.Pid, l.ProcessName, l.FriendlyName)).ToList()
                : null;
            return new BackupResultDto(result.Success, result.HadDirtyUpdate, result.VersionUnsupported, result.ErrorCode, result.ErrorMessage, lockers);
        }
        catch (OperationCanceledException)
        {
            progress.Report(new Core.System.BackupProgress(
                "error", 0, null, null, null, "CANCELLED", "Операция остановлена. Недокачанные временные файлы удалены."));
            return new BackupResultDto(false, false, false, "CANCELLED", "Операция остановлена. Недокачанные временные файлы удалены.", null);
        }
        finally
        {
            lock (_backupCtsLock)
            {
                if (ReferenceEquals(_backupCts, runCts))
                    _backupCts = null;
            }
        }
    }

    public Task<bool> BackupCancelAsync()
    {
        lock (_backupCtsLock)
        {
            if (_backupCts is null) return Task.FromResult(false);
            try { _backupCts.Cancel(); } catch {  }
            return Task.FromResult(true);
        }
    }

    public Task<bool> BackupRestoreCleanAsync()
        => Task.Run(async () =>
        {
            const string opId   = "rollback:all";
            const string opName = "Откат всех модов";
            try
            {
                var gtaRoot = await GetGtaPathAsync();

                try
                {
                    var st = ReadInstallState();
                    if (st?.CurrentSoundPackFiles is { Count: > 0 } && !string.IsNullOrWhiteSpace(gtaRoot))
                    {
                        EmitInstallProgress(opId, opName, "starting", 2, null,
                            detailMessage: Loc.T("progress.gunpack.restoringStockSound"));
                        await AwcSoundUninstallAsync(st, gtaRoot);
                    }
                }
                catch (Exception ex) { Debug.WriteLine($"[rollback:all] sound restore FAILED (non-fatal): {ex.Message}"); }

                var ok = await RestoreCleanWithLockRetryAsync(gtaRoot, CancellationToken.None,
                    pct => EmitInstallProgress(opId, opName, "starting", pct, null,
                        detailMessage: Loc.T("progress.common.restoringCleanRpf")));
                if (ok)
                {
                    try { await _backupService.RestoreCleanDlcAsync(gtaRoot, CancellationToken.None); }
                    catch (Exception ex) { Debug.WriteLine($"[rollback:all] patchday18ng restore FAILED (non-fatal): {ex.Message}"); }

                    try
                    {
                        EmitInstallProgress(opId, opName, "starting", 96, null,
                            detailMessage: Loc.T("progress.common.restoringCleanRpf"));
                        MiamiGraphics.Core.Services.ImprovementManagerService.WipeAllLocal(
                            gtaRoot, s => Debug.WriteLine(s));
                    }
                    catch (Exception ex) { Debug.WriteLine($"[rollback:all] improvements wipe FAILED (non-fatal): {ex.Message}"); }

                    TryWipeInstallJournals();
                    EmitInstallProgress(opId, opName, "done", 100, null,
                        detailMessage: Loc.T("progress.common.gtaRestoredClean"));
                }
                return ok;
            }
            catch (Exception ex)
            {
                var friendly = IsTransientFileLock(ex)
                    ? "Не удалось откатить: update.rpf занят другим процессом." + DescribeUpdateRpfLockState()
                    : ex.Message;
                EmitInstallProgress(opId, opName, "error", 0, friendly);
                throw new InvalidOperationException(friendly, ex);
            }
        });

    private static void TryWipeInstallJournals()
    {
        var localAppData = Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData);
        var paths = new[]
        {
            Path.Combine(localAppData, "MiamiGraphics", "install_state.json"),
            Path.Combine(localAppData, "MiamiGraphics", "admin", "installed_gunpack.json"),
            Path.Combine(localAppData, "MiamiGraphics", "admin", "selected_guns.json"),
            Path.Combine(localAppData, "MiamiGraphics", "config", "minimap_layout.json"),
        };
        foreach (var p in paths)
        {
            try
            {
                if (File.Exists(p))
                {
                    File.Delete(p);
                    Debug.WriteLine($"[backupRestoreClean] wiped journal: {p}");
                }
            }
            catch (Exception ex)
            {
                Debug.WriteLine($"[backupRestoreClean] wipe failed for {p}: {ex.Message}");
            }
        }
    }

    public Task<bool> BackupRestoreSnapshotAsync()
