    public Task FactoryResetAndRestartAsync()
    {

        var localAppData = Path.Combine(
            Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
            "MiamiGraphics");
        var tempDir = Path.Combine(Path.GetTempPath(), "MiamiGraphics");
        var exePath = Process.GetCurrentProcess().MainModule?.FileName
                      ?? throw new InvalidOperationException("Cannot determine current exe path.");
        var webView2Dir = Path.Combine(localAppData, "WebView2");
        var pid = Environment.ProcessId;

        byte[]? preservedAdminConfig = null;
        var adminConfigPath = Path.Combine(localAppData, "admin-config.bin");
        try
        {
            if (File.Exists(adminConfigPath))
                preservedAdminConfig = File.ReadAllBytes(adminConfigPath);
        }
        catch (Exception ex) { Debug.WriteLine($"[factory-reset] admin-config preserve read failed: {ex.Message}"); }

        var movedRoot = Core.System.AppDataRoot.Override;
        if (movedRoot is not null)
        {
            foreach (var sub in new[] { "cache", "backup" })
            {
                var dir = Path.Combine(movedRoot, sub);
                try { if (Directory.Exists(dir)) Directory.Delete(dir, recursive: true); }
                catch (Exception ex) { Debug.WriteLine($"[factory-reset] moved '{dir}' delete failed: {ex.Message}"); }
            }
        }

        try { if (Directory.Exists(localAppData)) Directory.Delete(localAppData, recursive: true); }
        catch (Exception ex) { Debug.WriteLine($"[factory-reset] LocalAppData delete failed: {ex.Message}"); }

        try { Core.System.AppDataRoot.Invalidate(); } catch { }

        if (preservedAdminConfig is not null)
        {
            try
            {
                Directory.CreateDirectory(localAppData);
                File.WriteAllBytes(adminConfigPath, preservedAdminConfig);
            }
            catch (Exception ex) { Debug.WriteLine($"[factory-reset] admin-config restore failed: {ex.Message}"); }
        }

        try { if (Directory.Exists(tempDir)) Directory.Delete(tempDir, recursive: true); }
        catch (Exception ex) { Debug.WriteLine($"[factory-reset] Temp delete failed: {ex.Message}"); }

        try
        {
            using var key = Microsoft.Win32.Registry.CurrentUser.OpenSubKey("Software", writable: true);

            key?.DeleteSubKeyTree("MiamiGraphics", throwOnMissingSubKey: false);
            key?.DeleteSubKeyTree("MiamiGraphics", throwOnMissingSubKey: false);
        }
        catch (Exception ex) { Debug.WriteLine($"[factory-reset] Registry delete failed: {ex.Message}"); }

        var script = $@"@echo off
setlocal
set ""PID={pid}""
set ""WV2={webView2Dir}""
set ""EXE={exePath}""
for /l %%i in (1,1,30) do (
    tasklist /fi ""PID eq %PID%"" 2>nul | find ""%PID%"" >nul
    if errorlevel 1 goto cleanup
    timeout /t 1 /nobreak >nul
)
:cleanup
rd /s /q ""%WV2%"" 2>nul
start """" ""%EXE%""
del ""%~f0"" 2>nul
";
        var helperPath = Path.Combine(Path.GetTempPath(), $"hg_factory_reset_{Guid.NewGuid():N}.bat");
        File.WriteAllText(helperPath, script);

        try
        {
            Process.Start(new ProcessStartInfo
            {
                FileName        = "cmd.exe",
                Arguments       = $"/c \"\"{helperPath}\"\"",
                UseShellExecute = false,
                CreateNoWindow  = true,
            });
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[factory-reset] helper launch failed: {ex.Message}");
        }

        var dispatcher = global::System.Windows.Application.Current?.Dispatcher;
        if (dispatcher is not null)
        {
            _ = dispatcher.BeginInvoke(new Action(() =>
            {
                global::System.Windows.Application.Current?.Shutdown();
            }), global::System.Windows.Threading.DispatcherPriority.Background);
        }
        return Task.CompletedTask;
    }

    private const string UninstallRegSubKey =
        @"Software\Microsoft\Windows\CurrentVersion\Uninstall\{B5C65F97-79B5-41F2-8F3C-9891146D0632}_is1";

    public Task LauncherUninstallAsync()
    {
        var uninstallString = TryGetUninstallString();

        if (string.IsNullOrWhiteSpace(uninstallString))
        {
            try
            {
                var exePath = Process.GetCurrentProcess().MainModule?.FileName;
                var appDir  = exePath is null ? null : Path.GetDirectoryName(exePath);
                var rootDir = appDir  is null ? null : Path.GetDirectoryName(appDir);
                if (rootDir is not null)
                {
                    var candidate = Path.Combine(rootDir, "unins000.exe");
                    if (File.Exists(candidate)) uninstallString = $"\"{candidate}\"";
                }
            }
            catch (Exception ex) { Debug.WriteLine($"[uninstall] fallback derive failed: {ex.Message}"); }
        }

        if (string.IsNullOrWhiteSpace(uninstallString))
            throw new InvalidOperationException(Loc.T("errors.launcher.uninstallerMissing"));

        var pid = Environment.ProcessId;

        var script = $@"@echo off
setlocal
set ""PID={pid}""
for /l %%i in (1,1,30) do (
    tasklist /fi ""PID eq %PID%"" 2>nul | find ""%PID%"" >nul
    if errorlevel 1 goto run
    timeout /t 1 /nobreak >nul
)
:run
start """" {uninstallString}
del ""%~f0"" 2>nul
";
        var helperPath = Path.Combine(Path.GetTempPath(), $"hg_uninstall_{Guid.NewGuid():N}.bat");
        File.WriteAllText(helperPath, script);

        try
        {
            Process.Start(new ProcessStartInfo
            {
                FileName        = "cmd.exe",
                Arguments       = $"/c \"\"{helperPath}\"\"",
                UseShellExecute = false,
                CreateNoWindow  = true,
            });
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[uninstall] helper launch failed: {ex.Message}");
            throw;
        }

        var dispatcher = global::System.Windows.Application.Current?.Dispatcher;
        if (dispatcher is not null)
        {
            _ = dispatcher.BeginInvoke(new Action(() =>
            {
                global::System.Windows.Application.Current?.Shutdown();
            }), global::System.Windows.Threading.DispatcherPriority.Background);
        }
        return Task.CompletedTask;
    }

    private static string? TryGetUninstallString()
    {
        var targets = new (Microsoft.Win32.RegistryHive Hive, Microsoft.Win32.RegistryView View)[]
        {
            (Microsoft.Win32.RegistryHive.LocalMachine, Microsoft.Win32.RegistryView.Registry64),
            (Microsoft.Win32.RegistryHive.LocalMachine, Microsoft.Win32.RegistryView.Registry32),
            (Microsoft.Win32.RegistryHive.CurrentUser,  Microsoft.Win32.RegistryView.Registry64),
            (Microsoft.Win32.RegistryHive.CurrentUser,  Microsoft.Win32.RegistryView.Registry32),
        };

        foreach (var (hive, view) in targets)
        {
            try
            {
                using var baseKey = Microsoft.Win32.RegistryKey.OpenBaseKey(hive, view);
                using var key     = baseKey.OpenSubKey(UninstallRegSubKey);
                if (key?.GetValue("UninstallString") is string val && !string.IsNullOrWhiteSpace(val))
                    return val;
            }
            catch (Exception ex) { Debug.WriteLine($"[uninstall] registry read failed ({hive}/{view}): {ex.Message}"); }
        }
        return null;
    }

    private async Task<string> GetGtaPathAsync()
    {
        var cfg = await _adminConfig.GetAsync();
        var path = !string.IsNullOrWhiteSpace(cfg.GtaPathOverride) && Directory.Exists(cfg.GtaPathOverride)
            ? cfg.GtaPathOverride
            : await Task.Run(() => _hardwareLocator.FindGtaPath() ?? string.Empty);
        if (!string.IsNullOrWhiteSpace(path)) _lastGtaRoot = path;
        if (!string.IsNullOrWhiteSpace(path)) LogGameStateSnapshotOnce(path);
        return path;
    }

    private static int _gameStateLogged;

    private static void LogGameStateSnapshotOnce(string gtaRoot)
    {
        if (Interlocked.Exchange(ref _gameStateLogged, 1) != 0) return;
        try { LogGameStateSnapshot(gtaRoot); }
        catch (Exception ex) { SessionLog.Warn("состояние", $"снимок не собрался: {ex.Message}"); }
    }

    private static void LogGameStateSnapshot(string gtaRoot)
    {
        SessionLog.Info("состояние", $"игра: {gtaRoot}");

        var updateRpf = Path.Combine(gtaRoot, "update", "update.rpf");
        var sizeNote = Core.Injector.UpdateRpfLimits.Describe(updateRpf);
        SessionLog.Info("состояние", sizeNote.Length > 0 ? sizeNote : "update.rpf: не найден");

        var st = ReadInstallState();
        if (st is null || string.IsNullOrWhiteSpace(st.ReduxId))
            SessionLog.Info("состояние", "сборка: не установлена (install_state.json пуст)");
        else
        {
            SessionLog.Info("состояние",
                $"сборка: {st.ReduxId} версия {st.VersionId?.ToString() ?? "-"} от {st.InstalledAt:yyyy-MM-dd HH:mm}");
            if (!string.IsNullOrWhiteSpace(st.CurrentArmorName))
                SessionLog.Info("состояние", $"броня: {st.CurrentArmorName} ({st.CurrentArmorKind ?? "?"})");
            if (!string.IsNullOrWhiteSpace(st.CurrentSoundPackName))
                SessionLog.Info("состояние", $"звуки: {st.CurrentSoundPackName} ({st.CurrentSoundPackKind ?? "sfx"})");
        }

        var improvements = Core.Services.ImprovementManagerService.ReadRegistrySnapshot().Items;
        SessionLog.Info("состояние", improvements.Count == 0
            ? "улучшения: нет"
            : $"улучшения ({improvements.Count}): " +
              string.Join(", ", improvements.Select(i => $"{i.Id}/{i.Name}")));

        try
        {
            var gunpackPath = Path.Combine(
                Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
                "MiamiGraphics", "admin", "installed_gunpack.json");
            if (File.Exists(gunpackPath))
            {
                using var doc = JsonDocument.Parse(File.ReadAllText(gunpackPath));
                var root = doc.RootElement;
                string name = root.TryGetProperty("activeGunpackName", out var n) ? n.ToString() : "";
                string id = root.TryGetProperty("activeGunpackId", out var i) ? i.ToString() : "";
                SessionLog.Info("состояние", string.IsNullOrWhiteSpace(name) && string.IsNullOrWhiteSpace(id)
                    ? "ганпак: нет"
                    : $"ганпак: {(string.IsNullOrWhiteSpace(name) ? "?" : name)} ({id})");
            }
        }
        catch (Exception ex) { SessionLog.Warn("состояние", $"ганпак не прочитан: {ex.Message}"); }
    }

    private static bool LooksLikeGtaFolder(string? path) =>
        !string.IsNullOrWhiteSpace(path) && Directory.Exists(path) && File.Exists(Path.Combine(path!, "GTA5.exe"));

    public async Task<GtaPathInfoDto> GetGtaPathInfoAsync()
    {
        var cfg = await _adminConfig.GetAsync();
        var auto = await Task.Run(() => _hardwareLocator.FindGtaPath() ?? string.Empty);
        var overridePath = string.IsNullOrWhiteSpace(cfg.GtaPathOverride) ? null : cfg.GtaPathOverride;
        var overrideActive = LooksLikeGtaFolder(overridePath);
        var resolved = overrideActive ? overridePath! : auto;
        return new GtaPathInfoDto(resolved, overridePath, auto, overrideActive, LooksLikeGtaFolder(resolved));
    }

    public async Task<bool> SetGtaPathOverrideAsync(string path)
    {
        if (!LooksLikeGtaFolder(path)) return false;
        var cfg = await _adminConfig.GetAsync();
        await _adminConfig.SaveAsync(cfg with { GtaPathOverride = path });
        return true;
    }

    public async Task<bool> ClearGtaPathOverrideAsync()
    {
        var cfg = await _adminConfig.GetAsync();
        await _adminConfig.SaveAsync(cfg with { GtaPathOverride = null });
        return true;
    }

#if ADMIN
    public async Task<AdminWebAuthResultDto> AdminWebAuthenticateAsync()
    {
        var sessionToken = Services.SupabaseClient.UserSessionToken;
        if (string.IsNullOrWhiteSpace(sessionToken))
            return new AdminWebAuthResultDto(false, null, "Сначала войдите в аккаунт в лаунчере.");

        var apiBase = Services.SupabaseClient.Url.TrimEnd('/');
        using var http = new System.Net.Http.HttpClient { Timeout = TimeSpan.FromSeconds(20) };

        string linkToken;
        string? loginUrl;
        string? nick = null;
        try
        {
            var body = new System.Net.Http.StringContent(
                System.Text.Json.JsonSerializer.Serialize(new { sessionToken }),
                System.Text.Encoding.UTF8, "application/json");
            using var resp = await http.PostAsync($"{apiBase}/api/admin/link/start", body);
            var text = await resp.Content.ReadAsStringAsync();
            if (!resp.IsSuccessStatusCode)
                return new AdminWebAuthResultDto(false, null,
                    resp.StatusCode == System.Net.HttpStatusCode.Forbidden
                        ? "Аккаунт не имеет уровня Admin L2."
                        : "Не удалось начать вход в админ-панель.");
            using var doc = System.Text.Json.JsonDocument.Parse(text);
            linkToken = doc.RootElement.GetProperty("token").GetString() ?? string.Empty;
            loginUrl = doc.RootElement.TryGetProperty("loginUrl", out var lu)
                       && lu.ValueKind == System.Text.Json.JsonValueKind.String ? lu.GetString() : null;
        }
        catch (Exception ex)
        {
            return new AdminWebAuthResultDto(false, null, $"Сеть недоступна: {ex.Message}");
        }
        if (string.IsNullOrEmpty(linkToken))
            return new AdminWebAuthResultDto(false, null, "Сервер вернул пустой токен входа.");

        var openUrl = !string.IsNullOrEmpty(loginUrl)
            ? loginUrl!
            : $"{apiBase}/admin/login?token={Uri.EscapeDataString(linkToken)}";
        try { Process.Start(new ProcessStartInfo { FileName = openUrl, UseShellExecute = true }); }
        catch (Exception ex) { Debug.WriteLine($"[admin-auth] open browser failed: {ex.Message}"); }

        var deadline = DateTime.UtcNow.AddMinutes(5);
        var verified = false;
        while (DateTime.UtcNow < deadline)
        {
            await Task.Delay(2500);
            try
            {
                using var st = await http.GetAsync(
                    $"{apiBase}/api/admin/link/status?token={Uri.EscapeDataString(linkToken)}");
                if (!st.IsSuccessStatusCode) continue;
                using var sdoc = System.Text.Json.JsonDocument.Parse(await st.Content.ReadAsStringAsync());
                var status = sdoc.RootElement.TryGetProperty("status", out var se)
                             ? se.GetString() : null;
                if (sdoc.RootElement.TryGetProperty("nick", out var ne)
                    && ne.ValueKind == System.Text.Json.JsonValueKind.String)
                    nick = ne.GetString();
                if (status == "verified" || status == "consumed") { verified = true; break; }
                if (status == "expired" || status == "unknown")
                    return new AdminWebAuthResultDto(false, nick, "Срок действия входа истёк. Попробуйте снова.");
            }
            catch {}
        }
        if (!verified)
            return new AdminWebAuthResultDto(false, nick, "Время ожидания истекло. Вход не подтверждён.");

        return new AdminWebAuthResultDto(true, nick, null);
    }
#endif

