    private static bool IsRpfSharingViolation(IOException ex)
    {
        const int ERROR_SHARING_VIOLATION = 0x20;
        const int ERROR_LOCK_VIOLATION    = 0x21;
        var hr = ex.HResult & 0xFFFF;
        return hr == ERROR_SHARING_VIOLATION || hr == ERROR_LOCK_VIOLATION;
    }

#if ADMIN
    public Task<ReduxAnalysisDto> AdminReduxAnalyzeAsync(string sourcePath)
    {
        return Task.Run(async () =>
        {

            var (moddedRpfPath, resolveErr) = ResolveUpdateRpfPath(sourcePath);
            if (moddedRpfPath is null)
                throw new InvalidOperationException(resolveErr ?? "update.rpf not found in the supplied path");

            var config = await _adminConfig.GetAsync();
            var cleanRpfPath = config.CleanUpdateRpfPath;
            if (!File.Exists(cleanRpfPath))
                throw new InvalidOperationException(
                    $"Clean update.rpf not found: {cleanRpfPath}. " +
                    "Set the path in Admin → Settings → Paths → Clean update.rpf.");

            var reduxName = $"analysis_{Guid.NewGuid().ToString("N")[..8]}";

            var pipeline = new Core.Parser.ReduxParserPipeline();
            string? workDir = null;
            for (int attempt = 0; attempt < 2; attempt++)
            {
                try
                {
                    workDir = pipeline.ParseRedux(cleanRpfPath, moddedRpfPath, reduxName);
                    break;
                }
                catch (IOException ioe) when (IsRpfSharingViolation(ioe))
                {
                    if (attempt == 0)
                    {
                        Debug.WriteLine($"[admin.analyze] share-violation on first attempt ({ioe.Message}) - retrying after 800 ms");
                        await Task.Delay(800);
                        continue;
                    }

                    string lockedPath = ioe.Message.Contains(moddedRpfPath, StringComparison.OrdinalIgnoreCase)
                        ? moddedRpfPath
                        : (ioe.Message.Contains(cleanRpfPath, StringComparison.OrdinalIgnoreCase)
                            ? cleanRpfPath
                            : moddedRpfPath);
                    var lockers = Core.System.FileLockDetector.WhoIsLocking(lockedPath);
                    var who = lockers.Count == 0
                        ? "OpenIV / антивирус / другая копия лаунчера"
                        : string.Join(", ", lockers.Select(l => l.ProcessName));
                    throw new InvalidOperationException(
                        $"Не удалось открыть {Path.GetFileName(lockedPath)} - файл держит: {who}. " +
                        "Закрой эти программы и запусти анализ заново.");
                }
            }

            if (workDir is null)
                throw new InvalidOperationException("Анализ редукса не отработал.");

            var componentMapJson = await File.ReadAllTextAsync(Path.Combine(workDir, "component_map.json"));
            var componentMap = JsonSerializer.Deserialize<Core.Parser.ResolvedComponentMap>(componentMapJson, ReduxJson)
                ?? throw new InvalidOperationException("Failed to parse component_map.json");

            var manifestJson = await File.ReadAllTextAsync(Path.Combine(workDir, "manifest.json"));
            var manifest = JsonSerializer.Deserialize<Core.Parser.DiffManifest>(manifestJson, ReduxJson)
                ?? throw new InvalidOperationException("Failed to parse manifest.json");

            var targetVersion = DetectGtaVersionFromExe() ?? "1.0.3788.0";

            var componentDtos = componentMap.Components.ToDictionary(
                kv => kv.Key,
                kv => new ComponentInfoDto(
                    IsFound: kv.Value.IsFound,
                    SourceRpf: kv.Value.SourceRpf ?? string.Empty,
                    InternalPaths: kv.Value.InternalPaths?.ToArray() ?? Array.Empty<string>(),
                    Flags: kv.Value.Flags?.ToArray() ?? Array.Empty<string>()));

            var sourceSha = await Task.Run(() => ComputeFileSha256(moddedRpfPath));

            return new ReduxAnalysisDto(
                ResolvedUpdateRpfPath: moddedRpfPath,
                SizeBytes: manifest.TotalPatchSize,
                TargetGtaVersion: targetVersion,
                Components: componentDtos,
                TempWorkDir: workDir,
                SourceSha256: sourceSha);
        });
    }
#endif

    private static (string? Path, string? Error) ResolveUpdateRpfPath(string sourcePath)
    {
        if (string.IsNullOrWhiteSpace(sourcePath))
            return (null, "Путь не указан.");

        var p = sourcePath.Trim().Trim('"');
        Debug.WriteLine($"[admin.inject.resolve] input='{sourcePath}' normalized='{p}'");

        if (File.Exists(p))
        {
            if (p.EndsWith(".rpf", StringComparison.OrdinalIgnoreCase))
            {
                Debug.WriteLine($"[admin.inject.resolve] → direct .rpf");
                return (p, null);
            }
            if (p.EndsWith(".zip", StringComparison.OrdinalIgnoreCase) ||
                p.EndsWith(".rar", StringComparison.OrdinalIgnoreCase) ||
                p.EndsWith(".7z",  StringComparison.OrdinalIgnoreCase))
            {
                return (null,
                    $"Архивы (.zip/.rar/.7z) пока не поддерживаются. " +
                    $"Распакуй вручную и укажи update.rpf или папку с ним: {p}");
            }
            return (null, $"Файл должен быть .rpf, у тебя: {Path.GetExtension(p)}. {p}");
        }

        if (Directory.Exists(p))
        {
            var match = Directory.EnumerateFiles(p, "update.rpf", SearchOption.AllDirectories).FirstOrDefault();
            if (match is not null)
            {
                Debug.WriteLine($"[admin.inject.resolve] → folder match='{match}'");
                return (match, null);
            }
            return (null, $"В папке нет update.rpf (рекурсивный поиск): {p}");
        }

        return (null, $"Путь не существует на диске: {p}");
    }

    private string? DetectGtaVersionFromExe()
    {
        try
        {
            var gtaPath = _hardwareLocator.FindGtaPath();
            if (string.IsNullOrWhiteSpace(gtaPath)) return null;
            var exePath = Path.Combine(gtaPath, "GTA5.exe");
            if (!File.Exists(exePath)) return null;
            return FileVersionInfo.GetVersionInfo(exePath).FileVersion;
        }
        catch { return null; }
    }

