    public async Task AdminCatalogDeleteAsync(string id)
    {
        Debug.WriteLine($"[admin.catalog.delete] id='{id}'");
        var item = await _catalog.GetByIdAsync(id);
        if (item is null)
        {
            Debug.WriteLine("[admin.catalog.delete] item not found in catalog - nothing to do");
