        var baseKey = $"redux/{id}/";
        try
        {
            var deleted = await _remoteStorage.DeletePrefixAsync(baseKey, CancellationToken.None);
            Debug.WriteLine($"[admin.catalog.delete] r2 sweep removed {deleted} object(s)");
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[admin.catalog.delete] R2 cleanup FAILED: {ex.Message}");
            throw new InvalidOperationException(
                $"Не удалось удалить файлы редукса '{id}' с R2: {ex.Message}. " +
                $"Запись в каталоге сохранена, попробуй ещё раз.", ex);
        }

        var cfg = await _adminConfig.GetAsync();
        var serviceKey = cfg.SupabaseServiceKey;
        var hasServiceKey = !string.IsNullOrWhiteSpace(serviceKey);
        if (!hasServiceKey)
        {
            throw new InvalidOperationException(
                "Не задан Supabase Service Role Key в Admin → Настройки. " +
                "Без него DELETE не проходит RLS-политику (anon-ключ не может удалять). " +
                "Скопируй service_role-ключ из Supabase Studio → Settings → API → service_role key " +
                "и вставь в поле «Supabase Service Role Key».");
        }

        var escId = Uri.EscapeDataString(id);
        var childTables = new (string Table, string Filter)[]
        {
            ("redux_versions",  $"redux_id=eq.{escId}"),
            ("redux_reviews",   $"redux_id=eq.{escId}"),
            ("redux_installs",  $"redux_id=eq.{escId}"),
            ("featured_picks",  $"redux_id=eq.{escId}"),
        };
        foreach (var (table, filter) in childTables)
        {
            try
            {
                var n = await _supabase.DeleteWithServiceRoleAsync(table, filter, serviceKey);
                Debug.WriteLine($"[admin.catalog.delete] cascade ok: {table}?{filter} - {n} rows");
            }
            catch (Exception ex)
            {
                Debug.WriteLine($"[admin.catalog.delete] cascade WARN on {table}: {ex.Message} (continuing)");
            }
        }

        var parentDeleted = await _supabase.DeleteWithServiceRoleAsync(
            "redux_items", $"id=eq.{escId}", serviceKey);
        Debug.WriteLine($"[admin.catalog.delete] redux_items deleted: {parentDeleted} row(s)");

        try
        {
            var stillThere = await _catalog.GetByIdAsync(id);
            if (stillThere is not null)
            {
                throw new InvalidOperationException(
                    $"Запись редукса '{id}' осталась в Supabase после DELETE с service-role-ключом. " +
                    "Возможно ключ невалидный или истёк. " +
                    "Проверь Supabase Studio: SELECT * FROM redux_items WHERE id='" + id + "';");
            }
        }
        catch (InvalidOperationException) { throw; }
        catch (Exception ex)
        {
            Debug.WriteLine($"[admin.catalog.delete] post-delete verify skipped: {ex.Message}");
        }
    }
#endif

