#if ADMIN
    public async Task<DuplicateHashMatchDto?> AdminFindByHashAsync(string sha256)
    {
        if (string.IsNullOrWhiteSpace(sha256)) return null;

        var sourceMatch = await _versionsRepo.FindBySourceSha256Async(sha256);
        if (sourceMatch is not null)
        {
            var parent = await _catalog.GetByIdAsync(sourceMatch.ReduxId);
            var name   = parent?.Name ?? sourceMatch.ReduxId;
            return new DuplicateHashMatchDto(sourceMatch.ReduxId, name, sourceMatch.Id, sourceMatch.Slot, sourceMatch.Label);
        }

        var versionMatch = await _versionsRepo.FindByPatchSha256Async(sha256);
        if (versionMatch is not null)
        {
            var parent = await _catalog.GetByIdAsync(versionMatch.ReduxId);
            var name   = parent?.Name ?? versionMatch.ReduxId;
            return new DuplicateHashMatchDto(versionMatch.ReduxId, name, versionMatch.Id, versionMatch.Slot, versionMatch.Label);
        }

        var legacyMatch = await _catalog.FindByPatchSha256Async(sha256);
        if (legacyMatch is not null)
        {
            return new DuplicateHashMatchDto(
                legacyMatch.Id, legacyMatch.Name, Guid.Empty, 0, "(legacy)");
        }

        return null;
    }
#endif

