    private static string MapSupabaseError(SupabaseException sx)
    {

        var body = sx.Message ?? string.Empty;

        if (body.Contains("review_delete_forbidden", StringComparison.Ordinal))
            return "Нельзя удалить этот отзыв - нужно быть автором или админом.";
        if (body.Contains("unauthorized", StringComparison.Ordinal))
            return "Сессия истекла - войдите заново.";

        if (sx.Kind == SupabaseErrorKind.BadRequest)
        {
            if (body.Contains("body_too_short", StringComparison.Ordinal))
                return "Отзыв слишком короткий - минимум 4 символа.";
            if (body.Contains("rating_out_of_range", StringComparison.Ordinal))
                return "Оценка должна быть от 1 до 5.";
            if (body.Contains("redux_id_required", StringComparison.Ordinal))
                return "Не указан мод.";
            if (body.Contains("user_id_required", StringComparison.Ordinal))
                return "Сессия истекла - войдите заново.";

            return $"Сервер отклонил запрос: {body}";
        }

        return sx.Kind switch
        {
            SupabaseErrorKind.Network        => "Сервер недоступен. Проверьте интернет-соединение.",
            SupabaseErrorKind.NotProvisioned => "Миграция 0007_tags_and_review_body.sql не применена. Прогоните её в Supabase SQL Editor + notify pgrst, 'reload schema'.",
            SupabaseErrorKind.Unauthorized   => "Сервер отклонил API-ключ.",
            SupabaseErrorKind.Conflict       => "Конфликт записи.",
            _                                => $"Ошибка сервера: {sx.Message}",
        };
    }

