        TargetGtaVersion    = d.TargetGtaVersion ?? string.Empty,
        Components          = (d.Components ?? new()).ToDictionary(
            kv => kv.Key,
            kv => new Admin.ReduxComponentInfo
            {
                IsFound       = kv.Value?.IsFound ?? false,
                SourceRpf     = kv.Value?.SourceRpf ?? string.Empty,
                InternalPaths = kv.Value?.InternalPaths?.ToList() ?? new(),
                Flags         = kv.Value?.Flags?.ToList() ?? new(),
            }),
        SourceSha256        = d.SourceSha256 ?? string.Empty,
    };

    private static ReduxItemDto ToReduxDto(Admin.ReduxItem r) => new(
        r.Id, r.Name, r.Author, r.AuthorLink, r.Description, r.VideoUrl, r.PreviewUrl,
        r.GalleryUrls,
        r.R2Urls is null ? null : new R2UrlsDto
        {
            Patch = r.R2Urls.Patch,
            Components = new Dictionary<string, string>(r.R2Urls.Components),
            Manifest = r.R2Urls.Manifest,
            ComponentMap = r.R2Urls.ComponentMap,
            ContentInfo = r.R2Urls.ContentInfo,
        },
        r.PatchSizeBytes, r.PatchSha256, r.TargetGtaVersion, r.SupportedServers,
        r.IsVerified,
        r.Components.ToDictionary(kv => kv.Key,
            kv => BuildComponentDto(kv.Key, kv.Value, r.R2Urls?.Components)),
        r.UploadedAt, r.UploadedBy, r.Status,
        r.ViewerPriority, r.DownloadCount,
        r.TagNew, r.TagBest,
        r.ArmorStandaloneInstallHidden,

        r.ComponentScreenshots ?? new Dictionary<string, string>());

    private static ComponentInfoDto BuildComponentDto(
        string componentName,
        Admin.ReduxComponentInfo info,
        IReadOnlyDictionary<string, string> componentUrls)
    {
        string? glbUrl = null;
        if (componentUrls != null)
        {

            if (componentName == "armor"
                && componentUrls.TryGetValue("armor_glb", out var glb)
                && !string.IsNullOrWhiteSpace(glb))
            {
                glbUrl = glb;
            }
        }
        return new ComponentInfoDto(
            IsFound:                info.IsFound,
            SourceRpf:              info.SourceRpf ?? string.Empty,
            InternalPaths:          info.InternalPaths?.ToArray() ?? Array.Empty<string>(),
            Flags:                  info.Flags?.ToArray() ?? Array.Empty<string>(),
            GlbUrl:                 glbUrl);
    }

    private static Admin.ReduxItem FromReduxDto(ReduxItemDto d)
    {
        var item = new Admin.ReduxItem();
        CopyDtoIntoItem(d, item);
        return item;
    }

    private static void CopyDtoIntoItem(ReduxItemDto d, Admin.ReduxItem r)
    {
        r.Id = d.Id ?? string.Empty; r.Name = d.Name ?? string.Empty;
        r.Author = d.Author ?? string.Empty; r.AuthorLink = d.AuthorLink ?? string.Empty;
        r.Description = d.Description ?? string.Empty;
        r.VideoUrl = d.VideoUrl ?? string.Empty; r.PreviewUrl = d.PreviewUrl ?? string.Empty;
        r.GalleryUrls = d.GalleryUrls?.ToList() ?? new();
        r.R2Urls = d.R2Urls is null ? null : new Admin.R2UrlsLocal
        {
            Patch = d.R2Urls.Patch,
            Components = new Dictionary<string, string>(d.R2Urls.Components ?? new()),
            Manifest = d.R2Urls.Manifest,
            ComponentMap = d.R2Urls.ComponentMap,
            ContentInfo = d.R2Urls.ContentInfo,
        };
        r.PatchSizeBytes = d.PatchSizeBytes;
        r.PatchSha256 = d.PatchSha256 ?? string.Empty;
        r.TargetGtaVersion = d.TargetGtaVersion ?? string.Empty;
        r.SupportedServers = d.SupportedServers?.ToList() ?? new();
        r.IsVerified = d.IsVerified;
        r.Components = (d.Components ?? new()).ToDictionary(
            kv => kv.Key,
            kv => new Admin.ReduxComponentInfo
            {
                IsFound = kv.Value?.IsFound ?? false,
                SourceRpf = kv.Value?.SourceRpf ?? string.Empty,
                InternalPaths = kv.Value?.InternalPaths?.ToList() ?? new(),
                Flags = kv.Value?.Flags?.ToList() ?? new(),
            });
        r.UploadedAt = d.UploadedAt;
        r.UploadedBy = d.UploadedBy ?? string.Empty;
        r.Status = d.Status ?? "published";
        r.ViewerPriority = d.ViewerPriority;
        r.DownloadCount = d.DownloadCount;
        r.TagNew  = d.TagNew;
        r.TagBest = d.TagBest;
        r.ArmorStandaloneInstallHidden = d.ArmorStandaloneInstallHidden;
        r.ComponentScreenshots = d.ComponentScreenshots is null
            ? new Dictionary<string, string>()
            : new Dictionary<string, string>(d.ComponentScreenshots);
    }

