#if ADMIN
    public async Task<InjectResultDto> AdminInjectAsync(string moddedRpfPath)
    {
        var (modded, resolveErr) = ResolveUpdateRpfPath(moddedRpfPath);
        if (modded is null)
            return new InjectResultDto(false, resolveErr, null);

        var cfg = await _adminConfig.GetAsync();
        if (string.IsNullOrWhiteSpace(cfg.CleanUpdateRpfPath) || !File.Exists(cfg.CleanUpdateRpfPath))
            return new InjectResultDto(false, "Чистый update.rpf не задан в Admin → Settings → Paths.", null);

        var gtaRoot = await GetGtaPathAsync();
        if (string.IsNullOrWhiteSpace(gtaRoot))
            return new InjectResultDto(false, "GTA не найдена. Укажи путь в Admin → Settings → Paths.", null);

        try
        {
            Debug.WriteLine($"[admin.inject] modded='{modded}' clean='{cfg.CleanUpdateRpfPath}' gta='{gtaRoot}'");
            string workDir = await Task.Run(() =>
            {
                var pipeline = new Core.Parser.ReduxParserPipeline();
                var w = pipeline.ParseRedux(cfg.CleanUpdateRpfPath, modded, $"admin_inject_{Guid.NewGuid().ToString("N")[..8]}");
                return MoveWorkDirIfRequested(w, cfg.WorkDirOverride);
            });
            Debug.WriteLine($"[admin.inject] pipeline workDir='{workDir}'");

            var (ok, engine) = await InjectPatchWithRetryAsync(gtaRoot, workDir, "admin.inject");
            Debug.WriteLine($"[admin.inject] InjectPatch returned {ok}");

            return new InjectResultDto(
                Success: ok,
                ErrorMessage: ok ? null : InjectFailureMessage(engine, "InjectPatch вернул false. Проверь Debug-лог Shell для подробностей."),
                WorkDir: workDir);
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[admin.inject] CRASH: {ex.GetType().Name}: {ex.Message}\n{ex.StackTrace}");
            return new InjectResultDto(false, $"{ex.GetType().Name}: {ex.Message}", null);
        }
    }
#endif

    private static string MoveWorkDirIfRequested(string sourceWorkDir, string? overrideRoot)
    {
        if (string.IsNullOrWhiteSpace(overrideRoot)) return sourceWorkDir;
        try
        {
            Directory.CreateDirectory(overrideRoot);
            var leaf = Path.GetFileName(sourceWorkDir.TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar));
            var dest = Path.Combine(overrideRoot, leaf);
            if (Directory.Exists(dest)) Directory.Delete(dest, recursive: true);
            Directory.Move(sourceWorkDir, dest);
            Debug.WriteLine($"[admin.inject] workDir moved → {dest}");
            return dest;
        }
        catch (IOException ioex)
        {

            Debug.WriteLine($"[admin.inject] cross-volume move; falling back to copy: {ioex.Message}");
            try
            {
                var leaf = Path.GetFileName(sourceWorkDir.TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar));
                var dest = Path.Combine(overrideRoot, leaf);
                CopyDirectoryRecursive(sourceWorkDir, dest);
                Directory.Delete(sourceWorkDir, recursive: true);
                return dest;
            }
            catch (Exception cex)
            {
                Debug.WriteLine($"[admin.inject] copy fallback FAILED: {cex.Message} - using source workDir");
                return sourceWorkDir;
            }
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[admin.inject] WorkDir move failed: {ex.Message} - using source workDir");
            return sourceWorkDir;
        }
    }

    private static void CopyDirectoryRecursive(string sourceDir, string destDir)
    {
        Directory.CreateDirectory(destDir);
        foreach (var file in Directory.GetFiles(sourceDir))
            File.Copy(file, Path.Combine(destDir, Path.GetFileName(file)), overwrite: true);
        foreach (var sub in Directory.GetDirectories(sourceDir))
            CopyDirectoryRecursive(sub, Path.Combine(destDir, Path.GetFileName(sub)));
    }

#if ADMIN
    public Task<InjectResultDto> AdminInjectFromCatalogAsync(string reduxId)
        => AdminInjectFromCatalogInternalAsync(reduxId, versionId: null, progressEmit: null);
#endif

    private string InjectFailureMessage(Core.Injector.RpfInjectEngine engine, string fallback)
    {
        var raw = engine.LastError;
        return string.IsNullOrWhiteSpace(raw) ? fallback : TranslateInjectError(raw);
    }

    private string? _lastLockAutoFixNote;

    private string DescribeUpdateRpfLockState()
    {
        try
        {
            var root = _hardwareLocator.FindGtaPath();
            if (string.IsNullOrWhiteSpace(root)) return string.Empty;
            var p = Path.Combine(root, "update", "update.rpf");
            if (!File.Exists(p)) return string.Empty;

            var scan = Services.FileLockFinder.Scan(p);

            if (scan.Lockers.Count > 0)
            {
                var parts = scan.Lockers.Select(l =>
                    string.IsNullOrEmpty(l.Friendly) ? $"{l.ProcessName} (PID {l.Pid})"
                                                      : $"{l.ProcessName} - {l.Friendly}");
                var msg = "\n\n" + Loc.T("errors.lock.heldBy", ("who", string.Join(", ", parts)));
                if (scan.RebootRequired)
                    msg += " " + Loc.T("errors.lock.rebootAlso");
                return msg;
            }

            if (scan.RebootRequired)
                return "\n\n" + Loc.T("errors.lock.rebootRequired");

            if (!string.IsNullOrEmpty(_lastLockAutoFixNote))
                return "\n\n" + Loc.T("errors.lock.autoFixDidNotHelp", ("note", _lastLockAutoFixNote));

            return "\n\n" + Loc.T("errors.lock.notLocked");
        }
        catch { return string.Empty; }
    }

    private static string? TryAutoFixUpdateRpfLock(string updateRpfPath)
    {
        var actions = new List<string>();
        try
        {
            if (File.Exists(updateRpfPath))
            {
                var attr = File.GetAttributes(updateRpfPath);
                if (attr.HasFlag(FileAttributes.ReadOnly))
                {
                    File.SetAttributes(updateRpfPath, attr & ~FileAttributes.ReadOnly);
                    actions.Add(Loc.T("errors.autofix.clearedReadOnly"));
                    Debug.WriteLine($"[lock-autofix] cleared ReadOnly on {updateRpfPath}");
                }
            }

            var deleted = new List<string>();
            var name = Path.GetFileName(updateRpfPath);
            foreach (var suffix in new[] { ".hnt_temp", ".restoring", ".partial" })
            {
                var temp = updateRpfPath + suffix;
                if (!File.Exists(temp)) continue;

                if (Services.FileLockFinder.Scan(temp).Lockers.Count > 0)
                {
                    Debug.WriteLine($"[lock-autofix] orphan {temp} is still held - skipping delete");
                    continue;
                }
                try
                {
                    var ta = File.GetAttributes(temp);
                    if (ta.HasFlag(FileAttributes.ReadOnly))
                        File.SetAttributes(temp, ta & ~FileAttributes.ReadOnly);
                    File.Delete(temp);
                    deleted.Add(name + suffix);
                    Debug.WriteLine($"[lock-autofix] deleted orphan {temp}");
                }
                catch (Exception ex) { Debug.WriteLine($"[lock-autofix] delete {temp} FAILED: {ex.Message}"); }
            }
            if (deleted.Count > 0)
                actions.Add(Loc.T("errors.autofix.deletedLeftover", ("files", string.Join(", ", deleted))));
        }
        catch (Exception ex) { Debug.WriteLine($"[lock-autofix] OUTER: {ex.Message}"); }

        if (actions.Count == 0) return null;
        var s = string.Join(", ", actions);
        return Loc.T("errors.autofix.summary", ("actions", s));
    }

    private static bool IsTransientInjectError(string? engineError)
    {
        if (string.IsNullOrWhiteSpace(engineError)) return false;
        return engineError.Contains("RPF7 has no", StringComparison.OrdinalIgnoreCase)
            || engineError.Contains("being used by another process", StringComparison.OrdinalIgnoreCase)
            || engineError.Contains("IOException", StringComparison.OrdinalIgnoreCase)
            || engineError.Contains("UnauthorizedAccessException", StringComparison.OrdinalIgnoreCase);
    }

    private static bool IsTransientFileLock(Exception ex)
    {
        if (ex is UnauthorizedAccessException) return true;
        if (ex is IOException)
        {
            var code = ex.HResult & 0xFFFF;
            if (code == 32 || code == 33) return true;
            return ex.Message.Contains("another process", StringComparison.OrdinalIgnoreCase)
                || ex.Message.Contains("используется", StringComparison.OrdinalIgnoreCase);
        }
        return false;
    }

    private async Task<bool> RestoreCleanWithLockRetryAsync(string gtaRoot, CancellationToken ct,
        Action<int>? progressPercent = null)
    {
        _lastLockAutoFixNote = null;
        var updateRpf = Path.Combine(gtaRoot, "update", "update.rpf");
        var backoffMs = new[] { 0, 1500, 3000, 4500, 6000 };
        Exception? last = null;
        for (int attempt = 0; attempt < backoffMs.Length; attempt++)
        {
            if (attempt > 0)
            {
                _lastLockAutoFixNote = await Task.Run(() => TryAutoFixUpdateRpfLock(updateRpf));
                GC.Collect();
                GC.WaitForPendingFinalizers();
                await Task.Delay(backoffMs[attempt], ct);
                Debug.WriteLine($"[restore.clean] retry {attempt} после autofix='{_lastLockAutoFixNote ?? "<none>"}'");
            }
            if (File.Exists(updateRpf) && Services.FileLockFinder.Scan(updateRpf).Lockers.Count > 0)
            {
                last = new IOException(Loc.T("errors.restore.updateRpfHeld"));
                Debug.WriteLine($"[restore.clean] attempt {attempt + 1}: файл ещё занят, пропускаю копию");
                continue;
            }
            try
            {
                return await _backupService.RestoreFromCleanAsync(gtaRoot, ct, progressPercent);
            }
            catch (Exception ex) when (IsTransientFileLock(ex))
            {
                last = ex;
                Debug.WriteLine($"[restore.clean] attempt {attempt + 1} блокировка: {ex.Message}");
            }
        }
        throw last ?? new IOException(Loc.T("errors.restore.updateRpfBusy"));
    }

    private string TranslateInjectError(string engineError)
    {
        if (string.IsNullOrWhiteSpace(engineError))
            return Loc.T("errors.inject.generic");

        if (engineError.Contains("RPF7 has no", StringComparison.OrdinalIgnoreCase))
            return Loc.T("errors.inject.rpf7Empty") + DescribeUpdateRpfLockState();

        if (engineError.Contains("being used by another process", StringComparison.OrdinalIgnoreCase))
        {
            var detail = DescribeUpdateRpfLockState();
            if (string.IsNullOrEmpty(detail))
                detail = "\n\n" + Loc.T("errors.inject.busyHint");
            return Loc.T("errors.inject.busy") + detail;
        }

        if (engineError.Contains("UnauthorizedAccessException", StringComparison.OrdinalIgnoreCase))
            return Loc.T("errors.inject.noWriteAccess") + DescribeUpdateRpfLockState();

        return engineError + "\n\n" + Loc.T("errors.inject.retryHint");
    }

    private async Task<(bool ok, Core.Injector.RpfInjectEngine engine)> InjectPatchWithRetryAsync(
        string gtaRoot, string workDir, string debugLabel)
    {
        _lastLockAutoFixNote = null;

        Core.Injector.RpfInjectEngine engine = new(gtaRoot);
        bool ok = await Task.Run(() => engine.InjectPatch(workDir));
        if (ok) return (true, engine);

        var firstErr = engine.LastError;
        Debug.WriteLine($"[{debugLabel}] inject attempt 1 failed: {firstErr}");

        if (!IsTransientInjectError(firstErr))
            return (false, engine);

        var updateRpf = Path.Combine(gtaRoot, "update", "update.rpf");
        _lastLockAutoFixNote = await Task.Run(() => TryAutoFixUpdateRpfLock(updateRpf));
        Debug.WriteLine($"[{debugLabel}] transient - autofix='{_lastLockAutoFixNote ?? "<none>"}', retrying after GC + 750 ms");
        GC.Collect();
        GC.WaitForPendingFinalizers();
        await Task.Delay(TimeSpan.FromMilliseconds(750));

        engine = new Core.Injector.RpfInjectEngine(gtaRoot);
        ok = await Task.Run(() => engine.InjectPatch(workDir));
        Debug.WriteLine($"[{debugLabel}] inject attempt 2: ok={ok}, err={engine.LastError}");
        if (ok) _lastLockAutoFixNote = null;
        return (ok, engine);
    }

    private static void PurgeStaleWorkDirs(string baseDir, string prefix, string keepDir, string? legacyTempRoot = null)
    {
        try
        {
            if (Directory.Exists(baseDir))
            {
                foreach (var d in Directory.EnumerateDirectories(baseDir))
                {
                    if (string.Equals(d, keepDir, StringComparison.OrdinalIgnoreCase)) continue;
                    var name = Path.GetFileName(d);
                    if (!name.StartsWith(prefix, StringComparison.OrdinalIgnoreCase)) continue;
                    try
                    {
                        Directory.Delete(d, recursive: true);
                        Debug.WriteLine($"[workdir.purge] снесена брошенная папка установки {name}");
                    }
                    catch (Exception ex) { Debug.WriteLine($"[workdir.purge] {name}: {ex.Message}"); }
                }
            }

            if (!string.IsNullOrWhiteSpace(legacyTempRoot) && Directory.Exists(legacyTempRoot))
            {
                try
                {
                    Directory.Delete(legacyTempRoot, recursive: true);
                    Debug.WriteLine($"[workdir.purge] снесена старая куча в TEMP: {legacyTempRoot}");
                }
                catch (Exception ex) { Debug.WriteLine($"[workdir.purge] legacy temp: {ex.Message}"); }
            }
        }
        catch (Exception ex) { Debug.WriteLine($"[workdir.purge] обход '{baseDir}' сорвался: {ex.Message}"); }
    }

    private async Task<InjectResultDto> AdminInjectFromCatalogInternalAsync(string reduxId, Guid? versionId, Action<string, int, string?>? progressEmit, CancellationToken ct = default)
    {
        if (string.IsNullOrWhiteSpace(reduxId))
            return new InjectResultDto(false, "reduxId не указан.", null);

        var resolved = await ResolveVersionAsync(reduxId, versionId);
        if (resolved is null)
            return new InjectResultDto(false, $"Редукс '{reduxId}' не найден в каталоге.", null);

        if (string.IsNullOrWhiteSpace(resolved.Urls.Patch) || string.IsNullOrWhiteSpace(resolved.Urls.Manifest))
            return new InjectResultDto(false,
                resolved.IsLegacy
                    ? "У этого редукса нет R2-ссылок на patch.zip / manifest.json. При загрузке очередь не аплоадилась в R2. Перезалей с включённой галкой 'Загрузить на R2'."
                    : $"Версия '{resolved.Label}' (slot {resolved.Slot}) не имеет patch.zip на R2. Перезалей с включённой галкой 'Загрузить на R2'.",
                null);

        var gtaRoot = await GetGtaPathAsync();
        if (string.IsNullOrWhiteSpace(gtaRoot))
            return new InjectResultDto(false, "GTA не найдена. Укажи путь в Admin → Settings → Paths.", null);

        var cfg = await _adminConfig.GetAsync();

        var reserve = await Task.Run(() => Core.System.DataQuota.TryReserve(
            resolved.PatchSizeBytes > 0 ? resolved.PatchSizeBytes * 2 : 0,
            $"установка редукса {reduxId}"));
        if (!reserve.Ok)
        {
            progressEmit?.Invoke("error", 0, reserve.Message);
            return new InjectResultDto(false, reserve.Message, null);
        }

        var baseDir = !string.IsNullOrWhiteSpace(cfg.WorkDirOverride) && Directory.Exists(cfg.WorkDirOverride)
            ? cfg.WorkDirOverride!
            : Core.System.AppDataRoot.WorkRoot;
        Directory.CreateDirectory(baseDir);
        var workDir = Path.Combine(baseDir, $"catalog_inject_{reduxId}_{DateTime.Now:yyyyMMdd_HHmmss}");
        PurgeStaleWorkDirs(baseDir, "catalog_inject_", workDir,
            legacyTempRoot: Path.Combine(Path.GetTempPath(), "MiamiGraphics", "catalog_inject"));
        Directory.CreateDirectory(workDir);
        var patchFilesDir = Path.Combine(workDir, "patch_files");
        Directory.CreateDirectory(patchFilesDir);

        Debug.WriteLine($"[admin.inject.catalog] reduxId='{reduxId}' workDir='{workDir}'");

        try
        {
            using var http = HttpClientFactory.CreateFragmenting(TimeSpan.FromMinutes(15));

            progressEmit?.Invoke("downloading", 5, "Готовлю загрузку...");

            var patchZipPath = Path.Combine(workDir, "patch.zip");
            await DownloadFileAsync(http, resolved.Urls.Patch!, patchZipPath,
                bytesProgress: (received, total) =>
                {
                    if (total > 0)
                    {
                        var pct = 5 + (int)Math.Min(50, received * 50L / total);
                        progressEmit?.Invoke("downloading", pct, DownloadCounterText(received, total));
                    }
                    else
                    {
                        progressEmit?.Invoke("downloading", -1, $"Загрузка - {received / 1024 / 1024} МБ");
                    }
                },
                ct: ct);
            ct.ThrowIfCancellationRequested();
            Debug.WriteLine($"[admin.inject.catalog] patch.zip downloaded ({new FileInfo(patchZipPath).Length / 1024 / 1024} MB) slot={resolved.Slot?.ToString() ?? "legacy"}");

            if (string.IsNullOrWhiteSpace(resolved.PatchSha256))
            {
                return new InjectResultDto(false,
                    "Установка отклонена: для patch.zip не задан SHA-256 (отказ устанавливать непроверенный файл).",
                    workDir);
            }
            {
                var shaBand = new ProgressBand(55, 60);
                progressEmit?.Invoke("verifying", shaBand.From, "Проверяю целостность patch.zip...");
                var actualSha = await Task.Run(() => ComputeFileSha256(patchZipPath,
                    (done, total) => progressEmit?.Invoke("verifying", shaBand.MapBytes(done, total),
                        $"Проверяю целостность patch.zip - {done / 1024 / 1024} / {Math.Max(1, total / 1024 / 1024)} МБ")));
                if (!string.Equals(actualSha, resolved.PatchSha256, StringComparison.OrdinalIgnoreCase))
                {
                    Debug.WriteLine($"[admin.inject.catalog] SHA mismatch! expected={resolved.PatchSha256} actual={actualSha}");
                    return new InjectResultDto(false,
                        "Скачанный patch.zip не совпадает с эталонным SHA-256. Возможно файл повреждён или подменён. " +
                        $"expected={resolved.PatchSha256[..16]}… actual={actualSha[..16]}…",
                        workDir);
                }
                Debug.WriteLine($"[admin.inject.catalog] SHA verified: {actualSha[..16]}…");
            }

            var extractBand = new ProgressBand(60, 64);
            progressEmit?.Invoke("extracting", extractBand.From, "Распаковываю файлы редукса...");
            await Task.Run(() => ExtractZipWithProgress(patchZipPath, patchFilesDir,
                (i, total, name) => progressEmit?.Invoke("extracting",
                    total > 0 ? extractBand.From + (int)((long)extractBand.Width * i / total) : extractBand.From,
                    $"Распаковываю файлы редукса - {i} / {total}{(string.IsNullOrEmpty(name) ? "" : $" ({name})")}")), ct);

            var assetShasInj = await ReduxAssetShasAsync(resolved.VersionId);
            await Services.VerifiedDownload.FetchAsync(resolved.Urls.Manifest!,
                Path.Combine(workDir, "manifest.json"), assetShasInj.Manifest,
                "manifest.json редукса", referenceRequired: false, ct: ct);
            ct.ThrowIfCancellationRequested();

            if (!string.IsNullOrWhiteSpace(resolved.Urls.ComponentMap))
                await Services.VerifiedDownload.FetchAsync(resolved.Urls.ComponentMap!,
                    Path.Combine(workDir, "component_map.json"), assetShasInj.ComponentMap,
                    "component_map.json редукса", referenceRequired: false, ct: ct);
            if (!string.IsNullOrWhiteSpace(resolved.Urls.ContentInfo))
                await Services.VerifiedDownload.FetchAsync(resolved.Urls.ContentInfo!,
                    Path.Combine(workDir, "content_info.json"), assetShasInj.ContentInfo,
                    "content_info.json редукса", referenceRequired: false, ct: ct);
            ct.ThrowIfCancellationRequested();

            progressEmit?.Invoke("injecting", 65, "Пересобираю update.rpf...");

            using var rampCts = new CancellationTokenSource();
            Action<string, int>? rampEmit = progressEmit is null
                ? null
                : (ph, pc) => progressEmit(ph, pc, "Пересобираю update.rpf...");
            var ramp = StartProgressRamp(rampEmit, "injecting", 65, 95, 60, rampCts.Token);

            try
            {
                try
                {
                    var (ok, engine) = await InjectPatchWithRetryAsync(gtaRoot, workDir, "admin.inject.catalog");
                    Debug.WriteLine($"[admin.inject.catalog] InjectPatch returned {ok}");
                    progressEmit?.Invoke(ok ? "done" : "error", ok ? 100 : 65, null);
                    return new InjectResultDto(ok, ok ? null : InjectFailureMessage(engine, "InjectPatch вернул false. См. Debug-лог."), workDir);
                }
                catch (Exception ex)
                {
                    Debug.WriteLine($"[admin.inject.catalog] inject CRASH: {ex.GetType().Name}: {ex.Message}\n{ex.StackTrace}");
                    progressEmit?.Invoke("error", 65, null);
                    return new InjectResultDto(false, TranslateInjectError($"{ex.GetType().Name}: {ex.Message}"), workDir);
                }
            }
            finally
            {
                rampCts.Cancel();
                try { await ramp; } catch { }
            }
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[admin.inject.catalog] download/extract CRASH: {ex.GetType().Name}: {ex.Message}");
            return new InjectResultDto(false, $"Ошибка загрузки/распаковки: {ex.Message}", workDir);
        }
    }

    private static Task DownloadFileAsync(System.Net.Http.HttpClient http, string url, string destPath,
        Action<long, long>? bytesProgress = null,
        CancellationToken ct = default)
    {
        _ = http;
        return DownloadViaMirrorAsync(url, destPath, bytesProgress, ct);
    }

    internal static async Task DownloadViaMirrorAsync(string url, string destPath,
        Action<long, long>? bytesProgress, CancellationToken ct = default)
    {
        try { await MirrorSelector.EnsureSelectedAsync(ct).WaitAsync(TimeSpan.FromSeconds(6), ct).ConfigureAwait(false); }
        catch (OperationCanceledException) when (ct.IsCancellationRequested) { throw; }
        catch {}

        var candidates = BuildDownloadCandidates(url);

        LastProblemDownloadUrl = url;

        var logName = Path.GetFileName(destPath);
        var logKey = Uri.TryCreate(url, UriKind.Absolute, out var logUri) ? logUri.AbsolutePath : url;
        var logStorageHost = MirrorSelector.RegionStorageHost;
        DownloadLog.Write("download",
            $"старт {logName} (ключ {logKey}): кандидаты {string.Join(" > ", candidates.Select(HostOf))}; "
            + $"хранилище {logStorageHost}: {(MirrorSelector.IsStorageUsable(logStorageHost) ? "по пробе пригодно" : "по пробе молчит/ползёт - в обход")}");
        var logTrail = new List<string>();

        var ruSource = Services.DownloadSourceStore.Effective() == Services.DownloadSource.Ru2;
        var ruRegion = Services.ServerRegionStore.EffectiveRegion() == Services.ServerRegion.Ru;

        var hubSlot = candidates.Count > 1
                      && Uri.TryCreate(candidates[0], UriKind.Absolute, out var head)
                      && string.Equals(head.Host, MirrorSelector.RuStorageHost, StringComparison.OrdinalIgnoreCase)
                      ? 1 : 0;

        HubLease hubLease = HubLease.NoOp;
        var hubAsked = false;

        var missing = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

        Exception? last = null;
        Exception? lastMissing = null;
        try
        {
        var chainBudget = System.Diagnostics.Stopwatch.StartNew();
        var chainBudgetMax = TimeSpan.FromMinutes(4);
        var hubWait = TimeSpan.Zero;
        const int maxAttempts = 3;
        for (var attempt = 1; attempt <= maxAttempts; attempt++)
        {
            for (var i = 0; i < candidates.Count; i++)
            {
                if (i == hubSlot && !hubAsked && (ruSource || ruRegion))
                {
                    hubAsked = true;
                    var askedAt = chainBudget.Elapsed;
                    try
                    {
                        var keyPath = Uri.TryCreate(url, UriKind.Absolute, out var ku) ? ku.AbsolutePath : url;
                        var (hubUrl, leaseObj) = await HubRouter.ResolveAsync(
                            keyPath,
                            onQueue: (pos, eta) => _emitStatic?.Invoke("download:queue", new { active = true, position = pos, etaSec = eta }),
                            ct).ConfigureAwait(false);
                        hubLease = leaseObj;
                        _emitStatic?.Invoke("download:queue", new { active = false, position = 0, etaSec = 0 });
                        if (!string.IsNullOrEmpty(hubUrl))
                        {
                            var dup = candidates.FindIndex(x => string.Equals(x, hubUrl, StringComparison.OrdinalIgnoreCase));
                            if (dup >= i)
                            {
                                candidates.RemoveAt(dup);
                                candidates.Insert(i, hubUrl!);
                            }
                            else if (dup < 0)
                            {
                                candidates.Insert(i, hubUrl!);
                            }
                        }
                    }
                    catch (OperationCanceledException) when (ct.IsCancellationRequested) { throw; }
                    catch {}
                    hubWait += chainBudget.Elapsed - askedAt;
                }

                var candidate = candidates[i];
                if (missing.Contains(candidate)) continue;
                var isStorage = IsRuStorageCandidate(candidate);
                if (isStorage && candidates.Count > 1
                    && !MirrorSelector.IsStorageUsable(MirrorSelector.RuStorageHost)) continue;
                try
                {
                    if (i == 0)
                    {
                        if (attempt == 1 && !string.Equals(url, candidate, StringComparison.OrdinalIgnoreCase))
                            Debug.WriteLine($"[download] mirror rewrite: {url} -> {candidate}");
                    }
                    else
                    {
                        Debug.WriteLine($"[download] host fallback {i}/{candidates.Count - 1} (attempt {attempt}): {candidate}");
                    }

                    var swCand = System.Diagnostics.Stopwatch.StartNew();
                    if (isStorage && i < candidates.Count - 1)
                        await DownloadFromStorageAsync(candidate, destPath, bytesProgress,
                            MaxStreamsForUrl(candidate), ct);
                    else
                        await ParallelDownloader.DownloadAsync(candidate, destPath, bytesProgress,
                            parallelism: MaxStreamsForUrl(candidate), ct: ct);

                    swCand.Stop();
                    long gotBytes = 0;
                    try { gotBytes = new FileInfo(destPath).Length; } catch { }
                    var gotSec = Math.Max(swCand.Elapsed.TotalSeconds, 0.001);
                    DownloadLog.Write("download",
                        $"успех {logName}: {HostOf(candidate)}, {gotBytes / 1048576.0:F1} МБ за {gotSec:F1} с = {gotBytes / 1048576.0 / gotSec:F1} МБ/с "
                        + $"(проход {attempt}/{maxAttempts}, кандидат {i + 1}/{candidates.Count})");
                    return;
                }
                catch (OperationCanceledException) when (ct.IsCancellationRequested)
                {
                    throw;
                }
                catch (ParallelDownloader.FileNotOnMirrorException ex)
                {
                    lastMissing = ex;
                    missing.Add(candidate);
                    Debug.WriteLine($"[download] на кандидате файла нет (404), идём дальше: {candidate}");
                    logTrail.Add($"{HostOf(candidate)}: файла нет (404)");
                    DownloadLog.Write("download",
                        $"переезд {logName}: файла нет на этом зеркале ({HostOf(candidate)}, 404) - беру следующего кандидата");
                }
                catch (Exception ex)
                {
                    last = ex;
                    if (isStorage) MirrorSelector.ReportStorageFailure(MirrorSelector.RuStorageHost);
                    Debug.WriteLine($"[download] candidate failed ({candidate}, attempt {attempt}): {ex.GetType().Name}: {ex.Message}");
                    logTrail.Add($"{HostOf(candidate)}: {ex.GetType().Name}: {ex.Message}");
                    DownloadLog.Write("download",
                        $"переезд {logName}: {HostOf(candidate)} отказал (проход {attempt}) - {ex.GetType().Name}: {ex.Message}");
                }
            }

            if (attempt < maxAttempts && IsTransientNetworkError(last) && chainBudget.Elapsed - hubWait < chainBudgetMax)
            {
                Debug.WriteLine($"[download] all mirrors failed (attempt {attempt}/{maxAttempts}) - transient, retrying after backoff");
                try { await Task.Delay(TimeSpan.FromSeconds(attempt * 2), ct); }
                catch (OperationCanceledException) when (ct.IsCancellationRequested) { throw; }
                continue;
            }
            break;
        }

        }
        finally
        {
            await hubLease.DisposeAsync().ConfigureAwait(false);
            if (!ReferenceEquals(hubLease, HubLease.NoOp))
                _emitStatic?.Invoke("download:queue", new { active = false, position = 0, etaSec = 0 });
        }

        DownloadLog.Write("download",
            $"провал {logName}: {(logTrail.Count > 0 ? string.Join("; ", logTrail.Distinct()) : "кандидатов не было")}");

        var friendly = DescribeDownloadError(last);
        if (friendly is not null)
            throw new HttpRequestException(friendly, last);

        if (last is not null) throw last;
        if (lastMissing is not null)
            throw new HttpRequestException(
                Loc.T("errors.download.notOnAnyMirror", ("url", url)),
                lastMissing, System.Net.HttpStatusCode.NotFound);
        throw new InvalidOperationException(Loc.T("errors.download.allMirrorsDown", ("url", url)));
    }

    private static string HostOf(string url)
        => Uri.TryCreate(url, UriKind.Absolute, out var u) ? u.Host : url;

    private static bool IsRuStorageCandidate(string candidate)
        => Uri.TryCreate(candidate, UriKind.Absolute, out var u)
           && string.Equals(u.Host, MirrorSelector.RuStorageHost, StringComparison.OrdinalIgnoreCase);

    private const long StorageWarmupBytes = 2L * 1024 * 1024;

    private static readonly TimeSpan StorageWarmupWindow = TimeSpan.FromSeconds(25);

    private static async Task DownloadFromStorageAsync(string url, string destPath,
        Action<long, long>? bytesProgress, int parallelism, CancellationToken ct)
    {
        using var abort = new CancellationTokenSource();
        using var linked = CancellationTokenSource.CreateLinkedTokenSource(ct, abort.Token);
        long got = 0, size = 0;
        long baseGot = -1;

        var watch = Task.Run(async () =>
        {
            try
            {
                await Task.Delay(StorageWarmupWindow, linked.Token).ConfigureAwait(false);
                var s = Interlocked.Read(ref size);
                var b = Volatile.Read(ref baseGot);
                var remaining = s > 0 && b >= 0 ? s - b : s;
                var need = remaining > 0 ? Math.Min(StorageWarmupBytes, remaining * 3 / 4) : StorageWarmupBytes;
                var delivered = Interlocked.Read(ref got) - Math.Max(b, 0);
                if (delivered < need) abort.Cancel();
            }
            catch (OperationCanceledException) {}
        });

        try
        {
            await ParallelDownloader.DownloadAsync(url, destPath,
                (recv, total) =>
                {
                    Interlocked.CompareExchange(ref baseGot, recv, -1);
                    Interlocked.Exchange(ref got, recv);
                    if (total > 0) Interlocked.Exchange(ref size, total);
                    bytesProgress?.Invoke(recv, total);
                },
                parallelism: parallelism, ct: linked.Token);
        }
        catch (OperationCanceledException) when (abort.IsCancellationRequested && !ct.IsCancellationRequested)
        {
            throw new IOException(Loc.T("errors.download.storageTooSlow",
                ("mb", StorageWarmupBytes / 1024 / 1024),
                ("sec", StorageWarmupWindow.TotalSeconds.ToString("F0", global::System.Globalization.CultureInfo.InvariantCulture))));
        }
        finally
        {
            abort.Cancel();
            try { await watch.ConfigureAwait(false); } catch { }
        }
    }

    internal static bool IsTransientNetworkError(Exception? ex)
    {
        for (var e = ex; e is not null; e = e.InnerException)
        {
            if (e is System.Security.Authentication.AuthenticationException
                || e is System.Net.Sockets.SocketException
                || e is TimeoutException
                || e is IOException)
                return true;
            var m = e.Message ?? string.Empty;
            if (m.Contains("SSL", StringComparison.OrdinalIgnoreCase)
                || m.Contains("secure channel", StringComparison.OrdinalIgnoreCase)
                || m.Contains("connection could not be established", StringComparison.OrdinalIgnoreCase)
                || m.Contains("forcibly closed", StringComparison.OrdinalIgnoreCase)
                || m.Contains("connection was closed", StringComparison.OrdinalIgnoreCase))
                return true;
        }
        return false;
    }

    private static string? DescribeDownloadError(Exception? ex)
    {
        var isTls = false;
        for (var e = ex; e is not null; e = e.InnerException)
        {
            if (e is System.Security.Authentication.AuthenticationException) { isTls = true; break; }
            var m = e.Message ?? string.Empty;
            if (m.Contains("SSL", StringComparison.OrdinalIgnoreCase)
                || m.Contains("secure channel", StringComparison.OrdinalIgnoreCase)
                || m.Contains("connection could not be established", StringComparison.OrdinalIgnoreCase))
            { isTls = true; break; }
        }
        if (!isTls) return null;
        return "Не удалось скачать с серверов (ошибка SSL-соединения). "
             + "Проверь интернет и повтори - лаунчер попробует другие зеркала.";
    }

    internal static int MaxStreamsForUrl(string url)
    {
        if (!Uri.TryCreate(url, UriKind.Absolute, out var uri)) return 8;
        var host = uri.Host;
        if (host.EndsWith(".miamigraphicsstorage.uk", StringComparison.OrdinalIgnoreCase))
        {
            var node = host[..^".miamigraphicsstorage.uk".Length];
            return node.ToLowerInvariant() switch
            {
                "ru2"                             => 2,
                "spb1" or "spb2" or "msk" or "hnt" or "eu" or "ru" => 4,
                "rf"                              => 8,
                _                                 => 8,
            };
        }
        return 8;
    }

    internal static List<string> BuildDownloadCandidates(string url)
    {
        var result = new List<string>();
        if (!Uri.TryCreate(url, UriKind.Absolute, out var uri) || !MirrorSelector.ShouldRewrite(url))
        {
            result.Add(url);
            return result;
        }

        const string CfCdn  = "cdn.miamigraphicsstorage.uk";
        const string CfBare = "miamigraphicsstorage.uk";
        const string RuVps  = Services.DownloadSourceStore.RuVpsHost;
        const string R2Pub  = "pub-f3641b214c164277964c1e92c826b19b.r2.dev";

        void Add(string? host)
        {
            if (string.IsNullOrEmpty(host)) return;
            var u = new UriBuilder(uri) { Scheme = "https", Host = host, Port = -1 }.Uri.ToString();
            if (!result.Any(x => string.Equals(x, u, StringComparison.OrdinalIgnoreCase)))
                result.Add(u);
        }

        if (Services.DownloadSourceStore.Effective() == Services.DownloadSource.Ru2)
        {
            if (MirrorSelector.IsStorageUsable(MirrorSelector.RuStorageHost))
                Add(MirrorSelector.RuStorageHost);
            Add(RuVps);
            Add(R2Pub);
            return result;
        }

        var ru = Services.ServerRegionStore.EffectiveRegion() == Services.ServerRegion.Ru;

        var storageHost = MirrorSelector.RegionStorageHost;
        if (MirrorSelector.IsStorageUsable(storageHost))
            Add(storageHost);

        var hosts = ru
            ? new[] { CfCdn, R2Pub, RuVps, CfBare }
            : new[] { CfCdn, CfBare, R2Pub, RuVps };

        foreach (var h in hosts) Add(h);
        return result;
    }

#if ADMIN
    public async Task<bool> AdminRestoreCleanUpdateAsync()
    {
        var cfg = await _adminConfig.GetAsync();
        if (string.IsNullOrWhiteSpace(cfg.CleanUpdateRpfPath) || !File.Exists(cfg.CleanUpdateRpfPath))
            throw new InvalidOperationException("Чистый update.rpf не задан или не найден. Admin → Settings → Paths.");

        var gtaRoot = await GetGtaPathAsync();
        if (string.IsNullOrWhiteSpace(gtaRoot))
            throw new InvalidOperationException("GTA не найдена. Укажи путь в Admin → Settings → Paths.");

        var dest = Path.Combine(gtaRoot, "update", "update.rpf");
        var destDir = Path.GetDirectoryName(dest);
        if (string.IsNullOrEmpty(destDir) || !Directory.Exists(destDir))
            throw new InvalidOperationException($"Не найдена папка update в GTA: {destDir}");

        try
        {
            if (File.Exists(dest))
            {
                var attrs = File.GetAttributes(dest);
                if ((attrs & FileAttributes.ReadOnly) == FileAttributes.ReadOnly)
                    File.SetAttributes(dest, attrs & ~FileAttributes.ReadOnly);
            }
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[admin.restore] failed to clear ReadOnly on {dest}: {ex.Message}");
        }

        const int bufferSize = 1 << 20;
        await using var src = new FileStream(cfg.CleanUpdateRpfPath, FileMode.Open, FileAccess.Read, FileShare.Read, bufferSize, useAsync: true);
        await using var dst = new FileStream(dest, FileMode.Create, FileAccess.Write, FileShare.None, bufferSize, useAsync: true);
        await src.CopyToAsync(dst);
        Debug.WriteLine($"[admin.restore] copied {cfg.CleanUpdateRpfPath} -> {dest}");
        TryWipeInstallJournals();
        return true;
    }
#endif

