    private sealed record ResolvedVersion(
        Admin.R2UrlsLocal Urls,
        long PatchSizeBytes,
        string PatchSha256,
        string TargetGtaVersion,
        Dictionary<string, Admin.ReduxComponentInfo> Components,
        bool IsLegacy,
        Guid? VersionId,
        int? Slot,
        string? Label
    );

    private async Task<ResolvedVersion?> ResolveVersionAsync(string reduxId, Guid? versionId)
    {
        var item = await _catalog.GetByIdAsync(reduxId);
        if (item is null) return null;

        var versions = await _versionsRepo.ListByReduxAsync(reduxId);
        if (versions.Count > 0)
        {
            Admin.ReduxVersion? picked = null;
            if (versionId.HasValue)
                picked = versions.FirstOrDefault(v => v.Id == versionId.Value);
            if (picked is null)
                picked = versions.OrderBy(v => v.Slot).First();

            var urls = new Admin.R2UrlsLocal
            {
                Patch        = picked.PatchUrl,
                Components   = new Dictionary<string, string>(picked.ComponentUrls),
                Manifest     = picked.ManifestUrl,
                ComponentMap = picked.ComponentMapUrl,
                ContentInfo  = picked.ContentInfoUrl,
            };
            return new ResolvedVersion(
                urls,
                picked.PatchSizeBytes,
                picked.PatchSha256 ?? string.Empty,
                picked.TargetGtaVersion ?? string.Empty,
                picked.Components,
                IsLegacy:  false,
                VersionId: picked.Id,
                Slot:      picked.Slot,
                Label:     picked.Label);
        }

        return new ResolvedVersion(
            item.R2Urls ?? new Admin.R2UrlsLocal(),
            item.PatchSizeBytes,
            item.PatchSha256 ?? string.Empty,
            item.TargetGtaVersion,
            item.Components,
            IsLegacy:  true,
            VersionId: null,
            Slot:      null,
            Label:     null);
    }

    private sealed class ReduxAssetShaRow
    {
        public string? ManifestSha256     { get; set; }
        public string? ComponentMapSha256 { get; set; }
        public string? ContentInfoSha256  { get; set; }
    }

    private static bool _reduxAssetShaColumnsMissing;

    private readonly System.Collections.Concurrent.ConcurrentDictionary<Guid,
        (string Manifest, string ComponentMap, string ContentInfo)> _reduxAssetShaCache = new();

    private async Task<(string Manifest, string ComponentMap, string ContentInfo)>
        ReduxAssetShasAsync(Guid? versionId)
    {
        var empty = (string.Empty, string.Empty, string.Empty);
        if (_reduxAssetShaColumnsMissing) return empty;
        if (versionId is not Guid vid || vid == Guid.Empty) return empty;
        if (_reduxAssetShaCache.TryGetValue(vid, out var hit)) return hit;

        try
        {
            var rows = await _supabase.SelectAsync<ReduxAssetShaRow>(
                "redux_versions",
                $"select=manifest_sha256,component_map_sha256,content_info_sha256&id=eq.{vid}&limit=1");
            var r = rows.FirstOrDefault();
            var res = (r?.ManifestSha256 ?? string.Empty,
                       r?.ComponentMapSha256 ?? string.Empty,
                       r?.ContentInfoSha256 ?? string.Empty);
            _reduxAssetShaCache[vid] = res;
            return res;
        }
        catch (Exception ex)
        {
            _reduxAssetShaColumnsMissing = true;
            Debug.WriteLine($"[redux.integrity] колонок хешей манифеста нет ({ex.Message}) - манифесты идут без сверки");
            Services.DownloadLog.Write("integrity",
                "внимание: в базе нет колонок manifest_sha256 (миграция 0287) - манифесты редуксов ставятся БЕЗ сверки");
            return empty;
        }
    }

    private readonly System.Collections.Concurrent.ConcurrentDictionary<string, ReduxBundledFeaturesDto> _bundledFeaturesCache = new();

    public async Task<ReduxBundledFeaturesDto> ReduxBundledFeaturesAsync(string reduxId, string? versionId)
    {
        if (string.IsNullOrWhiteSpace(reduxId)) return new ReduxBundledFeaturesDto(false, false, false, false);
        var cacheKey = $"{reduxId}|{versionId}";
        if (_bundledFeaturesCache.TryGetValue(cacheKey, out var cached)) return cached;

        bool fastjoin = false, greenzone = false, zalazy = false, customMinimap = false;
        try
        {
            Guid? vid = Guid.TryParse(versionId, out var g) ? g : (Guid?)null;
            var resolved = await ResolveVersionAsync(reduxId, vid);
            if (resolved is not null)
            {
                try
                {
                    customMinimap = resolved.Components != null
                        && resolved.Components.TryGetValue("minimap", out var mm)
                        && mm is not null && mm.IsFound;
                }
                catch { }

                if (!string.IsNullOrWhiteSpace(resolved.Urls?.Manifest))
                {
                    var tmpDir = Path.Combine(Path.GetTempPath(), "MiamiGraphics", "manifests");
                    Directory.CreateDirectory(tmpDir);
                    var dest = Path.Combine(tmpDir, $"{reduxId}_{versionId ?? "legacy"}.json");
                    await DownloadViaMirrorAsync(resolved.Urls.Manifest!, dest, null, CancellationToken.None);
                    var json = await File.ReadAllTextAsync(dest);
                    var manifest = JsonSerializer.Deserialize<Core.Parser.DiffManifest>(json, ReduxJson);
                    foreach (var a in manifest?.Actions ?? new())
                    {
                        var p = (a.TargetPath ?? string.Empty).Replace('\\', '/').ToLowerInvariant();
                        if (p.Length == 0) continue;
                        if (p.Contains("playerswitch.meta")) fastjoin = true;
                        if (p.Contains("green_zone") || p.Contains("gz.rpf")) greenzone = true;
                        if (p.Contains("zalazu.rpf") || p.Contains("slivkimods.rpf") || p.Contains("mirz.rpf")) zalazy = true;
                    }
                }
            }
        }
        catch (Exception ex) { Debug.WriteLine($"[redux.bundledFeatures] {reduxId}: {ex.Message}"); }

        var dto = new ReduxBundledFeaturesDto(fastjoin, greenzone, zalazy, customMinimap);
        _bundledFeaturesCache[cacheKey] = dto;
        return dto;
    }

