    public Task ReduxDeferMinimapReapplyOnceAsync()
    {
        _deferMinimapReapplyOnce = true;
        try
        {
            var state = ReadInstallState();
            var draft = state?.CustomizationDraft;
            if (draft?.Minimap is { } prevMap)
            {
                var cleared = prevMap with
                {
                    Enabled             = false,
                    Tweaks              = null,
                    LibraryItemId       = null,
                    ImportedFromReduxId = null,
                    RangeRingsMeters    = null,
                };
                WriteInstallState(new InstallState
                {
                    ReduxId            = state!.ReduxId,
                    VersionId          = state.VersionId,
                    PostInstallSha256  = state.PostInstallSha256,
                    CustomizationDraft = draft with { Minimap = cleared },
                    CurrentArmorId     = state.CurrentArmorId,
                    CurrentArmorGlbUrl = state.CurrentArmorGlbUrl,
                    CurrentArmorKind   = state.CurrentArmorKind,
                });
            }
        }
        catch (Exception ex) { Debug.WriteLine($"[redux.minimap] defer clear failed (non-fatal): {ex.Message}"); }
        return Task.CompletedTask;
