    public async Task<InjectResultDto> ReduxApplyArmorSwapAsync(string donorReduxId, Guid? donorVersionId)
    {
        using var _mtx = await MiamiGraphics.Shell.Services.UpdateRpfMutex.AcquireAsync($"redux-armorswap:{donorReduxId}");
        var donorItem = await _catalog.GetByIdAsync(donorReduxId);
        var displayName = "Свап брони: " + (donorItem?.Name ?? donorReduxId);

        EmitInstallProgress(donorReduxId, displayName, "starting", 0, null);

        var gtaRoot = await GetGtaPathAsync();
        if (string.IsNullOrWhiteSpace(gtaRoot))
        {
            EmitInstallProgress(donorReduxId, displayName, "error", 0, "GTA не найдена.");
            return new InjectResultDto(false, "GTA не найдена. Укажи путь в Admin → Settings → Paths.", null);
        }
        var updateRpf = Path.Combine(gtaRoot, "update", "update.rpf");

        var resolved = await ResolveVersionAsync(donorReduxId, donorVersionId);
        if (resolved is null)
        {
            EmitInstallProgress(donorReduxId, displayName, "error", 0, "donor redux not found");
            return new InjectResultDto(false, $"Редукс-донор '{donorReduxId}' не найден в каталоге.", null);
        }
        if (resolved.Urls.Components is null
            || !resolved.Urls.Components.TryGetValue("armor", out var armorZipUrl)
            || string.IsNullOrWhiteSpace(armorZipUrl))
        {
            EmitInstallProgress(donorReduxId, displayName, "error", 0, "no armor component url");
            return new InjectResultDto(false,
                "У донора нет ссылки на components/armor.zip в R2. Перезалей с галкой R2.",
                null);
        }

        var rollbackPath = updateRpf + ".armorswap.preinstall";
        await MakeRollbackPointAsync(updateRpf, rollbackPath, donorReduxId, displayName,
            "starting", new ProgressBand(1, 4), "redux.armorswap");

        try
        {
            using var http = HttpClientFactory.CreateFragmenting(TimeSpan.FromMinutes(10));

            EmitInstallProgress(donorReduxId, displayName, "downloading", 5, null,
                detailMessage: Loc.T("progress.armor.downloading"));
            var donorRoot = await EnsureDonorCachedAsync(donorReduxId, "armor", http,
                (phase, pct, detail) => EmitInstallProgress(donorReduxId, displayName, phase, pct, null, detailMessage: detail),
                donorVersionId,
                progressBase: 5, progressSpan: 30);
            if (donorRoot is null)
            {
                EmitInstallProgress(donorReduxId, displayName, "error", 0, "Не удалось подготовить donor armor.");
                return new InjectResultDto(false, "Не удалось подготовить donor armor.", null);
            }

            EmitInstallProgress(donorReduxId, displayName, "applying_user_changes", 35, null,
                detailMessage: Loc.T("progress.armor.applying"));

            var svc = new Core.Services.ArmorStandaloneInstallService(_backupService);
            var r = await svc.InstallAsync(gtaRoot, donorRoot,
                NestedProgressEmit(donorReduxId, displayName, 35, 97, Loc.T("progress.armor.finishingInstall")),
                CancellationToken.None,
                restoreFromClean: false);

            if (!r.Success)
            {
                await TryRollbackAsync(updateRpf, rollbackPath);
                EmitInstallProgress(donorReduxId, displayName, "error", 0, r.ErrorMessage);
                return new InjectResultDto(false, r.ErrorMessage, r.WorkDir);
            }

            try
            {
                var postSha = await Task.Run(() => Services.FileShaCache.ComputeSha256Cached(updateRpf));
                var armorGlb = await ResolveArmorGlbUrlAsync(donorItem, donorReduxId, donorVersionId);
                var prevState = ReadInstallState();
                WriteInstallState(new InstallState
                {
                    ReduxId           = prevState?.ReduxId,
                    VersionId         = prevState?.VersionId,
                    PostInstallSha256 = postSha,
                    InstalledAt       = prevState?.InstalledAt ?? DateTime.UtcNow,

                    CustomizationDraft = prevState?.CustomizationDraft,
                    CurrentArmorId     = donorReduxId,
                    CurrentArmorName   = donorItem?.Name ?? donorReduxId,
                    CurrentArmorGlbUrl = armorGlb,
                    CurrentArmorKind   = "redux",
                });
            }
            catch (Exception ex) { Debug.WriteLine($"[redux.armorswap] state save FAILED: {ex.Message}"); }

            try { if (File.Exists(rollbackPath)) File.Delete(rollbackPath); } catch { }

            EmitInstallProgress(donorReduxId, displayName, "done", 100, null);
            return new InjectResultDto(true, null, r.WorkDir);
        }
        catch (Exception ex)
        {
            await TryRollbackAsync(updateRpf, rollbackPath);
            EmitInstallProgress(donorReduxId, displayName, "error", 0, ex.Message);
            return new InjectResultDto(false, ex.Message, null);
        }
    }

    public async Task<InjectResultDto> ReduxClearArmorAsync()
    {
        var displayName = "Очистка брони";

        EmitInstallProgress("__clear_armor__", displayName, "starting", 0, null);

        var gtaRoot = await GetGtaPathAsync();
        if (string.IsNullOrWhiteSpace(gtaRoot))
        {
            EmitInstallProgress("__clear_armor__", displayName, "error", 0, "GTA не найдена.");
            return new InjectResultDto(false, "GTA не найдена. Укажи путь в Admin → Settings → Paths.", null);
        }
        var updateRpf = Path.Combine(gtaRoot, "update", "update.rpf");

        using var _mtx = await MiamiGraphics.Shell.Services.UpdateRpfMutex.AcquireAsync("redux-armorclear");

        var rollbackPath = updateRpf + ".armorclear.preinstall";
        await MakeRollbackPointAsync(updateRpf, rollbackPath, "__clear_armor__", displayName,
            "starting", new ProgressBand(2, 22), "redux.armorclear");

        try
        {
            EmitInstallProgress("__clear_armor__", displayName, "applying_user_changes", 25, null,
                detailMessage: Loc.T("progress.armor.removing"));

            var svc = new Core.Services.ArmorStandaloneInstallService(_backupService);
            var r = await svc.InstallClearAsync(gtaRoot,
                NestedProgressEmit("__clear_armor__", displayName, 25, 97, Loc.T("progress.armor.finishingRemove")),
                CancellationToken.None);

            if (!r.Success)
            {
                await TryRollbackAsync(updateRpf, rollbackPath);
                EmitInstallProgress("__clear_armor__", displayName, "error", 0, r.ErrorMessage);
                return new InjectResultDto(false, r.ErrorMessage, r.WorkDir);
            }

            try
            {
                var postSha = await Task.Run(() => Services.FileShaCache.ComputeSha256Cached(updateRpf));
                var prevState = ReadInstallState();
                WriteInstallState(new InstallState
                {
                    ReduxId           = prevState?.ReduxId,
                    VersionId         = prevState?.VersionId,
                    PostInstallSha256 = postSha,
                    InstalledAt       = prevState?.InstalledAt ?? DateTime.UtcNow,

                    CustomizationDraft = prevState?.CustomizationDraft,
                    CurrentArmorId     = null,
                    CurrentArmorName   = null,
                    CurrentArmorGlbUrl = null,
                    CurrentArmorKind   = "none",
                });
            }
            catch (Exception ex) { Debug.WriteLine($"[redux.armorclear] state save FAILED: {ex.Message}"); }

            try { if (File.Exists(rollbackPath)) File.Delete(rollbackPath); } catch { }

            EmitInstallProgress("__clear_armor__", displayName, "done", 100, null);
            return new InjectResultDto(true, null, r.WorkDir);
        }
        catch (Exception ex)
        {
            await TryRollbackAsync(updateRpf, rollbackPath);
            EmitInstallProgress("__clear_armor__", displayName, "error", 0, ex.Message);
            return new InjectResultDto(false, ex.Message, null);
        }
    }

    public async Task<string?> ReadLocalFileBase64Async(string absolutePath)
    {
        const long MaxBytes = 32L * 1024 * 1024;
        try
        {
            if (string.IsNullOrWhiteSpace(absolutePath)) return null;
            if (!Path.IsPathRooted(absolutePath)) return null;
            if (!File.Exists(absolutePath)) return null;
            var info = new FileInfo(absolutePath);
            if (info.Length > MaxBytes) return null;
            var bytes = await File.ReadAllBytesAsync(absolutePath);
            return Convert.ToBase64String(bytes);
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[ReadLocalFileBase64] FAIL {absolutePath}: {ex.Message}");
            return null;
        }
    }

    public async Task<DlcArmorInspectionResultDto> InspectDlcRpfArmorAsync(string dlcRpfPath)
    {

        var localApp = Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData);
        var scratchRoot = Path.Combine(localApp, "MiamiGraphics", "dlc_inspect");
        try { Directory.CreateDirectory(scratchRoot); } catch {  }

        try
        {
            var cutoff = DateTime.UtcNow.AddHours(-1);
            foreach (var oldDir in Directory.EnumerateDirectories(scratchRoot))
            {
                try
                {
                    if (Directory.GetCreationTimeUtc(oldDir) < cutoff)
                        Directory.Delete(oldDir, recursive: true);
                }
                catch {  }
            }
        }
        catch {  }

        var sessionId = Guid.NewGuid().ToString("n").Substring(0, 12);
        var sessionDir = Path.Combine(scratchRoot, sessionId);
        Directory.CreateDirectory(sessionDir);

        var cts = new CancellationTokenSource();
        var oldCts = Interlocked.Exchange(ref _inspectionCts, cts);
        oldCts?.Dispose();

        Core.Services.ArmorInspectionResult coreResult;
        try
        {
            coreResult = await Task.Run(() =>
                Core.Services.DlcRpfArmorImporter.Inspect(dlcRpfPath, sessionDir, cts.Token), cts.Token);
        }
        catch (OperationCanceledException)
        {
            return new DlcArmorInspectionResultDto(
                DlcRpfPath:   dlcRpfPath ?? "",
                Candidates:   new List<DlcArmorCandidateDto>(),
                Warnings:     new List<string> { "Inspection cancelled by user." },
                ErrorMessage: null);
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[InspectDlcRpfArmor] FATAL: {ex}");
            return new DlcArmorInspectionResultDto(
                DlcRpfPath:   dlcRpfPath ?? "",
                Candidates:   new List<DlcArmorCandidateDto>(),
                Warnings:     new List<string>(),
                ErrorMessage: $"{ex.GetType().Name}: {ex.Message}");
        }
        finally
        {

            Interlocked.CompareExchange(ref _inspectionCts, null, cts);
            cts.Dispose();
        }

        var candidates = coreResult.Candidates.Select(c => new DlcArmorCandidateDto(
            YddInternalPath:      c.YddInternalPath ?? "",
            YddName:              c.YddName ?? "",
            DrawableInternalName: c.DrawableInternalName,
            ParseError:           c.ParseError,
            SamplerExpectations:  c.SamplerExpectations.Select(s =>
                new DlcArmorSamplerExpectationDto(s.SamplerName, s.ExpectedTextureName)).ToList(),
            CandidateYtds:        c.CandidateYtds.Select(y => new DlcArmorYtdDto(
                InternalPath:      y.InternalPath ?? "",
                FileName:          y.FileName ?? "",
                InnerTextureNames: y.InnerTextureNames ?? new List<string>(),
                ParseError:        y.ParseError)).ToList(),
            MissingExpectedDiffuses: c.MissingExpectedDiffuses ?? new List<string>(),
            HasNameMismatch:        c.HasNameMismatch,
            SuggestedRename:        c.SuggestedRename is null ? null
                : new DlcArmorRenameSuggestionDto(
                    YtdInternalPath: c.SuggestedRename.YtdInternalPath ?? "",
                    OldTextureName:  c.SuggestedRename.OldTextureName ?? "",
                    NewTextureName:  c.SuggestedRename.NewTextureName ?? ""),
            PreviewGlbUrl: string.IsNullOrEmpty(c.PreviewGlbPath) ? null
                : new Uri(c.PreviewGlbPath).AbsoluteUri
        )).ToList();

        return new DlcArmorInspectionResultDto(
            DlcRpfPath:   coreResult.DlcRpfPath ?? dlcRpfPath ?? "",
            Candidates:   candidates,
            Warnings:     coreResult.Warnings ?? new List<string>(),
            ErrorMessage: coreResult.ErrorMessage);
    }

    public Task<bool> InspectDlcRpfArmorCancelAsync()
    {

        var cts = Interlocked.Exchange(ref _inspectionCts, null);
        if (cts is null) return Task.FromResult(false);
        try { cts.Cancel(); } catch {  }
        return Task.FromResult(true);
    }

    public async Task<DlcArmorImportResultDto> ImportDlcRpfArmorAsync(DlcArmorImportRequestDto request)
    {
        if (request is null)
            return new DlcArmorImportResultDto(false, null, null, null, "request null");
        if (string.IsNullOrWhiteSpace(request.DlcRpfPath))
            return new DlcArmorImportResultDto(false, null, null, null, "dlcRpfPath required");
        if (string.IsNullOrWhiteSpace(request.YddInternalPath))
            return new DlcArmorImportResultDto(false, null, null, null, "yddInternalPath required");
        if (string.IsNullOrWhiteSpace(request.Name))
            return new DlcArmorImportResultDto(false, null, null, null, "name required");
        if (!File.Exists(request.DlcRpfPath))
            return new DlcArmorImportResultDto(false, null, null, null, $"file not found: {request.DlcRpfPath}");

        try
        {

            var slug = SlugifyForId(request.Name);
            var id = string.IsNullOrEmpty(slug)
                ? "armor_" + Guid.NewGuid().ToString("n").Substring(0, 8)
                : slug + "_" + Guid.NewGuid().ToString("n").Substring(0, 6);

            var localApp = Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData);
            var importDir = Path.Combine(localApp, "MiamiGraphics", "dlc_import", id);
            Directory.CreateDirectory(importDir);

            byte[]? yddBytes = null;
            string? yddSubDir = null;
            string? yddFileName = null;
            var pairedYtds = new List<(string FileName, byte[] Bytes)>();

            var folderMap = new Dictionary<string, IList<Core.Services.SyntheticArmorRpfBuilder.FileEntry>>(StringComparer.OrdinalIgnoreCase);
            string selectedFolder = "";

            await Task.Run(() =>
            {
                var primary = ScanArmorComponentFolders(request.DlcRpfPath, request.YddInternalPath);
                yddBytes      = primary.SelYddBytes;
                yddFileName   = primary.SelYddName;
                yddSubDir     = primary.SelSubDir;
                pairedYtds    = primary.SelPaired;
                selectedFolder = primary.SelFolder;
                foreach (var kv in primary.Folders) folderMap[kv.Key] = kv.Value;

                if (request.ExtraSources != null)
                {
                    foreach (var ex in request.ExtraSources)
                    {
                        if (ex == null || string.IsNullOrWhiteSpace(ex.DlcRpfPath)
                            || string.IsNullOrWhiteSpace(ex.YddInternalPath)) continue;
                        var cap = ScanArmorComponentFolders(ex.DlcRpfPath, ex.YddInternalPath);
                        foreach (var kv in cap.Folders)
                        {
                            if (folderMap.TryGetValue(kv.Key, out var existing))
                            {
                                var have = new HashSet<string>(
                                    existing.Select(e => e.FileName), StringComparer.OrdinalIgnoreCase);
                                foreach (var e in kv.Value)
                                    if (have.Add(e.FileName)) existing.Add(e);
                            }
                            else folderMap[kv.Key] = kv.Value;
                        }
                    }
                }
            });

            if (yddBytes == null || string.IsNullOrEmpty(yddFileName) || string.IsNullOrEmpty(yddSubDir))
                return new DlcArmorImportResultDto(false, null, null, null, "extraction failed (yddBytes null)");

            var fixApplied = false;
            string? fixSummary = null;
            if (request.ApplyAutoFix
                && !string.IsNullOrEmpty(request.RenameYtdFileName)
                && !string.IsNullOrEmpty(request.RenameOldTextureName)
                && !string.IsNullOrEmpty(request.RenameNewTextureName))
            {
                var matchIdx = pairedYtds.FindIndex(p =>
                    string.Equals(p.FileName, request.RenameYtdFileName, StringComparison.OrdinalIgnoreCase));
                if (matchIdx < 0)
                {
                    fixSummary = $"WARN: YTD '{request.RenameYtdFileName}' не найден среди парных - auto-fix пропущен.";
                }
                else
                {
                    var renamed = Core.Services.YtdRenamer.RenameInnerTexture(
                        pairedYtds[matchIdx].Bytes,
                        request.RenameOldTextureName,
                        request.RenameNewTextureName);
                    if (renamed.Success && renamed.OutputBytes != null)
                    {
                        pairedYtds[matchIdx] = (pairedYtds[matchIdx].FileName, renamed.OutputBytes);
                        fixApplied = true;
                        fixSummary = $"Renamed '{request.RenameOldTextureName}' → '{request.RenameNewTextureName}' " +
                                     $"в {request.RenameYtdFileName}.";
                    }
                    else
                    {
                        fixSummary = $"WARN: rename failed: {renamed.ErrorMessage}";
                    }
                }
            }

            var localArmorRpf = Path.Combine(importDir, "armor.rpf");

            if (fixApplied && !string.IsNullOrEmpty(request.RenameYtdFileName)
                && folderMap.TryGetValue(selectedFolder, out var selList))
            {
                var pf = pairedYtds.FirstOrDefault(p =>
                    string.Equals(p.FileName, request.RenameYtdFileName, StringComparison.OrdinalIgnoreCase));
                if (pf.Bytes != null)
                    foreach (var e in selList)
                        if (string.Equals(e.FileName, request.RenameYtdFileName, StringComparison.OrdinalIgnoreCase))
                            e.FileBytes = pf.Bytes;
            }

            if (folderMap.Count == 0)
            {
                var single = new List<Core.Services.SyntheticArmorRpfBuilder.FileEntry>
                {
                    new() { FileName = yddFileName!, FileBytes = yddBytes!, IsResource = true },
                };
                foreach (var (fname, bytes) in pairedYtds)
                    single.Add(new Core.Services.SyntheticArmorRpfBuilder.FileEntry
                    {
                        FileName = fname, FileBytes = bytes,
                        IsResource = Core.Services.SyntheticArmorRpfBuilder.IsRageResourceByExt(fname),
                    });
                folderMap[yddSubDir!] = single;
            }

            Debug.WriteLine($"[DlcImport] armor.rpf folders: {string.Join(", ", folderMap.Keys)} " +
                            $"(files: {folderMap.Values.Sum(v => v.Count)})");
            await Task.Run(() =>
                Core.Services.SyntheticArmorRpfBuilder.BuildMulti(localArmorRpf, folderMap));
            if (!File.Exists(localArmorRpf))
                return new DlcArmorImportResultDto(false, null, null, null, "synthetic armor.rpf was not created");

            var localGlb = Path.Combine(importDir, "armor.glb");
            try
            {
                var ytdBytesList = pairedYtds.Select(p => p.Bytes).ToList();
                await Core.Services.YddToGltfConverter.ConvertBytesAsync(
                    yddBytes!, ytdBytesList, localGlb);
            }
            catch (Exception ex)
            {
                Debug.WriteLine($"[DlcImport] GLB generation failed: {ex.Message}");

            }

            var armorRpfKey = $"armor_library/{id}/armor.rpf";
            var glbKey      = $"armor_library/{id}/armor.glb";

            string armorRpfUrl;
            try
            {
                armorRpfUrl = await _remoteStorage.UploadAsync(
                    localArmorRpf, armorRpfKey, progress: null, ct: CancellationToken.None);
            }
            catch (Exception ex)
            {
                return new DlcArmorImportResultDto(false, null, null, null,
                    $"R2 upload failed (armor.rpf): {ex.Message}");
            }

            string? glbUrl = null;
            if (File.Exists(localGlb))
            {
                try
                {
                    glbUrl = await _remoteStorage.UploadAsync(
                        localGlb, glbKey, progress: null, ct: CancellationToken.None);
                }
                catch (Exception ex)
                {
                    Debug.WriteLine($"[DlcImport] R2 upload of GLB failed: {ex.Message}");

                }
            }

            string? previewUrl = null;
            if (File.Exists(localGlb))
            {
                try
                {
                    var webpTmp = Path.Combine(Path.GetDirectoryName(localGlb)!, "preview.webp");
                    var rendered = await Core.Services.GlbToPngRenderer.RenderAsync(localGlb, webpTmp, 1024, 1024);
                    if (rendered && File.Exists(webpTmp))
                    {
                        var webpKey = $"armor_library/{id}/preview.webp";
                        previewUrl = await _remoteStorage.UploadAsync(
                            webpTmp, webpKey, progress: null, ct: CancellationToken.None);
                        Debug.WriteLine($"[DlcImport] preview.webp → {previewUrl}");
                        try { File.Delete(webpTmp); } catch {}
                    }
                    else
                    {
                        Debug.WriteLine("[DlcImport] preview render returned false - frontend will fall back to inline GLB");
                    }
                }
                catch (Exception ex)
                {
                    Debug.WriteLine($"[DlcImport] preview render/upload failed: {ex.Message} - proceeding without preview");
                }
            }

            const string canonicalInternalPath = "miamigraphics/miami_graphics_armor.rpf";

            var armorRpfSha = await Task.Run(() =>
                Services.VerifiedDownload.ComputeSha256(localArmorRpf));
            Debug.WriteLine($"[DlcImport] armor.rpf sha256={armorRpfSha}");

            var item = new Admin.ArmorLibraryItem
            {
                Id                   = id,
                Name                 = request.Name,
                Author               = request.Author ?? string.Empty,
                AuthorLink           = string.Empty,
                Description          = string.Empty,
                GlbUrl               = glbUrl ?? string.Empty,
                PreviewUrl           = previewUrl,
                ArmorRpfUrl          = armorRpfUrl,
                InternalPath         = canonicalInternalPath,
                UploadedBy           = string.Empty,
                UploadedAt           = DateTime.UtcNow,
                Status               = "published",
                IsVerified           = false,
                DownloadCount        = 0,
                ViewerPriority       = 0,
                SupportedServers     = new List<string> { "majestic" },
                ArmorRpfUrlMajestic  = armorRpfUrl,
                InternalPathMajestic = canonicalInternalPath,
                ArmorRpfSha256         = armorRpfSha,
                ArmorRpfSha256Majestic = armorRpfSha,
            };
            try
            {
                await ArmorLibraryRepo.UpsertAsync(item);
            }
            catch (Exception ex)
            {
                return new DlcArmorImportResultDto(false, null, null, null,
                    $"Supabase upsert failed: {ex.Message}");
            }

            return new DlcArmorImportResultDto(
                Success:     true,
                ArmorId:     id,
                ArmorRpfUrl: armorRpfUrl,
                GlbUrl:      glbUrl,
                ErrorMessage: fixSummary);
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[DlcImport] FATAL: {ex}");
            return new DlcArmorImportResultDto(false, null, null, null,
                $"{ex.GetType().Name}: {ex.Message}");
        }
    }

    private sealed class ArmorScan
    {
        public Dictionary<string, IList<Core.Services.SyntheticArmorRpfBuilder.FileEntry>> Folders
            = new(StringComparer.OrdinalIgnoreCase);
        public byte[]? SelYddBytes;
        public string? SelYddName;
        public string? SelSubDir;
        public List<(string FileName, byte[] Bytes)> SelPaired = new();
        public string SelFolder = "";
    }

    private static ArmorScan ScanArmorComponentFolders(string dlcRpfPath, string selectedYddPath)
    {
        var r = new ArmorScan();
        using var stream = File.Open(dlcRpfPath, FileMode.Open, FileAccess.Read, FileShare.Read);
        using var arc = RageLib.GTA5.ArchiveWrappers.RageArchiveWrapper7.Open(
            stream, Path.GetFileName(dlcRpfPath), true);

        var allYdds = new List<(string Path, byte[] Bytes)>();
        var allYtds = new List<(string Path, byte[] Bytes)>();
        CollectFilesEager(arc.Root, "", allYdds, allYtds);

        var yi = allYdds.FindIndex(c => string.Equals(c.Path, selectedYddPath, StringComparison.OrdinalIgnoreCase));
        if (yi < 0)
            throw new InvalidOperationException($"YDD '{selectedYddPath}' not found inside the RPF.");
        var ydd = allYdds[yi];
        r.SelYddBytes = ydd.Bytes;
        r.SelYddName = Path.GetFileName(ydd.Path);
        int slash = ydd.Path.LastIndexOf('/');
        string dirPart = slash < 0 ? "" : ydd.Path.Substring(0, slash);
        var dp = dirPart.Split(new[] { '/' }, StringSplitOptions.RemoveEmptyEntries);
        r.SelSubDir = dp.Length > 0 ? dp[dp.Length - 1] : "mp_f_freemode_01_mp_f_january2016";

        foreach (var yt in allYtds)
        {
            int s2 = yt.Path.LastIndexOf('/'); string d2 = s2 < 0 ? "" : yt.Path.Substring(0, s2);
            if (!string.Equals(d2, dirPart, StringComparison.OrdinalIgnoreCase)) continue;
            if (yt.Bytes == null || yt.Bytes.Length == 0) continue;
            r.SelPaired.Add((Path.GetFileName(yt.Path), yt.Bytes));
        }

        string comp = (r.SelYddName ?? "").Split('_')[0];
        static string FolderName(string p)
        {
            int s1 = p.LastIndexOf('/'); if (s1 < 0) return "";
            string d = p.Substring(0, s1); int s2 = d.LastIndexOf('/');
            return s2 < 0 ? d : d.Substring(s2 + 1);
        }
        static string FileNm(string p) { int s = p.LastIndexOf('/'); return s < 0 ? p : p.Substring(s + 1); }
        bool IsCompYdd(string p) =>
            !string.IsNullOrEmpty(comp)
            && FileNm(p).StartsWith(comp + "_", StringComparison.OrdinalIgnoreCase)
            && FileNm(p).EndsWith(".ydd", StringComparison.OrdinalIgnoreCase);

        r.SelFolder = FolderName(selectedYddPath);
        var compFolders = allYdds.Where(y => IsCompYdd(y.Path))
            .Select(y => FolderName(y.Path))
            .Where(f => !string.IsNullOrEmpty(f))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .ToList();
        foreach (var folder in compFolders)
        {
            var list = new List<Core.Services.SyntheticArmorRpfBuilder.FileEntry>();
            var fYdds = allYdds.Where(y => IsCompYdd(y.Path)
                && string.Equals(FolderName(y.Path), folder, StringComparison.OrdinalIgnoreCase)).ToList();
            var rep = fYdds.FirstOrDefault(y =>
                string.Equals(y.Path, selectedYddPath, StringComparison.OrdinalIgnoreCase));
            if (rep.Bytes == null) rep = fYdds[0];
            list.Add(new Core.Services.SyntheticArmorRpfBuilder.FileEntry
            {
                FileName = FileNm(rep.Path), FileBytes = rep.Bytes, IsResource = true,
            });
            foreach (var yt in allYtds.Where(y =>
                string.Equals(FolderName(y.Path), folder, StringComparison.OrdinalIgnoreCase)))
            {
                if (yt.Bytes == null || yt.Bytes.Length == 0) continue;
                list.Add(new Core.Services.SyntheticArmorRpfBuilder.FileEntry
                {
                    FileName = FileNm(yt.Path), FileBytes = yt.Bytes,
                    IsResource = Core.Services.SyntheticArmorRpfBuilder.IsRageResourceByExt(FileNm(yt.Path)),
                });
            }
            r.Folders[folder] = list;
        }
        return r;
    }

    private static void CollectFilesEager(
        RageLib.Archives.IArchiveDirectory dir, string prefix,
        List<(string Path, byte[] Bytes)> ydds,
        List<(string Path, byte[] Bytes)> ytds)
    {
        foreach (var f in dir.GetFiles())
        {
            string childPath = string.IsNullOrEmpty(prefix) ? f.Name : prefix + "/" + f.Name;
            if (f.Name.EndsWith(".ydd", StringComparison.OrdinalIgnoreCase))
            {
                var b = TryExportFileBytes(f);
                if (b != null) ydds.Add((childPath, b));
            }
            else if (f.Name.EndsWith(".ytd", StringComparison.OrdinalIgnoreCase))
            {
                var b = TryExportFileBytes(f);
                if (b != null) ytds.Add((childPath, b));
            }
            if (f.Name.EndsWith(".rpf", StringComparison.OrdinalIgnoreCase)
                && f is RageLib.Archives.IArchiveBinaryFile binRpf)
            {
                try
                {
                    using var s = binRpf.GetStream();
                    using var nested = RageLib.GTA5.ArchiveWrappers.RageArchiveWrapper7.Open(
                        s, binRpf.Name, true);
                    CollectFilesEager(nested.Root, childPath, ydds, ytds);
                }
                catch {  }
            }
        }
        foreach (var sub in dir.GetDirectories())
        {
            string subPath = string.IsNullOrEmpty(prefix) ? sub.Name : prefix + "/" + sub.Name;
            CollectFilesEager(sub, subPath, ydds, ytds);
        }
    }

    private static byte[]? TryExportFileBytes(RageLib.Archives.IArchiveFile f)
    {
        try
        {
            using var ms = new MemoryStream();
            f.Export(ms);
            return ms.ToArray();
        }
        catch { return null; }
    }

    private static string SlugifyForId(string name)
    {
        if (string.IsNullOrWhiteSpace(name)) return "";
        var sb = new System.Text.StringBuilder();
        foreach (var c in name.ToLowerInvariant())
        {
            if (c >= 'a' && c <= 'z') sb.Append(c);
            else if (c >= '0' && c <= '9') sb.Append(c);
            else if (c == ' ' || c == '_' || c == '-') sb.Append('_');
        }
        var slug = sb.ToString().Trim('_');
        if (slug.Length > 32) slug = slug.Substring(0, 32);
        return slug;
    }

    public async Task<List<ArmorLibraryItemDto>> ArmorLibraryListAllAsync()
    {
        try
        {

            var rows = await ArmorLibraryRepo.ListAsync(null);
            return rows.Select(MapArmorLibraryItem).ToList();
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[ArmorLibraryListAll] FAIL: {ex.Message}");
            return new List<ArmorLibraryItemDto>();
        }
    }

    public async Task<bool> ArmorLibrarySetVisibilityAsync(string armorLibraryId, bool visible)
    {
        if (string.IsNullOrWhiteSpace(armorLibraryId)) return false;
        try
        {
            var row = await ArmorLibraryRepo.GetByIdAsync(armorLibraryId);
            if (row is null) return false;
            row.Status = visible ? "published" : "draft";
            await ArmorLibraryRepo.UpsertAsync(row);
            return true;
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[ArmorLibrarySetVisibility] FAIL: {ex.Message}");
            return false;
        }
    }

    public async Task<bool> ArmorLibrarySetSupportedServersAsync(string armorLibraryId, List<string> servers)
    {
        if (string.IsNullOrWhiteSpace(armorLibraryId)) return false;
        if (servers is null || servers.Count == 0) return false;
        try
        {
            var row = await ArmorLibraryRepo.GetByIdAsync(armorLibraryId);
            if (row is null) return false;

            var clean = servers
                .Where(s => !string.IsNullOrWhiteSpace(s))
                .Select(s => s.Trim().ToLowerInvariant())
                .Distinct()
                .ToList();
            if (clean.Count == 0) return false;
            row.SupportedServers = clean;
            await ArmorLibraryRepo.UpsertAsync(row);
            return true;
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[ArmorLibrarySetSupportedServers] FAIL: {ex.Message}");
            return false;
        }
    }

    public async Task<List<string>> ArmorLibraryRenderVariantsAsync(string armorLibraryId)
    {
        if (string.IsNullOrWhiteSpace(armorLibraryId)) return new List<string>();
        var views = new List<string> { "front", "fl", "fr", "left", "right", "back" };

        var row = await ArmorLibraryRepo.GetByIdAsync(armorLibraryId);
        if (row is null || string.IsNullOrWhiteSpace(row.GlbUrl))
        {
            Debug.WriteLine($"[ArmorRenderVariants] no row/GLB for {armorLibraryId}");
            return new List<string>();
        }

        var workDir = Path.Combine(Path.GetTempPath(),
            "armor_variants_" + Guid.NewGuid().ToString("N").Substring(0, 8));
        Directory.CreateDirectory(workDir);
        try
        {
            var localGlb = Path.Combine(workDir, "armor.glb");
            using (var http = new System.Net.Http.HttpClient { Timeout = TimeSpan.FromSeconds(60) })
                await DownloadFileAsync(http, row.GlbUrl, localGlb);

            if (!File.Exists(localGlb))
            {
                Debug.WriteLine($"[ArmorRenderVariants] GLB download failed: {row.GlbUrl}");
                return new List<string>();
            }

            var outDir = Path.Combine(workDir, "out");
            var files = await Core.Services.GlbToPngRenderer.RenderVariantsAsync(localGlb, outDir, views, 1024, 1024);
            if (files.Count == 0)
            {
                Debug.WriteLine("[ArmorRenderVariants] renderer produced nothing");
                return new List<string>();
            }

            var urls = new List<string>();
            foreach (var f in files)
            {
                var view = Path.GetFileNameWithoutExtension(f);
                var key  = $"armor_library/{armorLibraryId}/variants/{view}.webp";
                try
                {
                    var url = await _remoteStorage.UploadAsync(f, key, progress: null, ct: CancellationToken.None);
                    if (!string.IsNullOrWhiteSpace(url)) urls.Add(url);
                }
                catch (Exception ex)
                {
                    Debug.WriteLine($"[ArmorRenderVariants] upload {key} failed: {ex.Message}");
                }
            }

            if (urls.Count == 0) return new List<string>();

            row.PreviewVariants = urls;
            if (string.IsNullOrWhiteSpace(row.PreviewUrl)) row.PreviewUrl = urls[0];
            await ArmorLibraryRepo.UpsertAsync(row);
            return urls;
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[ArmorRenderVariants] FAIL: {ex.Message}");
            return new List<string>();
        }
        finally
        {
            try { Directory.Delete(workDir, recursive: true); } catch {}
        }
    }

    public async Task<bool> ArmorLibrarySetPreviewAsync(string armorLibraryId, string previewUrl)
    {
        if (string.IsNullOrWhiteSpace(armorLibraryId) || string.IsNullOrWhiteSpace(previewUrl))
