            return false;
        }
    }

    public async Task<string?> ReduxArmorRenderPreviewAsync(string reduxId)
    {
        if (string.IsNullOrWhiteSpace(reduxId)) return null;

        var item = await _catalog.GetByIdAsync(reduxId);
        if (item is null)
        {
            Debug.WriteLine($"[reduxArmor.render] redux not found: {reduxId}");
            return null;
        }
        if (item.Components is null || !item.Components.TryGetValue("armor", out var ac) || !ac.IsFound)
        {
            Debug.WriteLine($"[reduxArmor.render] no armor component on '{reduxId}'");
            return null;
        }

        var glbUrl = await ResolveArmorGlbUrlAsync(item, reduxId, versionId: null);
        if (string.IsNullOrWhiteSpace(glbUrl))
        {
            Debug.WriteLine($"[reduxArmor.render] armor.glb URL not resolved for '{reduxId}'");
            return null;
        }

        var workDir = Path.Combine(Path.GetTempPath(),
            "reduxarmor_" + Guid.NewGuid().ToString("N").Substring(0, 8));
        Directory.CreateDirectory(workDir);
        try
        {
            var localGlb = Path.Combine(workDir, "armor.glb");
            using (var http = new System.Net.Http.HttpClient { Timeout = TimeSpan.FromSeconds(60) })
                await DownloadFileAsync(http, glbUrl, localGlb);
            if (!File.Exists(localGlb))
            {
                Debug.WriteLine($"[reduxArmor.render] GLB download failed: {glbUrl}");
                return null;
            }

            var localPng = Path.Combine(workDir, "preview.webp");
            var ok = await Core.Services.GlbToPngRenderer.RenderAsync(localGlb, localPng, 1024, 1024);
            if (!ok || !File.Exists(localPng))
            {
                Debug.WriteLine($"[reduxArmor.render] render failed for '{reduxId}'");
                return null;
            }

            var key = $"redux_armor_previews/{reduxId}/preview.webp";
            string? url;
            try
            {
                url = await _remoteStorage.UploadAsync(localPng, key, progress: null, ct: CancellationToken.None);
            }
            catch (Exception ex)
            {
                Debug.WriteLine($"[reduxArmor.render] R2 upload failed: {ex.Message}");
                return null;
            }
            if (string.IsNullOrWhiteSpace(url)) return null;

            try
            {
                await _catalog.UpdateAsync(reduxId, r =>
                {
                    r.ComponentScreenshots ??= new Dictionary<string, string>();
                    r.ComponentScreenshots["armor"] = url;
                });
            }
            catch (Exception ex)
            {
                Debug.WriteLine($"[reduxArmor.render] catalog update failed: {ex.Message}");
                return null;
            }

            Debug.WriteLine($"[reduxArmor.render] '{reduxId}' -> {url}");
            return url;
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[reduxArmor.render] FAIL: {ex.Message}");
            return null;
        }
        finally
        {
            try { Directory.Delete(workDir, recursive: true); } catch {}
        }
    }

    public async Task<(int total, int rendered)> ReduxArmorBackfillPreviewsAsync()
    {
        var rows = await _catalog.ListAsync(null);
        var candidates = rows
            .Where(r => r.Components != null
                     && r.Components.TryGetValue("armor", out var ac) && ac.IsFound)
            .Where(r => r.ComponentScreenshots == null
                     || !r.ComponentScreenshots.TryGetValue("armor", out var existing)
                     || string.IsNullOrWhiteSpace(existing))
            .ToList();

        Debug.WriteLine($"[reduxArmor.backfill] candidates: {candidates.Count}");
        int rendered = 0;
        foreach (var r in candidates)
        {
            var url = await ReduxArmorRenderPreviewAsync(r.Id);
            if (!string.IsNullOrWhiteSpace(url)) rendered++;
        }
        Debug.WriteLine($"[reduxArmor.backfill] done: {rendered}/{candidates.Count}");
        return (candidates.Count, rendered);
    }

    public async Task<List<string>> ReduxArmorRenderVariantsAsync(string reduxId)
    {
        if (string.IsNullOrWhiteSpace(reduxId)) return new List<string>();
        var views = new List<string> { "front", "fl", "fr", "left", "right", "back" };

        var item = await _catalog.GetByIdAsync(reduxId);
        if (item is null
            || item.Components is null
            || !item.Components.TryGetValue("armor", out var ac) || !ac.IsFound)
            throw new InvalidOperationException("У этого редукса нет компонента брони.");

        var glbUrl = await ResolveArmorGlbUrlAsync(item, reduxId, versionId: null);
        if (string.IsNullOrWhiteSpace(glbUrl))
            throw new InvalidOperationException(
                "Не найден armor.glb в R2 у этого редукса. Перезалейте редукс с включённой загрузкой в R2 - без 3D-модели превью не сгенерировать.");

        if (!Core.Services.GlbToPngRenderer.IsAvailable())
            throw new InvalidOperationException(
                "Рендерер не установлен на этой машине. Откройте Admin → Настройки → «Рендер превью ганов» → «Установить» (скачает Node + Chromium), затем повторите.");

        var workDir = Path.Combine(Path.GetTempPath(),
            "reduxarmorvar_" + Guid.NewGuid().ToString("N").Substring(0, 8));
        Directory.CreateDirectory(workDir);
        try
        {
            var localGlb = Path.Combine(workDir, "armor.glb");
            using (var http = new System.Net.Http.HttpClient { Timeout = TimeSpan.FromSeconds(60) })
                await DownloadFileAsync(http, glbUrl, localGlb);
            if (!File.Exists(localGlb) || new FileInfo(localGlb).Length == 0)
                throw new InvalidOperationException($"Не удалось скачать armor.glb из R2 (битая ссылка или нет доступа): {glbUrl}");

            var outDir = Path.Combine(workDir, "out");
            var files = await Core.Services.GlbToPngRenderer.RenderVariantsAsync(localGlb, outDir, views, 1024, 1024);
            if (files.Count == 0)
                throw new InvalidOperationException("Рендерер не смог отрисовать эту модель (возможно, GLB повреждён или Chromium не запустился).");

            var urls = new List<string>();
            foreach (var f in files)
            {
                var view = Path.GetFileNameWithoutExtension(f);
                var key  = $"redux_armor_previews/{reduxId}/variants/{view}.webp";
                try
                {
                    var url = await _remoteStorage.UploadAsync(f, key, progress: null, ct: CancellationToken.None);
                    if (!string.IsNullOrWhiteSpace(url)) urls.Add(url);
                }
                catch (Exception ex) { Debug.WriteLine($"[reduxArmorVariants] upload {key} fail: {ex.Message}"); }
            }
            if (urls.Count == 0)
                throw new InvalidOperationException("Ракурсы отрисованы, но не загрузились в R2. Проверьте ключи R2 в Admin → Настройки.");

            var hasPreview = item.ComponentScreenshots != null
                && item.ComponentScreenshots.TryGetValue("armor", out var existing)
                && !string.IsNullOrWhiteSpace(existing);
            if (!hasPreview)
            {
                var front = urls.FirstOrDefault(u => u.EndsWith("/front.webp")) ?? urls[0];
                try { await _catalog.UpdateAsync(reduxId, r => { r.ComponentScreenshots ??= new(); r.ComponentScreenshots["armor"] = front; }); }
                catch (Exception ex) { Debug.WriteLine($"[reduxArmorVariants] default set fail: {ex.Message}"); }
            }
            return urls;
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[reduxArmorVariants] FAIL: {ex.Message}");
            throw;
        }
        finally
        {
            try { Directory.Delete(workDir, recursive: true); } catch {}
        }
    }

    public async Task<List<string>> ReduxArmorVariantUrlsAsync(string reduxId)
    {
        if (string.IsNullOrWhiteSpace(reduxId)) return new List<string>();
        try
        {
            var prefix = $"redux_armor_previews/{reduxId}/variants/";
            var keys = await _remoteStorage.ListKeysAsync(prefix, CancellationToken.None);
            if (keys is null || keys.Count == 0) return new List<string>();
            var baseUrl = ((await _adminConfig.GetAsync()).R2PublicUrl ?? string.Empty).TrimEnd('/');
            var order = new[] { "front", "fl", "fr", "left", "right", "back" };
            return keys
                .Where(k => k.EndsWith(".webp"))
                .OrderBy(k => { var i = Array.IndexOf(order, Path.GetFileNameWithoutExtension(k)); return i < 0 ? 99 : i; })
                .Select(k => $"{baseUrl}/{k}")
                .ToList();
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[reduxArmorVariantUrls] FAIL: {ex.Message}");
            return new List<string>();
        }
    }

