    public async Task<bool> ArmorLibraryDeleteAsync(string armorLibraryId)
    {
        if (string.IsNullOrWhiteSpace(armorLibraryId))
            throw new InvalidOperationException("armorLibraryId required");

        Debug.WriteLine($"[admin.armorLibrary.delete] id='{armorLibraryId}'");
        var row = await ArmorLibraryRepo.GetByIdAsync(armorLibraryId);
        if (row is null)
        {
            Debug.WriteLine("[admin.armorLibrary.delete] not found - nothing to do");
            return true;
        }

        var baseKey = $"armor_library/{armorLibraryId}/";
        try
        {
            var deleted = await _remoteStorage.DeletePrefixAsync(baseKey, CancellationToken.None);
            Debug.WriteLine($"[admin.armorLibrary.delete] r2 sweep removed {deleted} object(s)");
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[admin.armorLibrary.delete] R2 cleanup FAILED: {ex.Message}");
            throw new InvalidOperationException(
                $"Не удалось удалить файлы брони '{armorLibraryId}' с R2: {ex.Message}. " +
                $"Запись в каталоге сохранена, попробуй ещё раз.", ex);
        }

        await ArmorLibraryRepo.DeleteAsync(armorLibraryId);
        Debug.WriteLine($"[admin.armorLibrary.delete] catalog row removed for '{armorLibraryId}'");
        return true;
    }

