    public Task<InjectResultDto> ArmorLibraryInstallAsync(string armorLibraryId)
        => ArmorLibraryInstallAsync(armorLibraryId, overlayMode: false, force: false);

    public Task<InjectResultDto> ArmorLibraryInstallAsync(string armorLibraryId, bool overlayMode)
        => ArmorLibraryInstallAsync(armorLibraryId, overlayMode, force: false);

    public Task<InjectResultDto> ArmorLibraryInstallAsync(string armorLibraryId, bool overlayMode, bool force)
        => ArmorLibraryInstallAsync(armorLibraryId, overlayMode, force, alreadyLocked: false);

    public async Task<InjectResultDto> ArmorLibraryInstallAsync(string armorLibraryId, bool overlayMode, bool force, bool alreadyLocked, bool confirmWipe = false)
    {
        if (string.IsNullOrWhiteSpace(armorLibraryId))
            return new InjectResultDto(false, "armorLibraryId required", null);
        IDisposable? _cancelReg = null;
        IDisposable? _mtx;
        if (alreadyLocked)
        {
            _mtx = null;
        }
        else
        {
            var (token, reg) = BeginCancellableOp($"redux:{armorLibraryId}");
            _cancelReg = reg;
            _mtx = await MiamiGraphics.Shell.Services.UpdateRpfMutex.AcquireAsync($"armor-library-install:{armorLibraryId}", token);
        }
        using var _cancelScope = _cancelReg;
        using var _mtxScope = _mtx;

        var row = await ArmorLibraryRepo.GetByIdAsync(armorLibraryId);
        if (row is null)
            return new InjectResultDto(false, $"Armor '{armorLibraryId}' not found in catalog.", null);

        var displayName = "Броня из каталога: " + (row.Name ?? armorLibraryId);
        EmitInstallProgress(armorLibraryId, displayName, "starting", 0, null);

        var gtaRoot = await GetGtaPathAsync();
        if (string.IsNullOrWhiteSpace(gtaRoot))
        {
            EmitInstallProgress(armorLibraryId, displayName, "error", 0, "GTA не найдена.");
            return new InjectResultDto(false, "GTA не найдена. Укажи путь в Admin → Settings → Paths.", null);
        }
        var updateRpf = Path.Combine(gtaRoot, "update", "update.rpf");

        if (!force && File.Exists(updateRpf))
        {
            try
            {
                var (currentSha, state, matchesLast, matchesClean) =
                    await PreflightUpdateRpfShaAsync(updateRpf, gtaRoot, armorLibraryId, displayName);
                if (!matchesLast && !matchesClean)
                {
                    if (GetLocalCleanRpfPath() is null
                        && !await TryFetchCleanViaBackupAsync(gtaRoot, armorLibraryId, displayName))
                    {
                        const string noBackup = "Нет бэкапа чистого update.rpf - сделай бэкап в стартовом окне, чтобы поставить броню.";
                        EmitInstallProgress(armorLibraryId, displayName, "error", 0, noBackup);
                        return new InjectResultDto(false, noBackup, null);
                    }
                    if (!confirmWipe)
                    {
                        Debug.WriteLine("[ArmorLibrary.install] preflight: foreign/dirty update.rpf - awaiting user confirm to reset to clean");
                        EmitInstallProgress(armorLibraryId, displayName, "error", 0, DirtyFilesCardMessage);
                        return new InjectResultDto(false, ERROR_DIRTY_FILES, null);
                    }
                    Debug.WriteLine("[ArmorLibrary.install] preflight: user-confirmed reset to clean before armor install");
                    try { await _backupService.RestoreFromCleanAsync(gtaRoot, CancellationToken.None); }
                    catch (Exception rex) { Debug.WriteLine($"[ArmorLibrary.install] restore-clean failed: {rex.Message}"); }
                }
            }
            catch (Exception ex) { Debug.WriteLine($"[ArmorLibrary.install] preflight skipped: {ex.Message}"); }
        }

        if (string.IsNullOrWhiteSpace(row.ArmorRpfUrl))
        {
            EmitInstallProgress(armorLibraryId, displayName, "error", 0, "В каталоге нет ссылки на armor.rpf.");
            return new InjectResultDto(false, "В каталоге нет ссылки на armor.rpf.", null);
        }

        var localApp = Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData);
        var donorRoot = Path.Combine(localApp, "MiamiGraphics", "armor_library_donor",
                                     armorLibraryId + "_" + Guid.NewGuid().ToString("n").Substring(0, 6));
        Directory.CreateDirectory(donorRoot);
        var componentArmorDir = Path.Combine(donorRoot, "components", "armor",
                                             "miamigraphics");
        Directory.CreateDirectory(componentArmorDir);
        var localArmorRpf = Path.Combine(componentArmorDir, "miami_graphics_armor.rpf");

        try
        {
            var armorCacheDir = MiamiGraphics.Shell.Services.ModCacheSettings.Dir("armor_library");
            var urlHash = global::System.Convert.ToHexString(
                global::System.Security.Cryptography.SHA256.HashData(
                    global::System.Text.Encoding.UTF8.GetBytes(row.ArmorRpfUrl ?? string.Empty)))
                .Substring(0, 12);
            var armorCachePath = Path.Combine(armorCacheDir, $"{armorLibraryId}__{urlHash}.rpf");

            var armorSha = row.ArmorRpfSha256;
            bool cacheUsable = MiamiGraphics.Shell.Services.ModCacheSettings.ReuseEnabled
                && File.Exists(armorCachePath)
                && (string.IsNullOrWhiteSpace(armorSha)
                    || Services.VerifiedDownload.CachedFileOk(armorCachePath, armorSha, row.Name ?? armorLibraryId));

            if (cacheUsable)
            {
                EmitInstallProgress(armorLibraryId, displayName, "downloading", 30, null,
                    detailMessage: Loc.T("progress.armor.cacheHit"));
                File.Copy(armorCachePath, localArmorRpf, overwrite: true);
                Core.System.DataQuota.Touch(armorCachePath);
                Debug.WriteLine($"[armor.library] cache hit at {armorCachePath}");
            }
            else
            {
                EmitInstallProgress(armorLibraryId, displayName, "downloading", 10, null,
                    detailMessage: Loc.T("progress.armor.downloading"));

                await Services.VerifiedDownload.FetchAsync(row.ArmorRpfUrl ?? string.Empty, localArmorRpf,
                    armorSha, row.Name ?? armorLibraryId,
                    bytesProgress: (recv, total) => EmitInstallProgress(armorLibraryId, displayName, "downloading",
                        total > 0 ? (int)(10 + recv * 15.0 / total) : 10, null,
                        detailMessage: total > 0
                            ? DownloadCounterText(recv, total)
                            : Loc.T("progress.armor.downloading")),
                    hashProgress: (done, total) => EmitInstallProgress(armorLibraryId, displayName, "downloading",
                        26, null, detailMessage: Loc.T("progress.common.verifyingMb",
                            ("done", done / 1024 / 1024), ("total", Math.Max(1, total / 1024 / 1024)))),
                    referenceRequired: false,
                    ct: CancellationToken.None);
                try { File.Copy(localArmorRpf, armorCachePath, overwrite: true); }
                catch (Exception cex) { Debug.WriteLine($"[armor.library] cache save failed: {cex.Message}"); }
            }

            var donorMap = new Core.Parser.ResolvedComponentMap();
            donorMap.Components["armor"] = new Core.Parser.ComponentInfo
            {
                IsFound       = true,
                SourceRpf     = "miamigraphics/miami_graphics_armor.rpf",
                InternalPaths = new List<string> { "miamigraphics/miami_graphics_armor.rpf" },
                Flags         = new List<string> { "transferable", "clearable" },
            };
            File.WriteAllText(
                Path.Combine(donorRoot, "component_map.json"),
                System.Text.Json.JsonSerializer.Serialize(donorMap,
                    new System.Text.Json.JsonSerializerOptions { WriteIndented = true }));

            var rollbackPath = updateRpf + ".preinstall";
            await MakeRollbackPointAsync(updateRpf, rollbackPath, armorLibraryId, displayName,
                "applying_user_changes", new ProgressBand(26, 34), "ArmorLibrary.install");

            EmitInstallProgress(armorLibraryId, displayName, "applying_user_changes", 35, null,
                detailMessage: Loc.T("progress.armor.applying"));
            var svc = new Core.Services.ArmorStandaloneInstallService(_backupService);

            var r = await svc.InstallAsync(gtaRoot, donorRoot,
                NestedProgressEmit(armorLibraryId, displayName, 35, 97, Loc.T("progress.armor.finishingInstall")),
                CancellationToken.None,
                restoreFromClean: !overlayMode);

            if (!r.Success)
            {
                await TryRollbackAsync(updateRpf, rollbackPath);
                EmitInstallProgress(armorLibraryId, displayName, "error", 0, r.ErrorMessage);
                return new InjectResultDto(false, r.ErrorMessage, r.WorkDir);
            }

            try
            {
                var postSha = await Task.Run(() => Services.FileShaCache.ComputeSha256Cached(updateRpf));

                var prior = overlayMode ? ReadInstallState() : null;
                WriteInstallState(new InstallState
                {
                    ReduxId           = prior?.ReduxId,
                    VersionId         = prior?.VersionId,
                    PostInstallSha256 = postSha,
                    InstalledAt       = DateTime.UtcNow,

                    CustomizationDraft = prior?.CustomizationDraft,
                    CurrentArmorId     = armorLibraryId,
                    CurrentArmorName   = row.Name ?? armorLibraryId,
                    CurrentArmorGlbUrl = row.GlbUrl,
                    CurrentArmorKind   = "library",
                });
            }
            catch (Exception ex) { Debug.WriteLine($"[ArmorLibrary.install] state save FAILED: {ex.Message}"); }

            try { if (File.Exists(rollbackPath)) File.Delete(rollbackPath); } catch { }

            try { await ArmorLibraryRepo.IncrementDownloadsAsync(armorLibraryId); } catch { }

            EmitInstallProgress(armorLibraryId, displayName, "done", 100, null);
            return new InjectResultDto(true, null, r.WorkDir);
        }
        catch (Exception ex)
        {
            EmitInstallProgress(armorLibraryId, displayName, "error", 0, ex.Message);
            return new InjectResultDto(false, ex.Message, null);
        }
        finally
        {

            try { if (Directory.Exists(donorRoot)) Directory.Delete(donorRoot, recursive: true); } catch { }
        }
    }

    public Task<InjectResultDto> ArmorInstallStandaloneAsync(string reduxId, Guid? versionId)
        => ArmorInstallStandaloneAsync(reduxId, versionId, force: false);

    public async Task<InjectResultDto> ArmorInstallStandaloneAsync(string reduxId, Guid? versionId, bool force)
        => await ArmorInstallStandaloneAsync(reduxId, versionId, force, confirmWipe: false);

    public async Task<InjectResultDto> ArmorInstallStandaloneAsync(string reduxId, Guid? versionId, bool force, bool confirmWipe)
    {
        var (ct, _cancelReg) = BeginCancellableOp($"redux:{reduxId}");
        using var _cs = _cancelReg;
        using var _mtx = await MiamiGraphics.Shell.Services.UpdateRpfMutex.AcquireAsync($"armor-standalone:{reduxId}", ct);
        var item = await _catalog.GetByIdAsync(reduxId);

        var displayName = "Броня из редукса: " + (item?.Name ?? reduxId);

        EmitInstallProgress(reduxId, displayName, "starting", 0, null);

        var gtaRoot = await GetGtaPathAsync();
        if (string.IsNullOrWhiteSpace(gtaRoot))
        {
            EmitInstallProgress(reduxId, displayName, "error", 0, "GTA не найдена.");
            return new InjectResultDto(false, "GTA не найдена. Укажи путь в Admin → Settings → Paths.", null);
        }
        var updateRpf = Path.Combine(gtaRoot, "update", "update.rpf");

        if (!force && File.Exists(updateRpf))
        {
            try
            {
                var (currentSha, state, matchesLast, matchesClean) =
                    await PreflightUpdateRpfShaAsync(updateRpf, gtaRoot, reduxId, displayName);
                Debug.WriteLine($"[armor.install.standalone] preflight: current={currentSha[..16]} matchesLast={matchesLast} matchesClean={matchesClean} firstInstall={state is null}");
                if (!matchesLast && !matchesClean)
                {
                    if (GetLocalCleanRpfPath() is null
                        && !await TryFetchCleanViaBackupAsync(gtaRoot, reduxId, displayName))
                    {
                        const string noBackup = "Нет бэкапа чистого update.rpf - сделай бэкап в стартовом окне, чтобы поставить броню.";
                        EmitInstallProgress(reduxId, displayName, "error", 0, noBackup);
                        return new InjectResultDto(false, noBackup, null);
                    }
                    if (!confirmWipe)
                    {
                        Debug.WriteLine("[armor.install.standalone] preflight: foreign/dirty update.rpf - awaiting user confirm to reset to clean");
                        EmitInstallProgress(reduxId, displayName, "error", 0, DirtyFilesCardMessage);
                        return new InjectResultDto(false, ERROR_DIRTY_FILES, null);
                    }
                    Debug.WriteLine("[armor.install.standalone] preflight: user-confirmed reset to clean");
                    try { await _backupService.RestoreFromCleanAsync(gtaRoot, CancellationToken.None); }
                    catch (Exception rex) { Debug.WriteLine($"[armor.install.standalone] restore-clean failed: {rex.Message}"); }
                }
            }
            catch (Exception ex) { Debug.WriteLine($"[armor.install.standalone] preflight skipped: {ex.Message}"); }
        }

        var resolved = await ResolveVersionAsync(reduxId, versionId);
        if (resolved is null)
        {
            EmitInstallProgress(reduxId, displayName, "error", 0, "redux not found");
            return new InjectResultDto(false, $"Редукс '{reduxId}' не найден в каталоге.", null);
        }
        if (resolved.Urls.Components is null
            || !resolved.Urls.Components.TryGetValue("armor", out var armorZipUrl)
            || string.IsNullOrWhiteSpace(armorZipUrl))
        {
            EmitInstallProgress(reduxId, displayName, "error", 0, "no armor component url");
            return new InjectResultDto(false,
                "У этого редукса нет ссылки на components/armor.zip в R2. Перезалей с галкой R2.",
                null);
        }

        var rollbackPath = updateRpf + ".preinstall";
        await MakeRollbackPointAsync(updateRpf, rollbackPath, reduxId, displayName,
            "starting", new ProgressBand(1, 4), "armor.install.standalone");

        try
        {
            using var http = HttpClientFactory.CreateFragmenting(TimeSpan.FromMinutes(10));

            EmitInstallProgress(reduxId, displayName, "downloading", 5, null,
                detailMessage: Loc.T("progress.armor.downloading"));
            var donorRoot = await EnsureDonorCachedAsync(reduxId, "armor", http,
                (phase, pct, detail) => EmitInstallProgress(reduxId, displayName, phase, pct, null, detailMessage: detail),
                versionId,
                progressBase: 5, progressSpan: 30);
            if (donorRoot is null)
            {
                EmitInstallProgress(reduxId, displayName, "error", 0, "Не удалось подготовить donor armor.");
                return new InjectResultDto(false, "Не удалось подготовить donor armor.", null);
            }

            EmitInstallProgress(reduxId, displayName, "applying_user_changes", 35, null,
                detailMessage: Loc.T("progress.armor.applying"));

            var svc = new Core.Services.ArmorStandaloneInstallService(_backupService);
            var r = await svc.InstallAsync(gtaRoot, donorRoot,
                NestedProgressEmit(reduxId, displayName, 35, 97, Loc.T("progress.armor.finishingInstall")),
                ct,
                restoreFromClean: false);

            if (!r.Success)
            {
                await TryRollbackAsync(updateRpf, rollbackPath);
                EmitInstallProgress(reduxId, displayName, "error", 0, r.ErrorMessage);
                return new InjectResultDto(false, r.ErrorMessage, r.WorkDir);
            }

            try
            {
                var postSha = await Task.Run(() => Services.FileShaCache.ComputeSha256Cached(updateRpf));
                var armorGlb = await ResolveArmorGlbUrlAsync(item, reduxId, versionId);

                var prior = ReadInstallState();
                WriteInstallState(new InstallState
                {
                    ReduxId           = prior?.ReduxId,
                    VersionId         = prior?.VersionId,
                    PostInstallSha256 = postSha,
                    InstalledAt       = DateTime.UtcNow,

                    CustomizationDraft = prior?.CustomizationDraft,
                    CurrentArmorId     = reduxId,
                    CurrentArmorName   = item?.Name ?? reduxId,
                    CurrentArmorGlbUrl = armorGlb,
                    CurrentArmorKind   = "redux",
                });
            }
            catch (Exception ex) { Debug.WriteLine($"[armor.install.standalone] state save FAILED: {ex.Message}"); }

            try { if (File.Exists(rollbackPath)) File.Delete(rollbackPath); } catch { }

            EmitInstallProgress(reduxId, displayName, "done", 100, null);
            return new InjectResultDto(true, null, r.WorkDir);
        }
        catch (Exception ex)
        {
            await TryRollbackAsync(updateRpf, rollbackPath);
            EmitInstallProgress(reduxId, displayName, "error", 0, ex.Message);
            return new InjectResultDto(false, ex.Message, null);
        }
    }

    public async Task<CurrentArmorInfoDto?> GetCurrentArmorInfoAsync()
    {
        var state = ReadInstallState();
        if (state is null
            || string.IsNullOrWhiteSpace(state.CurrentArmorId)
            || string.IsNullOrWhiteSpace(state.CurrentArmorKind))
            return null;

        string? glb = string.IsNullOrWhiteSpace(state.CurrentArmorGlbUrl) ? null : state.CurrentArmorGlbUrl;
        if (glb is null && string.Equals(state.CurrentArmorKind, "redux", StringComparison.OrdinalIgnoreCase))
        {
            try
            {
                var item = await _catalog.GetByIdAsync(state.CurrentArmorId!);
                glb = await ResolveArmorGlbUrlAsync(item, state.CurrentArmorId!, state.VersionId);
                if (!string.IsNullOrWhiteSpace(glb))
                {
                    state.CurrentArmorGlbUrl = glb;
                    try { WriteInstallState(state); }
                    catch (Exception ex) { Debug.WriteLine($"[armor.current] backfill write FAILED: {ex.Message}"); }
                }
            }
            catch (Exception ex) { Debug.WriteLine($"[armor.current] backfill resolve FAILED: {ex.Message}"); }
        }

        return new CurrentArmorInfoDto(
            Id:     state.CurrentArmorId!,
            Name:   state.CurrentArmorName ?? state.CurrentArmorId!,
            GlbUrl: glb,
            Kind:   state.CurrentArmorKind!);
    }

    private async Task<string?> ResolveArmorGlbUrlAsync(Admin.ReduxItem? item, string reduxId, Guid? versionId)
    {
        if (item?.R2Urls?.Components is { } legacy
            && legacy.TryGetValue("armor_glb", out var legacyUrl)
            && !string.IsNullOrWhiteSpace(legacyUrl))
            return legacyUrl;

        try
        {
            var resolved = await ResolveVersionAsync(reduxId, versionId);
            if (resolved?.Urls.Components is { } verComps
                && verComps.TryGetValue("armor_glb", out var verUrl)
                && !string.IsNullOrWhiteSpace(verUrl))
                return verUrl;
        }
        catch (Exception ex) { Debug.WriteLine($"[armor.glb.resolve] versions lookup failed for {reduxId}: {ex.Message}"); }
        return null;
    }

    private async Task<string?> ResolveVersionLabelAsync(string reduxId, Guid? versionId)
    {
        if (versionId is null || versionId.Value == Guid.Empty) return null;
        var vid = versionId.Value;
        try
        {
            var versions = await _versionsRepo.ListByReduxAsync(reduxId);
            return versions.FirstOrDefault(x => x.Id == vid)?.Label;
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[redux.install] version label resolve failed (non-fatal): {ex.Message}");
            return null;
        }
    }

    private static string WithVersionSuffix(string baseName, string? versionLabel)
        => string.IsNullOrWhiteSpace(versionLabel) ? baseName : $"{baseName} ({versionLabel!.Trim()})";

    private async Task<InjectResultDto> ReduxInstallInternalAsync(string reduxId, Guid? versionId, bool force)
    {
        var cts = new CancellationTokenSource();
        lock (_reduxInstallCtsLock)
        {

            _reduxInstallCts?.Dispose();
            _reduxInstallCts = cts;
        }
        using var _cancelReg = RegisterInstallCts($"redux:{reduxId}", cts);
        var ct = cts.Token;

        using var _mtx = await MiamiGraphics.Shell.Services.UpdateRpfMutex.AcquireAsync($"redux-install:{reduxId}", ct);
        var item = await _catalog.GetByIdAsync(reduxId);

        var displayName = WithVersionSuffix(
            "Установка Redux: " + (item?.Name ?? reduxId),
            await ResolveVersionLabelAsync(reduxId, versionId));

        Core.System.QuotaReservation? quotaDenied = null;
        try
        {
            var need = await ResolveVersionAsync(reduxId, versionId);
            var needBytes = need is { PatchSizeBytes: > 0 } ? need.PatchSizeBytes * 2 : 0;
            var res = await Task.Run(() => Core.System.DataQuota.TryReserve(
                needBytes, "установка " + (item?.Name ?? reduxId)));
            if (!res.Ok) quotaDenied = res;
        }
        catch (Exception qex) { Debug.WriteLine($"[redux.install] проверка места пропущена: {qex.Message}"); }

        EmitInstallProgress(reduxId, displayName, "starting", 0, null);

        if (quotaDenied is not null)
        {
            EmitInstallProgress(reduxId, displayName, "error", 0, quotaDenied.Message);
            return new InjectResultDto(false, quotaDenied.Message, null);
        }

        var gtaRoot = await GetGtaPathAsync();
        if (string.IsNullOrWhiteSpace(gtaRoot))
        {
            EmitInstallProgress(reduxId, displayName, "error", 0, "GTA не найдена.");
            return new InjectResultDto(false, "GTA не найдена. Укажи путь в Admin → Settings → Paths.", null);
        }
        var updateRpf = Path.Combine(gtaRoot, "update", "update.rpf");

        string? prevStandaloneArmorId = null;
        try
        {
            var prevState = ReadInstallState();
            if (prevState is not null
                && string.Equals(prevState.CurrentArmorKind, "library", StringComparison.OrdinalIgnoreCase)
                && !string.IsNullOrWhiteSpace(prevState.CurrentArmorId))
                prevStandaloneArmorId = prevState.CurrentArmorId;
        }
        catch {}

        bool skipArmorReapply = _deferArmorReapplyOnce;
        _deferArmorReapplyOnce = false;

        var effectiveForce = force;
        int cleanRestoreFrom = PREFLIGHT_BAND_FROM;
        if (!force && File.Exists(updateRpf))
        {
            try
            {
                var (currentSha, state, matchesLast, matchesClean) =
                    await PreflightUpdateRpfShaAsync(updateRpf, gtaRoot, reduxId, displayName);
                cleanRestoreFrom = PREFLIGHT_BAND_TO;

                Debug.WriteLine($"[redux.install] preflight: current={currentSha[..16]} matchesLast={matchesLast} matchesClean={matchesClean} firstInstall={state is null}");
                if (!matchesLast && !matchesClean)
                {

                    if (GetLocalCleanRpfPath() is not null)
                    {
                        var reason = state is null ? "first-ever install" : "stale state (likely GTA auto-update)";
                        Debug.WriteLine($"[redux.install] preflight: {reason} + local clean cache present - auto-promoting to force-clean");
                        effectiveForce = true;
                    }
                    else if (await TryFetchCleanViaBackupAsync(gtaRoot, reduxId, displayName))
                    {
                        Debug.WriteLine("[redux.install] preflight: DIRTY - clean cache fetched on the fly, auto-promoting to force-clean");
                        effectiveForce = true;
                        cleanRestoreFrom = AUTOBACKUP_BAND_TO;
                    }
                    else
                    {

                        Debug.WriteLine($"[redux.install] preflight: DIRTY - no local clean cache and auto-fetch failed (state={(state is null ? "null" : "present")})");
                        EmitInstallProgress(reduxId, displayName, "error", 0, DirtyFilesCardMessage);
                        return new InjectResultDto(false, ERROR_DIRTY_FILES, null);
                    }
                }
                else if (matchesLast && !matchesClean)
                {

                    Debug.WriteLine("[redux.install] preflight: matches lastInstall - auto-restoring clean before injecting new redux");
                    effectiveForce = true;
                }
            }
            catch (Exception ex) { Debug.WriteLine($"[redux.install] preflight skipped: {ex.Message}"); }
        }

        if (effectiveForce)
        {
            EmitInstallProgress(reduxId, displayName, "starting", cleanRestoreFrom, null,
                detailMessage: Loc.T("progress.common.restoringCleanRpf"));
            var cleanBand = new ProgressBand(cleanRestoreFrom, CLEAN_BAND_TO);
            long cleanBytes = 0;
            try { if (GetLocalCleanRpfPath() is { } cleanSrc) cleanBytes = new FileInfo(cleanSrc).Length; }
            catch { }
            Action<int> restoreEmit = pct => EmitInstallProgress(reduxId, displayName, "starting",
                cleanBand.Map(pct), null,
                detailMessage: cleanBytes > 0
                    ? Loc.T("progress.common.restoringCleanRpfMb",
                        ("done", (long)(cleanBytes * (pct / 100.0)) / 1024 / 1024), ("total", cleanBytes / 1024 / 1024))
                    : Loc.T("progress.common.restoringCleanRpf"));
            try
            {
                var ok = await _backupService.RestoreFromCleanAsync(gtaRoot, CancellationToken.None, restoreEmit);
                if (!ok)
                {
                    Debug.WriteLine("[redux.install] restore-clean returned false - re-running backup to heal manifest and retrying");
                    if (await TryFetchCleanViaBackupAsync(gtaRoot, reduxId, displayName))
                    {
                        cleanRestoreFrom = AUTOBACKUP_BAND_TO;
                        cleanBand = new ProgressBand(cleanRestoreFrom, CLEAN_BAND_TO);
                        ok = await _backupService.RestoreFromCleanAsync(gtaRoot, CancellationToken.None, restoreEmit);
                    }
                }
                if (!ok)
                {
                    EmitInstallProgress(reduxId, displayName, "error", 0, "Бэкап чистого update.rpf не найден локально. Повтори backup в стартовом окне.");
                    return new InjectResultDto(false,
                        "Бэкап чистого update.rpf не найден локально. Повтори backup в стартовом окне " +
                        "или используй Admin → Injector → 'Восстановить чистый update.rpf'.", null);
                }
            }
            catch (Exception rex)
            {
                EmitInstallProgress(reduxId, displayName, "error", 0, rex.Message);
                return new InjectResultDto(false, $"Не удалось восстановить чистый update.rpf: {rex.Message}", null);
            }
        }

        var spaceError = PreflightUpdateRpfSpace(updateRpf, "установка кастомизации");
        if (spaceError != null)
        {
            EmitInstallProgress(reduxId, displayName, "error", 0, spaceError);
            return new InjectResultDto(false, spaceError, null);
        }

        var rollbackBand = new ProgressBand(ROLLBACK_BAND_FROM, ROLLBACK_BAND_TO);
        long rollbackBytes = 0;
        try { if (File.Exists(updateRpf)) rollbackBytes = new FileInfo(updateRpf).Length; } catch { }
        EmitInstallProgress(reduxId, displayName, "starting", rollbackBand.From, null,
            detailMessage: Loc.T("progress.common.creatingRestorePoint"));
        var rollbackPath = updateRpf + ".preinstall";
        try
        {
            if (File.Exists(updateRpf))
            {
                await global::MiamiGraphics.Core.System.BackupService.CopyLargeFileAsync(updateRpf, rollbackPath,
                    pct => EmitInstallProgress(reduxId, displayName, "starting", rollbackBand.Map(pct), null,
                        detailMessage: rollbackBytes > 0
                            ? Loc.T("progress.common.creatingRestorePointMb",
                                ("done", (long)(rollbackBytes * (pct / 100.0)) / 1024 / 1024), ("total", rollbackBytes / 1024 / 1024))
                            : Loc.T("progress.common.creatingRestorePoint")),
                    CancellationToken.None);
                Debug.WriteLine($"[redux.install] rollback copy at {rollbackPath}");
            }
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[redux.install] rollback copy FAILED: {ex.Message} - proceeding without rollback");
        }
        EmitInstallProgress(reduxId, displayName, "starting", INJECT_BAND_FROM, null,
            detailMessage: Loc.T("progress.redux.preparingInjector"));

        InjectResultDto r;
        try
        {
            r = await AdminInjectFromCatalogInternalAsync(reduxId, versionId,
                (phase, percent, detail) =>
                {
                    if (string.Equals(phase, "error", StringComparison.Ordinal)) return;
                    if (string.Equals(phase, "done", StringComparison.Ordinal))
                    {
                        EmitInstallProgress(reduxId, displayName, "applying_user_changes", INJECT_BAND_TO, null,
                            detailMessage: Loc.T("progress.common.finishingInstall"));
                        return;
                    }
                    EmitInstallProgress(reduxId, displayName, phase,
                        MapNestedProgress(percent, INJECT_BAND_FROM, INJECT_BAND_TO), null,
                        detailMessage: detail);
                },
                ct);
        }
        catch (OperationCanceledException)
        {

            await TryRollbackAsync(updateRpf, rollbackPath);
            EmitInstallProgress(reduxId, displayName, "cancelled", 0, "Установка отменена пользователем.",
                detailMessage: Loc.T("progress.common.cancelledByUser"));
            return new InjectResultDto(false, "CANCELLED", null);
        }
        catch (Exception ex)
        {
            await TryRollbackAsync(updateRpf, rollbackPath);
            EmitInstallProgress(reduxId, displayName, "error", 0, ex.Message);
            return new InjectResultDto(false, ex.Message, null);
        }

        if (!r.Success)
        {
            await TryRollbackAsync(updateRpf, rollbackPath);
            EmitInstallProgress(reduxId, displayName, "error", 0, r.ErrorMessage);
            return r;
        }

        try
        {
            var postSha = await Task.Run(() => Services.FileShaCache.ComputeSha256Cached(updateRpf));
            bool reduxHasArmor = item?.Components is not null
                && item.Components.TryGetValue("armor", out var aComp)
                && aComp is not null && aComp.IsFound;
            string? armorGlb = reduxHasArmor
                ? await ResolveArmorGlbUrlAsync(item, reduxId, versionId)
                : null;
            WriteInstallState(new InstallState
            {
                ReduxId = reduxId,
                VersionId = versionId,
                PostInstallSha256 = postSha,
                InstalledAt = DateTime.UtcNow,
                CustomizationDraft = BuildDefaultDraft(reduxId, versionId),
                CurrentArmorId     = reduxHasArmor ? reduxId : null,
                CurrentArmorName   = reduxHasArmor ? (item?.Name ?? reduxId) : null,
                CurrentArmorGlbUrl = armorGlb,
                CurrentArmorKind   = reduxHasArmor ? "redux" : null,
            });
            Debug.WriteLine($"[redux.install] lastInstall saved: {postSha[..16]}");
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[redux.install] lastInstall save FAILED: {ex.Message}");
        }

        if (!skipArmorReapply && !string.IsNullOrWhiteSpace(prevStandaloneArmorId))
        {
            try
            {
                EmitInstallProgress(reduxId, displayName, "applying_user_changes", 98, null,
                    detailMessage: Loc.T("progress.armor.reapplyOverRedux"));
                var ar = await ArmorLibraryInstallAsync(prevStandaloneArmorId!, overlayMode: true, force: true, alreadyLocked: true);
                if (ar.Success)
                    Debug.WriteLine($"[redux.install] re-applied standalone armor '{prevStandaloneArmorId}' over new redux");
                else
                    Debug.WriteLine($"[redux.install] re-apply armor '{prevStandaloneArmorId}' FAILED: {ar.ErrorMessage}");
            }
            catch (Exception ex)
            {
                Debug.WriteLine($"[redux.install] re-apply armor EXCEPTION: {ex.Message}");
            }
        }

        await ReapplyZalazyIfEnabledAsync(updateRpf);
        await ReapplyGreenZoneIfEnabledAsync(updateRpf);
        await ReapplyRukzakIfEnabledAsync(updateRpf);
        await ReapplyCarLogosIfEnabledAsync(updateRpf);
        await ReapplyFastJoinIfEnabledAsync(updateRpf);
        await ReapplyBigMapIfEnabledAsync(updateRpf);
        await FixUpdateRpfAfterOverlayReapplyAsync(updateRpf);
        await ReapplySmokeIfEnabledAsync(gtaRoot);
        await ReapplyNoTracerIfEnabledAsync(gtaRoot);
        await ReapplyTracerStudioIfEnabledAsync(gtaRoot);
        await ReapplyImprovementsIfAnyAsync(gtaRoot);

        try
        {
            var sealedSha = await Task.Run(() => Services.FileShaCache.ComputeSha256Cached(updateRpf));
            var st = ReadInstallState();
            if (st is not null && !string.Equals(st.PostInstallSha256, sealedSha, StringComparison.OrdinalIgnoreCase))
            {
                st.PostInstallSha256 = sealedSha;
                WriteInstallState(st);
                Debug.WriteLine($"[redux.install] PostInstallSha256 re-sealed after overlay re-apply: {sealedSha[..16]}");
            }
        }
        catch (Exception ex) { Debug.WriteLine($"[redux.install] re-seal sha FAILED: {ex.Message}"); }

        try { if (File.Exists(rollbackPath)) File.Delete(rollbackPath); } catch { }

        EmitInstallProgress(reduxId, displayName, "done", 100, null);
        _ = ReduxIncrementDownloadsAsync(reduxId);
        return r;
    }

    private static string? PreflightUpdateRpfSpace(string updateRpf, string operationLabel)
    {
        long size = 0;
        try { if (File.Exists(updateRpf)) size = new FileInfo(updateRpf).Length; } catch { }
        if (size <= 0) return null;
        return Services.CriticalOperationGuard.TryEnsureSpaceAvailable(
            updateRpf, size * 2, operationLabel, out var error) ? null : error;
    }

    private static async Task TryRollbackAsync(string updateRpf, string rollbackPath)
    {
        try
        {
            if (File.Exists(rollbackPath))
            {
                await Task.Run(() => File.Copy(rollbackPath, updateRpf, overwrite: true));
                Debug.WriteLine($"[redux.install] rolled back from {rollbackPath}");
            }
        }
        catch (Exception ex) { Debug.WriteLine($"[redux.install] rollback FAILED: {ex.Message}"); }
        try { if (File.Exists(rollbackPath)) File.Delete(rollbackPath); } catch { }
    }

    private async Task<string?> TryGetCleanShaForCurrentVersionAsync(string gtaRoot)
    {
        try
        {
            var exePath = Path.Combine(gtaRoot, "GTA5.exe");
            if (!File.Exists(exePath)) return null;
            var version = FileVersionInfo.GetVersionInfo(exePath).FileVersion;
            if (string.IsNullOrWhiteSpace(version)) return null;

            var rows = await _supabase.SelectAsync<GtaVersionRow>(
                "gta_versions",
                $"select=update_rpf_sha256&exe_version=eq.{Uri.EscapeDataString(version)}&limit=1");
            return rows.FirstOrDefault()?.UpdateRpfSha256;
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[redux.install] couldn't fetch clean SHA: {ex.Message}");
            return null;
        }
    }

    private async Task<(string CurrentSha, InstallState? State, bool MatchesLast, bool MatchesClean)>
        PreflightUpdateRpfShaAsync(string updateRpf, string gtaRoot, string progressKey, string displayName)
    {
        var band      = new ProgressBand(PREFLIGHT_BAND_FROM, PREFLIGHT_BAND_TO);
        var liveBand  = band.Slice(0, 65);
        var cleanBand = band.Slice(65, 100);

        var currentSha = await Task.Run(() => Services.FileShaCache.ComputeSha256Cached(updateRpf,
            (done, total) => EmitInstallProgress(progressKey, displayName, "starting",
                liveBand.MapBytes(done, total), null,
                detailMessage: Loc.T("progress.common.verifyingUpdateRpfMb",
                    ("done", done / 1024 / 1024), ("total", Math.Max(1, total / 1024 / 1024))))));

        var state = ReadInstallState();
        var matchesLast = state?.PostInstallSha256 is { } lastSha
            && string.Equals(currentSha, lastSha, StringComparison.OrdinalIgnoreCase);
        var matchesClean = await IsRpfCleanAsync(currentSha, gtaRoot,
            (done, total) => EmitInstallProgress(progressKey, displayName, "starting",
                cleanBand.MapBytes(done, total), null,
                detailMessage: Loc.T("progress.common.comparingWithCleanMb",
                    ("done", done / 1024 / 1024), ("total", Math.Max(1, total / 1024 / 1024)))));

        EmitInstallProgress(progressKey, displayName, "starting", band.To, null,
            detailMessage: Loc.T("progress.common.integrityCheckDone"));
        return (currentSha, state, matchesLast, matchesClean);
    }

    private async Task<bool> IsRpfCleanAsync(string currentSha, string gtaRoot,
        Action<long, long>? cleanShaProgress = null)
    {
        if (string.IsNullOrWhiteSpace(currentSha)) return false;

        var updateRpfPath = Path.Combine(gtaRoot, "update", "update.rpf");
        var localCleanRpf = GetLocalCleanRpfPath();

        if (localCleanRpf is not null && File.Exists(localCleanRpf))
        {
            try
            {
                var liveSize  = new FileInfo(updateRpfPath).Length;
                var cleanSize = new FileInfo(localCleanRpf).Length;
                if (liveSize == cleanSize)
                {
                    var localCleanSha = await Task.Run(() => Services.FileShaCache.ComputeSha256Cached(localCleanRpf, cleanShaProgress));
                    if (string.Equals(currentSha, localCleanSha, StringComparison.OrdinalIgnoreCase))
                    {
                        Debug.WriteLine($"[redux.preflight] clean confirmed via local backup (size={liveSize}).");
                        return true;
                    }
                    Debug.WriteLine("[redux.preflight] hash mismatch against local backup - trying canonical SHA fallback.");

                }
                else
                {
                    Debug.WriteLine($"[redux.preflight] size mismatch live={liveSize} backup={cleanSize} - trying canonical SHA fallback.");

                }
            }
            catch (Exception ex)
            {
                Debug.WriteLine($"[redux.preflight] local backup check failed ({ex.Message}); falling back to canonical SHA.");

            }
        }

        var canonicalSha = await TryGetCleanShaForCurrentVersionAsync(gtaRoot);
        if (canonicalSha is not null
            && string.Equals(currentSha, canonicalSha, StringComparison.OrdinalIgnoreCase))
        {
            Debug.WriteLine("[redux.preflight] clean confirmed via canonical SHA.");
            return true;
        }

        return false;
    }

    private static Task StartProgressRamp(
        Action<string, int>? emit,
        string phase,
        int fromPct,
        int toPct,
        int estimatedDurationSec,
        CancellationToken ct)
    {
        return Task.Run(async () =>
        {
            if (emit is null || toPct <= fromPct) return;
            int range = toPct - fromPct;
            double tau = Math.Max(3.0, estimatedDurationSec) / 2.3;
            var sw = Stopwatch.StartNew();
            int last = fromPct;
            emit(phase, last);
            while (!ct.IsCancellationRequested)
            {
                try { await Task.Delay(400, ct); } catch { break; }
                if (ct.IsCancellationRequested) break;

                double frac = 1.0 - Math.Exp(-sw.Elapsed.TotalSeconds / tau);
                int target = fromPct + (int)Math.Round(range * frac);
                if (target > toPct) target = toPct;
                if (target > last)
                {
                    emit(phase, target);
                    last = target;
                }
            }
        });
    }

    private const int PREFLIGHT_BAND_FROM  = 1;
    private const int PREFLIGHT_BAND_TO    = 12;
    private const int AUTOBACKUP_BAND_TO   = 27;
    private const int CLEAN_BAND_TO        = 45;
    private const int ROLLBACK_BAND_FROM   = 45;
    private const int ROLLBACK_BAND_TO     = 58;

    private const int INJECT_BAND_FROM = 60;
    private const int INJECT_BAND_TO   = 97;

    private readonly struct ProgressBand
    {
        public readonly int From;
        public readonly int To;

        public ProgressBand(int from, int to)
        {
            From = from;
            To   = Math.Max(from, to);
        }

        public int Width => To - From;

        public int Map(int inner)
        {
            if (inner < 0) return inner;
            var clamped = Math.Clamp(inner, 0, 100);
            return From + (int)Math.Round(Width * clamped / 100.0);
        }

        public int MapBytes(long done, long total)
            => total > 0 ? From + (int)Math.Min(Width, done * Width / total) : From;

        public ProgressBand Slice(int innerFrom, int innerTo) => new(Map(innerFrom), Map(innerTo));

        public override string ToString() => $"{From}..{To}";
    }

    private static int MapNestedProgress(int inner, int from, int to)
        => new ProgressBand(from, to).Map(inner);

    private async Task CopyLargeFileWithProgressAsync(string src, string dst,
        string progressKey, string displayName, string phase, ProgressBand band, string caption)
    {
        long total = 0;
        try { total = new FileInfo(src).Length; } catch { }
        await Core.System.BackupService.CopyLargeFileAsync(src, dst,
            pct => EmitInstallProgress(progressKey, displayName, phase, band.Map(pct), null,
                detailMessage: total > 0
                    ? Loc.T("progress.common.captionMb", ("caption", caption),
                        ("done", (long)(total * (pct / 100.0)) / 1024 / 1024), ("total", total / 1024 / 1024))
                    : caption),
            CancellationToken.None);
        EmitInstallProgress(progressKey, displayName, phase, band.To, null, detailMessage: caption);
    }

    private async Task MakeRollbackPointAsync(string src, string rollbackPath,
        string progressKey, string displayName, string phase, ProgressBand band, string tag)
    {
        try
        {
            if (!File.Exists(src))
            {
                EmitInstallProgress(progressKey, displayName, phase, band.To, null);
                return;
            }
            await CopyLargeFileWithProgressAsync(src, rollbackPath, progressKey, displayName,
                phase, band, Loc.T("progress.common.restorePointCaption"));
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[{tag}] rollback copy FAILED: {ex.Message} - proceeding without rollback");
            EmitInstallProgress(progressKey, displayName, phase, band.To, null,
                detailMessage: Loc.T("progress.common.restorePointFailed"));
        }
    }

    private Action<string, int> NestedProgressEmit(
        string progressKey, string displayName, int from, int to, string? doneDetail = null)
        => (phase, pct) =>
        {
            if (string.Equals(phase, "error", StringComparison.Ordinal)) return;
            if (string.Equals(phase, "done", StringComparison.Ordinal))
            {
                EmitInstallProgress(progressKey, displayName, "applying_user_changes", to, null,
                    detailMessage: doneDetail);
                return;
            }
            EmitInstallProgress(progressKey, displayName, phase,
                MapNestedProgress(pct, from, to), null);
        };

    private Action<string, int, string?> NestedProgressEmitDetailed(
        string progressKey, string displayName, ProgressBand band, string? doneDetail = null)
        => (phase, pct, detail) =>
        {
            if (string.Equals(phase, "error", StringComparison.Ordinal)) return;
            if (string.Equals(phase, "done", StringComparison.Ordinal))
            {
                EmitInstallProgress(progressKey, displayName, "applying_user_changes", band.To, null,
                    detailMessage: doneDetail ?? detail);
                return;
            }
            EmitInstallProgress(progressKey, displayName, phase, band.Map(pct), null, detailMessage: detail);
        };

    private const int REDUX_CACHE_MAX = 4;

    private static string GetReduxCacheRoot()
        => MiamiGraphics.Shell.Services.ModCacheSettings.Dir("redux");

    private async Task<string> EnsureReduxCachedAsync(string reduxId, Guid? versionId, Action<string, int, string?>? progressEmit, int progressBase, int progressSpan)
    {
        var resolved = await ResolveVersionAsync(reduxId, versionId)
            ?? throw new InvalidOperationException(Loc.T("errors.redux.notInCatalog", ("id", reduxId)));
        if (string.IsNullOrWhiteSpace(resolved.Urls.Patch) || string.IsNullOrWhiteSpace(resolved.Urls.Manifest))
            throw new InvalidOperationException(
                resolved.IsLegacy
                    ? Loc.T("errors.redux.noR2LinksLegacy", ("id", reduxId))
                    : Loc.T("errors.redux.noR2LinksVersion", ("label", resolved.Label), ("slot", resolved.Slot), ("id", reduxId)));

        var cacheKey = resolved.IsLegacy
            ? reduxId
            : $"{reduxId}__v{resolved.Slot}";
        var cacheDir = Core.System.SafePath.ResolveLeafInside(
            GetReduxCacheRoot(), cacheKey, "Идентификатор редукса");
        var manifestPath = Path.Combine(cacheDir, "manifest.json");
        var patchDir = Path.Combine(cacheDir, "patch_files");

        if (MiamiGraphics.Shell.Services.ModCacheSettings.ReuseEnabled
            && File.Exists(manifestPath) && Directory.Exists(patchDir)
            && Services.VerifiedDownload.DirMarkerMatches(cacheDir, resolved.PatchSha256))
        {

            try { File.SetLastAccessTimeUtc(manifestPath, DateTime.UtcNow); } catch { }
            Core.System.DataQuota.Touch(cacheDir);
            Debug.WriteLine($"[redux.cache] hit '{cacheKey}'");
            progressEmit?.Invoke("downloading_new", progressBase + progressSpan,
                "Использую сохранённую копию редукса (без перекачки)...");
            return cacheDir;
        }

        Debug.WriteLine($"[redux.cache] miss '{cacheKey}', downloading");

        var reserve = await Task.Run(() => Core.System.DataQuota.TryReserve(
            resolved.PatchSizeBytes > 0 ? resolved.PatchSizeBytes * 2 : 0,
            $"загрузка редукса {reduxId}"));
        if (!reserve.Ok) throw new InvalidOperationException(reserve.Message!);

        Directory.CreateDirectory(cacheDir);
        if (Directory.Exists(patchDir)) Directory.Delete(patchDir, recursive: true);
        Directory.CreateDirectory(patchDir);

        using var http = HttpClientFactory.CreateFragmenting(TimeSpan.FromMinutes(15));
        var patchZipPath = Path.Combine(cacheDir, "patch.zip");

        var band       = new ProgressBand(progressBase, progressBase + progressSpan);
        var dlBand     = band.Slice(0, 78);
        var shaBand    = band.Slice(78, 89);
        var unzipBand  = band.Slice(89, 100);

        await DownloadFileAsync(http, resolved.Urls.Patch!, patchZipPath,
            bytesProgress: (received, total) =>
            {
                if (total > 0)
                {
                    progressEmit?.Invoke("downloading_new", dlBand.MapBytes(received, total),
                        DownloadCounterText(received, total));
                }
                else
                {
                    progressEmit?.Invoke("downloading_new", -1, $"Загрузка - {received / 1024 / 1024} МБ");
                }
            });

        Services.VerifiedDownload.RequireReference(resolved.PatchSha256, $"patch.zip редукса «{cacheKey}»");
        {
            var actualSha = await Task.Run(() => ComputeFileSha256(patchZipPath,
                (done, total) => progressEmit?.Invoke("downloading_new", shaBand.MapBytes(done, total),
                    $"Проверяю целостность - {done / 1024 / 1024} / {Math.Max(1, total / 1024 / 1024)} МБ")));
            if (!Services.VerifiedDownload.Matches(resolved.PatchSha256, actualSha))
            {
                try { File.Delete(patchZipPath); } catch { }
                throw new Services.IntegrityException(
                    $"patch.zip редукса «{cacheKey}» не прошёл проверку целостности и удалён - установка отменена. " +
                    "Повтори попытку, а если повторится - сообщи админу.");
            }
        }

        await Task.Run(() => ExtractZipWithProgress(patchZipPath, patchDir,
            (i, total, name) => progressEmit?.Invoke("downloading_new",
                total > 0 ? unzipBand.From + (int)((long)unzipBand.Width * i / total) : unzipBand.From,
                $"Распаковываю - {i} / {total}{(string.IsNullOrEmpty(name) ? "" : $" ({name})")}")));
        try { File.Delete(patchZipPath); } catch { }

        var assetShas = await ReduxAssetShasAsync(resolved.VersionId);
        await Services.VerifiedDownload.FetchAsync(resolved.Urls.Manifest!, manifestPath,
            assetShas.Manifest, $"manifest.json редукса «{cacheKey}»", referenceRequired: false);
        if (!string.IsNullOrWhiteSpace(resolved.Urls.ComponentMap))
        {
            try
            {
                await Services.VerifiedDownload.FetchAsync(resolved.Urls.ComponentMap!,
                    Path.Combine(cacheDir, "component_map.json"), assetShas.ComponentMap,
                    $"component_map.json редукса «{cacheKey}»", referenceRequired: false);
            }
            catch (Services.IntegrityException) { throw; }
            catch { }
        }
        if (!string.IsNullOrWhiteSpace(resolved.Urls.ContentInfo))
        {
            try
            {
                await Services.VerifiedDownload.FetchAsync(resolved.Urls.ContentInfo!,
                    Path.Combine(cacheDir, "content_info.json"), assetShas.ContentInfo,
                    $"content_info.json редукса «{cacheKey}»", referenceRequired: false);
            }
            catch (Services.IntegrityException) { throw; }
            catch { }
        }

        Services.VerifiedDownload.WriteDirMarker(cacheDir, resolved.PatchSha256);

        EvictReduxCache();
        return cacheDir;
    }

    private static void EvictReduxCache()
    {
        try
        {
            var root = GetReduxCacheRoot();
            var entries = Directory.GetDirectories(root)
                .Select(d => new { Path = d, AccessTime = TryGetEntryAccessTime(d) })
                .OrderByDescending(e => e.AccessTime)
                .ToList();
            foreach (var e in entries.Skip(REDUX_CACHE_MAX))
            {
                try
                {
                    Directory.Delete(e.Path, recursive: true);
                    Debug.WriteLine($"[redux.cache] evicted '{Path.GetFileName(e.Path)}'");
                }
                catch (Exception ex) { Debug.WriteLine($"[redux.cache] evict failed: {ex.Message}"); }
            }
        }
        catch (Exception ex) { Debug.WriteLine($"[redux.cache] eviction loop failed: {ex.Message}"); }
    }

    private static DateTime TryGetEntryAccessTime(string dir)
    {
        try { return File.GetLastAccessTimeUtc(Path.Combine(dir, "manifest.json")); }
        catch { return DateTime.MinValue; }
    }

    private static string? GetLocalCleanRpfPath()
    {

        var backupDir    = Core.System.AppDataRoot.BackupRoot;
        var cleanDir     = Path.Combine(backupDir, "clean");
        if (!Directory.Exists(cleanDir)) return null;

        try
        {
            var manifestPath = Path.Combine(backupDir, "manifest.json");
            if (File.Exists(manifestPath))
            {
                using var fs = File.OpenRead(manifestPath);
                using var doc = JsonDocument.Parse(fs);
                if (doc.RootElement.TryGetProperty("files", out var files)
                    && files.TryGetProperty("cleanUpdate", out var cu)
                    && cu.TryGetProperty("path", out var pathEl)
                    && pathEl.ValueKind == JsonValueKind.String)
                {
                    var rel = pathEl.GetString() ?? string.Empty;
                    var abs = Path.Combine(backupDir, rel.Replace('\\', Path.DirectorySeparatorChar)
                                                       .Replace('/', Path.DirectorySeparatorChar));
                    if (File.Exists(abs))
                    {
                        Debug.WriteLine($"[redux.preflight] clean rpf via manifest: {abs}");
                        return abs;
                    }
                }
            }
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[redux.preflight] manifest parse failed: {ex.Message} - falling back to dir scan");
        }

        var legacy = Path.Combine(cleanDir, "update.rpf");
        if (File.Exists(legacy)) return legacy;

        try
        {
            var scanned = Directory.EnumerateFiles(cleanDir, "update*.rpf", SearchOption.TopDirectoryOnly)
                .Select(p => new FileInfo(p))
                .OrderByDescending(fi => fi.Length)
                .FirstOrDefault();
            if (scanned is not null)
            {
                Debug.WriteLine($"[redux.preflight] clean rpf via dir scan: {scanned.FullName}");
                return scanned.FullName;
            }
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[redux.preflight] dir scan failed: {ex.Message}");
        }

        return null;
    }

    private async Task<bool> TryFetchCleanViaBackupAsync(string gtaRoot, string progressKey, string displayName,
        ProgressBand? bandOverride = null)
    {
        try
        {
            var band = bandOverride ?? new ProgressBand(PREFLIGHT_BAND_TO, AUTOBACKUP_BAND_TO);
            var bDetect   = band.Slice(0, 4);
            var bHash     = band.Slice(4, 26);
            var bCompare  = band.Slice(26, 30);
            var bSnapshot = band.Slice(30, 52);
            var bDownload = band.Slice(52, 88);
            var bDlcSnap  = band.Slice(88, 94);
            var bDlcDown  = band.Slice(94, 100);

            var progress = new Progress<Core.System.BackupProgress>(p =>
            {
                string amount = p.BytesTotal is > 0 && p.BytesProcessed is >= 0
                    ? Loc.T("progress.common.amountMb",
                        ("done", p.BytesProcessed!.Value / 1024 / 1024), ("total", p.BytesTotal!.Value / 1024 / 1024))
                    : $"{Math.Clamp(p.Percent, 0, 100)}%";

                (string text, ProgressBand phaseBand) = p.Phase switch
                {
                    "detecting"                => (Loc.T("progress.backup.detecting"),               bDetect),
                    "hashing_user_update"      => (Loc.T("progress.backup.hashingUserUpdate"),       bHash),
                    "comparing"                => (Loc.T("progress.backup.comparing"),               bCompare),
                    "snapshot_user_update"     => (Loc.T("progress.backup.snapshotUserUpdate"),      bSnapshot),
                    "downloading_clean_update" => (Loc.T("progress.backup.downloadingCleanUpdate"),  bDownload),
                    "snapshot_dlc"             => (Loc.T("progress.backup.snapshotDlc"),             bDlcSnap),
                    "downloading_clean_dlc"    => (Loc.T("progress.backup.downloadingCleanDlc"),     bDlcDown),
                    _                          => (Loc.T("progress.backup.preparing"),               bDlcDown),
                };

                EmitInstallProgress(progressKey, displayName, "starting",
                    phaseBand.Map(p.Percent), null, detailMessage: $"{text} - {amount}");
            });

            var result = await _backupService.RunFullBackupAsync(gtaRoot, progress, CancellationToken.None);
            Debug.WriteLine($"[preflight.autobackup] success={result.Success} err={result.ErrorCode} dirty={result.HadDirtyUpdate} versionUnsupported={result.VersionUnsupported}");

            return result.Success && GetLocalCleanRpfPath() is not null;
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[preflight.autobackup] FAIL: {ex.GetType().Name}: {ex.Message}");
            return false;
        }
    }

    public async Task<InjectResultDto> ReduxInstallPreserveAsync(string newReduxId, Guid? versionId)
    {
        using var _mtx = await MiamiGraphics.Shell.Services.UpdateRpfMutex.AcquireAsync($"redux-preserve:{newReduxId}");
        var newItem = await _catalog.GetByIdAsync(newReduxId);
        if (newItem is null)
            return new InjectResultDto(false, "Редукс не найден в каталоге.", null);
        var displayName = WithVersionSuffix(
            "Установка Redux: " + (newItem.Name ?? newReduxId),
            await ResolveVersionLabelAsync(newReduxId, versionId));

        EmitInstallProgress(newReduxId, displayName, "starting", 0, null);

        var state = ReadInstallState();
        if (state is null || string.IsNullOrWhiteSpace(state.ReduxId))
        {
            EmitInstallProgress(newReduxId, displayName, "error", 0, "Не помним предыдущую установку.");
            return new InjectResultDto(false,
                "Не помним предыдущую установку (install_state.json пуст). " +
                "Запусти Чистую установку - мы запишем lastInstall, и со следующей сможем сохранять твои файлы.",
                null);
        }
        var lastReduxId = state.ReduxId;
        var lastVersionId = state.VersionId;

        var lastItem = await _catalog.GetByIdAsync(lastReduxId);
        if (lastItem is null)
        {
            EmitInstallProgress(newReduxId, displayName, "error", 0, $"Прошлый редукс '{lastReduxId}' удалён из каталога.");
            return new InjectResultDto(false,
                $"Прошлый редукс '{lastReduxId}' удалён из каталога - не получится воспроизвести базу для diff'а. " +
                "Запусти Чистую установку.", null);
        }

        var gtaRoot = await GetGtaPathAsync();
        if (string.IsNullOrWhiteSpace(gtaRoot))
        {
            EmitInstallProgress(newReduxId, displayName, "error", 0, "GTA не найдена.");
            return new InjectResultDto(false, "GTA не найдена.", null);
        }
        var userUpdateRpf = Path.Combine(gtaRoot, "update", "update.rpf");
        if (!File.Exists(userUpdateRpf))
        {
            EmitInstallProgress(newReduxId, displayName, "error", 0, "user update.rpf не найден.");
            return new InjectResultDto(false, $"Нет файла {userUpdateRpf}", null);
        }

        var cleanRpf = GetLocalCleanRpfPath();
        if (cleanRpf is null)
        {
            EmitInstallProgress(newReduxId, displayName, "error", 0, "Локальный clean update.rpf не найден.");
            return new InjectResultDto(false,
                "Локальный чистый update.rpf не найден в backup\\clean\\. Запусти полный backup в стартовом окне.",
                null);
        }

        var sessionRoot = Path.Combine(Path.GetTempPath(), "MiamiGraphics", $"preserve_{Guid.NewGuid().ToString("N")[..8]}");
        Directory.CreateDirectory(sessionRoot);
        Debug.WriteLine($"[redux.install.preserve] session={sessionRoot} new='{newReduxId}' last='{lastReduxId}'");

        var rollbackPath = userUpdateRpf + ".preinstall";

        try
        {

            EmitInstallProgress(newReduxId, displayName, "restoring_old_state", 5, null);
            var fakeGtaRoot = Path.Combine(sessionRoot, "fake_gta");
            var fakeUpdateDir = Path.Combine(fakeGtaRoot, "update");
            Directory.CreateDirectory(fakeUpdateDir);
            var fakeUpdate = Path.Combine(fakeUpdateDir, "update.rpf");
            await CopyLargeFileWithProgressAsync(cleanRpf, fakeUpdate, newReduxId, displayName,
                "restoring_old_state", new ProgressBand(5, 10), "Готовлю рабочую копию update.rpf");

            EmitInstallProgress(newReduxId, displayName, "restoring_old_state", 10, null);
            var lastWorkDir = await EnsureReduxCachedAsync(lastReduxId, lastVersionId,
                (phase, pct, detail) => EmitInstallProgress(newReduxId, displayName, "restoring_old_state", pct, null,
                    detailMessage: detail),
                progressBase: 10, progressSpan: 5);

            EmitInstallProgress(newReduxId, displayName, "restoring_old_state", 18, null);
            using (var rampCts1 = new CancellationTokenSource())
            {
                var ramp1 = StartProgressRamp(
                    (phase, pct) => EmitInstallProgress(newReduxId, displayName, "restoring_old_state", pct, null),
                    "restoring_old_state", 18, 24, 60, rampCts1.Token);
                var fakeEngine = new Core.Injector.RpfInjectEngine(fakeGtaRoot);
                var ok = await Task.Run(() => fakeEngine.InjectPatch(lastWorkDir));
                rampCts1.Cancel(); try { await ramp1; } catch { }
                if (!ok)
                {
                    var errorMessage = InjectFailureMessage(fakeEngine, Loc.T("errors.install.replayPrevFailed"));
                    EmitInstallProgress(newReduxId, displayName, "error", 0, errorMessage);
                    return new InjectResultDto(false,
                        errorMessage, sessionRoot);
                }
            }

            EmitInstallProgress(newReduxId, displayName, "computing_diff", 25, null);
            string userDiffWorkDir;
            using (var rampCts2 = new CancellationTokenSource())
            {
                var ramp2 = StartProgressRamp(
                    (phase, pct) => EmitInstallProgress(newReduxId, displayName, "computing_diff", pct, null),
                    "computing_diff", 25, 38, 30, rampCts2.Token);
                userDiffWorkDir = await Task.Run(() =>
                {
                    var pipeline = new Core.Parser.ReduxParserPipeline();
                    return pipeline.ParseRedux(fakeUpdate, userUpdateRpf, $"user_diff_{Guid.NewGuid().ToString("N")[..8]}");
                });
                rampCts2.Cancel(); try { await ramp2; } catch { }
            }
            Debug.WriteLine($"[redux.install.preserve] user_diff workDir={userDiffWorkDir}");

            EmitInstallProgress(newReduxId, displayName, "downloading_new", 40, null);
            var newWorkDir = await EnsureReduxCachedAsync(newReduxId, versionId,
                (phase, pct, detail) => EmitInstallProgress(newReduxId, displayName, "downloading_new", pct, null,
                    detailMessage: detail),
                progressBase: 40, progressSpan: 15);

            await CopyLargeFileWithProgressAsync(userUpdateRpf, rollbackPath, newReduxId, displayName,
                "installing_new", new ProgressBand(55, 58), "Создаём точку восстановления");

            await CopyLargeFileWithProgressAsync(cleanRpf, userUpdateRpf, newReduxId, displayName,
                "installing_new", new ProgressBand(58, 61), "Ставлю чистый update.rpf");

            var realEngine = new Core.Injector.RpfInjectEngine(gtaRoot);

            using (var rampCts3 = new CancellationTokenSource())
            {
                var ramp3 = StartProgressRamp(
                    (phase, pct) => EmitInstallProgress(newReduxId, displayName, "installing_new", pct, null),
                    "installing_new", 61, 76, 60, rampCts3.Token);
                var newOk = await Task.Run(() => realEngine.InjectPatch(newWorkDir));
                rampCts3.Cancel(); try { await ramp3; } catch { }
                if (!newOk)
                {
                    var errorMessage = InjectFailureMessage(realEngine, Loc.T("errors.install.newReduxFailed"));
                    await TryRollbackAsync(userUpdateRpf, rollbackPath);
                    EmitInstallProgress(newReduxId, displayName, "error", 0, errorMessage);
                    return new InjectResultDto(false, errorMessage, null);
                }
            }

            EmitInstallProgress(newReduxId, displayName, "applying_user_changes", 78, null);
            using (var rampCts4 = new CancellationTokenSource())
            {
                var ramp4 = StartProgressRamp(
                    (phase, pct) => EmitInstallProgress(newReduxId, displayName, "applying_user_changes", pct, null),
                    "applying_user_changes", 78, 95, 30, rampCts4.Token);
                var diffOk = await Task.Run(() => realEngine.InjectPatch(userDiffWorkDir));
                rampCts4.Cancel(); try { await ramp4; } catch { }
                if (!diffOk)
                {
                    var errorMessage = InjectFailureMessage(realEngine, Loc.T("errors.install.userChangesFilesFailed"));
                    await TryRollbackAsync(userUpdateRpf, rollbackPath);
                    EmitInstallProgress(newReduxId, displayName, "error", 0, errorMessage);
                    return new InjectResultDto(false, errorMessage, null);
                }
            }

            var newSha = await Task.Run(() => Services.FileShaCache.ComputeSha256Cached(userUpdateRpf));
            bool presReduxHasArmor = newItem?.Components is not null
                && newItem.Components.TryGetValue("armor", out var pAComp)
                && pAComp is not null && pAComp.IsFound;
            string? presArmorGlb = presReduxHasArmor
                ? await ResolveArmorGlbUrlAsync(newItem, newReduxId, versionId)
                : null;
            bool carryPrevArmor = string.Equals(state.CurrentArmorKind, "library", StringComparison.OrdinalIgnoreCase)
                && !string.IsNullOrWhiteSpace(state.CurrentArmorId);
            WriteInstallState(new InstallState
            {
                ReduxId = newReduxId,
                VersionId = versionId,
                PostInstallSha256 = newSha,
                InstalledAt = DateTime.UtcNow,
                CustomizationDraft = state.CustomizationDraft is { } prevDraft
                    ? prevDraft with { ReduxId = newReduxId, BaseVersionId = versionId }
                    : BuildDefaultDraft(newReduxId, versionId),
                CurrentArmorId     = carryPrevArmor ? state.CurrentArmorId   : (presReduxHasArmor ? newReduxId : null),
                CurrentArmorName   = carryPrevArmor ? state.CurrentArmorName : (presReduxHasArmor ? (newItem?.Name ?? newReduxId) : null),
                CurrentArmorGlbUrl = carryPrevArmor ? state.CurrentArmorGlbUrl : presArmorGlb,
                CurrentArmorKind   = carryPrevArmor ? "library" : (presReduxHasArmor ? "redux" : null),
            });

            try { if (File.Exists(rollbackPath)) File.Delete(rollbackPath); } catch { }
            EmitInstallProgress(newReduxId, displayName, "done", 100, null);
            _ = ReduxIncrementDownloadsAsync(newReduxId);
            return new InjectResultDto(true, null, userUpdateRpf);
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[redux.install.preserve] CRASH: {ex.GetType().Name}: {ex.Message}\n{ex.StackTrace}");
            await TryRollbackAsync(userUpdateRpf, rollbackPath);
            EmitInstallProgress(newReduxId, displayName, "error", 0, ex.Message);
            return new InjectResultDto(false, $"{ex.GetType().Name}: {ex.Message}", null);
        }
        finally
        {
            try { if (Directory.Exists(sessionRoot)) Directory.Delete(sessionRoot, recursive: true); }
            catch (Exception ex) { Debug.WriteLine($"[redux.install.preserve] session cleanup failed: {ex.Message}"); }
        }
    }

    public Task<InjectResultDto> ReduxUninstallAsync()
        => ReduxUninstallInternalAsync(force: false, preserve: false);

    public Task<InjectResultDto> ReduxUninstallForceCleanAsync()
        => ReduxUninstallInternalAsync(force: true, preserve: false);

    public Task<InjectResultDto> ReduxUninstallPreserveAsync()
        => ReduxUninstallInternalAsync(force: false, preserve: true);

    private async Task<InjectResultDto> ReduxUninstallInternalAsync(bool force, bool preserve)
    {
        var state = ReadInstallState();
        if (state is null || string.IsNullOrWhiteSpace(state.ReduxId))
        {

            return new InjectResultDto(true, null, null);
        }

        var item = await _catalog.GetByIdAsync(state.ReduxId);
        var displayName = "Откат Redux: " + (item?.Name ?? state.ReduxId);

        EmitInstallProgress(state.ReduxId, displayName, "starting", 0, null,
            detailMessage: Loc.T("progress.redux.removing"));

        var gtaRoot = await GetGtaPathAsync();
        if (string.IsNullOrWhiteSpace(gtaRoot))
        {
            EmitInstallProgress(state.ReduxId, displayName, "error", 0, "GTA не найдена.");
            return new InjectResultDto(false, "GTA не найдена. Укажи путь в Admin → Settings → Paths.", null);
        }
        var updateRpf = Path.Combine(gtaRoot, "update", "update.rpf");
        if (!File.Exists(updateRpf))
        {

            DeleteInstallState();
            EmitInstallProgress(state.ReduxId, displayName, "done", 100, null);
            return new InjectResultDto(true, null, null);
        }

        var currentSha = await Task.Run(() => Services.FileShaCache.ComputeSha256Cached(updateRpf));
        var matchesLast = !string.IsNullOrWhiteSpace(state.PostInstallSha256)
            && string.Equals(currentSha, state.PostInstallSha256, StringComparison.OrdinalIgnoreCase);
        var matchesClean = await IsRpfCleanAsync(currentSha, gtaRoot);

        Debug.WriteLine($"[redux.uninstall] preflight: current={currentSha[..16]} matchesLast={matchesLast} matchesClean={matchesClean} force={force} preserve={preserve}");

        if (matchesClean)
        {

            DeleteInstallState();
            EmitInstallProgress(state.ReduxId, displayName, "done", 100, null);
            return new InjectResultDto(true, null, null);
        }

        if (!force && !preserve && !matchesLast)
        {

            EmitInstallProgress(state.ReduxId, displayName, "error", 0, DirtyFilesCardMessage);
            return new InjectResultDto(false, ERROR_DIRTY_FILES, null);
        }

        if (force || matchesLast)
        {

            EmitInstallProgress(state.ReduxId, displayName, "starting", 5, null, detailMessage: Loc.T("progress.redux.removing"));
            using var rampCts = new CancellationTokenSource();
            var ramp = StartProgressRamp(
                (phase, pct) => EmitInstallProgress(state.ReduxId, displayName, phase, pct, null,
                    detailMessage: Loc.T("progress.redux.removing")),
                "starting", 5, 95, 60, rampCts.Token);
            try
            {
                var ok = await RestoreCleanWithLockRetryAsync(gtaRoot, CancellationToken.None);
                rampCts.Cancel(); try { await ramp; } catch { }
                if (!ok)
                {
                    EmitInstallProgress(state.ReduxId, displayName, "error", 0, "Бэкап чистого update.rpf не найден.");
                    return new InjectResultDto(false,
                        "Бэкап чистого update.rpf не найден локально. Повтори backup в стартовом окне.", null);
                }
            }
            catch (Exception ex)
            {
                rampCts.Cancel(); try { await ramp; } catch { }
                var friendly = IsTransientFileLock(ex)
                    ? "Не удалось откатить: update.rpf занят другим процессом." + DescribeUpdateRpfLockState()
                    : $"Не удалось восстановить чистый update.rpf: {ex.Message}";
                EmitInstallProgress(state.ReduxId, displayName, "error", 0, friendly);
                return new InjectResultDto(false, friendly, null);
            }
            DeleteInstallState();
            EmitInstallProgress(state.ReduxId, displayName, "done", 100, null);
            return new InjectResultDto(true, null, null);
        }

        var cleanRpf = GetLocalCleanRpfPath();
        if (cleanRpf is null)
        {
            EmitInstallProgress(state.ReduxId, displayName, "error", 0, "Локальный clean update.rpf не найден.");
            return new InjectResultDto(false,
                "Локальный чистый update.rpf не найден в backup\\clean\\. Запусти полный backup в стартовом окне.", null);
        }

        var sessionRoot = Path.Combine(Path.GetTempPath(), "MiamiGraphics",
            $"uninstall_preserve_{Guid.NewGuid().ToString("N")[..8]}");
        Directory.CreateDirectory(sessionRoot);
        Debug.WriteLine($"[redux.uninstall.preserve] session={sessionRoot} lastReduxId='{state.ReduxId}'");

        var rollbackPath = updateRpf + ".preinstall";

        try
        {

            EmitInstallProgress(state.ReduxId, displayName, "restoring_old_state", 5, null);
            var fakeGtaRoot = Path.Combine(sessionRoot, "fake_gta");
            var fakeUpdateDir = Path.Combine(fakeGtaRoot, "update");
            Directory.CreateDirectory(fakeUpdateDir);
            var fakeUpdate = Path.Combine(fakeUpdateDir, "update.rpf");
            await CopyLargeFileWithProgressAsync(cleanRpf, fakeUpdate, state.ReduxId, displayName,
                "restoring_old_state", new ProgressBand(5, 12), "Готовлю рабочую копию update.rpf");

            EmitInstallProgress(state.ReduxId, displayName, "restoring_old_state", 12, null);
            var lastWorkDir = await EnsureReduxCachedAsync(state.ReduxId, state.VersionId,
                (phase, pct, detail) => EmitInstallProgress(state.ReduxId, displayName, "restoring_old_state", pct, null,
                    detailMessage: detail),
                progressBase: 12, progressSpan: 13);

            EmitInstallProgress(state.ReduxId, displayName, "restoring_old_state", 28, null);
            using (var rampCts1 = new CancellationTokenSource())
            {
                var ramp1 = StartProgressRamp(
                    (phase, pct) => EmitInstallProgress(state.ReduxId, displayName, "restoring_old_state", pct, null),
                    "restoring_old_state", 28, 38, 60, rampCts1.Token);
                var fakeEngine = new Core.Injector.RpfInjectEngine(fakeGtaRoot);
                var ok = await Task.Run(() => fakeEngine.InjectPatch(lastWorkDir));
                rampCts1.Cancel(); try { await ramp1; } catch { }
                if (!ok)
                {
                    var errorMessage = InjectFailureMessage(fakeEngine, Loc.T("errors.install.replayPrevFailed"));
                    EmitInstallProgress(state.ReduxId, displayName, "error", 0, errorMessage);
                    return new InjectResultDto(false,
                        errorMessage, sessionRoot);
                }
            }

            EmitInstallProgress(state.ReduxId, displayName, "computing_diff", 40, null);
            string userDiffWorkDir;
            using (var rampCts2 = new CancellationTokenSource())
            {
                var ramp2 = StartProgressRamp(
                    (phase, pct) => EmitInstallProgress(state.ReduxId, displayName, "computing_diff", pct, null),
                    "computing_diff", 40, 60, 30, rampCts2.Token);
                userDiffWorkDir = await Task.Run(() =>
                {
                    var pipeline = new Core.Parser.ReduxParserPipeline();
                    return pipeline.ParseRedux(fakeUpdate, updateRpf, $"user_diff_{Guid.NewGuid().ToString("N")[..8]}");
                });
                rampCts2.Cancel(); try { await ramp2; } catch { }
            }
            Debug.WriteLine($"[redux.uninstall.preserve] user_diff workDir={userDiffWorkDir}");

            await CopyLargeFileWithProgressAsync(updateRpf, rollbackPath, state.ReduxId, displayName,
                "applying_user_changes", new ProgressBand(60, 63), "Создаём точку восстановления");

            await CopyLargeFileWithProgressAsync(cleanRpf, updateRpf, state.ReduxId, displayName,
                "applying_user_changes", new ProgressBand(63, 65), "Ставлю чистый update.rpf");

            var realEngine = new Core.Injector.RpfInjectEngine(gtaRoot);
            using (var rampCts3 = new CancellationTokenSource())
            {
                var ramp3 = StartProgressRamp(
                    (phase, pct) => EmitInstallProgress(state.ReduxId, displayName, "applying_user_changes", pct, null),
                    "applying_user_changes", 65, 95, 60, rampCts3.Token);
                var diffOk = await Task.Run(() => realEngine.InjectPatch(userDiffWorkDir));
                rampCts3.Cancel(); try { await ramp3; } catch { }
                if (!diffOk)
                {
                    var errorMessage = InjectFailureMessage(realEngine, Loc.T("errors.install.userChangesFailed"));
                    await TryRollbackAsync(updateRpf, rollbackPath);
                    EmitInstallProgress(state.ReduxId, displayName, "error", 0, errorMessage);
                    return new InjectResultDto(false, errorMessage, null);
                }
            }

            try { if (File.Exists(rollbackPath)) File.Delete(rollbackPath); } catch { }
            DeleteInstallState();
            EmitInstallProgress(state.ReduxId, displayName, "done", 100, null);
            return new InjectResultDto(true, null, updateRpf);
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[redux.uninstall.preserve] CRASH: {ex.GetType().Name}: {ex.Message}\n{ex.StackTrace}");
            await TryRollbackAsync(updateRpf, rollbackPath);
            EmitInstallProgress(state.ReduxId, displayName, "error", 0, ex.Message);
            return new InjectResultDto(false, $"{ex.GetType().Name}: {ex.Message}", null);
        }
        finally
        {
            try { if (Directory.Exists(sessionRoot)) Directory.Delete(sessionRoot, recursive: true); }
            catch (Exception ex) { Debug.WriteLine($"[redux.uninstall.preserve] session cleanup failed: {ex.Message}"); }
        }
    }

    private static void DeleteInstallState()
    {
        try
        {
            var p = GetInstallStatePath();
            if (File.Exists(p)) File.Delete(p);
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[redux.uninstall] DeleteInstallState failed: {ex.Message}");
        }
    }

