        public CustomizationDraftDto? CustomizationDraft { get; set; }

        public string? CurrentArmorId { get; set; }
        public string? CurrentArmorName { get; set; }
        public string? CurrentArmorGlbUrl { get; set; }
        public string? CurrentArmorKind { get; set; }

        public string? CurrentSoundPackId { get; set; }
        public string? CurrentSoundPackName { get; set; }

        public List<string>? CurrentSoundPackFiles { get; set; }

        public string? CurrentSoundPackKind { get; set; }

        public string? CurrentSoundPackArchiveRel { get; set; }
    }

    private static string GetMinimapSavePath()
    {
        var localAppData = Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData);
        var dir = Path.Combine(localAppData, "MiamiGraphics", "config");
        Directory.CreateDirectory(dir);
        return Path.Combine(dir, "minimap_save.json");
    }

    public Task<MinimapSaveDto?> MinimapGetSaveAsync()
    {
        try
        {
            var p = GetMinimapSavePath();
            if (!File.Exists(p)) return Task.FromResult<MinimapSaveDto?>(null);
            var dto = System.Text.Json.JsonSerializer.Deserialize<MinimapSaveDto>(File.ReadAllText(p));
            return Task.FromResult(dto);
        }
        catch (Exception ex)
        {
            Core.System.FeatureLog.Write("миникарта", "сохранение не прочиталось", ex);
            return Task.FromResult<MinimapSaveDto?>(null);
        }
    }

    public Task<MinimapSaveDto> MinimapWriteSaveAsync(string name, MinimapTweaksDto tweaks)
    {
        var clean = string.IsNullOrWhiteSpace(name) ? "Моя миникарта" : name.Trim();
        if (clean.Length > 40) clean = clean.Substring(0, 40);
        var dto = new MinimapSaveDto(clean, DateTime.UtcNow.ToString("o"), tweaks);
        try
        {
            File.WriteAllText(GetMinimapSavePath(),
                System.Text.Json.JsonSerializer.Serialize(dto, new System.Text.Json.JsonSerializerOptions { WriteIndented = true }));
            Core.System.FeatureLog.Write("миникарта", $"сохранение записано: «{clean}»");
        }
        catch (Exception ex) { Core.System.FeatureLog.Write("миникарта", "сохранение не записалось", ex); }
        return Task.FromResult(dto);
    }

    public Task MinimapClearSaveAsync()
    {
        try
        {
            var p = GetMinimapSavePath();
            if (File.Exists(p)) File.Delete(p);
            Core.System.FeatureLog.Write("миникарта", "сохранение удалено");
        }
        catch (Exception ex) { Core.System.FeatureLog.Write("миникарта", "сохранение не удалилось", ex); }
        return Task.CompletedTask;
    }

    private static string GetInstallStatePath()
    {
        var localAppData = Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData);
        var dir = Path.Combine(localAppData, "MiamiGraphics");
        Directory.CreateDirectory(dir);
        return Path.Combine(dir, "install_state.json");
    }

    private static string? _lastGtaRoot;

    private static void ResealUpdateRpfSha()
    {
        try
        {
            var gtaRoot = _lastGtaRoot;
            if (string.IsNullOrWhiteSpace(gtaRoot)) return;

            var updateRpf = Path.Combine(gtaRoot, "update", "update.rpf");
            if (!File.Exists(updateRpf)) return;

            var st = ReadInstallState();
            if (st is null || string.IsNullOrWhiteSpace(st.PostInstallSha256)) return;

            var sha = Services.FileShaCache.ComputeSha256Cached(updateRpf);
            if (string.IsNullOrWhiteSpace(sha)
                || string.Equals(st.PostInstallSha256, sha, StringComparison.OrdinalIgnoreCase))
                return;

            st.PostInstallSha256 = sha;
            WriteInstallState(st);
            Debug.WriteLine($"[update.rpf] PostInstallSha256 re-sealed -> {sha[..16]}");
        }
        catch (Exception ex) { Debug.WriteLine($"[update.rpf] reseal FAILED (non-fatal): {ex.Message}"); }
    }

    private static InstallState? ReadInstallState()
    {
        try
        {
            var p = GetInstallStatePath();
            if (!File.Exists(p)) return null;
            return JsonSerializer.Deserialize<InstallState>(File.ReadAllText(p), new JsonSerializerOptions
            {
                PropertyNameCaseInsensitive = true,
            });
        }
        catch { return null; }
    }

    private static void WriteInstallState(InstallState state, bool preserveSoundPack = true)
    {
        if (preserveSoundPack && string.IsNullOrWhiteSpace(state.CurrentSoundPackId))
        {
            try
            {
                var prev = ReadInstallState();
                if (prev is not null && !string.IsNullOrWhiteSpace(prev.CurrentSoundPackId))
                {
                    state.CurrentSoundPackId    = prev.CurrentSoundPackId;
                    state.CurrentSoundPackName  = prev.CurrentSoundPackName;
                    state.CurrentSoundPackFiles = prev.CurrentSoundPackFiles;
                    state.CurrentSoundPackKind  = prev.CurrentSoundPackKind;
                }
            }
            catch {}
        }

        var p = GetInstallStatePath();
        File.WriteAllText(p, JsonSerializer.Serialize(state, new JsonSerializerOptions
        {
            WriteIndented = true,
        }));
    }

    private Services.InstallProgressGate? _progressGate;
    private readonly object _progressGateLock = new();

    private Services.InstallProgressGate ProgressGate
    {
        get
        {
            if (_progressGate is not null) return _progressGate;
            lock (_progressGateLock)
                return _progressGate ??= new Services.InstallProgressGate(SendInstallProgressRaw);
        }
    }

    private void SendInstallProgressRaw(string reduxId, string name, string phase, int percent,
                                        string? errorMessage, string? detailMessage)
    {
        _emitEvent?.Invoke("redux:installProgress", new
        {
            reduxId,
            name,
            phase,
            percent,
            errorMessage,

            detailMessage,
        });

        LogInstallPhase(reduxId, name, phase, percent, errorMessage, detailMessage);
    }

    private void EmitInstallProgress(string reduxId, string name, string phase, int percent, string? errorMessage, string? detailMessage = null)
    {
        ProgressGate.Admit(reduxId, name, phase, percent, errorMessage, detailMessage);
        LogFeatureProgress(reduxId, name, phase, percent, errorMessage, detailMessage);

        if (string.Equals(phase, "done", StringComparison.OrdinalIgnoreCase)
         || string.Equals(phase, "error", StringComparison.OrdinalIgnoreCase)
         || string.Equals(phase, "cancelled", StringComparison.OrdinalIgnoreCase))
        {
            Core.System.DataQuota.SweepInBackground($"после установки {name} ({phase})");

            Core.System.MemoryRelease.Trim($"после установки {name} ({phase})");
        }
    }

    private readonly Dictionary<string, string> _lastFeatureLogPhase = new(StringComparer.Ordinal);
    private readonly object _featureLogGate = new();

    private void LogFeatureProgress(string key, string name, string phase, int percent,
                                    string? errorMessage, string? detailMessage)
    {
        try
        {
            var scope = key switch
            {
                _ when key.StartsWith("reticle", StringComparison.OrdinalIgnoreCase) => "прицел",
                _ when key.StartsWith("minimap", StringComparison.OrdinalIgnoreCase) => "миникарта",
                _ when key.StartsWith("other-zalazy",   StringComparison.OrdinalIgnoreCase) => "залазы",
                _ when key.StartsWith("other-notracer", StringComparison.OrdinalIgnoreCase) => "трейсеры",
                _ when key.StartsWith("other-smoke",    StringComparison.OrdinalIgnoreCase) => "дым",
                _ when key.StartsWith("other-rukzak",   StringComparison.OrdinalIgnoreCase) => "рюкзаки",
                _ when key.StartsWith("other-backpack", StringComparison.OrdinalIgnoreCase) => "рюкзаки",
                _ when key.StartsWith("other",          StringComparison.OrdinalIgnoreCase) => "другое",
                _ => null,
            };
            if (scope is null) return;

            bool hasText = !string.IsNullOrWhiteSpace(errorMessage) || !string.IsNullOrWhiteSpace(detailMessage);
            lock (_featureLogGate)
            {
                var prev = _lastFeatureLogPhase.TryGetValue(key, out var p) ? p : null;
                bool phaseChanged = !string.Equals(prev, phase, StringComparison.Ordinal);
                if (!phaseChanged && !hasText) return;
                _lastFeatureLogPhase[key] = phase;
            }

            var sb = new global::System.Text.StringBuilder();
            sb.Append(name).Append(": ").Append(phase).Append(' ').Append(percent).Append('%');
            if (!string.IsNullOrWhiteSpace(detailMessage)) sb.Append(" - ").Append(detailMessage);
            if (!string.IsNullOrWhiteSpace(errorMessage)) sb.Append(" | ОШИБКА: ").Append(errorMessage);
            Core.System.FeatureLog.Write(scope, sb.ToString());
        }
        catch {}
    }

    private readonly Dictionary<string, string> _lastLoggedInstallPhase = new(StringComparer.Ordinal);
    private readonly object _installLogGate = new();

    private void LogInstallPhase(string reduxId, string name, string phase, int percent, string? errorMessage, string? detailMessage)
    {
        try
        {
            var key = reduxId ?? string.Empty;
            bool isError = string.Equals(phase, "error", StringComparison.OrdinalIgnoreCase);
            bool isTerminal = isError
                || string.Equals(phase, "done", StringComparison.OrdinalIgnoreCase)
                || string.Equals(phase, "cancelled", StringComparison.OrdinalIgnoreCase);

            lock (_installLogGate)
            {
                if (!isError
                    && _lastLoggedInstallPhase.TryGetValue(key, out var prev)
                    && string.Equals(prev, phase, StringComparison.Ordinal))
                    return;

                _lastLoggedInstallPhase[key] = phase;
                if (isTerminal) _lastLoggedInstallPhase.Remove(key);
            }

            var detail = errorMessage ?? detailMessage;
            var suffix = string.IsNullOrWhiteSpace(detail) ? string.Empty : $" - {detail}";
            var msg = $"{reduxId} \"{name}\" -> {phase} {percent}%{suffix}";

            if (isError) Services.SessionLog.Error("install", msg);
            else Services.SessionLog.Info("install", msg);
        }
        catch {}
    }

    private sealed class FavRow
    {
        public string ReduxId { get; set; } = string.Empty;
    }

    private sealed class CounterRow
    {
        public long DownloadCount { get; set; }
    }

    private sealed class NoopDisposable : IDisposable
    {
        public static readonly NoopDisposable Instance = new();
        public void Dispose() { }
    }

    public Task<InjectResultDto> ReduxCustomizeApplyAsync(string reduxId, CustomizationDraftDto draft)
        => ReduxCustomizeApplyAsync(reduxId, draft, null, null);

    public async Task<InjectResultDto> ReduxCustomizeApplyAsync(
        string reduxId,
        CustomizationDraftDto draft,
        string? progressKeyOverride,
        string? progressDisplayOverride,
        bool alreadyLocked = false)
    {
        using var _mtx = alreadyLocked
            ? (IDisposable)NoopDisposable.Instance
            : await MiamiGraphics.Shell.Services.UpdateRpfMutex.AcquireAsync($"redux-customize:{reduxId}");
        var item = await _catalog.GetByIdAsync(reduxId);
        var displayName = progressDisplayOverride ?? ("Кастомизация Redux: " + (item?.Name ?? reduxId));
        var progressKey = progressKeyOverride ?? reduxId;

        var progressDisplay = displayName;

        EmitInstallProgress(progressKey, progressDisplay, "starting", 0, null);

        var gtaRoot = await GetGtaPathAsync();
        if (string.IsNullOrWhiteSpace(gtaRoot))
        {
            EmitInstallProgress(progressKey, progressDisplay, "error", 0, "GTA не найдена.");
            return new InjectResultDto(false, "GTA не найдена. Укажи путь в Admin → Settings → Paths.", null);
        }
        var updateRpf = Path.Combine(gtaRoot, "update", "update.rpf");

        string? prevStandaloneArmorId = null;
        try
        {
            var prevState = ReadInstallState();
            if (prevState is not null
                && string.Equals(prevState.CurrentArmorKind, "library", StringComparison.OrdinalIgnoreCase)
                && !string.IsNullOrWhiteSpace(prevState.CurrentArmorId))
                prevStandaloneArmorId = prevState.CurrentArmorId;
        }
        catch {}

        if (item is null)
        {
            EmitInstallProgress(progressKey, progressDisplay, "error", 0, "redux not found");
            return new InjectResultDto(false, $"Редукс '{reduxId}' не найден в каталоге.", null);
        }

        var resolved = await ResolveVersionAsync(reduxId, draft.BaseVersionId);
        if (resolved is null)
        {
            EmitInstallProgress(progressKey, progressDisplay, "error", 0, "redux not found");
            return new InjectResultDto(false, $"Редукс '{reduxId}' не найден в каталоге.", null);
        }
        if (string.IsNullOrWhiteSpace(resolved.Urls.Patch) || string.IsNullOrWhiteSpace(resolved.Urls.Manifest))
        {
            EmitInstallProgress(progressKey, progressDisplay, "error", 0, "no R2 urls");
            return new InjectResultDto(false,
                resolved.IsLegacy
                    ? "У этого редукса нет R2-ссылок на patch.zip / manifest.json. Перезалей с галкой R2."
                    : $"Версия '{resolved.Label}' (slot {resolved.Slot}) не имеет patch.zip на R2. Перезалей с галкой R2.",
                null);
        }

        const int CZ_PREFLIGHT_TO = 3;
        const int CZ_AUTOBACKUP_TO = 16;
        const int CZ_RESTORE_TO    = 24;
        const int CZ_DOWNLOAD_TO   = 36;
        int czFloor = 5;

        EmitInstallProgress(progressKey, progressDisplay, "starting", 1, null,
            detailMessage: Loc.T("progress.common.preparingInstall"));
        using var preflightCts = new CancellationTokenSource();
        var preflightRamp = StartProgressRamp(
            (phase, percent) => EmitInstallProgress(progressKey, progressDisplay, phase, percent, null,
                detailMessage: Loc.T("progress.common.preparingInstall")),
            "starting", 1, CZ_PREFLIGHT_TO, 60, preflightCts.Token);

        bool restoreFromCleanFirst = false;
        if (File.Exists(updateRpf))
        {
            try
            {
                preflightCts.Cancel();
                var czPreflight = new ProgressBand(1, CZ_PREFLIGHT_TO);
                var czLive      = czPreflight.Slice(0, 65);
                var czClean     = czPreflight.Slice(65, 100);
                var currentSha = await Task.Run(() => Services.FileShaCache.ComputeSha256Cached(updateRpf,
                    (done, total) => EmitInstallProgress(progressKey, progressDisplay, "starting",
                        czLive.MapBytes(done, total), null,
                        detailMessage: Loc.T("progress.common.verifyingUpdateRpfMb",
                            ("done", done / 1024 / 1024), ("total", Math.Max(1, total / 1024 / 1024))))));
                var state = ReadInstallState();
                var matchesLast = state?.PostInstallSha256 is { } lastSha
                    && string.Equals(currentSha, lastSha, StringComparison.OrdinalIgnoreCase);
                var matchesClean = await IsRpfCleanAsync(currentSha, gtaRoot,
                    (done, total) => EmitInstallProgress(progressKey, progressDisplay, "starting",
                        czClean.MapBytes(done, total), null,
                        detailMessage: Loc.T("progress.common.comparingWithCleanMb",
                            ("done", done / 1024 / 1024), ("total", Math.Max(1, total / 1024 / 1024)))));

                Debug.WriteLine($"[redux.customize] preflight: current={currentSha[..16]} matchesLast={matchesLast} matchesClean={matchesClean} firstInstall={state is null}");
                if (!matchesLast && !matchesClean)
                {

                    if (GetLocalCleanRpfPath() is not null)
                    {
                        var reason = state is null ? "first-ever install" : "stale state (likely GTA auto-update)";
                        Debug.WriteLine($"[redux.customize] preflight: {reason} + local clean cache - auto-promoting to restore-clean");
                        restoreFromCleanFirst = true;
                    }
                    else
                    {
                        preflightCts.Cancel();
                        if (await TryFetchCleanViaBackupAsync(gtaRoot, progressKey, progressDisplay,
                                new ProgressBand(CZ_PREFLIGHT_TO, CZ_AUTOBACKUP_TO)))
                        {
                            Debug.WriteLine("[redux.customize] preflight: clean cache fetched on the fly - auto-promoting to restore-clean");
                            restoreFromCleanFirst = true;
                            czFloor = CZ_AUTOBACKUP_TO;
                        }
                        else
                        {
                            EmitInstallProgress(progressKey, progressDisplay, "error", 0, DirtyFilesCardMessage);
                            return new InjectResultDto(false, ERROR_DIRTY_FILES, null);
                        }
                    }
                }
                else if (matchesLast && !matchesClean)
                {
                    Debug.WriteLine("[redux.customize] preflight: matches lastInstall - will auto-restore clean before customize inject");
                    restoreFromCleanFirst = true;
                }
            }
            catch (Exception ex) { Debug.WriteLine($"[redux.customize] preflight skipped: {ex.Message}"); }
        }

        if (restoreFromCleanFirst)
        {
            preflightCts.Cancel();
            var czRestoreBand = new ProgressBand(czFloor, CZ_RESTORE_TO);
            long czCleanBytes = 0;
            try { if (GetLocalCleanRpfPath() is { } czSrc) czCleanBytes = new FileInfo(czSrc).Length; }
            catch { }
            Action<int> czRestoreEmit = pct => EmitInstallProgress(progressKey, progressDisplay, "starting",
                czRestoreBand.Map(pct), null,
                detailMessage: czCleanBytes > 0
                    ? Loc.T("progress.common.restoringCleanRpfMb",
                        ("done", (long)(czCleanBytes * (pct / 100.0)) / 1024 / 1024), ("total", czCleanBytes / 1024 / 1024))
                    : Loc.T("progress.common.restoringCleanRpf"));

            try
            {
                var ok = await _backupService.RestoreFromCleanAsync(gtaRoot, CancellationToken.None, czRestoreEmit);
                czFloor = CZ_RESTORE_TO;
                if (!ok)
                {
                    preflightCts.Cancel();
                    EmitInstallProgress(progressKey, progressDisplay, "error", 0,
                        "Бэкап чистого update.rpf не найден локально. Повтори backup в стартовом окне.");
                    return new InjectResultDto(false,
                        "Бэкап чистого update.rpf не найден локально. Повтори backup в стартовом окне " +
                        "или используй Admin → Injector → 'Восстановить чистый update.rpf'.", null);
                }
            }
            catch (Exception rex)
            {
                preflightCts.Cancel();
                EmitInstallProgress(progressKey, progressDisplay, "error", 0, rex.Message);
                return new InjectResultDto(false, $"Не удалось восстановить чистый update.rpf: {rex.Message}", null);
            }
        }
        preflightCts.Cancel();
        try { await preflightRamp; } catch { }

        var czReserve = await Task.Run(() => Core.System.DataQuota.TryReserve(
            resolved.PatchSizeBytes > 0 ? resolved.PatchSizeBytes * 2 : 0,
            $"сборка редукса {reduxId}"));
        if (!czReserve.Ok)
        {
            EmitInstallProgress(progressKey, progressDisplay, "error", 0, czReserve.Message);
            return new InjectResultDto(false, czReserve.Message, null);
        }

        var cfg = await _adminConfig.GetAsync();
        var baseDir = !string.IsNullOrWhiteSpace(cfg.WorkDirOverride) && Directory.Exists(cfg.WorkDirOverride)
            ? cfg.WorkDirOverride!
            : Core.System.AppDataRoot.WorkRoot;
        Directory.CreateDirectory(baseDir);
        var workDir = Path.Combine(baseDir, $"customize_inject_{reduxId}_{DateTime.Now:yyyyMMdd_HHmmss}");
        PurgeStaleWorkDirs(baseDir, "customize_inject_", workDir,
            legacyTempRoot: Path.Combine(Path.GetTempPath(), "MiamiGraphics", "customize_inject"));
        Directory.CreateDirectory(workDir);
        var patchFilesDir = Path.Combine(workDir, "patch_files");
        Directory.CreateDirectory(patchFilesDir);

        Debug.WriteLine($"[redux.customize] reduxId='{reduxId}' workDir='{workDir}'");

        var totalSw    = System.Diagnostics.Stopwatch.StartNew();
        var downloadSw = new System.Diagnostics.Stopwatch();
        var applySw    = new System.Diagnostics.Stopwatch();
        var injectSw   = new System.Diagnostics.Stopwatch();

        try
        {
            using var http = HttpClientFactory.CreateFragmenting(TimeSpan.FromMinutes(15));

            var czDownloadBand = new ProgressBand(czFloor, CZ_DOWNLOAD_TO);
            var czShaBand      = new ProgressBand(CZ_DOWNLOAD_TO, CZ_DOWNLOAD_TO + 2);

            EmitInstallProgress(progressKey, progressDisplay, "downloading", czDownloadBand.From, null,
                detailMessage: Loc.T("progress.build.downloadingFiles"));

            downloadSw.Start();
            var basePatchZip = Path.Combine(workDir, "patch.zip");

            string patchCacheRoot = MiamiGraphics.Shell.Services.ModCacheSettings.Dir("redux_patches");
            string? patchCachePath = !string.IsNullOrWhiteSpace(resolved.PatchSha256)
                ? Path.Combine(patchCacheRoot, $"{reduxId}_{resolved.PatchSha256[..Math.Min(16, resolved.PatchSha256.Length)]}.zip")
                : null;

            Services.VerifiedDownload.RequireReference(resolved.PatchSha256, $"patch.zip редукса «{reduxId}»");

            async Task<bool> BaseMatchesShaAsync(ProgressBand shaBand)
            {
                var actualSha = await Task.Run(() => ComputeFileSha256(basePatchZip,
                    (done, total) => EmitInstallProgress(progressKey, progressDisplay, "verifying",
                        shaBand.MapBytes(done, total), null,
                        detailMessage: Loc.T("progress.common.verifyingFilesMb",
                            ("done", done / 1024 / 1024), ("total", Math.Max(1, total / 1024 / 1024))))));
                return string.Equals(actualSha, resolved.PatchSha256, StringComparison.OrdinalIgnoreCase);
            }

            bool verified = false;

            if (MiamiGraphics.Shell.Services.ModCacheSettings.ReuseEnabled
                && patchCachePath is not null && File.Exists(patchCachePath))
            {
                try
                {
                    EmitInstallProgress(progressKey, progressDisplay, "downloading", czDownloadBand.To, null,
                        detailMessage: Loc.T("progress.build.cacheHit"));
                    File.Copy(patchCachePath, basePatchZip, overwrite: true);
                    if (await BaseMatchesShaAsync(czShaBand))
                    {
                        Debug.WriteLine($"[redux.customize] patch.zip cache hit (verified) at {patchCachePath}");
                        verified = true;
                    }
                    else
                    {
                        Debug.WriteLine($"[redux.customize] cached patch.zip FAILED sha - purging poisoned cache {patchCachePath}");
                        try { File.Delete(patchCachePath); } catch { }
                    }
                }
                catch (Exception cacheEx)
                {
                    Debug.WriteLine($"[redux.customize] patch.zip cache copy failed ({cacheEx.Message}) - falling back to download");
                }
            }

            if (!verified)
            {
                await DownloadFileAsync(http, resolved.Urls.Patch!, basePatchZip,
                    bytesProgress: (received, total) =>
                    {
                        if (total > 0)
                            EmitInstallProgress(progressKey, progressDisplay, "downloading",
                                czDownloadBand.MapBytes(received, total), null,
                                detailMessage: Loc.T("progress.common.downloadMb",
                                    ("done", received / 1024 / 1024), ("total", total / 1024 / 1024)));
                    });

                EmitInstallProgress(progressKey, progressDisplay, "verifying", czShaBand.From, null,
                    detailMessage: Loc.T("progress.common.verifyingFiles"));
                if (!await BaseMatchesShaAsync(czShaBand))
                {
                    try { File.Delete(basePatchZip); } catch { }
                    EmitInstallProgress(progressKey, progressDisplay, "error", 0, "patch sha mismatch");
                    return new InjectResultDto(false,
                        "patch.zip редукса не прошёл проверку целостности и удалён - установка отменена. " +
                        "Повтори попытку, а если повторится - сообщи админу.", workDir);
                }

                if (patchCachePath is not null)
                {
                    try
                    {
                        File.Copy(basePatchZip, patchCachePath, overwrite: true);
                        Debug.WriteLine($"[redux.customize] patch.zip cached (verified) to {patchCachePath}");
                    }
                    catch (Exception saveEx)
                    {
                        Debug.WriteLine($"[redux.customize] patch.zip cache save failed: {saveEx.Message}");
                    }
                }
            }

            var unzipBand = new ProgressBand(czShaBand.To, 40);
            EmitInstallProgress(progressKey, progressDisplay, "extracting", unzipBand.From, null,
                detailMessage: Loc.T("progress.build.extracting"));
            await Task.Run(() => ExtractZipWithProgress(basePatchZip, patchFilesDir,
                (i, total, name) => EmitInstallProgress(progressKey, progressDisplay, "extracting",
                    total > 0 ? unzipBand.From + (int)((long)unzipBand.Width * i / total) : unzipBand.From, null,
                    detailMessage: Loc.T("progress.build.extractingCount", ("done", i), ("total", total))
                        + (string.IsNullOrEmpty(name) ? "" : $" ({name})"))));

            EmitInstallProgress(progressKey, progressDisplay, "downloading", 40, null,
                detailMessage: Loc.T("progress.build.downloadingManifest"));
            var assetShasBase = await ReduxAssetShasAsync(resolved.VersionId);
            await Services.VerifiedDownload.FetchAsync(resolved.Urls.Manifest!,
                Path.Combine(workDir, "manifest.json"), assetShasBase.Manifest,
                "manifest.json базы редукса", referenceRequired: false);
            if (!string.IsNullOrWhiteSpace(resolved.Urls.ComponentMap))
                await Services.VerifiedDownload.FetchAsync(resolved.Urls.ComponentMap!,
                    Path.Combine(workDir, "component_map.json"), assetShasBase.ComponentMap,
                    "component_map.json базы редукса", referenceRequired: false);
            if (!string.IsNullOrWhiteSpace(resolved.Urls.ContentInfo))
                await Services.VerifiedDownload.FetchAsync(resolved.Urls.ContentInfo!,
                    Path.Combine(workDir, "content_info.json"), assetShasBase.ContentInfo,
                    "content_info.json базы редукса", referenceRequired: false);

            downloadSw.Stop();
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[redux.customize] base download/extract FAIL: {ex.Message}");
            EmitInstallProgress(progressKey, progressDisplay, "error", 0, ex.Message);
            return new InjectResultDto(false, $"Ошибка загрузки базы: {ex.Message}", workDir);
        }

        var manifestPath = Path.Combine(workDir, "manifest.json");
        Core.Parser.DiffManifest manifest;
        try
        {
            manifest = JsonSerializer.Deserialize<Core.Parser.DiffManifest>(
                await File.ReadAllTextAsync(manifestPath), ReduxJson)
                ?? throw new InvalidOperationException("manifest.json couldn't be parsed");
        }
        catch (Exception ex)
        {
            EmitInstallProgress(progressKey, progressDisplay, "error", 0, "bad manifest");
            return new InjectResultDto(false, $"Не удалось прочитать manifest.json: {ex.Message}", workDir);
        }

        var skippedNotes = new List<string>();
        var importFailures = new List<string>();
        var donorSelections = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        byte[]? donorMinimapBaseBytes = null;

        Action<string, int, string?> emitDetail = (phase, pct, detail) =>
            EmitInstallProgress(progressKey, progressDisplay, phase, pct, null, detailMessage: detail);

        try
        {
            using var http = HttpClientFactory.CreateFragmenting(TimeSpan.FromMinutes(15));

            emitDetail("downloading_new", 42, Loc.T("progress.build.preparingComponents"));

            applySw.Start();

            emitDetail("applying_user_changes", 43, Loc.T("progress.minimap.applying"));
            var minimapOk = await ApplyMinimapCustomizationAsync(workDir, manifest, gtaRoot, draft.Minimap, http, skippedNotes, importFailures, emitDetail,
                onDonorBase: b => donorMinimapBaseBytes = b);

            emitDetail("applying_user_changes", 48, Loc.T("progress.tracers.applying"));
            var tracersOk = await ApplyTracersCustomizationAsync(workDir, manifest, draft.Tracers, http, skippedNotes, importFailures, emitDetail);

            emitDetail("applying_user_changes", 51, Loc.T("progress.armor.applying"));
            var armorOk = await ApplyArmorCustomizationAsync(workDir, manifest, draft.Armor, http, skippedNotes, importFailures, emitDetail);

            emitDetail("applying_user_changes", 54, Loc.T("progress.arena.applying"));
            var arenaOk = await ApplyArenaCustomizationAsync(workDir, manifest, draft.Arena, http, skippedNotes, importFailures, emitDetail);

            Debug.WriteLine($"[redux.customize] component apply results: minimap={minimapOk}, tracers={tracersOk}, armor={armorOk}, arena={arenaOk}, importFailures={importFailures.Count}");

            emitDetail("applying_user_changes", 56, Loc.T("progress.reticle.applying"));
            bool crosshairHandled = await ApplyCrosshairCustomizationAsync(
                workDir, manifest, gtaRoot, draft.Crosshair, http, skippedNotes, emitDetail);

            emitDetail("downloading_new", 59, Loc.T("progress.build.preparingEffects"));
            var draftForGeneric = crosshairHandled
                ? draft with { Crosshair = new GenericSettingDto("default", null, null, null) }
                : draft;
            await ApplyGenericCrossInjectsAsync(workDir, donorSelections, draftForGeneric, http, skippedNotes, emitDetail);

            applySw.Stop();
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[redux.customize] apply CRASH: {ex.GetType().Name}: {ex.Message}\n{ex.StackTrace}");
            EmitInstallProgress(progressKey, progressDisplay, "error", 0, ex.Message);
            return new InjectResultDto(false, $"Ошибка применения: {ex.Message}", workDir);
        }

        try
        {
            Core.Services.PatchCustomizationSupport.RecalculateTotalPatchSize(manifest);
            await File.WriteAllTextAsync(manifestPath,
                JsonSerializer.Serialize(manifest, new JsonSerializerOptions
                {
                    WriteIndented = true,
                    PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
                    DefaultIgnoreCondition = JsonIgnoreCondition.WhenWritingNull,
                }));
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[redux.customize] manifest write FAIL: {ex.Message}");
        }

        string finalDir = workDir;
        if (donorSelections.Count > 0)
        {
            EmitInstallProgress(progressKey, progressDisplay, "applying_user_changes", 63, null);
            try
            {
                var crossInject = new Core.Injector.CrossInjectBuilder();
                finalDir = await Task.Run(() => crossInject.BuildCrossInjectedPatch(workDir, donorSelections));
                Debug.WriteLine($"[redux.customize] cross-inject merged {donorSelections.Count} component(s) → {finalDir}");
            }
            catch (Exception ex)
            {
                Debug.WriteLine($"[redux.customize] CrossInjectBuilder FAIL: {ex.Message}");
                skippedNotes.Add($"[Кросс-инжект] Сбой: {ex.Message}. Применил остальное без cross-inject.");
                finalDir = workDir;
            }
        }

        var spaceError = PreflightUpdateRpfSpace(updateRpf, "кастомизация");
        if (spaceError != null)
        {
            EmitInstallProgress(progressKey, progressDisplay, "error", 0, spaceError);
            return new InjectResultDto(false, spaceError, null);
        }

        var rollbackPath = updateRpf + ".preinstall";
        await MakeRollbackPointAsync(updateRpf, rollbackPath, progressKey, progressDisplay,
            "applying_user_changes", new ProgressBand(63, 65), "redux.customize");

        EmitInstallProgress(progressKey, progressDisplay, "injecting", 65, null);

        using var rampCts = new CancellationTokenSource();
        var ramp = StartProgressRamp(
            (phase, percent) => EmitInstallProgress(progressKey, progressDisplay, phase, percent, null),
            "injecting", 65, 95, 60, rampCts.Token);

        try
        {
            return await Task.Run(() =>
            {
                try
                {
                    var engine = new Core.Injector.RpfInjectEngine(gtaRoot);
                    var ok = engine.InjectPatch(finalDir);
                    Debug.WriteLine($"[redux.customize] InjectPatch (finalDir={finalDir}) returned {ok}");

                    if (!ok)
                    {
                        var errorMessage = InjectFailureMessage(engine, Loc.T("errors.install.injectPatchFalse"));
                        TryRollbackAsync(updateRpf, rollbackPath).GetAwaiter().GetResult();
                        EmitInstallProgress(progressKey, progressDisplay, "error", 0, errorMessage);
                        return new InjectResultDto(false, errorMessage, finalDir);
                    }

                    try
                    {
                        var postSha = Services.FileShaCache.ComputeSha256Cached(updateRpf);

                        string? curArmorId = null, curArmorName = null, curArmorGlb = null, curArmorKind = null;
                        try
                        {

                            var aDraft = draft.Armor;
                            if (aDraft is not null && aDraft.Kind == "import" && !string.IsNullOrWhiteSpace(aDraft.DonorReduxId))
                            {
                                var donor = _catalog.GetByIdAsync(aDraft.DonorReduxId!).GetAwaiter().GetResult();
                                if (donor is not null)
                                {
                                    curArmorId = donor.Id;
                                    curArmorName = donor.Name;

                                    curArmorGlb = ResolveArmorGlbUrlAsync(donor, donor.Id, aDraft.DonorVersionId)
                                                  .GetAwaiter().GetResult();
                                    curArmorKind = "redux";
                                }
                            }
                            else if (aDraft is null || aDraft.Kind == "default")
                            {

                                bool baseHasArmor = item?.Components is not null
                                    && item.Components.TryGetValue("armor", out var bA)
                                    && bA is not null && bA.IsFound;
                                if (baseHasArmor)
                                {
                                    curArmorId = reduxId;
                                    curArmorName = item?.Name ?? reduxId;
                                    curArmorGlb = ResolveArmorGlbUrlAsync(item, reduxId, draft.BaseVersionId ?? resolved.VersionId)
                                                  .GetAwaiter().GetResult();
                                    curArmorKind = "redux";
                                }
                            }
                        }
                        catch (Exception ex2) { Debug.WriteLine($"[redux.customize] armor identity resolution failed: {ex2.Message}"); }

                        WriteInstallState(new InstallState
                        {
                            ReduxId = reduxId,
                            VersionId = draft.BaseVersionId ?? resolved.VersionId,
                            PostInstallSha256 = postSha,
                            InstalledAt = DateTime.UtcNow,
                            CustomizationDraft = draft,
                            CurrentArmorId     = curArmorId,
                            CurrentArmorName   = curArmorName,
                            CurrentArmorGlbUrl = curArmorGlb,
                            CurrentArmorKind   = curArmorKind,
                        });
                        Debug.WriteLine($"[redux.customize] lastInstall saved: {postSha[..16]} (with customize draft)");
                    }
                    catch (Exception ex)
                    {
                        Debug.WriteLine($"[redux.customize] lastInstall save FAILED: {ex.Message}");
                    }

                    string? armorLibOverlayId =
                        (draft.Armor?.Kind == "armorLibrary" && !string.IsNullOrWhiteSpace(draft.Armor.ArmorLibraryId))
                            ? draft.Armor.ArmorLibraryId
                            : (draft.Armor is null || draft.Armor.Kind == "default")
                                ? prevStandaloneArmorId
                                : null;
                    if (!string.IsNullOrWhiteSpace(armorLibOverlayId))
                    {
                        try
                        {
                            EmitInstallProgress(progressKey, progressDisplay, "applying_user_changes", 95, null,
                                detailMessage: Loc.T("progress.armor.applyingOverlay"));
                            var ar = ArmorLibraryInstallAsync(armorLibOverlayId!, overlayMode: true, force: true, alreadyLocked: true)
                                     .GetAwaiter().GetResult();
                            if (ar.Success)
                                Debug.WriteLine($"[redux.customize] applied armor_library overlay '{armorLibOverlayId}' over rebuild");
                            else
                                Debug.WriteLine($"[redux.customize] armor_library overlay '{armorLibOverlayId}' FAILED: {ar.ErrorMessage}");
                        }
                        catch (Exception exA) { Debug.WriteLine($"[redux.customize] armor overlay EXCEPTION: {exA.Message}"); }
                    }

                    try { ReapplyZalazyIfEnabledAsync(updateRpf).GetAwaiter().GetResult(); }
                    catch (Exception exZ) { Debug.WriteLine($"[redux.customize] zalazy re-apply EXCEPTION: {exZ.Message}"); }
                    try { ReapplyGreenZoneIfEnabledAsync(updateRpf).GetAwaiter().GetResult(); }
                    catch (Exception exG) { Debug.WriteLine($"[redux.customize] greenzone re-apply EXCEPTION: {exG.Message}"); }
                    try { ReapplyRukzakIfEnabledAsync(updateRpf).GetAwaiter().GetResult(); }
                    catch (Exception exRk) { Debug.WriteLine($"[redux.customize] rukzak re-apply EXCEPTION: {exRk.Message}"); }
                    try { ReapplyCarLogosIfEnabledAsync(updateRpf).GetAwaiter().GetResult(); }
                    catch (Exception exCl) { Debug.WriteLine($"[redux.customize] carlogos re-apply EXCEPTION: {exCl.Message}"); }
                    try { ReapplyFastJoinIfEnabledAsync(updateRpf).GetAwaiter().GetResult(); }
                    catch (Exception exF) { Debug.WriteLine($"[redux.customize] fastjoin re-apply EXCEPTION: {exF.Message}"); }
                    try { ReapplyBigMapIfEnabledAsync(updateRpf).GetAwaiter().GetResult(); }
                    catch (Exception exM) { Debug.WriteLine($"[redux.customize] bigmap re-apply EXCEPTION: {exM.Message}"); }
                    try { FixUpdateRpfAfterOverlayReapplyAsync(updateRpf).GetAwaiter().GetResult(); }
                    catch (Exception exFix) { Debug.WriteLine($"[redux.customize] overlay ArchiveFix EXCEPTION: {exFix.Message}"); }

                    if (donorMinimapBaseBytes is not null)
                    {
                        try
                        {
                            var mmKeyPath = ResolveLiveMinimapGfxPath(gtaRoot);
                            var mmLive = mmKeyPath is null
                                ? null
                                : Core.Services.PatchCustomizationSupport.GetBytesFromArchiveExactPath(updateRpf, mmKeyPath);
                            if (mmKeyPath is not null && mmLive is not null)
                            {
                                SaveMinimapTweakBase(donorMinimapBaseBytes, mmLive, mmKeyPath);
                                Debug.WriteLine($"[redux.customize] minimap tweak base refreshed after rebuild (key='{mmKeyPath}')");
                            }
                        }
                        catch (Exception exMm) { Debug.WriteLine($"[redux.customize] minimap tweak-base refresh EXCEPTION: {exMm.Message}"); }
                    }
                    try { ReapplySmokeIfEnabledAsync(gtaRoot).GetAwaiter().GetResult(); }
                    catch (Exception exS) { Debug.WriteLine($"[redux.customize] smoke re-apply EXCEPTION: {exS.Message}"); }
                    try { ReapplyNoTracerIfEnabledAsync(gtaRoot).GetAwaiter().GetResult(); }
                    catch (Exception exT) { Debug.WriteLine($"[redux.customize] notracer re-apply EXCEPTION: {exT.Message}"); }
                    try { ReapplyTracerStudioIfEnabledAsync(gtaRoot).GetAwaiter().GetResult(); }
                    catch (Exception exTs) { Debug.WriteLine($"[redux.customize] tracerstudio re-apply EXCEPTION: {exTs.Message}"); }
                    try { ReapplyImprovementsIfAnyAsync(gtaRoot).GetAwaiter().GetResult(); }
                    catch (Exception exI) { Debug.WriteLine($"[redux.customize] improvements re-apply EXCEPTION: {exI.Message}"); }

                    var msg = skippedNotes.Count == 0
                        ? "Кастомизация применена."
                        : $"Готово. Заметки:\n• " + string.Join("\n• ", skippedNotes);

                    EmitInstallProgress(progressKey, progressDisplay, "done", 100, null);
                    try { if (File.Exists(rollbackPath)) File.Delete(rollbackPath); } catch { }

                    if (importFailures.Count > 0)
                    {
                        var failMsg = "Кастомизация частично не применилась:\n• " + string.Join("\n• ", importFailures);
                        Debug.WriteLine($"[redux.customize] returning success=false due to {importFailures.Count} import failures");
                        return new InjectResultDto(false, failMsg, finalDir);
                    }

                    return new InjectResultDto(true, msg, finalDir);
                }
                catch (Exception ex)
                {
                    Debug.WriteLine($"[redux.customize] inject CRASH: {ex.GetType().Name}: {ex.Message}\n{ex.StackTrace}");
                    TryRollbackAsync(updateRpf, rollbackPath).GetAwaiter().GetResult();
                    EmitInstallProgress(progressKey, progressDisplay, "error", 0, ex.Message);
                    return new InjectResultDto(false, $"{ex.GetType().Name}: {ex.Message}", finalDir);
                }
            });
        }
        finally
        {
            rampCts.Cancel();
            try { await ramp; } catch { }
        }
    }

    private async Task<bool> ApplyMinimapCustomizationAsync(
        string workDir,
        Core.Parser.DiffManifest manifest,
        string gtaRoot,
        MinimapSettingDto m,
        System.Net.Http.HttpClient http,
        List<string> notes,
        List<string> importFailures,
        Action<string, int, string?>? emitDetail = null,
        Action<byte[]>? onDonorBase = null)
    {

        if (!m.Enabled
            && m.Tweaks is null
            && m.RangeRingsMeters is not { Length: > 0 }
            && string.IsNullOrWhiteSpace(m.LibraryItemId)
            && string.IsNullOrWhiteSpace(m.ImportedFromReduxId))
            return true;

        await ApplyMinimapLayoutAsync(workDir, manifest, gtaRoot, m, notes, emitDetail);

        bool importRequested =
            !string.IsNullOrWhiteSpace(m.LibraryItemId) ||
            !string.IsNullOrWhiteSpace(m.ImportedFromReduxId);
        bool importSucceeded = false;

        bool TryDeliverDonorMinimapGfx(byte[] donorBytes, Core.Parser.DiffManifest mf)
        {
            int delivered = 0;

            if (Core.Services.PatchCustomizationSupport
                .TryReplaceNestedComponentFile(workDir, "minimap", "minimap.gfx", donorBytes))
            {
                delivered++;
                Debug.WriteLine("[redux.customize][minimap] tier1: component-file replace OK");
            }

            foreach (var act in mf.Actions ?? new List<Core.Parser.PatchAction>())
            {
                var src = act.SourcePath;
                var tgt = act.TargetPath;
                if (string.IsNullOrWhiteSpace(src) || string.IsNullOrWhiteSpace(tgt)) continue;
                if (!tgt.EndsWith("minimap.gfx", StringComparison.OrdinalIgnoreCase)) continue;
                try
                {

                    var abs = Path.Combine(workDir, src.Replace('/', Path.DirectorySeparatorChar));
                    Directory.CreateDirectory(Path.GetDirectoryName(abs)!);
                    File.WriteAllBytes(abs, donorBytes);
                    Debug.WriteLine($"[redux.customize][minimap] tier2: wrote donor minimap.gfx to {abs} ({donorBytes.Length} b)");

                    act.Size = donorBytes.Length;
                    act.Sha256 = "";
                    delivered++;
                }
                catch (Exception writeEx)
                {
                    Debug.WriteLine($"[redux.customize][minimap] tier2 write FAIL: {writeEx.GetType().Name}: {writeEx.Message}");
                }
            }

            try
            {
                var imported = Core.Services.PatchCustomizationSupport.EnsureOriginalsImported(
                    workDir, mf, gtaRoot, "minimap.gfx",
                    Core.Services.MinimapBuilderService.DefaultTargetPaths,
                    Core.Services.MinimapBuilderService.RpfNameHints);
                foreach (var wf in imported)
                {
                    File.WriteAllBytes(wf.PhysicalPath, donorBytes);
                    Core.Services.PatchCustomizationSupport.UpsertPatchAction(mf, workDir, wf);
                    delivered++;
                }
                Debug.WriteLine($"[redux.customize][minimap] tier3: live-resolve OK, {imported.Count} path(s), {donorBytes.Length} b");
            }
            catch (Exception liveEx)
            {
                Debug.WriteLine($"[redux.customize][minimap] tier3 FAIL: {liveEx.GetType().Name}: {liveEx.Message}");
            }

            Console.WriteLine($"[Минимапа] Донор разложен по {delivered} копиям minimap.gfx.");
            if (delivered > 0) return true;
            return false;
        }

        bool TryDeliverDonorScaleformRpfWhole(string donorMinimapDir, Core.Parser.DiffManifest mf)
        {
            var donorRpfPath = Core.Services.PatchCustomizationSupport
                .TryFindFirstRpfPath(donorMinimapDir, "scaleform_minimap.rpf");
            if (donorRpfPath is null)
            {
                Debug.WriteLine($"[redux.customize][minimap.whole-rpf] donor has no .rpf in {donorMinimapDir}");
                return false;
            }

            string relativeFromDonor;
            try
            {
                relativeFromDonor = Path.GetRelativePath(donorMinimapDir, donorRpfPath)
                    .Replace('\\', '/');
            }
            catch
            {
                Debug.WriteLine($"[redux.customize][minimap.whole-rpf] cannot resolve relative path for {donorRpfPath}");
                return false;
            }

            try
            {
                var targetAbs = Path.Combine(
                    workDir, "patch_files",
                    relativeFromDonor.Replace('/', Path.DirectorySeparatorChar));
                Directory.CreateDirectory(Path.GetDirectoryName(targetAbs)!);
                File.Copy(donorRpfPath, targetAbs, overwrite: true);
                var bytes = File.ReadAllBytes(targetAbs);
                var sha = Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(bytes)).ToLowerInvariant();

                var normalizedTarget = relativeFromDonor;
                var existing = mf.Actions?.FirstOrDefault(a =>
                    !string.IsNullOrWhiteSpace(a.TargetPath) &&
                    string.Equals(a.TargetPath.Replace('\\', '/'), normalizedTarget, StringComparison.OrdinalIgnoreCase));

                if (existing is not null)
                {
                    existing.Type = Core.Parser.ActionType.Replace;
                    existing.SourcePath = $"patch_files/{normalizedTarget}";
                    existing.Size = bytes.LongLength;
                    existing.Sha256 = sha;
                    existing.IsWholeReplaceNestedRpf = true;
                    Debug.WriteLine($"[redux.customize][minimap.whole-rpf] updated existing action for '{normalizedTarget}'");
                }
                else
                {
                    mf.Actions ??= new List<Core.Parser.PatchAction>();
                    mf.Actions.Add(new Core.Parser.PatchAction
                    {
                        Type = Core.Parser.ActionType.Replace,
                        TargetPath = normalizedTarget,
                        SourcePath = $"patch_files/{normalizedTarget}",
                        Size = bytes.LongLength,
                        Sha256 = sha,
                        IsWholeReplaceNestedRpf = true,
                    });
                    Debug.WriteLine($"[redux.customize][minimap.whole-rpf] added new action for '{normalizedTarget}'");
                }

                Core.Services.PatchCustomizationSupport.RecalculateTotalPatchSize(mf);
                return true;
            }
            catch (Exception ex)
            {
                Debug.WriteLine($"[redux.customize][minimap.whole-rpf] FAIL: {ex.GetType().Name}: {ex.Message}");
                return false;
            }
        }

        int TryDeliverDonorMinimapFonts(string donorMinimapDir)
        {
            int delivered = 0;
            if (string.IsNullOrWhiteSpace(donorMinimapDir) || !Directory.Exists(donorMinimapDir))
                return 0;

            string[] gfxFiles;
            try { gfxFiles = Directory.GetFiles(donorMinimapDir, "*.gfx", SearchOption.AllDirectories); }
            catch { return 0; }

            foreach (var file in gfxFiles)
            {
                string rel = Path.GetRelativePath(donorMinimapDir, file).Replace('\\', '/');
                if (!Core.Parser.MinimapFontLinker.IsCustomFontPath(rel)) continue;

                try
                {
                    byte[] fontBytes = File.ReadAllBytes(file);
                    var fontSha = Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(fontBytes)).ToLowerInvariant();

                    var cleanBytes = Core.Services.PatchCustomizationSupport.GetCleanBytesForExactPath(gtaRoot, rel);
                    if (cleanBytes is not null && cleanBytes.Length == fontBytes.Length &&
                        Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(cleanBytes)).Equals(fontSha, StringComparison.OrdinalIgnoreCase))
                    {
                        Debug.WriteLine($"[redux.customize][minimap.fonts] skip stock font {rel}");
                        continue;
                    }

                    var targetAbs = Path.Combine(workDir, "patch_files", rel.Replace('/', Path.DirectorySeparatorChar));
                    Directory.CreateDirectory(Path.GetDirectoryName(targetAbs)!);
                    File.WriteAllBytes(targetAbs, fontBytes);

                    var existing = manifest.Actions?.FirstOrDefault(a =>
                        !string.IsNullOrWhiteSpace(a.TargetPath) &&
                        string.Equals(a.TargetPath.Replace('\\', '/'), rel, StringComparison.OrdinalIgnoreCase));
                    if (existing is not null)
                    {
                        existing.Type = Core.Parser.ActionType.Replace;
                        existing.SourcePath = $"patch_files/{rel}";
                        existing.Size = fontBytes.LongLength;
                        existing.Sha256 = fontSha;
                        existing.IsWholeReplaceNestedRpf = false;
                    }
                    else
                    {
                        manifest.Actions ??= new List<Core.Parser.PatchAction>();
                        manifest.Actions.Add(new Core.Parser.PatchAction
                        {
                            Type = Core.Parser.ActionType.Replace,
                            TargetPath = rel,
                            SourcePath = $"patch_files/{rel}",
                            Size = fontBytes.LongLength,
                            Sha256 = fontSha,
                            IsWholeReplaceNestedRpf = false,
                        });
                    }

                    delivered++;
                    Debug.WriteLine($"[redux.customize][minimap.fonts] staged {rel} ({fontBytes.Length} b)");
                }
                catch (Exception ex)
                {
                    Debug.WriteLine($"[redux.customize][minimap.fonts] FAIL {rel}: {ex.GetType().Name}: {ex.Message}");
                }
            }

            if (delivered > 0)
                Core.Services.PatchCustomizationSupport.RecalculateTotalPatchSize(manifest);
            return delivered;
        }

        if (!string.IsNullOrWhiteSpace(m.LibraryItemId))
        {
            try
            {
                emitDetail?.Invoke("downloading_new", 44, Loc.T("progress.minimap.downloading"));
                var libRoot = await EnsureLibraryCachedAsync(m.LibraryItemId!, "minimap", http, emitDetail,
                    progressBase: 44, progressSpan: 2);
                if (libRoot is null)
                {
                    notes.Add("[Минимапа] Не удалось скачать library-донора - применил только цвет/PNG.");
                }
                else
                {
                    var donorMinimapDir = Path.Combine(libRoot, "components", "minimap");
                    var baseMinimapDir  = Path.Combine(workDir, "components", "minimap");
                    if (!Directory.Exists(donorMinimapDir) ||
                        !Directory.EnumerateFileSystemEntries(donorMinimapDir).Any())
                    {
                        notes.Add($"[Минимапа] У library-донора '{m.LibraryItemId}' нет содержимого minimap.");
                    }
                    else
                    {
                        emitDetail?.Invoke("applying_user_changes", 46, Loc.T("progress.minimap.applying"));
                        if (Directory.Exists(baseMinimapDir))
                        {
                            try { Directory.Delete(baseMinimapDir, recursive: true); }
                            catch (Exception delEx) { Debug.WriteLine($"[redux.customize][minimap.library] failed wiping base dir: {delEx.Message}"); }
                        }
                        Directory.CreateDirectory(baseMinimapDir);
                        CopyDirectoryRecursive(donorMinimapDir, baseMinimapDir);

                        var donorBytes = Core.Services.PatchCustomizationSupport.TryFindFileBytesInDir(donorMinimapDir, "minimap.gfx");
                        bool injected = false;
                        if (donorBytes is not null)
                        {
                            try
                            {
                                injected = TryDeliverDonorMinimapGfx(donorBytes, manifest);
                            }
                            catch (Exception injectEx)
                            {
                                Debug.WriteLine($"[redux.customize][minimap.library] inject failed: {injectEx.GetType().Name}: {injectEx.Message}");
                                notes.Add($"[Минимапа] Не удалось инжектнуть minimap.gfx: {injectEx.Message}");
                            }
                        }
                        if (!injected)
                        {
                            Debug.WriteLine($"[redux.customize][minimap.library] inject point missing, trying whole-rpf fallback");
                            injected = TryDeliverDonorScaleformRpfWhole(donorMinimapDir, manifest);
                        }
                        if (injected)
                        {
                            notes.Add($"[Минимапа] Импортировано из библиотеки.");
                            importSucceeded = true;
                            if (donorBytes is not null) onDonorBase?.Invoke(donorBytes);
                            int fonts = TryDeliverDonorMinimapFonts(donorMinimapDir);
                            if (fonts > 0) notes.Add($"[Минимапа] Подтянуты кастомные шрифты ({fonts}) - цифры на миникарте будут корректны.");
                        }
                        else
                        {
                            notes.Add($"[Минимапа] У library-донора нет ни минимапы (minimap.gfx), ни scaleform_minimap.rpf - применил только цвет/PNG.");
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                Debug.WriteLine($"[redux.customize][minimap.library] FAIL: {ex.GetType().Name}: {ex.Message}");
                notes.Add($"[Минимапа] Сбой импорта из библиотеки: {ex.Message} - применил только цвет/PNG.");
            }
        }
        else if (!string.IsNullOrWhiteSpace(m.ImportedFromReduxId))
        {

            try
            {
                emitDetail?.Invoke("downloading_new", 44, Loc.T("progress.minimap.downloading"));
                var donorRoot = await EnsureDonorCachedAsync(m.ImportedFromReduxId!, "minimap", http, emitDetail, m.DonorVersionId,
                    progressBase: 44, progressSpan: 2);
                if (donorRoot is null)
                {
                    notes.Add("[Минимапа] Не удалось скачать донора - применил только цвет/PNG.");
                }
                else
                {
                    var donorMinimapDir = Path.Combine(donorRoot, "components", "minimap");
                    var baseMinimapDir  = Path.Combine(workDir, "components", "minimap");
                    if (!Directory.Exists(donorMinimapDir) ||
                        !Directory.EnumerateFileSystemEntries(donorMinimapDir).Any())
                    {
                        notes.Add($"[Минимапа] У донора '{m.ImportedFromReduxId}' нет компонента minimap - применил только цвет/PNG.");
                    }
                    else
                    {
                        emitDetail?.Invoke("applying_user_changes", 46, Loc.T("progress.minimap.applying"));
                        if (Directory.Exists(baseMinimapDir))
                        {
                            try { Directory.Delete(baseMinimapDir, recursive: true); }
                            catch (Exception delEx) { Debug.WriteLine($"[redux.customize][minimap.import] failed wiping base dir: {delEx.Message}"); }
                        }
                        Directory.CreateDirectory(baseMinimapDir);
                        CopyDirectoryRecursive(donorMinimapDir, baseMinimapDir);

                        var donorBytes = Core.Services.PatchCustomizationSupport.TryFindFileBytesInDir(donorMinimapDir, "minimap.gfx");
                        bool injected = false;
                        if (donorBytes is not null)
                        {
                            try
                            {
                                injected = TryDeliverDonorMinimapGfx(donorBytes, manifest);
                            }
                            catch (Exception injectEx)
                            {
                                Debug.WriteLine($"[redux.customize][minimap.import] inject failed: {injectEx.GetType().Name}: {injectEx.Message}");
                                notes.Add($"[Минимапа] Не удалось инжектнуть minimap.gfx: {injectEx.Message}");
                            }
                        }
                        if (!injected)
                        {
                            Debug.WriteLine($"[redux.customize][minimap.import] inject point missing, trying whole-rpf fallback");
                            injected = TryDeliverDonorScaleformRpfWhole(donorMinimapDir, manifest);
                        }
                        if (injected)
                        {
                            notes.Add($"[Минимапа] Импортировано из '{m.ImportedFromReduxId}'.");
                            importSucceeded = true;
                            if (donorBytes is not null) onDonorBase?.Invoke(donorBytes);
                            int fonts = TryDeliverDonorMinimapFonts(donorMinimapDir);
                            if (fonts > 0) notes.Add($"[Минимапа] Подтянуты кастомные шрифты ({fonts}) - цифры на миникарте будут корректны.");
                        }
                        else
                        {
                            notes.Add($"[Минимапа] У донора '{m.ImportedFromReduxId}' нет ни минимапы (minimap.gfx), ни scaleform_minimap.rpf - применил только цвет/PNG.");
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                Debug.WriteLine($"[redux.customize][minimap.import] FAIL: {ex.GetType().Name}: {ex.Message}");
                notes.Add($"[Минимапа] Сбой импорта: {ex.Message} - применил только цвет/PNG.");
            }
        }

        bool minimapDefaultColors =
            string.Equals(m.HpColor,    "#34D399", StringComparison.OrdinalIgnoreCase) &&
            string.Equals(m.ArmorColor, "#60A5FA", StringComparison.OrdinalIgnoreCase);
        bool minimapWantsHitmarker = !string.IsNullOrWhiteSpace(m.PngOverlayPath);
        bool minimapImportFailed = importRequested && !importSucceeded;
        var coreTweaks = MapMinimapTweaks(m.Tweaks);
        var rebuildHitImage = TryDecodeImageRgba(m.Tweaks?.HitPngPath);
        bool minimapWantsOwnHitPng = !string.IsNullOrWhiteSpace(m.Tweaks?.HitPngPath);
        if (minimapWantsOwnHitPng && rebuildHitImage is null)
            notes.Add($"[Минимапа] Картинка вспышки не читается ({Path.GetFileName(m.Tweaks!.HitPngPath)}) - вспышка осталась стоковой.");
        var rebuildArrowImage = TryDecodeImageRgba(m.Tweaks?.ArrowPngPath);
        if (!string.IsNullOrWhiteSpace(m.Tweaks?.ArrowPngPath) && rebuildArrowImage is null)
            notes.Add($"[Минимапа] Картинка стрелки игрока не читается ({Path.GetFileName(m.Tweaks!.ArrowPngPath)}) - стрелка осталась стоковой.");
        var rebuildGpsImage = TryDecodeImageRgba(m.Tweaks?.GpsPngPath);
        if (!string.IsNullOrWhiteSpace(m.Tweaks?.GpsPngPath) && rebuildGpsImage is null)
            notes.Add($"[Минимапа] Картинка метки GPS не читается ({Path.GetFileName(m.Tweaks!.GpsPngPath)}) - метка осталась стоковой.");
        bool minimapWantsTweaks = Core.Services.MinimapScriptTweaksService.AnyRequested(coreTweaks)
            || rebuildHitImage is not null
            || rebuildArrowImage is not null
            || rebuildGpsImage is not null
            || m.RangeRingsMeters is { Length: > 0 };
        if (minimapDefaultColors && !minimapWantsHitmarker && !minimapWantsTweaks && !minimapImportFailed)
        {
            notes.Add(importSucceeded
                ? "[Минимапа] Импортирована как есть - цвета и шрифт донора сохранены."
                : "[Минимапа] Цвета не менялись - оставлены оригинальные цвета редукса.");
            return true;
        }

        var (javaExe, ffdecJar, swfmillExe) = ResolveMinimapTools();
        var missing = new List<string>();

        if (ffdecJar   is null) missing.Add("additionals/minimap/ffdec.jar");
        if (swfmillExe is null) missing.Add("additionals/minimap/swfmill.exe");
        if (missing.Count > 0)
        {
            notes.Add($"[Минимапа] Не найдены инструменты: {string.Join(", ", missing)}. " +
                      "Положи папку additionals/ рядом с приложением " +
                      "(или в %LocalAppData%/MiamiGraphics/additionals/).");
            if (!minimapDefaultColors)
                importFailures.Add("Минимапа: не найдены инструменты перекраски (ffdec.jar/swfmill.exe) - цвета ХП/брони НЕ применены. Переустанови лаунчер.");
            if (importRequested && !importSucceeded)
            {
                importFailures.Add("Минимапа: нет инструментов (ffdec.jar/swfmill.exe) и импорт не доехал.");
                return false;
            }
            return importRequested ? importSucceeded : true;
        }

        javaExe = await EnsureMinimapJavaAsync(javaExe, notes, emitDetail);
        if (javaExe is null)
        {
            if (!minimapDefaultColors)
                importFailures.Add("Минимапа: не удалось подготовить Java для перекраски - цвета ХП/брони НЕ применены. Проверь интернет и нажми «Применить» ещё раз.");
            if (minimapWantsHitmarker)
                importFailures.Add("Минимапа: PNG-обводка требует Java - НЕ применена. Проверь интернет и нажми «Применить» ещё раз.");
            if (importRequested && !importSucceeded)
            {
                importFailures.Add("Минимапа: импорт не доехал, а без Java не перекрасить.");
                return false;
            }
            return minimapDefaultColors && !minimapWantsHitmarker;
        }

        var (hr, hg, hb) = ParseHex(m.HpColor);
        var (ar, ag, ab) = ParseHex(m.ArmorColor);

        try
        {
            emitDetail?.Invoke("applying_user_changes", 47, Loc.T("progress.minimap.recoloring"));
            var svc = new Core.Services.MinimapBuilderService();
            var recolor = svc.Customize(workDir, manifest, gtaRoot, hr, hg, hb, ar, ag, ab,
                customHitmarkerPath: string.IsNullOrWhiteSpace(m.PngOverlayPath) ? null : m.PngOverlayPath,
                javaExePath:    javaExe,
                ffdecJarPath:   ffdecJar,
                swfmillExePath: swfmillExe,
                tweaks:         coreTweaks,
                applyColors:      !minimapDefaultColors,
                hitImage:         rebuildHitImage,
                rangeRingsMeters: m.RangeRingsMeters,
                arrowImage:       rebuildArrowImage,
                gpsImage:         rebuildGpsImage);
            Debug.WriteLine($"[redux.customize][minimap] recolor: {recolor.FilesRecolored}/{recolor.FilesFound} files");
            if (!minimapDefaultColors && recolor.FilesRecolored == 0)
                importFailures.Add(recolor.FilesFound == 0
                    ? "Минимапа: minimap.gfx не найден ни в патче, ни в update.rpf - цвета ХП/брони НЕ применены."
                    : "Минимапа: у этого редукса нестандартный minimap.gfx, перекрасить не получилось - цвета ХП/брони НЕ применены.");
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[redux.customize][minimap] FAIL: {ex.GetType().Name}: {ex.Message}");
            notes.Add($"[Минимапа] Сбой: {ex.Message}");
            if (!minimapDefaultColors)
                importFailures.Add($"Минимапа: сбой перекраски ({ex.Message}) - цвета ХП/брони НЕ применены.");
        }

        if (importRequested && !importSucceeded)
        {
            var src = !string.IsNullOrWhiteSpace(m.LibraryItemId)
                ? $"library:{m.LibraryItemId}"
                : $"redux:{m.ImportedFromReduxId}" + (m.DonorVersionId.HasValue ? $" (v={m.DonorVersionId})" : "");
            importFailures.Add($"Минимапа: импорт из {src} не доехал. Минимапа в РПФ остаётся базовой.");
            return false;
        }
        return true;
    }

    private async Task ApplyMinimapLayoutAsync(
        string workDir,
        Core.Parser.DiffManifest manifest,
        string gtaRoot,
        MinimapSettingDto m,
        List<string> notes,
        Action<string, int, string?>? emitDetail)
    {
        var saved     = ReadSavedMinimapLayout();
        var ratio     = saved?.Ratio     ?? (string.IsNullOrWhiteSpace(m.AspectRatio) ? "16:9"    : m.AspectRatio);
        var placement = saved?.Placement ?? (string.IsNullOrWhiteSpace(m.Position)    ? "default" : m.Position);

        List<Core.Services.MinimapLayoutElement> elements;
        if (string.Equals(placement, "custom", StringComparison.OrdinalIgnoreCase)
            && saved?.PosX is not null && saved.PosY is not null)
        {
            emitDetail?.Invoke("applying_user_changes", 43, Loc.T("progress.minimap.applyingPositionShort"));
            elements = Core.Services.MinimapLayoutService.BuildCustomElements(saved.PosX.Value, saved.PosY.Value);
        }
        else
        {
            List<MinimapLayoutRow> rows;
            try
            {
                emitDetail?.Invoke("applying_user_changes", 43, Loc.T("progress.minimap.applyingPositionShort"));
                rows = await _supabase.SelectAsync<MinimapLayoutRow>(
                    "minimap_layouts",
                    $"select=*&aspect_ratio=eq.{Uri.EscapeDataString(ratio)}&placement=eq.{Uri.EscapeDataString(placement)}");
            }
            catch (Exception ex)
            {
                Debug.WriteLine($"[redux.customize][minimap.layout] fetch FAIL: {ex.GetType().Name}: {ex.Message}");
                notes.Add($"[Минимапа] Позиция не применена (нет связи с базой): {ex.Message}");
                return;
            }

            if (rows.Count == 0)
            {
                Debug.WriteLine($"[redux.customize][minimap.layout] no rows for ratio={ratio} placement={placement}");
                notes.Add($"[Минимапа] Позиция не применена: в базе нет раскладки {ratio} / {placement}.");
                return;
            }

            elements = rows
                .Select(r => new Core.Services.MinimapLayoutElement(r.Element, r.PosX, r.PosY, r.SizeX, r.SizeY))
                .ToList();
        }

        elements = Core.Services.MinimapLayoutService.AppendBigmap(elements);

        elements = Core.Services.MinimapLayoutService.WithTransparency(elements, saved?.Transparent ?? false);

        byte[]? fallbackFrontend = await ResolveVanillaFrontendXmlBytesAsync();

        try
        {
            bool ok = await Task.Run(() => new Core.Services.MinimapLayoutService()
                .Apply(workDir, manifest, gtaRoot, elements, fallbackFrontend));
            if (ok)
            {
                Debug.WriteLine($"[redux.customize][minimap.layout] applied ratio={ratio} placement={placement} ({elements.Count} elements)");
            }
            else
            {
                notes.Add("[Минимапа] Позиция не применена: frontend.xml не найден или элементы не совпали.");
            }
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[redux.customize][minimap.layout] apply FAIL: {ex.GetType().Name}: {ex.Message}");
            notes.Add($"[Минимапа] Позиция не применена: {ex.Message}");
        }
    }

    private static string GetMinimapLayoutConfigPath()
        => Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
            "MiamiGraphics", "config", "minimap_layout.json");

    private sealed class SavedMinimapLayout
    {
        public string Ratio { get; set; } = "16:9";
        public string Placement { get; set; } = "default";
        public bool Transparent { get; set; }
        public decimal? PosX { get; set; }
        public decimal? PosY { get; set; }
    }

    private static SavedMinimapLayout? ReadSavedMinimapLayout()
    {
        try
        {
            var p = GetMinimapLayoutConfigPath();
            if (!File.Exists(p)) return null;
            return JsonSerializer.Deserialize<SavedMinimapLayout>(File.ReadAllText(p));
        }
        catch { return null; }
    }

    private static void WriteSavedMinimapLayout(string ratio, string placement, bool transparent = false,
        decimal? posX = null, decimal? posY = null)
    {
        try
        {
            var p = GetMinimapLayoutConfigPath();
            Directory.CreateDirectory(Path.GetDirectoryName(p)!);
            File.WriteAllText(p, JsonSerializer.Serialize(new SavedMinimapLayout
                { Ratio = ratio, Placement = placement, Transparent = transparent, PosX = posX, PosY = posY }));
        }
        catch (Exception ex) { Debug.WriteLine($"[minimap.layout] save FAIL: {ex.Message}"); }
    }

    public Task<int?> MinimapGetSafezoneAsync()
    {
        return Task.Run(() =>
        {
            try
            {
                var profiles = Path.Combine(
                    Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments),
                    "Rockstar Games", "GTA V", "Profiles");
                if (!Directory.Exists(profiles)) return (int?)null;
                var bin = Directory.EnumerateFiles(profiles, "pc_settings.bin", SearchOption.AllDirectories)
                    .OrderByDescending(File.GetLastWriteTimeUtc)
                    .FirstOrDefault();
                if (bin is null) return null;

                var d = File.ReadAllBytes(bin);
                if (d.Length < 8 || d.Length % 8 != 0)
                {
                    Debug.WriteLine($"[minimap.safezone] {bin}: длина {d.Length} не кратна 8 - формат не тот, не читаю");
                    return (int?)null;
                }

                int pairs = d.Length / 8;
                var vals = new Dictionary<uint, int>(pairs);
                for (int p = 0; p + 8 <= d.Length; p += 8)
                    vals[BitConverter.ToUInt32(d, p)] = BitConverter.ToInt32(d, p + 4);

                if (vals.Count != pairs)
                {
                    Debug.WriteLine($"[minimap.safezone] {bin}: {pairs} пар, но {vals.Count} уникальных id - выравнивание не сходится, не доверяю");
                    return (int?)null;
                }

                if (!vals.TryGetValue(212, out var n))
                {
                    Debug.WriteLine($"[minimap.safezone] {bin}: id 212 отсутствует ({pairs} пар) - отдаю null, а не 0");
                    return (int?)null;
                }
                if (n < 0 || n > 10)
                {
                    Debug.WriteLine($"[minimap.safezone] {bin}: id 212 = {n} вне шкалы 0..10 - не доверяю");
                    return (int?)null;
                }

                Debug.WriteLine($"[minimap.safezone] {bin}: id 212 = {n} ({pairs} пар, коллизий нет)");
                return (int?)n;
            }
            catch (Exception ex)
            {
                Debug.WriteLine($"[minimap.safezone] read FAIL: {ex.GetType().Name}: {ex.Message}");
                return (int?)null;
            }
        });
    }

    public Task<MinimapScreenDto> MinimapGetScreenAsync() => Task.Run(() =>
    {
        var path = Core.Services.GtaSettingsApplier.GetSettingsPath();
        try
        {
            if (File.Exists(path))
            {
                var text = File.ReadAllText(path);
                var video = System.Xml.Linq.XDocument.Parse(text).Root?.Element("video");
                bool hasSize = video is not null
                            && video.Element("ScreenWidth") is not null
                            && video.Element("ScreenHeight") is not null;
                var m = Core.Services.GtaSettingsModel.FromXml(text);
                if (hasSize && m.ScreenWidth > 0 && m.ScreenHeight > 0)
                {
                    Debug.WriteLine($"[minimap.screen] {m.ScreenWidth}x{m.ScreenHeight} aspect={m.AspectRatio} windowed={m.Windowed} из {path}");
                    return new MinimapScreenDto(m.ScreenWidth, m.ScreenHeight, m.AspectRatio, m.Windowed != 0, true, path);
                }
                Debug.WriteLine($"[minimap.screen] {path}: video/ScreenWidth не найден - отдаю дефолт как НЕ факт");
            }
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[minimap.screen] read FAIL: {ex.GetType().Name}: {ex.Message}");
        }
        var def = Core.Services.GtaSettingsModel.Defaults();
        return new MinimapScreenDto(def.ScreenWidth, def.ScreenHeight, def.AspectRatio, def.Windowed != 0, false, path);
    });

    public async Task<MinimapLayoutDto> MinimapLayoutGetAsync()
    {
        var saved = ReadSavedMinimapLayout();
        var fallback = new MinimapLayoutDto(saved?.Ratio ?? "16:9", saved?.Placement ?? "default", saved?.Transparent ?? false,
            (double?)saved?.PosX, (double?)saved?.PosY);

        try
        {
            var gtaRoot = await GetGtaPathAsync();
            if (string.IsNullOrWhiteSpace(gtaRoot)) return fallback;
            var updateRpf = Path.Combine(gtaRoot, "update", "update.rpf");
            if (!File.Exists(updateRpf)) return fallback;

            byte[]? frontend;
            await _detectOverlaysGate.WaitAsync();
            try
            {
                frontend = await Task.Run(() =>
                    Core.Services.PatchCustomizationSupport.GetBytesFromArchiveExactPath(
                        updateRpf, Core.Services.MinimapLayoutService.FrontendXmlTargetPath));
                if (frontend is null)
                {
                    await Task.Delay(400);
                    frontend = await Task.Run(() =>
                        Core.Services.PatchCustomizationSupport.GetBytesFromArchiveExactPath(
                            updateRpf, Core.Services.MinimapLayoutService.FrontendXmlTargetPath));
                }
            }
            finally { _detectOverlaysGate.Release(); }
            var current = frontend is null ? null
                : Core.Services.MinimapLayoutService.ReadElementCoords(frontend, "minimap");

            bool transparent = saved?.Transparent ?? false;
            var liveBlur = frontend is null ? null
                : Core.Services.MinimapLayoutService.ReadElementCoords(frontend, "minimap_blur");
            if (liveBlur is not null)
                transparent = liveBlur.SizeX <= 0.0006m && liveBlur.SizeY <= 0.0006m;

            if (current is null) return new MinimapLayoutDto(fallback.Ratio, fallback.Placement, transparent, fallback.PosX, fallback.PosY);

            const decimal epsCustom = 0.0006m;
            if (saved is not null
                && string.Equals(saved.Placement, "custom", StringComparison.OrdinalIgnoreCase)
                && saved.PosX is not null && saved.PosY is not null
                && Math.Abs(saved.PosX.Value - current.PosX) <= epsCustom
                && Math.Abs(saved.PosY.Value - current.PosY) <= epsCustom)
            {
                return new MinimapLayoutDto(saved.Ratio, "custom", transparent, (double)current.PosX, (double)current.PosY);
            }

            var rows = await _supabase.SelectAsync<MinimapLayoutRow>(
                "minimap_layouts", "select=*&element=eq.minimap");
            if (rows.Count == 0) return new MinimapLayoutDto(fallback.Ratio, fallback.Placement, transparent, (double)current.PosX, (double)current.PosY);

            const decimal eps = 0.0006m;
            static bool Near(decimal a, decimal b, decimal e) => Math.Abs(a - b) <= e;
            static bool NearOpt(decimal a, decimal? b, decimal e) => b is not { } v || Math.Abs(a - v) <= e;
            var hits = rows.Where(r =>
                Near(r.PosX, current.PosX, eps) && Near(r.PosY, current.PosY, eps) &&
                NearOpt(r.SizeX, current.SizeX, eps) && NearOpt(r.SizeY, current.SizeY, eps)).ToList();

            if (hits.Count > 0)
            {
                var hit = hits.FirstOrDefault(h => saved is not null
                              && string.Equals(h.AspectRatio, saved.Ratio, StringComparison.OrdinalIgnoreCase)
                              && string.Equals(h.Placement, saved.Placement, StringComparison.OrdinalIgnoreCase))
                       ?? hits.FirstOrDefault(h => saved is not null
                              && string.Equals(h.AspectRatio, saved.Ratio, StringComparison.OrdinalIgnoreCase))
                       ?? hits.FirstOrDefault(h => h.AspectRatio == "16:9")
                       ?? hits[0];

                WriteSavedMinimapLayout(hit.AspectRatio, hit.Placement, transparent);
                Debug.WriteLine($"[minimap.layout] detected {hit.AspectRatio}/{hit.Placement} transparent={transparent} from live frontend.xml ({hits.Count} candidate row(s))");
                return new MinimapLayoutDto(hit.AspectRatio, hit.Placement, transparent, (double)current.PosX, (double)current.PosY);
            }

            Debug.WriteLine($"[minimap.layout] live coords {current.PosX}/{current.PosY}/{current.SizeX}/{current.SizeY} matched no known layout - using saved/default");
            return new MinimapLayoutDto(fallback.Ratio, fallback.Placement, transparent, (double)current.PosX, (double)current.PosY);
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[minimap.layout] detect FAIL: {ex.GetType().Name}: {ex.Message}");
            return fallback;
        }
    }

    public async Task<InjectResultDto> MinimapLayoutApplyAsync(string ratio, string placement, bool transparent)
    {
        ratio     = string.IsNullOrWhiteSpace(ratio)     ? "16:9"    : ratio.Trim();
        placement = string.IsNullOrWhiteSpace(placement) ? "default" : placement.Trim();

        using var _mtx = await MiamiGraphics.Shell.Services.UpdateRpfMutex.AcquireAsync($"minimap-layout:{ratio}:{placement}:{transparent}");

        const string progressKey = "minimap-layout";
        const string prettyName  = "Миникарта: положение";

        var gtaRoot = await GetGtaPathAsync();
        if (string.IsNullOrWhiteSpace(gtaRoot))
            return new InjectResultDto(false, "GTA не найдена.", null);
        var updateRpf = Path.Combine(gtaRoot, "update", "update.rpf");
        if (!File.Exists(updateRpf))
            return new InjectResultDto(false, $"Не найден {updateRpf}.", null);

        WriteSavedMinimapLayout(ratio, placement, transparent);

        EmitInstallProgress(progressKey, prettyName, "starting", 5, null, detailMessage: Loc.T("progress.minimap.preparingLayout"));

        List<MinimapLayoutRow> rows;
        try
        {
            rows = await _supabase.SelectAsync<MinimapLayoutRow>(
                "minimap_layouts",
                $"select=*&aspect_ratio=eq.{Uri.EscapeDataString(ratio)}&placement=eq.{Uri.EscapeDataString(placement)}");
        }
        catch (Exception ex)
        {
            EmitInstallProgress(progressKey, prettyName, "error", 0, ex.Message);
            return new InjectResultDto(false, $"Не удалось получить раскладку из базы: {ex.Message}", null);
        }
        if (rows.Count == 0)
        {
            var msg = $"В базе нет раскладки {ratio} / {placement}.";
            EmitInstallProgress(progressKey, prettyName, "error", 0, msg);
            return new InjectResultDto(false, msg, null);
        }
        var elements = rows
            .Select(r => new Core.Services.MinimapLayoutElement(r.Element, r.PosX, r.PosY, r.SizeX, r.SizeY))
            .ToList();

        elements = Core.Services.MinimapLayoutService.AppendBigmap(elements);

        elements = Core.Services.MinimapLayoutService.WithTransparency(elements, transparent);

        byte[]? current;
        try
        {
            current = await Task.Run(() =>
                Core.Services.PatchCustomizationSupport.GetBytesFromArchiveExactPath(
                    updateRpf, Core.Services.MinimapLayoutService.FrontendXmlTargetPath));
        }
        catch (Exception ex)
        {
            EmitInstallProgress(progressKey, prettyName, "error", 0, ex.Message);
            return new InjectResultDto(false, $"Не удалось прочитать frontend.xml: {ex.Message}", null);
        }
        bool addFromVanilla = false;
        if (current is null || current.Length == 0)
        {
            addFromVanilla = true;
            current = await ResolveVanillaFrontendXmlBytesAsync();
            if (current is null || current.Length == 0)
            {
                const string msg = "frontend.xml отсутствует в сборке, а эталонный получить не удалось (нет папки additionals/frontend.xml, R2 и кэша).";
                EmitInstallProgress(progressKey, prettyName, "error", 0, msg);
                return new InjectResultDto(false, msg, null);
            }
        }

        var patched = Core.Services.MinimapLayoutService.PatchFrontendXmlBytes(current, elements);
        if (patched is null)
        {
            const string msg = "Не удалось пропатчить frontend.xml (нестандартный формат).";
            EmitInstallProgress(progressKey, prettyName, "error", 0, msg);
            return new InjectResultDto(false, msg, null);
        }

        var rollback = updateRpf + ".layout_rollback";
        await MakeRollbackPointAsync(updateRpf, rollback, progressKey, prettyName,
            "starting", new ProgressBand(5, 14), "minimap.layout");

        using var rampCts = new CancellationTokenSource();
        var ramp = StartProgressRamp(
            (phase, pct) => EmitInstallProgress(progressKey, prettyName, phase, pct, null,
                detailMessage: addFromVanilla
                    ? Loc.T("progress.minimap.applyingPositionWithReference")
                    : Loc.T("progress.minimap.applyingPosition")),
            "injecting", 15, 95, 120, rampCts.Token);

        bool checksumOk = false;
        Exception? applyErr = null;
        try
        {
            checksumOk = await Task.Run(() =>
                Core.Services.PatchCustomizationSupport.ReplaceFilesInLiveArchive(
                    updateRpf,
                    new[] { new KeyValuePair<string, byte[]>(
                        Core.Services.MinimapLayoutService.FrontendXmlTargetPath, patched) },
                    out _, out _,
                    addMissingPlainPaths: true));
        }
        catch (Exception ex) { applyErr = ex; }
        finally { rampCts.Cancel(); try { await ramp; } catch { } }

        if (applyErr is not null || !checksumOk)
        {
            try { if (File.Exists(rollback)) File.Copy(rollback, updateRpf, overwrite: true); } catch { }
            try { if (File.Exists(rollback)) File.Delete(rollback); } catch { }
            var msg = applyErr is not null
                ? $"Не удалось применить положение: {applyErr.Message}"
                : "Не удалось перешифровать update.rpf (ArchiveFix) - изменения откачены. Попробуй ещё раз.";
            EmitInstallProgress(progressKey, prettyName, "error", 0, msg);
            return new InjectResultDto(false, msg, null);
        }

        try { if (File.Exists(rollback)) File.Delete(rollback); } catch { }
        EmitInstallProgress(progressKey, prettyName, "done", 100, null,
            detailMessage: Loc.T("progress.minimap.positionApplied"));
        return new InjectResultDto(true, null, updateRpf);
    }

