    private sealed class MinimapLayoutRow
    {
        public string  AspectRatio { get; set; } = string.Empty;
        public string  Placement   { get; set; } = string.Empty;
        public string  Element     { get; set; } = string.Empty;
        public decimal PosX        { get; set; }
        public decimal PosY        { get; set; }
        public decimal SizeX       { get; set; }
        public decimal SizeY       { get; set; }
    }

    private static readonly string[] CrosshairDefaultTargetPaths =
    {
        "x64/patch/data/cdimages/scaleform_generic.rpf/hud_reticle.gfx",
        "x64/data/cdimages/scaleform_generic.rpf/hud_reticle.gfx",
    };

    private static bool IsReticleGfxPath(string? path)
    {
        if (string.IsNullOrWhiteSpace(path)) return false;
        var leaf = path!.Replace('\\', '/');
        int slash = leaf.LastIndexOf('/');
        if (slash >= 0) leaf = leaf[(slash + 1)..];
        return leaf.EndsWith(".gfx", StringComparison.OrdinalIgnoreCase)
            && leaf.Contains("reticle", StringComparison.OrdinalIgnoreCase);
    }

    private static string? FindDonorReticleGfxPath(string compDir)
    {
        if (!Directory.Exists(compDir)) return null;
        List<string> all;
        try
        {
            all = Directory.EnumerateFiles(compDir, "*.gfx", SearchOption.AllDirectories).ToList();
        }
        catch { return null; }
        if (all.Count == 0) return null;

        var byName = all.FirstOrDefault(p =>
        {
            var n = Path.GetFileName(p);
            return n.Equals("hud_reticle.gfx", StringComparison.OrdinalIgnoreCase)
                || n.EndsWith("_hud_reticle.gfx", StringComparison.OrdinalIgnoreCase);
        });
        if (byName is not null) return byName;

        foreach (var p in all)
        {
            try
            {
                if (Core.Services.ReticleBuilderService.LooksLikeReticleGfx(File.ReadAllBytes(p)))
                    return p;
            }
            catch {}
        }

        return all.Count == 1 ? all[0] : null;
    }

    private async Task<bool> ApplyCrosshairCustomizationAsync(
        string workDir,
        Core.Parser.DiffManifest manifest,
        string gtaRoot,
        GenericSettingDto c,
        System.Net.Http.HttpClient http,
        List<string> notes,
        Action<string, int, string?>? emitDetail = null)
    {

        if (c.Kind == "default" || c.Kind == "clear") return false;

        byte[] donorBytes;
        string srcNoun;

        if (c.Kind == "custom")
        {
            if (string.IsNullOrWhiteSpace(c.CustomSpecJson)) return false;
            ReticleSpecDto? spec = null;
            try
            {
                spec = System.Text.Json.JsonSerializer.Deserialize<ReticleSpecDto>(
                    c.CustomSpecJson!,
                    new System.Text.Json.JsonSerializerOptions { PropertyNameCaseInsensitive = true });
            }
            catch (Exception ex)
            {
                Debug.WriteLine($"[redux.customize][crosshair] custom spec parse FAIL: {ex.Message}");
            }
            if (spec is null)
            {
                notes.Add("[Прицел] Спека кастомного прицела не читается - оставлен ванильный.");
                return false;
            }
            emitDetail?.Invoke("applying_user_changes", 56, Loc.T("progress.reticle.buildingCustom"));
            var built = await BuildCustomReticleGfxAsync(gtaRoot, spec, notes,
                msg => emitDetail?.Invoke("applying_user_changes", 56, msg));
            if (built is null) return false;
            donorBytes = built;
            srcNoun = "конструктора";
        }
        else
        {
            string? donorRoot = null;
            string donorLabel = "";
            try
            {
                if (c.Kind == "library" && !string.IsNullOrWhiteSpace(c.LibraryItemId))
                {
                    emitDetail?.Invoke("downloading_new", 56, Loc.T("progress.reticle.downloading"));
                    donorRoot = await EnsureLibraryCachedAsync(c.LibraryItemId!, "crosshair", http, emitDetail,
                        progressBase: 56, progressSpan: 2);
                    donorLabel = $"library:{c.LibraryItemId}";
                }
                else if (c.Kind == "import" && !string.IsNullOrWhiteSpace(c.DonorReduxId))
                {
                    emitDetail?.Invoke("downloading_new", 56, Loc.T("progress.reticle.downloading"));
                    donorRoot = await EnsureDonorCachedAsync(c.DonorReduxId!, "crosshair", http, emitDetail, c.DonorVersionId,
                        progressBase: 56, progressSpan: 2);
                    donorLabel = $"redux:{c.DonorReduxId}";
                }
                else
                {
                    return false;
                }
            }
            catch (Exception ex)
            {
                Debug.WriteLine($"[redux.customize][crosshair] donor fetch FAIL: {ex.GetType().Name}: {ex.Message}");
                notes.Add($"[Прицел] Не удалось подготовить донора: {ex.Message}");
                return false;
            }

            if (donorRoot is null)
            {
                notes.Add("[Прицел] Донор не подготовлен.");
                return false;
            }

            var donorCompDir = Path.Combine(donorRoot, "components", "crosshair");
            string? donorGfxPath = FindDonorReticleGfxPath(donorCompDir);

            if (donorGfxPath is null || !File.Exists(donorGfxPath))
            {
                notes.Add($"[Прицел] У донора {donorLabel} нет hud_reticle.gfx - компонент пропущен.");
                return false;
            }

            try { donorBytes = await File.ReadAllBytesAsync(donorGfxPath); }
            catch (Exception ex)
            {
                notes.Add($"[Прицел] Не удалось прочитать донорский hud_reticle.gfx: {ex.Message}");
                return false;
            }
            srcNoun = c.Kind == "library" ? "библиотеки" : "редукса";
        }

        emitDetail?.Invoke("applying_user_changes", 58, Loc.T("progress.reticle.applying"));

        int cmReplaced = 0;
        try
        {
            cmReplaced = Core.Services.PatchCustomizationSupport
                .TryReplaceNestedComponentFiles(workDir, "crosshair", IsReticleGfxPath, donorBytes);
            if (cmReplaced > 0)
            {
                Debug.WriteLine($"[redux.customize][crosshair] component_map inject OK from {srcNoun}: {cmReplaced} copy(ies), {donorBytes.Length} b");
                notes.Add($"[Прицел] Импортировано из {srcNoun}.");
                return true;
            }
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[redux.customize][crosshair] component_map inject FAIL: {ex.Message}");

        }

        try
        {
            var actions = manifest.Actions ?? new List<Core.Parser.PatchAction>();
            int mfWritten = 0;
            foreach (var act in actions)
            {
                var src = act.SourcePath;
                var tgt = act.TargetPath;
                if (string.IsNullOrWhiteSpace(src) || string.IsNullOrWhiteSpace(tgt)) continue;
                if (!IsReticleGfxPath(tgt)) continue;

                var abs = Path.Combine(workDir, src.Replace('/', Path.DirectorySeparatorChar));
                Directory.CreateDirectory(Path.GetDirectoryName(abs)!);
                await File.WriteAllBytesAsync(abs, donorBytes);
                act.Size = donorBytes.Length;
                act.Sha256 = "";
                Debug.WriteLine($"[redux.customize][crosshair] manifest fallback wrote {abs} ({donorBytes.Length} b)");
                mfWritten++;
            }
            if (mfWritten > 0)
            {
                notes.Add($"[Прицел] Импортировано из {srcNoun}.");
                return true;
            }
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[redux.customize][crosshair] manifest fallback FAIL: {ex.GetType().Name}: {ex.Message}");
        }

        try
        {
            var targets = await Task.Run(() =>
            {
                var byContent = Core.Services.PatchCustomizationSupport.FindLiveFilesByContent(
                    gtaRoot,
                    n => n.EndsWith(".gfx", StringComparison.OrdinalIgnoreCase),
                    Core.Services.ReticleBuilderService.LooksLikeReticleGfx);
                Debug.WriteLine($"[redux.customize][crosshair] content probe found {byContent.Count}: {string.Join(" | ", byContent)}");
                return byContent.Concat(CrosshairDefaultTargetPaths)
                                .Distinct(StringComparer.OrdinalIgnoreCase).ToList();
            });

            var imported = await Task.Run(() => Core.Services.PatchCustomizationSupport.EnsureOriginalsImported(
                workDir, manifest, gtaRoot, "hud_reticle.gfx",
                targets, "generic", "scaleform", "reticle"));
            foreach (var wf in imported)
            {
                await File.WriteAllBytesAsync(wf.PhysicalPath, donorBytes);
                Core.Services.PatchCustomizationSupport.UpsertPatchAction(manifest, workDir, wf);
            }
            Debug.WriteLine($"[redux.customize][crosshair] live-resolve inject OK: {imported.Count} path(s), {donorBytes.Length} b");
            notes.Add($"[Прицел] Импортировано из {srcNoun}.");
            return true;
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[redux.customize][crosshair] live-resolve FAIL: {ex.GetType().Name}: {ex.Message}");
            notes.Add($"[Прицел] Не удалось внедрить в патч: {ex.Message}");
        }

        return false;
    }

    private async Task<bool> ApplyTracersCustomizationAsync(
        string workDir,
        Core.Parser.DiffManifest manifest,
        TracerSettingDto t,
        System.Net.Http.HttpClient http,
        List<string> notes,
        List<string> importFailures,
        Action<string, int, string?>? emitDetail = null)
    {

        if (t.SourceKind == "default")
        {
            if (t.R == 255 && t.G == 255 && t.B == 255) return true;

            try
            {
                emitDetail?.Invoke("applying_user_changes", 48, Loc.T("progress.tracers.recoloring"));
                var gtaRootForRecolor = await GetGtaPathAsync();
                var svc = new Core.Services.TracerBuilderService();
                svc.Customize(new Core.Services.TracerCustomizationRequest
                {
                    Scenario = Core.Services.TracerScenario.ColorOnly,
                    PatchRootDirectory = workDir,
                    Manifest = manifest,
                    GtaRootPath = gtaRootForRecolor,
                    IncludeQualityVariants = true,
                    Red   = (byte)Math.Clamp(t.R, 0, 255),
                    Green = (byte)Math.Clamp(t.G, 0, 255),
                    Blue  = (byte)Math.Clamp(t.B, 0, 255),
                });
                return true;
            }
            catch (Exception ex)
            {
                Debug.WriteLine($"[redux.customize][tracers.recolor] FAIL: {ex.Message}");
                notes.Add($"[Трейсера] Сбой перекраски: {ex.Message}");
                importFailures.Add($"Трейсера: исключение при перекраске: {ex.Message}");
                return false;
            }
        }

        if (t.SourceKind == "import")
        {
            if (string.IsNullOrWhiteSpace(t.DonorReduxId))
            {
                notes.Add("[Трейсера] Импорт без указанного донора - пропуск.");
                importFailures.Add("Трейсера: импорт запрошен но donorReduxId пуст.");
                return false;
            }
            try
            {
                emitDetail?.Invoke("downloading_new", 48, Loc.T("progress.tracers.downloading"));
                var donorRoot = await EnsureDonorCachedAsync(t.DonorReduxId!, "tracers", http, emitDetail, t.DonorVersionId,
                    progressBase: 48, progressSpan: 2);
                if (donorRoot is null)
                {
                    notes.Add("[Трейсера] Не удалось скачать донора.");
                    importFailures.Add($"Трейсера: donor {t.DonorReduxId}" + (t.DonorVersionId.HasValue ? $" (v={t.DonorVersionId})" : "") + " не доехал.");
                    return false;
                }
                var donorTracersDir = Path.Combine(donorRoot, "components", "tracers");
                if (!Directory.Exists(donorTracersDir) || !Directory.EnumerateFileSystemEntries(donorTracersDir).Any())
                {
                    notes.Add($"[Трейсера] У донора '{t.DonorReduxId}' нет компонента tracers.");
                    importFailures.Add($"Трейсера: у donor {t.DonorReduxId}" + (t.DonorVersionId.HasValue ? $" (v={t.DonorVersionId})" : "") + " нет компонента tracers.");
                    return false;
                }
                emitDetail?.Invoke("applying_user_changes", 50, Loc.T("progress.tracers.applying"));
                var gtaRootForTracers = await GetGtaPathAsync();
                var svc = new Core.Services.TracerBuilderService();
                svc.Customize(new Core.Services.TracerCustomizationRequest
                {
                    Scenario = Core.Services.TracerScenario.CrossInject,
                    PatchRootDirectory = workDir,
                    Manifest = manifest,
                    DonorReduxPath = donorRoot,
                    GtaRootPath = gtaRootForTracers,
                    IncludeQualityVariants = true,
                    InjectDonorBlood = t.TakeDonorBlood,
                    UseCleanBaseline = t.UseCleanEffects,
                    OverrideColorWithPicker = t.OverrideColor,
                    Red   = (byte)Math.Clamp(t.R, 0, 255),
                    Green = (byte)Math.Clamp(t.G, 0, 255),
                    Blue  = (byte)Math.Clamp(t.B, 0, 255),
                });

                try
                {
                    await ApplyDonorTracerBindingFilesAsync(
                        workDir, manifest, t.DonorReduxId!, t.DonorVersionId, donorRoot, http, notes, emitDetail);
                }
                catch (Exception bindEx)
                {
                    Debug.WriteLine($"[redux.customize][tracers.bindings] FAIL: {bindEx.Message}");
                    notes.Add($"[Трейсера] Привязки донора (weaponfx/меты) не перенеслись: {bindEx.Message}. Трейсер может не отображаться на части оружия.");
                }

                return true;
            }
            catch (Exception ex)
            {
                Debug.WriteLine($"[redux.customize][tracers.import] FAIL: {ex.Message}");
                notes.Add($"[Трейсера] Сбой импорта: {ex.Message}");
                importFailures.Add($"Трейсера: исключение при импорте: {ex.Message}");
                return false;
            }
        }

        if (string.IsNullOrWhiteSpace(t.ModelFolderName))
        {
            notes.Add("[Трейсера] Модель не выбрана.");
            return true;
        }
        var modelDir = ResolveTracerModelDir(t.ModelFolderName);
        if (string.IsNullOrEmpty(modelDir) || !Directory.Exists(modelDir))
        {
            notes.Add($"[Трейсера] Папка модели «{t.ModelFolderName}» не найдена. Поставь additionals/tracers.");
            importFailures.Add($"Трейсера: папка модели '{t.ModelFolderName}' не найдена в additionals/tracers.");
            return false;
        }
        try
        {
            emitDetail?.Invoke("applying_user_changes", 50, Loc.T("progress.tracers.applying"));
            var gtaRootForModel = await GetGtaPathAsync();
            var svc = new Core.Services.TracerBuilderService();
            svc.Customize(new Core.Services.TracerCustomizationRequest
            {
                Scenario = Core.Services.TracerScenario.MasterTexture,
                PatchRootDirectory = workDir,
                Manifest = manifest,
                ModelDirectory = modelDir,
                GtaRootPath = gtaRootForModel,
                IncludeQualityVariants = true,
                Red   = (byte)Math.Clamp(t.R, 0, 255),
                Green = (byte)Math.Clamp(t.G, 0, 255),
                Blue  = (byte)Math.Clamp(t.B, 0, 255),
            });
            return true;
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[redux.customize][tracers] FAIL: {ex.Message}");
            notes.Add($"[Трейсера] Сбой: {ex.Message}");
            importFailures.Add($"Трейсера: исключение при применении модели: {ex.Message}");
            return false;
        }
    }

    private async Task<bool> ApplyArmorCustomizationAsync(
        string workDir,
        Core.Parser.DiffManifest manifest,
        GenericSettingDto a,
        System.Net.Http.HttpClient http,
        List<string> notes,
        List<string> importFailures,
        Action<string, int, string?>? emitDetail = null)
    {
        if (a.Kind == "default") return true;

        if (a.Kind == "armorLibrary")
        {
            try
            {
                emitDetail?.Invoke("applying_user_changes", 51, Loc.T("progress.armor.removingReduxArmor"));
                var clr = new Core.Services.ArmorClearService();
                var rc = clr.Clear(new Core.Services.ArmorClearRequest
                {
                    RecipientPatchRoot = workDir,
                    RecipientManifest = manifest,
                });
                if (!rc.Success)
                    Debug.WriteLine($"[redux.customize][armor.armorLibrary] clear redux armor non-fatal: {rc.Message}");
            }
            catch (Exception ex)
            {
                Debug.WriteLine($"[redux.customize][armor.armorLibrary] clear FAIL (non-fatal): {ex.Message}");
            }
            return true;
        }

        if (a.Kind == "clear")
        {
            try
            {
                emitDetail?.Invoke("applying_user_changes", 51, Loc.T("progress.armor.removing"));
                var svc = new Core.Services.ArmorClearService();
                var r = svc.Clear(new Core.Services.ArmorClearRequest
                {
                    RecipientPatchRoot = workDir,
                    RecipientManifest = manifest,
                });
                if (!r.Success)
                {
                    notes.Add($"[Броник] {r.Message}");
                    importFailures.Add($"Броник: сбой очистки: {r.Message}");
                    return false;
                }
                return true;
            }
            catch (Exception ex)
            {
                Debug.WriteLine($"[redux.customize][armor.clear] FAIL: {ex.Message}");
                notes.Add($"[Броник] Сбой очистки: {ex.Message}");
                importFailures.Add($"Броник: исключение при очистке: {ex.Message}");
                return false;
            }
        }

        string? donorRoot = null;
        try
        {
            if (a.Kind == "library" && !string.IsNullOrWhiteSpace(a.LibraryItemId))
            {
                emitDetail?.Invoke("downloading_new", 51, Loc.T("progress.armor.downloading"));
                donorRoot = await EnsureLibraryCachedAsync(a.LibraryItemId!, "armor", http, emitDetail,
                    progressBase: 51, progressSpan: 2);
            }
            else if (a.Kind == "import" && !string.IsNullOrWhiteSpace(a.DonorReduxId))
            {
                emitDetail?.Invoke("downloading_new", 51, Loc.T("progress.armor.downloading"));
                donorRoot = await EnsureDonorCachedAsync(a.DonorReduxId!, "armor", http, emitDetail, a.DonorVersionId,
                    progressBase: 51, progressSpan: 2);
            }
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[redux.customize][armor.{a.Kind}] download FAIL: {ex.Message}");
            notes.Add($"[Броник] Не удалось скачать донора: {ex.Message}");
            importFailures.Add($"Броник: ошибка скачивания донора ({a.Kind}): {ex.Message}");
            return false;
        }
        if (donorRoot is null)
        {
            notes.Add("[Броник] Донор не подготовлен.");
            var src = a.Kind == "library" ? $"library:{a.LibraryItemId}" : $"redux:{a.DonorReduxId}";
            importFailures.Add($"Броник: донор {src}" + (a.DonorVersionId.HasValue ? $" (v={a.DonorVersionId})" : "") + " не доехал.");
            return false;
        }
        var donorArmorDir = Path.Combine(donorRoot, "components", "armor");
        if (!Directory.Exists(donorArmorDir) || !Directory.EnumerateFileSystemEntries(donorArmorDir).Any())
        {
            notes.Add($"[Броник] У донора нет компонента armor.");
            var src = a.Kind == "library" ? $"library:{a.LibraryItemId}" : $"redux:{a.DonorReduxId}";
            importFailures.Add($"Броник: у донора {src}" + (a.DonorVersionId.HasValue ? $" (v={a.DonorVersionId})" : "") + " нет компонента armor.");
            return false;
        }
        try
        {
            emitDetail?.Invoke("applying_user_changes", 53, Loc.T("progress.armor.applying"));
            var svc = new Core.Services.ArmorTransferService();
            var r = svc.Transfer(new Core.Services.ArmorTransferRequest
            {
                RecipientPatchRoot = workDir,
                RecipientManifest = manifest,
                DonorPatchRoot = donorRoot,
            });
            if (!r.Success)
            {
                notes.Add($"[Броник] {r.Message}");
                importFailures.Add($"Броник: сбой переноса: {r.Message}");
                return false;
            }
            return true;
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[redux.customize][armor.transfer] FAIL: {ex.Message}");
            notes.Add($"[Броник] Сбой переноса: {ex.Message}");
            importFailures.Add($"Броник: исключение при переносе: {ex.Message}");
            return false;
        }
    }

