    private async Task QueueGenericAsync(
        string componentName,
        GenericSettingDto g,
        string workDir,
        Dictionary<string, string> donorSelections,
        System.Net.Http.HttpClient http,
        List<string> notes,
        Action<string, int, string?>? emitDetail = null)
    {
        if (g.Kind == "default") return;
        if (g.Kind == "clear")
        {

            return;
        }

        try
        {
            string? donor = null;
            if (g.Kind == "library" && !string.IsNullOrWhiteSpace(g.LibraryItemId))
            {
                emitDetail?.Invoke("downloading_new", 59, Loc.T("progress.build.downloadingComponent", ("component", ComponentLabelLoc(componentName))));
                donor = await EnsureLibraryCachedAsync(g.LibraryItemId!, componentName, http, emitDetail,
                    progressBase: 59, progressSpan: 2);
            }
            else if (g.Kind == "import" && !string.IsNullOrWhiteSpace(g.DonorReduxId))
            {
                emitDetail?.Invoke("downloading_new", 59, Loc.T("progress.build.downloadingComponent", ("component", ComponentLabelLoc(componentName))));
                donor = await EnsureDonorCachedAsync(g.DonorReduxId!, componentName, http, emitDetail, g.DonorVersionId,
                    progressBase: 59, progressSpan: 2);
            }

            if (donor is null)
            {
                notes.Add($"[{ComponentLabel(componentName)}] Донор не подготовлен.");
                return;
            }

            donorSelections[componentName] = donor;
            _ = workDir;
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[redux.customize][{componentName}] queue FAIL: {ex.Message}");
            notes.Add($"[{ComponentLabel(componentName)}] Не удалось подготовить донора: {ex.Message}");
        }
    }

    private static string ComponentLabel(string name) => name switch
    {
        "minimap"   => "Минимапа",
        "crosshair" => "Прицел",
        "tracers"   => "Трейсера",
        "bloodfx"   => "Эффекты",
        "timecycle" => "Таймциклы",
        "armor"     => "Броник",
        "arena"     => "Арена",
        _           => name,
    };

    private static string ComponentLabelLoc(string name)
        => Loc.Has("progress.component." + name)
            ? Loc.T("progress.component." + name)
            : ComponentLabel(name).ToLowerInvariant();

    private const string CustomizeCacheRoot = "customize_donor_cache";

    private static readonly System.Text.RegularExpressions.Regex TracerFxNonEmptyRegex =
        new(@"<TracerFx>\s*([^<\s][^<]*?)\s*</TracerFx>",
            System.Text.RegularExpressions.RegexOptions.Compiled | System.Text.RegularExpressions.RegexOptions.IgnoreCase);

    private async Task ApplyDonorTracerBindingFilesAsync(
        string workDir,
        Core.Parser.DiffManifest manifest,
        string donorReduxId,
        Guid? donorVersionId,
        string donorRoot,
        System.Net.Http.HttpClient http,
        List<string> notes,
        Action<string, int, string?>? emitDetail)
    {
        var donorManifestPath = Path.Combine(donorRoot, "manifest.json");
        if (!File.Exists(donorManifestPath))
        {
            Debug.WriteLine("[tracers.bindings] donor manifest.json отсутствует - пропуск привязок");
            return;
        }

        Core.Parser.DiffManifest? donorManifest;
        try
        {
            donorManifest = JsonSerializer.Deserialize<Core.Parser.DiffManifest>(
                await File.ReadAllTextAsync(donorManifestPath), ReduxJson);
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[tracers.bindings] donor manifest parse fail: {ex.Message}");
            return;
        }
        if (donorManifest?.Actions == null) return;

        static string Norm(string p) => p.Replace('\\', '/').TrimStart('/');

        var wanted = donorManifest.Actions
            .Where(a => a.Type != Core.Parser.ActionType.Delete && !string.IsNullOrWhiteSpace(a.TargetPath))
            .Where(a =>
            {
                var tp = Norm(a.TargetPath);
                if (tp.Equals("common/data/effects/ptxclipregions.dat", StringComparison.OrdinalIgnoreCase)) return true;
                if (tp.Equals("common/data/effects/weaponfx.dat", StringComparison.OrdinalIgnoreCase)) return true;
                return tp.EndsWith(".meta", StringComparison.OrdinalIgnoreCase) &&
                       tp.Contains("/ai/", StringComparison.OrdinalIgnoreCase);
            })
            .ToList();

        if (wanted.Count == 0)
        {
            Console.WriteLine("[tracers.bindings] у донора нет weaponfx.dat/оружейных мет - привязки не нужны.");
            return;
        }

        var resolved = await ResolveVersionAsync(donorReduxId, donorVersionId);
        if (resolved is null || string.IsNullOrWhiteSpace(resolved.Urls.Patch))
        {
            Console.WriteLine("[tracers.bindings] у донора нет URL patch.zip - пропуск привязок.");
            return;
        }

        string patchCacheRoot = MiamiGraphics.Shell.Services.ModCacheSettings.Dir("redux_patches");
        string? cachePath = !string.IsNullOrWhiteSpace(resolved.PatchSha256)
            ? Path.Combine(patchCacheRoot, $"{donorReduxId}_{resolved.PatchSha256[..Math.Min(16, resolved.PatchSha256.Length)]}.zip")
            : null;

        string? zipPath = null;
        string? tempZip = null;
        if (cachePath != null && File.Exists(cachePath)
            && Services.VerifiedDownload.CachedFileOk(cachePath, resolved.PatchSha256,
                $"patch.zip донора «{donorReduxId}»"))
        {
            zipPath = cachePath;
            Console.WriteLine($"[tracers.bindings] patch.zip донора из кэша: {cachePath}");
        }
        else
        {
            tempZip = Path.Combine(Path.GetTempPath(), "tracer_donor_patch_" + Guid.NewGuid().ToString("N") + ".zip");
            emitDetail?.Invoke("downloading_new", -1, Loc.T("progress.tracers.downloadingDonorBindings"));
            Console.WriteLine($"[tracers.bindings] качаю patch.zip донора: {resolved.Urls.Patch}");
            await DownloadFileAsync(http, resolved.Urls.Patch!, tempZip,
                bytesProgress: (received, total) =>
                {
                    if (total > 0)
                        emitDetail?.Invoke("downloading_new", -1,
                            $"привязки трейсера - {received / 1024 / 1024} / {Math.Max(1, total / 1024 / 1024)} МБ");
                });

            Services.VerifiedDownload.RequireReference(resolved.PatchSha256,
                $"patch.zip донора «{donorReduxId}»");
            {
                var actualSha = await Task.Run(() => ComputeFileSha256(tempZip));
                if (!Services.VerifiedDownload.Matches(resolved.PatchSha256, actualSha))
                {
                    try { File.Delete(tempZip); } catch { }
                    throw new Services.IntegrityException(
                        $"patch.zip донора «{donorReduxId}» не прошёл проверку целостности и удалён.");
                }
                if (cachePath != null)
                {
                    try
                    {
                        Directory.CreateDirectory(patchCacheRoot);
                        File.Copy(tempZip, cachePath, overwrite: true);
                    }
                    catch (Exception cacheEx) { Debug.WriteLine($"[tracers.bindings] cache save fail: {cacheEx.Message}"); }
                }
            }
            zipPath = tempZip;
        }

        int carried = 0;
        try
        {
            using var zip = System.IO.Compression.ZipFile.OpenRead(zipPath!);
            foreach (var action in wanted)
            {
                string tp = Norm(action.TargetPath);
                var entry = zip.Entries.FirstOrDefault(e =>
                    Norm(e.FullName).Equals(tp, StringComparison.OrdinalIgnoreCase));
                if (entry == null)
                {
                    Console.WriteLine($"[tracers.bindings] '{tp}' нет в patch.zip донора - пропуск.");
                    continue;
                }

                byte[] bytes;
                using (var ms = new MemoryStream())
                using (var es = entry.Open())
                {
                    await es.CopyToAsync(ms);
                    bytes = ms.ToArray();
                }

                bool isEffectsDat = tp.EndsWith(".dat", StringComparison.OrdinalIgnoreCase);
                if (!isEffectsDat)
                {
                    string text;
                    try { text = System.Text.Encoding.UTF8.GetString(bytes); }
                    catch { continue; }
                    if (!TracerFxNonEmptyRegex.IsMatch(text))
                    {
                        Console.WriteLine($"[tracers.bindings] '{tp}' без TracerFx - пропуск.");
                        continue;
                    }
                }

                string patchFilesRoot = Path.Combine(workDir, "patch_files");
                if (!Core.System.SafePath.TryResolveInside(patchFilesRoot, tp, out var physicalPath, out var whyTp))
                {
                    Console.WriteLine($"[tracers.bindings] '{tp}' отклонён - {whyTp}");
                    continue;
                }
                string? physDir = Path.GetDirectoryName(physicalPath);
                if (!string.IsNullOrEmpty(physDir)) Directory.CreateDirectory(physDir);
                await File.WriteAllBytesAsync(physicalPath, bytes);

                Core.Services.PatchCustomizationSupport.UpsertPatchAction(
                    manifest, workDir,
                    new Core.Services.PatchWorkspaceFile
                    {
                        TargetPath   = tp,
                        PhysicalPath = physicalPath,
                        ActionType   = action.Type
                    });

                Console.WriteLine($"[tracers.bindings] донор → {tp} ({bytes.Length} b, {action.Type})");
                carried++;
            }
        }
        finally
        {
            if (tempZip != null && tempZip != cachePath)
                try { File.Delete(tempZip); } catch { }
        }

        if (carried > 0)
        {
            Core.Services.PatchCustomizationSupport.RecalculateTotalPatchSize(manifest);
            Console.WriteLine($"[tracers.bindings] перенесено файлов-привязок: {carried}.");
        }
    }

    private async Task<string?> EnsureDonorCachedAsync(
        string donorReduxId,
        string componentName,
        System.Net.Http.HttpClient http,
        Action<string, int, string?>? emitDetail = null,
        Guid? donorVersionId = null,
        int progressBase = -1,
        int progressSpan = 0)
    {

        var resolved = await ResolveVersionAsync(donorReduxId, donorVersionId);
        if (resolved is null) return null;
        if (string.IsNullOrWhiteSpace(resolved.Urls.Manifest))
        {
            Debug.WriteLine($"[redux.customize.donor] {donorReduxId} (v={donorVersionId}) has no manifest URL");
            return null;
        }

        EnsureCustomizeCacheMigrationDoneOnce();

        var cacheKey = resolved.IsLegacy
            ? donorReduxId
            : $"{donorReduxId}__v{resolved.Slot}";
        var cacheRoot = MiamiGraphics.Shell.Services.ModCacheSettings.Dir(CustomizeCacheRoot, cacheKey);

        var donorShas = await ReduxAssetShasAsync(resolved.VersionId);
        var manifestPath = Path.Combine(cacheRoot, "manifest.json");
        if (!string.IsNullOrWhiteSpace(resolved.Urls.Manifest))
            await Services.VerifiedDownload.EnsureFileAsync(resolved.Urls.Manifest!, manifestPath,
                donorShas.Manifest, $"manifest.json донора «{cacheKey}»", referenceRequired: false);

        var componentMapPath = Path.Combine(cacheRoot, "component_map.json");
        if (!string.IsNullOrWhiteSpace(resolved.Urls.ComponentMap))
            await Services.VerifiedDownload.EnsureFileAsync(resolved.Urls.ComponentMap!, componentMapPath,
                donorShas.ComponentMap, $"component_map.json донора «{cacheKey}»", referenceRequired: false);

        if (!resolved.Urls.Components.TryGetValue(componentName, out var compUrl) ||
            string.IsNullOrWhiteSpace(compUrl))
        {
            Debug.WriteLine($"[redux.customize.donor] {cacheKey} has no '{componentName}.zip' URL");
            return null;
        }

        var componentDir = Path.Combine(cacheRoot, "components", componentName);

        string componentSha = string.Empty;
        bool haveComponentRef = Services.VerifiedDownload.Normalize(componentSha).Length > 0;
        bool cacheOk = Directory.Exists(componentDir)
            && (!haveComponentRef || Services.VerifiedDownload.SidecarMarkerMatches(componentDir, componentSha));

        if (cacheOk)
        {
            emitDetail?.Invoke("downloading_new", -1, Loc.T("progress.build.componentCacheHit", ("component", ComponentLabelLoc(componentName))));
        }
        else
        {
            if (Directory.Exists(componentDir))
                try { Directory.Delete(componentDir, recursive: true); } catch { }

            var zipPath = Path.Combine(cacheRoot, $"{componentName}.zip");
            emitDetail?.Invoke("downloading_new", -1, Loc.T("progress.build.downloadingComponent", ("component", ComponentLabelLoc(componentName))));
            await Services.VerifiedDownload.FetchAsync(compUrl, zipPath, componentSha,
                $"{componentName}.zip донора «{cacheKey}»",
                bytesProgress: (received, total) =>
                {
                    if (total > 0)
                    {
                        var msg = total >= 1024 * 1024
                            ? $"{componentName}.zip - {received / 1024 / 1024} / {total / 1024 / 1024} МБ"
                            : $"{componentName}.zip - {received / 1024} / {Math.Max(1, total / 1024)} КБ";
                        var pct = progressBase >= 0
                            ? progressBase + (int)Math.Min(progressSpan, received * progressSpan / total)
                            : -1;
                        emitDetail?.Invoke("downloading_new", pct, msg);
                    }
                },
                referenceRequired: false);
            Directory.CreateDirectory(componentDir);
            System.IO.Compression.ZipFile.ExtractToDirectory(zipPath, componentDir, overwriteFiles: true);
            Services.VerifiedDownload.WriteSidecarMarker(componentDir, componentSha);
            try { File.Delete(zipPath); } catch { }
        }

        return cacheRoot;
    }

    private static bool _migrationChecked;
    private static readonly object _migrationLock = new();
    private static void EnsureCustomizeCacheMigrationDoneOnce()
    {
        if (_migrationChecked) return;
        lock (_migrationLock)
        {
            if (_migrationChecked) return;
            try
            {
                var rootCache = MiamiGraphics.Shell.Services.ModCacheSettings.Dir(CustomizeCacheRoot);
                var marker = Path.Combine(rootCache, ".v3_migration_done");
                if (Directory.Exists(rootCache) && !File.Exists(marker))
                {
                    Debug.WriteLine($"[redux.customize.cache] migrating: wiping legacy donor cache at {rootCache}");
                    try { Directory.Delete(rootCache, recursive: true); } catch { }
                }
                Directory.CreateDirectory(rootCache);
                File.WriteAllText(marker, DateTime.UtcNow.ToString("O"));
            }
            catch (Exception ex)
            {
                Debug.WriteLine($"[redux.customize.cache] migration FAILED: {ex.Message}");
            }
            _migrationChecked = true;
        }
    }

    private async Task<string?> EnsureLibraryCachedAsync(
        string libraryItemId,
        string componentName,
        System.Net.Http.HttpClient http,
        Action<string, int, string?>? emitDetail = null,
        int progressBase = -1,
        int progressSpan = 0)
    {

        var rows = await _supabase.SelectAsync<LibraryRow>(
            "library_components",
            $"select=id,type,r2_url,sha256,name&id=eq.{Uri.EscapeDataString(libraryItemId)}&limit=1");
        var row = rows.FirstOrDefault();
        if (row is null || string.IsNullOrWhiteSpace(row.R2Url)) return null;

        var label = string.IsNullOrWhiteSpace(row.Name) ? $"{componentName} ({libraryItemId})" : row.Name;
        Services.VerifiedDownload.RequireReference(row.Sha256, label);

        var cacheRoot = MiamiGraphics.Shell.Services.ModCacheSettings.Dir(CustomizeCacheRoot, "library", libraryItemId);

        var componentDir = Path.Combine(cacheRoot, "components", componentName);
        if (Directory.Exists(componentDir)
            && !Services.VerifiedDownload.SidecarMarkerMatches(componentDir, row.Sha256))
        {
            Debug.WriteLine($"[library.cache] '{componentName}' у {libraryItemId} без метки проверки - перекачиваю");
            try { Directory.Delete(componentDir, recursive: true); }
            catch (Exception ex) { Debug.WriteLine($"[library.cache] снести каталог не вышло: {ex.Message}"); }
        }

        if (!Directory.Exists(componentDir))
        {
            var zipPath = Path.Combine(cacheRoot, $"{componentName}.zip");
            await Services.VerifiedDownload.FetchAsync(row.R2Url, zipPath, row.Sha256, label,
                bytesProgress: (received, total) =>
                {
                    if (total > 0)
                    {
                        var msg = total >= 1024 * 1024
                            ? $"{componentName}.zip - {received / 1024 / 1024} / {total / 1024 / 1024} МБ"
                            : $"{componentName}.zip - {received / 1024} / {Math.Max(1, total / 1024)} КБ";
                        var pct = progressBase >= 0
                            ? progressBase + (int)Math.Min(progressSpan, received * progressSpan / total)
                            : -1;
                        emitDetail?.Invoke("downloading_new", pct, msg);
                    }
                },
                hashProgress: (done, total) => emitDetail?.Invoke("downloading_new", -1,
                    $"Проверяю целостность {componentName}.zip - {done / 1024} / {Math.Max(1, total / 1024)} КБ"));
            Directory.CreateDirectory(componentDir);
            System.IO.Compression.ZipFile.ExtractToDirectory(zipPath, componentDir, overwriteFiles: true);
            Services.VerifiedDownload.WriteSidecarMarker(componentDir, row.Sha256);
            try { File.Delete(zipPath); } catch { }
        }

        var componentMapPath = Path.Combine(cacheRoot, "component_map.json");
        if (!File.Exists(componentMapPath))
        {
            var paths = Directory.EnumerateFiles(componentDir, "*", SearchOption.AllDirectories)
                .Select(p => Path.GetRelativePath(componentDir, p).Replace('\\', '/'))
                .OrderBy(p => p, StringComparer.OrdinalIgnoreCase)
                .ToList();
            var fakeMap = new
            {
                Components = new Dictionary<string, object>
                {
                    [componentName] = new
                    {
                        IsFound = true,
                        SourceRpf = paths.FirstOrDefault() ?? "",
                        InternalPaths = paths,
                        Flags = new[] { "library" }
                    }
                }
            };
            await File.WriteAllTextAsync(componentMapPath,
                JsonSerializer.Serialize(fakeMap, new JsonSerializerOptions { WriteIndented = true }));
        }

        return cacheRoot;
    }

    private static string ResolveTracerModelDir(string folderName)
    {
        var root = ResolveAdditionalsRoot();
        if (root is null) return string.Empty;
        var p = Path.Combine(root, "tracers", folderName);
        return Directory.Exists(p) ? p : string.Empty;
    }

    private static string? ResolveAdditionalsRoot()
        => Services.AdditionalsResolver.FindAdditionalsRoot();

    private async Task<byte[]?> ResolveVanillaFrontendXmlBytesAsync()
    {
        var cachePath = Path.Combine(Core.System.AppDataRoot.Dir(), "frontend_vanilla.xml");
        try
        {
            if (File.Exists(cachePath) && new FileInfo(cachePath).Length > 0)
                return await File.ReadAllBytesAsync(cachePath);
        }
        catch { }

        try
        {
            var cfg = await _adminConfig.GetAsync();
            var r2 = (cfg.R2PublicUrl ?? string.Empty).TrimEnd('/');
            if (!string.IsNullOrEmpty(r2))
            {
                using var http = new HttpClient { Timeout = TimeSpan.FromSeconds(30) };
                using var resp = await http.GetAsync($"{r2}/assets/frontend.xml");
                if (resp.IsSuccessStatusCode)
                {
                    var bytes = await resp.Content.ReadAsByteArrayAsync();
                    if (bytes.Length > 0)
                    {
                        try { Directory.CreateDirectory(Path.GetDirectoryName(cachePath)!); await File.WriteAllBytesAsync(cachePath, bytes); } catch { }
                        return bytes;
                    }
                }
            }
        }
        catch (Exception ex) { Debug.WriteLine($"[minimap.fallback] R2 frontend.xml fetch failed: {ex.Message}"); }

        try
        {
            var root = ResolveAdditionalsRoot();
            if (root != null)
            {
                foreach (var p in new[]
                {
                    Path.Combine(root, "frontend.xml", "frontend.xml"),
                    Path.Combine(root, "frontend.xml", "frontend_vanilla.xml"),
                    Path.Combine(root, "minimap", "frontend_vanilla.xml"),
                })
                {
                    if (File.Exists(p) && new FileInfo(p).Length > 0)
                        return await File.ReadAllBytesAsync(p);
                }
            }
        }
        catch (Exception ex) { Debug.WriteLine($"[minimap.fallback] bundled frontend.xml read failed: {ex.Message}"); }

        return null;
    }

    private async Task<string?> EnsureMinimapJavaAsync(
        string? resolvedJava,
        List<string> notes,
        Action<string, int, string?>? emitDetail)
    {
        if (resolvedJava is not null && resolvedJava != "java" && File.Exists(resolvedJava))
            return resolvedJava;

        if (await Task.Run(() => ProbeJavaWorks("java")))
            return "java";

        emitDetail?.Invoke("applying_user_changes", 45, Loc.T("progress.minimap.downloadingJava"));
        try
        {
            var boot = new Services.JreBootstrapper();
            var progress = new Progress<(string Phase, double Percent)>(p =>
            {
                if (p.Phase == "downloading")
                    emitDetail?.Invoke("applying_user_changes", 45,
                        Loc.T("progress.minimap.downloadingJavaPct", ("pct", p.Percent.ToString("F0", global::System.Globalization.CultureInfo.InvariantCulture))));
            });
            var r = await boot.EnsureInstalledAsync(progress);
            if (r.Success)
            {
                var candidate = Path.Combine(r.JrePath, "bin", "java.exe");
                if (File.Exists(candidate)) return candidate;
                var (again, _, _) = ResolveMinimapTools();
                if (again is not null && again != "java" && File.Exists(again)) return again;
            }
            notes.Add($"[Минимапа] Java не установилась: {r.ErrorMessage ?? "java.exe не найден после распаковки"}");
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[minimap.jre] ensure FAIL: {ex.GetType().Name}: {ex.Message}");
            notes.Add($"[Минимапа] Java не установилась: {ex.Message}");
        }
        return null;
    }

    private static bool ProbeJavaWorks(string javaExe)
    {
        try
        {
            using var p = new Process
            {
                StartInfo = new ProcessStartInfo
                {
                    FileName = javaExe,
                    Arguments = "-version",
                    UseShellExecute = false,
                    CreateNoWindow = true,
                    RedirectStandardOutput = true,
                    RedirectStandardError = true,
                },
            };
            p.Start();
            p.StandardOutput.ReadToEnd();
            p.StandardError.ReadToEnd();
            if (!p.WaitForExit(8_000))
            {
                try { p.Kill(true); } catch { }
                return false;
            }
            return p.ExitCode == 0;
        }
        catch
        {
            return false;
        }
    }

    private static (string? Java, string? FfdecJar, string? Swfmill) ResolveMinimapTools()
    {
        var root = ResolveAdditionalsRoot();
        if (root is null) return (null, null, null);

        string? PickFile(string relative)
        {
            var p = Path.Combine(root, relative);
            return File.Exists(p) ? p : null;
        }

        string? java =
            PickFile(Path.Combine("jre", "bin", "java.exe")) ??
            PickFile(Path.Combine("jre", "bin", "javaw.exe")) ??
            PickFile(Path.Combine("jre", "java.exe")) ??
            PickFile(Path.Combine("jre", "javaw.exe"));

        if (java is null)
        {

            var jreRoot = Path.Combine(root, "jre");
            if (Directory.Exists(jreRoot))
            {
                foreach (var sub in Directory.EnumerateDirectories(jreRoot))
                {
                    var candidate = Path.Combine(sub, "bin", "java.exe");
                    if (File.Exists(candidate)) { java = candidate; break; }
                }
            }
        }

        java ??= "java";

        return (
            Java:     java,
            FfdecJar: PickFile(Path.Combine("minimap", "ffdec.jar")),
            Swfmill:  PickFile(Path.Combine("minimap", "swfmill.exe"))
        );
    }

    private static (byte R, byte G, byte B) ParseHex(string hex)
    {
        if (string.IsNullOrWhiteSpace(hex)) return (255, 255, 255);
        var s = hex.StartsWith("#") ? hex[1..] : hex;
        if (s.Length != 6) return (255, 255, 255);
        try
        {
            return (
                Convert.ToByte(s.Substring(0, 2), 16),
                Convert.ToByte(s.Substring(2, 2), 16),
                Convert.ToByte(s.Substring(4, 2), 16)
            );
        }
        catch { return (255, 255, 255); }
    }

    public async Task<List<GtaVersionDto>> GtaVersionsListAsync()
    {
        var rows = await _supabase.SelectAsync<GtaVersionRow>(
            "gta_versions",
            "select=*&order=exe_version.desc");
        return rows.Select(r => new GtaVersionDto(
            r.ExeVersion,
            r.UpdateRpfSize,
            r.UpdateRpfSha256,
            r.CleanUpdateUrl,
            r.Notes,
            r.CreatedAt,
            r.UpdatedAt,
            r.GunsRpfSize,
            r.GunsRpfSha256)).ToList();
    }

    private async Task<string> AdminServiceKeyAsync()
    {
        var key = (await _adminConfig.GetAsync()).SupabaseServiceKey;
        if (string.IsNullOrWhiteSpace(key))
            throw new InvalidOperationException(
                "Не задан Supabase Service Role Key в Admin → Настройки (запись каталога заблокирована RLS для anon).");
        return key;
    }

    public async Task GtaVersionsUpsertAsync(GtaVersionDto v)
    {
        await _supabase.UpsertWithServiceRoleAsync("gta_versions", new
        {
            exe_version       = v.ExeVersion,
            update_rpf_size   = v.UpdateRpfSize,
            update_rpf_sha256 = (v.UpdateRpfSha256 ?? string.Empty).ToLowerInvariant(),
            clean_update_url  = v.CleanUpdateUrl ?? string.Empty,
            notes             = v.Notes ?? string.Empty,
            guns_rpf_size     = v.GunsRpfSize,
            guns_rpf_sha256   = string.IsNullOrEmpty(v.GunsRpfSha256) ? null : v.GunsRpfSha256!.ToLowerInvariant(),
            updated_at        = DateTime.UtcNow,
        }, await AdminServiceKeyAsync());
    }

