    public async Task<GtaVersionAutoFillDto> GtaVersionsAutoFillAsync(string cleanRpfPath)
    {
        if (string.IsNullOrWhiteSpace(cleanRpfPath) || !File.Exists(cleanRpfPath))
            throw new InvalidOperationException("Файл update.rpf не найден.");

        string? exeVersion = TryReadSiblingGta5ExeVersion(cleanRpfPath);

        var size = new FileInfo(cleanRpfPath).Length;
        var sha  = await Task.Run(() => ComputeFileSha256(cleanRpfPath));

        return new GtaVersionAutoFillDto(exeVersion ?? string.Empty, size, sha);
    }

    public async Task<GtaVersionDto> GtaVersionsUploadAsync(string cleanRpfPath, string exeVersion, string notes)
    {
        if (string.IsNullOrWhiteSpace(cleanRpfPath) || !File.Exists(cleanRpfPath))
            throw new InvalidOperationException("Файл update.rpf не найден.");
        if (string.IsNullOrWhiteSpace(exeVersion))
            throw new InvalidOperationException("Не указана версия (exeVersion).");

        var size = new FileInfo(cleanRpfPath).Length;
        var sha  = await Task.Run(() => ComputeFileSha256(cleanRpfPath));

        var key = $"gta_versions/{exeVersion}/clean_update.rpf";
        Debug.WriteLine($"[gta_versions.upload] {cleanRpfPath} -> {key}");
        var url = await _remoteStorage.UploadAsync(cleanRpfPath, key, progress: null, CancellationToken.None);

        var dto = new GtaVersionDto(
            ExeVersion: exeVersion,
            UpdateRpfSize: size,
            UpdateRpfSha256: sha,
            CleanUpdateUrl: url,
            Notes: notes ?? string.Empty,
            CreatedAt: DateTime.UtcNow,
            UpdatedAt: DateTime.UtcNow);

        await GtaVersionsUpsertAsync(dto);
        return dto;
    }

    private static string? TryReadSiblingGta5ExeVersion(string rpfPath)
    {

        try
        {
            var updateDir = Path.GetDirectoryName(rpfPath);
            var rootDir   = updateDir is null ? null : Path.GetDirectoryName(updateDir);
            if (rootDir is null) return null;
            var exe = Path.Combine(rootDir, "GTA5.exe");
            if (!File.Exists(exe)) return null;
            return FileVersionInfo.GetVersionInfo(exe).FileVersion;
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[gta_versions.autofill] couldn't read GTA5.exe version: {ex.Message}");
            return null;
        }
    }

    private static string ComputeFileSha256(string path)
        => ComputeFileSha256(path, null);

    private static string ComputeFileSha256(string path, Action<long, long>? bytesProgress)
    {
        using var sha = System.Security.Cryptography.SHA256.Create();
        using var fs = new FileStream(path, FileMode.Open, FileAccess.Read, FileShare.Read,
            bufferSize: 1 << 20, useAsync: false);
        if (bytesProgress is null)
            return Convert.ToHexString(sha.ComputeHash(fs)).ToLowerInvariant();

        long size = fs.Length;
        const int chunk = 4 * 1024 * 1024;
        var buffer = new byte[chunk];
        long done = 0, lastReported = 0;
        int read;
        bytesProgress(0, size);
        while ((read = fs.Read(buffer, 0, chunk)) > 0)
        {
            sha.TransformBlock(buffer, 0, read, null, 0);
            done += read;
            if (done - lastReported >= 16L * 1024 * 1024 || done >= size)
            {
                lastReported = done;
                bytesProgress(done, size);
            }
        }
        sha.TransformFinalBlock(Array.Empty<byte>(), 0, 0);
        return Convert.ToHexString(sha.Hash!).ToLowerInvariant();
    }

    private static readonly TimeSpan ExtractReportGap = TimeSpan.FromMilliseconds(200);

    private static void ExtractZipWithProgress(string zipPath, string destDir,
        Action<int, int, string>? onEntry)
    {
        Directory.CreateDirectory(destDir);

        using var archive = System.IO.Compression.ZipFile.OpenRead(zipPath);
        var entries = archive.Entries;
        int total = entries.Count, i = 0;
        var sw = System.Diagnostics.Stopwatch.StartNew();
        long lastReportMs = -(long)ExtractReportGap.TotalMilliseconds;
        foreach (var entry in entries)
        {
            i++;
            if (!Core.System.SafePath.TryResolveInside(destDir, entry.FullName, out var targetPath, out var whyEntry))
                throw new IOException(
                    $"Запись архива выходит за пределы каталога распаковки: '{entry.FullName}' - {whyEntry}.");

            if (string.IsNullOrEmpty(entry.Name))
            {
                Directory.CreateDirectory(targetPath);
                continue;
            }
            Directory.CreateDirectory(Path.GetDirectoryName(targetPath)!);
            System.IO.Compression.ZipFileExtensions.ExtractToFile(entry, targetPath, overwrite: true);
            var nowMs = sw.ElapsedMilliseconds;
            if (nowMs - lastReportMs >= ExtractReportGap.TotalMilliseconds)
            {
                lastReportMs = nowMs;
                onEntry?.Invoke(i, total, entry.Name);
            }
        }
        onEntry?.Invoke(total, total, string.Empty);
    }

    public async Task<List<LibraryComponentDto>> LibraryListAsync(string? type)
    {
        var query = string.IsNullOrWhiteSpace(type)
            ? "select=*&order=type.asc,uploaded_at.desc"
            : $"select=*&type=eq.{Uri.EscapeDataString(type)}&order=uploaded_at.desc";
