    public async Task<LibraryComponentDto> LibraryUploadComponentAsync(LibraryUploadDto p)
    {
        if (string.IsNullOrWhiteSpace(p.WorkDir) || !Directory.Exists(p.WorkDir))
            throw new InvalidOperationException("workDir не существует - сначала запусти Analyze.");
        if (string.IsNullOrWhiteSpace(p.ComponentName))
            throw new InvalidOperationException("Не указано какой компонент сохранять.");
        if (string.IsNullOrWhiteSpace(p.Name))
            throw new InvalidOperationException("Не указано имя в библиотеке.");

        var componentDir = Path.Combine(p.WorkDir, "components", p.ComponentName);
        if (!Directory.Exists(componentDir))
            throw new InvalidOperationException($"Компонент '{p.ComponentName}' не найден в workDir/components/.");

        var manifestPath = Path.Combine(p.WorkDir, "manifest.json");
        var sourceVersion = TryReadGtaVersionFromManifest(manifestPath) ?? string.Empty;

        var libraryId = $"lib_{p.ComponentName}_{Guid.NewGuid().ToString("N")[..8]}";
        var zipPath = Path.Combine(Path.GetTempPath(), $"{libraryId}.zip");
        try
        {
            if (File.Exists(zipPath)) File.Delete(zipPath);
            System.IO.Compression.ZipFile.CreateFromDirectory(
                componentDir, zipPath,
                System.IO.Compression.CompressionLevel.Optimal,
                includeBaseDirectory: false);

            var size = new FileInfo(zipPath).Length;
            var sha  = await Task.Run(() => ComputeFileSha256(zipPath));

            var key = $"library/{p.ComponentName}/{libraryId}.zip";
            Debug.WriteLine($"[library.upload] {zipPath} -> {key} ({size / 1024} KB)");
            var url = await _remoteStorage.UploadAsync(zipPath, key, progress: null, CancellationToken.None);

            var dto = new LibraryComponentDto(
                Id: libraryId,
                Type: p.ComponentName,
                Name: p.Name,
                Author: p.Author ?? string.Empty,
                Description: p.Description ?? string.Empty,
                R2Url: url,
                Sha256: sha,
                SizeBytes: size,
                SourceRpfVersion: sourceVersion,
                UploadedBy: string.Empty,
                UploadedAt: DateTime.UtcNow);

            await _supabase.UpsertWithServiceRoleAsync("library_components", new
            {
                id                  = dto.Id,
                type                = dto.Type,
                name                = dto.Name,
                author              = dto.Author,
                description         = dto.Description,
                r2_url              = dto.R2Url,
                sha256              = dto.Sha256,
                size_bytes          = dto.SizeBytes,
                source_rpf_version  = dto.SourceRpfVersion,
                uploaded_by         = dto.UploadedBy,
            }, await AdminServiceKeyAsync());

            return dto;
        }
        finally
        {
            try { if (File.Exists(zipPath)) File.Delete(zipPath); } catch {  }
        }
    }

    public async Task<LibraryComponentDto> LibraryPatchAsync(LibraryPatchDto p)
    {
        if (string.IsNullOrWhiteSpace(p.Id))
            throw new InvalidOperationException("id обязателен.");
        if (string.IsNullOrWhiteSpace(p.Name))
            throw new InvalidOperationException("Имя пресета обязательно.");

        await _supabase.UpdateWithServiceRoleAsync("library_components",
            $"id=eq.{Uri.EscapeDataString(p.Id)}",
            new
            {
                name        = p.Name.Trim(),
                author      = (p.Author ?? string.Empty).Trim(),
                description = (p.Description ?? string.Empty).Trim(),
            }, await AdminServiceKeyAsync());

        var rows = await _supabase.SelectAsync<LibraryRow>(
            "library_components",
            $"select=*&id=eq.{Uri.EscapeDataString(p.Id)}");
        var r = rows.FirstOrDefault()
            ?? throw new InvalidOperationException("Пресет не найден после обновления.");
        return new LibraryComponentDto(
            r.Id, r.Type, r.Name, r.Author, r.Description,
            r.R2Url, r.Sha256, r.SizeBytes, r.SourceRpfVersion,
            r.UploadedBy, r.UploadedAt,
            r.PreviewUrl ?? string.Empty,
            r.GalleryUrls ?? new List<string>(),
            r.PreviewVideoUrl ?? string.Empty);
    }

