    public Task<CurrentMinimapInfoDto?> GetCurrentMinimapInfoAsync() => Task.Run(() =>
    {
        try
        {
            var state = ReadInstallState();
            var draft = state?.CustomizationDraft;
            if (draft is null) return (CurrentMinimapInfoDto?)null;
            if (!string.IsNullOrWhiteSpace(draft.Minimap?.LibraryItemId))
            {

                var libId = draft.Minimap!.LibraryItemId!;
                string name = "";
                try
                {
                    var rows = _supabase.SelectAsync<LibraryRow>(
                        "library_components",
                        $"select=id,name,type&id=eq.{Uri.EscapeDataString(libId)}").Result;
                    name = rows.FirstOrDefault()?.Name ?? "";
                }
                catch {  }
                return (CurrentMinimapInfoDto?)new CurrentMinimapInfoDto("library", libId, name);
            }
            if (!string.IsNullOrWhiteSpace(draft.Minimap?.ImportedFromReduxId))
            {
                var rid = draft.Minimap!.ImportedFromReduxId!;
                string name = rid;
                try { name = _catalog.GetByIdAsync(rid).Result?.Name ?? rid; }
                catch {  }
                return (CurrentMinimapInfoDto?)new CurrentMinimapInfoDto("redux", rid, name);
            }
            if (!string.IsNullOrWhiteSpace(state?.ReduxId)
                && !string.Equals(state!.ReduxId, "vanilla", StringComparison.OrdinalIgnoreCase))
            {
                var rid = state.ReduxId!;
                string name = rid;
                try { name = _catalog.GetByIdAsync(rid).Result?.Name ?? rid; }
                catch {  }
                return (CurrentMinimapInfoDto?)new CurrentMinimapInfoDto("redux", rid, name);
            }
            return (CurrentMinimapInfoDto?)null;
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[getCurrentMinimapInfo] FAIL: {ex.Message}");
            return (CurrentMinimapInfoDto?)null;
        }
    });

