    public Task<InjectResultDto> ReduxApplyMinimapAsync(string source, string id)
        => ReduxApplyMinimapAsync(source, id, null);

    public async Task<InjectResultDto> ReduxApplyMinimapAsync(string source, string id, string? displayName)
    {
        if (string.IsNullOrWhiteSpace(source) || string.IsNullOrWhiteSpace(id))
            return new InjectResultDto(false, "source + id required.", null);
        using var _mtx = await MiamiGraphics.Shell.Services.UpdateRpfMutex.AcquireAsync($"minimap-apply:{source}:{id}");

        var state = ReadInstallState();

        var reduxId = string.IsNullOrWhiteSpace(state?.ReduxId) ? "vanilla" : state!.ReduxId;

        var progressKey = $"minimap-swap-{source}-{id}";

        var prettyName = !string.IsNullOrWhiteSpace(displayName)
            ? $"Миникарта: {displayName.Trim()}"
            : (source == "library"
                ? $"Миникарта (library {id.Substring(0, Math.Min(id.Length, 12))})"
                : $"Миникарта (редукс {id})");

        var gtaRoot = await GetGtaPathAsync();
        if (string.IsNullOrWhiteSpace(gtaRoot))
            return new InjectResultDto(false, "GTA не найдена. Укажи путь в Admin → Settings → Paths.", null);

        var updateRpf = Path.Combine(gtaRoot, "update", "update.rpf");
        if (!File.Exists(updateRpf))
            return new InjectResultDto(false, $"Не найден {updateRpf} - переустанови редукс.", null);

        var prevDraft = state?.CustomizationDraft;
        var prevMinimap = prevDraft?.Minimap;
        string hpColor    = prevMinimap?.HpColor    ?? "#34D399";
        string armorColor = prevMinimap?.ArmorColor ?? "#60A5FA";
        string? pngOverlay = prevMinimap?.PngOverlayPath;

        Debug.WriteLine($"[minimap.swap] router: prevDraft={(prevDraft is null ? "null" : "exists")}, "
                        + $"prevReduxId={prevDraft?.ReduxId ?? "<null>"}, stateReduxId={state?.ReduxId ?? "<null>"}");

        EmitInstallProgress(progressKey, prettyName, "starting", 1, null,
            detailMessage: Loc.T("progress.minimap.changing"));

        InjectResultDto FailSwap(string msg)
        {
            EmitInstallProgress(progressKey, prettyName, "error", 0, msg);
            return new InjectResultDto(false, msg, null);
        }

        byte[] donorGfxBytes;
        string donorLabel;
        try
        {
            using var http = HttpClientFactory.CreateFragmenting(TimeSpan.FromMinutes(15));
            string donorRoot;
            if (source == "library")
            {
                EmitInstallProgress(progressKey, prettyName, "downloading", 10, null,
                    detailMessage: Loc.T("progress.minimap.downloading"));
                var root = await EnsureLibraryCachedAsync(id, "minimap", http,
                    (_, pct, msg) => EmitInstallProgress(progressKey, prettyName, "downloading", pct >= 0 ? 10 + (pct/4) : -1, null, detailMessage: msg),
                    progressBase: 0, progressSpan: 100);
                if (root is null)
                    return FailSwap("Не удалось скачать library-миникарту.");
                donorRoot = root;
                donorLabel = $"library:{id}";
            }
            else if (source == "redux")
            {
                EmitInstallProgress(progressKey, prettyName, "downloading", 10, null,
                    detailMessage: Loc.T("progress.minimap.downloading"));
                var root = await EnsureDonorCachedAsync(id, "minimap", http,
                    (_, pct, msg) => EmitInstallProgress(progressKey, prettyName, "downloading", pct >= 0 ? 10 + (pct/4) : -1, null, detailMessage: msg),
                    null,
                    progressBase: 0, progressSpan: 100);
                if (root is null)
                    return FailSwap("Не удалось скачать донора-редукса.");
                donorRoot = root;
                donorLabel = $"redux:{id}";
            }
            else
            {
                return FailSwap($"Неизвестный source='{source}' (ожидался 'library' или 'redux').");
            }

            var minimapDir = Path.Combine(donorRoot, "components", "minimap");
            var donorGfxPath = Path.Combine(minimapDir, "minimap.gfx");
            if (File.Exists(donorGfxPath))
            {
                donorGfxBytes = await File.ReadAllBytesAsync(donorGfxPath);
            }
            else
            {
                var nested = Core.Services.PatchCustomizationSupport
                    .TryFindFileBytesInDir(minimapDir, "minimap.gfx");
                if (nested is null || nested.Length == 0)
                    return FailSwap($"У донора {donorLabel} отсутствует minimap.gfx.");
                donorGfxBytes = nested;
                Debug.WriteLine($"[minimap.swap] donor minimap.gfx найден вложенным в {minimapDir}");
            }
            Debug.WriteLine($"[minimap.swap] donor minimap.gfx: {donorGfxBytes.Length} bytes from {donorLabel}");
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[minimap.swap] donor fetch FAIL: {ex.GetType().Name}: {ex.Message}");
            EmitInstallProgress(progressKey, prettyName, "error", 0, ex.Message);
            return new InjectResultDto(false, $"Ошибка получения донора: {ex.Message}", null);
        }

        byte[] finalGfxBytes = donorGfxBytes;

        EmitInstallProgress(progressKey, prettyName, "injecting", 80, null,
            detailMessage: Loc.T("progress.minimap.applying"));

        var rollbackPath = updateRpf + ".swap_rollback";
        await MakeRollbackPointAsync(updateRpf, rollbackPath, progressKey, prettyName,
            "injecting", new ProgressBand(80, 84), "minimap.swap");

        var found = await Task.Run(() =>
            Core.Services.PatchCustomizationSupport.FindInternalPathsByNameDeep(gtaRoot, "minimap.gfx"));
        var candidates = found
            .Concat(new[] { "x64/patch/data/cdimages/scaleform_minimap.rpf/minimap.gfx",
                            "x64/data/cdimages/scaleform_minimap.rpf/minimap.gfx" })
            .Distinct(StringComparer.OrdinalIgnoreCase).ToArray();
        Debug.WriteLine($"[minimap.swap] copies to replace: {string.Join(" | ", candidates)}");

        bool injected = false;
        bool checksumOk = true;
        string? injectedPath = null;
        var injectedAll = new List<string>();
        Exception? lastErr = null;
        try
        {
            await Task.Run(() =>
            {
                foreach (var path in candidates)
                {
                    try
                    {
                        checksumOk &= Core.Services.PatchCustomizationSupport.ReplaceFileInLiveArchive(
                            updateRpf, path, finalGfxBytes);
                        injected = true;
                        injectedPath ??= path;
                        injectedAll.Add(path);
                        Debug.WriteLine($"[minimap.swap] injected via path '{path}' (checksumOk={checksumOk})");
                    }
                    catch (Exception ex)
                    {
                        lastErr = ex;
                        Debug.WriteLine($"[minimap.swap] path '{path}' failed: {ex.Message}");
                    }
                }
                Debug.WriteLine($"[minimap.swap] replaced {injectedAll.Count} of {candidates.Length} copies");
            });
        }
        catch (Exception ex)
        {
            lastErr = ex;
        }

        if (injected && !checksumOk)
        {
            bool restored = false;
            try
            {
                if (File.Exists(rollbackPath)) { File.Copy(rollbackPath, updateRpf, overwrite: true); restored = true; }
            }
            catch { }
            try { if (File.Exists(rollbackPath)) File.Delete(rollbackPath); } catch { }
            var fixMsg = "Миникарта не применена: не удалось перешифровать update.rpf (ArchiveFix). " +
                         "Проверь, что антивирус не удалил файлы лаунчера, и переустанови лаунчер. " +
                         (restored
                             ? "Изменения откатились."
                             : "ВНИМАНИЕ: откат не удался - восстанови чистый update.rpf через настройки лаунчера перед игрой.");
            EmitInstallProgress(progressKey, prettyName, "error", 0, fixMsg);
            return new InjectResultDto(false, fixMsg, null);
        }

        if (!injected)
        {

            try { if (File.Exists(rollbackPath)) File.Copy(rollbackPath, updateRpf, overwrite: true); } catch { }
            try { if (File.Exists(rollbackPath)) File.Delete(rollbackPath); } catch { }
            var msg = lastErr?.Message ?? "Не нашёл путь до minimap.gfx в update.rpf.";
            EmitInstallProgress(progressKey, prettyName, "error", 0, msg);
            return new InjectResultDto(false, $"Не удалось внедрить миникарту: {msg}", null);
        }
        try { if (File.Exists(rollbackPath)) File.Delete(rollbackPath); } catch { }

        var baseKeyPath = await Task.Run(() => ResolveLiveMinimapGfxPath(gtaRoot))
                          ?? injectedPath ?? string.Empty;
        SaveMinimapTweakBase(finalGfxBytes, finalGfxBytes, baseKeyPath);

        try
        {
            var nextMinimap = new MinimapSettingDto(
                Enabled:             true,
                HpColor:             hpColor,
                ArmorColor:          armorColor,
                AspectRatio:         prevMinimap?.AspectRatio    ?? "16:9",
                Position:            prevMinimap?.Position       ?? "default",
                PngOverlayPath:      pngOverlay,
                ImportedFromReduxId: source == "redux"   ? id : null,
                DonorVersionId:      prevMinimap?.DonorVersionId,
                LibraryItemId:       source == "library" ? id : null,
                RangeRingsMeters:    prevMinimap?.RangeRingsMeters,
                Tweaks:              prevMinimap?.Tweaks);

            var nextDraft = prevDraft is not null
                ? prevDraft with { Minimap = nextMinimap }
                : new CustomizationDraftDto(

                    ReduxId:   reduxId!,
                    BaseVersionId: state?.VersionId,
                    Bloodfx:   new GenericSettingDto("default", null, null, null),
                    Crosshair: new GenericSettingDto("default", null, null, null),
                    Timecycle: new GenericSettingDto("default", null, null, null),
                    Armor:     new GenericSettingDto("default", null, null, null),
                    Arena:     new GenericSettingDto("default", null, null, null),
                    Minimap:   nextMinimap,
                    Tracers:   new TracerSettingDto("default", null, null, 255, 255, 255, null));

            var postSha = await Task.Run(() => Services.FileShaCache.ComputeSha256Cached(updateRpf));

            string? persistedReduxId = !string.IsNullOrWhiteSpace(state?.ReduxId)
                ? state!.ReduxId
                : null;
            WriteInstallState(new InstallState
            {
                ReduxId            = persistedReduxId,
                VersionId          = state?.VersionId,
                PostInstallSha256  = postSha,
                InstalledAt        = DateTime.UtcNow,
                CustomizationDraft = nextDraft,
                CurrentArmorId     = state?.CurrentArmorId,
                CurrentArmorName   = state?.CurrentArmorName,
                CurrentArmorGlbUrl = state?.CurrentArmorGlbUrl,
                CurrentArmorKind   = state?.CurrentArmorKind,
            });
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[minimap.swap] state persist FAILED (non-fatal): {ex.Message}");
        }

        EmitInstallProgress(progressKey, prettyName, "done", 100, null,
            detailMessage: Loc.T("progress.minimap.replaced"));
        return new InjectResultDto(true,
            "Миникарта подменена (с цветами/анимациями донора). Остальная кастомизация сохранена.", null);
    }

    private async Task<List<string>> ReapplyMinimapAndReticleFromDraftAsync(
        string gtaRoot, string updateRpf, CustomizationDraftDto? draft, string tag)
    {
        var notes = new List<string>();
        if (draft is null) return notes;

        using var http = HttpClientFactory.CreateFragmenting(TimeSpan.FromMinutes(15));

        try
        {
            bool skipMinimap = _deferMinimapReapplyOnce;
            if (skipMinimap)
            {
                _deferMinimapReapplyOnce = false;
                Debug.WriteLine($"[{tag}] minimap re-apply deferred to overlays prompt");
            }
            var m = skipMinimap ? null : draft.Minimap;
            bool hasDonor = m is not null
                && (!string.IsNullOrWhiteSpace(m.LibraryItemId) || !string.IsNullOrWhiteSpace(m.ImportedFromReduxId));
            var coreTweaks = MapMinimapTweaks(m?.Tweaks);
            bool wantsTweaks = m is { Tweaks: not null }
                && (Core.Services.MinimapScriptTweaksService.AnyRequested(coreTweaks)
                    || !string.IsNullOrWhiteSpace(m.Tweaks.HitPngPath)
                    || !string.IsNullOrWhiteSpace(m.Tweaks.ArrowPngPath)
                    || !string.IsNullOrWhiteSpace(m.Tweaks.GpsPngPath));
            bool wantsRings = m?.RangeRingsMeters is { Length: > 0 };

            if (hasDonor || wantsTweaks || wantsRings)
            {
                byte[]? baseGfx = null;
                if (hasDonor)
                {
                    var donorRoot = !string.IsNullOrWhiteSpace(m!.LibraryItemId)
                        ? await EnsureLibraryCachedAsync(m.LibraryItemId!, "minimap", http)
                        : await EnsureDonorCachedAsync(m.ImportedFromReduxId!, "minimap", http, null, m.DonorVersionId);
                    if (donorRoot is not null)
                    {
                        var dir = Path.Combine(donorRoot, "components", "minimap");
                        var flat = Path.Combine(dir, "minimap.gfx");
                        baseGfx = File.Exists(flat)
                            ? await File.ReadAllBytesAsync(flat)
                            : Core.Services.PatchCustomizationSupport.TryFindFileBytesInDir(dir, "minimap.gfx");
                    }
                    if (baseGfx is null)
                        notes.Add("миникарта не вернулась (донор недоступен - переустанови её вручную)");
                }
                else
                {
                    baseGfx = await TryGetCleanMinimapGfxBytesAsync();
                    if (baseGfx is null)
                        notes.Add("твики миникарты не вернулись (нет чистой базы)");
                }

                if (baseGfx is not null)
                {
                    var finalGfx = baseGfx;
                    if (wantsTweaks)
                    {
                        var toolNotes = new List<string>();
                        var (javaCandidate, ffdecJar, _) = ResolveMinimapTools();
                        var javaExe = await EnsureMinimapJavaAsync(javaCandidate, toolNotes, null);
                        if (javaExe is null || ffdecJar is null || !File.Exists(ffdecJar))
                        {
                            notes.Add("твики миникарты не вернулись (нет Java/ffdec)");
                        }
                        else
                        {
                            var built = await Task.Run(() =>
                                Core.Services.MinimapBuilderService.ApplyTweaksToGfxBytes(
                                    baseGfx, coreTweaks!, javaExe!, ffdecJar!, out _, out _, out _,
                                    hitImage:   TryDecodeImageRgba(m!.Tweaks!.HitPngPath),
                                    arrowImage: TryDecodeImageRgba(m.Tweaks.ArrowPngPath),
                                    gpsImage:   TryDecodeImageRgba(m.Tweaks.GpsPngPath)));
                            if (built is not null) finalGfx = built;
                            else notes.Add("твики миникарты не вернулись (сбой сборки)");
                        }
                    }
                    if (wantsRings)
                    {
                        var ringsTmp = Path.Combine(Path.GetTempPath(), "mmrings_" + Guid.NewGuid().ToString("N") + ".gfx");
                        try
                        {
                            await File.WriteAllBytesAsync(ringsTmp, finalGfx);
                            if (await Task.Run(() => Core.Services.MinimapRangeRingsService.Apply(ringsTmp, m!.RangeRingsMeters!)))
                                finalGfx = await File.ReadAllBytesAsync(ringsTmp);
                        }
                        catch (Exception exR) { Debug.WriteLine($"[{tag}] rings re-apply FAIL: {exR.Message}"); }
                        finally { try { File.Delete(ringsTmp); } catch { } }
                    }

                    var bytesToWrite = finalGfx;
                    var (wrote, firstPath, mmSumOk) = await Task.Run(() =>
                    {
                        var found = Core.Services.PatchCustomizationSupport
                            .FindInternalPathsByNameDeep(gtaRoot, "minimap.gfx");
                        var candidates = found
                            .Concat(new[] { "x64/patch/data/cdimages/scaleform_minimap.rpf/minimap.gfx",
                                            "x64/data/cdimages/scaleform_minimap.rpf/minimap.gfx" })
                            .Distinct(StringComparer.OrdinalIgnoreCase);
                        int n = 0; string? first = null; bool sumOk = true;
                        foreach (var p in candidates)
                        {
                            try
                            {
                                sumOk &= Core.Services.PatchCustomizationSupport.ReplaceFileInLiveArchive(updateRpf, p, bytesToWrite);
                                n++; first ??= p;
                            }
                            catch {}
                        }
                        return (n, first, sumOk);
                    });
                    if (wrote > 0)
                    {
                        var baseKeyPath = await Task.Run(() => ResolveLiveMinimapGfxPath(gtaRoot))
                                          ?? firstPath ?? string.Empty;
                        SaveMinimapTweakBase(baseGfx, finalGfx, baseKeyPath);
                        Debug.WriteLine($"[{tag}] minimap re-applied to {wrote} copies after clean restore (checksumOk={mmSumOk})");
                        if (!mmSumOk)
                            notes.Add("миникарта вернулась, но перешифровка update.rpf не удалась (ArchiveFix) - если игра не пустит, переустанови миникарту");
                    }
                    else notes.Add("миникарта не вернулась (не нашлось ни одной копии minimap.gfx)");
                }
            }
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[{tag}] minimap re-apply EXCEPTION: {ex.Message}");
            notes.Add($"миникарта не вернулась ({ex.Message})");
        }

        try
        {
            var c = draft.Crosshair;
            var kind = c?.Kind;
            bool ourReticle = !string.IsNullOrWhiteSpace(kind)
                && !kind!.Equals("default", StringComparison.OrdinalIgnoreCase)
                && !kind.Equals("clear", StringComparison.OrdinalIgnoreCase);
            if (ourReticle)
            {
                byte[]? gfx = null;
                if (kind!.Equals("custom", StringComparison.OrdinalIgnoreCase))
                {
                    if (!string.IsNullOrWhiteSpace(c!.CustomSpecJson))
                    {
                        var spec = System.Text.Json.JsonSerializer.Deserialize<ReticleSpecDto>(c.CustomSpecJson!);
                        if (spec is not null)
                        {
                            var rNotes = new List<string>();
                            gfx = await BuildCustomReticleGfxAsync(gtaRoot, spec, rNotes);
                        }
                    }
                }
                else
                {
                    var donorRoot = kind.Equals("library", StringComparison.OrdinalIgnoreCase)
                                    && !string.IsNullOrWhiteSpace(c!.LibraryItemId)
                        ? await EnsureLibraryCachedAsync(c.LibraryItemId!, "crosshair", http)
                        : !string.IsNullOrWhiteSpace(c!.DonorReduxId)
                            ? await EnsureDonorCachedAsync(c.DonorReduxId!, "crosshair", http, null, c.DonorVersionId)
                            : null;
                    if (donorRoot is not null)
                    {
                        var p = FindDonorReticleGfxPath(Path.Combine(donorRoot, "components", "crosshair"));
                        if (p is not null && File.Exists(p)) gfx = await File.ReadAllBytesAsync(p);
                    }
                }

                if (gfx is not null)
                {
                    var outcome = await Task.Run(() => InjectReticleIntoLiveArchive(updateRpf, gfx, tag + ".reticle"));
                    if (!outcome.Injected)
                        notes.Add("прицел не вернулся (hud_reticle.gfx не найден)");
                    else
                    {
                        Debug.WriteLine($"[{tag}] reticle re-applied after clean restore ({outcome.Where}, {outcome.Replaced} copies, checksumOk={outcome.ChecksumOk})");
                        if (!outcome.ChecksumOk)
                            notes.Add("прицел вернулся, но перешифровка update.rpf не удалась (ArchiveFix) - если игра не пустит, переустанови прицел");
                    }
                }
                else notes.Add("прицел не вернулся (донор/спека недоступны - поставь его вручную)");
            }
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[{tag}] reticle re-apply EXCEPTION: {ex.Message}");
            notes.Add($"прицел не вернулся ({ex.Message})");
        }

        return notes;
    }

    public async Task<InjectResultDto> TimecycleInstallAsync(string donorReduxId, string? displayName, string? donorVersionId = null)
    {
        if (string.IsNullOrWhiteSpace(donorReduxId))
            return new InjectResultDto(false, "donorReduxId required.", null);
        Guid? donorVersionGuid = Guid.TryParse(donorVersionId, out var dvg) ? dvg : null;
        using var _mtx = await MiamiGraphics.Shell.Services.UpdateRpfMutex.AcquireAsync($"timecycle-install:{donorReduxId}");

        var state = ReadInstallState();
        var reduxId = string.IsNullOrWhiteSpace(state?.ReduxId) ? "vanilla" : state!.ReduxId;
        var progressKey = $"timecycle-install-{donorReduxId}";
        var prettyName = !string.IsNullOrWhiteSpace(displayName)
            ? $"Таймцикл: {displayName.Trim()}"
            : $"Таймцикл (редукс {donorReduxId})";

        var gtaRoot = await GetGtaPathAsync();
        if (string.IsNullOrWhiteSpace(gtaRoot))
            return new InjectResultDto(false, "GTA не найдена. Укажи путь в Admin → Settings → Paths.", null);
        var updateRpf = Path.Combine(gtaRoot, "update", "update.rpf");
        if (!File.Exists(updateRpf))
            return new InjectResultDto(false, $"Не найден {updateRpf}.", null);

        var prevDraft = state?.CustomizationDraft;
        bool hasRealReduxInstalled = !string.IsNullOrWhiteSpace(state?.ReduxId)
            && !state!.ReduxId.Equals("vanilla", StringComparison.OrdinalIgnoreCase);

        bool hadPriorTimecycleSwap =
            prevDraft?.Timecycle is { } tcPrev && (tcPrev.Kind == "import" || tcPrev.Kind == "library");
        var reapplyNotes = new List<string>();
        if (!hasRealReduxInstalled && hadPriorTimecycleSwap)
        {
            try
            {
                string? cleanRpf = GetLocalCleanRpfPath();
                if (cleanRpf is null)
                {
                    var cfg = await _adminConfig.GetAsync();
                    if (!string.IsNullOrWhiteSpace(cfg.CleanUpdateRpfPath) && File.Exists(cfg.CleanUpdateRpfPath))
                        cleanRpf = cfg.CleanUpdateRpfPath;
                }
                if (cleanRpf is not null)
                {
                    EmitInstallProgress(progressKey, prettyName, "starting", 1, null,
                        detailMessage: Loc.T("progress.timecycle.preparingReplace"));
                    File.Copy(cleanRpf, updateRpf, overwrite: true);
                    Debug.WriteLine("[timecycle.install] clean update.rpf restored (vanilla + prior timecycle swap)");
                    EmitInstallProgress(progressKey, prettyName, "starting", 2, null,
                        detailMessage: Loc.T("progress.minimap.restoringMinimapAndReticle"));
                    reapplyNotes = await ReapplyMinimapAndReticleFromDraftAsync(
                        gtaRoot, updateRpf, prevDraft, "timecycle.install");
                }
            }
            catch (Exception ex)
            {
                Debug.WriteLine($"[timecycle.install] clean restore FAILED: {ex.Message} - proceeding anyway");
            }
        }

        EmitInstallProgress(progressKey, prettyName, "starting", 2, null,
            detailMessage: Loc.T("progress.timecycle.preparing"));

        string donorRoot;
        try
        {
            using var http = HttpClientFactory.CreateFragmenting(TimeSpan.FromMinutes(15));
            EmitInstallProgress(progressKey, prettyName, "downloading", 8, null,
                detailMessage: Loc.T("progress.timecycle.downloading"));
            var root = await EnsureDonorCachedAsync(donorReduxId, "timecycle", http,
                (_, pct, msg) => EmitInstallProgress(progressKey, prettyName, "downloading", pct, null, detailMessage: msg),
                donorVersionGuid,
                progressBase: 8, progressSpan: 30);
            if (root is null)
            {
                EmitInstallProgress(progressKey, prettyName, "error", 0, "Не удалось скачать донора-редукса.");
                return new InjectResultDto(false, "Не удалось скачать донора-редукса.", null);
            }
            donorRoot = root;
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[timecycle.install] donor fetch FAIL: {ex.GetType().Name}: {ex.Message}");
            EmitInstallProgress(progressKey, prettyName, "error", 0, ex.Message);
            return new InjectResultDto(false, $"Ошибка получения донора: {ex.Message}", null);
        }

        var componentRoot = Path.Combine(donorRoot, "components", "timecycle");
        if (!Directory.Exists(componentRoot))
        {
            EmitInstallProgress(progressKey, prettyName, "error", 0, "У донора отсутствует папка компонента timecycle.");
            return new InjectResultDto(false, "У донора отсутствует папка компонента timecycle.", null);
        }

        var targetPaths = new List<string>();
        try
        {
            var mapPath = Path.Combine(donorRoot, "component_map.json");
            if (File.Exists(mapPath))
            {
                var map = JsonSerializer.Deserialize<Core.Parser.ResolvedComponentMap>(
                    await File.ReadAllTextAsync(mapPath), ReduxJson);
                if (map?.Components != null
                    && map.Components.TryGetValue("timecycle", out var tcInfo)
                    && tcInfo is { IsFound: true } && tcInfo.InternalPaths is { Count: > 0 })
                {
                    targetPaths = tcInfo.InternalPaths.Distinct(StringComparer.OrdinalIgnoreCase).ToList();
                }
            }
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[timecycle.install] component_map parse FAIL: {ex.Message} - falling back to file walk");
        }
        if (targetPaths.Count == 0)
        {
            targetPaths = Directory.GetFiles(componentRoot, "*", SearchOption.AllDirectories)
                .Select(p => Path.GetRelativePath(componentRoot, p).Replace('\\', '/'))
                .ToList();
        }
        if (targetPaths.Count == 0)
        {
            EmitInstallProgress(progressKey, prettyName, "error", 0, "У донора пустой компонент timecycle.");
            return new InjectResultDto(false, "У донора пустой компонент timecycle.", null);
        }

        var donorFilesByName = Directory.GetFiles(componentRoot, "*", SearchOption.AllDirectories)
            .ToLookup(p => Path.GetFileName(p), StringComparer.OrdinalIgnoreCase);
        var donorBlocks = Core.Injector.TimecycleModsMerger.CollectDonorModifierBlocks(componentRoot);

        EmitInstallProgress(progressKey, prettyName, "injecting", 55, null,
            detailMessage: Loc.T("progress.timecycle.preparingFiles"));

        var rollbackPath = updateRpf + ".swap_rollback";
        await MakeRollbackPointAsync(updateRpf, rollbackPath, progressKey, prettyName,
            "injecting", new ProgressBand(55, 62), "timecycle.swap");

        int mergedMods = 0, skippedMods = 0, missingDonorFiles = 0;
        var replacements = new List<KeyValuePair<string, byte[]>>();
        try
        {
            await Task.Run(() =>
            {
                foreach (var targetPath in targetPaths)
                {
                    var fileName = Path.GetFileName(targetPath.Replace('/', '\\'));
                    if (string.IsNullOrWhiteSpace(fileName)) continue;

                    if (Core.Injector.TimecycleModsMerger.IsModsFile(fileName))
                    {
                        var baseBytes = Core.Services.PatchCustomizationSupport.TryExtractLiveFileBytes(updateRpf, targetPath);
                        if (baseBytes is null) { skippedMods++; continue; }
                        bool hadBom = baseBytes.Length >= 3 && baseBytes[0] == 0xEF && baseBytes[1] == 0xBB && baseBytes[2] == 0xBF;
                        var baseXml = new System.Text.UTF8Encoding(false)
                            .GetString(hadBom ? baseBytes.AsSpan(3).ToArray() : baseBytes);
                        var merged = Core.Injector.TimecycleModsMerger.MergeModsXml(
                            baseXml, donorBlocks, out var replacedCount, out var mergeErr);
                        if (merged is null)
                        {
                            Debug.WriteLine($"[timecycle.install] '{fileName}' merge skipped: {mergeErr ?? "нет одноимённых модификаторов"}");
                            skippedMods++;
                            continue;
                        }
                        var body = new System.Text.UTF8Encoding(false).GetBytes(merged);
                        var outBytes = hadBom
                            ? new byte[] { 0xEF, 0xBB, 0xBF }.Concat(body).ToArray()
                            : body;
                        replacements.Add(new KeyValuePair<string, byte[]>(targetPath, outBytes));
                        mergedMods++;
                        Debug.WriteLine($"[timecycle.install] '{fileName}' merged ({replacedCount} modifiers)");
                        continue;
                    }

                    string? donorFile = donorFilesByName[fileName].FirstOrDefault();
                    if (donorFile is null)
                    {
                        var relCandidate = Path.Combine(componentRoot, targetPath.Replace('/', '\\'));
                        if (File.Exists(relCandidate)) donorFile = relCandidate;
                    }
                    if (donorFile is null) { missingDonorFiles++; continue; }
                    replacements.Add(new KeyValuePair<string, byte[]>(targetPath, File.ReadAllBytes(donorFile)));
                }
            });
        }
        catch (Exception ex)
        {
            try { if (File.Exists(rollbackPath)) File.Delete(rollbackPath); } catch { }
            Debug.WriteLine($"[timecycle.install] prepare FAIL: {ex.GetType().Name}: {ex.Message}");
            EmitInstallProgress(progressKey, prettyName, "error", 0, ex.Message);
            return new InjectResultDto(false, $"Ошибка подготовки файлов: {ex.Message}", null);
        }

        if (replacements.Count == 0)
        {
            try { if (File.Exists(rollbackPath)) File.Delete(rollbackPath); } catch { }
            var msg = "Донор не дал ни одного применимого файла таймцикла.";
            EmitInstallProgress(progressKey, prettyName, "error", 0, msg);
            return new InjectResultDto(false, msg, null);
        }

        EmitInstallProgress(progressKey, prettyName, "injecting", 70, null,
            detailMessage: Loc.T("progress.timecycle.injecting", ("count", replacements.Count)));

        bool batchOk = false;
        int applied = 0;
        List<string> skippedPaths = new();
        Exception? injectErr = null;
        try
        {
            (batchOk, applied, skippedPaths) = await Task.Run(() =>
            {
                var ok = Core.Services.PatchCustomizationSupport.ReplaceFilesInLiveArchive(
                    updateRpf, replacements, out var appliedCount, out var skipped,
                    addMissingPlainPaths: true);
                return (ok, appliedCount, skipped);
            });
        }
        catch (Exception ex)
        {
            injectErr = ex;
        }

        if (!batchOk || injectErr is not null)
        {
            bool restored = false;
            try
            {
                if (File.Exists(rollbackPath)) { File.Copy(rollbackPath, updateRpf, overwrite: true); restored = true; }
            }
            catch { }
            try { if (File.Exists(rollbackPath)) File.Delete(rollbackPath); } catch { }
            var fixMsg = injectErr is not null
                ? $"Таймцикл не применён: {injectErr.Message}. "
                : "Таймцикл не применён: не удалось перешифровать update.rpf (ArchiveFix). " +
                  "Проверь, что антивирус не удалил файлы лаунчера, и переустанови лаунчер. ";
            fixMsg += restored
                ? "Изменения откатились."
                : "ВНИМАНИЕ: откат не удался - восстанови чистый update.rpf через настройки лаунчера перед игрой.";
            EmitInstallProgress(progressKey, prettyName, "error", 0, fixMsg);
            return new InjectResultDto(false, fixMsg, null);
        }
        try { if (File.Exists(rollbackPath)) File.Delete(rollbackPath); } catch { }
        Debug.WriteLine($"[timecycle.install] applied={applied}, mergedMods={mergedMods}, " +
                        $"skippedMods={skippedMods}, missingDonor={missingDonorFiles}, absentInLive={skippedPaths.Count}");

        try
        {
            var nextTimecycle = new GenericSettingDto(
                Kind:           "import",
                LibraryItemId:  null,
                DonorReduxId:   donorReduxId,
                DonorVersionId: donorVersionGuid);
            var nextDraft = prevDraft is not null
                ? prevDraft with { Timecycle = nextTimecycle }
                : BuildDefaultDraft(reduxId!, state?.VersionId) with { Timecycle = nextTimecycle };

            var postSha = await Task.Run(() => Services.FileShaCache.ComputeSha256Cached(updateRpf));
            WriteInstallState(new InstallState
            {
                ReduxId            = !string.IsNullOrWhiteSpace(state?.ReduxId) ? state!.ReduxId : null,
                VersionId          = state?.VersionId,
                PostInstallSha256  = postSha,
                InstalledAt        = DateTime.UtcNow,
                CustomizationDraft = nextDraft,
                CurrentArmorId     = state?.CurrentArmorId,
                CurrentArmorName   = state?.CurrentArmorName,
                CurrentArmorGlbUrl = state?.CurrentArmorGlbUrl,
                CurrentArmorKind   = state?.CurrentArmorKind,
            });
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[timecycle.install] state persist FAILED (non-fatal): {ex.Message}");
        }

        EmitInstallProgress(progressKey, prettyName, "done", 100, null,
            detailMessage: Loc.T("progress.timecycle.installed"));
        var tcOkMsg = $"Таймцикл применён ({applied} файлов, merge таблицы модификаторов: {mergedMods}). Остальные моды не тронуты.";
        if (reapplyNotes.Count > 0)
            tcOkMsg += " Заметки: " + string.Join("; ", reapplyNotes) + ".";
        return new InjectResultDto(true, tcOkMsg, null);
    }

    public Task<CurrentMinimapInfoDto?> GetCurrentTimecycleInfoAsync() => Task.Run(() =>
    {
        try
        {
            var tc = ReadInstallState()?.CustomizationDraft?.Timecycle;
            if (tc is null || tc.Kind == "default") return (CurrentMinimapInfoDto?)null;
            if (tc.Kind == "library" && !string.IsNullOrWhiteSpace(tc.LibraryItemId))
            {
                var libId = tc.LibraryItemId!;
                string name = "";
                try
                {
                    var rows = _supabase.SelectAsync<LibraryRow>(
                        "library_components",
                        $"select=id,name,type&id=eq.{Uri.EscapeDataString(libId)}").Result;
                    name = rows.FirstOrDefault()?.Name ?? "";
                }
                catch { }
                return (CurrentMinimapInfoDto?)new CurrentMinimapInfoDto("library", libId, name);
            }
            if (tc.Kind == "import" && !string.IsNullOrWhiteSpace(tc.DonorReduxId))
            {
                var rid = tc.DonorReduxId!;
                string name = rid;
                try { name = _catalog.GetByIdAsync(rid).Result?.Name ?? rid; }
                catch { }
                if (tc.DonorVersionId is { } vid)
                {
                    try
                    {
                        var versions = _versionsRepo.ListByReduxAsync(rid).Result;
                        var label = versions?.FirstOrDefault(v => v.Id == vid)?.Label;
                        if (!string.IsNullOrWhiteSpace(label) && (versions?.Count ?? 0) > 1)
                            name = $"{name} · {label}";
                    }
                    catch { }
                }
                return (CurrentMinimapInfoDto?)new CurrentMinimapInfoDto("redux", rid, name);
            }
            return (CurrentMinimapInfoDto?)null;
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[getCurrentTimecycleInfo] FAIL: {ex.Message}");
            return (CurrentMinimapInfoDto?)null;
        }
    });

    public async Task<InjectResultDto> TimecycleRestoreVanillaAsync()
    {
        using var _mtx = await MiamiGraphics.Shell.Services.UpdateRpfMutex.AcquireAsync("timecycle-restore-vanilla");
        const string progressKey = "timecycle-restore-vanilla";
        const string pretty = "Возврат ванильного таймцикла";
        EmitInstallProgress(progressKey, pretty, "starting", 5, null, detailMessage: Loc.T("progress.timecycle.restoring"));

        var gtaRoot = await GetGtaPathAsync();
        if (string.IsNullOrWhiteSpace(gtaRoot))
        {
            EmitInstallProgress(progressKey, pretty, "error", 0, "GTA не найдена.");
            return new InjectResultDto(false, "GTA не найдена. Укажи путь в Настройках → Папка GTA.", null);
        }
        var updateRpf = Path.Combine(gtaRoot, "update", "update.rpf");
        if (!File.Exists(updateRpf))
        {
            EmitInstallProgress(progressKey, pretty, "error", 0, "update.rpf не найден.");
            return new InjectResultDto(false, $"Не найден {updateRpf}.", null);
        }
        var cleanRpf = _backupService.GetCleanUpdateRpfPath();
        if (string.IsNullOrWhiteSpace(cleanRpf))
        {
            EmitInstallProgress(progressKey, pretty, "error", 0, "Нет чистой копии update.rpf.");
            return new InjectResultDto(false, "Нет чистой копии update.rpf. Сделай Backup, чтобы вернуть ванильный таймцикл.", null);
        }

        static bool IsTimecyclePath(string p)
        {
            var n = p.Replace('\\', '/').ToLowerInvariant();
            return n.StartsWith("common/data/timecycle/")
                || n == "common/data/visualsettings.dat"
                || n == "common/data/cloudkeyframes.xml"
                || n == "common/data/clouds.xml"
                || n.StartsWith("common/data/levels/gta5/weather/");
        }

        try
        {
            EmitInstallProgress(progressKey, pretty, "injecting", 40, null,
                detailMessage: Loc.T("progress.timecycle.restoringLong"));
            var result = await Task.Run(() =>
            {
                var livePaths = Core.Services.PatchCustomizationSupport
                    .EnumerateInternalPaths(gtaRoot, _ => true)
                    .Where(IsTimecyclePath)
                    .Distinct(StringComparer.OrdinalIgnoreCase)
                    .ToList();
                if (livePaths.Count == 0) return (ok: false, applied: 0, msg: "В update.rpf не найдено файлов таймцикла.");

                var commonRpf = Path.Combine(gtaRoot, "common.rpf");
                var replacements = new List<KeyValuePair<string, byte[]>>();
                foreach (var p in livePaths)
                {
                    var bytes = Core.Services.PatchCustomizationSupport.GetBytesFromArchiveExactPath(cleanRpf!, p);
                    if (bytes is null && File.Exists(commonRpf))
                    {
                        var commonPath = p.StartsWith("common/", StringComparison.OrdinalIgnoreCase) ? p.Substring("common/".Length) : p;
                        bytes = Core.Services.PatchCustomizationSupport.GetBytesFromArchiveExactPath(commonRpf, commonPath);
                    }
                    if (bytes is null)
                    {
                        Debug.WriteLine($"[timecycle.restore] no clean source for '{p}' - skipped");
                        continue;
                    }
                    replacements.Add(new KeyValuePair<string, byte[]>(p, bytes));
                }
                if (replacements.Count == 0) return (ok: false, applied: 0, msg: "Не нашёл ванильные файлы таймцикла в чистой копии.");
                var ok = Core.Services.PatchCustomizationSupport.ReplaceFilesInLiveArchive(
                    updateRpf, replacements, out var appliedCount, out _);
                return (ok, applied: appliedCount, msg: ok ? "" : "Не удалось перешифровать update.rpf (ArchiveFix).");
            });
            if (!result.ok)
            {
                EmitInstallProgress(progressKey, pretty, "error", 0, result.msg);
                return new InjectResultDto(false, result.msg, null);
            }

            try
            {
                var state = ReadInstallState();
                var prevDraft = state?.CustomizationDraft;
                if (prevDraft is not null)
                {
                    var nextDraft = prevDraft with { Timecycle = new GenericSettingDto("default", null, null, null) };
                    var postSha = await Task.Run(() => Services.FileShaCache.ComputeSha256Cached(updateRpf));
                    WriteInstallState(new InstallState
                    {
                        ReduxId = state?.ReduxId,
                        VersionId = state?.VersionId,
                        PostInstallSha256 = postSha,
                        InstalledAt = DateTime.UtcNow,
                        CustomizationDraft = nextDraft,
                        CurrentArmorId = state?.CurrentArmorId,
                        CurrentArmorName = state?.CurrentArmorName,
                        CurrentArmorGlbUrl = state?.CurrentArmorGlbUrl,
                        CurrentArmorKind = state?.CurrentArmorKind,
                    });
                }
            }
            catch (Exception ex) { Debug.WriteLine($"[timecycle.restore] state persist failed (non-fatal): {ex.Message}"); }

            EmitInstallProgress(progressKey, pretty, "done", 100, null, detailMessage: Loc.T("progress.timecycle.vanillaRestored"));
            return new InjectResultDto(true, null, null);
        }
        catch (Exception ex)
        {
            EmitInstallProgress(progressKey, pretty, "error", 0, ex.Message);
            return new InjectResultDto(false, $"Ошибка: {ex.Message}", null);
        }
    }

    private static readonly Dictionary<string, string> EnvironmentAssetSha =
        new(StringComparer.OrdinalIgnoreCase)
        {
        };

    private static string EnvAssetSha(string r2Key)
        => EnvironmentAssetSha.TryGetValue(r2Key, out var sha) ? sha : string.Empty;

