    private sealed class TreesState
    {
        public string TreeId { get; set; } = string.Empty;
        public string TreeName { get; set; } = string.Empty;
        public string? OriginalBackupPath { get; set; }
        public bool? HadOriginal { get; set; }
        public DateTime InstalledAt { get; set; }
    }

    private static readonly JsonSerializerOptions TreesJson = new()
    {
        WriteIndented = true,
        PropertyNameCaseInsensitive = true,
    };

    private static TreesState? ReadTreesState()
    {
        try
        {
            var p = GetTreesStatePath();
            if (!File.Exists(p)) return null;
            return JsonSerializer.Deserialize<TreesState>(File.ReadAllText(p), TreesJson);
        }
        catch { return null; }
    }

    private static void WriteTreesState(TreesState? state)
    {
        try
        {
            var p = GetTreesStatePath();
            if (state is null) { if (File.Exists(p)) File.Delete(p); return; }
            var tmp = p + ".tmp";
            File.WriteAllText(tmp, JsonSerializer.Serialize(state, TreesJson));
            File.Move(tmp, p, overwrite: true);
        }
        catch (Exception ex) { Debug.WriteLine($"[trees] state persist FAILED (non-fatal): {ex.Message}"); }
    }

    private static string GetTreesBackupPath()
    {
        var dir = Core.System.AppDataRoot.BackupDir("trees");
        return Path.Combine(dir, "mpxmas_604490_original.rpf");
    }

    public async Task<InjectResultDto> TreesInstallAsync(string treeId, string? displayName)
    {
        if (string.IsNullOrWhiteSpace(treeId))
            return new InjectResultDto(false, "treeId required.", null);

        var pack = TreePacks.FirstOrDefault(t => t.Id.Equals(treeId, StringComparison.OrdinalIgnoreCase));
        if (pack.Id is null)
            return new InjectResultDto(false, $"Неизвестный пак деревьев: {treeId}.", null);

        using var _mtx = await MiamiGraphics.Shell.Services.UpdateRpfMutex.AcquireAsync("trees-install");

        var progressKey = "trees-install";
        var prettyName = !string.IsNullOrWhiteSpace(displayName)
            ? $"Деревья: {displayName!.Trim()}"
            : $"Деревья: {pack.Name}";

        var gtaRoot = await GetGtaPathAsync();
        if (string.IsNullOrWhiteSpace(gtaRoot))
        {
            EmitInstallProgress(progressKey, prettyName, "error", 0, "GTA не найдена.");
            return new InjectResultDto(false, "GTA не найдена. Укажи путь в Настройках → Папка GTA.", null);
        }

        var target = Path.Combine(gtaRoot, TreesDlcRelPath);
        var targetDir = Path.GetDirectoryName(target)!;

        if (File.Exists(target))
        {
            try
            {
                using var probe = new FileStream(target, FileMode.Open, FileAccess.ReadWrite, FileShare.None);
            }
            catch (IOException)
            {
                var lockers = Core.System.FileLockDetector.WhoIsLocking(target);
                var who = lockers.Count == 0
                    ? "GTA 5 / Rockstar Launcher / антивирус"
                    : string.Join(", ", lockers.Select(l => l.ProcessName));
                var msg = $"Файл деревьев занят ({who}). Закрой GTA 5 и попробуй ещё раз.";
                EmitInstallProgress(progressKey, prettyName, "error", 0, msg);
                return new InjectResultDto(false, msg, null);
            }
        }

        EmitInstallProgress(progressKey, prettyName, "starting", 3, null, detailMessage: Loc.T("progress.trees.preparing"));

        var prevState = ReadTreesState();
        var backupPath = GetTreesBackupPath();
        string? originalBackup = File.Exists(backupPath) ? backupPath : prevState?.OriginalBackupPath;
        bool? hadOriginal = prevState?.HadOriginal ?? (prevState is null ? File.Exists(target) : null);
        if (prevState is null && File.Exists(target) && !File.Exists(backupPath))
        {
            try
            {
                EmitInstallProgress(progressKey, prettyName, "starting", 6, null, detailMessage: Loc.T("progress.common.savingOriginal"));
                await Core.System.BackupService.CopyLargeFileAsync(target, backupPath, null, CancellationToken.None);
                originalBackup = backupPath;
                Debug.WriteLine($"[trees.install] backed up original dlc.rpf ({new FileInfo(backupPath).Length / (1024 * 1024)} MB)");
            }
            catch (Exception ex)
            {
                Debug.WriteLine($"[trees.install] original backup FAILED (non-fatal): {ex.Message}");
                originalBackup = null;
            }
        }
        else if (prevState is not null && File.Exists(backupPath))
        {
            originalBackup = backupPath;
        }

        Directory.CreateDirectory(targetDir);
        var tmpDownload = target + ".treedl";
        try { if (File.Exists(tmpDownload)) File.Delete(tmpDownload); } catch { }

        var url = $"https://miamigraphicsstorage.uk/{pack.R2Key}";
        try
        {
            EmitInstallProgress(progressKey, prettyName, "downloading", 8, null, detailMessage: Loc.T("progress.trees.downloading"));
            await Services.VerifiedDownload.FetchAsync(url, tmpDownload,
                EnvAssetSha(pack.R2Key), $"деревья {pack.Name}",
                bytesProgress: (received, total) =>
                {
                    if (total > 0)
                    {
                        var pct = (int)Math.Clamp(8 + received * 82L / total, 8, 90);
                        var msg = $"Загружаю деревья - {received / 1024 / 1024} / {total / 1024 / 1024} МБ";
                        EmitInstallProgress(progressKey, prettyName, "downloading", pct, null, detailMessage: msg);
                    }
                },
                hashProgress: (done, total) => EmitInstallProgress(progressKey, prettyName, "downloading", 91, null,
                    detailMessage: Loc.T("progress.common.verifyingMb",
                        ("done", done / 1024 / 1024), ("total", Math.Max(1, total / 1024 / 1024)))),
                referenceRequired: false);
        }
        catch (Exception ex)
        {
            try { if (File.Exists(tmpDownload)) File.Delete(tmpDownload); } catch { }
            Debug.WriteLine($"[trees.install] download FAIL: {ex.GetType().Name}: {ex.Message}");
            EmitInstallProgress(progressKey, prettyName, "error", 0, ex.Message);
            return new InjectResultDto(false, $"Не удалось скачать деревья: {ex.Message}", null);
        }

        if (!File.Exists(tmpDownload) || new FileInfo(tmpDownload).Length < 1024 * 1024)
        {
            try { if (File.Exists(tmpDownload)) File.Delete(tmpDownload); } catch { }
            var msg = "Скачанный файл деревьев пуст или повреждён.";
            EmitInstallProgress(progressKey, prettyName, "error", 0, msg);
            return new InjectResultDto(false, msg, null);
        }

        try
        {
            EmitInstallProgress(progressKey, prettyName, "injecting", 92, null,
                detailMessage: Loc.T("progress.common.checkingArchiveEncryption"));
            bool ngOk = await Task.Run(() =>
                Core.Services.PatchCustomizationSupport.NormalizeArchiveEncryptionToNG(tmpDownload));
            if (!ngOk)
            {
                try { if (File.Exists(tmpDownload)) File.Delete(tmpDownload); } catch { }
                var m = "Не удалось перешифровать архив деревьев в NG (ERR_GEN_INVALID-защита). " +
                        "Проверь, что антивирус не удалил ArchiveFix/ключи, и переустанови лаунчер.";
                EmitInstallProgress(progressKey, prettyName, "error", 0, m);
                return new InjectResultDto(false, m, null);
            }
        }
        catch (Exception ex)
        {
            try { if (File.Exists(tmpDownload)) File.Delete(tmpDownload); } catch { }
            var msg = $"Не удалось подготовить архив деревьев (перешифровка): {ex.Message}";
            Debug.WriteLine($"[trees.install] NG-normalize FAIL: {ex.Message}");
            EmitInstallProgress(progressKey, prettyName, "error", 0, msg);
            return new InjectResultDto(false, msg, null);
        }

        try
        {
            EmitInstallProgress(progressKey, prettyName, "injecting", 94, null, detailMessage: Loc.T("progress.trees.applying"));
            File.Move(tmpDownload, target, overwrite: true);
        }
        catch (Exception ex)
        {
            try { if (File.Exists(tmpDownload)) File.Delete(tmpDownload); } catch { }
            Debug.WriteLine($"[trees.install] move FAIL: {ex.Message}");
            EmitInstallProgress(progressKey, prettyName, "error", 0, ex.Message);
            return new InjectResultDto(false, $"Не удалось заменить файл деревьев: {ex.Message}", null);
        }

        WriteTreesState(new TreesState
        {
            TreeId = pack.Id,
            TreeName = pack.Name,
            OriginalBackupPath = originalBackup,
            HadOriginal = hadOriginal,
            InstalledAt = DateTime.UtcNow,
        });

        EmitInstallProgress(progressKey, prettyName, "done", 100, null, detailMessage: Loc.T("progress.trees.installed"));
        return new InjectResultDto(true, $"Деревья «{pack.Name}» установлены.", null);
    }

    public Task<CurrentMinimapInfoDto?> GetCurrentTreesInfoAsync() => Task.Run(() =>
    {
        try
        {
            var st = ReadTreesState();
            if (st is null || string.IsNullOrWhiteSpace(st.TreeId)) return (CurrentMinimapInfoDto?)null;
            return (CurrentMinimapInfoDto?)new CurrentMinimapInfoDto("trees", st.TreeId, st.TreeName);
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[getCurrentTreesInfo] FAIL: {ex.Message}");
            return (CurrentMinimapInfoDto?)null;
        }
    });

    public async Task<InjectResultDto> TreesRestoreAsync()
    {
        using var _mtx = await MiamiGraphics.Shell.Services.UpdateRpfMutex.AcquireAsync("trees-restore");
        const string progressKey = "trees-restore";
        const string pretty = "Возврат стоковых деревьев";

        var st = ReadTreesState();
        if (st is null || string.IsNullOrWhiteSpace(st.TreeId))
        {
            EmitInstallProgress(progressKey, pretty, "done", 100, null, detailMessage: Loc.T("progress.trees.alreadyStock"));
            return new InjectResultDto(true, "Деревья не были изменены.", null);
        }

        EmitInstallProgress(progressKey, pretty, "starting", 5, null, detailMessage: Loc.T("progress.trees.restoring"));

        var gtaRoot = await GetGtaPathAsync();
        if (string.IsNullOrWhiteSpace(gtaRoot))
        {
            EmitInstallProgress(progressKey, pretty, "error", 0, "GTA не найдена.");
            return new InjectResultDto(false, "GTA не найдена. Укажи путь в Настройках → Папка GTA.", null);
        }

        var target = Path.Combine(gtaRoot, TreesDlcRelPath);

        if (File.Exists(target))
        {
            try
            {
                using var probe = new FileStream(target, FileMode.Open, FileAccess.ReadWrite, FileShare.None);
            }
            catch (IOException)
            {
                var lockers = Core.System.FileLockDetector.WhoIsLocking(target);
                var who = lockers.Count == 0 ? "GTA 5 / Rockstar Launcher / антивирус"
                    : string.Join(", ", lockers.Select(l => l.ProcessName));
                var msg = $"Файл деревьев занят ({who}). Закрой GTA 5 и попробуй ещё раз.";
                EmitInstallProgress(progressKey, pretty, "error", 0, msg);
                return new InjectResultDto(false, msg, null);
            }
        }

        try
        {
            var backup = !string.IsNullOrWhiteSpace(st.OriginalBackupPath) && File.Exists(st.OriginalBackupPath)
                ? st.OriginalBackupPath
                : (File.Exists(GetTreesBackupPath()) ? GetTreesBackupPath() : null);

            if (backup is not null)
            {
                EmitInstallProgress(progressKey, pretty, "injecting", 40, null, detailMessage: Loc.T("progress.common.restoringOriginal"));
                await Core.System.BackupService.CopyLargeFileAsync(backup, target,
                    p => EmitInstallProgress(progressKey, pretty, "injecting", 40 + p / 2, null,
                        detailMessage: Loc.T("progress.common.restoringOriginal")), CancellationToken.None);
            }
            else if (st.HadOriginal == false)
            {
                EmitInstallProgress(progressKey, pretty, "injecting", 50, null, detailMessage: Loc.T("progress.trees.removingPack"));
                try { if (File.Exists(target)) File.Delete(target); } catch { }
            }
            else
            {
                var msg = Loc.T("error.treesNoBackupRestore",
                    ("file", "mpxmas_604490"));
                EmitInstallProgress(progressKey, pretty, "error", 0, msg);
                return new InjectResultDto(false, msg, null);
            }
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[trees.restore] FAIL: {ex.Message}");
            EmitInstallProgress(progressKey, pretty, "error", 0, ex.Message);
            return new InjectResultDto(false, $"Ошибка отката деревьев: {ex.Message}", null);
        }

        WriteTreesState(null);
        EmitInstallProgress(progressKey, pretty, "done", 100, null, detailMessage: Loc.T("progress.trees.stockRestored"));
        return new InjectResultDto(true, null, null);
    }

