            var msg = $"Не удалось подготовить архив дорог (перешифровка): {ex.Message}";
            Debug.WriteLine($"[roads.install] NG-normalize FAIL: {ex.Message}");
            EmitInstallProgress(progressKey, prettyName, "error", 0, msg);
            return new InjectResultDto(false, msg, null);
        }

        try
        {
            EmitInstallProgress(progressKey, prettyName, "injecting", 94, null, detailMessage: Loc.T("progress.roads.applying"));
            File.Move(tmpDownload, target, overwrite: true);
        }
        catch (Exception ex)
        {
            try { if (File.Exists(tmpDownload)) File.Delete(tmpDownload); } catch { }
            Debug.WriteLine($"[roads.install] move FAIL: {ex.Message}");
            EmitInstallProgress(progressKey, prettyName, "error", 0, ex.Message);
            return new InjectResultDto(false, $"Не удалось заменить файл дорог: {ex.Message}", null);
        }

        WriteRoadsState(new RoadsState
        {
            RoadId = pack.Id,
            RoadName = pack.Name,
            OriginalBackupPath = originalBackup,
            HadOriginal = hadOriginal,
            InstalledAt = DateTime.UtcNow,
        });

        EmitInstallProgress(progressKey, prettyName, "done", 100, null, detailMessage: Loc.T("progress.roads.installed"));
        return new InjectResultDto(true, $"Дороги «{pack.Name}» установлены.", null);
    }

