    private const string GfxWaterYtd       = @"x64/textures/water.ytd";
    private const string GfxGraphicsYtd    = @"x64/textures/graphics.ytd";
    private const string GfxVisualSettings = @"common/data/visualsettings.dat";
    private static readonly string[] LedGraphicsTextures =
        { "corona", "flare_animorphic", "torch", "vehiclelight_siren", "vehiclelight_sirenlight" };
    private const string WaterStockArchive = "x64a.rpf";
    private const string WaterStockPath    = "textures/water.ytd";
    private static string R2Water(string variant, string file) => $"environment/misc/water/{variant}/{file}";
    private const string R2LedVisual   = "environment/misc/led_spotlight/visualsettings.dat";
    private const string R2LedGraphics = "environment/misc/led_spotlight/graphics.ytd";

    private static readonly JsonSerializerOptions GraphicsJson = new() { WriteIndented = true, PropertyNameCaseInsensitive = true };

    private sealed class GraphicsModEntry
    {
        public string VariantId { get; set; } = string.Empty;
        public string[] Targets { get; set; } = Array.Empty<string>();
        public DateTime InstalledAt { get; set; }
    }
    private sealed class GraphicsModStateFile
    {
        public Dictionary<string, GraphicsModEntry> Mods { get; set; } = new(StringComparer.OrdinalIgnoreCase);
    }

    private static string GetGraphicsStatePath()
    {
        var dir = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "MiamiGraphics");
        Directory.CreateDirectory(dir);
        return Path.Combine(dir, "graphics_mods_state.json");
    }
    private static string FlattenTarget(string target) => target.Replace('/', '_').Replace('\\', '_');

    private static string GetGfxStockDir()
        => Core.System.AppDataRoot.BackupDir("graphicsmods", "__stock");
    private static void CaptureGfxStock(string updateRpf, string target)
    {
        var bp = Path.Combine(GetGfxStockDir(), FlattenTarget(target));
        if (File.Exists(bp) || File.Exists(bp + ".absent")) return;
        var cur = Core.Services.PatchCustomizationSupport.TryExtractLiveFileBytes(updateRpf, target);
        if (cur != null) File.WriteAllBytes(bp, cur);
        else File.WriteAllText(bp + ".absent", "");
    }
    private static byte[]? GfxStockBytes(string target, string gtaRoot)
    {
        var bp = Path.Combine(GetGfxStockDir(), FlattenTarget(target));
        if (File.Exists(bp)) return File.ReadAllBytes(bp);
        if (File.Exists(bp + ".absent") && target == GfxWaterYtd)
        {
            var s = Path.Combine(gtaRoot, WaterStockArchive);
            return File.Exists(s) ? Core.Services.PatchCustomizationSupport.TryExtractLiveFileBytes(s, WaterStockPath) : null;
        }
        return null;
    }

    private async Task<byte[]> GfxDownloadAsync(string r2Key, Action<long, long>? bytesProgress = null)
    {
        var url = $"https://miamigraphicsstorage.uk/{r2Key}";
        var tmp = Path.Combine(Path.GetTempPath(), $"mg_gfx_{Guid.NewGuid():N}.bin");
        try
        {
            await Services.VerifiedDownload.FetchAsync(url, tmp, EnvAssetSha(r2Key), r2Key,
                bytesProgress: bytesProgress, referenceRequired: false);
            var b = await File.ReadAllBytesAsync(tmp);
            if (b.Length == 0) throw new Exception(Loc.T("errors.gfx.emptyFile", ("key", r2Key)));
            return b;
        }
        finally { try { if (File.Exists(tmp)) File.Delete(tmp); } catch { } }
    }

    private static string DownloadCounterText(long received, long total)
        => total >= 1024 * 1024
            ? Loc.T("progress.common.downloadMb",
                ("done", received / 1024 / 1024), ("total", total / 1024 / 1024))
            : Loc.T("progress.common.downloadKb",
                ("done", received / 1024), ("total", Math.Max(1, total / 1024)));

    private static GraphicsModStateFile CloneGraphicsState(GraphicsModStateFile s)
    {
        var n = new GraphicsModStateFile();
        foreach (var kv in s.Mods)
            n.Mods[kv.Key] = new GraphicsModEntry { VariantId = kv.Value.VariantId, InstalledAt = kv.Value.InstalledAt };
        return n;
    }

    private async Task<InjectResultDto> ApplyGraphicsStateAsync(GraphicsModStateFile state, string progressKey, string pretty)
    {
        var gtaRoot = await GetGtaPathAsync();
        if (string.IsNullOrWhiteSpace(gtaRoot))
        {
            EmitInstallProgress(progressKey, pretty, "error", 0, "GTA не найдена.");
            return new InjectResultDto(false, "GTA не найдена. Укажи путь в Настройках → Папка GTA.", null);
        }
        var updateRpf = Path.Combine(gtaRoot, "update", "update.rpf");
        if (!File.Exists(updateRpf))
            return new InjectResultDto(false, $"Не найден {updateRpf}.", null);

        bool water = state.Mods.TryGetValue("water", out var w);
        bool led = state.Mods.ContainsKey("led_spotlight");
        var waterVariant = (water ? w!.VariantId : null);
        if (string.IsNullOrWhiteSpace(waterVariant)) waterVariant = "4k";

        CaptureGfxStock(updateRpf, GfxWaterYtd);
        CaptureGfxStock(updateRpf, GfxGraphicsYtd);
        CaptureGfxStock(updateRpf, GfxVisualSettings);

        var repl = new List<KeyValuePair<string, byte[]>>();
        try
        {
            Action<long, long> gfxFeed(int b, int span) => (received, total) =>
            {
                if (total > 0)
                    EmitInstallProgress(progressKey, pretty, "downloading",
                        b + (int)Math.Min(span, received * span / total), null,
                        detailMessage: DownloadCounterText(received, total));
            };

            if (water)
            {
                EmitInstallProgress(progressKey, pretty, "downloading", 15, null, detailMessage: Loc.T("progress.graphics.downloadingWater"));
                repl.Add(new(GfxWaterYtd, await GfxDownloadAsync(R2Water(waterVariant!, "water.ytd"), gfxFeed(15, 15))));
            }
            else { var s = GfxStockBytes(GfxWaterYtd, gtaRoot); if (s != null) repl.Add(new(GfxWaterYtd, s)); }

            if (led)
            {
                EmitInstallProgress(progressKey, pretty, "downloading", 35, null, detailMessage: Loc.T("progress.graphics.downloadingVisualSettings"));
                repl.Add(new(GfxVisualSettings, await GfxDownloadAsync(R2LedVisual, gfxFeed(35, 10))));
            }
            else { var s = GfxStockBytes(GfxVisualSettings, gtaRoot); if (s != null) repl.Add(new(GfxVisualSettings, s)); }

            if (water && led)
            {
                EmitInstallProgress(progressKey, pretty, "injecting", 50, null, detailMessage: Loc.T("progress.graphics.mergingGraphicsYtd"));
                var wg = await GfxDownloadAsync(R2Water(waterVariant!, "graphics.ytd"), gfxFeed(50, 10));
                var lg = await GfxDownloadAsync(R2LedGraphics, gfxFeed(60, 10));
                var merge = await Task.Run(() => Core.Services.GraphicsYtdMerger.Overlay(wg, lg, LedGraphicsTextures));
                if (!merge.Success) throw new Exception(Loc.T("errors.gfx.ytdMergeFailed", ("error", merge.Error)));
                Debug.WriteLine($"[graphics] merged graphics.ytd applied=[{string.Join(",", merge.Applied)}] missing=[{string.Join(",", merge.Missing)}]");
                repl.Add(new(GfxGraphicsYtd, merge.Bytes!));
            }
            else if (water) repl.Add(new(GfxGraphicsYtd, await GfxDownloadAsync(R2Water(waterVariant!, "graphics.ytd"), gfxFeed(30, 20))));
            else if (led) repl.Add(new(GfxGraphicsYtd, await GfxDownloadAsync(R2LedGraphics, gfxFeed(45, 20))));
            else { var s = GfxStockBytes(GfxGraphicsYtd, gtaRoot); if (s != null) repl.Add(new(GfxGraphicsYtd, s)); }
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[graphics.apply] prepare FAIL: {ex.Message}");
            EmitInstallProgress(progressKey, pretty, "error", 0, ex.Message);
            return new InjectResultDto(false, $"Не удалось подготовить файлы: {ex.Message}", null);
        }

        if (repl.Count == 0)
            return new InjectResultDto(true, null, null);

        EmitInstallProgress(progressKey, pretty, "injecting", 75, null,
            detailMessage: Loc.T("progress.graphics.injecting"));
        var rollbackPath = updateRpf + ".gfx_rollback";
        await MakeRollbackPointAsync(updateRpf, rollbackPath, progressKey, pretty,
            "injecting", new ProgressBand(75, 80), "graphics.apply");

        bool ok = false; Exception? err = null;
        try
        {
            ok = await Task.Run(() =>
                Core.Services.PatchCustomizationSupport.ReplaceFilesInLiveArchive(
                    updateRpf, repl, out _, out _, addMissingPlainPaths: true));
        }
        catch (Exception ex) { err = ex; }

        if (!ok || err != null)
        {
            bool restored = false;
            try { if (File.Exists(rollbackPath)) { File.Copy(rollbackPath, updateRpf, overwrite: true); restored = true; } } catch { }
            try { if (File.Exists(rollbackPath)) File.Delete(rollbackPath); } catch { }
            var msg = (err != null ? $"Ошибка: {err.Message}. " : "Не удалось перешифровать update.rpf. ")
                    + (restored ? "Откат выполнен." : "ВНИМАНИЕ: откат не удался - восстанови чистый update.rpf.");
            EmitInstallProgress(progressKey, pretty, "error", 0, msg);
            return new InjectResultDto(false, msg, null);
        }
        try { if (File.Exists(rollbackPath)) File.Delete(rollbackPath); } catch { }
        return new InjectResultDto(true, null, null);
    }
    private static GraphicsModStateFile ReadGraphicsState()
    {
        try
        {
            var p = GetGraphicsStatePath();
            if (!File.Exists(p)) return new GraphicsModStateFile();
            return JsonSerializer.Deserialize<GraphicsModStateFile>(File.ReadAllText(p), GraphicsJson) ?? new GraphicsModStateFile();
        }
        catch { return new GraphicsModStateFile(); }
    }
    private static void WriteGraphicsState(GraphicsModStateFile state)
    {
        try
        {
            var p = GetGraphicsStatePath();
            var tmp = p + ".tmp";
            File.WriteAllText(tmp, JsonSerializer.Serialize(state, GraphicsJson));
            File.Move(tmp, p, overwrite: true);
        }
        catch (Exception ex) { Debug.WriteLine($"[graphics] state persist FAILED: {ex.Message}"); }
    }

    public async Task<InjectResultDto> GraphicsModRestoreAsync(string modId)
    {
        var mod = GraphicsMods.FirstOrDefault(m => m.Id.Equals(modId, StringComparison.OrdinalIgnoreCase));
        using var _mtx = await MiamiGraphics.Shell.Services.UpdateRpfMutex.AcquireAsync($"graphics-restore:{modId}");
        var progressKey = $"graphics-restore-{modId}";
        var pretty = mod?.Name ?? modId;

        var state = ReadGraphicsState();
        if (!state.Mods.ContainsKey(modId))
        {
            EmitInstallProgress(progressKey, pretty, "done", 100, null, detailMessage: Loc.T("progress.graphics.modNotInstalled"));
            return new InjectResultDto(true, "Мод не был установлен.", null);
        }

        EmitInstallProgress(progressKey, pretty, "starting", 5, null, detailMessage: Loc.T("progress.graphics.removingMod"));
        var next = CloneGraphicsState(state);
        next.Mods.Remove(modId);

        var res = await ApplyGraphicsStateAsync(next, progressKey, pretty);
        if (!res.Success) return res;

        WriteGraphicsState(next);
        EmitInstallProgress(progressKey, pretty, "done", 100, null, detailMessage: Loc.T("progress.graphics.modRemoved"));
        return new InjectResultDto(true, null, null);
    }

    public Task<GraphicsModInfoDto[]> GetInstalledGraphicsModsAsync() => Task.Run(() =>
    {
        try
        {
            var state = ReadGraphicsState();
            return state.Mods.Select(kv =>
            {
                var def = GraphicsMods.FirstOrDefault(m => m.Id.Equals(kv.Key, StringComparison.OrdinalIgnoreCase));
                var variant = def?.Variants.FirstOrDefault(v => v.Id.Equals(kv.Value.VariantId, StringComparison.OrdinalIgnoreCase));
                return new GraphicsModInfoDto(kv.Key, def?.Name ?? kv.Key, variant?.Label ?? string.Empty);
            }).ToArray();
        }
        catch { return Array.Empty<GraphicsModInfoDto>(); }
    });

