    private static (long ticks, long size, string? path)? _minimapPathCache;
    private static readonly object _minimapPathCacheLock = new();

    private static string? ResolveLiveMinimapGfxPath(string gtaRoot)
        => ResolveLiveMinimapGfxPath(gtaRoot, out _);

    private static string? ResolveLiveMinimapGfxPath(string gtaRoot, out string? failReason)
    {
        failReason = null;
        var updateRpf = Path.Combine(gtaRoot, "update", "update.rpf");
        long ticks = 0, size = 0;
        try { var fi = new FileInfo(updateRpf); ticks = fi.LastWriteTimeUtc.Ticks; size = fi.Length; } catch { }

        lock (_minimapPathCacheLock)
        {
            if (_minimapPathCache is { } c && c.ticks == ticks && c.size == size && c.path is not null)
                return c.path;
        }

        List<string> all = new();
        Exception? openErr = null;
        for (int attempt = 0; attempt < 3; attempt++)
        {
            all = Core.Services.PatchCustomizationSupport
                .FindInternalPathsByNameDeep(gtaRoot, "minimap.gfx", out openErr);
            if (all.Count > 0) break;
            if (attempt < 2) System.Threading.Thread.Sleep(350);
        }
        if (all.Count == 0)
        {
            failReason = openErr is null
                ? "minimap.gfx не найден в update.rpf."
                : $"Не удалось открыть update.rpf ({openErr.Message}). Закрой GTA и лишние программы, потом попробуй ещё раз.";
            return null;
        }
        var resolved = all.FirstOrDefault(p =>
            p.IndexOf("scaleform_minimap.rpf", StringComparison.OrdinalIgnoreCase) < 0) ?? all[0];
        lock (_minimapPathCacheLock) { _minimapPathCache = (ticks, size, resolved); }
        return resolved;
    }

    private static string GetMinimapTweakBasePath()
        => Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
            "MiamiGraphics", "config", "minimap_tweak_base.gfx");

    private static string GetMinimapTweakBaseMetaPath()
        => Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
            "MiamiGraphics", "config", "minimap_tweak_base.json");

    private sealed record MinimapTweakBaseMeta(string BaseSha, string LiveSha, string InternalPath);

    private static string Sha256Hex(byte[] bytes)
    {
        using var sha = global::System.Security.Cryptography.SHA256.Create();
        return Convert.ToHexString(sha.ComputeHash(bytes));
    }

    private static void SaveMinimapTweakBase(byte[] baseGfx, byte[]? liveGfx, string internalPath)
    {
        try
        {
            var path = GetMinimapTweakBasePath();
            Directory.CreateDirectory(Path.GetDirectoryName(path)!);
            File.WriteAllBytes(path, baseGfx);
            var meta = new MinimapTweakBaseMeta(
                Sha256Hex(baseGfx), Sha256Hex(liveGfx ?? baseGfx), internalPath ?? string.Empty);
            File.WriteAllText(GetMinimapTweakBaseMetaPath(),
                System.Text.Json.JsonSerializer.Serialize(meta));
        }
        catch (Exception ex) { Debug.WriteLine($"[minimap.base] save FAIL: {ex.Message}"); }
    }

    private static void UpdateMinimapTweakBaseLiveSha(byte[] liveGfx)
    {
        try
        {
            var metaPath = GetMinimapTweakBaseMetaPath();
            if (!File.Exists(metaPath)) return;
            var meta = System.Text.Json.JsonSerializer.Deserialize<MinimapTweakBaseMeta>(File.ReadAllText(metaPath));
            if (meta is null) return;
            File.WriteAllText(metaPath, System.Text.Json.JsonSerializer.Serialize(
                meta with { LiveSha = Sha256Hex(liveGfx) }));
        }
        catch (Exception ex) { Debug.WriteLine($"[minimap.base] live-sha update FAIL: {ex.Message}"); }
    }

    private static void ClearMinimapTweakBase()
    {
        try { if (File.Exists(GetMinimapTweakBasePath())) File.Delete(GetMinimapTweakBasePath()); } catch { }
        try { if (File.Exists(GetMinimapTweakBaseMetaPath())) File.Delete(GetMinimapTweakBaseMetaPath()); } catch { }
    }

    private static byte[]? LoadValidMinimapTweakBase(byte[] liveGfx, string internalPath)
    {
        var basePath = GetMinimapTweakBasePath();
        if (!File.Exists(basePath)) return null;

        byte[] baseGfx;
        try { baseGfx = File.ReadAllBytes(basePath); }
        catch { return null; }

        MinimapTweakBaseMeta? meta = null;
        try
        {
            var metaPath = GetMinimapTweakBaseMetaPath();
            if (File.Exists(metaPath))
                meta = System.Text.Json.JsonSerializer.Deserialize<MinimapTweakBaseMeta>(File.ReadAllText(metaPath));
        }
        catch { }

        if (meta is null)
        {
            Debug.WriteLine("[minimap.base] legacy base without sidecar - adopting for the current live gfx");
            Core.System.FeatureLog.Write("миникарта",
                "база твиков без сайдкара (от старой сборки) - усыновляю под текущую живую minimap.gfx");
            SaveMinimapTweakBase(baseGfx, liveGfx, internalPath);
            return baseGfx;
        }

        var liveSha = Sha256Hex(liveGfx);
        bool sameFile = !string.IsNullOrWhiteSpace(meta.InternalPath)
            && meta.InternalPath.Equals(internalPath, StringComparison.OrdinalIgnoreCase);
        bool sameMinimap = liveSha.Equals(meta.LiveSha, StringComparison.OrdinalIgnoreCase)
                        || liveSha.Equals(meta.BaseSha, StringComparison.OrdinalIgnoreCase);

        if (sameFile && sameMinimap)
        {
            Core.System.FeatureLog.Write("миникарта",
                $"база твиков годна: путь {internalPath}, живой файл {liveSha[..12]} " +
                $"({(liveSha.Equals(meta.LiveSha, StringComparison.OrdinalIgnoreCase) ? "наш прошлый выход" : "сама база")})");
            return baseGfx;
        }

        Debug.WriteLine($"[minimap.base] STALE (samePath={sameFile}, sameMinimap={sameMinimap}) - dropping, live gfx becomes the new base");
        Core.System.FeatureLog.Write("миникарта",
            "база твиков ПРОТУХЛА - сбрасываю, новой базой станет то, что лежит в игре сейчас. " +
            $"Путь совпал: {(sameFile ? "да" : $"нет (база от {meta.InternalPath}, сейчас {internalPath})")}; " +
            $"файл совпал: {(sameMinimap ? "да" : $"нет (в игре {liveSha[..12]}, ждали {meta.LiveSha[..Math.Min(12, meta.LiveSha.Length)]} или {meta.BaseSha[..Math.Min(12, meta.BaseSha.Length)]})")}");
        ClearMinimapTweakBase();
        return null;
    }

    private static (int Width, int Height, byte[] Rgba)? TryDecodeImageRgba(string? path)
        => TryDecodeImageRgba(path, out _);

    private static (int Width, int Height, byte[] Rgba)? TryDecodeImageRgba(string? path, out string? note)
    {
        note = null;
        if (string.IsNullOrWhiteSpace(path) || !File.Exists(path)) return null;

        var frames = TryCountFrames(path);
        if (frames > 1)
        {
            var picked = TryDecodeBestFrameWic(path, frames, out var usedIndex);
            if (picked is not null)
            {
                note = Loc.T("minimap.animationFlattened",
                    ("frames", frames), ("used", usedIndex + 1));
                return picked;
            }
        }

        return TryDecodeImageRgbaGdi(path) ?? TryDecodeImageRgbaWic(path);
    }

    private static int TryCountFrames(string path)
    {
        try
        {
            using var fs = File.OpenRead(path);
            var dec = System.Windows.Media.Imaging.BitmapDecoder.Create(
                fs,
                System.Windows.Media.Imaging.BitmapCreateOptions.PreservePixelFormat,
                System.Windows.Media.Imaging.BitmapCacheOption.OnDemand);
            return Math.Max(1, dec.Frames.Count);
        }
        catch { return 1; }
    }

    private static (int Width, int Height, byte[] Rgba)? TryDecodeBestFrameWic(
        string path, int frameCount, out int usedIndex)
    {
        usedIndex = 0;
        (int Width, int Height, byte[] Rgba)? first = null;
        var limit = Math.Min(frameCount, 24);
        for (var i = 0; i < limit; i++)
        {
            var frame = TryDecodeImageRgbaWic(path, i);
            if (frame is null) continue;
            first ??= frame;
            if (!HasVisibleContent(frame.Value.Rgba)) continue;
            usedIndex = i;
            return frame;
        }
        return first;
    }

    private static bool HasVisibleContent(byte[] rgba)
    {
        long visible = 0;
        var pixels = rgba.Length / 4;
        if (pixels == 0) return false;
        for (var i = 3; i < rgba.Length; i += 4)
            if (rgba[i] >= 16) visible++;
        return visible * 100 >= pixels;
    }

    private static (int Width, int Height, byte[] Rgba)? TryDecodeImageRgbaGdi(string path)
    {
        try
        {
            using var src = new System.Drawing.Bitmap(path);
            int sw = src.Width, sh = src.Height;
            if (sw < 1 || sh < 1) return null;
            int w = sw, h = sh;
            const int MaxSide = 512;
            if (w > MaxSide || h > MaxSide)
            {
                double k = Math.Min((double)MaxSide / w, (double)MaxSide / h);
                w = Math.Max(1, (int)Math.Round(w * k));
                h = Math.Max(1, (int)Math.Round(h * k));
            }
            using var bmp = new System.Drawing.Bitmap(w, h, System.Drawing.Imaging.PixelFormat.Format32bppArgb);
            using (var g = System.Drawing.Graphics.FromImage(bmp))
            {
                g.InterpolationMode = System.Drawing.Drawing2D.InterpolationMode.HighQualityBicubic;
                g.PixelOffsetMode = System.Drawing.Drawing2D.PixelOffsetMode.HighQuality;
                g.CompositingMode = System.Drawing.Drawing2D.CompositingMode.SourceCopy;
                g.DrawImage(src, new System.Drawing.Rectangle(0, 0, w, h));
            }
            var rect = new System.Drawing.Rectangle(0, 0, w, h);
            using var clone = bmp.Clone(rect, System.Drawing.Imaging.PixelFormat.Format32bppArgb);
            var data = clone.LockBits(rect, System.Drawing.Imaging.ImageLockMode.ReadOnly,
                System.Drawing.Imaging.PixelFormat.Format32bppArgb);
            var rgba = new byte[w * h * 4];
            try
            {
                var tmp = new byte[Math.Abs(data.Stride) * h];
                System.Runtime.InteropServices.Marshal.Copy(data.Scan0, tmp, 0, tmp.Length);
                for (int y = 0; y < h; y++)
                for (int x = 0; x < w; x++)
                {
                    int si = y * data.Stride + x * 4;
                    int di = (y * w + x) * 4;
                    rgba[di + 0] = tmp[si + 2];
                    rgba[di + 1] = tmp[si + 1];
                    rgba[di + 2] = tmp[si + 0];
                    rgba[di + 3] = tmp[si + 3];
                }
            }
            finally { clone.UnlockBits(data); }
            return (w, h, rgba);
        }
        catch { return null; }
    }

    private static (int Width, int Height, byte[] Rgba)? TryDecodeImageRgbaWic(string path, int frameIndex = 0)
    {
        try
        {
            using var fs = File.OpenRead(path);
            var dec = System.Windows.Media.Imaging.BitmapDecoder.Create(
                fs,
                System.Windows.Media.Imaging.BitmapCreateOptions.PreservePixelFormat,
                System.Windows.Media.Imaging.BitmapCacheOption.OnLoad);
            if (frameIndex < 0 || frameIndex >= dec.Frames.Count) return null;
            System.Windows.Media.Imaging.BitmapSource frame = dec.Frames[frameIndex];
            int sw = frame.PixelWidth, sh = frame.PixelHeight;
            if (sw < 1 || sh < 1) return null;
            const int MaxSide = 512;
            if (sw > MaxSide || sh > MaxSide)
            {
                double k = Math.Min((double)MaxSide / sw, (double)MaxSide / sh);
                frame = new System.Windows.Media.Imaging.TransformedBitmap(
                    frame, new System.Windows.Media.ScaleTransform(k, k));
            }
            var conv = new System.Windows.Media.Imaging.FormatConvertedBitmap(
                frame, System.Windows.Media.PixelFormats.Bgra32, null, 0);
            int w = conv.PixelWidth, h = conv.PixelHeight;
            int stride = w * 4;
            var bgra = new byte[stride * h];
            conv.CopyPixels(bgra, stride, 0);
            var rgba = new byte[w * h * 4];
            for (int i = 0; i < w * h; i++)
            {
                rgba[i * 4 + 0] = bgra[i * 4 + 2];
                rgba[i * 4 + 1] = bgra[i * 4 + 1];
                rgba[i * 4 + 2] = bgra[i * 4 + 0];
                rgba[i * 4 + 3] = bgra[i * 4 + 3];
            }
            return (w, h, rgba);
        }
        catch { return null; }
    }

    private async Task<byte[]?> TryGetCleanMinimapGfxBytesAsync()
    {
        var candidates = new List<string?> { GetLocalCleanRpfPath() };
        try { candidates.Add((await _adminConfig.GetAsync()).CleanUpdateRpfPath); } catch { }
        foreach (var rpf in candidates)
        {
            if (string.IsNullOrWhiteSpace(rpf) || !File.Exists(rpf)) continue;
            foreach (var p in Core.Services.MinimapBuilderService.DefaultTargetPaths)
            {
                var b = await Task.Run(() =>
                    Core.Services.PatchCustomizationSupport.GetBytesFromArchiveExactPath(rpf!, p));
                if (b is { Length: > 1000 }) return b;
            }
        }
        return null;
    }

    private async Task<byte[]?> TryGetCleanFontLibBytesAsync()
    {
        var candidates = new List<string?> { GetLocalCleanRpfPath() };
        try { candidates.Add((await _adminConfig.GetAsync()).CleanUpdateRpfPath); } catch { }
        foreach (var rpf in candidates)
        {
            if (string.IsNullOrWhiteSpace(rpf) || !File.Exists(rpf)) continue;
            var b = await Task.Run(() =>
                Core.Services.PatchCustomizationSupport.GetBytesFromArchiveExactPath(
                    rpf!, MinimapFontContainerPath + "font_lib_efigs_pc.gfx"));
            if (b is { Length: > 1000 }) return b;
        }
        return null;
    }

    private async Task<string?> RestoreStockFontLibAsync(string updateRpf)
    {
        try
        {
            var clean = await TryGetCleanFontLibBytesAsync();
            if (clean is null) return null;

            var path = MinimapFontContainerPath + "font_lib_efigs_pc.gfx";
            var live = await Task.Run(() =>
                Core.Services.PatchCustomizationSupport.GetBytesFromArchiveExactPath(updateRpf, path));
            if (live is null) return null;
            if (live.Length == clean.Length && live.AsSpan().SequenceEqual(clean))
                return null;

            return "у сборки свой шрифт интерфейса - мы его сохранили. " +
                   "Ник и статистика игрока останутся как были, но цифры и текст на миникарте " +
                   "в игре будут набраны этим шрифтом, а не тем, что показывает редактор. " +
                   "Нужен свой шрифт именно на миникарте - выбери гарнитуру в редакторе миникарты.";
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[minimap.fontlib] check FAIL: {ex.Message}");
            return null;
        }
    }

    public async Task<InjectResultDto> MinimapApplyTweaksAsync(MinimapTweaksDto tweaks)
    {
        using var _mtx = await MiamiGraphics.Shell.Services.UpdateRpfMutex.AcquireAsync("minimap-tweaks");

        const string progressKey = "minimap-tweaks";
        const string prettyName  = "Миникарта: конструктор";

        var gtaRoot = await GetGtaPathAsync();
        if (string.IsNullOrWhiteSpace(gtaRoot))
            return new InjectResultDto(false, "GTA не найдена.", null);
        var updateRpf = Path.Combine(gtaRoot, "update", "update.rpf");
        if (!File.Exists(updateRpf))
            return new InjectResultDto(false, $"Не найден {updateRpf}.", null);

        EmitInstallProgress(progressKey, prettyName, "starting", 4, null, detailMessage: Loc.T("progress.minimap.preparing"));

        var notes = new List<string>();
        var (javaCandidate, ffdecJar, swfmillExe) = ResolveMinimapTools();
        var javaExe = await EnsureMinimapJavaAsync(javaCandidate, notes,
            (_, _, msg) => { if (msg != null) EmitInstallProgress(progressKey, prettyName, "injecting", 20, null, detailMessage: msg); });
        if (javaExe is null || ffdecJar is null || !File.Exists(ffdecJar))
        {
            var msg = "Не удалось подготовить инструменты (Java/ffdec) для конструктора миникарты.";
            EmitInstallProgress(progressKey, prettyName, "error", 0, msg);
            return new InjectResultDto(false, msg, null);
        }

        string? resolveFail = null;
        var internalPath = await Task.Run(() => ResolveLiveMinimapGfxPath(gtaRoot, out resolveFail));
        if (internalPath is null)
        {
            var msg = resolveFail ?? "minimap.gfx не найден в update.rpf.";
            EmitInstallProgress(progressKey, prettyName, "error", 0, msg);
            return new InjectResultDto(false, msg, null);
        }

        var liveGfx = await Task.Run(() =>
            Core.Services.PatchCustomizationSupport.GetBytesFromArchiveExactPath(updateRpf, internalPath));
        if (liveGfx is null)
        {
            const string msg = "Не удалось извлечь minimap.gfx из update.rpf.";
            EmitInstallProgress(progressKey, prettyName, "error", 0, msg);
            return new InjectResultDto(false, msg, null);
        }

        byte[]? baseGfx = LoadValidMinimapTweakBase(liveGfx, internalPath);
        bool baseFromDisk = baseGfx is not null;
        bool usedCleanFallback = false;

        if (baseGfx is null)
        {
            baseGfx = await TryGetCleanMinimapGfxBytesAsync();
            usedCleanFallback = baseGfx is not null;
        }
        baseGfx ??= liveGfx;

        EmitInstallProgress(progressKey, prettyName, "injecting", 35, null, detailMessage: Loc.T("progress.minimap.building"));

        byte[]? built;
        string? hitWarn = null;
        bool nothingRequested = !Core.Services.MinimapScriptTweaksService.AnyRequested(MapMinimapTweaks(tweaks))
            && string.IsNullOrWhiteSpace(tweaks.HitPngPath)
            && string.IsNullOrWhiteSpace(tweaks.ArrowPngPath)
            && string.IsNullOrWhiteSpace(tweaks.GpsPngPath);
        if (nothingRequested)
        {
            if (!baseFromDisk && !usedCleanFallback)
            {
                const string msg = "Нет ни сохранённой базы, ни чистого бэкапа - снять твики не из чего.";
                EmitInstallProgress(progressKey, prettyName, "error", 0, msg);
                return new InjectResultDto(false, msg, null);
            }
            built = baseGfx;
        }
        else
        {
            var coreTweaks = MapMinimapTweaks(tweaks)!;
            var imageNotes = new List<string>();
            var hitImage = TryDecodeImageRgba(tweaks.HitPngPath, out var hitImgNote);
            if (hitImgNote is not null) imageNotes.Add(Loc.T("minimap.noteForHit", ("note", hitImgNote)));
            if (!string.IsNullOrWhiteSpace(tweaks.HitPngPath) && hitImage is null)
            {
                var msg = $"Картинка вспышки не читается ({Path.GetFileName(tweaks.HitPngPath)}): " +
                          "поддерживаются PNG, GIF, JPG, WEBP, BMP. Файл битый или " +
                          "формат без кодека Windows - выбери другой файл или выключи «Свой PNG/GIF».";
                EmitInstallProgress(progressKey, prettyName, "error", 0, msg);
                return new InjectResultDto(false, msg, null);
            }
            var arrowImage = TryDecodeImageRgba(tweaks.ArrowPngPath, out var arrowImgNote);
            if (arrowImgNote is not null) imageNotes.Add(Loc.T("minimap.noteForArrow", ("note", arrowImgNote)));
            if (!string.IsNullOrWhiteSpace(tweaks.ArrowPngPath) && arrowImage is null)
            {
                var msg = $"Картинка стрелки игрока не читается ({Path.GetFileName(tweaks.ArrowPngPath)}): " +
                          "поддерживаются PNG, GIF, JPG, WEBP, BMP - выбери другой файл или убери картинку.";
                EmitInstallProgress(progressKey, prettyName, "error", 0, msg);
                return new InjectResultDto(false, msg, null);
            }
            var gpsImage = TryDecodeImageRgba(tweaks.GpsPngPath, out var gpsImgNote);
            if (gpsImgNote is not null) imageNotes.Add(Loc.T("minimap.noteForGps", ("note", gpsImgNote)));
            if (!string.IsNullOrWhiteSpace(tweaks.GpsPngPath) && gpsImage is null)
            {
                var msg = $"Картинка метки GPS не читается ({Path.GetFileName(tweaks.GpsPngPath)}): " +
                          "поддерживаются PNG, GIF, JPG, WEBP, BMP - выбери другой файл или убери картинку.";
                EmitInstallProgress(progressKey, prettyName, "error", 0, msg);
                return new InjectResultDto(false, msg, null);
            }
            var (bytes, err, already, hitNote) = await Task.Run(() =>
            {
                var b = Core.Services.MinimapBuilderService.ApplyTweaksToGfxBytes(
                    baseGfx!, coreTweaks, javaExe!, ffdecJar!, out var e, out var a, out var hn,
                    hitImage: hitImage, arrowImage: arrowImage, gpsImage: gpsImage);
                return (b, e, a, hn);
            });

            if (bytes is null && already && !baseFromDisk)
            {
                EmitInstallProgress(progressKey, prettyName, "injecting", 40, null,
                    detailMessage: Loc.T("progress.minimap.tweaksPresentUseCleanBase"));
                var clean = await TryGetCleanMinimapGfxBytesAsync();
                if (clean is not null)
                {
                    (bytes, err, already, hitNote) = await Task.Run(() =>
                    {
                        var b = Core.Services.MinimapBuilderService.ApplyTweaksToGfxBytes(
                            clean, coreTweaks, javaExe!, ffdecJar!, out var e, out var a, out var hn,
                            hitImage: hitImage, arrowImage: arrowImage, gpsImage: gpsImage);
                        return (b, e, a, hn);
                    });
                    if (bytes is not null)
                    {
                        baseGfx = clean;
                        usedCleanFallback = true;
                    }
                }
            }

            if (bytes is null)
            {
                var msg = already
                    ? "В установленной миникарте уже стоят твики, а чистый бэкап недоступен - переустанови миникарту и попробуй снова."
                    : $"Не удалось собрать миникарту: {err}";
                EmitInstallProgress(progressKey, prettyName, "error", 0, msg);
                return new InjectResultDto(false, msg, null);
            }
            built = bytes;
            if (hitNote is not null) imageNotes.Insert(0, hitNote);
            hitWarn = imageNotes.Count > 0 ? string.Join(" ", imageNotes) : null;
        }

        string? ringsWarn = null;
        var ringsMeters = ReadInstallState()?.CustomizationDraft?.Minimap?.RangeRingsMeters;
        if (ringsMeters is { Length: > 0 } && built is not null)
        {
            var ringsTmp = Path.Combine(Path.GetTempPath(), "mmrings_" + Guid.NewGuid().ToString("N") + ".gfx");
            try
            {
                await File.WriteAllBytesAsync(ringsTmp, built);
                if (await Task.Run(() => Core.Services.MinimapRangeRingsService.Apply(ringsTmp, ringsMeters)))
                    built = await File.ReadAllBytesAsync(ringsTmp);
                else
                    ringsWarn = "круги дальности не легли на эту миникарту";
            }
            catch (Exception ex)
            {
                ringsWarn = $"круги дальности не переприменились ({ex.Message})";
                Debug.WriteLine($"[minimap.tweaks] rings re-apply FAIL: {ex.Message}");
            }
            finally { try { File.Delete(ringsTmp); } catch { } }
        }

        var rollback = updateRpf + ".tweaks_rollback";
        await MakeRollbackPointAsync(updateRpf, rollback, progressKey, prettyName,
            "injecting", new ProgressBand(40, 45), "minimap.tweaks");

        using var rampCts = new CancellationTokenSource();
        var ramp = StartProgressRamp(
            (phase, pct) => EmitInstallProgress(progressKey, prettyName, phase, pct, null,
                detailMessage: Loc.T("progress.minimap.embedding")),
            "injecting", 45, 95, 120, rampCts.Token);

        bool checksumOk = false;
        Exception? applyErr = null;
        try
        {
            checksumOk = await Task.Run(() =>
                Core.Services.PatchCustomizationSupport.ReplaceFileInLiveArchive(updateRpf, internalPath, built!));
        }
        catch (Exception ex) { applyErr = ex; }
        finally { rampCts.Cancel(); try { await ramp; } catch { } }

        if (applyErr is not null || !checksumOk)
        {
            try { if (File.Exists(rollback)) File.Copy(rollback, updateRpf, overwrite: true); } catch { }
            try { if (File.Exists(rollback)) File.Delete(rollback); } catch { }
            var msg = applyErr is not null
                ? $"Не удалось применить: {applyErr.Message}"
                : "Не удалось перешифровать update.rpf (ArchiveFix) - изменения откачены.";
            EmitInstallProgress(progressKey, prettyName, "error", 0, msg);
            return new InjectResultDto(false, msg, null);
        }
        try { if (File.Exists(rollback)) File.Delete(rollback); } catch { }

        var fontLibNote = await RestoreStockFontLibAsync(updateRpf);
        if (fontLibNote is not null) notes.Add(fontLibNote);

        SaveMinimapTweakBase(baseGfx!, built!, internalPath);

        try
        {
            var st = ReadInstallState();
            var prev = st?.CustomizationDraft;
            if (prev is not null)
            {
                var nextMinimap = prev.Minimap with
                {
                    Enabled = prev.Minimap.Enabled || !nothingRequested,
                    Tweaks  = nothingRequested ? null : tweaks,
                };
                WriteInstallState(new InstallState
                {
                    ReduxId            = st!.ReduxId,
                    VersionId          = st.VersionId,
                    PostInstallSha256  = await Task.Run(() => Services.FileShaCache.ComputeSha256Cached(updateRpf)),
                    InstalledAt        = st.InstalledAt,
                    CustomizationDraft = prev with { Minimap = nextMinimap },
                    CurrentArmorId     = st.CurrentArmorId,
                    CurrentArmorName   = st.CurrentArmorName,
                    CurrentArmorGlbUrl = st.CurrentArmorGlbUrl,
                    CurrentArmorKind   = st.CurrentArmorKind,
                });
            }
        }
        catch (Exception ex) { Debug.WriteLine($"[minimap.tweaks] persist FAIL (non-fatal): {ex.Message}"); }

        var doneMsg = nothingRequested
            ? Loc.T("progress.minimap.builderSettingsCleared")
            : usedCleanFallback
                ? Loc.T("progress.minimap.updatedFromCleanBase")
                : Loc.T("progress.minimap.updated");
        if (hitWarn is not null) doneMsg += Loc.T("progress.common.warningSuffix", ("text", hitWarn));
        if (ringsWarn is not null) doneMsg += Loc.T("progress.common.warningSuffix", ("text", ringsWarn));
        EmitInstallProgress(progressKey, prettyName, "done", 100, null, detailMessage: doneMsg);
        return new InjectResultDto(true, null, updateRpf);
    }

    public Task<string?> FileToDataUrlAsync(string path)
    {
        try
        {
            if (string.IsNullOrWhiteSpace(path) || !File.Exists(path)) return Task.FromResult<string?>(null);
            var fi = new FileInfo(path);
            if (fi.Length > 8_000_000) return Task.FromResult<string?>(null);
            var mime = Path.GetExtension(path).ToLowerInvariant() switch
            {
                ".png"  => "image/png",
                ".gif"  => "image/gif",
                ".jpg" or ".jpeg" => "image/jpeg",
                ".webp" => "image/webp",
                ".bmp"  => "image/bmp",
                _ => null,
            };
            if (mime is null) return Task.FromResult<string?>(null);
            return Task.FromResult<string?>($"data:{mime};base64,{Convert.ToBase64String(File.ReadAllBytes(path))}");
        }
        catch { return Task.FromResult<string?>(null); }
    }

