    {
        try { return Task.FromResult(ReadInstallState()?.CustomizationDraft?.Minimap?.Tweaks); }
        catch { return Task.FromResult<MinimapTweaksDto?>(null); }
    }

    private const string HotSwapTaskName = "MiamiGraphicsAgent";

    private static string? ResolveAgentExe() => Environment.ProcessPath;

    private static void KillHotSwapAgent(string gtaRoot)
    {
        try
        {
            var ap = Core.HotSwap.HotSwapPaths.AgentStatePath(gtaRoot);
            if (!File.Exists(ap)) return;
            using var doc = System.Text.Json.JsonDocument.Parse(File.ReadAllText(ap));
            if (!doc.RootElement.TryGetProperty("pid", out var pidEl) || !pidEl.TryGetInt32(out int pid)) return;
            if (pid == Environment.ProcessId) return;
            using var p = Process.GetProcessById(pid);
            Core.HotSwap.HotSwapLog.Write("мост", $"гашу фонового агента (pid {pid} из heartbeat)");
            p.Kill();
            p.WaitForExit(5000);
        }
        catch {}
    }

    private static bool RunSchtasks(string args, out string output)
    {
        try
        {
            using var proc = Process.Start(new ProcessStartInfo("schtasks.exe", args)
            {
                UseShellExecute = false, CreateNoWindow = true,
                RedirectStandardOutput = true, RedirectStandardError = true,
            })!;
            output = proc.StandardOutput.ReadToEnd() + proc.StandardError.ReadToEnd();
            proc.WaitForExit(30_000);
            return proc.ExitCode == 0;
        }
        catch (Exception ex) { output = ex.Message; return false; }
    }

    public async Task<HotSwapStatusDto> HotSwapGetStatusAsync()
    {
        try
        {
            var mode = Core.HotSwap.HotSwapModeStore.Read();
            var method = Core.HotSwap.HotSwapPlan.Normalize(mode.Method);
            bool manual = Core.HotSwap.HotSwapPlan.IsManual(method);
            var gtaRoot = mode.GtaRoot ?? await GetGtaPathAsync();
            if (string.IsNullOrWhiteSpace(gtaRoot))
                return new HotSwapStatusDto(false, false, false, false, false, null, "GTA не найдена.",
                    (int)method, manual);

            bool volOk = Core.HotSwap.HotSwapPaths.VolumeSupported(gtaRoot, method, mode.StoreRoot, out var volReason);
            bool haveClean = GetLocalCleanRpfPath() is { } cp && File.Exists(cp);
            bool frozen = Core.HotSwap.GameFileSwapper.ReadSet(gtaRoot).Count > 0;
            var phase = Core.HotSwap.HotSwapJournal.Read(gtaRoot).Phase;
            bool armed = phase == Core.HotSwap.HotSwapPhase.Armed;

            bool agentAlive = false;
            try
            {
                var ap = Core.HotSwap.HotSwapPaths.AgentStatePath(gtaRoot);
                if (File.Exists(ap))
                {
                    using var doc = System.Text.Json.JsonDocument.Parse(File.ReadAllText(ap));
                    if (doc.RootElement.TryGetProperty("atUtc", out var at) &&
                        DateTime.TryParse(at.GetString(), null,
                            System.Globalization.DateTimeStyles.RoundtripKind, out var t))
                        agentAlive = (DateTime.UtcNow - t).TotalSeconds < 60;
                }
            }
            catch { }

            string? staleNote = frozen ? Core.HotSwap.GameFileSwapper.StaleReason(gtaRoot) : null;
            bool stale = staleNote is not null;
            string? staleAt = null;
            if (stale)
                try { staleAt = Core.HotSwap.RockstarRepairWatch.Read(gtaRoot)?.AtUtc; } catch { }

            string? note = staleNote
                ?? (!volOk ? volReason
                : !haveClean ? "Нужен чистый бэкап update.rpf (сделай установку через лаунчер)."
                : null);
            if (manual) agentAlive = mode.Enabled;

            return new HotSwapStatusDto(mode.Enabled, volOk && haveClean, frozen, armed, agentAlive,
                Core.HotSwap.HotSwapPaths.ImageRoot(gtaRoot, method, mode.StoreRoot), note,
                (int)method, manual, stale, staleNote, staleAt);
        }
        catch (Exception ex)
        {
            return new HotSwapStatusDto(false, false, false, false, false, null, ex.Message);
        }
    }

