    public async Task<InjectResultDto> HotSwapRebuildAsync()
    {
        using var _mtx = await MiamiGraphics.Shell.Services.UpdateRpfMutex.AcquireAsync("hotswap-rebuild");
        const string progressKey = "hotswap";
        const string prettyName  = "Режим Rockstar";

        bool agentTornDown = false;
        bool modeStillEnabled = false;
        string? tornDownRoot = null;
        bool needsAgentForRestore = false;

        try
        {
            Core.HotSwap.HotSwapLog.Write("мост", "Rebuild: запрос из интерфейса (пересборка протухшего образа)");
            var mode = Core.HotSwap.HotSwapModeStore.Read();
            var gtaRoot = !string.IsNullOrWhiteSpace(mode.GtaRoot) ? mode.GtaRoot! : await GetGtaPathAsync();
            if (string.IsNullOrWhiteSpace(gtaRoot))
            {
                Core.HotSwap.HotSwapLog.Write("мост", "Rebuild: отказ - GTA не найдена");
                return new InjectResultDto(false, "GTA не найдена.", null);
            }
            if (Core.HotSwap.GameProcessWatcher.FindRpfHolderProcess() is not null)
            {
                Core.HotSwap.HotSwapLog.Write("мост", "Rebuild: отказ - игра запущена, файлы заняты");
                return new InjectResultDto(false, "Сначала закрой GTA - файлы игры заняты.", null);
            }

            var swapMethod = Core.HotSwap.HotSwapStore.ActiveMethod(gtaRoot);
            var staleWhy = Core.HotSwap.GameFileSwapper.StaleReason(gtaRoot);
            Core.HotSwap.HotSwapLog.Write("мост",
                $"Rebuild: gta {gtaRoot}, способ {(int)swapMethod}, причина протухания: {staleWhy ?? "(нет, образ считается годным)"}");

            modeStillEnabled = mode.Enabled;
            tornDownRoot = gtaRoot;
            needsAgentForRestore = Core.HotSwap.HotSwapPlan.NeedsAgent(
                Core.HotSwap.HotSwapPlan.Normalize(mode.Method));
            EmitInstallProgress(progressKey, prettyName, "injecting", 10, null,
                detailMessage: Loc.T("progress.hotswap.stoppingAgent"));
            RunSchtasks($"/Delete /TN \"{HotSwapTaskName}\" /F", out _);
            KillHotSwapAgent(gtaRoot);
            agentTornDown = true;

            var dropped = new List<string>();
            if (Core.HotSwap.GameFileSwapper.ReadSet(gtaRoot).Count > 0)
            {
                EmitInstallProgress(progressKey, prettyName, "injecting", 25, null,
                    detailMessage: Loc.T("progress.hotswap.dismantlingImage"));
                await Task.Run(() =>
                {
                    if (!Core.HotSwap.GameFileSwapper.Unfreeze(gtaRoot, swapMethod, out var e, out var dr))
                        throw new InvalidOperationException(e);
                    dropped = dr;
                });
            }
            else
            {
                Core.HotSwap.HotSwapLog.Write("мост", "Rebuild: образа нет (набор пуст) - только выключаю режим");
            }

            Core.HotSwap.HotSwapModeStore.Write(new Core.HotSwap.HotSwapMode
            {
                Enabled = false, GtaRoot = gtaRoot,
                Method = (int)Core.HotSwap.HotSwapPlan.Normalize(mode.Method),
                StoreRoot = mode.StoreRoot,
            });
            modeStillEnabled = false;

            EmitInstallProgress(progressKey, prettyName, "injecting", 55, null,
                detailMessage: Loc.T("progress.hotswap.updatingCleanCopy"));
            bool cleanOk = false;
            try
            {
                var progress = new Progress<Core.System.BackupProgress>(p =>
                {
                    string detail = p.Phase switch
                    {
                        "hashing_user_update"      => "Проверяю новый update.rpf...",
                        "comparing"                => "Сверяю с эталоном...",
                        "snapshot_user_update"     => "Сохраняю update.rpf в бэкап...",
                        "downloading_clean_update" => "Готовлю чистую копию update.rpf...",
                        _                          => "Обновляю чистую копию...",
                    };
                    int pct = 55 + Math.Clamp(p.Percent, 0, 100) * 35 / 100;
                    EmitInstallProgress(progressKey, prettyName, "injecting", pct, null, detailMessage: detail);
                });
                Core.System.BackupResult backup;
                for (int attempt = 1; ; attempt++)
                {
                    backup = await _backupService.RunFullBackupAsync(gtaRoot, progress, CancellationToken.None);
                    cleanOk = backup.Success && GetLocalCleanRpfPath() is not null;
                    Core.HotSwap.HotSwapLog.Write("мост",
                        $"Rebuild: обновление чистой копии, попытка {attempt} - success={backup.Success}, " +
                        $"код {backup.ErrorCode ?? "нет"}, чистый файл на диске: {(cleanOk ? "есть" : "НЕТ")}");
                    bool locked = !cleanOk && string.Equals(backup.ErrorCode, "FILE_LOCKED", StringComparison.OrdinalIgnoreCase);
                    if (!locked || attempt >= 6) break;
                    EmitInstallProgress(progressKey, prettyName, "injecting", 55, null,
                        detailMessage: Loc.T("progress.hotswap.waitingForLauncher", ("attempt", attempt)));
                    await Task.Delay(TimeSpan.FromSeconds(20));
                }
            }
            catch (Exception bex)
            {
                Core.HotSwap.HotSwapLog.Write("мост", "Rebuild: обновление чистой копии не удалось (не критично)", bex);
            }

            var reduxName = ReadInstallState()?.ReduxId;
            var msg = Loc.T("progress.hotswap.rebuildDoneHead") +
                      (dropped.Count > 0 ? Loc.T("progress.hotswap.rebuildDropped", ("count", dropped.Count)) : "") +
                      (cleanOk ? "" : Loc.T("progress.hotswap.rebuildCleanFailed")) +
                      Loc.T("progress.hotswap.rebuildDoneTail");
            Core.HotSwap.HotSwapLog.Write("мост",
                $"Rebuild: итог - режим выключен, выброшено файлов образа {dropped.Count} " +
                $"[{string.Join(", ", dropped)}], прошлая сборка в state: {reduxName ?? "(нет)"}");
            EmitInstallProgress(progressKey, prettyName, "done", 100, null, detailMessage: msg);
            return new InjectResultDto(true, null, gtaRoot);
        }
        catch (Exception ex)
        {
            Core.HotSwap.HotSwapLog.Write("мост", "Rebuild: ошибка", ex);

            var restoreNote = "";
            if (agentTornDown && modeStillEnabled && needsAgentForRestore && tornDownRoot is not null)
            {
                var agentExe = ResolveAgentExe();
                var so = "(не определён путь exe)";
                bool taskBack = agentExe is not null && RunSchtasks(
                    $"/Create /TN \"{HotSwapTaskName}\" /TR \"\\\"{agentExe}\\\" --hotswap-agent\" /SC ONLOGON /RL HIGHEST /F",
                    out so);
                if (taskBack)
                {
                    try
                    {
                        Process.Start(new ProcessStartInfo(agentExe!)
                        { Arguments = "--hotswap-agent", UseShellExecute = true });
                    }
                    catch (Exception sx)
                    {
                        Core.HotSwap.HotSwapLog.Write("мост",
                            "Rebuild: агент вернулся задачей, но сразу не стартовал (поднимется при входе в систему)", sx);
                    }
                    Core.HotSwap.HotSwapLog.Write("мост", "Rebuild: откат - задача Планировщика и агент возвращены на место");
                }
                else
                {
                    Core.HotSwap.HotSwapLog.Write("мост",
                        "Rebuild: ВЕРНУТЬ агента не удалось - режим включён, но подставлять моды некому. Вывод schtasks: "
                        + so.Trim());
                    restoreNote = " Фоновый агент вернуть не удалось - выключи режим Rockstar в настройках, " +
                                  "иначе моды не будут подставляться.";
                }
            }

            var msg = "Пересборка режима Rockstar: " + ex.Message + restoreNote;
            EmitInstallProgress(progressKey, prettyName, "error", 0, msg);
            return new InjectResultDto(false, msg, null);
        }
    }

    public async Task<InjectResultDto> HotSwapSetEnabledAsync(bool enabled, int? method = null)
    {
        using var _mtx = await MiamiGraphics.Shell.Services.UpdateRpfMutex.AcquireAsync("hotswap-mode");
        const string progressKey = "hotswap";
        const string prettyName  = "Режим Rockstar";
        try
        {
            var gtaRoot = await GetGtaPathAsync();
            if (string.IsNullOrWhiteSpace(gtaRoot) && !enabled)
            {
                gtaRoot = Core.HotSwap.HotSwapModeStore.Read().GtaRoot ?? "";
                if (!string.IsNullOrWhiteSpace(gtaRoot))
                    Core.HotSwap.HotSwapLog.Write("мост",
                        $"SetEnabled(false): GTA по текущему пути не найдена, выключаю по замороженному корню {gtaRoot}");
            }
            if (string.IsNullOrWhiteSpace(gtaRoot))
            {
                Core.HotSwap.HotSwapLog.Write("мост", $"SetEnabled({enabled}): отказ - GTA не найдена");
                return new InjectResultDto(false, "GTA не найдена.", null);
            }
            if (Core.HotSwap.GameProcessWatcher.FindRpfHolderProcess() is not null)
            {
                Core.HotSwap.HotSwapLog.Write("мост", $"SetEnabled({enabled}): отказ - игра запущена, файлы заняты");
                return new InjectResultDto(false, "Сначала закрой GTA - файлы игры заняты.", null);
            }

            var prevMode  = Core.HotSwap.HotSwapModeStore.Read();
            var swapMethod = enabled
                ? Core.HotSwap.HotSwapPlan.Normalize(method ?? prevMode.Method)
                : Core.HotSwap.HotSwapPlan.Normalize(prevMode.Method);
            bool needsAgent = Core.HotSwap.HotSwapPlan.NeedsAgent(swapMethod);
            Core.HotSwap.HotSwapLog.Write("мост",
                $"SetEnabled({enabled}): способ {(int)swapMethod} ({Core.HotSwap.HotSwapPlan.For(swapMethod).Title}), " +
                $"storeRoot {(string.IsNullOrWhiteSpace(prevMode.StoreRoot) ? "(дефолт)" : prevMode.StoreRoot)}, " +
                $"gta {gtaRoot}, агент нужен: {(needsAgent ? "да" : "нет")}");

            var agentExe = needsAgent ? ResolveAgentExe() : null;

            if (enabled)
            {
                if (!Core.HotSwap.HotSwapPaths.VolumeSupported(gtaRoot, swapMethod, prevMode.StoreRoot, out var volWhy))
                {
                    Core.HotSwap.HotSwapLog.Write("мост", "SetEnabled(true): отказ - диск не подходит: " + volWhy);
                    return new InjectResultDto(false, volWhy ?? "Диск игры не подходит для режима.", null);
                }
                if (needsAgent && agentExe is null)
                {
                    Core.HotSwap.HotSwapLog.Write("мост", "SetEnabled(true): отказ - не определить путь exe для агента");
                    return new InjectResultDto(false,
                        "Не удалось определить путь лаунчера для фонового агента.", null);
                }

                EmitInstallProgress(progressKey, prettyName, "injecting", 20, null,
                    detailMessage: Loc.T("progress.hotswap.preparingImage"));

                var cleanSources = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
                if (GetLocalCleanRpfPath() is { } cleanUpd && File.Exists(cleanUpd))
                    cleanSources[@"update\update.rpf"] = cleanUpd;
                var dlcTemplate = Path.Combine(
                    Core.System.WorkDirDefaults.ResultBaseDir, "backup", "dlc.rpf");
                if (File.Exists(dlcTemplate))
                    cleanSources[@"update\x64\dlcpacks\patchday18ng\dlc.rpf"] = dlcTemplate;
                foreach (var sfxRel in Core.HotSwap.HotSwapPaths.SfxRelPaths(gtaRoot))
                {
                    var bak = Core.HotSwap.HotSwapPaths.SfxCleanSource(gtaRoot, sfxRel);
                    if (File.Exists(bak)) cleanSources[sfxRel] = bak;
                }
                if (cleanSources.Count == 0)
                {
                    const string noClean = "Нет чистых копий файлов игры - сначала поставь сборку через лаунчер.";
                    Core.HotSwap.HotSwapLog.Write("мост", "SetEnabled(true): отказ - нет ни одного чистого источника");
                    EmitInstallProgress(progressKey, prettyName, "error", 0, noClean);
                    return new InjectResultDto(false, noClean, null);
                }
                Core.HotSwap.HotSwapLog.Write("мост", "SetEnabled(true): чистые источники: " +
                    string.Join("; ", cleanSources.Select(kv => $"{kv.Key} <- {kv.Value}")));

                Core.HotSwap.HotSwapModeStore.Write(new Core.HotSwap.HotSwapMode
                {
                    Enabled = false, GtaRoot = gtaRoot, Method = (int)swapMethod,
                    StoreRoot = prevMode.StoreRoot,
                });

                await Task.Run(() =>
                {
                    if (!Core.HotSwap.GameFileSwapper.Freeze(gtaRoot, cleanSources, swapMethod, prevMode.StoreRoot, out var e))
                        throw new InvalidOperationException(e);
                });

                if (needsAgent)
                {
                    EmitInstallProgress(progressKey, prettyName, "injecting", 80, null,
                        detailMessage: Loc.T("progress.hotswap.registeringAgent"));
                    RunSchtasks($"/Delete /TN \"{HotSwapTaskName}\" /F", out _);
                    if (!RunSchtasks($"/Create /TN \"{HotSwapTaskName}\" /TR \"\\\"{agentExe}\\\" --hotswap-agent\" /SC ONLOGON /RL HIGHEST /F", out var so))
                    {
                        Core.HotSwap.HotSwapLog.Write("мост",
                            "SetEnabled(true): schtasks /Create не удался, откатываю заморозку. Вывод: " + so.Trim());
                        Core.HotSwap.GameFileSwapper.Unfreeze(gtaRoot, swapMethod, out _);
                        var msg = "Не удалось зарегистрировать фоновый агент: " + so.Trim();
                        EmitInstallProgress(progressKey, prettyName, "error", 0, msg);
                        return new InjectResultDto(false, msg, null);
                    }
                    Core.HotSwap.HotSwapLog.Write("мост",
                        $"SetEnabled(true): задача Планировщика {HotSwapTaskName} создана ({agentExe} --hotswap-agent)");
                }

                Core.HotSwap.HotSwapModeStore.Write(new Core.HotSwap.HotSwapMode
                {
                    Enabled = true, GtaRoot = gtaRoot, EnabledAtUtc = DateTime.UtcNow.ToString("O"),
                    Method = (int)swapMethod, StoreRoot = prevMode.StoreRoot,
                });
                if (needsAgent && agentExe is not null)
                {
                    try
                    {
                        Process.Start(new ProcessStartInfo(agentExe)
                        { Arguments = "--hotswap-agent", UseShellExecute = true });
                        Core.HotSwap.HotSwapLog.Write("мост", "SetEnabled(true): агент запущен сразу (не ждём релогина)");
                    }
                    catch (Exception startEx)
                    {
                        Core.HotSwap.HotSwapLog.Write("мост",
                            "SetEnabled(true): немедленный старт агента не удался (поднимется задачей при входе в систему)", startEx);
                    }
                }

                Core.HotSwap.HotSwapLog.Write("мост", "SetEnabled(true): итог - режим включён");
                var doneMsg = needsAgent
                    ? Loc.T("progress.hotswap.enabledWithAgent")
                    : Loc.T("progress.hotswap.enabledManual");
                if (!Core.HotSwap.HotSwapPlan.For(swapMethod).KillGameBeforeReturn
                    && Core.HotSwap.RockstarRepairWatch.Probe(gtaRoot).LauncherAlive)
                {
                    doneMsg += " " + Loc.T("progress.hotswap.enabledRockstarAliveWarning");
                    Core.HotSwap.HotSwapLog.Write("мост",
                        "SetEnabled(true): Rockstar Launcher запущен - предупреждение показано в интерфейсе");
                }
                EmitInstallProgress(progressKey, prettyName, "done", 100, null, detailMessage: doneMsg);
                return new InjectResultDto(true, null, gtaRoot);
            }
            else
            {
                var mode0 = Core.HotSwap.HotSwapModeStore.Read();
                var frozenRoot = !string.IsNullOrWhiteSpace(mode0.GtaRoot) ? mode0.GtaRoot! : gtaRoot;
                Core.HotSwap.HotSwapLog.Write("мост",
                    $"SetEnabled(false): выключаю, замороженный корень {frozenRoot}, снимаю задачу и гашу агента");

                EmitInstallProgress(progressKey, prettyName, "injecting", 30, null,
                    detailMessage: Loc.T("progress.hotswap.disabling"));
                RunSchtasks($"/Delete /TN \"{HotSwapTaskName}\" /F", out _);
                KillHotSwapAgent(frozenRoot);

                Core.HotSwap.HotSwapRecovery.EnsureConsistent(frozenRoot, out _);
                var droppedOff = new List<string>();
                var frozenSet = Core.HotSwap.GameFileSwapper.ReadSet(frozenRoot);
                bool frozenGameGone = frozenSet.Count > 0
                    && !File.Exists(Path.Combine(frozenRoot, "GTA5.exe"));
                if (frozenGameGone)
                {
                    Core.HotSwap.HotSwapLog.Write("мост",
                        $"SetEnabled(false): по замороженному корню {frozenRoot} игры больше нет - сношу образ без возврата");
                    await Task.Run(() => Core.HotSwap.GameFileSwapper.DropImage(frozenRoot));
                    droppedOff = frozenSet;
                }
                else if (frozenSet.Count > 0)
                {
                    await Task.Run(() =>
                    {
                        if (!Core.HotSwap.GameFileSwapper.Unfreeze(frozenRoot, swapMethod, out var e2, out var dr))
                            throw new InvalidOperationException(e2);
                        droppedOff = dr;
                    });
                }
                Core.HotSwap.HotSwapModeStore.Write(new Core.HotSwap.HotSwapMode
                {
                    Enabled = false, GtaRoot = frozenRoot,
                    Method = (int)swapMethod, StoreRoot = prevMode.StoreRoot,
                });
                Core.HotSwap.HotSwapLog.Write("мост", droppedOff.Count == 0
                    ? "SetEnabled(false): итог - режим выключен, моды снова в игре"
                    : $"SetEnabled(false): итог - режим выключен, но моды НЕ вернулись: " +
                      $"выброшено устаревших копий {droppedOff.Count} [{string.Join(", ", droppedOff)}]; " +
                      "в игре остались файлы Rockstar, моды надо ставить заново");
                EmitInstallProgress(progressKey, prettyName, "done", 100, null,
                    detailMessage: droppedOff.Count > 0
                        ? Loc.T("progress.hotswap.disabledDropped")
                        : Loc.T("progress.hotswap.disabled"));
                return new InjectResultDto(true, null, frozenRoot);
            }
        }
        catch (Exception ex)
        {
            bool expected = ex is InvalidOperationException
                            && ex.Message.StartsWith("Нечего замораживать", StringComparison.Ordinal);
            if (expected) Core.HotSwap.HotSwapLog.Write("мост", $"SetEnabled({enabled}): {ex.Message}");
            else Core.HotSwap.HotSwapLog.Write("мост", $"SetEnabled({enabled}): ошибка", ex);
            var msg = "Режим Rockstar: " + ex.Message;
            EmitInstallProgress(progressKey, prettyName, "error", 0, msg);
            return new InjectResultDto(false, msg, null);
        }
    }

