    public async Task<string?> OtherGetArchiveFingerprintAsync()
    {
        try
        {
            var gtaRoot = await GetGtaPathAsync();
            if (string.IsNullOrWhiteSpace(gtaRoot)) return null;
            var fi = new FileInfo(Path.Combine(gtaRoot, "update", "update.rpf"));
            return fi.Exists ? $"{fi.Length}-{fi.LastWriteTimeUtc.Ticks}" : null;
        }
        catch { return null; }
    }

    private const string MinimapFontContainerPath = "x64/data/cdimages/scaleform_platform_pc.rpf/";
    private static readonly string[] MinimapFontSlots =
    {
        "font_lib_efigs_pc.gfx", "font_lib_efigs.gfx",
        "font_lib_russian_pc.gfx", "font_lib_russian.gfx",
    };

    private static string MinimapFontConfigDir =>
        Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
                     "MiamiGraphics", "config");
    private static string MinimapFontBackupDir => Path.Combine(MinimapFontConfigDir, "font_backup");
    private static string MinimapFontStatePath => Path.Combine(MinimapFontConfigDir, "minimap_font.json");

    private sealed class MinimapFontState
    {
        public string? Slot { get; set; }
        public string? SourceFile { get; set; }
    }

    public Task<MinimapFontStateDto> MinimapGetFontStateAsync()
    {
        try
        {
            if (File.Exists(MinimapFontStatePath))
            {
                var st = System.Text.Json.JsonSerializer.Deserialize<MinimapFontState>(
                    File.ReadAllText(MinimapFontStatePath));
                if (st?.Slot is not null)
                    return Task.FromResult(new MinimapFontStateDto(true, st.Slot, st.SourceFile));
            }
        }
        catch { }
        return Task.FromResult(new MinimapFontStateDto(false));
    }

