    public async Task<InjectResultDto> MinimapInstallFontAsync(string gfxPath, string? slot)
    {
        using var _mtx = await MiamiGraphics.Shell.Services.UpdateRpfMutex.AcquireAsync("minimap-font");
        const string progressKey = "minimap-font";
        const string prettyName  = "Миникарта: шрифт";

        try
        {
            if (string.IsNullOrWhiteSpace(gfxPath) || !File.Exists(gfxPath))
                return new InjectResultDto(false, "Файл шрифта не найден.", null);
            var bytes = await File.ReadAllBytesAsync(gfxPath);
            bool sigOk = bytes.Length > 10_000 &&
                ((bytes[0] == (byte)'G' && bytes[1] == (byte)'F' && bytes[2] == (byte)'X') ||
                 (bytes[0] == (byte)'C' && bytes[1] == (byte)'F' && bytes[2] == (byte)'X') ||
                 (bytes[0] == (byte)'F' && bytes[1] == (byte)'W' && bytes[2] == (byte)'S') ||
                 (bytes[0] == (byte)'C' && bytes[1] == (byte)'W' && bytes[2] == (byte)'S'));
            if (!sigOk)
                return new InjectResultDto(false,
                    "Это не шрифт Scaleform (.gfx): нет сигнатуры GFX/CFX/SWF или файл слишком мал.", null);

            var gtaRoot = await GetGtaPathAsync();
            if (string.IsNullOrWhiteSpace(gtaRoot))
                return new InjectResultDto(false, "GTA не найдена.", null);
            var updateRpf = Path.Combine(gtaRoot, "update", "update.rpf");
            if (!File.Exists(updateRpf))
                return new InjectResultDto(false, $"Не найден {updateRpf}.", null);

            string? targetSlot = slot;
            var srcName = Path.GetFileName(gfxPath);
            if (string.IsNullOrWhiteSpace(targetSlot) &&
                srcName.StartsWith("font_lib_", StringComparison.OrdinalIgnoreCase) &&
                srcName.EndsWith(".gfx", StringComparison.OrdinalIgnoreCase))
                targetSlot = srcName;

            EmitInstallProgress(progressKey, prettyName, "starting", 5, null,
                detailMessage: Loc.T("progress.font.searchingSlot"));

            string? foundSlot = null; byte[]? origBytes = null;
            var candidates = targetSlot is not null
                ? new[] { targetSlot }
                : MinimapFontSlots;
            foreach (var cand in candidates)
            {
                var b = await Task.Run(() => Core.Services.PatchCustomizationSupport
                    .GetBytesFromArchiveExactPath(updateRpf, MinimapFontContainerPath + cand));
                if (b is { Length: > 1000 }) { foundSlot = cand; origBytes = b; break; }
            }
            if (foundSlot is null || origBytes is null)
            {
                var msg = targetSlot is not null
                    ? $"Слот {targetSlot} не найден в scaleform_platform_pc.rpf."
                    : "Ни один слот font_lib_*.gfx не найден в scaleform_platform_pc.rpf.";
                EmitInstallProgress(progressKey, prettyName, "error", 0, msg);
                return new InjectResultDto(false, msg, null);
            }

            Directory.CreateDirectory(MinimapFontBackupDir);
            var backupPath = Path.Combine(MinimapFontBackupDir, foundSlot);
            if (!File.Exists(backupPath))
                await File.WriteAllBytesAsync(backupPath, origBytes);

            EmitInstallProgress(progressKey, prettyName, "injecting", 30, null,
                detailMessage: Loc.T("progress.font.installingToSlot", ("slot", foundSlot)));

            bool ok = await Task.Run(() => Core.Services.PatchCustomizationSupport
                .ReplaceFileInLiveArchive(updateRpf, MinimapFontContainerPath + foundSlot, bytes));

            var check = await Task.Run(() => Core.Services.PatchCustomizationSupport
                .GetBytesFromArchiveExactPath(updateRpf, MinimapFontContainerPath + foundSlot));
            if (check is null || check.Length != bytes.Length)
            {
                const string msg = "Шрифт не записался в архив (проверка обратным чтением).";
                EmitInstallProgress(progressKey, prettyName, "error", 0, msg);
                return new InjectResultDto(false, msg, null);
            }

            Directory.CreateDirectory(MinimapFontConfigDir);
            await File.WriteAllTextAsync(MinimapFontStatePath, System.Text.Json.JsonSerializer.Serialize(
                new MinimapFontState { Slot = foundSlot, SourceFile = srcName }));

            var doneMsg = ok
                ? Loc.T("progress.font.installed", ("slot", foundSlot))
                : Loc.T("progress.font.writtenUnconfirmed", ("slot", foundSlot));
            EmitInstallProgress(progressKey, prettyName, "done", 100, null, detailMessage: doneMsg);
            return new InjectResultDto(true, null, updateRpf);
        }
        catch (Exception ex)
        {
            var msg = $"Шрифт миникарты: {ex.Message}";
            EmitInstallProgress(progressKey, prettyName, "error", 0, msg);
            return new InjectResultDto(false, msg, null);
        }
    }

    public async Task<InjectResultDto> MinimapRestoreFontAsync()
    {
        using var _mtx = await MiamiGraphics.Shell.Services.UpdateRpfMutex.AcquireAsync("minimap-font");
        return await RestoreMinimapFontCoreAsync();
    }

    private async Task<InjectResultDto> RestoreMinimapFontCoreAsync()
    {
        const string progressKey = "minimap-font";
        const string prettyName  = "Миникарта: шрифт";
        try
        {
            MinimapFontState? st = null;
            try
            {
                if (File.Exists(MinimapFontStatePath))
                    st = System.Text.Json.JsonSerializer.Deserialize<MinimapFontState>(
                        File.ReadAllText(MinimapFontStatePath));
            }
            catch { }
            if (st?.Slot is null)
                return new InjectResultDto(true, null, null);

            var backupPath = Path.Combine(MinimapFontBackupDir, st.Slot);
            if (!File.Exists(backupPath))
                return new InjectResultDto(false, $"Бэкап стокового шрифта не найден ({st.Slot}).", null);

            var gtaRoot = await GetGtaPathAsync();
            if (string.IsNullOrWhiteSpace(gtaRoot))
                return new InjectResultDto(false, "GTA не найдена.", null);
            var updateRpf = Path.Combine(gtaRoot, "update", "update.rpf");

            EmitInstallProgress(progressKey, prettyName, "injecting", 30, null,
                detailMessage: Loc.T("progress.font.restoringStock"));

            var orig = await File.ReadAllBytesAsync(backupPath);
            await Task.Run(() => Core.Services.PatchCustomizationSupport
                .ReplaceFileInLiveArchive(updateRpf, MinimapFontContainerPath + st.Slot, orig));

            try { File.Delete(MinimapFontStatePath); } catch { }
            EmitInstallProgress(progressKey, prettyName, "done", 100, null,
                detailMessage: Loc.T("progress.font.stockRestored"));
            return new InjectResultDto(true, null, updateRpf);
        }
        catch (Exception ex)
        {
            var msg = $"Возврат шрифта: {ex.Message}";
            EmitInstallProgress(progressKey, prettyName, "error", 0, msg);
            return new InjectResultDto(false, msg, null);
        }
    }

    public async Task<bool> MinimapDetectRingsAsync()
    {
        try
        {
            var gtaRoot = await GetGtaPathAsync();
            if (string.IsNullOrWhiteSpace(gtaRoot)) return false;
            using var _mtx = await MiamiGraphics.Shell.Services.UpdateRpfMutex.TryAcquireAsync(
                "minimap-detect-rings", TimeSpan.FromSeconds(2));
            if (_mtx is null)
            {
                var saved = await MinimapGetRangeRingsAsync();
                return saved.Length > 0;
            }
            await _detectOverlaysGate.WaitAsync();
            try
            {
                var usedPath = await Task.Run(() => ResolveLiveMinimapGfxPath(gtaRoot));
                if (usedPath is null) return false;
                var cur = await Task.Run(() => Core.Services.PatchCustomizationSupport.GetCleanBytesForExactPath(gtaRoot, usedPath));
                if (cur is null) return false;
                return await Task.Run(() => Core.Services.MinimapRangeRingsService.Detect(cur));
            }
            finally { _detectOverlaysGate.Release(); }
        }
        catch { return false; }
    }

    public async Task<InjectResultDto> MinimapSetRangeRingsAsync(int[] radiiMeters)
    {
        using var _mtx = await MiamiGraphics.Shell.Services.UpdateRpfMutex.AcquireAsync("minimap-rangerings");
        radiiMeters ??= Array.Empty<int>();
        const string progressKey = "minimap-rangerings";
        bool adding = radiiMeters.Length > 0;
        string pretty = adding
            ? "Добавление кругов на миникарту"
            : "Удаление кругов с миникарты";
        EmitInstallProgress(progressKey, pretty, "starting", 5, null,
            detailMessage: adding ? Loc.T("progress.minimap.addingCircles") : Loc.T("progress.minimap.removingCircles"));

        var gtaRoot = await GetGtaPathAsync();
        if (string.IsNullOrWhiteSpace(gtaRoot))
        {
            EmitInstallProgress(progressKey, pretty, "error", 0, "GTA не найдена.");
            return new InjectResultDto(false, "GTA не найдена. Укажи путь в Настройках → Папка GTA.", null);
        }
        var updateRpf = Path.Combine(gtaRoot, "update", "update.rpf");
        if (!File.Exists(updateRpf))
        {
            EmitInstallProgress(progressKey, pretty, "error", 0, "update.rpf не найден.");
            return new InjectResultDto(false, $"Не найден {updateRpf}.", null);
        }

        var tmp = Path.Combine(Path.GetTempPath(), "mmrings_" + Guid.NewGuid().ToString("N") + ".gfx");
        try
        {
            string? resolveFail = null;
            string? usedPath = await Task.Run(() => ResolveLiveMinimapGfxPath(gtaRoot, out resolveFail));
            byte[]? cur = null;
            if (usedPath is not null)
            {
                for (int attempt = 0; attempt < 3 && cur is null; attempt++)
                {
                    if (attempt > 0) await Task.Delay(350);
                    cur = await Task.Run(() =>
                        Core.Services.PatchCustomizationSupport.GetCleanBytesForExactPath(gtaRoot, usedPath));
                }
            }
            if (cur is null || usedPath is null)
            {
                var msg = resolveFail
                    ?? "Не удалось прочитать minimap.gfx из update.rpf. Закрой GTA и попробуй ещё раз.";
                EmitInstallProgress(progressKey, pretty, "error", 0, msg);
                return new InjectResultDto(false, msg, null);
            }

            await File.WriteAllBytesAsync(tmp, cur);
            EmitInstallProgress(progressKey, pretty, "injecting", 55, null, detailMessage: Loc.T("progress.minimap.editing"));
            bool ok = await Task.Run(() => Core.Services.MinimapRangeRingsService.Apply(tmp, radiiMeters));
            if (!ok)
            {
                EmitInstallProgress(progressKey, pretty, "error", 0, "Текущая миникарта не поддерживает круги.");
                return new InjectResultDto(false,
                    "Не удалось нанести круги на текущую миникарту (несовместимая структура/формат).", null);
            }

            var newBytes = await File.ReadAllBytesAsync(tmp);
            await Task.Run(() => Core.Services.PatchCustomizationSupport.ReplaceFileInLiveArchive(updateRpf, usedPath, newBytes));

            UpdateMinimapTweakBaseLiveSha(newBytes);

            try
            {
                var state = ReadInstallState();
                var prevDraft = state?.CustomizationDraft;
                var prevMm = prevDraft?.Minimap;
                var nextMm = prevMm is not null
                    ? prevMm with { RangeRingsMeters = radiiMeters }
                    : new MinimapSettingDto(true, "#34D399", "#60A5FA", "16:9", "default",
                        null, null, null, null, radiiMeters);
                var nextDraft = prevDraft is not null
                    ? prevDraft with { Minimap = nextMm }
                    : BuildDefaultDraft(state?.ReduxId ?? "vanilla", state?.VersionId) with { Minimap = nextMm };
                var postSha = await Task.Run(() => Services.FileShaCache.ComputeSha256Cached(updateRpf));
                WriteInstallState(new InstallState
                {
                    ReduxId = state?.ReduxId,
                    VersionId = state?.VersionId,
                    PostInstallSha256 = postSha,
                    InstalledAt = DateTime.UtcNow,
                    CustomizationDraft = nextDraft,
                    CurrentArmorId = state?.CurrentArmorId,
                    CurrentArmorName = state?.CurrentArmorName,
                    CurrentArmorGlbUrl = state?.CurrentArmorGlbUrl,
                    CurrentArmorKind = state?.CurrentArmorKind,
                });
            }
            catch (Exception ex) { Debug.WriteLine($"[minimap.rings] state persist failed (non-fatal): {ex.Message}"); }

            EmitInstallProgress(progressKey, pretty, "done", 100, null,
                detailMessage: adding ? Loc.T("progress.minimap.circlesAdded") : Loc.T("progress.minimap.circlesRemoved"));
            return new InjectResultDto(true, null, null);
        }
        catch (Exception ex)
        {
            EmitInstallProgress(progressKey, pretty, "error", 0, ex.Message);
            return new InjectResultDto(false, $"Ошибка: {ex.Message}", null);
        }
        finally { try { if (File.Exists(tmp)) File.Delete(tmp); } catch { } }
    }

    public async Task<InjectResultDto> MinimapRestoreVanillaAsync()
    {
        using var _mtx = await MiamiGraphics.Shell.Services.UpdateRpfMutex.AcquireAsync("minimap-restore-vanilla");
        const string progressKey = "minimap-restore-vanilla";
        const string pretty = "Возврат ванильной миникарты";
        EmitInstallProgress(progressKey, pretty, "starting", 5, null, detailMessage: Loc.T("progress.minimap.restoring"));

        var gtaRoot = await GetGtaPathAsync();
        if (string.IsNullOrWhiteSpace(gtaRoot))
        {
            EmitInstallProgress(progressKey, pretty, "error", 0, "GTA не найдена.");
            return new InjectResultDto(false, "GTA не найдена. Укажи путь в Настройках → Папка GTA.", null);
        }
        var updateRpf = Path.Combine(gtaRoot, "update", "update.rpf");
        if (!File.Exists(updateRpf))
        {
            EmitInstallProgress(progressKey, pretty, "error", 0, "update.rpf не найден.");
            return new InjectResultDto(false, $"Не найден {updateRpf}.", null);
        }

        var cleanRpf = _backupService.GetCleanUpdateRpfPath();
        if (string.IsNullOrWhiteSpace(cleanRpf))
        {
            EmitInstallProgress(progressKey, pretty, "error", 0, "Нет чистой копии update.rpf.");
            return new InjectResultDto(false, "Нет чистой копии update.rpf. Сделай Backup, чтобы вернуть ванильную миникарту.", null);
        }

        var canonical = new[]
        {
            "x64/patch/data/cdimages/scaleform_minimap.rpf/minimap.gfx",
            "x64/data/cdimages/scaleform_minimap.rpf/minimap.gfx",
        };

        var scan = await Task.Run(() =>
        {
            try
            {
                var found = Core.Services.PatchCustomizationSupport
                    .FindInternalPathsByNameDeep(gtaRoot!, "minimap.gfx", out var openErr);
                return (Paths: found, Error: openErr);
            }
            catch (Exception ex) { return (Paths: new List<string>(), Error: (Exception?)ex); }
        });
        var targets = scan.Paths ?? new List<string>();
        var scanErr = scan.Error;

        if (scanErr is not null)
        {
            var msg = "Не удалось открыть update.rpf (" + scanErr.Message + "). Закрой GTA и попробуй ещё раз.";
            EmitInstallProgress(progressKey, pretty, "error", 0, msg);
            return new InjectResultDto(false, msg, null);
        }
        foreach (var c in canonical)
            if (!targets.Contains(c, StringComparer.OrdinalIgnoreCase)) targets.Add(c);

        var rollbackPath = updateRpf + ".restore_rollback";
        try
        {
            EmitInstallProgress(progressKey, pretty, "injecting", 20, null, detailMessage: Loc.T("progress.minimap.restoring"));

            byte[]? vanillaGfx = null;
            foreach (var c in canonical)
            {
                vanillaGfx = await Task.Run(() => Core.Services.PatchCustomizationSupport.GetBytesFromArchiveExactPath(cleanRpf!, c));
                if (vanillaGfx is not null) break;
            }
            if (vanillaGfx is null)
            {
                EmitInstallProgress(progressKey, pretty, "error", 0, "minimap.gfx не найден в чистой копии.");
                return new InjectResultDto(false, "Не нашёл minimap.gfx в чистой копии update.rpf.", null);
            }

            await MakeRollbackPointAsync(updateRpf, rollbackPath, progressKey, pretty,
                "injecting", new ProgressBand(30, 45), "minimap.restore");

            EmitInstallProgress(progressKey, pretty, "injecting", 55, null, detailMessage: Loc.T("progress.minimap.restoring"));
            bool restoredAny = false, checksumOk = true;
            var failedPaths = new List<string>();
            foreach (var p in targets)
            {
                try
                {
                    var ok = await Task.Run(() =>
                        Core.Services.PatchCustomizationSupport.ReplaceFileInLiveArchive(updateRpf, p, vanillaGfx));
                    if (!ok) checksumOk = false;
                    restoredAny = true;
                }
                catch (Exception ex)
                {
                    failedPaths.Add(p);
                    Debug.WriteLine($"[minimap.restore] {p}: {ex.GetType().Name}: {ex.Message}");
                }
            }
            if (!restoredAny)
            {
                try { if (File.Exists(rollbackPath)) File.Delete(rollbackPath); } catch { }
                EmitInstallProgress(progressKey, pretty, "error", 0, "Ни одна копия миникарты не заменилась.");
                return new InjectResultDto(false,
                    "Не удалось вернуть ванильную миникарту: ни одна копия не заменилась. Закрой GTA и попробуй ещё раз.", null);
            }

            if (failedPaths.Count > 0)
            {
                var live = ResolveLiveMinimapGfxPath(gtaRoot!);
                bool liveMissed = live is not null
                    && failedPaths.Contains(live, StringComparer.OrdinalIgnoreCase);
                var listed = string.Join(", ", failedPaths);
                if (liveMissed)
                {
                    try { if (File.Exists(rollbackPath)) File.Delete(rollbackPath); } catch { }
                    var msg = $"Миникарта сборки осталась в игре: не удалось заменить {live}. " +
                              "Закрой GTA и попробуй ещё раз, а если не поможет - переустанови сборку.";
                    EmitInstallProgress(progressKey, pretty, "error", 0, msg);
                    return new InjectResultDto(false, msg, null);
                }
                Debug.WriteLine($"[minimap.restore] пропущены копии (игра их не грузит): {listed}");
            }

            if (!checksumOk)
            {
                bool restored = false;
                try
                {
                    if (File.Exists(rollbackPath)) { File.Copy(rollbackPath, updateRpf, overwrite: true); restored = true; }
                }
                catch { }
                try { if (File.Exists(rollbackPath)) File.Delete(rollbackPath); } catch { }
                var fixMsg = "Откат миникарты не выполнен: не удалось перешифровать update.rpf (ArchiveFix). " +
                             (restored ? "Изменения откатились."
                                       : "ВНИМАНИЕ: откат не удался - восстанови чистый update.rpf через настройки лаунчера перед игрой.");
                EmitInstallProgress(progressKey, pretty, "error", 0, fixMsg);
                return new InjectResultDto(false, fixMsg, null);
            }

            try { if (File.Exists(rollbackPath)) File.Delete(rollbackPath); } catch { }

            ClearMinimapTweakBase();

            try
            {
                var state = ReadInstallState();
                var prevDraft = state?.CustomizationDraft;
                var prevMm = prevDraft?.Minimap;
                if (prevDraft is not null && prevMm is not null)
                {
                    var nextMm = prevMm with
                    {
                        LibraryItemId = null, ImportedFromReduxId = null,
                        RangeRingsMeters = null, Tweaks = null,
                        Enabled = false, HpColor = "#34D399", ArmorColor = "#60A5FA",
                        PngOverlayPath = null, DonorVersionId = null,
                    };
                    var nextDraft = prevDraft with { Minimap = nextMm };
                    var postSha = await Task.Run(() => Services.FileShaCache.ComputeSha256Cached(updateRpf));
                    WriteInstallState(new InstallState
                    {
                        ReduxId = state?.ReduxId,
                        VersionId = state?.VersionId,
                        PostInstallSha256 = postSha,
                        InstalledAt = DateTime.UtcNow,
                        CustomizationDraft = nextDraft,
                        CurrentArmorId = state?.CurrentArmorId,
                        CurrentArmorName = state?.CurrentArmorName,
                        CurrentArmorGlbUrl = state?.CurrentArmorGlbUrl,
                        CurrentArmorKind = state?.CurrentArmorKind,
                    });
                }
            }
            catch (Exception ex) { Debug.WriteLine($"[minimap.restore] state persist failed (non-fatal): {ex.Message}"); }

            EmitInstallProgress(progressKey, pretty, "done", 100, null, detailMessage: Loc.T("progress.minimap.vanillaRestored"));
            return new InjectResultDto(true, null, null);
        }
        catch (Exception ex)
        {
            try { if (File.Exists(rollbackPath)) File.Delete(rollbackPath); } catch { }
            EmitInstallProgress(progressKey, pretty, "error", 0, ex.Message);
            return new InjectResultDto(false, $"Ошибка: {ex.Message}", null);
        }
    }

    private static byte[] ReadZalazyBytes(Core.Services.ZalazyService.Variant variant)
    {
        var root = ResolveAdditionalsRoot()
            ?? throw new InvalidOperationException(Loc.T("errors.additionals.rootMissing"));
        var p = Path.Combine(root, "zalazy", variant.FileName);
        if (!File.Exists(p))
            throw new FileNotFoundException(Loc.T("errors.additionals.zalazyMissing", ("file", variant.FileName)), p);
        return File.ReadAllBytes(p);
    }

    public async Task<InjectResultDto> OtherSetZalazyAsync(bool enabled, string server)
    {
        using var _mtx = await MiamiGraphics.Shell.Services.UpdateRpfMutex.AcquireAsync("other-zalazy");
        const string progressKey = "other-zalazy";
        var variant = Core.Services.ZalazyService.ByServer(server);
        string pretty = enabled ? "Добавление залазов" : "Удаление залазов";
        EmitInstallProgress(progressKey, pretty, "starting", 5, null,
            detailMessage: enabled ? Loc.T("progress.climb.preparing") : Loc.T("progress.climb.removing"));

        var gtaRoot = await GetGtaPathAsync();
        if (string.IsNullOrWhiteSpace(gtaRoot))
        {
            EmitInstallProgress(progressKey, pretty, "error", 0, "GTA не найдена.");
            return new InjectResultDto(false, "GTA не найдена. Укажи путь в Настройках → Папка GTA.", null);
        }
        var updateRpf = Path.Combine(gtaRoot, "update", "update.rpf");
        if (!File.Exists(updateRpf))
        {
            EmitInstallProgress(progressKey, pretty, "error", 0, "update.rpf не найден.");
            return new InjectResultDto(false, $"Не найден {updateRpf}.", null);
        }

        var rollbackPath = updateRpf + ".preinstall";
        try
        {
            await MakeRollbackPointAsync(updateRpf, rollbackPath, progressKey, pretty,
                "starting", new ProgressBand(5, 20), "other.zalazy");

            byte[]? bytes = enabled ? await Task.Run(() => ReadZalazyBytes(variant)) : null;
            EmitInstallProgress(progressKey, pretty, "injecting", 45, null,
                detailMessage: enabled ? Loc.T("progress.common.registeringInGame") : Loc.T("progress.common.unregistering"));

            bool checksumOk = await Task.Run(() =>
            {
                if (enabled) Core.Services.ZalazyService.Apply(updateRpf, variant, bytes!);
                else         Core.Services.ZalazyService.Remove(updateRpf);
                EmitInstallProgress(progressKey, pretty, "injecting", 75, null, detailMessage: Loc.T("install.reencryptingUpdateRpf"));
                return Core.Services.PatchCustomizationSupport.FixLiveArchiveChecksums(updateRpf, Array.Empty<string>());
            });

            if (!checksumOk)
            {
                bool restored = false;
                try { if (File.Exists(rollbackPath)) { File.Copy(rollbackPath, updateRpf, overwrite: true); restored = true; } } catch { }
                try { if (File.Exists(rollbackPath)) File.Delete(rollbackPath); } catch { }
                var fixMsg = "Залазы не применены: не удалось перешифровать update.rpf (ArchiveFix). " +
                             "Проверь, что антивирус не удалил файлы лаунчера, и переустанови лаунчер. " +
                             (restored ? "Изменения откатились." : "ВНИМАНИЕ: откат не удался - восстанови чистый update.rpf через настройки.");
                EmitInstallProgress(progressKey, pretty, "error", 0, fixMsg);
                return new InjectResultDto(false, fixMsg, null);
            }

            try
            {
                var state = ReadInstallState();
                var prevDraft = state?.CustomizationDraft;
                var nextDraft = (prevDraft ?? BuildDefaultDraft(state?.ReduxId ?? "vanilla", state?.VersionId))
                    with { ZalazyEnabled = enabled, ZalazyServer = variant.Server };
                var postSha = await Task.Run(() => Services.FileShaCache.ComputeSha256Cached(updateRpf));
                WriteInstallState(new InstallState
                {
                    ReduxId = state?.ReduxId,
                    VersionId = state?.VersionId,
                    PostInstallSha256 = postSha,
                    InstalledAt = DateTime.UtcNow,
                    CustomizationDraft = nextDraft,
                    CurrentArmorId = state?.CurrentArmorId,
                    CurrentArmorName = state?.CurrentArmorName,
                    CurrentArmorGlbUrl = state?.CurrentArmorGlbUrl,
                    CurrentArmorKind = state?.CurrentArmorKind,
                });
            }
            catch (Exception ex) { Debug.WriteLine($"[other.zalazy] state persist failed (non-fatal): {ex.Message}"); }

            try { if (File.Exists(rollbackPath)) File.Delete(rollbackPath); } catch { }

            EmitInstallProgress(progressKey, pretty, "done", 100, null,
                detailMessage: enabled ? Loc.T("progress.climb.added") : Loc.T("progress.climb.removed"));
            return new InjectResultDto(true, null, null);
        }
        catch (Exception ex)
        {
            try { if (File.Exists(rollbackPath)) { File.Copy(rollbackPath, updateRpf, overwrite: true); File.Delete(rollbackPath); } } catch { }
            EmitInstallProgress(progressKey, pretty, "error", 0, ex.Message);
            return new InjectResultDto(false, $"Ошибка: {ex.Message}", null);
        }
    }

    public Task<ZalazyStateDto> OtherGetZalazyAsync() => Task.Run(async () =>
    {
        var draft = ReadInstallState()?.CustomizationDraft;
        bool enabled = draft?.ZalazyEnabled ?? false;
        var server = string.IsNullOrWhiteSpace(draft?.ZalazyServer) ? "gta5rp" : draft!.ZalazyServer;
        if (enabled) return new ZalazyStateDto(true, server);

        try
        {
            var gtaRoot = await GetGtaPathAsync();
            if (string.IsNullOrWhiteSpace(gtaRoot)) return new ZalazyStateDto(false, server);
            var updateRpf = Path.Combine(gtaRoot, "update", "update.rpf");
            if (!File.Exists(updateRpf)) return new ZalazyStateDto(false, server);

            string? appliedServer;
            await _detectOverlaysGate.WaitAsync();
            try
            {
                appliedServer = await Task.Run(() => Core.Services.ZalazyService.AppliedServer(updateRpf));
                if (appliedServer is null)
                {
                    await Task.Delay(400);
                    appliedServer = await Task.Run(() => Core.Services.ZalazyService.AppliedServer(updateRpf));
                }
            }
            finally { _detectOverlaysGate.Release(); }
            if (appliedServer is null) return new ZalazyStateDto(false, server);

            try
            {
                var state = ReadInstallState();
                var prevDraft = state?.CustomizationDraft;
                var nextDraft = (prevDraft ?? BuildDefaultDraft(state?.ReduxId ?? "vanilla", state?.VersionId))
                    with { ZalazyEnabled = true, ZalazyServer = appliedServer };
                WriteInstallState(new InstallState
                {
                    ReduxId = state?.ReduxId,
                    VersionId = state?.VersionId,
                    PostInstallSha256 = state?.PostInstallSha256,
                    InstalledAt = state?.InstalledAt ?? DateTime.UtcNow,
                    CustomizationDraft = nextDraft,
                    CurrentArmorId = state?.CurrentArmorId,
                    CurrentArmorName = state?.CurrentArmorName,
                    CurrentArmorGlbUrl = state?.CurrentArmorGlbUrl,
                    CurrentArmorKind = state?.CurrentArmorKind,
                });
            }
            catch (Exception ex) { Debug.WriteLine($"[other.zalazy] detect-heal persist failed (non-fatal): {ex.Message}"); }

            Debug.WriteLine($"[other.zalazy] disk-detected server={appliedServer} - journal healed");
            return new ZalazyStateDto(true, appliedServer);
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[other.zalazy] disk detect failed: {ex.Message}");
            return new ZalazyStateDto(false, server);
        }
