    private static readonly System.Threading.SemaphoreSlim _detectOverlaysGate = new(1, 1);

    public async Task<OverlayDetectDto> OtherDetectOverlaysAsync()
    {
        await _detectOverlaysGate.WaitAsync();
        try
        {
            return await DetectOverlaysCoreAsync();
        }
        finally { _detectOverlaysGate.Release(); }
    }

    private async Task<OverlayDetectDto> DetectOverlaysCoreAsync()
    {
        try
        {
            var gtaRoot = await GetGtaPathAsync();
            if (string.IsNullOrWhiteSpace(gtaRoot))
            {
                Debug.WriteLine("[other.detect] GTA path empty - skip");
                return new OverlayDetectDto(false, false);
            }
            var updateRpf = Path.Combine(gtaRoot, "update", "update.rpf");
            if (!File.Exists(updateRpf))
            {
                Debug.WriteLine($"[other.detect] update.rpf not found at {updateRpf}");
                return new OverlayDetectDto(false, false);
            }
            var res = await Task.Run(() => Core.Services.OverlayModDetector.Detect(updateRpf));
            Services.SessionLog.Info("other-detect",
                $"{updateRpf}: zalazy={res.ForeignZalazy} green={res.ForeignGreenZone} backpack={res.ForeignBackpack} " +
                $"zpaths=[{string.Join(",", res.ZalazyPaths)}] gpaths=[{string.Join(",", res.GreenZonePaths)}] " +
                $"bpaths=[{string.Join(",", res.BackpackPaths)}]");
            return new OverlayDetectDto(res.ForeignZalazy, res.ForeignGreenZone, res.ForeignBackpack);
        }
        catch (Exception ex)
        {
            Services.SessionLog.Error("other-detect", "detect failed", ex);
            return new OverlayDetectDto(false, false);
        }
    }

    public async Task<InjectResultDto> OtherRemoveForeignOverlayAsync(string kind)
    {
        using var _mtx = await MiamiGraphics.Shell.Services.UpdateRpfMutex.AcquireAsync("other-foreign-overlay");
        var overlayKind = kind?.ToLowerInvariant() switch
        {
            "greenzone" => Core.Services.OverlayModDetector.Kind.GreenZone,
            "backpack"  => Core.Services.OverlayModDetector.Kind.Backpack,
            _           => Core.Services.OverlayModDetector.Kind.Zalazy,
        };
        const string progressKey = "other-foreign-overlay";
        string pretty = overlayKind switch
        {
            Core.Services.OverlayModDetector.Kind.GreenZone => "Удаление чужих зелёных зон",
            Core.Services.OverlayModDetector.Kind.Backpack  => "Удаление чужого мода на рюкзаки",
            _                                              => "Удаление чужих залазов",
        };
        EmitInstallProgress(progressKey, pretty, "starting", 5, null, detailMessage: Loc.T("progress.strip.searching"));

        var gtaRoot = await GetGtaPathAsync();
        if (string.IsNullOrWhiteSpace(gtaRoot))
        {
            EmitInstallProgress(progressKey, pretty, "error", 0, "GTA не найдена.");
            return new InjectResultDto(false, "GTA не найдена. Укажи путь в Настройках → Папка GTA.", null);
        }
        var updateRpf = Path.Combine(gtaRoot, "update", "update.rpf");
        if (!File.Exists(updateRpf))
        {
            EmitInstallProgress(progressKey, pretty, "error", 0, "update.rpf не найден.");
            return new InjectResultDto(false, $"Не найден {updateRpf}.", null);
        }

        var rollbackPath = updateRpf + ".preinstall";
        try
        {
            await MakeRollbackPointAsync(updateRpf, rollbackPath, progressKey, pretty,
                "starting", new ProgressBand(5, 20), "other.foreign");

            EmitInstallProgress(progressKey, pretty, "injecting", 40, null, detailMessage: Loc.T("progress.strip.cutting"));
            var (result, checksumOk) = await Task.Run(() =>
            {
                var r = Core.Services.OverlayModDetector.RemoveForeign(updateRpf, overlayKind);
                if (r.FilesStripped == 0 && r.RpfsDropped == 0)
                    return (r, true);
                EmitInstallProgress(progressKey, pretty, "injecting", 75, null, detailMessage: Loc.T("install.reencryptingUpdateRpf"));
                var nested = r.EditedRpfNames?.ToArray() ?? Array.Empty<string>();
                bool ok = Core.Services.PatchCustomizationSupport.FixLiveArchiveChecksums(updateRpf, nested);
                return (r, ok);
            });

            if (!checksumOk)
            {
                bool restored = false;
                try { if (File.Exists(rollbackPath)) { File.Copy(rollbackPath, updateRpf, overwrite: true); restored = true; } } catch { }
                try { if (File.Exists(rollbackPath)) File.Delete(rollbackPath); } catch { }
                var fixMsg = "Не удалось перешифровать update.rpf (ArchiveFix). " +
                             (restored ? "Изменения откатились." : "ВНИМАНИЕ: откат не удался - восстанови чистый update.rpf через настройки.");
                EmitInstallProgress(progressKey, pretty, "error", 0, fixMsg);
                return new InjectResultDto(false, fixMsg, null);
            }

            try { if (File.Exists(rollbackPath)) File.Delete(rollbackPath); } catch { }

            if (result.FilesStripped == 0 && result.RpfsDropped == 0)
            {
                EmitInstallProgress(progressKey, pretty, "done", 100, null, detailMessage: Loc.T("progress.strip.nothingFound"));
                return new InjectResultDto(true, null, null);
            }

            EmitInstallProgress(progressKey, pretty, "done", 100, null,
                detailMessage: Loc.T("progress.strip.removedCount", ("count", result.FilesStripped)));
            return new InjectResultDto(true, null, null);
        }
        catch (Exception ex)
        {
            try { if (File.Exists(rollbackPath)) { File.Copy(rollbackPath, updateRpf, overwrite: true); File.Delete(rollbackPath); } } catch { }
            EmitInstallProgress(progressKey, pretty, "error", 0, ex.Message);
            return new InjectResultDto(false, $"Ошибка: {ex.Message}", null);
        }
    }

