    public Task<bool> OtherGetFastJoinAsync()
        => OtherGetFastJoinStatusAsync().ContinueWith(t => t.Result.Active);

    public Task<FastJoinStatusDto> OtherGetFastJoinStatusAsync() => Task.Run(async () =>
    {
        bool userInstalled = ReadInstallState()?.CustomizationDraft?.FastJoinUserInstalled ?? false;
        if (userInstalled) return new FastJoinStatusDto(true, true);

        try
        {
            var gtaRoot = await GetGtaPathAsync();
            if (string.IsNullOrWhiteSpace(gtaRoot)) return new FastJoinStatusDto(false, false);
            var updateRpf = Path.Combine(gtaRoot, "update", "update.rpf");
            if (!File.Exists(updateRpf)) return new FastJoinStatusDto(false, false);

            byte[]? live;
            await _detectOverlaysGate.WaitAsync();
            try
            {
                live = Core.Services.PatchCustomizationSupport.GetBytesFromArchiveExactPath(
                    updateRpf, Core.Services.PlayerSwitchService.InternalPath);
                if (live is null)
                {
                    await Task.Delay(400);
                    live = Core.Services.PatchCustomizationSupport.GetBytesFromArchiveExactPath(
                        updateRpf, Core.Services.PlayerSwitchService.InternalPath);
                }
            }
            finally { _detectOverlaysGate.Release(); }
            if (live is null) return new FastJoinStatusDto(false, false);

            bool isOurs = false;
            try { isOurs = live.AsSpan().SequenceEqual(ReadFastJoinMetaBytes()); } catch { }

            bool differsFromVanilla = false;
            if (!isOurs)
            {
                var cleanRpf = _backupService.GetCleanUpdateRpfPath();
                if (cleanRpf is not null)
                {
                    var vanilla = Core.Services.PatchCustomizationSupport.GetBytesFromArchiveExactPath(
                        cleanRpf, Core.Services.PlayerSwitchService.InternalPath);
                    differsFromVanilla = vanilla is not null && !live.AsSpan().SequenceEqual(vanilla);
                }
            }

            bool active = isOurs || differsFromVanilla;
            if (active)
                Debug.WriteLine($"[other.fastjoin] disk-detected (ours={isOurs} foreignDiff={differsFromVanilla}) - redux-bundled, NOT a user install");
            return new FastJoinStatusDto(active, false);
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[other.fastjoin] disk detect failed: {ex.Message}");
            return new FastJoinStatusDto(false, false);
        }
    });

