    private const string R2CarLogos = "environment/misc/carlogos/miami_cars.rpf";

    private async Task<byte[]> ReadCarLogosBytesAsync()
    {
        var name = Core.Services.CarLogosService.FileName;
        var root = ResolveAdditionalsRoot();
        if (root != null)
        {
            var p = Path.Combine(root, "carlogos", name);
            if (File.Exists(p)) return File.ReadAllBytes(p);
        }
        var bytes = await GfxDownloadAsync(R2CarLogos);
        if (bytes == null || bytes.Length == 0)
            throw new FileNotFoundException(Loc.T("errors.additionals.carlogosMissing", ("file", name)));
        try
        {
            if (root != null)
            {
                var dir = Path.Combine(root, "carlogos");
                Directory.CreateDirectory(dir);
                File.WriteAllBytes(Path.Combine(dir, name), bytes);
            }
        }
        catch (Exception ex) { Debug.WriteLine($"[other.carlogos] cache to additionals failed (non-fatal): {ex.Message}"); }
        return bytes;
    }

    private IReadOnlyList<string> CarLogosSignature()
    {
        try
        {
            var root = ResolveAdditionalsRoot();
            if (root != null)
            {
                var p = Path.Combine(root, "carlogos", Core.Services.CarLogosService.FileName);
                if (File.Exists(p))
                {
                    var names = Core.Services.CarLogosService.SignatureFromPack(File.ReadAllBytes(p));
                    if (names.Count > 0) return names;
                }
            }
        }
        catch (Exception ex) { Debug.WriteLine($"[other.carlogos] signature from pack failed: {ex.Message}"); }
        return Core.Services.CarLogosService.DefaultSignature;
    }

    public async Task<InjectResultDto> OtherSetCarLogosAsync(bool enabled)
    {
        using var _mtx = await MiamiGraphics.Shell.Services.UpdateRpfMutex.AcquireAsync("other-carlogos");
        const string progressKey = "other-carlogos";
        string pretty = enabled ? "Добавление логотипов авто" : "Удаление логотипов авто";
        EmitInstallProgress(progressKey, pretty, "starting", 5, null,
            detailMessage: enabled ? Loc.T("progress.carlogos.preparing") : Loc.T("progress.carlogos.removing"));

        var gtaRoot = await GetGtaPathAsync();
        if (string.IsNullOrWhiteSpace(gtaRoot))
        {
            EmitInstallProgress(progressKey, pretty, "error", 0, "GTA не найдена.");
            return new InjectResultDto(false, "GTA не найдена. Укажи путь в Настройках → Папка GTA.", null);
        }
        var updateRpf = Path.Combine(gtaRoot, "update", "update.rpf");
        if (!File.Exists(updateRpf))
        {
            EmitInstallProgress(progressKey, pretty, "error", 0, "update.rpf не найден.");
            return new InjectResultDto(false, $"Не найден {updateRpf}.", null);
        }

        var rollbackPath = updateRpf + ".preinstall";
        try
        {
            await MakeRollbackPointAsync(updateRpf, rollbackPath, progressKey, pretty,
                "starting", new ProgressBand(5, 20), "other.carlogos");

            byte[]? bytes = enabled ? await ReadCarLogosBytesAsync() : null;
            EmitInstallProgress(progressKey, pretty, "injecting", 45, null,
                detailMessage: enabled ? Loc.T("progress.common.registeringInGame") : Loc.T("progress.common.unregistering"));

            bool checksumOk = await Task.Run(() =>
            {
                if (enabled) Core.Services.CarLogosService.Apply(updateRpf, bytes!);
                else         Core.Services.CarLogosService.Remove(updateRpf);
                EmitInstallProgress(progressKey, pretty, "injecting", 75, null, detailMessage: Loc.T("install.reencryptingUpdateRpf"));
                return Core.Services.PatchCustomizationSupport.FixLiveArchiveChecksums(
                    updateRpf, Array.Empty<string>());
            });

            if (!checksumOk)
            {
                bool restored = false;
                try { if (File.Exists(rollbackPath)) { File.Copy(rollbackPath, updateRpf, overwrite: true); restored = true; } } catch { }
                try { if (File.Exists(rollbackPath)) File.Delete(rollbackPath); } catch { }
                var fixMsg = "Логотипы не применены: не удалось перешифровать update.rpf (ArchiveFix). " +
                             "Проверь, что антивирус не удалил файлы лаунчера, и переустанови лаунчер. " +
                             (restored ? "Изменения откатились." : "ВНИМАНИЕ: откат не удался - восстанови чистый update.rpf через настройки.");
                EmitInstallProgress(progressKey, pretty, "error", 0, fixMsg);
                return new InjectResultDto(false, fixMsg, null);
            }

            try
            {
                var state = ReadInstallState();
                var prevDraft = state?.CustomizationDraft;
                var nextDraft = (prevDraft ?? BuildDefaultDraft(state?.ReduxId ?? "vanilla", state?.VersionId))
                    with { CarLogosEnabled = enabled };
                var postSha = await Task.Run(() => Services.FileShaCache.ComputeSha256Cached(updateRpf));
                WriteInstallState(new InstallState
                {
                    ReduxId = state?.ReduxId,
                    VersionId = state?.VersionId,
                    PostInstallSha256 = postSha,
                    InstalledAt = DateTime.UtcNow,
                    CustomizationDraft = nextDraft,
                    CurrentArmorId = state?.CurrentArmorId,
                    CurrentArmorName = state?.CurrentArmorName,
                    CurrentArmorGlbUrl = state?.CurrentArmorGlbUrl,
                    CurrentArmorKind = state?.CurrentArmorKind,
                });
            }
            catch (Exception ex) { Debug.WriteLine($"[other.carlogos] state persist failed (non-fatal): {ex.Message}"); }

            try { if (File.Exists(rollbackPath)) File.Delete(rollbackPath); } catch { }

            EmitInstallProgress(progressKey, pretty, "done", 100, null,
                detailMessage: enabled ? Loc.T("progress.carlogos.added") : Loc.T("progress.carlogos.removed"));
            return new InjectResultDto(true, null, null);
        }
        catch (Exception ex)
        {
            try { if (File.Exists(rollbackPath)) { File.Copy(rollbackPath, updateRpf, overwrite: true); File.Delete(rollbackPath); } } catch { }
            EmitInstallProgress(progressKey, pretty, "error", 0, ex.Message);
            return new InjectResultDto(false, $"Ошибка: {ex.Message}", null);
        }
    }

    public Task<CarLogosStatusDto> OtherGetCarLogosAsync() => Task.Run(async () =>
    {
        bool journal = ReadInstallState()?.CustomizationDraft?.CarLogosEnabled ?? false;
        try
        {
            var gtaRoot = await GetGtaPathAsync();
            if (string.IsNullOrWhiteSpace(gtaRoot))
                return new CarLogosStatusDto(journal, false, Array.Empty<string>());
            var updateRpf = Path.Combine(gtaRoot, "update", "update.rpf");
            if (!File.Exists(updateRpf))
                return new CarLogosStatusDto(journal, false, Array.Empty<string>());

            var sig = CarLogosSignature();
            bool applied;
            Core.Services.CarLogosService.DetectResult foreign;
            await _detectOverlaysGate.WaitAsync();
            try
            {
                applied = await Task.Run(() => Core.Services.CarLogosService.IsApplied(updateRpf));
                if (!applied)
                {
                    await Task.Delay(400);
                    applied = await Task.Run(() => Core.Services.CarLogosService.IsApplied(updateRpf));
                }
                foreign = await Task.Run(() => Core.Services.CarLogosService.DetectExisting(updateRpf, sig));
            }
            finally { _detectOverlaysGate.Release(); }

            if (applied && !journal)
            {
                try
                {
                    var state = ReadInstallState();
                    var prevDraft = state?.CustomizationDraft;
                    var nextDraft = (prevDraft ?? BuildDefaultDraft(state?.ReduxId ?? "vanilla", state?.VersionId))
                        with { CarLogosEnabled = true };
                    WriteInstallState(new InstallState
                    {
                        ReduxId = state?.ReduxId,
                        VersionId = state?.VersionId,
                        PostInstallSha256 = state?.PostInstallSha256,
                        InstalledAt = state?.InstalledAt ?? DateTime.UtcNow,
                        CustomizationDraft = nextDraft,
                        CurrentArmorId = state?.CurrentArmorId,
                        CurrentArmorName = state?.CurrentArmorName,
                        CurrentArmorGlbUrl = state?.CurrentArmorGlbUrl,
                        CurrentArmorKind = state?.CurrentArmorKind,
                    });
                    Debug.WriteLine("[other.carlogos] disk-detected - journal healed");
                }
                catch (Exception ex) { Debug.WriteLine($"[other.carlogos] detect-heal persist failed (non-fatal): {ex.Message}"); }
            }

            if (foreign.Found)
                Debug.WriteLine($"[other.carlogos] foreign logo pack: paths=[{string.Join(",", foreign.Paths)}] hits=[{string.Join(",", foreign.Hits)}]");

            return new CarLogosStatusDto(applied || journal, foreign.Found, foreign.Hits);
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[other.carlogos] disk detect failed: {ex.Message}");
            return new CarLogosStatusDto(journal, false, Array.Empty<string>());
        }
    });

