    private const string R2Rukzak = "environment/misc/rukzak/miami_rukzak_v2.rpf";

    private async Task<byte[]> ReadRukzakBytesAsync()
    {
        var name = Core.Services.RukzakService.FileName;
        var root = ResolveAdditionalsRoot();
        if (root != null)
        {
            var p = Path.Combine(root, "rukzak", name);
            if (File.Exists(p)) return File.ReadAllBytes(p);
        }
        var bytes = await GfxDownloadAsync(R2Rukzak);
        if (bytes == null || bytes.Length == 0)
            throw new FileNotFoundException(Loc.T("errors.additionals.rukzakMissing", ("file", name)));
        try
        {
            if (root != null)
            {
                var dir = Path.Combine(root, "rukzak");
                Directory.CreateDirectory(dir);
                File.WriteAllBytes(Path.Combine(dir, name), bytes);
            }
        }
        catch (Exception ex) { Debug.WriteLine($"[other.rukzak] cache to additionals failed (non-fatal): {ex.Message}"); }
        return bytes;
    }

    private static string BackpackBackupPath() => Path.Combine(
        Core.System.AppDataRoot.BackupDir("rukzak"), "patchday11ng_dlc.rpf");

    private static string BackpackCachePath(string name) => Path.Combine(
        Core.System.AppDataRoot.Dir("rukzak"), name);

    private async Task<string> EnsureBackpackFileAsync(
        string r2Key, string expectSha, long expectSize, string cacheName,
        string progressKey, string pretty)
    {
        var path = BackpackCachePath(cacheName);
        if (File.Exists(path))
        {
            try
            {
                if (new FileInfo(path).Length == expectSize &&
                    (await Task.Run(() => Core.Services.BackpackDlcService.Sha256File(path)))
                        .Equals(expectSha, StringComparison.OrdinalIgnoreCase))
                    return path;
            }
            catch {}
            try { File.Delete(path); } catch { }
        }

        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        EmitInstallProgress(progressKey, pretty, "downloading", 10, null, detailMessage: Loc.T("progress.common.downloadingFile"));
        try
        {
            await DownloadViaMirrorAsync($"https://miamigraphicsstorage.uk/{r2Key}", path, (done, total) =>
            {
                int pct = total > 0 ? 10 + (int)(55.0 * done / total) : 15;
                EmitInstallProgress(progressKey, pretty, "downloading", pct, null,
                    detailMessage: total > 0
                        ? Loc.T("progress.common.downloadingFileMb", ("done", done / 1048576), ("total", total / 1048576))
                        : Loc.T("progress.common.downloadingFileMbOnly", ("done", done / 1048576)));
            });
        }
        catch (HttpRequestException ex) when (
            ex.StatusCode == System.Net.HttpStatusCode.NotFound || ex.Message.Contains("404"))
        {
            throw new IOException(Loc.T("errors.file.notPublishedYet"));
        }
        catch (HttpRequestException ex)
        {
            throw new IOException(Loc.T("errors.file.downloadFailed", ("reason", ex.Message.Trim())));
        }

        if (!File.Exists(path) || new FileInfo(path).Length != expectSize)
            throw new IOException(Loc.T("errors.file.incomplete"));
        var sha = await Task.Run(() => Core.Services.BackpackDlcService.Sha256File(path));
        if (!sha.Equals(expectSha, StringComparison.OrdinalIgnoreCase))
        {
            try { File.Delete(path); } catch { }
            throw new IOException(Loc.T("errors.file.hashMismatch"));
        }
        return path;
    }

    public async Task<BackpackStatusDto> OtherGetBackpackStatusAsync()
    {
        var gtaRoot = await GetGtaPathAsync();
        if (string.IsNullOrWhiteSpace(gtaRoot))
            return new BackpackStatusDto("missing", 0, false, false, GtaFound: false);

        var st = await Task.Run(() => Core.Services.BackpackDlcService.Inspect(
            gtaRoot, BackpackBackupPath(), Services.FileShaCache.ComputeSha256Cached));

        bool legacy = false;
        try
        {
            var updateRpf = Path.Combine(gtaRoot, "update", "update.rpf");
            if (File.Exists(updateRpf))
                legacy = await Task.Run(() => Core.Services.RukzakService.IsApplied(updateRpf));
        }
        catch (Exception ex) { Debug.WriteLine($"[backpack] legacy probe failed: {ex.Message}"); }

        string state = st.State switch
        {
            Core.Services.BackpackFileState.Vanilla => "vanilla",
            Core.Services.BackpackFileState.Removed => "removed",
            Core.Services.BackpackFileState.RemovedForeign => "removed-foreign",
            Core.Services.BackpackFileState.Foreign => "foreign",
            _ => "missing",
        };
        Console.WriteLine($"[Рюкзаки] {state}, {st.SizeBytes:N0} б, бэкап={st.BackupAvailable}, старый оверлей={legacy}");
        return new BackpackStatusDto(state, st.SizeBytes, st.BackupAvailable, legacy, GtaFound: true);
    }

    public async Task<InjectResultDto> OtherApplyBackpackAsync(string action)
    {
        bool toRemoved = string.Equals(action, "remove", StringComparison.OrdinalIgnoreCase);
        using var _mtx = await MiamiGraphics.Shell.Services.UpdateRpfMutex.AcquireAsync("other-backpack");
        const string progressKey = "other-backpack";
        string pretty = toRemoved ? "Удаление рюкзаков" : "Возврат рюкзаков";
        EmitInstallProgress(progressKey, pretty, "starting", 5, null,
            detailMessage: Loc.T("progress.common.checkingGameFile"));

        var gtaRoot = await GetGtaPathAsync();
        if (string.IsNullOrWhiteSpace(gtaRoot))
        {
            EmitInstallProgress(progressKey, pretty, "error", 0, "GTA не найдена.");
            return new InjectResultDto(false, "GTA не найдена. Укажи путь в Настройках → Папка GTA.", null);
        }

        try
        {
            var backup = BackpackBackupPath();
            var st = await Task.Run(() => Core.Services.BackpackDlcService.Inspect(
                gtaRoot, backup, Services.FileShaCache.ComputeSha256Cached));

            string source;
            if (toRemoved)
            {
                source = await EnsureBackpackFileAsync(
                    Core.Services.BackpackDlcService.R2Removed,
                    Core.Services.BackpackDlcService.RemovedSha256,
                    Core.Services.BackpackDlcService.RemovedSize,
                    "patchday11ng_removed.rpf", progressKey, pretty);
            }
            else
            {
                string? fromBackup = null;
                if (File.Exists(backup))
                {
                    var bsha = await Task.Run(() => Core.Services.BackpackDlcService.Sha256File(backup));
                    if (bsha.Equals(Core.Services.BackpackDlcService.VanillaSha256, StringComparison.OrdinalIgnoreCase))
                        fromBackup = backup;
                }
                source = fromBackup ?? await EnsureBackpackFileAsync(
                    Core.Services.BackpackDlcService.R2Vanilla,
                    Core.Services.BackpackDlcService.VanillaSha256,
                    Core.Services.BackpackDlcService.VanillaSize,
                    "patchday11ng_vanilla.rpf", progressKey, pretty);
            }

            EmitInstallProgress(progressKey, pretty, "injecting", 75, null, detailMessage: Loc.T("progress.common.replacingGameFile"));
            await Task.Run(() => Core.Services.BackpackDlcService.Swap(gtaRoot, source, backup, st.State));

            try
            {
                var updateRpf = Path.Combine(gtaRoot, "update", "update.rpf");
                if (File.Exists(updateRpf) && await Task.Run(() => Core.Services.RukzakService.IsApplied(updateRpf)))
                {
                    EmitInstallProgress(progressKey, pretty, "injecting", 88, null,
                        detailMessage: Loc.T("progress.backpack.removingPrevMethod"));
                    await Task.Run(() =>
                    {
                        Core.Services.RukzakService.Remove(updateRpf);
                        Core.Services.PatchCustomizationSupport.FixLiveArchiveChecksums(
                            updateRpf, Array.Empty<string>());
                    });
                    Console.WriteLine("[Рюкзаки] Старый оверлей miami_rukzak.rpf снят.");
                }
            }
            catch (Exception ex) { Debug.WriteLine($"[backpack] legacy cleanup failed (non-fatal): {ex.Message}"); }

            try
            {
                var state = ReadInstallState();
                var prevDraft = state?.CustomizationDraft;
                var nextDraft = (prevDraft ?? BuildDefaultDraft(state?.ReduxId ?? "vanilla", state?.VersionId))
                    with { NoBackpackEnabled = toRemoved };
                WriteInstallState(new InstallState
                {
                    ReduxId = state?.ReduxId,
                    VersionId = state?.VersionId,
                    PostInstallSha256 = state?.PostInstallSha256,
                    InstalledAt = state?.InstalledAt ?? DateTime.UtcNow,
                    CustomizationDraft = nextDraft,
                    CurrentArmorId = state?.CurrentArmorId,
                    CurrentArmorName = state?.CurrentArmorName,
                    CurrentArmorGlbUrl = state?.CurrentArmorGlbUrl,
                    CurrentArmorKind = state?.CurrentArmorKind,
                });
            }
            catch (Exception ex) { Debug.WriteLine($"[backpack] state persist failed (non-fatal): {ex.Message}"); }

            EmitInstallProgress(progressKey, pretty, "done", 100, null,
                detailMessage: toRemoved ? Loc.T("progress.backpack.removed") : Loc.T("progress.backpack.restored"));
            return new InjectResultDto(true, null, null);
        }
        catch (Exception ex)
        {
            var msg = $"Не удалось изменить рюкзаки: {ex.Message}";
            Console.WriteLine($"[Рюкзаки] ОШИБКА: {ex.GetType().Name}: {ex.Message}");
            EmitInstallProgress(progressKey, pretty, "error", 0, msg);
            return new InjectResultDto(false, msg, null);
        }
    }

