    private async Task FixUpdateRpfAfterOverlayReapplyAsync(string updateRpf)
    {
        try
        {
            var draft = ReadInstallState()?.CustomizationDraft;
            bool any = (draft?.ZalazyEnabled ?? false)
                    || (draft?.GreenZoneEnabled ?? false)
                    || (draft?.NoBackpackEnabled ?? false)
                    || (draft?.FastJoinUserInstalled ?? false)
                    || (draft?.CarLogosEnabled ?? false)
                    || (draft?.BigMapEnabled ?? false);
            if (!any) return;
            var touched = Interlocked.Exchange(ref _bigMapReapplyTouched, null) ?? new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            await Task.Run(() => Core.Services.PatchCustomizationSupport.FixLiveArchiveChecksums(updateRpf, touched));
            Debug.WriteLine("[other.overlays] consolidated ArchiveFix after re-apply done");
        }
        catch (Exception ex) { Debug.WriteLine($"[other.overlays] consolidated ArchiveFix failed (non-fatal): {ex.Message}"); }
    }

    private HashSet<string>? _bigMapReapplyTouched;

    private static string BigMapBackupDir => Core.System.AppDataRoot.BackupDir("bigmap");

    private static string BigMapCacheRoot
        => MiamiGraphics.Shell.Services.ModCacheSettings.Dir("bigmap");

    private static BigMapDto MapBigMap(Admin.BigMapItem r) => new(
        r.Id, r.Name, r.Author, r.AuthorLink, r.Description,
        r.PreviewUrl, r.GalleryUrls, r.VideoUrl, r.SupportedServers,
        r.SizeBytes, r.PackFormat, r.DownloadCount, r.IsVerified);

    public async Task<List<BigMapDto>> BigMapListAsync()
    {
        try
        {
            var rows = await BigMapRepo.ListAsync("published");
            return rows.Select(MapBigMap).ToList();
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[bigmap.list] FAIL: {ex.Message}");
            return new List<BigMapDto>();
        }
