    public async Task<BigMapStateDto> BigMapGetStateAsync()
    {
        var draft = ReadInstallState()?.CustomizationDraft;
        bool enabled = draft?.BigMapEnabled ?? false;
        string? id = draft?.BigMapId;
        string? name = draft?.BigMapName;

        bool foreign = false;
        if (!enabled)
        {
            try
            {
                var gtaRoot = await GetGtaPathAsync();
                if (!string.IsNullOrWhiteSpace(gtaRoot))
                {
                    var updateRpf = Path.Combine(gtaRoot, "update", "update.rpf");
                    if (File.Exists(updateRpf))
                        foreign = await Task.Run(() => Core.Services.BigMapService.IsInstalled(updateRpf));
                }
            }
            catch (Exception ex) { Debug.WriteLine($"[bigmap.state] foreign detect failed: {ex.Message}"); }
        }
        return new BigMapStateDto(enabled, id, name, foreign);
    }

    private async Task<string> EnsureBigMapPackageAsync(Admin.BigMapItem row, string progressKey, string pretty)
    {
        Directory.CreateDirectory(BigMapCacheRoot);
        Services.VerifiedDownload.RequireReference(row.PackageSha256, $"пакет карты «{pretty}»");
        var urlHash = global::System.Convert.ToHexString(
            global::System.Security.Cryptography.SHA256.HashData(
                global::System.Text.Encoding.UTF8.GetBytes(row.PackageUrl ?? string.Empty)))
            .Substring(0, 12);
        var pkgDir = Path.Combine(BigMapCacheRoot, $"{row.Id}__{urlHash}");
        if (MiamiGraphics.Shell.Services.ModCacheSettings.ReuseEnabled
            && File.Exists(Path.Combine(pkgDir, "manifest.json"))
            && Services.VerifiedDownload.DirMarkerMatches(pkgDir, row.PackageSha256))
        {
            EmitInstallProgress(progressKey, pretty, "downloading", 30, null,
                detailMessage: Loc.T("progress.map.cacheHit"));
            Core.System.DataQuota.Touch(pkgDir);
            return pkgDir;
        }

        EmitInstallProgress(progressKey, pretty, "downloading", 10, null,
            detailMessage: Loc.T("progress.map.downloading"));
        var zipTmp = Path.Combine(BigMapCacheRoot, $"{row.Id}__{urlHash}.zip.part");

        await DownloadViaMirrorAsync(row.PackageUrl, zipTmp,
            (recv, total) => EmitInstallProgress(progressKey, pretty, "downloading",
                total > 0 ? (int)(10 + recv * 10.0 / total) : 10, null,
                detailMessage: total > 0
                    ? DownloadCounterText(recv, total)
                    : Loc.T("progress.map.downloading")),
            CancellationToken.None);

        {
            EmitInstallProgress(progressKey, pretty, "downloading", 25, null,
                detailMessage: Loc.T("progress.common.verifying"));
            string actual;
            await using (var fs = File.OpenRead(zipTmp))
                actual = global::System.Convert.ToHexString(
                    await global::System.Security.Cryptography.SHA256.HashDataAsync(fs));
            if (!Services.VerifiedDownload.Matches(row.PackageSha256, actual))
            {
                try { File.Delete(zipTmp); } catch { }
                throw new Services.IntegrityException(
                    "Пакет карты не прошёл проверку целостности и удалён - установка отменена. " +
                    "Скорее всего файл побился при загрузке; повтори попытку, а если повторится - сообщи админу.");
            }
        }

        if (Directory.Exists(pkgDir)) try { Directory.Delete(pkgDir, true); } catch { }
        global::System.IO.Compression.ZipFile.ExtractToDirectory(zipTmp, pkgDir);
        try { File.Delete(zipTmp); } catch { }
        if (!File.Exists(Path.Combine(pkgDir, "manifest.json")))
            throw new InvalidOperationException(Loc.T("errors.bigmap.noManifest"));
        Services.VerifiedDownload.WriteDirMarker(pkgDir, row.PackageSha256);
        return pkgDir;
    }

    public async Task<InjectResultDto> BigMapInstallAsync(string id)
    {
        using var _mtx = await MiamiGraphics.Shell.Services.UpdateRpfMutex.AcquireAsync("bigmap-install");
        const string progressKey = "bigmap";
        const string pretty = "Установка большой карты";
        EmitInstallProgress(progressKey, pretty, "starting", 5, null, detailMessage: Loc.T("progress.map.preparing"));

        var gtaRoot = await GetGtaPathAsync();
        if (string.IsNullOrWhiteSpace(gtaRoot))
        {
            EmitInstallProgress(progressKey, pretty, "error", 0, "GTA не найдена.");
            return new InjectResultDto(false, "GTA не найдена. Укажи путь в Настройках → Папка GTA.", null);
        }
        var updateRpf = Path.Combine(gtaRoot, "update", "update.rpf");
        if (!File.Exists(updateRpf))
        {
            EmitInstallProgress(progressKey, pretty, "error", 0, "update.rpf не найден.");
            return new InjectResultDto(false, $"Не найден {updateRpf}.", null);
        }

        var row = await BigMapRepo.GetByIdAsync(id);
        if (row is null || string.IsNullOrWhiteSpace(row.PackageUrl))
        {
            EmitInstallProgress(progressKey, pretty, "error", 0, "Карта не найдена в каталоге.");
            return new InjectResultDto(false, "Карта не найдена в каталоге (возможно, снята с публикации).", null);
        }

        var rollbackPath = updateRpf + ".preinstall";
        try
        {
            var pkgDir = await EnsureBigMapPackageAsync(row, progressKey, pretty);

            await MakeRollbackPointAsync(updateRpf, rollbackPath, progressKey, pretty,
                "starting", new ProgressBand(30, 42), "bigmap.install");

            EmitInstallProgress(progressKey, pretty, "injecting", 45, null, detailMessage: Loc.T("progress.map.installing"));
            var cleanRpf = GetLocalCleanRpfPath();

            bool checksumOk = false;
            string? applyError = null;
            await Task.Run(() =>
            {
                var res = Core.Services.BigMapService.Apply(updateRpf, pkgDir, BigMapBackupDir, cleanRpf);
                if (!res.Ok) { applyError = res.Error; return; }
                EmitInstallProgress(progressKey, pretty, "injecting", 75, null, detailMessage: Loc.T("install.reencryptingUpdateRpf"));
                checksumOk = Core.Services.PatchCustomizationSupport.FixLiveArchiveChecksums(
                    updateRpf, res.TouchedNestedRpfNames.ToList());
            });

            if (applyError is not null || !checksumOk)
            {
                bool restored = false;
                try { if (File.Exists(rollbackPath)) { File.Copy(rollbackPath, updateRpf, overwrite: true); restored = true; } } catch { }
                try { if (File.Exists(rollbackPath)) File.Delete(rollbackPath); } catch { }
                var msg = applyError is not null
                    ? $"Карта не применена: {applyError}" + (restored ? " Изменения откатились." : "")
                    : "Карта не применена: не удалось перешифровать update.rpf (ArchiveFix). " +
                      "Проверь, что антивирус не удалил файлы лаунчера, и переустанови лаунчер. " +
                      (restored ? "Изменения откатились." : "ВНИМАНИЕ: откат не удался - восстанови чистый update.rpf через настройки.");
                EmitInstallProgress(progressKey, pretty, "error", 0, msg);
                return new InjectResultDto(false, msg, null);
            }

            try
            {
                var state = ReadInstallState();
                var prevDraft = state?.CustomizationDraft;
                var nextDraft = (prevDraft ?? BuildDefaultDraft(state?.ReduxId ?? "vanilla", state?.VersionId))
                    with { BigMapEnabled = true, BigMapId = row.Id, BigMapName = row.Name };
                var postSha = await Task.Run(() => Services.FileShaCache.ComputeSha256Cached(updateRpf));
                WriteInstallState(new InstallState
                {
                    ReduxId = state?.ReduxId,
                    VersionId = state?.VersionId,
                    PostInstallSha256 = postSha,
                    InstalledAt = DateTime.UtcNow,
                    CustomizationDraft = nextDraft,
                    CurrentArmorId = state?.CurrentArmorId,
                    CurrentArmorName = state?.CurrentArmorName,
                    CurrentArmorGlbUrl = state?.CurrentArmorGlbUrl,
                    CurrentArmorKind = state?.CurrentArmorKind,
                });
            }
            catch (Exception ex) { Debug.WriteLine($"[bigmap.install] state persist failed (non-fatal): {ex.Message}"); }

            try { if (File.Exists(rollbackPath)) File.Delete(rollbackPath); } catch { }
            _ = Task.Run(() => BigMapRepo.IncrementDownloadsAsync(row.Id));

            EmitInstallProgress(progressKey, pretty, "done", 100, null, detailMessage: Loc.T("progress.map.installed"));
            return new InjectResultDto(true, null, null);
        }
        catch (Exception ex)
        {
            try { if (File.Exists(rollbackPath)) { File.Copy(rollbackPath, updateRpf, overwrite: true); File.Delete(rollbackPath); } } catch { }
            EmitInstallProgress(progressKey, pretty, "error", 0, ex.Message);
            return new InjectResultDto(false, $"Ошибка: {ex.Message}", null);
        }
    }

    public async Task<InjectResultDto> BigMapUninstallAsync()
    {
        using var _mtx = await MiamiGraphics.Shell.Services.UpdateRpfMutex.AcquireAsync("bigmap-uninstall");
        const string progressKey = "bigmap";
        const string pretty = "Удаление большой карты";
        EmitInstallProgress(progressKey, pretty, "starting", 5, null, detailMessage: Loc.T("progress.map.removing"));

        var gtaRoot = await GetGtaPathAsync();
        if (string.IsNullOrWhiteSpace(gtaRoot))
        {
            EmitInstallProgress(progressKey, pretty, "error", 0, "GTA не найдена.");
            return new InjectResultDto(false, "GTA не найдена. Укажи путь в Настройках → Папка GTA.", null);
        }
        var updateRpf = Path.Combine(gtaRoot, "update", "update.rpf");
        if (!File.Exists(updateRpf))
        {
            EmitInstallProgress(progressKey, pretty, "error", 0, "update.rpf не найден.");
            return new InjectResultDto(false, $"Не найден {updateRpf}.", null);
        }

        var rollbackPath = updateRpf + ".preinstall";
        try
        {
            await MakeRollbackPointAsync(updateRpf, rollbackPath, progressKey, pretty,
                "starting", new ProgressBand(5, 40), "bigmap.uninstall");

            EmitInstallProgress(progressKey, pretty, "injecting", 45, null, detailMessage: Loc.T("progress.map.restoringOriginals"));
            var cleanRpf = GetLocalCleanRpfPath();

            bool checksumOk = false;
            string? removeError = null;
            await Task.Run(() =>
            {
                var res = Core.Services.BigMapService.Remove(updateRpf, BigMapBackupDir, cleanRpf);
                if (!res.Ok) { removeError = res.Error; return; }
                EmitInstallProgress(progressKey, pretty, "injecting", 75, null, detailMessage: Loc.T("install.reencryptingUpdateRpf"));
                checksumOk = Core.Services.PatchCustomizationSupport.FixLiveArchiveChecksums(
                    updateRpf, res.TouchedNestedRpfNames.ToList());
            });

            if (removeError is not null || !checksumOk)
            {
                bool restored = false;
                try { if (File.Exists(rollbackPath)) { File.Copy(rollbackPath, updateRpf, overwrite: true); restored = true; } } catch { }
                try { if (File.Exists(rollbackPath)) File.Delete(rollbackPath); } catch { }
                var msg = removeError is not null
                    ? $"Карта не убрана: {removeError}" + (restored ? " Изменения откатились." : "")
                    : "Карта не убрана: не удалось перешифровать update.rpf (ArchiveFix). " +
                      (restored ? "Изменения откатились." : "ВНИМАНИЕ: откат не удался - восстанови чистый update.rpf через настройки.");
                EmitInstallProgress(progressKey, pretty, "error", 0, msg);
                return new InjectResultDto(false, msg, null);
            }

            try
            {
                var state = ReadInstallState();
                var prevDraft = state?.CustomizationDraft;
                if (prevDraft is not null)
                {
                    var nextDraft = prevDraft with { BigMapEnabled = false, BigMapId = null, BigMapName = null };
                    var postSha = await Task.Run(() => Services.FileShaCache.ComputeSha256Cached(updateRpf));
                    WriteInstallState(new InstallState
                    {
                        ReduxId = state?.ReduxId,
                        VersionId = state?.VersionId,
                        PostInstallSha256 = postSha,
                        InstalledAt = DateTime.UtcNow,
                        CustomizationDraft = nextDraft,
                        CurrentArmorId = state?.CurrentArmorId,
                        CurrentArmorName = state?.CurrentArmorName,
                        CurrentArmorGlbUrl = state?.CurrentArmorGlbUrl,
                        CurrentArmorKind = state?.CurrentArmorKind,
                    });
                }
            }
            catch (Exception ex) { Debug.WriteLine($"[bigmap.uninstall] state persist failed (non-fatal): {ex.Message}"); }

            try { if (File.Exists(rollbackPath)) File.Delete(rollbackPath); } catch { }
            EmitInstallProgress(progressKey, pretty, "done", 100, null, detailMessage: Loc.T("progress.map.removed"));
            return new InjectResultDto(true, null, null);
        }
        catch (Exception ex)
        {
            try { if (File.Exists(rollbackPath)) { File.Copy(rollbackPath, updateRpf, overwrite: true); File.Delete(rollbackPath); } } catch { }
            EmitInstallProgress(progressKey, pretty, "error", 0, ex.Message);
            return new InjectResultDto(false, $"Ошибка: {ex.Message}", null);
        }
    }

    internal static string BigMap3dDir => Path.Combine(
        Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
        "MiamiGraphics", "bigmap3d");

    private static readonly global::System.Threading.SemaphoreSlim _bigMap3dGate = new(1, 1);

    public async Task<string?> BigMapPreviewGlbAsync(string id)
    {
        const string progressKey = "bigmap3d";
        const string pretty = "3D-модель карты";
        await _bigMap3dGate.WaitAsync();
        try
        {
            var row = await BigMapRepo.GetByIdAsync(id);
            if (row is null || string.IsNullOrWhiteSpace(row.PackageUrl)) return null;

            var urlHash = global::System.Convert.ToHexString(
                global::System.Security.Cryptography.SHA256.HashData(
                    global::System.Text.Encoding.UTF8.GetBytes(row.PackageUrl)))
                .Substring(0, 12);
            var fileName = $"{row.Id}__{urlHash}.glb";
            Directory.CreateDirectory(BigMap3dDir);
            var glbPath = Path.Combine(BigMap3dDir, fileName);

            if (!File.Exists(glbPath))
            {
                var pkgDir = await EnsureBigMapPackageAsync(row, progressKey, pretty);
                EmitInstallProgress(progressKey, pretty, "injecting", 60, null,
                    detailMessage: Loc.T("progress.map.building3d"));
                var tmp = glbPath + ".part";
                bool ok = await Core.Services.MinimapGlbExporter.ExportFromPackageAsync(pkgDir, tmp);
                if (!ok)
                {
                    try { File.Delete(tmp); } catch { }
                    EmitInstallProgress(progressKey, pretty, "error", 0, "Не удалось собрать 3D-модель карты.");
                    return null;
                }
                File.Move(tmp, glbPath, overwrite: true);
                EmitInstallProgress(progressKey, pretty, "done", 100, null, detailMessage: Loc.T("progress.map.model3dReady"));
            }
            return "https://bigmap3d.huntergraphics.local/" + fileName;
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[bigmap.3d] FAIL: {ex.Message}");
            EmitInstallProgress(progressKey, pretty, "error", 0, ex.Message);
            return null;
        }
        finally { _bigMap3dGate.Release(); }
    }

    private async Task ReapplyBigMapIfEnabledAsync(string updateRpf)
    {
        bool cardShown = false;
        try
        {
            var draft = ReadInstallState()?.CustomizationDraft;
            if (!(draft?.BigMapEnabled ?? false) || string.IsNullOrWhiteSpace(draft!.BigMapId)) return;
            var row = await BigMapRepo.GetByIdAsync(draft.BigMapId!);
            if (row is null || string.IsNullOrWhiteSpace(row.PackageUrl))
            {
                Debug.WriteLine("[bigmap.reapply] row missing from catalog - skipped");
                return;
            }
            cardShown = true;
            var pkgDir = await EnsureBigMapPackageAsync(row, "bigmap", "Большая карта");
            var cleanRpf = GetLocalCleanRpfPath();
            EmitInstallProgress("bigmap", "Большая карта", "injecting", 60, null,
                detailMessage: Loc.T("progress.map.reinstallAfterRebuild"));
            var res = await Task.Run(() =>
                Core.Services.BigMapService.Apply(updateRpf, pkgDir, BigMapBackupDir, cleanRpf));
            if (res.Ok)
            {
                _bigMapReapplyTouched = new HashSet<string>(res.TouchedNestedRpfNames, StringComparer.OrdinalIgnoreCase);
                Debug.WriteLine("[bigmap.reapply] re-applied after rebuild");
                EmitInstallProgress("bigmap", "Большая карта", "done", 100, null,
                    detailMessage: Loc.T("progress.map.reinstalledAfterRebuild"));
            }
            else
            {
                Debug.WriteLine($"[bigmap.reapply] failed (non-fatal): {res.Error}");
                EmitInstallProgress("bigmap", "Большая карта", "error", 0,
                    $"Карта не переустановилась после пересборки: {res.Error}");
            }
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[bigmap.reapply] failed (non-fatal): {ex.Message}");
            if (cardShown)
                EmitInstallProgress("bigmap", "Большая карта", "error", 0,
                    $"Карта не переустановилась после пересборки: {ex.Message}");
        }
    }

