    public async Task<BigMapDto> AdminBigMapPublishAsync(BigMapPublishRequestDto request)
    {
        if (string.IsNullOrWhiteSpace(request.Name))
            throw new ArgumentException("name required", nameof(request));
        var (srcDir, isTemp) = await ExtractBigMapSourceAsync(request.SourcePath);
        var workDir = Path.Combine(Path.GetTempPath(), "mg_bigmap_pub_" + Guid.NewGuid().ToString("N"));
        try
        {
            var id = !string.IsNullOrWhiteSpace(request.ExistingId)
                ? request.ExistingId!
                : MakeBigMapId(request.Name);

            var pkgDir = Path.Combine(workDir, "package");
            var analysis = await Task.Run(() => Core.Services.BigMapAnalyzer.Analyze(srcDir, pkgDir));
            if (!analysis.IsInstallable)
                throw new InvalidOperationException(
                    "Пак не пригоден к установке: " + string.Join("; ", analysis.Warnings));

            var zipPath = Path.Combine(workDir, "package.zip");
            await Task.Run(() => global::System.IO.Compression.ZipFile.CreateFromDirectory(pkgDir, zipPath));
            long zipSize = new FileInfo(zipPath).Length;
            string zipSha;
            await using (var fs = File.OpenRead(zipPath))
                zipSha = global::System.Convert.ToHexString(
                    await global::System.Security.Cryptography.SHA256.HashDataAsync(fs));

            var hex = Guid.NewGuid().ToString("N").Substring(0, 16);
            var pkgKey = $"big_maps/{id}/package_{hex}.zip";
            var packageUrl = await _remoteStorage.UploadAsync(zipPath, pkgKey, progress: null, CancellationToken.None);

            string previewUrl = string.Empty;
            var vectorGlb  = Path.Combine(workDir, "map.glb");
            var vectorWebp = Path.Combine(workDir, "vector_preview.webp");
            try
            {
                bool glbOk = await Core.Services.MinimapGlbExporter.ExportFromPackageAsync(pkgDir, vectorGlb);
                bool webpOk = glbOk && await Core.Services.GlbToPngRenderer.RenderAsync(
                    vectorGlb, vectorWebp, 1280, 720, view: "map");
                if (webpOk && File.Exists(vectorWebp))
                {
                    previewUrl = await _remoteStorage.UploadAsync(
                        vectorWebp, $"big_maps/{id}/preview.webp", progress: null, CancellationToken.None);
                    Debug.WriteLine($"[admin.bigmap.publish] vector preview ok -> {previewUrl}");
                }
                else
                {
                    Debug.WriteLine("[admin.bigmap.publish] vector preview render failed - fallback to admin photos");
                }
            }
            catch (Exception ex)
            {
                Debug.WriteLine($"[admin.bigmap.publish] vector preview EXCEPTION (non-fatal): {ex.Message}");
            }

            var photos = (request.PhotoPaths ?? new List<string>())
                .Where(p => !string.IsNullOrWhiteSpace(p) && File.Exists(p))
                .Take(7).ToList();
            var galleryUrls = new List<string>();
            for (int i = 0; i < photos.Count; i++)
            {
                bool asCover = previewUrl.Length == 0 && i == 0;
                var (localPath, ext, tmp) = await EnsureWebPAsync(photos[i]);
                try
                {
                    var key = asCover
                        ? $"big_maps/{id}/preview{ext}"
                        : $"big_maps/{id}/gallery/{i}{ext}";
                    var url = await _remoteStorage.UploadAsync(localPath, key, progress: null, CancellationToken.None);
                    if (asCover) previewUrl = url;
                    galleryUrls.Add(url);
                }
                finally
                {
                    if (tmp && File.Exists(localPath)) try { File.Delete(localPath); } catch { }
                }
            }

            var servers = (request.SupportedServers ?? new List<string>())
                .Select(s => s.Trim().ToLowerInvariant())
                .Where(s => s == "gta5rp" || s == "majestic")
                .Distinct().ToList();
            if (servers.Count == 0) servers.Add("majestic");

            var item = new Admin.BigMapItem
            {
                Id = id,
                Name = request.Name.Trim(),
                Author = request.Author?.Trim() ?? string.Empty,
                AuthorLink = request.AuthorLink?.Trim() ?? string.Empty,
                Description = request.Description?.Trim() ?? string.Empty,
                PreviewUrl = previewUrl,
                GalleryUrls = galleryUrls,
                VideoUrl = request.VideoUrl?.Trim() ?? string.Empty,
                SupportedServers = servers,
                PackageUrl = packageUrl,
                PackageSha256 = zipSha,
                SizeBytes = zipSize,
                PackFormat = analysis.PackFormat,
                UploadedAt = DateTime.UtcNow,
                Status = "published",
            };
            await BigMapRepo.UpsertAsync(item);
            Debug.WriteLine($"[admin.bigmap.publish] {id} fmt={analysis.PackFormat} zip={zipSize:N0}B -> {packageUrl}");
            return MapBigMap(item);
        }
        finally
        {
            try { Directory.Delete(workDir, true); } catch { }
            if (isTemp) try { Directory.Delete(srcDir, true); } catch { }
        }
    }

