    private static async Task<(string dir, bool isTemp)> ExtractBigMapSourceAsync(string sourcePath)
    {
        if (string.IsNullOrWhiteSpace(sourcePath))
            throw new ArgumentException("sourcePath required", nameof(sourcePath));
        if (Directory.Exists(sourcePath)) return (sourcePath, false);
        if (!File.Exists(sourcePath))
            throw new FileNotFoundException("Источник карты не найден", sourcePath);
        if (!sourcePath.EndsWith(".zip", StringComparison.OrdinalIgnoreCase))
            throw new ArgumentException("Поддерживаются папка или .zip (rar/7z распакуй сам).", nameof(sourcePath));
        var tmp = Path.Combine(Path.GetTempPath(), "mg_bigmap_src_" + Guid.NewGuid().ToString("N"));
        await Task.Run(() => global::System.IO.Compression.ZipFile.ExtractToDirectory(sourcePath, tmp));
        return (tmp, true);
    }

    private static string MakeBigMapId(string name)
    {
        var slug = new string(name.ToLowerInvariant()
            .Select(c => char.IsLetterOrDigit(c) ? c : '-').ToArray())
            .Trim('-');
        while (slug.Contains("--")) slug = slug.Replace("--", "-");
        if (slug.Length > 40) slug = slug.Substring(0, 40).Trim('-');
        if (string.IsNullOrEmpty(slug)) slug = "map";
        return $"{slug}-{Guid.NewGuid():N}"[..Math.Min(slug.Length + 9, 48)];
    }
#endif

