    private static string? ResolveSmokeDdsDir()
    {
        var root = ResolveAdditionalsRoot();
        if (string.IsNullOrWhiteSpace(root)) return null;
        var p = Path.Combine(root, "smoke");
        return Directory.Exists(p) ? p : null;
    }

    public async Task<InjectResultDto> OtherSetSmokeAsync(bool enabled)
    {
        using var _mtx = await MiamiGraphics.Shell.Services.UpdateRpfMutex.AcquireAsync("other-smoke");
        const string progressKey = "other-smoke";
        string pretty = enabled ? "Установка дыма" : "Возврат стандартного дыма";
        EmitInstallProgress(progressKey, pretty, "starting", 5, null,
            detailMessage: enabled ? Loc.T("progress.smoke.preparing") : Loc.T("progress.smoke.restoringStock"));

        var gtaRoot = await GetGtaPathAsync();
        if (string.IsNullOrWhiteSpace(gtaRoot))
        {
            EmitInstallProgress(progressKey, pretty, "error", 0, "GTA не найдена.");
            return new InjectResultDto(false, "GTA не найдена. Укажи путь в Настройках → Папка GTA.", null);
        }
        var updateRpf = Path.Combine(gtaRoot, "update", "update.rpf");
        if (!File.Exists(updateRpf))
        {
            EmitInstallProgress(progressKey, pretty, "error", 0, "update.rpf не найден.");
            return new InjectResultDto(false, $"Не найден {updateRpf}.", null);
        }

        try
        {
            var svc = new Core.Services.SmokeInstallService();
            Core.Services.SmokeInstallService.Result res;
            if (enabled)
            {
                var smokeDir = ResolveSmokeDdsDir();
                if (smokeDir is null)
                {
                    EmitInstallProgress(progressKey, pretty, "error", 0, "Папка additionals/Smoke не найдена.");
                    return new InjectResultDto(false, "Не найдена папка additionals/Smoke с текстурами дыма.", null);
                }
                EmitInstallProgress(progressKey, pretty, "injecting", 40, null, detailMessage: Loc.T("progress.smoke.registering"));
                res = await Task.Run(() => svc.Apply(gtaRoot, smokeDir,
                    p => Core.Services.PatchCustomizationSupport.GetCleanBytesForExactPath(gtaRoot, p)));
            }
            else
            {
                var cleanRpf = _backupService.GetCleanUpdateRpfPath();
                if (cleanRpf is null)
                {
                    EmitInstallProgress(progressKey, pretty, "error", 0, "Нет чистой копии update.rpf.");
                    return new InjectResultDto(false, "Нет резервной копии update.rpf для возврата стандартного дыма.", null);
                }
                EmitInstallProgress(progressKey, pretty, "injecting", 40, null, detailMessage: Loc.T("progress.smoke.restoringStock"));
                res = await Task.Run(() => svc.Restore(gtaRoot,
                    p => Core.Services.PatchCustomizationSupport.GetCleanBytesForExactPath(gtaRoot, p),
                    p => Core.Services.PatchCustomizationSupport.GetBytesFromArchiveExactPath(cleanRpf, p)));
            }

            if (!res.Success)
            {
                EmitInstallProgress(progressKey, pretty, "error", 0, res.ErrorMessage);
                return new InjectResultDto(false, res.ErrorMessage, null);
            }

            try
            {
                var state = ReadInstallState();
                var prevDraft = state?.CustomizationDraft;
                var nextDraft = (prevDraft ?? BuildDefaultDraft(state?.ReduxId ?? "vanilla", state?.VersionId))
                    with { SmokeEnabled = enabled };
                var postSha = await Task.Run(() => Services.FileShaCache.ComputeSha256Cached(updateRpf));
                WriteInstallState(new InstallState
                {
                    ReduxId = state?.ReduxId,
                    VersionId = state?.VersionId,
                    PostInstallSha256 = postSha,
                    InstalledAt = DateTime.UtcNow,
                    CustomizationDraft = nextDraft,
                    CurrentArmorId = state?.CurrentArmorId,
                    CurrentArmorName = state?.CurrentArmorName,
                    CurrentArmorGlbUrl = state?.CurrentArmorGlbUrl,
                    CurrentArmorKind = state?.CurrentArmorKind,
                });
            }
            catch (Exception ex) { Debug.WriteLine($"[other.smoke] state persist failed (non-fatal): {ex.Message}"); }

            EmitInstallProgress(progressKey, pretty, "done", 100, null,
                detailMessage: enabled ? Loc.T("progress.smoke.installed") : Loc.T("progress.smoke.stockRestored"));
            return new InjectResultDto(true, null, null);
        }
        catch (Exception ex)
        {
            EmitInstallProgress(progressKey, pretty, "error", 0, ex.Message);
            return new InjectResultDto(false, $"Ошибка: {ex.Message}", null);
        }
    }

