    private static string NoTracerCacheDir()
        => Core.System.AppDataRoot.Dir("notracer");

    private static string FormatNoTracerScope(string[] cats, bool keepSnipers)
    {
        if (keepSnipers) return "кроме снайперок";
        bool Has(string c) => cats.Contains(c, StringComparer.OrdinalIgnoreCase);
        if (Has("normal") && Has("vehicle") && Has("mk2ammo")) return "всё оружие";
        var labels = new List<string>();
        if (Has("normal")) labels.Add("обычное");
        if (Has("mk2ammo")) labels.Add("Mk II");
        if (Has("vehicle")) labels.Add("транспорт");
        return labels.Count > 0 ? string.Join(", ", labels) : "-";
    }

    private static string[] NormalizeTracerCategories(string[]? categories)
    {
        var all = Core.Services.NoTracerInstallService.AllCategories;
        if (categories is null || categories.Length == 0) return all;
        var set = new HashSet<string>(categories, StringComparer.OrdinalIgnoreCase);
        return all.Where(c => set.Contains(c)).ToArray();
    }

    public async Task<InjectResultDto> OtherSetNoTracerAsync(bool enabled, string[]? categories = null, bool keepSnipers = false)
    {
        using var _mtx = await MiamiGraphics.Shell.Services.UpdateRpfMutex.AcquireAsync("other-notracer");
        const string progressKey = "other-notracer";
        string pretty = enabled ? "Удаление трейсера" : "Возврат трейсера";
        EmitInstallProgress(progressKey, pretty, "starting", 5, null,
            detailMessage: enabled ? Loc.T("progress.tracer.removing") : Loc.T("progress.tracer.restoring"));

        var gtaRoot = await GetGtaPathAsync();
        if (string.IsNullOrWhiteSpace(gtaRoot))
        {
            EmitInstallProgress(progressKey, pretty, "error", 0, "GTA не найдена.");
            return new InjectResultDto(false, "GTA не найдена. Укажи путь в Настройках → Папка GTA.", null);
        }
        var updateRpf = Path.Combine(gtaRoot, "update", "update.rpf");
        if (!File.Exists(updateRpf))
        {
            EmitInstallProgress(progressKey, pretty, "error", 0, "update.rpf не найден.");
            return new InjectResultDto(false, $"Не найден {updateRpf}.", null);
        }

        var cats = NormalizeTracerCategories(categories);

        try
        {
            var svc = new Core.Services.NoTracerInstallService();
            string cacheDir = NoTracerCacheDir();
            Core.Services.NoTracerInstallService.Result res;
            if (enabled)
            {
                EmitInstallProgress(progressKey, pretty, "injecting", 40, null, detailMessage: Loc.T("progress.tracer.removingFromGame"));
                res = await Task.Run(() => svc.Apply(gtaRoot, cacheDir, cats, keepSnipers,
                    p => Core.Services.PatchCustomizationSupport.GetCleanBytesForExactPath(gtaRoot, p)));
            }
            else
            {
                var cleanRpf = _backupService.GetCleanUpdateRpfPath();
                EmitInstallProgress(progressKey, pretty, "injecting", 40, null, detailMessage: Loc.T("progress.tracer.restoring"));
                res = await Task.Run(() => svc.Restore(gtaRoot, cacheDir,
                    p => Core.Services.PatchCustomizationSupport.GetCleanBytesForExactPath(gtaRoot, p),
                    p => cleanRpf is null ? null : Core.Services.PatchCustomizationSupport.GetBytesFromArchiveExactPath(cleanRpf, p)));
            }

            if (!res.Success)
            {
                EmitInstallProgress(progressKey, pretty, "error", 0, res.ErrorMessage);
                return new InjectResultDto(false, res.ErrorMessage, null);
            }

            try
            {
                var state = ReadInstallState();
                var prevDraft = state?.CustomizationDraft;
                var nextDraft = (prevDraft ?? BuildDefaultDraft(state?.ReduxId ?? "vanilla", state?.VersionId))
                    with
                    {
                        NoTracerEnabled = enabled,
                        NoTracerCategories = enabled ? string.Join(",", cats) : "",
                        NoTracerKeepSnipers = enabled && keepSnipers,
                    };
                var postSha = await Task.Run(() => Services.FileShaCache.ComputeSha256Cached(updateRpf));
                WriteInstallState(new InstallState
                {
                    ReduxId = state?.ReduxId,
                    VersionId = state?.VersionId,
                    PostInstallSha256 = postSha,
                    InstalledAt = DateTime.UtcNow,
                    CustomizationDraft = nextDraft,
                    CurrentArmorId = state?.CurrentArmorId,
                    CurrentArmorName = state?.CurrentArmorName,
                    CurrentArmorGlbUrl = state?.CurrentArmorGlbUrl,
                    CurrentArmorKind = state?.CurrentArmorKind,
                });
            }
            catch (Exception ex) { Debug.WriteLine($"[other.notracer] state persist failed (non-fatal): {ex.Message}"); }

            EmitInstallProgress(progressKey, pretty, "done", 100, null,
                detailMessage: enabled
                    ? Loc.T("progress.tracer.removedScope", ("scope", FormatNoTracerScope(cats, keepSnipers)))
                    : Loc.T("progress.tracer.restored"));
            return new InjectResultDto(true, null, null);
        }
        catch (Exception ex)
        {
            EmitInstallProgress(progressKey, pretty, "error", 0, ex.Message);
            return new InjectResultDto(false, $"Ошибка: {ex.Message}", null);
        }
    }

    public Task<NoTracerStateDto> OtherGetNoTracerAsync()
    {
        var draft = ReadInstallState()?.CustomizationDraft;
        bool enabled = draft?.NoTracerEnabled ?? false;
        var cats = enabled
            ? NormalizeTracerCategories((draft?.NoTracerCategories ?? "")
                .Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries))
            : Array.Empty<string>();
        return Task.FromResult(new NoTracerStateDto(enabled, cats, enabled && (draft?.NoTracerKeepSnipers ?? false)));
    }

