    public async Task<InjectResultDto> OtherSetTracerStudioAsync(string? settings)
    {
        using var _mtx = await MiamiGraphics.Shell.Services.UpdateRpfMutex.AcquireAsync("other-tracer-studio");
        const string progressKey = "other-tracer-studio";
        var parsed = Core.Services.TracerStudioService.Decode(settings);
        bool enabling = !parsed.IsEmpty;
        string pretty = enabling ? "Студия трейсеров" : "Возврат трейсеров";
        EmitInstallProgress(progressKey, pretty, "starting", 5, null,
            detailMessage: enabling ? Loc.T("progress.tracerStudio.preparing") : Loc.T("progress.tracerStudio.removing"));

        var gtaRoot = await GetGtaPathAsync();
        if (string.IsNullOrWhiteSpace(gtaRoot))
        {
            EmitInstallProgress(progressKey, pretty, "error", 0, "GTA не найдена.");
            return new InjectResultDto(false, "GTA не найдена. Укажи путь в Настройках → Папка GTA.", null);
        }

        try
        {
            var svc = new Core.Services.TracerStudioService();
            var res = await Task.Run(() => svc.Apply(
                gtaRoot, TracerStudioMetaCacheDir(), TracerStudioCoreCacheDir(), parsed,
                p => Core.Services.PatchCustomizationSupport.GetCleanBytesForExactPath(gtaRoot, p),
                (pct, msg) => EmitInstallProgress(progressKey, pretty, "injecting", pct, null, detailMessage: msg)));

            if (!res.Success)
            {
                EmitInstallProgress(progressKey, pretty, "error", 0, res.ErrorMessage);
                return new InjectResultDto(false, res.ErrorMessage, null);
            }

            try
            {
                var state = ReadInstallState();
                var prevDraft = state?.CustomizationDraft;
                var nextDraft = (prevDraft ?? BuildDefaultDraft(state?.ReduxId ?? "vanilla", state?.VersionId))
                    with { TracerStudio = enabling ? (settings ?? "") : "" };
                WriteInstallState(new InstallState
                {
                    ReduxId = state?.ReduxId,
                    VersionId = state?.VersionId,
                    PostInstallSha256 = state?.PostInstallSha256,
                    InstalledAt = state?.InstalledAt ?? DateTime.UtcNow,
                    CustomizationDraft = nextDraft,
                    CurrentArmorId = state?.CurrentArmorId,
                    CurrentArmorName = state?.CurrentArmorName,
                    CurrentArmorGlbUrl = state?.CurrentArmorGlbUrl,
                    CurrentArmorKind = state?.CurrentArmorKind,
                });
            }
            catch (Exception ex) { Debug.WriteLine($"[other.tracerstudio] state persist failed (non-fatal): {ex.Message}"); }

            string doneMsg = enabling ? Loc.T("progress.tracerStudio.applied") : Loc.T("progress.tracerStudio.removed");
            var warnParts = new List<string>();
            if (res.NotFound.Count > 0)
                warnParts.Add("Не найдены в метах: " + string.Join(", ", res.NotFound));
            warnParts.AddRange(res.Warnings);
            string? warn = warnParts.Count > 0 ? string.Join("\n", warnParts) : null;
            EmitInstallProgress(progressKey, pretty, "done", 100, null, detailMessage: doneMsg);
            return new InjectResultDto(true, warn, null);
        }
        catch (Exception ex)
        {
            EmitInstallProgress(progressKey, pretty, "error", 0, ex.Message);
            return new InjectResultDto(false, ex.Message, null);
        }
    }

    private async Task ReapplyTracerStudioIfEnabledAsync(string gtaRoot)
    {
        try
        {
            var packed = ReadInstallState()?.CustomizationDraft?.TracerStudio;
            if (string.IsNullOrWhiteSpace(packed)) return;
            var parsed = Core.Services.TracerStudioService.Decode(packed);
            if (parsed.IsEmpty) return;

            Core.Services.TracerStudioService.InvalidateCoreBaseline(TracerStudioCoreCacheDir());
            var metaCache = TracerStudioMetaCacheDir();
            try { if (Directory.Exists(metaCache)) Directory.Delete(metaCache, recursive: true); } catch { }

            var svc = new Core.Services.TracerStudioService();
            await Task.Run(() => svc.Apply(gtaRoot, metaCache, TracerStudioCoreCacheDir(), parsed,
                p => Core.Services.PatchCustomizationSupport.GetCleanBytesForExactPath(gtaRoot, p)));
            Debug.WriteLine("[other.tracerstudio] re-applied after rebuild");
        }
        catch (Exception ex) { Debug.WriteLine($"[other.tracerstudio] re-apply failed (non-fatal): {ex.Message}"); }
    }

