    private string _improvementsCatalogError = string.Empty;

    private async Task<List<Core.Services.ImprovementManagerService.CatalogEntry>> ImprovementCatalogAsync()
    {
        _improvementsCatalogError = string.Empty;
        var remote = new List<Core.Services.ImprovementManagerService.CatalogEntry>();
        var sw = System.Diagnostics.Stopwatch.StartNew();

        var rowsTask = _supabase.SelectAsync<ImprovementRow>(
            "improvements", "select=*&is_deleted=eq.false&order=name.asc");
        var reqsTask = _supabase.SelectAsync<ImprovementRequirementRow>(
            "improvement_requirements", "select=*");

        List<ImprovementRow> rows = new();
        List<ImprovementRequirementRow> reqs = new();
        try { rows = await rowsTask; }
        catch (Exception ex)
        {
            _improvementsCatalogError = $"каталог улучшений недоступен: {ex.Message}";
            Services.SessionLog.Info("improvements", _improvementsCatalogError);
        }
        try { reqs = await reqsTask; }
        catch (Exception ex)
        {
            _improvementsCatalogError = $"не прочитались требования к контейнерам: {ex.Message}";
            Services.SessionLog.Info("improvements", _improvementsCatalogError);
        }

        _improvementsMeta = rows;

        try
        {
            foreach (var r in rows)
            {
                remote.Add(new Core.Services.ImprovementManagerService.CatalogEntry
                {
                    Id              = r.Id,
                    Name            = r.Name,
                    ExclusiveGroup  = r.ExclusiveGroup ?? string.Empty,
                    Category        = r.Category ?? string.Empty,
                    BundleUrl       = r.ManifestUrl,
                    BundleSha256    = r.ManifestSha256,
                    BundleSizeBytes = r.SizeBytes,
                    Requires = reqs.Where(q => q.ImprovementId == r.Id)
                        .Select(q => new Core.Services.ImprovementManagerService.RequiredContainer
                        {
                            Path      = q.Path,
                            SizeBytes = q.SizeBytes,
                            Sha256    = q.Sha256,
                            Url       = ImprovementCleanCdnBase +
                                        q.Path.Replace('\\', '/').Trim('/').Replace('/', '_'),
                        }).ToList(),
                });
            }
        }
        catch (Exception ex)
        {
            _improvementsCatalogError = $"каталог не разобрался: {ex.GetType().Name}: {ex.Message}";
            Services.SessionLog.Info("improvements", _improvementsCatalogError);
        }

        var merged = Core.Services.ImprovementManagerService.MergeCatalog(remote);
        Services.SessionLog.Info("improvements",
            $"каталог: сеть={rows.Count}, требований={reqs.Count}, итого={merged.Count}, {sw.ElapsedMilliseconds} мс");
        return merged;
    }

    private List<ImprovementRow> _improvementsMeta = new();

    public async Task<List<ImprovementDto>> ImprovementsListAsync()
    {
        var installed = new Core.Services.ImprovementManagerService().LoadRegistry()
            .Items.Select(i => i.Id).ToHashSet(StringComparer.OrdinalIgnoreCase);

        var catalog = await ImprovementCatalogAsync();
        var meta = _improvementsMeta.ToDictionary(r => r.Id, r => r, StringComparer.OrdinalIgnoreCase);

        if (catalog.Count == 0 && _improvementsCatalogError.Length > 0)
            throw new InvalidOperationException(_improvementsCatalogError);
        return catalog.Select(e =>
        {
            meta.TryGetValue(e.Id, out var m);
            return new ImprovementDto(
                e.Id,
                string.IsNullOrWhiteSpace(e.Name) ? (m?.Name ?? e.Id) : e.Name,
                m?.Author ?? string.Empty,
                m?.Description ?? string.Empty,
                m?.Source ?? string.Empty,
                e.ExclusiveGroup ?? string.Empty,
                e.Category ?? string.Empty,
                m?.PreviewUrl ?? string.Empty,
                m?.VideoUrl ?? string.Empty,
                m?.GalleryUrls?.Where(u => !string.IsNullOrWhiteSpace(u)).ToArray()
                    ?? Array.Empty<string>(),
                e.BundleSizeBytes > 0 ? e.BundleSizeBytes : (m?.SizeBytes ?? 0),
                installed.Contains(e.Id),
                Array.Empty<string>(),
                m?.Popularity ?? 0);
        }).ToList();
    }

    private async Task ReapplyImprovementsIfAnyAsync(string gtaRoot)
    {
        try
        {
            var mgr = new Core.Services.ImprovementManagerService();
            var want = mgr.LoadRegistry().Items.Select(x => x.Id).ToList();
            if (want.Count == 0) return;

            Services.SessionLog.Info("improvements",
                $"после пересборки update.rpf возвращаю: {string.Join(", ", want)}");

            var catalog = await ImprovementCatalogAsync();
            var res = await mgr.ApplySetAsync(gtaRoot, want, catalog, ImprovementDownloader(),
                progress: null, log: m => Debug.WriteLine(m), CancellationToken.None);

            Services.SessionLog.Info("improvements",
                res.Success ? $"возвращены: {res.Message}" : $"вернуть не удалось: {res.Message}");
        }
        catch (Exception ex)
        {
            Services.SessionLog.Info("improvements", $"re-apply упал: {ex.GetType().Name}: {ex.Message}");
        }
    }

    private static Core.Services.ImprovementManagerService.DownloadAsync ImprovementDownloader() =>
        async (url, dest, bytes, ct) =>
        {
            if (!url.StartsWith("http", StringComparison.OrdinalIgnoreCase))
            {
                var src = url.StartsWith("file:", StringComparison.OrdinalIgnoreCase)
                    ? new Uri(url).LocalPath : url;
                if (!File.Exists(src)) throw new FileNotFoundException(Loc.T("errors.improvement.fileMissing", ("path", src)));
                Directory.CreateDirectory(Path.GetDirectoryName(dest)!);
                await Task.Run(() => File.Copy(src, dest, overwrite: true), ct);
                bytes?.Invoke(new FileInfo(dest).Length, new FileInfo(dest).Length);
                return;
            }
            await DownloadViaMirrorAsync(url, dest, bytes, ct);
        };

    public Task<InjectResultDto> ImprovementInstallAsync(string id) => ImprovementApplyAsync(id, install: true);
    public Task<InjectResultDto> ImprovementRemoveAsync(string id)  => ImprovementApplyAsync(id, install: false);

    private async Task<InjectResultDto> ImprovementApplyAsync(string id, bool install)
    {
        var catalog = await ImprovementCatalogAsync();
        var entry = catalog.FirstOrDefault(e => e.Id.Equals(id, StringComparison.OrdinalIgnoreCase));
        if (entry is null)
            return new InjectResultDto(false, $"Улучшения '{id}' нет в каталоге.", null);

        var gtaRoot = await GetGtaPathAsync();
        if (string.IsNullOrWhiteSpace(gtaRoot))
            return new InjectResultDto(false, "Не найдена папка GTA V.", null);

        string pretty = entry.Name;
        string key = "improvement:" + entry.Id;
        EmitInstallProgress(key, pretty, "downloading", 0, null,
            detailMessage: install ? Loc.T("progress.common.preparingInstall") : Loc.T("progress.improvement.removing"));

        var mgr = new Core.Services.ImprovementManagerService();
        var download = ImprovementDownloader();

        try
        {
            var res = install
                ? await mgr.InstallAsync(gtaRoot, entry, catalog, download,
                    (phase, pct, detail) => EmitInstallProgress(key, pretty, phase, pct, null, detailMessage: detail),
                    m => Debug.WriteLine(m), CancellationToken.None)
                : await mgr.RemoveAsync(gtaRoot, entry.Id, catalog, download,
                    (phase, pct, detail) => EmitInstallProgress(key, pretty, phase, pct, null, detailMessage: detail),
                    m => Debug.WriteLine(m), CancellationToken.None);

            if (!res.Success)
            {
                EmitInstallProgress(key, pretty, "error", 0, res.Message);
                return new InjectResultDto(false, res.Message, null);
            }

            var updateRpfPath = Path.Combine(gtaRoot!, "update", "update.rpf");
            await ReapplyZalazyIfEnabledAsync(updateRpfPath);
            await ReapplyGreenZoneIfEnabledAsync(updateRpfPath);
            await ReapplyRukzakIfEnabledAsync(updateRpfPath);
            await ReapplyCarLogosIfEnabledAsync(updateRpfPath);
            await ReapplyFastJoinIfEnabledAsync(updateRpfPath);
            await ReapplyBigMapIfEnabledAsync(updateRpfPath);
            await FixUpdateRpfAfterOverlayReapplyAsync(updateRpfPath);

            EmitInstallProgress(key, pretty, "done", 100, null, detailMessage: res.Message);

            if (install)
            {
                try { await _supabase.RpcVoidAsync("improvement_increment_downloads", new { p_id = entry.Id }); }
                catch (Exception ex) { Debug.WriteLine($"[improvements.increment] {entry.Id}: {ex.Message}"); }
            }

            return new InjectResultDto(true, null, null);
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[improvements] {id} CRASH: {ex.GetType().Name}: {ex.Message}\n{ex.StackTrace}");
            EmitInstallProgress(key, pretty, "error", 0, ex.Message);
            return new InjectResultDto(false, $"{ex.GetType().Name}: {ex.Message}", null);
        }
    }

    private async Task ReapplyNoTracerIfEnabledAsync(string gtaRoot)
    {
        try
        {
            var draft = ReadInstallState()?.CustomizationDraft;
            if (!(draft?.NoTracerEnabled ?? false)) return;
            var cats = NormalizeTracerCategories((draft?.NoTracerCategories ?? "")
                .Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries));
            bool keepSnipers = draft?.NoTracerKeepSnipers ?? false;
            var cacheDir = NoTracerCacheDir();
            try { if (Directory.Exists(cacheDir)) Directory.Delete(cacheDir, recursive: true); } catch { }
            var svc = new Core.Services.NoTracerInstallService();
            await Task.Run(() => svc.Apply(gtaRoot, cacheDir, cats, keepSnipers,
                p => Core.Services.PatchCustomizationSupport.GetCleanBytesForExactPath(gtaRoot, p)));
            Debug.WriteLine("[other.notracer] re-applied after rebuild");
        }
        catch (Exception ex) { Debug.WriteLine($"[other.notracer] re-apply failed (non-fatal): {ex.Message}"); }
    }

