                SizeBytes:         size,
                SourceRpfVersion:  string.Empty,
                UploadedBy:        string.Empty,
                UploadedAt:        DateTime.UtcNow,
                PreviewUrl:        previewUrl);

            await _supabase.UpsertWithServiceRoleAsync("library_components", new
            {
