    public Task<CurrentReticleInfoDto?> GetCurrentReticleInfoAsync() => Task.Run(() =>
    {
        try
        {
            var state = ReadInstallState();
            var draft = state?.CustomizationDraft;
            if (draft is null) return (CurrentReticleInfoDto?)null;
            var c = draft.Crosshair;
            if (c is null) return (CurrentReticleInfoDto?)null;
            if (c.Kind == "custom" && !string.IsNullOrWhiteSpace(c.CustomSpecJson))
            {
                string code = "";
                try
                {
                    using var doc = System.Text.Json.JsonDocument.Parse(c.CustomSpecJson!);
                    if (doc.RootElement.TryGetProperty("Code", out var el) ||
                        doc.RootElement.TryGetProperty("code", out el))
                        code = el.GetString() ?? "";
                }
                catch { }
                return (CurrentReticleInfoDto?)new CurrentReticleInfoDto("custom", code, "Свой прицел (KNK)");
            }
            if (c.Kind == "library" && !string.IsNullOrWhiteSpace(c.LibraryItemId))
            {
                var libId = c.LibraryItemId!;
                string name = "";
                try
                {
                    var rows = _supabase.SelectAsync<LibraryRow>(
                        "library_components",
                        $"select=id,name,type&id=eq.{Uri.EscapeDataString(libId)}").Result;
                    name = rows.FirstOrDefault()?.Name ?? "";
                }
                catch {  }
                return (CurrentReticleInfoDto?)new CurrentReticleInfoDto("library", libId, name);
            }
            if (c.Kind == "import" && !string.IsNullOrWhiteSpace(c.DonorReduxId))
            {
                var rid = c.DonorReduxId!;
                string name = rid;
                try { name = _catalog.GetByIdAsync(rid).Result?.Name ?? rid; }
                catch {  }
                return (CurrentReticleInfoDto?)new CurrentReticleInfoDto("redux", rid, name);
            }
            return (CurrentReticleInfoDto?)null;
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[getCurrentReticleInfo] FAIL: {ex.Message}");
            return (CurrentReticleInfoDto?)null;
        }
    });

    public async Task<InjectResultDto> ReduxResetCustomizationAsync(string part)
    {
        var what = (part ?? string.Empty).Trim().ToLowerInvariant();
        if (what is not ("crosshair" or "minimap" or "all"))
            return new InjectResultDto(false, $"Неизвестная часть '{part}'. Ожидается crosshair, minimap или all.", null);

        using var _mtx = await MiamiGraphics.Shell.Services.UpdateRpfMutex.AcquireAsync($"customization-reset:{what}");

        var state = ReadInstallState();
        var reduxId = string.IsNullOrWhiteSpace(state?.ReduxId) ? "vanilla" : state!.ReduxId;
        if (reduxId.Equals("vanilla", StringComparison.OrdinalIgnoreCase))
            return new InjectResultDto(false,
                "Редукс не установлен - возвращать не к чему. Поставь редукс, потом сбрасывай.", null);

        var stock = BuildDefaultDraft(reduxId, state!.VersionId);
        var draft = state.CustomizationDraft ?? stock;

        if (what is "crosshair" or "all") draft = draft with { Crosshair = stock.Crosshair };
        if (what is "minimap" or "all")   draft = draft with { Minimap   = stock.Minimap };

        var prettyName = what switch
        {
            "crosshair" => "Прицел: возврат к редуксу",
            "minimap"   => "Миникарта: возврат к редуксу",
            _           => "Возврат к редуксу",
        };
        var progressKey = $"customization-reset-{what}";

        Core.System.FeatureLog.Write(what == "minimap" ? "миникарта" : "прицел",
            $"сброс кастомизации ({what}) к стоку редукса {reduxId}");

        try
        {
            var result = await ReduxCustomizeApplyAsync(
                reduxId, draft,
                progressKeyOverride: progressKey,
                progressDisplayOverride: prettyName,
                alreadyLocked: true);

            if (result.Success && what is "minimap" or "all") ClearMinimapTweakBase();
            return result;
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[customization.reset] FAIL ({what}): {ex.GetType().Name}: {ex.Message}");
            return new InjectResultDto(false, $"Не удалось вернуть сток редукса: {ex.Message}", null);
        }
    }

    public Task<InjectResultDto> ReduxApplyReticleAsync(string source, string id)
        => ReduxApplyReticleAsync(source, id, null);

    public async Task<InjectResultDto> ReduxApplyReticleAsync(string source, string id, string? displayName)
    {
        if (string.IsNullOrWhiteSpace(source) || string.IsNullOrWhiteSpace(id))
            return new InjectResultDto(false, "source + id required.", null);
        if (!source.Equals("library", StringComparison.OrdinalIgnoreCase)
            && !source.Equals("redux", StringComparison.OrdinalIgnoreCase))
            return new InjectResultDto(false,
                $"Неизвестный источник прицела '{source}'. Свой прицел ставится через конструктор.", null);
        using var _mtx = await MiamiGraphics.Shell.Services.UpdateRpfMutex.AcquireAsync($"reticle-apply:{source}:{id}");

        var state = ReadInstallState();
        var reduxId = string.IsNullOrWhiteSpace(state?.ReduxId) ? "vanilla" : state!.ReduxId;
        var progressKey = $"reticle-swap-{source}-{id}";
        var prettyName = !string.IsNullOrWhiteSpace(displayName)
            ? $"Прицел: {displayName.Trim()}"
            : (source == "library"
                ? $"Прицел (library {id.Substring(0, Math.Min(id.Length, 12))})"
                : $"Прицел (редукс {id})");

        var gtaRoot = await GetGtaPathAsync();
        if (string.IsNullOrWhiteSpace(gtaRoot))
            return new InjectResultDto(false, "GTA не найдена. Укажи путь в Admin → Settings → Paths.", null);

        var updateRpf = Path.Combine(gtaRoot, "update", "update.rpf");
        if (!File.Exists(updateRpf))
            return new InjectResultDto(false, $"Не найден {updateRpf} - переустанови редукс.", null);

        var prevDraft = state?.CustomizationDraft;
        Debug.WriteLine($"[reticle.swap] router: prevDraft={(prevDraft is null ? "null" : "exists")}, "
                        + $"prevReduxId={prevDraft?.ReduxId ?? "<null>"}, stateReduxId={state?.ReduxId ?? "<null>"}");

        bool hasRealReduxInstalled = !string.IsNullOrWhiteSpace(state?.ReduxId)
            && !state!.ReduxId.Equals("vanilla", StringComparison.OrdinalIgnoreCase);

        if (hasRealReduxInstalled)
        {
            EmitInstallProgress(progressKey, prettyName, "starting", 1, null,
                detailMessage: Loc.T("progress.reticle.changing"));

            var baseDraft = prevDraft ?? BuildDefaultDraft(state!.ReduxId, state.VersionId);

            var nextCrosshair = new GenericSettingDto(
                Kind:           source == "library" ? "library" : "import",
                LibraryItemId:  source == "library" ? id : null,
                DonorReduxId:   source == "redux"   ? id : null,
                DonorVersionId: null);
            var nextDraft = baseDraft with { Crosshair = nextCrosshair };

            try
            {
                Debug.WriteLine($"[reticle.swap] routing through ReduxCustomizeApplyAsync (dedicated crosshair path) for reduxId={baseDraft.ReduxId}");
                var result = await ReduxCustomizeApplyAsync(
                    baseDraft.ReduxId, nextDraft,
                    progressKeyOverride: progressKey,
                    progressDisplayOverride: prettyName,
                    alreadyLocked: true);
                return result;
            }
            catch (Exception ex)
            {
                Debug.WriteLine($"[reticle.swap] customize-apply FAIL: {ex.Message}");
                EmitInstallProgress(progressKey, prettyName, "error", 0, ex.Message);
                return new InjectResultDto(false,
                    $"Не удалось переустановить сборку с новым прицелом: {ex.Message}", null);
            }
        }

        EmitInstallProgress(progressKey, prettyName, "starting", 1, null,
            detailMessage: Loc.T("progress.reticle.changing"));

        byte[] donorGfxBytes;
        string donorLabel;
        try
        {
            using var http = HttpClientFactory.CreateFragmenting(TimeSpan.FromMinutes(15));
            string donorRoot;
            if (source == "library")
            {
                EmitInstallProgress(progressKey, prettyName, "downloading", 10, null,
                    detailMessage: Loc.T("progress.reticle.downloading"));
                var root = await EnsureLibraryCachedAsync(id, "crosshair", http,
                    (_, pct, msg) => EmitInstallProgress(progressKey, prettyName, "downloading", pct >= 0 ? 10 + (pct / 4) : -1, null, detailMessage: msg),
                    progressBase: 0, progressSpan: 100);
                if (root is null)
                    return new InjectResultDto(false, "Не удалось скачать library-прицел.", null);
                donorRoot = root;
                donorLabel = $"library:{id}";
            }
            else if (source == "redux")
            {
                EmitInstallProgress(progressKey, prettyName, "downloading", 10, null,
                    detailMessage: Loc.T("progress.reticle.downloading"));
                var root = await EnsureDonorCachedAsync(id, "crosshair", http,
                    (_, pct, msg) => EmitInstallProgress(progressKey, prettyName, "downloading", pct >= 0 ? 10 + (pct / 4) : -1, null, detailMessage: msg),
                    null,
                    progressBase: 0, progressSpan: 100);
                if (root is null)
                    return new InjectResultDto(false, "Не удалось скачать донора-редукса.", null);
                donorRoot = root;
                donorLabel = $"redux:{id}";
            }
            else
            {
                return new InjectResultDto(false, $"Неизвестный source='{source}' (ожидался 'library' или 'redux').", null);
            }

            var compDir = Path.Combine(donorRoot, "components", "crosshair");
            string? donorGfxPath = FindDonorReticleGfxPath(compDir);
            if (donorGfxPath is null || !File.Exists(donorGfxPath))
                return new InjectResultDto(false, $"У донора {donorLabel} отсутствует hud_reticle.gfx.", null);
            donorGfxBytes = await File.ReadAllBytesAsync(donorGfxPath);
            Debug.WriteLine($"[reticle.swap] donor hud_reticle.gfx: {donorGfxBytes.Length} bytes from {donorLabel} ({Path.GetFileName(donorGfxPath)})");
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[reticle.swap] donor fetch FAIL: {ex.GetType().Name}: {ex.Message}");
            EmitInstallProgress(progressKey, prettyName, "error", 0, ex.Message);
            return new InjectResultDto(false, $"Ошибка получения донора: {ex.Message}", null);
        }

        EmitInstallProgress(progressKey, prettyName, "injecting", 80, null,
            detailMessage: Loc.T("progress.reticle.applying"));

        var rollbackPath = updateRpf + ".swap_rollback";
        await MakeRollbackPointAsync(updateRpf, rollbackPath, progressKey, prettyName,
            "injecting", new ProgressBand(80, 84), "reticle.swap");

        bool injected = false;
        bool checksumOk = true;
        Exception? lastErr = null;
        try
        {
            var outcome = await Task.Run(() =>
                InjectReticleIntoLiveArchive(updateRpf, donorGfxBytes, "reticle.swap"));
            injected   = outcome.Injected;
            checksumOk = outcome.ChecksumOk;
            lastErr    = outcome.Error;
        }
        catch (Exception ex) { lastErr = ex; }

        if (injected && !checksumOk)
        {
            bool restored = false;
            try
            {
                if (File.Exists(rollbackPath)) { File.Copy(rollbackPath, updateRpf, overwrite: true); restored = true; }
            }
            catch { }
            try { if (File.Exists(rollbackPath)) File.Delete(rollbackPath); } catch { }
            var fixMsg = "Прицел не применён: не удалось перешифровать update.rpf (ArchiveFix). " +
                         "Проверь, что антивирус не удалил файлы лаунчера, и переустанови лаунчер. " +
                         (restored
                             ? "Изменения откатились."
                             : "ВНИМАНИЕ: откат не удался - восстанови чистый update.rpf через настройки лаунчера перед игрой.");
            EmitInstallProgress(progressKey, prettyName, "error", 0, fixMsg);
            return new InjectResultDto(false, fixMsg, null);
        }

        if (!injected)
        {
            try { if (File.Exists(rollbackPath)) File.Copy(rollbackPath, updateRpf, overwrite: true); } catch { }
            try { if (File.Exists(rollbackPath)) File.Delete(rollbackPath); } catch { }
            var msg = lastErr?.Message ?? "Не нашёл hud_reticle.gfx ни в одном слое update.rpf.";
            EmitInstallProgress(progressKey, prettyName, "error", 0, msg);
            return new InjectResultDto(false, $"Не удалось внедрить прицел: {msg}", null);
        }
        try { if (File.Exists(rollbackPath)) File.Delete(rollbackPath); } catch { }

        try
        {
            var nextCrosshair = new GenericSettingDto(
                Kind:           source == "library" ? "library" : "import",
                LibraryItemId:  source == "library" ? id : null,
                DonorReduxId:   source == "redux"   ? id : null,
                DonorVersionId: null);

            var nextDraft = prevDraft is not null
                ? prevDraft with { Crosshair = nextCrosshair }
                : new CustomizationDraftDto(
                    ReduxId:       reduxId!,
                    BaseVersionId: state?.VersionId,
                    Bloodfx:       new GenericSettingDto("default", null, null, null),
                    Crosshair:     nextCrosshair,
                    Timecycle:     new GenericSettingDto("default", null, null, null),
                    Armor:         new GenericSettingDto("default", null, null, null),
                    Arena:         new GenericSettingDto("default", null, null, null),
                    Minimap:       new MinimapSettingDto(false, "#34D399", "#60A5FA", "16:9", "default", null, null, null, null),
                    Tracers:       new TracerSettingDto("default", null, null, 255, 255, 255, null));

            var postSha = await Task.Run(() => Services.FileShaCache.ComputeSha256Cached(updateRpf));
            string? persistedReduxId = !string.IsNullOrWhiteSpace(state?.ReduxId)
                ? state!.ReduxId
                : null;
            WriteInstallState(new InstallState
            {
                ReduxId            = persistedReduxId,
                VersionId          = state?.VersionId,
                PostInstallSha256  = postSha,
                InstalledAt        = DateTime.UtcNow,
                CustomizationDraft = nextDraft,
                CurrentArmorId     = state?.CurrentArmorId,
                CurrentArmorName   = state?.CurrentArmorName,
                CurrentArmorGlbUrl = state?.CurrentArmorGlbUrl,
                CurrentArmorKind   = state?.CurrentArmorKind,
            });
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[reticle.swap] state persist FAILED (non-fatal): {ex.Message}");
        }

        EmitInstallProgress(progressKey, prettyName, "done", 100, null,
            detailMessage: Loc.T("progress.reticle.replaced"));
        return new InjectResultDto(true,
            "Прицел подменён. Остальная кастомизация сохранена.", null);
    }

    private readonly record struct ReticleInjectOutcome(
        bool Injected, bool ChecksumOk, int Replaced, string Where,
        IReadOnlyList<string> Paths, Exception? Error);

    private static ReticleInjectOutcome InjectReticleIntoLiveArchive(
        string updateRpf, byte[] gfxBytes, string tag)
    {
        Exception? lastErr = null;

        try
        {
            int n = Core.Services.PatchCustomizationSupport.ReplaceFilesByContentInLiveArchive(
                updateRpf,
                name => name.EndsWith(".gfx", StringComparison.OrdinalIgnoreCase),
                Core.Services.ReticleBuilderService.LooksLikeReticleGfx,
                gfxBytes, out var okContent, out var paths);
            if (n > 0)
            {
                Debug.WriteLine($"[{tag}] content sweep replaced {n} reticle gfx (checksumOk={okContent}): {string.Join(" | ", paths)}");
                Core.System.FeatureLog.Write("прицел",
                    $"{tag}: по содержимому заменено копий {n}, перешифровка {(okContent ? "ок" : "НЕ УДАЛАСЬ")}. " +
                    $"Пути: {(paths.Count > 0 ? string.Join(" | ", paths) : "(не отданы)")}");
                return new ReticleInjectOutcome(true, okContent, n, "content", paths, null);
            }
            Debug.WriteLine($"[{tag}] content sweep found no reticle-like .gfx - falling back to name/canonical");
            Core.System.FeatureLog.Write("прицел",
                $"{tag}: по содержимому не нашлось ни одного прицелоподобного .gfx - иду по имени hud_reticle.gfx");
        }
        catch (Exception ex)
        {
            lastErr = ex;
            Debug.WriteLine($"[{tag}] content sweep failed: {ex.Message}");
            Core.System.FeatureLog.Write("прицел", $"{tag}: проход по содержимому сорвался", ex);
        }

        try
        {
            int n = Core.Services.PatchCustomizationSupport.ReplaceAllMatchingFilesInLiveArchive(
                updateRpf, "hud_reticle.gfx", gfxBytes, out var okName);
            if (n > 0)
            {
                Debug.WriteLine($"[{tag}] name sweep replaced {n} (checksumOk={okName})");
                Core.System.FeatureLog.Write("прицел",
                    $"{tag}: по имени заменено копий {n}, перешифровка {(okName ? "ок" : "НЕ УДАЛАСЬ")}");
                return new ReticleInjectOutcome(true, okName, n, "name", Array.Empty<string>(), null);
            }
            Core.System.FeatureLog.Write("прицел", $"{tag}: по имени hud_reticle.gfx тоже ничего не заменено");
        }
        catch (Exception ex)
        {
            lastErr = ex;
            Debug.WriteLine($"[{tag}] name sweep failed: {ex.Message}");
            Core.System.FeatureLog.Write("прицел", $"{tag}: проход по имени сорвался", ex);
        }

        foreach (var path in Core.Services.ReticleBuilderService.DefaultTargetPaths)
        {
            try
            {
                bool okPath = Core.Services.PatchCustomizationSupport.ReplaceFileInLiveArchive(
                    updateRpf, path, gfxBytes);
                Debug.WriteLine($"[{tag}] canonical '{path}' (checksumOk={okPath})");
                return new ReticleInjectOutcome(true, okPath, 1, "canonical", new[] { path }, null);
            }
            catch (Exception ex)
            {
                lastErr = ex;
                Debug.WriteLine($"[{tag}] canonical '{path}' failed: {ex.Message}");
            }
        }

        return new ReticleInjectOutcome(false, true, 0, "none", Array.Empty<string>(), lastErr);
    }

    public async Task<InjectResultDto> ReticleApplyCustomAsync(ReticleSpecDto spec)
    {
        if (spec is null)
            return new InjectResultDto(false, "spec required.", null);
        using var _mtx = await MiamiGraphics.Shell.Services.UpdateRpfMutex.AcquireAsync("reticle-custom");

        var state = ReadInstallState();
        var reduxId = string.IsNullOrWhiteSpace(state?.ReduxId) ? "vanilla" : state!.ReduxId;
        const string progressKey = "reticle-custom";
        const string prettyName = "Прицел: свой (KNK)";

        var gtaRoot = await GetGtaPathAsync();
        if (string.IsNullOrWhiteSpace(gtaRoot))
            return new InjectResultDto(false, "GTA не найдена. Укажи путь в настройках.", null);
        var updateRpf = Path.Combine(gtaRoot, "update", "update.rpf");
        if (!File.Exists(updateRpf))
            return new InjectResultDto(false, $"Не найден {updateRpf}.", null);

        EmitInstallProgress(progressKey, prettyName, "starting", 2, null,
            detailMessage: Loc.T("progress.reticle.preparingBuild"));

        var notes = new List<string>();
        var customBytes = await BuildCustomReticleGfxAsync(gtaRoot, spec, notes,
            msg => EmitInstallProgress(progressKey, prettyName, "injecting", 35, null, detailMessage: msg));
        if (customBytes is null)
        {
            var err = notes.Count > 0 ? string.Join(" ", notes) : "Сборка прицела не удалась.";
            EmitInstallProgress(progressKey, prettyName, "error", 0, err);
            return new InjectResultDto(false, err, null);
        }
        Debug.WriteLine($"[reticle.custom] built gfx: {customBytes.Length} bytes");

        EmitInstallProgress(progressKey, prettyName, "injecting", 80, null,
            detailMessage: Loc.T("progress.reticle.embedding"));

        var rollbackPath = updateRpf + ".swap_rollback";
        await MakeRollbackPointAsync(updateRpf, rollbackPath, progressKey, prettyName,
            "injecting", new ProgressBand(80, 84), "reticle.custom");

        bool injected = false;
        bool checksumOk = true;
        Exception? lastErr = null;
        try
        {
            var outcome = await Task.Run(() =>
                InjectReticleIntoLiveArchive(updateRpf, customBytes, "reticle.custom"));
            injected   = outcome.Injected;
            checksumOk = outcome.ChecksumOk;
            lastErr    = outcome.Error;
        }
        catch (Exception ex) { lastErr = ex; }

        if (injected && !checksumOk)
        {
            bool restored = false;
            try
            {
                if (File.Exists(rollbackPath)) { File.Copy(rollbackPath, updateRpf, overwrite: true); restored = true; }
            }
            catch { }
            try { if (File.Exists(rollbackPath)) File.Delete(rollbackPath); } catch { }
            var fixMsg = "Прицел не применён: не удалось перешифровать update.rpf (ArchiveFix). " +
                         (restored ? "Изменения откатились." : "ВНИМАНИЕ: откат не удался - восстанови чистый update.rpf.");
            EmitInstallProgress(progressKey, prettyName, "error", 0, fixMsg);
            return new InjectResultDto(false, fixMsg, null);
        }
        if (!injected)
        {
            try { if (File.Exists(rollbackPath)) File.Copy(rollbackPath, updateRpf, overwrite: true); } catch { }
            try { if (File.Exists(rollbackPath)) File.Delete(rollbackPath); } catch { }
            var msg = lastErr?.Message ?? "hud_reticle.gfx не найден в update.rpf.";
            EmitInstallProgress(progressKey, prettyName, "error", 0, msg);
            return new InjectResultDto(false, $"Не удалось вшить прицел: {msg}", null);
        }
        try { if (File.Exists(rollbackPath)) File.Delete(rollbackPath); } catch { }

        try
        {
            var specJson = System.Text.Json.JsonSerializer.Serialize(spec);
            var nextCrosshair = new GenericSettingDto("custom", null, null, null, null, specJson);

            var prevDraft = state?.CustomizationDraft;
            var nextDraft = prevDraft is not null
                ? prevDraft with { Crosshair = nextCrosshair }
                : new CustomizationDraftDto(
                    ReduxId:       reduxId!,
                    BaseVersionId: state?.VersionId,
                    Bloodfx:       new GenericSettingDto("default", null, null, null),
                    Crosshair:     nextCrosshair,
                    Timecycle:     new GenericSettingDto("default", null, null, null),
                    Armor:         new GenericSettingDto("default", null, null, null),
                    Arena:         new GenericSettingDto("default", null, null, null),
                    Minimap:       new MinimapSettingDto(false, "#34D399", "#60A5FA", "16:9", "default", null, null, null, null),
                    Tracers:       new TracerSettingDto("default", null, null, 255, 255, 255, null));

            var postSha = await Task.Run(() => Services.FileShaCache.ComputeSha256Cached(updateRpf));
            WriteInstallState(new InstallState
            {
                ReduxId            = !string.IsNullOrWhiteSpace(state?.ReduxId) ? state!.ReduxId : null,
                VersionId          = state?.VersionId,
                PostInstallSha256  = postSha,
                InstalledAt        = DateTime.UtcNow,
                CustomizationDraft = nextDraft,
                CurrentArmorId     = state?.CurrentArmorId,
                CurrentArmorName   = state?.CurrentArmorName,
                CurrentArmorGlbUrl = state?.CurrentArmorGlbUrl,
                CurrentArmorKind   = state?.CurrentArmorKind,
            });
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[reticle.custom] state persist FAILED (non-fatal): {ex.Message}");
        }

        EmitInstallProgress(progressKey, prettyName, "done", 100, null,
            detailMessage: Loc.T("progress.reticle.customEmbedded"));
        return new InjectResultDto(true, "Свой прицел вшит в update.rpf.", null);
    }

    private async Task<byte[]?> BuildCustomReticleGfxAsync(
        string gtaRoot, ReticleSpecDto spec, List<string> notes, Action<string>? detail = null)
    {
        var (javaCandidate, ffdecJar, _) = ResolveMinimapTools();
        var javaExe = await EnsureMinimapJavaAsync(javaCandidate, notes, (_, _, msg) =>
        {
            if (msg != null) detail?.Invoke(msg);
        });
        if (javaExe is null)
        {
            notes.Add("[Прицел] Java не установилась - сборка кастомного прицела невозможна.");
            return null;
        }
        if (ffdecJar is null || !File.Exists(ffdecJar))
        {
            notes.Add("[Прицел] ffdec.jar не найден (additionals/minimap) - переустанови лаунчер.");
            return null;
        }

        detail?.Invoke("Достаю базовый прицел...");
        byte[]? baseGfx = null;

        var cleanCandidates = new List<string?> { GetLocalCleanRpfPath() };
        try { cleanCandidates.Add((await _adminConfig.GetAsync()).CleanUpdateRpfPath); } catch { }
        foreach (var rpf in cleanCandidates)
        {
            if (string.IsNullOrWhiteSpace(rpf) || !File.Exists(rpf)) continue;
            foreach (var p in Core.Services.ReticleBuilderService.DefaultTargetPaths)
            {
                var b = await Task.Run(() =>
                    Core.Services.PatchCustomizationSupport.GetBytesFromArchiveExactPath(rpf!, p));
                if (b is { Length: > 10_000 }) { baseGfx = b; break; }
            }
            if (baseGfx is not null) break;
        }

        if (baseGfx is null)
        {
            baseGfx = await Task.Run(() => Core.Services.PatchCustomizationSupport.GetCleanOriginalBytes(
                gtaRoot, Core.Services.ReticleBuilderService.DefaultTargetPaths));
            if (baseGfx is not null)
                Debug.WriteLine("[reticle.build] clean backup unavailable - building from LIVE update.rpf");
        }
        if (baseGfx is null)
        {
            notes.Add("[Прицел] hud_reticle.gfx не найден ни в бэкапе, ни в update.rpf.");
            return null;
        }

        detail?.Invoke("Собираю прицел (ffdec)...");
        var buildSpec = new Core.Services.ReticleBuildSpec(
            spec.Dot, spec.DotSize, spec.Gap, spec.Length, spec.Thickness, spec.Tilt,
            spec.Outline, spec.OutlineWidth, spec.Opacity, spec.Scale,
            spec.ColorMain, spec.ColorAds, spec.Permanent, spec.HipfireSeconds,
            spec.Ring, spec.RingRadius, spec.RingThickness);

        Dictionary<string, Core.Services.ReticleBuildSpec>? weaponSpecs = null;
        if (spec.WeaponOverrides is { Length: > 0 })
        {
            weaponSpecs = new(StringComparer.OrdinalIgnoreCase);
            foreach (var o in spec.WeaponOverrides)
            {
                if (o is null || string.IsNullOrWhiteSpace(o.Weapon)) continue;
                weaponSpecs[o.Weapon.Trim()] = new Core.Services.ReticleBuildSpec(
                    o.Dot, o.DotSize, o.Gap, o.Length, o.Thickness, o.Tilt,
                    o.Outline, o.OutlineWidth, spec.Opacity, spec.Scale,
                    string.IsNullOrWhiteSpace(o.ColorMain) ? spec.ColorMain : o.ColorMain!,
                    spec.ColorAds, spec.Permanent, spec.HipfireSeconds,
                    o.Ring, o.RingRadius, o.RingThickness);
            }
        }

        var (bytes, err) = await Task.Run(() =>
        {
            var b = new Core.Services.ReticleBuilderService()
                .Build(baseGfx, buildSpec, weaponSpecs, javaExe, ffdecJar, out var e);
            return (b, e);
        });
        if (bytes is null)
            notes.Add($"[Прицел] Сборка не удалась: {err}");
        return bytes;
    }

#if ADMIN
    public async Task<LibraryComponentDto> AdminCreateLibraryReticleAsync(
        string name, string author, string description, string gfxPath, string photoPath)
    {
        if (string.IsNullOrWhiteSpace(name))
            throw new ArgumentException("name required", nameof(name));
        if (string.IsNullOrWhiteSpace(gfxPath) || !File.Exists(gfxPath))
            throw new ArgumentException("hud_reticle.gfx path required + must exist", nameof(gfxPath));
        if (string.IsNullOrWhiteSpace(photoPath) || !File.Exists(photoPath))
            throw new ArgumentException("photo path required + must exist", nameof(photoPath));

        var gfxExt = Path.GetExtension(gfxPath).ToLowerInvariant();
        if (gfxExt != ".gfx")
            throw new ArgumentException(".gfx file required (Scaleform bytecode)", nameof(gfxPath));

        var photoExt = Path.GetExtension(photoPath).ToLowerInvariant();
        if (photoExt != ".png" && photoExt != ".jpg" && photoExt != ".jpeg" && photoExt != ".webp")
            throw new ArgumentException("photo must be .png / .jpg / .webp", nameof(photoPath));

        var libraryId = $"libret_{Guid.NewGuid().ToString("N")[..8]}";
        var stagingRoot = Path.Combine(Path.GetTempPath(), $"hg_libret_{libraryId}");
        var componentDir = Path.Combine(stagingRoot, "components", "crosshair");
        Directory.CreateDirectory(componentDir);

        var dstGfx = Path.Combine(componentDir, "hud_reticle.gfx");
        File.Copy(gfxPath, dstGfx, overwrite: true);

        var zipPath = Path.Combine(Path.GetTempPath(), $"{libraryId}.zip");
        try { if (File.Exists(zipPath)) File.Delete(zipPath); } catch { }
        try
        {
            System.IO.Compression.ZipFile.CreateFromDirectory(
                componentDir, zipPath,
                System.IO.Compression.CompressionLevel.Optimal,
                includeBaseDirectory: false);

            var size = new FileInfo(zipPath).Length;
            var sha  = await Task.Run(() => ComputeFileSha256(zipPath));

            var zipKey = $"library/crosshair/{libraryId}.zip";
            Debug.WriteLine($"[admin.createLibraryReticle] zip → {zipKey} ({size / 1024} KB)");
            var zipUrl = await _remoteStorage.UploadAsync(zipPath, zipKey, progress: null, CancellationToken.None);

            var photoKey = $"library/crosshair/{libraryId}__preview{photoExt}";
            var previewUrl = await _remoteStorage.UploadAsync(photoPath, photoKey, progress: null, CancellationToken.None);
            Debug.WriteLine($"[admin.createLibraryReticle] preview → {previewUrl}");

            var dto = new LibraryComponentDto(
                Id:                libraryId,
                Type:              "crosshair",
                Name:              name.Trim(),
                Author:            (author ?? string.Empty).Trim(),
                Description:       (description ?? string.Empty).Trim(),
                R2Url:             zipUrl,
                Sha256:            sha,
                SizeBytes:         size,
                SourceRpfVersion:  string.Empty,
                UploadedBy:        string.Empty,
                UploadedAt:        DateTime.UtcNow,
                PreviewUrl:        previewUrl);

            await _supabase.UpsertWithServiceRoleAsync("library_components", new
            {
                id                  = dto.Id,
                type                = dto.Type,
                name                = dto.Name,
                author              = dto.Author,
                description         = dto.Description,
                r2_url              = dto.R2Url,
                sha256              = dto.Sha256,
                size_bytes          = dto.SizeBytes,
                source_rpf_version  = dto.SourceRpfVersion,
                uploaded_by         = dto.UploadedBy,
                preview_url         = dto.PreviewUrl,
            }, await AdminServiceKeyAsync());
            return dto;
        }
        finally
        {
            try { if (File.Exists(zipPath))    File.Delete(zipPath); } catch {  }
            try { if (Directory.Exists(stagingRoot)) Directory.Delete(stagingRoot, recursive: true); }
            catch {  }
        }
    }
#endif

    private static string GetSoundsBackupDir()
    {
        var localAppData = Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData);
        var dir = Path.Combine(localAppData, "MiamiGraphics", "sounds_backup");
        Directory.CreateDirectory(dir);
        return dir;
    }

    public Task<CurrentSoundPackInfoDto?> GetCurrentSoundPackInfoAsync() => Task.Run(() =>
    {
        try
        {
            var state = ReadInstallState();
            if (state is null) return (CurrentSoundPackInfoDto?)null;
            if (string.IsNullOrWhiteSpace(state.CurrentSoundPackId))
                return (CurrentSoundPackInfoDto?)null;
            return (CurrentSoundPackInfoDto?)new CurrentSoundPackInfoDto(
                state.CurrentSoundPackId,
                state.CurrentSoundPackName ?? state.CurrentSoundPackId);
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[getCurrentSoundPackInfo] FAIL: {ex.Message}");
            return (CurrentSoundPackInfoDto?)null;
        }
    });

    public Task<InjectResultDto> SoundPackInstallAsync(string libraryId)
        => SoundPackInstallAsync(libraryId, null);

    public async Task<InjectResultDto> SoundPackInstallAsync(string libraryId, string? displayName)
    {
        if (string.IsNullOrWhiteSpace(libraryId))
            return new InjectResultDto(false, "libraryId required.", null);
        using var _mtx = await MiamiGraphics.Shell.Services.UpdateRpfMutex.AcquireAsync($"sound-install:{libraryId}");

        var progressKey = $"sounds-install-{libraryId}";
        var prettyName = !string.IsNullOrWhiteSpace(displayName)
            ? $"Звуки: {displayName.Trim()}"
            : $"Звуки (library {libraryId.Substring(0, Math.Min(libraryId.Length, 12))})";

        var gtaRoot = await GetGtaPathAsync();
        if (string.IsNullOrWhiteSpace(gtaRoot))
            return new InjectResultDto(false, "GTA не найдена. Укажи путь в Admin → Settings → Paths.", null);

        var awcInfo = await TryFetchAwcSoundAsync(libraryId);
        if (awcInfo is not null)
            return await AwcSoundInstallAsync(libraryId, displayName, gtaRoot, awcInfo, progressKey, prettyName);

        var sfxDir = Path.Combine(gtaRoot, "x64", "audio", "sfx");
        if (!Directory.Exists(sfxDir))
            return new InjectResultDto(false, $"Не найден {sfxDir} - проверь установку GTA.", null);

        EmitInstallProgress(progressKey, prettyName, "starting", 1, null,
            detailMessage: Loc.T("progress.common.preparingInstall"));

        var prevState = ReadInstallState();
        var backupDir = GetSoundsBackupDir();
        await RestorePreviousSoundPackAsync(prevState, gtaRoot, progressKey, prettyName);

        string cacheRoot;
        try
        {
            using var http = HttpClientFactory.CreateFragmenting(TimeSpan.FromMinutes(15));
            EmitInstallProgress(progressKey, prettyName, "downloading", 15, null,
                detailMessage: Loc.T("progress.gunpack.downloadingPack"));
            var root = await EnsureLibraryCachedAsync(libraryId, "sounds", http,
                (_, pct, msg) => EmitInstallProgress(progressKey, prettyName, "downloading", pct >= 0 ? 15 + (pct / 3) : -1, null, detailMessage: msg),
                progressBase: 0, progressSpan: 100);
            if (root is null)
                return new InjectResultDto(false, "Не удалось скачать пак звуков.", null);
            cacheRoot = root;
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[sounds.install] download FAIL: {ex.GetType().Name}: {ex.Message}");
            EmitInstallProgress(progressKey, prettyName, "error", 0, ex.Message);
            return new InjectResultDto(false, $"Ошибка загрузки пака: {ex.Message}", null);
        }

        var packRpfs = new List<string>();
        try
        {
            packRpfs.AddRange(Directory.EnumerateFiles(cacheRoot, "*.rpf", SearchOption.AllDirectories));
        }
        catch (Exception ex)
        {
            return new InjectResultDto(false, $"Не удалось прочитать содержимое пака: {ex.Message}", null);
        }
        if (packRpfs.Count == 0)
            return new InjectResultDto(false, "В паке не найдено ни одного .rpf файла.", null);

        var fileMap = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        foreach (var src in packRpfs)
        {
            var name = Path.GetFileName(src);
            if (string.IsNullOrWhiteSpace(name)) continue;
            fileMap[name] = src;
        }

        EmitInstallProgress(progressKey, prettyName, "injecting", 60, null,
            detailMessage: Loc.T("progress.gunpack.applyingSounds", ("count", fileMap.Count)));

        var installedFiles = new List<string>();
        var skippedFiles  = new List<string>();
        foreach (var (fname, srcPath) in fileMap)
        {
            var live = Path.Combine(sfxDir, fname);
            var backup = Path.Combine(backupDir, fname);
            if (!File.Exists(live))
            {

                skippedFiles.Add(fname);
                Debug.WriteLine($"[sounds.install] skipping {fname} - not present in vanilla sfx folder");
                continue;
            }
            try
            {
                if (!File.Exists(backup))
                {
                    File.Copy(live, backup, overwrite: false);
                    Debug.WriteLine($"[sounds.install] backed up {fname}");
                }
                File.Copy(srcPath, live, overwrite: true);
                installedFiles.Add(fname);
            }
            catch (Exception ex)
            {
                Debug.WriteLine($"[sounds.install] failed to install {fname}: {ex.Message}");
                skippedFiles.Add(fname);
            }
        }

        if (installedFiles.Count == 0)
        {
            EmitInstallProgress(progressKey, prettyName, "error", 0,
                "Ни один файл из пака не подошёл к структуре GTA.");
            return new InjectResultDto(false,
                "Ни один файл из пака не подошёл к структуре GTA. Проверь содержимое .zip - внутри должны быть .rpf файлы из x64/audio/sfx.",
                null);
        }

        try
        {
            var libraryRow = await TryFetchLibraryRowAsync(libraryId);
            var name = !string.IsNullOrWhiteSpace(displayName)
                ? displayName!
                : (libraryRow?.Name ?? libraryId);

            var state = ReadInstallState() ?? new InstallState();
            state.CurrentSoundPackId    = libraryId;
            state.CurrentSoundPackName  = name;
            state.CurrentSoundPackFiles = installedFiles;
            WriteInstallState(state);
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[sounds.install] state persist FAILED (non-fatal): {ex.Message}");
        }

        EmitInstallProgress(progressKey, prettyName, "done", 100, null,
            detailMessage: Loc.T("progress.gunpack.soundsApplied", ("count", installedFiles.Count)));

        var detail = skippedFiles.Count > 0
            ? $". Пропущено {skippedFiles.Count} файл(ов), не входящих в стандартную структуру GTA: " + string.Join(", ", skippedFiles.Take(5))
            : "";
        return new InjectResultDto(true,
            $"Установлено {installedFiles.Count} звуковых файла(ов){detail}.", null);
    }

    public async Task<InjectResultDto> SoundPackUninstallAsync()
    {
        var state = ReadInstallState();
        if (state is null || string.IsNullOrWhiteSpace(state.CurrentSoundPackId))
            return new InjectResultDto(true, "Сейчас активны стоковые звуки - откатывать нечего.", null);

        var gtaRoot = await GetGtaPathAsync();
        if (string.IsNullOrWhiteSpace(gtaRoot))
            return new InjectResultDto(false, "GTA не найдена.", null);

        if (string.Equals(state.CurrentSoundPackKind, "awc", StringComparison.OrdinalIgnoreCase))
            return await AwcSoundUninstallAsync(state, gtaRoot);

        var sfxDir = Path.Combine(gtaRoot, "x64", "audio", "sfx");
        var backupDir = GetSoundsBackupDir();
        var files = state.CurrentSoundPackFiles ?? new List<string>();

        var progressKey = "sounds-uninstall";
        var prettyName  = $"Звуки: восстановление";
        EmitInstallProgress(progressKey, prettyName, "starting", 10, null,
            detailMessage: Loc.T("progress.gunpack.restoringStock"));

        int restored = 0;
        foreach (var fname in files)
        {
            var safeName = Path.GetFileName(fname);
            if (string.IsNullOrWhiteSpace(safeName)) continue;
            var backup = Path.Combine(backupDir, safeName);
            var live   = Path.Combine(sfxDir,   safeName);
            if (!File.Exists(backup)) continue;
            try
            {
                File.Copy(backup, live, overwrite: true);
                restored++;
            }
            catch (Exception ex)
            {
                Debug.WriteLine($"[sounds.uninstall] failed to restore {safeName}: {ex.Message}");
            }
        }

        try
        {
            state.CurrentSoundPackId    = null;
            state.CurrentSoundPackName  = null;
            state.CurrentSoundPackFiles = null;
            WriteInstallState(state, preserveSoundPack: false);
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[sounds.uninstall] state clear FAILED: {ex.Message}");
        }

        EmitInstallProgress(progressKey, prettyName, "done", 100, null,
            detailMessage: Loc.T("progress.gunpack.stockRestored", ("count", restored)));
        return new InjectResultDto(true,
            $"Возвращены стоковые звуки ({restored} файла(ов)).", null);
    }

    private sealed record AwcSoundInfo(string FileName, string R2Url, string? Name, string? Sha256);

    private sealed class AwcRow
    {
        public string? AwcFilename { get; set; }
        public string? R2Url       { get; set; }
        public string? Name        { get; set; }
        public string? Sha256      { get; set; }
    }

    private static string GetAwcBackupDir()
    {
        var localAppData = Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData);
        var dir = Path.Combine(localAppData, "MiamiGraphics", "sounds_backup", "awc");
        Directory.CreateDirectory(dir);
        return dir;
    }

    private static string AwcHostMapPath() => Path.Combine(GetAwcBackupDir(), "_hostmap.json");

    private static Dictionary<string, string> ReadAwcHostMap()
    {
        try
        {
            var p = AwcHostMapPath();
            if (!File.Exists(p)) return new(StringComparer.OrdinalIgnoreCase);
            return System.Text.Json.JsonSerializer.Deserialize<Dictionary<string, string>>(File.ReadAllText(p))
                   ?? new(StringComparer.OrdinalIgnoreCase);
        }
        catch { return new(StringComparer.OrdinalIgnoreCase); }
    }

    private static void WriteAwcHostMap(Dictionary<string, string> map)
    {
        try { File.WriteAllText(AwcHostMapPath(), System.Text.Json.JsonSerializer.Serialize(map)); }
        catch { }
    }

    private string? ResolveAwcHostArchive(string gtaRoot, string fileName, string progressKey, string prettyName)
    {
        string RelOf(string abs) => Path.GetRelativePath(gtaRoot, abs).Replace('\\', '/');
        bool Hosts(string abs) => File.Exists(abs)
            && Core.Services.PatchCustomizationSupport.AudioSubtreeContainsFile(abs, fileName);

        var map = ReadAwcHostMap();
        if (map.TryGetValue(fileName, out var relCached))
        {
            var abs = Path.Combine(gtaRoot, relCached.Replace('/', Path.DirectorySeparatorChar));
            if (Hosts(abs)) return abs;
        }

        var updateRpf = Path.Combine(gtaRoot, "update", "update.rpf");
        if (Hosts(updateRpf)) { map[fileName] = RelOf(updateRpf); WriteAwcHostMap(map); return updateRpf; }

        var dlcRoot = Path.Combine(gtaRoot, "update", "x64", "dlcpacks");
        if (Directory.Exists(dlcRoot))
        {
            var dlcs = Directory.EnumerateFiles(dlcRoot, "dlc.rpf", SearchOption.AllDirectories).ToList();
            for (int i = 0; i < dlcs.Count; i++)
            {
                var pack = Path.GetFileName(Path.GetDirectoryName(dlcs[i])) ?? "";
                EmitInstallProgress(progressKey, prettyName, "downloading", 8, null,
                    detailMessage: Loc.T("progress.gunpack.searchingSoundInDlc",
                        ("index", i + 1), ("total", dlcs.Count), ("pack", pack)));
                if (Hosts(dlcs[i])) { map[fileName] = RelOf(dlcs[i]); WriteAwcHostMap(map); return dlcs[i]; }
            }
        }
        return null;
    }

    private string? ResolveStoredAwcHost(string gtaRoot, string? archiveRel, string fileName,
        string progressKey, string prettyName)
    {
        if (!string.IsNullOrWhiteSpace(archiveRel))
        {
            var abs = Path.Combine(gtaRoot, archiveRel!.Replace('/', Path.DirectorySeparatorChar));
            if (File.Exists(abs)) return abs;
        }
        return ResolveAwcHostArchive(gtaRoot, fileName, progressKey, prettyName)
               ?? Path.Combine(gtaRoot, "update", "update.rpf");
    }

    private async Task<AwcSoundInfo?> TryFetchAwcSoundAsync(string libraryId)
    {
        try
        {
            var rows = await _supabase.SelectAsync<AwcRow>(
                "library_components",
                $"select=awc_filename,r2_url,name,sha256&id=eq.{Uri.EscapeDataString(libraryId)}&limit=1");
            var row = rows.FirstOrDefault();
            if (row is null || string.IsNullOrWhiteSpace(row.AwcFilename)) return null;
            return new AwcSoundInfo(row.AwcFilename!.Trim(), row.R2Url ?? string.Empty, row.Name, row.Sha256);
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[awc.fetch] {ex.Message}");
            return null;
        }
    }

    private async Task RestorePreviousSoundPackAsync(
        InstallState? prevState, string gtaRoot, string progressKey, string prettyName)
    {
        if (prevState is null) return;

        if (string.Equals(prevState.CurrentSoundPackKind, "awc", StringComparison.OrdinalIgnoreCase))
        {
            var files = prevState.CurrentSoundPackFiles ?? new List<string>();
            if (files.Count == 0) return;
            var awcBackupDir = GetAwcBackupDir();
            var archiveRel = prevState.CurrentSoundPackArchiveRel;
            EmitInstallProgress(progressKey, prettyName, "starting", 5, null,
                detailMessage: Loc.T("progress.gunpack.restoringPrevSound"));
            await Task.Run(() =>
            {
                foreach (var fname in files)
                {
                    var safe = Path.GetFileName(fname);
                    if (string.IsNullOrWhiteSpace(safe)) continue;
                    var backup = Path.Combine(awcBackupDir, safe);
                    if (!File.Exists(backup)) continue;
                    var host = ResolveStoredAwcHost(gtaRoot, archiveRel, safe, progressKey, prettyName);
                    if (host is null || !File.Exists(host)) continue;
                    try
                    {
                        Core.Services.PatchCustomizationSupport.ReplaceAudioAwcInLiveArchive(
                            host, safe, File.ReadAllBytes(backup), out _, out _);
                    }
                    catch (Exception ex) { Debug.WriteLine($"[awc.restore-prev] {safe}: {ex.Message}"); }
                }
            });
            return;
        }

        if (prevState.CurrentSoundPackFiles is not { Count: > 0 } prevFiles) return;
        var sfxDir = Path.Combine(gtaRoot, "x64", "audio", "sfx");
        var backupDir = GetSoundsBackupDir();
        EmitInstallProgress(progressKey, prettyName, "starting", 5, null,
            detailMessage: Loc.T("progress.gunpack.restoringPrevSounds"));
        foreach (var fname in prevFiles)
        {
            var safeName = Path.GetFileName(fname);
            if (string.IsNullOrWhiteSpace(safeName)) continue;
            var backup = Path.Combine(backupDir, safeName);
            var live   = Path.Combine(sfxDir, safeName);
            if (File.Exists(backup))
            {
                try { File.Copy(backup, live, overwrite: true); }
                catch (Exception ex) { Debug.WriteLine($"[sounds.install] failed to restore {safeName}: {ex.Message}"); }
            }
        }
    }

    private async Task<InjectResultDto> AwcSoundInstallAsync(
        string libraryId, string? displayName, string gtaRoot, AwcSoundInfo info,
        string progressKey, string prettyName)
    {
        var fileName = Path.GetFileName(info.FileName);
        if (string.IsNullOrWhiteSpace(fileName) || !fileName.EndsWith(".awc", StringComparison.OrdinalIgnoreCase))
            return new InjectResultDto(false, "Некорректное имя .awc в каталоге.", null);

        EmitInstallProgress(progressKey, prettyName, "starting", 1, null, detailMessage: Loc.T("progress.common.preparingInstall"));

        var prevState = ReadInstallState();
        await RestorePreviousSoundPackAsync(prevState, gtaRoot, progressKey, prettyName);

        EmitInstallProgress(progressKey, prettyName, "starting", 3, null, detailMessage: Loc.T("progress.gunpack.searchingSound"));
        var hostArchive = await Task.Run(() => ResolveAwcHostArchive(gtaRoot, fileName, progressKey, prettyName));
        if (hostArchive is null)
            return new InjectResultDto(false,
                $"Файл {fileName} не найден ни в update.rpf, ни в DLC-паках (dlcpacks). " +
                "Проверь, что имя .awc в каталоге совпадает с игровым.", null);

        string awcPath;
        try
        {
            EmitInstallProgress(progressKey, prettyName, "downloading", 35, null, detailMessage: Loc.T("progress.gunpack.downloadingSound"));
            var cacheDir = MiamiGraphics.Shell.Services.ModCacheSettings.Dir(CustomizeCacheRoot, "library", libraryId);
            awcPath = Path.Combine(cacheDir, fileName);
            if (string.IsNullOrWhiteSpace(info.R2Url))
                return new InjectResultDto(false, "У звука нет ссылки на файл.", null);
            await Services.VerifiedDownload.EnsureFileAsync(info.R2Url, awcPath, info.Sha256,
                info.Name ?? fileName,
                bytesProgress: (received, total) =>
                {
                    if (total > 0)
                    {
                        var pct = 35 + (int)Math.Min(20, received * 20 / total);
                        EmitInstallProgress(progressKey, prettyName, "downloading", pct, null,
                            detailMessage: DownloadCounterText(received, total));
                    }
                },
                hashProgress: (done, total) => EmitInstallProgress(progressKey, prettyName,
                    "downloading", 57, null,
                    detailMessage: Loc.T("progress.common.verifyingKb",
                        ("done", done / 1024), ("total", Math.Max(1, total / 1024)))));
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[awc.install] download FAIL: {ex.Message}");
            EmitInstallProgress(progressKey, prettyName, "error", 0, ex.Message);
            return new InjectResultDto(false, $"Ошибка загрузки звука: {ex.Message}", null);
        }

        var modBytes = await File.ReadAllBytesAsync(awcPath);
        var rollback = hostArchive + ".awc_rollback";
        var hostName = Path.GetFileName(hostArchive);
        int replaced = 0;
        byte[]? original = null;
        bool checksumOk = true;
        try
        {
            EmitInstallProgress(progressKey, prettyName, "injecting", 65, null,
                detailMessage: Loc.T("progress.gunpack.injectingSound", ("host", hostName)));

            File.Copy(hostArchive, rollback, overwrite: true);

            (replaced, original, checksumOk) = await Task.Run(() =>
            {
                var r = Core.Services.PatchCustomizationSupport.ReplaceAudioAwcInLiveArchive(
                    hostArchive, fileName, modBytes, out var orig, out var ok);
                return (r, orig, ok);
            });

            if (replaced == 0)
            {
                try { File.Copy(rollback, hostArchive, overwrite: true); } catch { }
                EmitInstallProgress(progressKey, prettyName, "error", 0, $"В {hostName} не найден {fileName}.");
                return new InjectResultDto(false,
                    $"В {hostName} не найден файл {fileName} - нечего заменять.", null);
            }

            try
            {
                var backupFile = Path.Combine(GetAwcBackupDir(), fileName);
                if (!File.Exists(backupFile) && original is not null)
                    await File.WriteAllBytesAsync(backupFile, original);
            }
            catch (Exception bex) { Debug.WriteLine($"[awc.install] backup FAIL: {bex.Message}"); }

            if (!checksumOk)
            {
                try { File.Copy(rollback, hostArchive, overwrite: true); } catch { }
                var msg = $"ArchiveFix не смог пересчитать checksum {hostName} после замены звука - установка отменена " +
                          "(иначе звук «установился бы», но игра его не подхватила бы). Попробуй ещё раз.";
                EmitInstallProgress(progressKey, prettyName, "error", 0, msg);
                return new InjectResultDto(false, msg, null);
            }
        }
        catch (Exception ex)
        {
            try { if (File.Exists(rollback)) File.Copy(rollback, hostArchive, overwrite: true); } catch { }
            Debug.WriteLine($"[awc.install] inject FAIL: {ex.Message}");
            EmitInstallProgress(progressKey, prettyName, "error", 0, ex.Message);
            return new InjectResultDto(false, $"Ошибка внедрения звука: {ex.Message}", null);
        }
        finally
        {
            try { if (File.Exists(rollback)) File.Delete(rollback); } catch { }
        }

        try
        {
            var name = !string.IsNullOrWhiteSpace(displayName) ? displayName! : (info.Name ?? libraryId);
            var state = ReadInstallState() ?? new InstallState();
            state.CurrentSoundPackId    = libraryId;
            state.CurrentSoundPackName  = name;
            state.CurrentSoundPackFiles = new List<string> { fileName };
            state.CurrentSoundPackKind  = "awc";
            state.CurrentSoundPackArchiveRel = Path.GetRelativePath(gtaRoot, hostArchive).Replace('\\', '/');
            WriteInstallState(state);
        }
        catch (Exception ex) { Debug.WriteLine($"[awc.install] state persist FAIL: {ex.Message}"); }

        EmitInstallProgress(progressKey, prettyName, "done", 100, null,
            detailMessage: Loc.T("progress.gunpack.soundApplied", ("count", replaced), ("host", hostName)));
        return new InjectResultDto(true, $"Звук установлен ({replaced} замен).", null);
    }

    private async Task<InjectResultDto> AwcSoundUninstallAsync(InstallState state, string gtaRoot)
    {
        var progressKey = "sounds-uninstall";
        var prettyName  = "Звуки: восстановление";
        EmitInstallProgress(progressKey, prettyName, "starting", 10, null,
            detailMessage: Loc.T("progress.gunpack.restoringStockSound"));

        var awcBackupDir = GetAwcBackupDir();
        await Task.Run(() =>
        {
            foreach (var fname in state.CurrentSoundPackFiles ?? new List<string>())
            {
                var safe = Path.GetFileName(fname);
                if (string.IsNullOrWhiteSpace(safe)) continue;
                var backup = Path.Combine(awcBackupDir, safe);
                if (!File.Exists(backup)) continue;
                var host = ResolveStoredAwcHost(gtaRoot, state.CurrentSoundPackArchiveRel, safe, progressKey, prettyName);
                if (host is null || !File.Exists(host)) continue;
                try
                {
                    Core.Services.PatchCustomizationSupport.ReplaceAudioAwcInLiveArchive(
                        host, safe, File.ReadAllBytes(backup), out _, out _);
                }
                catch (Exception ex) { Debug.WriteLine($"[awc.uninstall] {safe}: {ex.Message}"); }
            }
        });

        try
        {
            state.CurrentSoundPackId    = null;
            state.CurrentSoundPackName  = null;
            state.CurrentSoundPackFiles = null;
            state.CurrentSoundPackKind  = null;
            state.CurrentSoundPackArchiveRel = null;
            WriteInstallState(state, preserveSoundPack: false);
        }
        catch (Exception ex) { Debug.WriteLine($"[awc.uninstall] state clear FAIL: {ex.Message}"); }

        EmitInstallProgress(progressKey, prettyName, "done", 100, null, detailMessage: Loc.T("progress.gunpack.stockSoundRestored"));
        return new InjectResultDto(true, "Возвращён стоковый звук.", null);
    }

#if ADMIN
    public async Task<LibraryComponentDto> AdminCreateLibraryAwcSoundAsync(
        string name, string author, string description, string awcPath, string photoPath)
    {
        if (string.IsNullOrWhiteSpace(name))
            throw new ArgumentException("name required", nameof(name));
        if (string.IsNullOrWhiteSpace(awcPath) || !File.Exists(awcPath))
            throw new ArgumentException("awc path required + must exist", nameof(awcPath));
        if (!Path.GetExtension(awcPath).Equals(".awc", StringComparison.OrdinalIgnoreCase))
            throw new ArgumentException("нужен .awc файл", nameof(awcPath));

        bool hasPhoto = !string.IsNullOrWhiteSpace(photoPath);
        if (hasPhoto && !File.Exists(photoPath))
            throw new ArgumentException("photo path must exist when provided", nameof(photoPath));
        var photoExt = hasPhoto ? Path.GetExtension(photoPath).ToLowerInvariant() : string.Empty;
        if (hasPhoto && photoExt != ".png" && photoExt != ".jpg" && photoExt != ".jpeg" && photoExt != ".webp")
            throw new ArgumentException("photo must be .png / .jpg / .webp", nameof(photoPath));

        var awcFileName = Path.GetFileName(awcPath);
        var libraryId   = $"libsnd_{Guid.NewGuid().ToString("N")[..8]}";
        var size = new FileInfo(awcPath).Length;
        var sha  = await Task.Run(() => ComputeFileSha256(awcPath));

        var awcKey = $"library/sounds/{libraryId}.awc";
        Debug.WriteLine($"[admin.createLibraryAwc] awc → {awcKey} ({size / 1024} KB), match='{awcFileName}'");
        var awcUrl = await _remoteStorage.UploadAsync(awcPath, awcKey, progress: null, CancellationToken.None);

        string previewUrl = string.Empty;
        if (hasPhoto)
        {
            var photoKey = $"library/sounds/{libraryId}__preview{photoExt}";
            previewUrl = await _remoteStorage.UploadAsync(photoPath, photoKey, progress: null, CancellationToken.None);
        }

        var dto = new LibraryComponentDto(
            Id:                libraryId,
            Type:              "sounds",
            Name:              name.Trim(),
            Author:            (author ?? string.Empty).Trim(),
            Description:       (description ?? string.Empty).Trim(),
            R2Url:             awcUrl,
            Sha256:            sha,
            SizeBytes:         size,
            SourceRpfVersion:  string.Empty,
            UploadedBy:        string.Empty,
            UploadedAt:        DateTime.UtcNow,
            PreviewUrl:        previewUrl);

        await _supabase.UpsertWithServiceRoleAsync("library_components", new
        {
            id                  = dto.Id,
            type                = dto.Type,
            name                = dto.Name,
            author              = dto.Author,
            description         = dto.Description,
            r2_url              = dto.R2Url,
            sha256              = dto.Sha256,
            size_bytes          = dto.SizeBytes,
            source_rpf_version  = dto.SourceRpfVersion,
            uploaded_by         = dto.UploadedBy,
            preview_url         = dto.PreviewUrl,
            awc_filename        = awcFileName,
        }, await AdminServiceKeyAsync());
        return dto;
    }
#endif

#if ADMIN
    public async Task<LibraryComponentDto> AdminCreateLibrarySoundsAsync(
        string name, string author, string description, string zipPath, string photoPath)
    {
        if (string.IsNullOrWhiteSpace(name))
            throw new ArgumentException("name required", nameof(name));
        if (string.IsNullOrWhiteSpace(zipPath) || !File.Exists(zipPath))
            throw new ArgumentException("archive path required + must exist", nameof(zipPath));

        bool hasPhoto = !string.IsNullOrWhiteSpace(photoPath);
        if (hasPhoto && !File.Exists(photoPath))
            throw new ArgumentException("photo path must exist when provided", nameof(photoPath));

        var srcExt = Path.GetExtension(zipPath).ToLowerInvariant();
        if (srcExt != ".zip" && srcExt != ".rar")
            throw new ArgumentException(".zip или .rar архив (с .rpf файлами внутри)", nameof(zipPath));

        var photoExt = hasPhoto ? Path.GetExtension(photoPath).ToLowerInvariant() : string.Empty;
        if (hasPhoto
            && photoExt != ".png" && photoExt != ".jpg" && photoExt != ".jpeg" && photoExt != ".webp")
            throw new ArgumentException("photo must be .png / .jpg / .webp", nameof(photoPath));

        string uploadZipPath = zipPath;
        string? tempZipToCleanup = null;
        bool   sourceIsRar = srcExt == ".rar";

        try
        {

            if (sourceIsRar)
            {
                bool hasRpf = false;
                try
                {
                    using var rar = SharpCompress.Archives.Rar.RarArchive.Open(zipPath);
                    foreach (var entry in rar.Entries)
                    {
                        if (entry.IsDirectory) continue;
                        if (entry.Key?.EndsWith(".rpf", StringComparison.OrdinalIgnoreCase) == true)
                        {
                            hasRpf = true; break;
                        }
                    }
                }
                catch (Exception ex) when (ex is SharpCompress.Common.InvalidFormatException
                                          || ex is System.IO.InvalidDataException)
                {
                    throw new ArgumentException(".rar повреждён или не открывается.", nameof(zipPath));
                }
                if (!hasRpf)
                    throw new ArgumentException(
                        "В .rar не найдено ни одного .rpf файла - это не пак звуков.",
                        nameof(zipPath));

                tempZipToCleanup = Path.Combine(Path.GetTempPath(),
                    $"hg_sounds_repack_{Guid.NewGuid():N}.zip");
                await Task.Run(() => RepackRarToZip(zipPath, tempZipToCleanup!));
                uploadZipPath = tempZipToCleanup!;
                Debug.WriteLine($"[admin.createLibrarySounds] repacked .rar → .zip ({new FileInfo(uploadZipPath).Length / 1024} KB)");
            }
            else
            {
                try
                {
                    using var probe = System.IO.Compression.ZipFile.OpenRead(zipPath);
                    var hasRpf = probe.Entries.Any(e =>
                        e.FullName.EndsWith(".rpf", StringComparison.OrdinalIgnoreCase));
                    if (!hasRpf)
                        throw new ArgumentException(
                            "В .zip не найдено ни одного .rpf файла - это не пак звуков.",
                            nameof(zipPath));
                }
                catch (System.IO.InvalidDataException)
                {
                    throw new ArgumentException(".zip повреждён или не открывается.", nameof(zipPath));
                }
            }

            var libraryId = $"libsnd_{Guid.NewGuid().ToString("N")[..8]}";
            var size = new FileInfo(uploadZipPath).Length;
            var sha  = await Task.Run(() => ComputeFileSha256(uploadZipPath));

            var zipKey = $"library/sounds/{libraryId}.zip";
            Debug.WriteLine($"[admin.createLibrarySounds] zip → {zipKey} ({size / 1024} KB)");
            var zipUrl = await _remoteStorage.UploadAsync(uploadZipPath, zipKey, progress: null, CancellationToken.None);

            string previewUrl = string.Empty;
            if (hasPhoto)
            {
                var photoKey = $"library/sounds/{libraryId}__preview{photoExt}";
                previewUrl = await _remoteStorage.UploadAsync(photoPath, photoKey, progress: null, CancellationToken.None);
            }

            var dto = new LibraryComponentDto(
                Id:                libraryId,
                Type:              "sounds",
                Name:              name.Trim(),
                Author:            (author ?? string.Empty).Trim(),
                Description:       (description ?? string.Empty).Trim(),
                R2Url:             zipUrl,
                Sha256:            sha,
                SizeBytes:         size,
                SourceRpfVersion:  string.Empty,
                UploadedBy:        string.Empty,
                UploadedAt:        DateTime.UtcNow,
                PreviewUrl:        previewUrl);

            await _supabase.UpsertWithServiceRoleAsync("library_components", new
            {
                id                  = dto.Id,
                type                = dto.Type,
                name                = dto.Name,
                author              = dto.Author,
                description         = dto.Description,
                r2_url              = dto.R2Url,
                sha256              = dto.Sha256,
                size_bytes          = dto.SizeBytes,
                source_rpf_version  = dto.SourceRpfVersion,
                uploaded_by         = dto.UploadedBy,
                preview_url         = dto.PreviewUrl,
            }, await AdminServiceKeyAsync());
            return dto;
        }
        finally
        {
            if (tempZipToCleanup is not null)
            {
                try { if (File.Exists(tempZipToCleanup)) File.Delete(tempZipToCleanup); }
                catch (Exception ex) { Debug.WriteLine($"[admin.createLibrarySounds] temp zip cleanup FAIL: {ex.Message}"); }
            }
        }
    }
#endif

#if ADMIN
    private static void RepackRarToZip(string rarPath, string outputZipPath)
    {
        var stagingDir = Path.Combine(Path.GetTempPath(),
            $"hg_sounds_unpack_{Guid.NewGuid():N}");
        Directory.CreateDirectory(stagingDir);
        try
        {
            using (var rar = SharpCompress.Archives.Rar.RarArchive.Open(rarPath))
            {
                foreach (var entry in rar.Entries)
                {
                    if (entry.IsDirectory) continue;
                    if (string.IsNullOrEmpty(entry.Key)) continue;

                    var safe = entry.Key.Replace('\\', '/');
                    if (safe.Split('/').Any(seg => seg == "..")) continue;
                    var dst = Path.Combine(stagingDir, safe.Replace('/', Path.DirectorySeparatorChar));
                    Directory.CreateDirectory(Path.GetDirectoryName(dst)!);
                    using var es = entry.OpenEntryStream();
                    using var fs = File.Create(dst);
                    es.CopyTo(fs);
                }
            }

            if (File.Exists(outputZipPath)) File.Delete(outputZipPath);

            System.IO.Compression.ZipFile.CreateFromDirectory(
                stagingDir, outputZipPath,
                System.IO.Compression.CompressionLevel.Optimal,
                includeBaseDirectory: false);
        }
        finally
        {
            try { if (Directory.Exists(stagingDir)) Directory.Delete(stagingDir, recursive: true); }
            catch (Exception ex) { Debug.WriteLine($"[admin.repackRar] staging cleanup FAIL: {ex.Message}"); }
        }
    }
#endif

    private async Task<LibraryRow?> TryFetchLibraryRowAsync(string id)
    {
        try
        {
            var rows = await _supabase.SelectAsync<LibraryRow>(
                "library_components",
                $"select=*&id=eq.{Uri.EscapeDataString(id)}");
            return rows.FirstOrDefault();
        }
        catch { return null; }
    }

#if ADMIN
    public async Task<string> AdminUploadLibraryPreviewAsync(string libraryId, string sourcePath)
    {
        if (string.IsNullOrWhiteSpace(libraryId))
            throw new ArgumentException("libraryId required", nameof(libraryId));
        if (string.IsNullOrWhiteSpace(sourcePath) || !File.Exists(sourcePath))
            throw new ArgumentException("sourcePath required + must exist", nameof(sourcePath));

        var origExt = Path.GetExtension(sourcePath).ToLowerInvariant();
        if (origExt != ".png" && origExt != ".jpg" && origExt != ".jpeg" && origExt != ".webp")
            throw new ArgumentException("preview must be .png / .jpg / .webp", nameof(sourcePath));

        var rows = await _supabase.SelectAsync<LibraryRow>(
            "library_components",
            $"select=*&id=eq.{Uri.EscapeDataString(libraryId)}");
        var row = rows.FirstOrDefault()
            ?? throw new InvalidOperationException("Library component not found.");

        var (localPath, ext, isTemp) = await EnsureWebPAsync(sourcePath);
        try
        {
            var key = $"library/{row.Type}/{libraryId}__preview{ext}";
            var url = await _remoteStorage.UploadHashedAsync(localPath, key, progress: null, CancellationToken.None);
            _assetCache?.Invalidate(url);
            Debug.WriteLine($"[admin.uploadLibraryPreview] {libraryId} -> {url}");

            await _supabase.UpdateWithServiceRoleAsync("library_components",
                $"id=eq.{Uri.EscapeDataString(libraryId)}",
                new { preview_url = url }, await AdminServiceKeyAsync());

            return url;
        }
        finally
        {
            if (isTemp && File.Exists(localPath)) try { File.Delete(localPath); } catch { }
        }
