#if ADMIN
    public async Task<List<string>> AdminUploadLibraryGalleryAsync(string libraryId, IReadOnlyList<string> sourcePaths)
    {
        if (string.IsNullOrWhiteSpace(libraryId))
            throw new ArgumentException("libraryId required", nameof(libraryId));
        if (sourcePaths is null || sourcePaths.Count == 0)
            throw new ArgumentException("at least one sourcePath required", nameof(sourcePaths));

        foreach (var p in sourcePaths)
        {
            if (string.IsNullOrWhiteSpace(p) || !File.Exists(p))
                throw new ArgumentException($"sourcePath '{p}' not found", nameof(sourcePaths));
            var e = Path.GetExtension(p).ToLowerInvariant();
            if (e != ".png" && e != ".jpg" && e != ".jpeg" && e != ".webp")
                throw new ArgumentException($"gallery photo must be .png / .jpg / .webp ('{p}')", nameof(sourcePaths));
        }

        var rows = await _supabase.SelectAsync<LibraryRow>(
            "library_components",
            $"select=*&id=eq.{Uri.EscapeDataString(libraryId)}");
        var row = rows.FirstOrDefault()
            ?? throw new InvalidOperationException("Library component not found.");

        var existing = row.GalleryUrls ?? new List<string>();
        var startIdx = existing.Count;
        var newUrls = new List<string>(sourcePaths.Count);

        for (int i = 0; i < sourcePaths.Count; i++)
        {
            var src = sourcePaths[i];
            var (localPath, ext, isTemp) = await EnsureWebPAsync(src);
            try
            {
                var guidShort = Guid.NewGuid().ToString("N").Substring(0, 6);
                var key = $"library/{row.Type}/{libraryId}__gallery_{startIdx + i}_{guidShort}{ext}";
                var url = await _remoteStorage.UploadAsync(localPath, key, progress: null, CancellationToken.None);
                Debug.WriteLine($"[admin.uploadLibraryGallery] {libraryId} #{startIdx + i} -> {url}");
                newUrls.Add(url);
            }
            finally
            {
                if (isTemp && File.Exists(localPath)) try { File.Delete(localPath); } catch { }
            }
        }

        var combined = existing.Concat(newUrls).ToList();
        await _supabase.UpdateWithServiceRoleAsync("library_components",
            $"id=eq.{Uri.EscapeDataString(libraryId)}",
            new { gallery_urls = combined }, await AdminServiceKeyAsync());

        return combined;
    }
