#if ADMIN
    public async Task<string> AdminUploadLibraryVideoAsync(string libraryId, string sourcePath)
    {
        if (string.IsNullOrWhiteSpace(libraryId))
            throw new ArgumentException("libraryId required", nameof(libraryId));
        if (string.IsNullOrWhiteSpace(sourcePath))
            throw new ArgumentException("sourcePath required", nameof(sourcePath));

        string localPath;
        bool   isTemp = false;
        bool   isYouTube = LooksLikeYouTubeUrl(sourcePath);

        if (isYouTube)
        {
            try
            {
                localPath = await DownloadYouTubeAsMp4Async(sourcePath);
                isTemp = true;
                Debug.WriteLine($"[admin.uploadLibraryVideo] downloaded YouTube → {localPath} ({new FileInfo(localPath).Length / 1024} KB)");
            }
