                throw new ArgumentException("sourcePath must exist or be a YouTube URL", nameof(sourcePath));
            var lext = Path.GetExtension(sourcePath).ToLowerInvariant();
            if (lext != ".mp4" && lext != ".webm" && lext != ".mov" && lext != ".m4v")
                throw new ArgumentException("video must be .mp4 / .webm / .mov / .m4v (or a YouTube URL)", nameof(sourcePath));
            localPath = sourcePath;
