            await _supabase.UpdateWithServiceRoleAsync("library_components",
                $"id=eq.{Uri.EscapeDataString(libraryId)}",
                new { preview_video_url = url }, await AdminServiceKeyAsync());

            if (isYouTube && string.IsNullOrWhiteSpace(row.PreviewUrl))
            {
                try
                {
                    var thumbUrl = await TryFetchYouTubeThumbnailUrlAsync(libraryId, sourcePath);
                    if (!string.IsNullOrEmpty(thumbUrl))
                    {
                        await _supabase.UpdateWithServiceRoleAsync("library_components",
                            $"id=eq.{Uri.EscapeDataString(libraryId)}",
                            new { preview_url = thumbUrl }, await AdminServiceKeyAsync());
                        Debug.WriteLine($"[admin.uploadLibraryVideo] auto-attached YT thumbnail: {thumbUrl}");
                    }
                }
                catch (Exception ex)
                {
                    Debug.WriteLine($"[admin.uploadLibraryVideo] YT thumbnail fetch FAIL: {ex.Message}");
                }
            }

            return url;
