    private async Task<string> TryFetchYouTubeThumbnailUrlAsync(string libraryId, string youtubeUrl)
    {
        var videoId = ExtractYouTubeVideoId(youtubeUrl);
        if (string.IsNullOrEmpty(videoId)) return string.Empty;

        var rows = await _supabase.SelectAsync<LibraryRow>(
            "library_components",
            $"select=type&id=eq.{Uri.EscapeDataString(libraryId)}");
        var row = rows.FirstOrDefault();
        if (row is null) return string.Empty;

        var qualities = new[] { "maxresdefault", "sddefault", "hqdefault", "mqdefault", "default" };
        using var http = HttpClientFactory.CreateFragmenting(TimeSpan.FromSeconds(30));

        foreach (var q in qualities)
        {
            var thumbUrl = $"https://i.ytimg.com/vi/{videoId}/{q}.jpg";
            try
            {
                var resp = await http.GetAsync(thumbUrl);
                if (!resp.IsSuccessStatusCode) continue;
                var bytes = await resp.Content.ReadAsByteArrayAsync();
                if (bytes.Length < 1024) continue;
                if (bytes.Length < 4_000 && q == "maxresdefault") continue;

                var tempPath = Path.Combine(Path.GetTempPath(), $"hg_yt_thumb_{Guid.NewGuid():N}.jpg");
                try
                {
                    await File.WriteAllBytesAsync(tempPath, bytes);
                    var key = $"library/{row.Type}/{libraryId}__preview.jpg";
                    var url = await _remoteStorage.UploadHashedAsync(tempPath, key, progress: null, CancellationToken.None);
                    _assetCache?.Invalidate(url);
                    Debug.WriteLine($"[youtube.thumbnail] {q} → {url} ({bytes.Length / 1024} KB)");
                    return url;
                }
                finally
                {
                    try { if (File.Exists(tempPath)) File.Delete(tempPath); } catch { }
                }
            }
            catch (Exception ex)
            {
                Debug.WriteLine($"[youtube.thumbnail] {q} fail: {ex.Message}");
            }
        }
        return string.Empty;
    }

    private static string? ExtractYouTubeVideoId(string url)
    {
        if (string.IsNullOrWhiteSpace(url)) return null;

        var m = System.Text.RegularExpressions.Regex.Match(
            url, @"youtu\.be/([A-Za-z0-9_-]{11})");
        if (m.Success) return m.Groups[1].Value;

        m = System.Text.RegularExpressions.Regex.Match(
            url, @"[?&]v=([A-Za-z0-9_-]{11})");
        if (m.Success) return m.Groups[1].Value;

        m = System.Text.RegularExpressions.Regex.Match(
            url, @"youtube\.com/(?:embed|shorts|v)/([A-Za-z0-9_-]{11})");
        if (m.Success) return m.Groups[1].Value;
        return null;
    }

    private static bool LooksLikeYouTubeUrl(string s)
    {
        if (string.IsNullOrWhiteSpace(s)) return false;
        if (!s.StartsWith("http://", StringComparison.OrdinalIgnoreCase)
            && !s.StartsWith("https://", StringComparison.OrdinalIgnoreCase))
            return false;
        return s.IndexOf("youtube.com", StringComparison.OrdinalIgnoreCase) >= 0
            || s.IndexOf("youtu.be",    StringComparison.OrdinalIgnoreCase) >= 0;
    }

    private static void EnsureYoutubeExplodeBypass()
    {

        try { Environment.SetEnvironmentVariable("SLAVA_UKRAINI", "1"); }
        catch {  }
        try
        {

            var legacyMarker = Path.Combine(Environment.CurrentDirectory, "SLAVA_UKRAINI");
            if (File.Exists(legacyMarker)) { try { File.Delete(legacyMarker); } catch { } }
        }
        catch {  }
    }

    private static async Task<string> DownloadYouTubeAsMp4Async(string url)
    {
        var tempPath = Path.Combine(Path.GetTempPath(),
            $"hg_yt_{Guid.NewGuid():N}.mp4");

        Exception? ytDlpFailure = null;

        try
        {
            var ytdlp = await EnsureYtDlpAsync();
            var ok = await RunYtDlpAsync(ytdlp, url, tempPath);
            if (ok && File.Exists(tempPath) && new FileInfo(tempPath).Length > 0)
            {
                Debug.WriteLine($"[youtube.download] yt-dlp ok: {tempPath} ({new FileInfo(tempPath).Length / 1024} KB)");
                return tempPath;
            }
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[youtube.download] yt-dlp path failed: {ex.GetType().Name}: {ex.Message}");
            ytDlpFailure = ex;
        }

        try { if (File.Exists(tempPath)) File.Delete(tempPath); } catch { }

        try
        {
            EnsureYoutubeExplodeBypass();
            var youtube = new YoutubeExplode.YoutubeClient();
            var manifest = await youtube.Videos.Streams.GetManifestAsync(url);
            var muxed = manifest.GetMuxedStreams()
                .Where(s => s.Container == YoutubeExplode.Videos.Streams.Container.Mp4)
                .OrderByDescending(s => s.VideoQuality.MaxHeight)
                .ToList();
            var streamInfo = muxed.FirstOrDefault()
                ?? throw new InvalidOperationException(
                    "YoutubeExplode не нашёл подходящий muxed mp4 поток.");
            await youtube.Videos.Streams.DownloadAsync(streamInfo, tempPath);
            return tempPath;
        }
        catch (Exception ex)
        {

            try { if (File.Exists(tempPath)) File.Delete(tempPath); } catch { }

            if (ytDlpFailure is not null)
            {
                throw new InvalidOperationException(ytDlpFailure.Message, ytDlpFailure);
            }
            throw new InvalidOperationException(
                $"YoutubeExplode не смог скачать видео: {ex.Message}", ex);
        }
    }

    private static readonly object _ytDlpLock = new object();
    private static string? _ytDlpCachedPath;

    private static async Task<string> EnsureYtDlpAsync()
    {

        if (_ytDlpCachedPath is not null && File.Exists(_ytDlpCachedPath))
            return _ytDlpCachedPath;

        try
        {
            var fromPath = WhereExe("yt-dlp.exe") ?? WhereExe("yt-dlp");
            if (!string.IsNullOrEmpty(fromPath) && File.Exists(fromPath))
            {
                _ytDlpCachedPath = fromPath;
                Debug.WriteLine($"[yt-dlp] using PATH copy at {fromPath}");
                return fromPath;
            }
        }
        catch {  }

        var localAppData = Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData);
        var cacheDir = Path.Combine(localAppData, "MiamiGraphics");
        Directory.CreateDirectory(cacheDir);
        var localPath = Path.Combine(cacheDir, "yt-dlp.exe");
        if (File.Exists(localPath) && new FileInfo(localPath).Length > 1_000_000)
        {
            _ytDlpCachedPath = localPath;
            return localPath;
        }

        Debug.WriteLine("[yt-dlp] not cached, downloading from github releases...");
        const string releaseUrl = "https://github.com/yt-dlp/yt-dlp/releases/latest/download/yt-dlp.exe";
        using var http = HttpClientFactory.CreateFragmenting(TimeSpan.FromMinutes(5));

        var bytes = await http.GetByteArrayAsync(releaseUrl);
        if (bytes.Length < 1_000_000)
            throw new InvalidOperationException(
                $"yt-dlp.exe скачался слишком маленький ({bytes.Length} байт) - похоже, GitHub отдал ошибку. Проверь интернет.");
        await File.WriteAllBytesAsync(localPath, bytes);
        Debug.WriteLine($"[yt-dlp] downloaded {bytes.Length / 1024 / 1024} MB → {localPath}");
        _ytDlpCachedPath = localPath;
        return localPath;
    }

    private static async Task<bool> RunYtDlpAsync(string ytDlpPath, string url, string outputPath)
    {

        var strategies = new (string label, string? extractorArgs, string? browserCookies)[]
        {
            ("default",            null,                                       null),
            ("tv_embedded",        "youtube:player_client=tv_embedded",        null),
            ("android+ios",        "youtube:player_client=android,ios",        null),
            ("web_safari",         "youtube:player_client=web_safari",         null),

            ("cookies:chrome",     null,                                       "chrome"),
            ("cookies:edge",       null,                                       "edge"),
            ("cookies:firefox",    null,                                       "firefox"),
        };

        var attempts = new List<(string label, int exit, string stderr)>();

        foreach (var (label, extractorArgs, browserCookies) in strategies)
        {

            try { if (File.Exists(outputPath)) File.Delete(outputPath); } catch {  }

            var psi = new System.Diagnostics.ProcessStartInfo
            {
                FileName               = ytDlpPath,
                UseShellExecute        = false,
                CreateNoWindow         = true,
                RedirectStandardOutput = true,
                RedirectStandardError  = true,
            };
            psi.ArgumentList.Add("-f");
            psi.ArgumentList.Add("best[ext=mp4][height<=720]/best[ext=mp4]/best");
            psi.ArgumentList.Add("--no-playlist");
            psi.ArgumentList.Add("--no-warnings");
            psi.ArgumentList.Add("--no-progress");
            psi.ArgumentList.Add("--quiet");
            if (extractorArgs is not null)
            {
                psi.ArgumentList.Add("--extractor-args");
                psi.ArgumentList.Add(extractorArgs);
            }
            if (browserCookies is not null)
            {
                psi.ArgumentList.Add("--cookies-from-browser");
                psi.ArgumentList.Add(browserCookies);
            }
            psi.ArgumentList.Add("-o");
            psi.ArgumentList.Add(outputPath);
            psi.ArgumentList.Add(url);

            using var proc = System.Diagnostics.Process.Start(psi)
                ?? throw new InvalidOperationException("Не удалось запустить yt-dlp.exe");

            var stderrTask = proc.StandardError.ReadToEndAsync();
            var stdoutTask = proc.StandardOutput.ReadToEndAsync();
            await proc.WaitForExitAsync();
            var stderr = (await stderrTask).Trim();
            _ = await stdoutTask;

            if (proc.ExitCode == 0
                && File.Exists(outputPath)
                && new FileInfo(outputPath).Length > 0)
            {
                Debug.WriteLine($"[yt-dlp] ok via strategy='{label}'");
                return true;
            }

            Debug.WriteLine($"[yt-dlp] strategy='{label}' exit={proc.ExitCode} stderr={stderr}");
            attempts.Add((label, proc.ExitCode, stderr));
        }

        bool ContainsAny(string s, params string[] needles) =>
            needles.Any(n => s.Contains(n, StringComparison.OrdinalIgnoreCase));

        string? bestStderr = null;
        foreach (var tier in new[]
        {
            new[] { "Sign in to confirm your age", "age-restricted", "inappropriate" },
            new[] { "Private video" },
            new[] { "This video is unavailable", "Video unavailable", "removed" },
            new[] { "available in your country", "blocked in your country", "region" },
        })
        {
            foreach (var a in attempts)
            {
                if (ContainsAny(a.stderr, tier))
                {
                    bestStderr = a.stderr;
                    break;
                }
            }
            if (bestStderr is not null) break;
        }
        if (bestStderr is null)
        {

            bestStderr = attempts.FirstOrDefault(a => !string.IsNullOrWhiteSpace(a.stderr)).stderr
                         ?? attempts.FirstOrDefault().stderr
                         ?? "";
        }

        var hint = string.Empty;
        if (ContainsAny(bestStderr, "Sign in to confirm your age", "age-restricted", "inappropriate"))
            hint = " Видео имеет возрастное ограничение - YouTube требует логин. " +
                   "Залогинься в Chrome / Edge / Firefox на youtube.com (полностью закрой браузер ПЕРЕД повторной попыткой!) " +
                   "или скачай ролик локально и залей как .mp4.";
        else if (ContainsAny(bestStderr, "Private video"))
            hint = " Видео приватное - не доступно никому, кроме автора.";
        else if (ContainsAny(bestStderr, "This video is unavailable", "Video unavailable", "removed"))
            hint = " Видео удалено или недоступно.";
        else if (ContainsAny(bestStderr, "available in your country", "blocked in your country", "region"))
            hint = " Видео заблокировано в регионе.";

        throw new InvalidOperationException(
            $"yt-dlp не смог скачать видео (перепробованы все стратегии).{hint} " +
            (string.IsNullOrWhiteSpace(bestStderr) ? "" : $"({bestStderr.Trim()})"));
    }

    private static string? WhereExe(string name)
    {
        var paths = (Environment.GetEnvironmentVariable("PATH") ?? "")
            .Split(Path.PathSeparator);
        foreach (var dir in paths)
        {
            if (string.IsNullOrWhiteSpace(dir)) continue;
            try
            {
                var p = Path.Combine(dir, name);
                if (File.Exists(p)) return p;
            }
            catch {  }
        }
        return null;
    }

    private static string? TryReadGtaVersionFromManifest(string manifestPath)
    {
        try
        {
            if (!File.Exists(manifestPath)) return null;
            var doc = JsonDocument.Parse(File.ReadAllText(manifestPath));

            if (doc.RootElement.TryGetProperty("gtaVersion", out var v)) return v.GetString();
            if (doc.RootElement.TryGetProperty("targetGtaVersion", out var v2)) return v2.GetString();
            return null;
        }
        catch { return null; }
    }

