    public async Task<List<GunpackFlatGunDto>> GunpackAllGunsAsync()
    {
        const int page = 1000;
        const int maxPages = 200;
        var outRows = new List<GunpackFlatGunDto>();
        try
        {
            for (int p = 0; p < maxPages; p++)
            {
                var rows = await _supabase.SelectAsync<FlatGunRow>(
                    "gunpack_guns",
                    "select=id,gunpack_id,base_name,weapon_prefix,category,display_name,glb_url,preview_url" +
                    "&is_hidden=not.is.true" +
                    $"&order=gunpack_id.asc,sort_order.asc,base_name.asc&limit={page}&offset={p * page}");
                foreach (var r in rows)
                {
                    if (string.IsNullOrWhiteSpace(r.GunpackId)) continue;
                    outRows.Add(new GunpackFlatGunDto(
                        r.Id ?? Guid.Empty,
                        r.GunpackId,
                        r.BaseName     ?? string.Empty,
                        r.WeaponPrefix ?? string.Empty,
                        r.Category     ?? string.Empty,
                        r.DisplayName,
                        r.GlbUrl,
                        r.PreviewUrl));
                }
                if (rows.Count < page) break;
            }
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[gunpackAllGuns] failed: {ex.Message}");
            return new List<GunpackFlatGunDto>();
        }
        return outRows;
    }

