    public Task<CustomGunDto> CustomGunApproveAsync(string id, string reviewerUserId) => Task.Run(async () =>
    {
        var pending = await CustomGunRepo.ListPendingAsync();
        var row = pending.FirstOrDefault(p => string.Equals(p.Id, id, StringComparison.Ordinal))
            ?? throw new InvalidOperationException("Скин не найден в очереди модерации (уже обработан?).");

        string? previewUrl = null;
        if (!string.IsNullOrWhiteSpace(row.GlbUrl))
        {
            await EnsureRendererReadyForGunpackUploadAsync();
            var workDir = Path.Combine(Path.GetTempPath(), "customgun_" + Guid.NewGuid().ToString("N")[..8]);
            Directory.CreateDirectory(workDir);
            try
            {
                var localGlb = Path.Combine(workDir, "model.glb");
                using (var http = new System.Net.Http.HttpClient { Timeout = TimeSpan.FromSeconds(60) })
                    await DownloadFileAsync(http, row.GlbUrl!, localGlb);
                if (!File.Exists(localGlb))
                    throw new InvalidOperationException("Не удалось скачать GLB для рендера превью.");

                var localPng = Path.Combine(workDir, "preview.webp");
                var ok = await Core.Services.GlbToPngRenderer.RenderAsync(localGlb, localPng, 1280, 800);
                if (!ok || !File.Exists(localPng))
                    throw new InvalidOperationException("Не удалось отрендерить превью скина - одобрение отменено, попробуй ещё раз.");

                var previewBytes = await File.ReadAllBytesAsync(localPng);
                previewUrl = await _supabase.UploadCustomGunFileAsync(previewBytes, "preview");
            }
            finally { try { Directory.Delete(workDir, recursive: true); } catch { } }
        }

        var saved = await CustomGunRepo.ApproveAsync(id, previewUrl)
            ?? throw new InvalidOperationException("Не удалось одобрить: скин не на модерации или нет прав.");
        return ToCustomGunDto(saved, null);
    });

