    public async Task<string> CustomGunPreviewDownloadAsync(string url, string suggestedName)
    {
        if (string.IsNullOrWhiteSpace(url)) throw new ArgumentException(Loc.T("errors.preview.emptyUrl"));
        var downloads = Path.Combine(
            Environment.GetFolderPath(Environment.SpecialFolder.UserProfile), "Downloads");
        Directory.CreateDirectory(downloads);
        var safe = string.Join("_",
            (string.IsNullOrWhiteSpace(suggestedName) ? "gun_preview" : suggestedName)
            .Split(Path.GetInvalidFileNameChars(), StringSplitOptions.RemoveEmptyEntries)).Trim('_');
        var ext = url.Contains(".png", StringComparison.OrdinalIgnoreCase) ? ".png" : ".webp";
        var target = Path.Combine(downloads, safe + ext);
        for (int n = 2; File.Exists(target); n++)
            target = Path.Combine(downloads, $"{safe}_{n}{ext}");
        using (var http = new System.Net.Http.HttpClient { Timeout = TimeSpan.FromSeconds(60) })
            await DownloadFileAsync(http, url, target);
        if (!File.Exists(target)) throw new InvalidOperationException(Loc.T("errors.preview.downloadFailed"));
        return target;
    }

