#if ADMIN
    public async Task<GunpackQueueItemDto> AdminGunpackVariantUploadAsync(
        string packId, string name, string sourceRpfPath, string? coverImagePath)
    {
        if (string.IsNullOrWhiteSpace(packId))
            throw new ArgumentException("packId required");
        if (string.IsNullOrWhiteSpace(sourceRpfPath) || !File.Exists(sourceRpfPath))
            throw new ArgumentException("sourceRpfPath required + must exist");
        if (!string.IsNullOrWhiteSpace(coverImagePath) && !File.Exists(coverImagePath))
            throw new ArgumentException("coverImagePath does not exist");

        var pack = await _gunpackRepo.GetByIdAsync(packId);
        if (pack is null)
            throw new InvalidOperationException($"Пак не найден: {packId}");

        var cfg = await _adminConfig.GetAsync();
        var serviceKey = cfg.SupabaseServiceKey;
        if (string.IsNullOrWhiteSpace(serviceKey))
            throw new InvalidOperationException(
                "Не задан Supabase Service Role Key в Admin → Настройки. " +
                "Загрузка вариантов требует service-role-ключ (anon заблокирован RLS).");

        var variantId = Guid.NewGuid();

        await EnsureRendererReadyForGunpackUploadAsync();

        var displayName = string.IsNullOrWhiteSpace(name) ? "New variant" : name.Trim();
        var item = new Admin.GunpackQueueItem
        {
            Metadata          = new Admin.GunpackItem { Name = $"{pack.Name} / {displayName}" },
            SourceDlcRpfPath  = sourceRpfPath,
            UploadToR2        = true,
            Variant           = new Admin.VariantUploadContext
            {
                PackId         = packId,
                VariantId      = variantId,
                Name           = displayName,
                CoverImagePath = coverImagePath,
                ServiceRoleKey = serviceKey,
            },
        };

        var queued = await _gunpackQueue.EnqueueAndStartAsync(
            item,
            snapshot => _emitEvent?.Invoke("admin:gunpackQueueProgress", ToGunpackQueueItemDto(snapshot)),
            CancellationToken.None);

        if (!string.IsNullOrWhiteSpace(coverImagePath))
        {
            _ = Task.Run(async () =>
            {
                try
                {
                    var deadline = DateTime.UtcNow.AddMinutes(10);
                    while (DateTime.UtcNow < deadline)
                    {
                        await Task.Delay(500);
                        var snap = (await _gunpackQueue.ListAsync())
                            .FirstOrDefault(x => x.TempId == queued.TempId);
                        if (snap is null) return;
                        if (snap.Status == "error") return;
                        if (snap.Status != "done") continue;

                        try
                        {
                            var (localPath, ext, isTemp) = await EnsureWebPAsync(coverImagePath);
                            try
                            {
                                var coverKey = $"gunpacks/{packId}/variants/{variantId:D}/cover{ext}";
                                var coverUrl = await _remoteStorage.UploadAsync(localPath, coverKey, progress: null, CancellationToken.None);
                                Debug.WriteLine($"[gunpack.variant.upload] cover → {coverUrl}");

                                await _gunpackRepo.PatchVariantAsync(
                                    variantId,
                                    new Dictionary<string, object?> { ["cover_url"] = coverUrl },
                                    serviceKey);
                                Debug.WriteLine($"[gunpack.variant.upload] cover_url patched onto variant {variantId}");
                            }
                            finally
                            {
                                if (isTemp && File.Exists(localPath)) try { File.Delete(localPath); } catch { }
                            }
                        }
                        catch (Exception ex)
                        {
                            Debug.WriteLine($"[gunpack.variant.upload] post-queue cover upload FAILED: {ex.Message}");
                        }
                        return;
                    }
                    Debug.WriteLine($"[gunpack.variant.upload] cover_url patch timed out waiting for queue {queued.TempId}");
                }
                catch (Exception ex)
                {
                    Debug.WriteLine($"[gunpack.variant.upload] cover watcher faulted: {ex.Message}");
                }
            });
        }

        return ToGunpackQueueItemDto(queued);
    }
#endif

