#if ADMIN
    public async Task AdminGunpackPatchAsync(string id, GunpackPatchDto patch)
    {
        var cfg = await _adminConfig.GetAsync();
        var serviceKey = cfg.SupabaseServiceKey;
        if (string.IsNullOrWhiteSpace(serviceKey))
        {
            throw new InvalidOperationException(
                "Не задан Supabase Service Role Key в Admin → Настройки. " +
                "Без него UPDATE не проходит RLS-политику (anon-ключ может " +
                "INSERT, но не UPDATE на каталоговые таблицы). " +
                "Скопируй service_role-ключ из Supabase Studio → Settings → API → service_role key " +
                "и вставь в поле «Supabase Service Role Key».");
        }

        var body = new Dictionary<string, object?>();
        if (patch.Name           is not null) body["name"]            = patch.Name;
        if (patch.Author         is not null) body["author"]          = string.IsNullOrEmpty(patch.Author)      ? null : patch.Author;
        if (patch.AuthorLink     is not null) body["author_link"]     = string.IsNullOrEmpty(patch.AuthorLink)  ? null : patch.AuthorLink;
        if (patch.Description    is not null) body["description"]     = string.IsNullOrEmpty(patch.Description) ? null : patch.Description;
        if (patch.Status         is not null) body["status"]          = patch.Status;
        if (patch.IsVerified     is not null) body["is_verified"]     = patch.IsVerified.Value;
        if (patch.ViewerPriority is not null) body["viewer_priority"] = patch.ViewerPriority.Value;
        if (patch.CoverKind      is not null) body["cover_kind"]      = patch.CoverKind;
        if (patch.CoverUrl       is not null) body["cover_url"]       = string.IsNullOrEmpty(patch.CoverUrl)    ? null : patch.CoverUrl;
        if (patch.GalleryUrls    is not null) body["gallery_urls"]    = patch.GalleryUrls;
        if (patch.Notes          is not null) body["notes"]           = string.IsNullOrEmpty(patch.Notes)       ? null : patch.Notes;

        if (body.Count == 0) return;

        body["updated_at"] = DateTime.UtcNow;

        var escId = Uri.EscapeDataString(id);
        var updated = await _supabase.UpdateWithServiceRoleAsync(
            "gunpacks", $"id=eq.{escId}", body, serviceKey);
        Debug.WriteLine($"[gunpack.patch] id={id} keys=[{string.Join(",", body.Keys)}] - updated={updated} row(s)");
        if (updated == 0)
        {
            throw new InvalidOperationException(
                $"PATCH gunpack '{id}' с service-role-ключом обновил 0 строк. " +
                "Возможно service-role-ключ невалидный или истёк. " +
                "Проверь в Supabase Studio: SELECT * FROM gunpacks WHERE id='" + id + "';");
        }

        try
        {
            var fresh = await _gunpackRepo.GetByIdAsync(id);
            if (fresh is null)
            {
                Debug.WriteLine($"[gunpack.patch.verify] id={id} - readback returned NULL (row vanished?)");
            }
            else
            {
                var expected = string.Join(", ",
                    body.Where(kv => kv.Key != "updated_at")
                        .Select(kv => $"{kv.Key}={kv.Value}"));
                Debug.WriteLine(
                    $"[gunpack.patch.verify] id={id} - DB now: status={fresh.Status}, " +
                    $"name={fresh.Name}, is_verified={fresh.IsVerified}, " +
                    $"cover_kind={fresh.CoverKind} | expected: {expected}");
            }
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[gunpack.patch.verify] id={id} - readback FAILED: {ex.Message}");
        }
    }
#endif

#if ADMIN
    public async Task AdminGunpackDeleteAsync(string id)
    {
        try
        {
            var purged = await _remoteStorage.DeletePrefixAsync($"gunpacks/{id}/", CancellationToken.None);
            Debug.WriteLine($"[gunpack.delete] purged R2 prefix 'gunpacks/{id}/' - {purged} object(s)");
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[gunpack.delete] WARN: R2 purge failed ({ex.Message}). DB row will still be removed; R2 objects may be orphaned.");
        }

        var cfg = await _adminConfig.GetAsync();
        var serviceKey = cfg.SupabaseServiceKey;
        if (string.IsNullOrWhiteSpace(serviceKey))
        {
            throw new InvalidOperationException(
                "Не задан Supabase Service Role Key в Admin → Настройки. " +
                "Без него DELETE не проходит RLS-политику (anon-ключ не может удалять). " +
                "Скопируй service_role-ключ из Supabase Studio → Settings → API → service_role key " +
                "и вставь в поле «Supabase Service Role Key».");
        }

        var escId = Uri.EscapeDataString(id);
        var childTables = new (string Table, string Filter)[]
        {
            ("gunpack_guns",      $"gunpack_id=eq.{escId}"),
            ("gunpack_whitelist", $"gunpack_id=eq.{escId}"),
        };
        foreach (var (table, filter) in childTables)
        {
            try
            {
                var n = await _supabase.DeleteWithServiceRoleAsync(table, filter, serviceKey);
                Debug.WriteLine($"[gunpack.delete] cascade ok: {table}?{filter} - {n} rows");
            }
            catch (Exception ex)
            {
                Debug.WriteLine($"[gunpack.delete] cascade WARN on {table}: {ex.Message} (continuing)");
            }
        }

        var parentDeleted = await _supabase.DeleteWithServiceRoleAsync(
            "gunpacks", $"id=eq.{escId}", serviceKey);
        Debug.WriteLine($"[gunpack.delete] gunpacks deleted: {parentDeleted} row(s)");

        try
        {
            var stillThere = await _gunpackRepo.GetByIdAsync(id);
            if (stillThere is not null)
            {
                throw new InvalidOperationException(
                    $"Запись ганпака '{id}' осталась в Supabase после DELETE с service-role-ключом. " +
                    "Возможно ключ невалидный или истёк. " +
                    "Проверь Supabase Studio: SELECT * FROM gunpacks WHERE id='" + id + "';");
            }
        }
        catch (InvalidOperationException) { throw; }
        catch (Exception ex)
        {
            Debug.WriteLine($"[gunpack.delete] post-delete verify skipped: {ex.Message}");
        }
    }
#endif

