    private async Task EnsureRendererReadyForGunpackUploadAsync()
    {
        if (Services.RendererBootstrapper.IsAlreadyInstalled())
        {
            Debug.WriteLine("[admin.gunpack.upload] Renderer already installed, skipping bootstrap");
            return;
        }

        Debug.WriteLine("[admin.gunpack.upload] Renderer missing - auto-downloading before queue");
        _emitEvent?.Invoke("admin:rendererBootstrap", new { phase = "downloading", percent = 0.0 });

        var boot = new Services.RendererBootstrapper();
        var progress = new Progress<(string Phase, double Percent)>(p =>
            _emitEvent?.Invoke("admin:rendererBootstrap", new { phase = p.Phase, percent = p.Percent }));

        Services.RendererBootstrapper.EnsureResult result;
        try
        {
            result = await boot.EnsureInstalledAsync(progress, CancellationToken.None);
        }
        catch (Exception ex)
        {
            _emitEvent?.Invoke("admin:rendererBootstrap", new { phase = "error", percent = 0.0, error = ex.Message });
            throw new InvalidOperationException(
                "Не удалось скачать Renderer (нужен для генерации PNG-превью ганов). " +
                $"Ошибка: {ex.Message}. " +
                "Проверь интернет + наличие свободного места ~200 MB. " +
                "Если ошибка повторяется - отключи VPN/Zapret и попробуй снова.", ex);
        }

        if (!result.Success)
        {
            _emitEvent?.Invoke("admin:rendererBootstrap", new { phase = "error", percent = 0.0, error = result.ErrorMessage });
            throw new InvalidOperationException(
                "Не удалось установить Renderer (нужен для генерации PNG-превью ганов). " +
                $"{result.ErrorMessage}. " +
                "Без него заливка ганпака пройдёт без фоток - ганы появятся в каталоге с 'Нет фото'. " +
                "Попробуй ещё раз; если повторяется - проверь свободное место на диске C: и отключи антивирус на момент скачивания.");
        }

        _emitEvent?.Invoke("admin:rendererBootstrap", new { phase = "done", percent = 100.0,
            downloadedMb = result.DownloadedBytes / 1024.0 / 1024.0, alreadyInstalled = result.AlreadyInstalled });
        Debug.WriteLine($"[admin.gunpack.upload] Renderer ready: {(result.AlreadyInstalled ? "already installed" : $"downloaded {result.DownloadedBytes / 1024 / 1024} MB")}");
    }

