    private async Task<InjectResultDto> GunpackInstallCoreAsync(
        string gunpackId,
        Dictionary<string, string>? perGunResolutions,
        Guid? variantId,
        IReadOnlyCollection<string>? vanillaInternalNames)
    {
        if (string.IsNullOrWhiteSpace(gunpackId))
            return new InjectResultDto(false, "gunpackId required", null);
        var (ct, _cancelReg) = BeginCancellableOp($"gunpack:{gunpackId}");
        using var _cs = _cancelReg;
        IDisposable _mtxTaken;
        try
        {
            _mtxTaken = await MiamiGraphics.Shell.Services.UpdateRpfMutex.AcquireAsync($"gunpack-install-all:{gunpackId}", ct);
        }
        catch (TimeoutException tex)
        {
            var msg = "Очередь установки занята слишком долго - другая установка зависла. Перезапусти лаунчер и попробуй снова.";
            EmitGunpackInstallProgress(gunpackId, "error", 0, msg, null);
            Debug.WriteLine($"[gunpack.install] mutex acquire timeout: {tex.Message}");
            return new InjectResultDto(false, msg, null);
        }
        catch (OperationCanceledException)
        {
            EmitGunpackInstallProgress(gunpackId, "error", 0, "Установка отменена.", null);
            throw;
        }
        using var _mtx = _mtxTaken;

        await ReconcileInstallStateAsync();

        try { await _selectedGunsInstaller.SetVanillaSlotsAsync(gunpackId, vanillaInternalNames); }
        catch (Exception ex) { Debug.WriteLine($"[gunpack.install] vanilla slots persist FAIL: {ex.Message}"); }

        if (perGunResolutions is { Count: > 0 })
        {
            try
            {
                var packPriorityNames = perGunResolutions
                    .Where(kv => string.Equals(kv.Value, "pack", StringComparison.OrdinalIgnoreCase))
                    .Select(kv => kv.Key)
                    .ToHashSet(StringComparer.OrdinalIgnoreCase);

                if (packPriorityNames.Count > 0)
                {
                    var emitNoop = new ISelectedGunsInstaller.EmitProgress((_, _, _, _) => { });
                    foreach (var sel in await _selectedGunsInstaller.ListInstalledAsync())
                    {
                        if (!packPriorityNames.Contains(sel.InternalName)) continue;
                        Debug.WriteLine($"[gunpack.install] perGun=pack for '{sel.InternalName}' - dropping selected before install");
                        await _selectedGunsInstaller.RemoveGunAsync(sel.InternalName, emitNoop, ct);
                    }

                    foreach (var cust in await _selectedGunsInstaller.GetCustomsAsync())
                    {
                        if (!packPriorityNames.Contains(cust.InternalName)) continue;
                        Debug.WriteLine($"[gunpack.install] perGun=pack for custom '{cust.InternalName}' - forgetting custom before install");
                        await _selectedGunsInstaller.ForgetCustomAsync(cust.InternalName);
                    }
                }
            }
            catch (Exception ex)
            {
                Debug.WriteLine($"[gunpack.install] per-gun pre-drop FAILED: {ex.Message} - proceeding anyway (rebuild will use default merge)");
            }
        }

        var gtaPath = await GetGtaPathAsync();
        var sysInfo = await GetSystemInfoAsync();
        var exeVersion = sysInfo.GtaExeVersion ?? string.Empty;

        var sw = Stopwatch.StartNew();
        long lastEmitMs = -1;
        string? lastPhase = null;
        Services.GunpackInstaller.EmitProgress emit = (phase, percent, err, detail) =>
        {
            var nowMs = sw.ElapsedMilliseconds;
            var phaseChanged = phase != lastPhase;
            var terminal = phase is "done" or "error";
            if (!phaseChanged && !terminal && nowMs - lastEmitMs < 250) return;
            lastEmitMs = nowMs;
            lastPhase = phase;
            EmitGunpackInstallProgress(gunpackId, phase, percent, err, detail);
        };

        return await _gunpackInstaller.InstallFullAsync(gunpackId, gtaPath, exeVersion, emit, ct, variantId);
    }

    public async Task<InjectResultDto> GunpackInstallSelectedAsync(string gunpackId, List<Guid> gunIds)
    {
        if (string.IsNullOrWhiteSpace(gunpackId))
            return new InjectResultDto(false, "gunpackId required", null);
        if (gunIds is not { Count: > 0 })
            return await GunpackInstallCoreAsync(gunpackId, null, null, null);

        List<string> vanilla;
        try
        {
            var wanted = gunIds.ToHashSet();
            var all = await _gunpackRepo.ListGunsAsync(gunpackId);
            vanilla = all.Where(g => !wanted.Contains(g.Id))
                         .Select(g => g.WeaponPrefix + g.BaseName)
                         .ToList();
            Debug.WriteLine($"[gunpack.installSelected] pack={gunpackId}: {wanted.Count} wanted, {vanilla.Count} left vanilla");
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[gunpack.installSelected] gun list FAIL ({ex.Message}) - installing whole pack");
            vanilla = new List<string>();
        }

        return await GunpackInstallCoreAsync(gunpackId, null, null, vanilla);
    }

    public async Task<bool> GunpackUninstallAsync()
    {
        using var _mtx = await MiamiGraphics.Shell.Services.UpdateRpfMutex.AcquireAsync("gunpack-uninstall");
        await ReconcileInstallStateAsync();
        var gtaPath = await GetGtaPathAsync();

        var sw = Stopwatch.StartNew();
        long lastEmitMs = -1;
        string? lastPhase = null;
        Services.GunpackInstaller.EmitProgress emit = (phase, percent, err, detail) =>
        {
            var nowMs = sw.ElapsedMilliseconds;
            var phaseChanged = phase != lastPhase;
            var terminal = phase is "done" or "error";
            if (!phaseChanged && !terminal && nowMs - lastEmitMs < 250) return;
            lastEmitMs = nowMs;
            lastPhase = phase;

            EmitGunpackInstallProgress(string.Empty, phase, percent, err, detail);
        };

        return await _gunpackInstaller.UninstallAsync(gtaPath, emit, CancellationToken.None);
    }

    public async Task<List<GunpackInstallConflictDto>> GunpackCheckInstallConflictsAsync(string gunpackId)
    {
        var output = new List<GunpackInstallConflictDto>();
        if (string.IsNullOrWhiteSpace(gunpackId)) return output;

        var selectedRows = await _selectedGunsInstaller.ListInstalledAsync();

        var customRows = await _selectedGunsInstaller.GetCustomsAsync();

        if (selectedRows.Count == 0 && customRows.Count == 0) return output;

        Admin.GunpackItem? newPack;
        List<Admin.GunpackGun> newPackGuns;
        try
        {
            newPack     = await _gunpackRepo.GetByIdAsync(gunpackId);
            newPackGuns = await _gunpackRepo.ListGunsAsync(gunpackId);
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[gunpack.check-conflicts] catalog lookup FAIL ({ex.Message}); returning empty list (caller will show generic error on actual install)");
            return output;
        }
        if (newPack is null) return output;

        var newPackByInternal = newPackGuns.ToDictionary(
            g => (g.WeaponPrefix ?? "") + (g.BaseName ?? ""),
            g => g,
            StringComparer.OrdinalIgnoreCase);

        var whitelist = await _gunpackWhitelistRepo.ListAsync();
        var whitelistByInternal = new Dictionary<string, Admin.GunpackWhitelistEntry>(StringComparer.OrdinalIgnoreCase);
        foreach (var w in whitelist) whitelistByInternal[w.InternalName] = w;

        var selectedSourcePackGuns = new Dictionary<string, List<Admin.GunpackGun>>(StringComparer.OrdinalIgnoreCase);

        foreach (var sel in selectedRows)
        {

            if (string.Equals(sel.GunpackId, gunpackId, StringComparison.OrdinalIgnoreCase))
            {
                Debug.WriteLine($"[gunpack.check-conflicts] skipping '{sel.InternalName}' - selected from same pack we're installing.");
                continue;
            }

            if (!newPackByInternal.TryGetValue(sel.InternalName, out var packGun)) continue;

            if (!selectedSourcePackGuns.TryGetValue(sel.GunpackId, out var srcGuns))
            {
                try
                {
                    srcGuns = await _gunpackRepo.ListGunsAsync(sel.GunpackId);
                }
                catch (Exception ex)
                {
                    Debug.WriteLine($"[gunpack.check-conflicts] selected source pack lookup FAIL ({sel.GunpackId}): {ex.Message}");
                    srcGuns = new List<Admin.GunpackGun>();
                }
                selectedSourcePackGuns[sel.GunpackId] = srcGuns;
            }
            var srcGun = srcGuns.FirstOrDefault(g =>
                string.Equals((g.WeaponPrefix ?? "") + (g.BaseName ?? ""), sel.InternalName, StringComparison.OrdinalIgnoreCase));

            string display = sel.DisplayName;
            if (!string.IsNullOrWhiteSpace(srcGun?.DisplayName)) display = srcGun!.DisplayName!;
            else if (whitelistByInternal.TryGetValue(sel.InternalName, out var w)
                     && !string.IsNullOrWhiteSpace(w.DisplayName)) display = w.DisplayName;

            output.Add(new GunpackInstallConflictDto(
                InternalName:        sel.InternalName,
                DisplayName:         display,

                GunpackPreviewUrl:   packGun.PreviewUrl,
                GunpackGlbUrl:       packGun.GlbUrl,
                GunpackPackName:     newPack.Name ?? gunpackId,

                SelectedPreviewUrl:   srcGun?.PreviewUrl,
                SelectedGlbUrl:       srcGun?.GlbUrl,
                SelectedFromPackId:   sel.GunpackId,
                SelectedFromPackName: sel.GunpackName));
        }

        var alreadyConflicted = new HashSet<string>(
            output.Select(o => o.InternalName), StringComparer.OrdinalIgnoreCase);
        foreach (var cust in customRows)
        {
            if (alreadyConflicted.Contains(cust.InternalName)) continue;

            if (string.Equals(cust.PackId, gunpackId, StringComparison.OrdinalIgnoreCase))
            {
                Debug.WriteLine($"[gunpack.check-conflicts] skipping custom '{cust.InternalName}' - painted from the same pack we're installing.");
                continue;
            }

            if (!newPackByInternal.TryGetValue(cust.InternalName, out var packGun)) continue;

            string display = cust.DisplayName;
            if (!string.IsNullOrWhiteSpace(packGun.DisplayName)) display = packGun.DisplayName!;
            else if (whitelistByInternal.TryGetValue(cust.InternalName, out var w)
                     && !string.IsNullOrWhiteSpace(w.DisplayName)) display = w.DisplayName;

            output.Add(new GunpackInstallConflictDto(
                InternalName:        cust.InternalName,
                DisplayName:         display,

                GunpackPreviewUrl:   packGun.PreviewUrl,
                GunpackGlbUrl:       packGun.GlbUrl,
                GunpackPackName:     newPack.Name ?? gunpackId,

                SelectedPreviewUrl:   null,
                SelectedGlbUrl:       null,
                SelectedFromPackId:   "_custom",
                SelectedFromPackName: cust.DisplayName));
        }

        Debug.WriteLine($"[gunpack.check-conflicts] pack='{newPack.Name}' selected={selectedRows.Count} customs={customRows.Count} conflicts={output.Count}");
        return output;
    }

