    public async Task<bool> ReconcileInstallStateAsync()
    {
        bool anyDrift = false;
        try
        {
            var gtaPath = await GetGtaPathAsync();
            if (!string.IsNullOrWhiteSpace(gtaPath) && Directory.Exists(gtaPath))
            {

                anyDrift |= await _gunpackInstaller.ReconcileStateAsync(gtaPath);
                anyDrift |= await _selectedGunsInstaller.ReconcileStateAsync();
            }
            else
            {
                Debug.WriteLine("[reconcile] gtaPath empty - skipping disk reconcile");
            }

            try
            {
                var reduxOrphans   = await _queue.ReconcileOrphansAsync();
                var gunpackOrphans = await _gunpackQueue.ReconcileOrphansAsync();
                if (reduxOrphans + gunpackOrphans > 0)
                {
                    Debug.WriteLine($"[reconcile] queues: reset {reduxOrphans} redux + {gunpackOrphans} gunpack orphans → error");
                    anyDrift = true;
                }
            }
            catch (Exception ex)
            {
                Debug.WriteLine($"[reconcile] queue-orphan sweep FAIL (non-fatal): {ex.Message}");
            }
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[reconcile] CRASH: {ex}");
        }
        return anyDrift;
    }

