    private Services.ISelectedGunsInstaller.EmitProgress MakeSelectedGunsEmit(string? internalName)
    {
        var sw = Stopwatch.StartNew();
        long lastEmitMs = -1;
        string? lastPhase = null;
        return (phase, percent, err, detail) =>
        {
            var nowMs = sw.ElapsedMilliseconds;
            var phaseChanged = phase != lastPhase;
            var terminal = phase is "done" or "error";
            if (!phaseChanged && !terminal && nowMs - lastEmitMs < 250) return;
            lastEmitMs = nowMs;
            lastPhase = phase;

            if (phaseChanged || terminal)
            {
                var d = err ?? detail;
                var msg = $"{internalName ?? "(rebuild)"} -> {phase} {percent}%{(string.IsNullOrWhiteSpace(d) ? "" : $" - {d}")}";
                if (phase == "error") Services.SessionLog.Error("selguns", msg);
                else Services.SessionLog.Info("selguns", msg);
            }

            SelGunsGate.Admit(internalName ?? "(rebuild)", internalName ?? string.Empty,
                phase, percent, err, detail);
        };
    }

    private Services.InstallProgressGate? _selGunsGate;
    private Services.InstallProgressGate SelGunsGate
    {
        get
        {
            if (_selGunsGate is not null) return _selGunsGate;
            lock (_progressGateLock)
                return _selGunsGate ??= new Services.InstallProgressGate(
                    (key, name, phase, percent, err, detail) =>
                        _emitEvent?.Invoke(Services.SelectedGunsInstaller.PROGRESS_EVENT, new
                        {
                            internalName  = string.IsNullOrEmpty(name) ? null : name,
                            phase,
                            percent,
                            errorMessage  = err,
                            detailMessage = detail,
                        }));
        }
    }

    private Services.InstallProgressGate? _gunpackGate;
    private Services.InstallProgressGate GunpackGate
    {
        get
        {
            if (_gunpackGate is not null) return _gunpackGate;
            lock (_progressGateLock)
                return _gunpackGate ??= new Services.InstallProgressGate(
                    (key, name, phase, percent, err, detail) =>
                        _emitEvent?.Invoke(Services.GunpackInstaller.PROGRESS_EVENT, new
                        {
                            gunpackId     = key,
                            phase,
                            percent,
                            errorMessage  = err,
                            detailMessage = detail,
                        }));
        }
    }

    private readonly Dictionary<string, string> _lastLoggedGunpackPhase = new(StringComparer.Ordinal);

    private void EmitGunpackInstallProgress(string gunpackId, string phase, int percent, string? errorMessage, string? detailMessage)
    {
        GunpackGate.Admit(gunpackId ?? string.Empty, gunpackId ?? string.Empty,
            phase, percent, errorMessage, detailMessage);

        if (string.Equals(phase, "done", StringComparison.OrdinalIgnoreCase)
         || string.Equals(phase, "error", StringComparison.OrdinalIgnoreCase)
         || string.Equals(phase, "cancelled", StringComparison.OrdinalIgnoreCase))
            Core.System.DataQuota.SweepInBackground($"после ганпака {gunpackId} ({phase})");

        try
        {
            var key = gunpackId ?? string.Empty;
            var isError = string.Equals(phase, "error", StringComparison.OrdinalIgnoreCase);
            lock (_installLogGate)
            {
                if (!isError && _lastLoggedGunpackPhase.TryGetValue(key, out var prev)
                    && string.Equals(prev, phase, StringComparison.Ordinal))
                    return;
                _lastLoggedGunpackPhase[key] = phase;
                if (phase is "done" or "error") _lastLoggedGunpackPhase.Remove(key);
            }
            var d = errorMessage ?? detailMessage;
            var msg = $"{gunpackId} -> {phase} {percent}%{(string.IsNullOrWhiteSpace(d) ? "" : $" - {d}")}";
            if (isError) Services.SessionLog.Error("gunpack", msg);
            else Services.SessionLog.Info("gunpack", msg);
        }
        catch { }
    }

