    public Task<HntCodeDto> HntCodeExportAsync(string userId)
        => HntCodeExportAsync(userId, includeRedux: true, includeGunpack: true, includeSelectedGuns: true);

    public async Task<HntCodeDto> HntCodeExportAsync(
        string userId,
        bool includeRedux,
        bool includeGunpack,
        bool includeSelectedGuns,
        bool includeComponents = true,
        IReadOnlyList<string>? gunFilter = null)
    {
        if (string.IsNullOrWhiteSpace(userId))
            throw new InvalidOperationException(Loc.T("errors.hnt.authRequired"));

        var payload = await CaptureHntPayloadAsync();

        if (includeRedux && string.IsNullOrWhiteSpace(payload.ReduxId))
            throw new InvalidOperationException(Loc.T("errors.hnt.noRedux"));

        if (!includeRedux)
        {
            payload = payload with
            {
                ReduxId        = null,
                ReduxVersionId = null,
                ReduxName      = null,
                ReduxAuthor    = null,
                Extras         = null,
            };
        }
        if (!includeGunpack)
        {
            payload = payload with
            {
                GunpackId   = null,
                GunpackName = null,
            };
        }
        if (!includeSelectedGuns)
        {
            payload = payload with { SelectedGuns = new List<HntSelectedGunDto>() };
        }
        else if (gunFilter is { Count: > 0 })
        {
            var wanted = new HashSet<string>(gunFilter, StringComparer.OrdinalIgnoreCase);
            payload = payload with
            {
                SelectedGuns = (payload.SelectedGuns ?? new List<HntSelectedGunDto>())
                    .Where(g => wanted.Contains(g.InternalName))
                    .ToList(),
            };
        }
        if (!includeComponents)
        {
            payload = payload with
            {
                Armor   = null,
                Minimap = null,
                Reticle = null,
                Sounds  = null,
                BigMap  = null,
            };
        }

        bool exportEmpty = string.IsNullOrWhiteSpace(payload.ReduxId)
            && string.IsNullOrWhiteSpace(payload.GunpackId)
            && (payload.SelectedGuns?.Count ?? 0) == 0
            && payload.Armor is null && payload.Minimap is null
            && payload.Reticle is null && payload.Sounds is null && payload.BigMap is null;
        if (exportEmpty)
            throw new InvalidOperationException(Loc.T("errors.hnt.empty"));

        var payloadElement = JsonSerializer.SerializeToElement(payload, _hntJsonOpts);

        var row = await _hntCodesRepo.ExportAsync(userId, payloadElement);
        Debug.WriteLine($"[hnt.export] code={row.Code} user={userId} mask=R{includeRedux}/G{includeGunpack}/S{includeSelectedGuns}/C{includeComponents} payloadBytes={payloadElement.GetRawText().Length}");
        return ToHntCodeDto(row);
    }

    public async Task<string> KnkShareAsync(string userId, ReticleSpecDto spec)
    {
        if (string.IsNullOrWhiteSpace(userId))
            throw new InvalidOperationException("KNK_AUTH_REQUIRED");
        if (spec is null)
