    public async Task<ReticleSpecDto> KnkFetchAsync(string code)
    {
        if (string.IsNullOrWhiteSpace(code))
            throw new InvalidOperationException("KNK_CODE_NOT_FOUND");
        var canonical = code.Trim().ToUpperInvariant();
        if (canonical.StartsWith("KNK-")) canonical = "HNT-" + canonical.Substring(4);

        Repositories.Models.HntCode row;
        try
        {
            row = await _hntCodesRepo.ImportAsync(canonical);
        }
        catch (SupabaseException ex) when (ex.Message.Contains("code_not_found", StringComparison.OrdinalIgnoreCase))
        {
            throw new InvalidOperationException("KNK_CODE_NOT_FOUND");
        }
        catch (SupabaseException ex) when (ex.Message.Contains("code_expired", StringComparison.OrdinalIgnoreCase))
        {
            throw new InvalidOperationException("KNK_CODE_EXPIRED");
        }

        try
        {
            if (row.Payload.ValueKind == JsonValueKind.Object
                && row.Payload.TryGetProperty("knkReticle", out var specEl))
            {
                var spec = JsonSerializer.Deserialize<ReticleSpecDto>(specEl.GetRawText(),
                    new JsonSerializerOptions { PropertyNameCaseInsensitive = true });
                if (spec is not null)
                {
                    var knk = "KNK-" + (row.Code.StartsWith("HNT-", StringComparison.OrdinalIgnoreCase)
                        ? row.Code.Substring(4) : row.Code);
                    return spec with { Code = knk };
                }
            }
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[knk.fetch] payload parse FAIL: {ex.Message}");
        }
        throw new InvalidOperationException("KNK_CODE_WRONG_KIND");
    }

    private void EmitScanProgress(int percent, string stage, string detail = "")
        => _emitEvent?.Invoke("optimization:scanProgress",
                              new OptimizationScanProgressDto(percent, stage, detail));

    private void EmitLegitProgress(int percent, string stage, string file = "")
        => _emitEvent?.Invoke("legitcheck:progress", new LegitCheckProgressDto(percent, stage, file));

    private static LegitReportDto ToLegitDto(Core.Services.LegitReport r) => new(
        r.Verdict switch
        {
            Core.Services.LegitVerdictKind.Safe => "safe",
            Core.Services.LegitVerdictKind.Mixed => "mixed",
            _ => "danger",
        },
        r.VerdictTitle, r.VerdictText, r.VerdictReasons, r.Source, r.CheckedAt,
        r.DangerCount, r.WarningCount, r.ChangedCount, r.AddedCount, r.DeletedCount,
        r.Findings.Select(f => new LegitFileFindingDto(
            f.Path, f.Change,
            f.Severity switch
            {
                Core.Services.LegitSeverity.Danger => "danger",
                Core.Services.LegitSeverity.Warning => "warning",
                Core.Services.LegitSeverity.Visual => "visual",
                _ => "neutral",
            },
            f.CategoryLabel, f.Note, f.FormatOnly, f.Size,
            f.FieldDiffs.Select(d => new LegitFieldDiffDto(
                d.Owner, d.Field, d.CleanValue, d.ModValue, d.DeltaPercent, d.IsRed)).ToList()
        )).ToList(),
        r.Unverified, r.CheckedCount);

    private static string? TryFindReduxCacheDir(string reduxId, int? slot)
    {
        try
        {
            var root = GetReduxCacheRoot();
            var candidates = new List<string>();
            if (slot.HasValue) candidates.Add(Path.Combine(root, $"{reduxId}__v{slot.Value}"));
            candidates.Add(Path.Combine(root, reduxId));
            foreach (var c in candidates)
            {
                if (File.Exists(Path.Combine(c, "manifest.json")) && Directory.Exists(Path.Combine(c, "patch_files")))
                    return c;
            }
        }
        catch { }
        return null;
    }

    private static (byte[]? bytes, string? where) ResolveVanillaBytes(string? cleanRpf, string? gtaRoot, string targetPath)
    {
        if (string.IsNullOrWhiteSpace(targetPath)) return (null, null);
        var norm = targetPath.Replace('\\', '/').TrimStart('/');
        string leaf = norm.Contains('/') ? norm[(norm.LastIndexOf('/') + 1)..] : norm;

        byte[]? Extract(string archive, string inner)
        {
            try { return Core.Services.LegitCheckService.TryExtractFileResilient(archive, inner); }
            catch { return null; }
        }

        if (!string.IsNullOrWhiteSpace(cleanRpf) && File.Exists(cleanRpf))
        {
            var b = Extract(cleanRpf!, norm);
            if (b != null) return (b, "чистый update.rpf");
            foreach (var basePath in new[] { "common/data/ai/" + leaf, "common/data/" + leaf })
            {
                var bb = Extract(cleanRpf!, basePath);
                if (bb != null) return (bb, "чистый update.rpf");
            }
        }

        bool isGunMeta = leaf.EndsWith(".meta", StringComparison.OrdinalIgnoreCase)
            && norm.Contains("/data/ai/", StringComparison.OrdinalIgnoreCase);

        if (!string.IsNullOrWhiteSpace(gtaRoot))
        {
            var m = System.Text.RegularExpressions.Regex.Match(
                norm, @"^dlc_patch/([^/]+)/(.+)$", System.Text.RegularExpressions.RegexOptions.IgnoreCase);
            if (!m.Success)
                m = System.Text.RegularExpressions.Regex.Match(
                    norm, @"dlcpacks/([^/]+)/dlc\.rpf/(.+)$", System.Text.RegularExpressions.RegexOptions.IgnoreCase);
            if (m.Success)
            {
                var dlc = m.Groups[1].Value;
                var inner = m.Groups[2].Value;
                var dlcRpf = Path.Combine(gtaRoot!, "update", "x64", "dlcpacks", dlc, "dlc.rpf");
                if (File.Exists(dlcRpf))
                {
                    var b = Extract(dlcRpf, inner);
                    if (b != null) return (b, $"dlcpack {dlc}");
                    if (isGunMeta)
                    {
                        var innerDir = inner.Contains('/') ? inner[..inner.LastIndexOf('/')] : "";
                        var (fb, fname) = Core.Services.LegitCheckService.TryExtractByGunBase(dlcRpf, innerDir, leaf);
                        if (fb != null) return (fb, $"dlcpack {dlc} · {fname}");
                    }
                }
            }

            var commonRpf = Path.Combine(gtaRoot!, "common.rpf");
            if (File.Exists(commonRpf))
            {
                var commonInner = norm.StartsWith("common/", StringComparison.OrdinalIgnoreCase)
                    ? norm["common/".Length..] : norm;
                foreach (var cand in new[] { commonInner, "data/ai/" + leaf, "data/" + leaf })
                {
                    var b = Extract(commonRpf, cand);
                    if (b != null) return (b, "common.rpf");
                }
            }
        }

        if (isGunMeta && !string.IsNullOrWhiteSpace(cleanRpf) && File.Exists(cleanRpf))
        {
            var (fb, fname) = Core.Services.LegitCheckService.TryExtractByGunBase(cleanRpf!, "common/data/ai", leaf);
            if (fb != null) return (fb, $"чистый update.rpf · {fname}");
        }

        return (null, null);
    }

    public async Task<LegitReportDto> LegitCheckReduxAsync(string reduxId, string? versionId = null)
    {
        if (string.IsNullOrWhiteSpace(reduxId))
            throw new ArgumentException("reduxId required", nameof(reduxId));

        Guid? vid = Guid.TryParse(versionId, out var g) ? g : (Guid?)null;
        var item = await _catalog.GetByIdAsync(reduxId);
        var resolved = await ResolveVersionAsync(reduxId, vid)
            ?? throw new InvalidOperationException(Loc.T("errors.legit.reduxNotFound"));
        if (string.IsNullOrWhiteSpace(resolved.Urls?.Manifest))
            throw new InvalidOperationException(Loc.T("errors.legit.noManifest"));

        EmitLegitProgress(2, "manifest");
        var tmpDir = Path.Combine(Path.GetTempPath(), "MiamiGraphics", "manifests");
        Directory.CreateDirectory(tmpDir);
        var dest = Path.Combine(tmpDir, $"legit_{reduxId}_{resolved.Slot?.ToString() ?? "legacy"}.json");
        await DownloadViaMirrorAsync(resolved.Urls.Manifest!, dest, null, CancellationToken.None);
        var manifest = JsonSerializer.Deserialize<Core.Parser.DiffManifest>(
                await File.ReadAllTextAsync(dest), ReduxJson)
            ?? throw new InvalidOperationException(Loc.T("errors.legit.manifestParse"));

        var cleanRpf = _backupService.GetCleanUpdateRpfPath();
        var gtaRoot = await GetGtaPathAsync();

        string? cacheDir = TryFindReduxCacheDir(reduxId, resolved.Slot);
        bool needBytes = (manifest.Actions ?? new()).Any(a =>
            a.Type != Core.Parser.ActionType.Delete
            && !string.IsNullOrWhiteSpace(a.TargetPath)
            && Core.Services.LegitCheckService.NeedsBytesForFieldDiff(a.TargetPath));
        if (needBytes && cacheDir is null)
        {
            EmitLegitProgress(5, "download");
            try
            {
                cacheDir = await EnsureReduxCachedAsync(reduxId, resolved.VersionId,
                    (_, p, _) => { if (p >= 0) EmitLegitProgress(Math.Min(70, 5 + p * 65 / 100), "download"); },
                    0, 100);
            }
            catch (Exception ex)
            {
                Debug.WriteLine($"[legit.redux] patch download failed, degrade to path-classification: {ex.Message}");
                cacheDir = null;
            }
        }

        string label = (item?.Name ?? reduxId)
            + (string.IsNullOrWhiteSpace(resolved.Label) ? "" : $" · {resolved.Label}");

        var svc = new Core.Services.LegitCheckService();
        var report = await Task.Run(() => svc.CheckFromManifest(
            manifest,
            fetchModBytes: a =>
            {
                if (cacheDir is null || string.IsNullOrWhiteSpace(a.SourcePath)) return null;
                var p = Path.Combine(cacheDir, a.SourcePath.Replace('/', '\\'));
                return File.Exists(p) ? File.ReadAllBytes(p) : null;
            },
            resolveVanilla: path => ResolveVanillaBytes(cleanRpf, gtaRoot, path),
            label,
            (p, f) => EmitLegitProgress(70 + p * 29 / 100, "scan", f),
            CancellationToken.None));

        if (item?.IsVerified == true && report.Verdict != Core.Services.LegitVerdictKind.Danger)
        {
            report.Verdict = Core.Services.LegitVerdictKind.Safe;
            report.VerdictTitle = "Безопасно - мод проверен";
            report.VerdictReasons.Insert(0, "Мод отмечен как «Проверенный» в каталоге Miami Graphics - модерация уже смотрела его содержимое.");
            report.VerdictText =
                "Этот мод несёт плашку «Проверенный»: его содержимое уже проверяла модерация Miami Graphics. " +
                "Автоматическая проверка опасных значений (отдача, разброс, урон, аим) тоже ничего не нашла.";
        }

        EmitLegitProgress(100, "done");
        Debug.WriteLine($"[legit.redux] {reduxId}: verdict={report.Verdict} danger={report.DangerCount} warn={report.WarningCount} verified={item?.IsVerified}");
        return ToLegitDto(report);
    }

    public async Task<LegitReportDto> LegitCheckUpdateRpfAsync(string? rpfPath = null)
    {
        var cleanRpf = _backupService.GetCleanUpdateRpfPath();
        if (string.IsNullOrWhiteSpace(cleanRpf))
            throw new InvalidOperationException(Loc.T("errors.legit.noClean"));

        string target;
        string label;
        if (string.IsNullOrWhiteSpace(rpfPath))
        {
            var gtaRoot = await GetGtaPathAsync();
            if (string.IsNullOrWhiteSpace(gtaRoot))
                throw new InvalidOperationException(Loc.T("errors.legit.noGta"));
            target = Path.Combine(gtaRoot, "update", "update.rpf");
            label = "Мой установленный update.rpf";
        }
        else
        {
            target = rpfPath!;
            label = $"Файл: {Path.GetFileName(target)}";
        }
        if (!File.Exists(target))
            throw new InvalidOperationException(Loc.T("errors.legit.fileNotFound", ("path", target)));

        EmitLegitProgress(0, "scan");
        var svc = new Core.Services.LegitCheckService();
        var report = await Task.Run(() => svc.CheckUpdateRpf(
            cleanRpf!, target, label,
            (p, f) => EmitLegitProgress(p, "scan", f),
            CancellationToken.None));
        EmitLegitProgress(100, "done");
        Debug.WriteLine($"[legit.rpf] {target}: verdict={report.Verdict} danger={report.DangerCount} warn={report.WarningCount}");
        return ToLegitDto(report);
    }

