    public async Task<HntImportResultDto> HntCodeApplyAsync(HntPayloadDto payload)
    {
        if (payload is null)
            return new HntImportResultDto(false, "Payload is null.", null, null, null);

        HntInstallStepResultDto reduxStep        = new(true, true, null);
        HntInstallStepResultDto gunpackStep      = new(true, true, null);
        HntInstallStepResultDto selectedGunsStep = new(true, true, null);

        bool customCrosshairAppliedWithRedux = false;

        if (!string.IsNullOrWhiteSpace(payload.ReduxId))
        {
            try
            {

                var customizeDraft = ExtractCustomizeDraft(payload);
                InjectResultDto r;
                if (customizeDraft is not null)
                {
                    Debug.WriteLine($"[hnt.apply] redux step using customize draft (reduxId='{payload.ReduxId}')");

                    var draftWithVersion = customizeDraft with { BaseVersionId = payload.ReduxVersionId };
                    r = await ReduxCustomizeApplyAsync(payload.ReduxId, draftWithVersion, null, null, alreadyLocked: false);
                }
                else
                {
                    r = await ReduxInstallAsync(payload.ReduxId, payload.ReduxVersionId);
                }
                reduxStep = new HntInstallStepResultDto(
                    Skipped: false,
                    Success: r.Success,
                    ErrorMessage: r.Success ? null : r.ErrorMessage);
                if (r.Success
                    && customizeDraft?.Crosshair is { } dcx
                    && string.Equals(dcx.Kind, "custom", StringComparison.OrdinalIgnoreCase)
                    && !string.IsNullOrWhiteSpace(dcx.CustomSpecJson))
                {
                    customCrosshairAppliedWithRedux = true;
                }
                if (!r.Success)
                {

                    return new HntImportResultDto(
                        Success: false,
                        ErrorMessage: r.ErrorMessage,
                        ReduxStep: reduxStep,
                        GunpackStep: new HntInstallStepResultDto(true, true, null),
                        SelectedGunsStep: new HntInstallStepResultDto(true, true, null));
                }
            }
            catch (Exception ex)
            {
                Debug.WriteLine($"[hnt.apply] redux step CRASH: {ex.Message}");
                reduxStep = new HntInstallStepResultDto(false, false, ex.Message);
                return new HntImportResultDto(false, ex.Message, reduxStep,
                    new HntInstallStepResultDto(true, true, null),
                    new HntInstallStepResultDto(true, true, null));
            }
        }

        if (!string.IsNullOrWhiteSpace(payload.GunpackId))
        {
            try
            {
                var r = await GunpackInstallAllAsync(payload.GunpackId);
                gunpackStep = new HntInstallStepResultDto(
                    Skipped: false,
                    Success: r.Success,
                    ErrorMessage: r.Success ? null : r.ErrorMessage);
            }
            catch (Exception ex)
            {
                Debug.WriteLine($"[hnt.apply] gunpack step CRASH: {ex.Message}");
                gunpackStep = new HntInstallStepResultDto(false, false, ex.Message);
            }
        }

        if (payload.SelectedGuns is { Count: > 0 })
        {
            int okCount = 0;
            var failures = new List<string>();
            foreach (var g in payload.SelectedGuns)
            {
                try
                {
                    var r = await SelectedGunsInstallAsync(g.GunpackId, g.InternalName);
                    if (r.Success) okCount++;
                    else           failures.Add($"{g.DisplayName}: {r.ErrorMessage ?? "unknown"}");
                }
                catch (Exception ex)
                {
                    failures.Add($"{g.DisplayName}: {ex.Message}");
                }
            }
            selectedGunsStep = new HntInstallStepResultDto(
                Skipped: false,
                Success: failures.Count == 0,
                ErrorMessage: failures.Count == 0 ? null
                    : Loc.T("errors.hnt.gunsPartial",
                        ("done", okCount),
                        ("total", payload.SelectedGuns.Count),
                        ("failures", string.Join("; ", failures))));
        }

        var componentErrors = new List<string>();
        bool anyComponent = false;

        if (payload.Armor is { } armor && !string.IsNullOrWhiteSpace(armor.Id))
        {
            anyComponent = true;
            try
            {
                InjectResultDto r;
                if (string.Equals(armor.Source, "library", StringComparison.OrdinalIgnoreCase))
                    r = await ArmorLibraryInstallAsync(armor.Id, overlayMode: true, force: true, alreadyLocked: false);
                else if (!string.IsNullOrWhiteSpace(payload.ReduxId))
                    r = await ReduxApplyArmorSwapAsync(armor.Id, null);
                else
                    r = await ArmorInstallStandaloneAsync(armor.Id, null, force: true);
                if (!r.Success) componentErrors.Add($"{Loc.T("errors.hnt.componentArmor")}: {r.ErrorMessage ?? "unknown"}");
            }
            catch (Exception ex) { componentErrors.Add($"{Loc.T("errors.hnt.componentArmor")}: {ex.Message}"); }
        }

        if (payload.Minimap is { } mm && !string.IsNullOrWhiteSpace(mm.Id))
        {
            anyComponent = true;
            try
            {
                var r = await ReduxApplyMinimapAsync(mm.Source, mm.Id, mm.Name);
                if (!r.Success) componentErrors.Add($"{Loc.T("errors.hnt.componentMinimap")}: {r.ErrorMessage ?? "unknown"}");
            }
            catch (Exception ex) { componentErrors.Add($"{Loc.T("errors.hnt.componentMinimap")}: {ex.Message}"); }
        }

        if (payload.Reticle is { } rtc
            && string.Equals(rtc.Source, "custom", StringComparison.OrdinalIgnoreCase))
        {
            if (customCrosshairAppliedWithRedux)
            {
                Debug.WriteLine("[hnt.apply] custom reticle already applied with the redux draft - skipping component step");
            }
            else if (!string.IsNullOrWhiteSpace(rtc.Id))
            {
                anyComponent = true;
                try
                {
                    var spec = await KnkFetchAsync(rtc.Id!);
                    var r = await ReticleApplyCustomAsync(spec);
                    if (!r.Success) componentErrors.Add($"{Loc.T("errors.hnt.componentReticle")}: {r.ErrorMessage ?? "unknown"}");
                }
                catch (Exception ex) { componentErrors.Add($"{Loc.T("errors.hnt.componentReticle")}: {ex.Message}"); }
            }
            else
            {
                anyComponent = true;
                componentErrors.Add(Loc.T("errors.hnt.reticleNoKnk"));
            }
        }
        else if (payload.Reticle is { } rt && !string.IsNullOrWhiteSpace(rt.Id))
        {
            anyComponent = true;
            try
            {
                var r = await ReduxApplyReticleAsync(rt.Source, rt.Id, rt.Name);
                if (!r.Success) componentErrors.Add($"{Loc.T("errors.hnt.componentReticle")}: {r.ErrorMessage ?? "unknown"}");
            }
            catch (Exception ex) { componentErrors.Add($"{Loc.T("errors.hnt.componentReticle")}: {ex.Message}"); }
        }

        if (payload.Sounds is { } snd && !string.IsNullOrWhiteSpace(snd.Id))
        {
            anyComponent = true;
            try
            {
                var r = await SoundPackInstallAsync(snd.Id, snd.Name);
                if (!r.Success) componentErrors.Add($"{Loc.T("errors.hnt.componentSounds")}: {r.ErrorMessage ?? "unknown"}");
            }
            catch (Exception ex) { componentErrors.Add($"{Loc.T("errors.hnt.componentSounds")}: {ex.Message}"); }
        }

        if (payload.BigMap is { } bmap && !string.IsNullOrWhiteSpace(bmap.Id))
        {
            anyComponent = true;
            try
            {
                var r = await BigMapInstallAsync(bmap.Id);
                if (!r.Success) componentErrors.Add($"{Loc.T("errors.hnt.componentBigMap")}: {r.ErrorMessage ?? "unknown"}");
            }
            catch (Exception ex) { componentErrors.Add($"{Loc.T("errors.hnt.componentBigMap")}: {ex.Message}"); }
        }

        var componentsStep = anyComponent
            ? new HntInstallStepResultDto(
                Skipped: false,
                Success: componentErrors.Count == 0,
                ErrorMessage: componentErrors.Count == 0 ? null : string.Join("; ", componentErrors))
            : new HntInstallStepResultDto(true, true, null);

        var overallSuccess = reduxStep.Success && gunpackStep.Success
            && selectedGunsStep.Success && componentsStep.Success;
        return new HntImportResultDto(
            Success: overallSuccess,
            ErrorMessage: overallSuccess ? null
                : reduxStep.ErrorMessage ?? gunpackStep.ErrorMessage
                    ?? selectedGunsStep.ErrorMessage ?? componentsStep.ErrorMessage,
            ReduxStep: reduxStep,
            GunpackStep: gunpackStep,
            SelectedGunsStep: selectedGunsStep,
            ComponentsStep: componentsStep);
    }

    private async Task<HntPayloadDto> CaptureHntPayloadAsync()
    {
        var state = ReadInstallState();
        string? reduxName   = null;
        string? reduxAuthor = null;
        if (state is not null && !string.IsNullOrWhiteSpace(state.ReduxId))
        {
            try
            {
                var item = await _catalog.GetByIdAsync(state.ReduxId);
                reduxName   = item?.Name;
                reduxAuthor = item?.Author;
            }
            catch (Exception ex) { Debug.WriteLine($"[hnt.export] redux catalog lookup failed: {ex.Message}"); }
        }

        var gunpackState = await _gunpackInstaller.GetInstalledStateAsync();

        var selectedRows = await _selectedGunsInstaller.ListInstalledAsync();
        var selectedGuns = selectedRows
            .Select(g => new HntSelectedGunDto(
                GunpackId:    g.GunpackId,
                GunpackName:  g.GunpackName,
                InternalName: g.InternalName,
                DisplayName:  g.DisplayName))
            .ToList();

        JsonElement? extras = null;
        if (state?.CustomizationDraft is not null)
        {
            var extrasObj = new { customizeDraft = state.CustomizationDraft };
            extras = JsonSerializer.SerializeToElement(extrasObj, _hntJsonOpts);
        }

        HntComponentRefDto? armorRef = null;
        try
        {
            var a = await GetCurrentArmorInfoAsync();
            if (a is not null
                && !string.Equals(a.Kind, "none", StringComparison.OrdinalIgnoreCase)
                && !(string.Equals(a.Kind, "redux", StringComparison.OrdinalIgnoreCase)
                     && string.Equals(a.Id, state?.ReduxId, StringComparison.OrdinalIgnoreCase)))
                armorRef = new HntComponentRefDto(a.Kind, a.Id, a.Name);
        }
        catch (Exception ex) { Debug.WriteLine($"[hnt.export] armor capture failed: {ex.Message}"); }

        HntComponentRefDto? minimapRef = null;
        try
        {
            var m = await GetCurrentMinimapInfoAsync();
            if (m is not null) minimapRef = new HntComponentRefDto(m.Kind, m.Id, m.Name);
        }
        catch (Exception ex) { Debug.WriteLine($"[hnt.export] minimap capture failed: {ex.Message}"); }

        HntComponentRefDto? reticleRef = null;
        try
        {
            var r = await GetCurrentReticleInfoAsync();
            if (r is not null) reticleRef = new HntComponentRefDto(r.Kind, r.Id, r.Name);
        }
        catch (Exception ex) { Debug.WriteLine($"[hnt.export] reticle capture failed: {ex.Message}"); }

        HntComponentRefDto? soundsRef = null;
        try
        {
            var s = await GetCurrentSoundPackInfoAsync();
            if (s is not null) soundsRef = new HntComponentRefDto("library", s.Id, s.Name);
        }
        catch (Exception ex) { Debug.WriteLine($"[hnt.export] sounds capture failed: {ex.Message}"); }

        HntComponentRefDto? bigMapRef = null;
        try
        {
            var b = await BigMapGetStateAsync();
            if (b.Enabled && !string.IsNullOrWhiteSpace(b.Id))
                bigMapRef = new HntComponentRefDto("library", b.Id!, b.Name);
        }
        catch (Exception ex) { Debug.WriteLine($"[hnt.export] bigmap capture failed: {ex.Message}"); }

        return new HntPayloadDto(
            ReduxId:        state?.ReduxId,
            ReduxVersionId: state?.VersionId,
            ReduxName:      reduxName,
            ReduxAuthor:    reduxAuthor,
            GunpackId:      gunpackState.ActiveGunpackId,
            GunpackName:    gunpackState.ActiveGunpackName,
            SelectedGuns:   selectedGuns,
            Extras:         extras,
            Armor:          armorRef,
            Minimap:        minimapRef,
            Reticle:        reticleRef,
            Sounds:         soundsRef,
            BigMap:         bigMapRef);
    }

    private static CustomizationDraftDto? ExtractCustomizeDraft(HntPayloadDto payload)
    {
        if (payload.Extras is not { } extras) return null;
        if (extras.ValueKind != JsonValueKind.Object) return null;
        if (!extras.TryGetProperty("customizeDraft", out var draftEl)) return null;
        if (draftEl.ValueKind == JsonValueKind.Null) return null;
        try
        {
            return draftEl.Deserialize<CustomizationDraftDto>(_hntJsonOpts);
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[hnt] customize draft deserialize failed: {ex.Message}");
            return null;
        }
    }

    private static HntCodeDto ToHntCodeDto(HntCode row)
    {

        HntPayloadDto payload;
        try
        {
            payload = row.Payload.Deserialize<HntPayloadDto>(_hntJsonOpts)
                ?? new HntPayloadDto(null, null, null, null, null, null, new List<HntSelectedGunDto>(), null);
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[hnt] payload deserialize failed: {ex.Message}");
            payload = new HntPayloadDto(null, null, null, null, null, null, new List<HntSelectedGunDto>(), null);
        }

        return new HntCodeDto(
            Code:             row.Code,
            Payload:          payload,
            CreatedBy:        row.CreatedBy,
            CreatedAt:        row.CreatedAt,
            LastDownloadedAt: row.LastDownloadedAt,
            DownloadsCount:   row.DownloadsCount);
    }

    private static readonly JsonSerializerOptions _hntJsonOpts = new()
    {
        PropertyNameCaseInsensitive = true,
        PropertyNamingPolicy        = JsonNamingPolicy.CamelCase,
    };

