#if ADMIN
    public async Task<string> AdminMirrorImageToR2Async(string reduxId, string externalUrl, string slot)
    {
        if (string.IsNullOrWhiteSpace(reduxId))
            throw new ArgumentException("reduxId required", nameof(reduxId));
        if (string.IsNullOrWhiteSpace(externalUrl))
            throw new ArgumentException("externalUrl required", nameof(externalUrl));
        if (!Uri.TryCreate(externalUrl, UriKind.Absolute, out var uri))
            throw new ArgumentException("externalUrl must be a valid absolute URL", nameof(externalUrl));

        var host = uri.Host.ToLowerInvariant();
        if (host.EndsWith("miamigraphicsstorage.uk", StringComparison.Ordinal)
            || host.EndsWith(".r2.dev", StringComparison.Ordinal)
            || host.EndsWith(".r2.cloudflarestorage.com", StringComparison.Ordinal))
        {
            return externalUrl;
        }

        var slotSafe = string.IsNullOrWhiteSpace(slot)
            ? "mirror"
            : new string(slot.Where(c => char.IsLetterOrDigit(c) || c is '_' or '-').ToArray());
        if (string.IsNullOrEmpty(slotSafe)) slotSafe = "mirror";

        using var http = Services.HttpClientFactory.CreateFragmenting(TimeSpan.FromMinutes(2));
        using var resp = await http.GetAsync(uri, HttpCompletionOption.ResponseContentRead, CancellationToken.None);
        resp.EnsureSuccessStatusCode();
        var bytes = await resp.Content.ReadAsByteArrayAsync();
        var contentType = resp.Content.Headers.ContentType?.MediaType?.ToLowerInvariant() ?? string.Empty;
        var ext = contentType switch
        {
            "image/png"  => ".png",
            "image/jpeg" => ".jpg",
            "image/webp" => ".webp",
            "image/gif"  => ".gif",
            _ => Path.GetExtension(uri.AbsolutePath).ToLowerInvariant() switch
            {
                ".png" or ".jpg" or ".jpeg" or ".webp" or ".gif" => Path.GetExtension(uri.AbsolutePath).ToLowerInvariant(),
                _ => ".jpg",
            },
        };
        if (ext == ".jpeg") ext = ".jpg";

        var temp = Path.Combine(Path.GetTempPath(), $"mg_mirror_{Guid.NewGuid():N}{ext}");
        try
        {
            await File.WriteAllBytesAsync(temp, bytes);
            var remoteKey = $"redux/{reduxId}/mirror/{slotSafe}{ext}";
            var url = await _remoteStorage.UploadHashedAsync(temp, remoteKey, null, CancellationToken.None);
            _assetCache?.Invalidate(url);
            Debug.WriteLine($"[admin.mirror] {externalUrl} -> {url}");
            return url;
        }
        finally
        {
            try { if (File.Exists(temp)) File.Delete(temp); } catch { }
        }
    }
#endif

#if ADMIN
    public async Task<string> AdminUploadComponentScreenshotAsync(
        string reduxId, string component, string sourcePath)
    {
        if (string.IsNullOrWhiteSpace(reduxId))
            throw new ArgumentException("reduxId required", nameof(reduxId));
        if (string.IsNullOrWhiteSpace(component))
            throw new ArgumentException("component required", nameof(component));
        if (string.IsNullOrWhiteSpace(sourcePath))
            throw new ArgumentException("sourcePath required", nameof(sourcePath));
        if (!File.Exists(sourcePath))
            throw new FileNotFoundException("source file not found", sourcePath);

        var allowed = new HashSet<string>(StringComparer.OrdinalIgnoreCase)
        {
            "armor", "arena", "minimap", "crosshair", "tracers", "bloodfx", "timecycle",
            "preview",
        };
        if (!allowed.Contains(component))
            throw new ArgumentException($"unsupported component '{component}'", nameof(component));

        var origExt = Path.GetExtension(sourcePath).ToLowerInvariant();
        if (origExt != ".png" && origExt != ".jpg" && origExt != ".jpeg" && origExt != ".webp")
            throw new ArgumentException(
                "screenshot must be a .png / .jpg / .webp file", nameof(sourcePath));

        var (localPath, ext, isTemp) = await EnsureWebPAsync(sourcePath);
        try
        {
            var remoteKey = component.Equals("preview", StringComparison.OrdinalIgnoreCase)
                ? $"redux/{reduxId}/preview{ext}"
                : $"redux/{reduxId}/screenshots/{component.ToLowerInvariant()}{ext}";
            var url = await _remoteStorage.UploadHashedAsync(localPath, remoteKey, null, CancellationToken.None);
            _assetCache?.Invalidate(url);
            Debug.WriteLine($"[admin.uploadScreenshot] {reduxId}/{component} -> {url}");
            return url;
        }
        finally
        {
            if (isTemp && File.Exists(localPath)) try { File.Delete(localPath); } catch { }
        }
    }
#endif

    public async Task<string> UserBuildUploadCoverAsync(string sourcePath)
    {
        if (string.IsNullOrWhiteSpace(sourcePath) || !File.Exists(sourcePath))
            throw new ArgumentException("sourcePath required + must exist", nameof(sourcePath));
        var origExt = Path.GetExtension(sourcePath).ToLowerInvariant();
        if (origExt != ".png" && origExt != ".jpg" && origExt != ".jpeg" && origExt != ".webp" && origExt != ".gif")
            throw new ArgumentException("cover must be .png / .jpg / .webp / .gif", nameof(sourcePath));

        var (localPath, ext, isTemp) = await EnsureWebPAsync(sourcePath);
        try
        {
            var key = $"user-builds/covers/{Guid.NewGuid():N}{ext}";
            var url = await _remoteStorage.UploadAsync(localPath, key, progress: null, CancellationToken.None);
            Debug.WriteLine($"[userBuild.uploadCover] {sourcePath} -> {url}");
            return url;
        }
        finally
        {
            if (isTemp && File.Exists(localPath)) try { File.Delete(localPath); } catch { }
        }
    }

    public async Task<string> UserBuildUploadSettingsXmlAsync(string buildId, string sourceXmlPath)
    {
        if (string.IsNullOrWhiteSpace(buildId))
            throw new ArgumentException("buildId required", nameof(buildId));
        if (string.IsNullOrWhiteSpace(sourceXmlPath) || !File.Exists(sourceXmlPath))
            throw new ArgumentException("sourceXmlPath required + must exist", nameof(sourceXmlPath));
        var ext = Path.GetExtension(sourceXmlPath).ToLowerInvariant();
        if (ext != ".xml")
            throw new ArgumentException("settings.xml must have .xml extension", nameof(sourceXmlPath));
        var key = $"user-builds/{buildId}/settings.xml";
        var url = await _remoteStorage.UploadAsync(sourceXmlPath, key, progress: null, CancellationToken.None);
        Debug.WriteLine($"[userBuild.uploadSettingsXml] {sourceXmlPath} → {url}");
        return url;
    }

