        "gunSlotsJson"          => "gun_slots",
        "armorJson"             => "armor",
        "arenaJson"             => "arena",
        "minimapJson"           => "minimap",
        "reticleJson"           => "reticle",
        "soundsJson"            => "sounds",
        "devicesJson"           => "devices",
        "sensitivity"           => "sensitivity",
        "dpi"                   => "dpi",
        "resolution"            => "resolution",
        "videoUrl"              => "video_url",
        "settingsXmlUrl"        => "settings_xml_url",
        "description"           => "description",
        "tier"                  => "tier",
