    public async Task<PresetReactionsDto> GtaPresetReactionsGetAsync(string presetId, string userId)
    {
        if (string.IsNullOrWhiteSpace(presetId)) return new PresetReactionsDto(0, 0, 0);
        try
        {
            var rows = await _supabase.SelectAsync<PresetReactionRow>(
                "preset_reactions",
                $"select=user_id,reaction&preset_id=eq.{Uri.EscapeDataString(presetId)}&limit=100000");
            long likes = 0, dislikes = 0; int mine = 0;
            foreach (var r in rows)
            {
                if (r.Reaction == 1) likes++;
                else if (r.Reaction == -1) dislikes++;
                if (!string.IsNullOrEmpty(userId) && string.Equals(r.UserId, userId, StringComparison.Ordinal))
                    mine = r.Reaction;
            }
            return new PresetReactionsDto(likes, dislikes, mine);
        }
        catch (SupabaseException sx)
        {
            Debug.WriteLine($"[preset.reactions.get] FAIL kind={sx.Kind} status={sx.StatusCode}");
            return new PresetReactionsDto(0, 0, 0);
        }
    }

    public async Task<PresetReactionsDto> GtaPresetReactionSetAsync(string presetId, int reaction)
    {
        if (string.IsNullOrWhiteSpace(presetId))
            throw new InvalidOperationException("preset_id required");
        if (reaction != 1 && reaction != -1)
            throw new InvalidOperationException("reaction must be 1 or -1");
        try
        {
            var row = await _supabase.RpcSingleAsync<PresetReactionAggRow>(
                "preset_reaction_set_secure",
                new
                {
                    p_token     = SupabaseClient.UserSessionToken,
                    p_preset_id = presetId,
                    p_reaction  = reaction,
                });
            if (row is null) return new PresetReactionsDto(0, 0, 0);
            return new PresetReactionsDto(row.Likes, row.Dislikes, row.MyReaction ?? 0);
        }
        catch (SupabaseException sx)
        {
            Debug.WriteLine($"[preset.reactions.set] FAIL kind={sx.Kind} status={sx.StatusCode} msg={sx.Message}");
            throw new InvalidOperationException(MapSupabaseError(sx), sx);
        }
    }

