    {
        public string? UserId   { get; set; }
        public int     Reaction { get; set; }
    }
    private sealed class PresetReactionAggRow
    {
        public long Likes      { get; set; }
        public long Dislikes   { get; set; }
        public int? MyReaction { get; set; }
    }

    public async Task<Dictionary<string, long>> GtaInstallCountsAsync(string eventType)
    {
        var result = new Dictionary<string, long>(StringComparer.OrdinalIgnoreCase);
        if (string.IsNullOrWhiteSpace(eventType)) return result;
        try
        {
            var rows = await _supabase.RpcManyAsync<InstallCountRow>(
                "activity_install_counts", new { p_event_type = eventType });
            foreach (var r in rows)
                if (!string.IsNullOrEmpty(r.ItemName))
                    result[r.ItemName!] = r.Installs;
        }
        catch (SupabaseException sx)
        {
            Debug.WriteLine($"[install.counts] FAIL kind={sx.Kind} status={sx.StatusCode}");
        }
        return result;
    }

