    {
        var preset = await _gtaPresetsRepo.GetByIdAsync(id);
        if (preset is null)
            return new GtaPresetApplyResultDto(false, "Пресет не найден.", string.Empty, null, false);
        if (string.IsNullOrWhiteSpace(preset.XmlUrl))
            return new GtaPresetApplyResultDto(false, "У пресета не указан XML URL.", string.Empty, null, false);

        return await GtaSettingsApplyFromUrlAsync(preset.XmlUrl);
    });

    public Task<GtaPresetApplyResultDto> GtaSettingsApplyFromUrlAsync(string xmlUrl) => Task.Run(async () =>
    {
        if (string.IsNullOrWhiteSpace(xmlUrl))
            return new GtaPresetApplyResultDto(false, "URL пустой.", string.Empty, null, false);

        string xmlText;
        try
        {
            var candidates = BuildDownloadCandidates(xmlUrl);
            Exception? last = null;
            string? got = null;
            foreach (var candidate in candidates)
            {
                try
                {
                    using var httpx = HttpClientFactory.CreateFragmenting(TimeSpan.FromSeconds(30));
                    got = await httpx.GetStringAsync(candidate);
                    if (!string.IsNullOrWhiteSpace(got))
                    {
                        if (!string.Equals(candidate, xmlUrl, StringComparison.Ordinal))
                            Debug.WriteLine($"[gta.settings] xml с зеркала {candidate}");
                        break;
                    }
                }
                catch (Exception ex)
                {
                    last = ex;
                    Debug.WriteLine($"[gta.settings] кандидат не отдал xml ({candidate}): {ex.GetType().Name}: {ex.Message}");
                    got = null;
                }
            }
            if (string.IsNullOrWhiteSpace(got))
                throw last ?? new InvalidOperationException(Loc.T("errors.gtaSettings.noMirrorXml"));
            xmlText = got;
        }
        catch (Exception ex)
        {
            var friendly = IsTransientNetworkError(ex)
                ? Loc.T("errors.gtaSettings.presetDownloadFlaky")
                : Loc.T("errors.gtaSettings.xmlDownloadFailed", ("message", ex.Message));
            return new GtaPresetApplyResultDto(false, friendly, string.Empty, null, false);
        }

        var applier = new Core.Services.GtaSettingsApplier();
        var result  = await applier.ApplyAsync(xmlText);
        return new GtaPresetApplyResultDto(
            result.Success,
            result.ErrorMessage,
            result.TargetPath,
            result.BackupPath,
            result.GameWasRunning);
    });

