#if ADMIN
    public Task<GtaPresetDto> AdminGtaPresetUploadAsync(GtaPresetUploadRequestDto request) => Task.Run(async () =>
    {
        if (!File.Exists(request.SourceXmlPath))
            throw new InvalidOperationException($"XML-файл не найден: {request.SourceXmlPath}");

        var bytes = await File.ReadAllBytesAsync(request.SourceXmlPath);
        var xmlText = System.Text.Encoding.UTF8.GetString(bytes);
        var analysis = _gtaAnalyzer.Analyze(xmlText);

        var sha256 = ComputeSha256Hex(bytes);
        var existing = await _gtaPresetsRepo.FindByXmlSha256Async(sha256);
        if (existing is not null)
        {

            throw new InvalidOperationException(
                $"Этот XML уже загружен как «{existing.Name}» (id={existing.Id}). " +
                $"Удали старый или поправь существующий через AdminGtaPresetPatch.");
        }

        var presetId = Guid.NewGuid().ToString();
        var remoteKey = $"gta-presets/{presetId}.xml";
        var url = await _remoteStorage.UploadAsync(request.SourceXmlPath, remoteKey, null, CancellationToken.None);

        var item = new Admin.GtaPresetItem
        {
            Id                  = presetId,
            Name                = request.Name?.Trim()        ?? string.Empty,
            Description         = request.Description?.Trim() ?? string.Empty,
            Author              = request.Author?.Trim()      ?? string.Empty,
            XmlUrl              = url,
            XmlSizeBytes        = bytes.LongLength,
            XmlSha256           = sha256,
            ExpectedFpsLow      = request.ExpectedFpsLow,
            ExpectedFpsHigh     = request.ExpectedFpsHigh,
            BaselineHwLabel     = request.BaselineHwLabel,
            ComputedGainPercent = analysis.GainPercent,
            CpuBias             = analysis.CpuBias,
            IsTournament        = request.IsTournament,
            Status              = string.IsNullOrWhiteSpace(request.Status) ? "published" : request.Status,
            ViewerPriority      = request.ViewerPriority,
            DownloadCount       = 0,
            UploadedBy          = string.Empty,
            UploadedAt          = DateTime.UtcNow,
            UpdatedAt           = DateTime.UtcNow,
        };
        await _gtaPresetsRepo.AddAsync(item);
        return ToGtaPresetDto(item);
    });
#endif

