#if ADMIN
    public async Task<AdminWipeAllResultDto> AdminWipeAllAsync(string category)
    {
        if (string.IsNullOrWhiteSpace(category))
            throw new ArgumentException("category required", nameof(category));

        int deleted = 0;
        int failed  = 0;
        var key = category.Trim().ToLowerInvariant();

        async Task TryDelete<T>(T id, Func<T, Task> doDelete) where T : notnull
        {
            try { await doDelete(id); deleted++; }
            catch (Exception ex)
            {
                failed++;
                Debug.WriteLine($"[wipeAll.{key}] '{id}' failed: {ex.Message}");
            }
        }

        switch (key)
        {
            case "redux":
            {
                var items = await _catalog.ListAsync(new Admin.ReduxFilter { Status = null });
                foreach (var x in items) await TryDelete(x.Id, AdminCatalogDeleteAsync);
                break;
            }
            case "gunpacks":
            {
                var items = await _gunpackRepo.ListAsync();
                foreach (var x in items) await TryDelete(x.Id, AdminGunpackDeleteAsync);
                break;
            }
            case "gtapresets":
            {
                var items = await _gtaPresetsRepo.ListAsync(new Admin.GtaPresetFilter { Status = null });
                foreach (var x in items) await TryDelete(x.Id, AdminGtaPresetDeleteAsync);
                break;
            }
            case "library":
            {

                var rows = await _supabase.SelectAsync<LibraryIdRow>(
                    "library_components", "select=id");
                foreach (var x in rows) await TryDelete(x.Id, LibraryDeleteAsync);
                break;
            }
            case "armorlibrary":
            {
                var items = await ArmorLibraryRepo.ListAsync(null);
                foreach (var x in items) await TryDelete(x.Id, ArmorLibraryDeleteAsync);
                break;
            }
            case "userbuilds":
            {

                var rows = await _supabase.SelectAsync<LibraryIdRow>(
                    "user_builds", "select=id");
                foreach (var x in rows) await TryDelete(x.Id, UserBuildDeleteAsync);
                break;
            }
            default:
                throw new ArgumentException($"Unknown category '{category}'.", nameof(category));
        }

        Debug.WriteLine($"[wipeAll.{key}] done: deleted={deleted} failed={failed}");
        return new AdminWipeAllResultDto(deleted, failed);
    }
#endif

