    private static GtaPresetDto ToGtaPresetDto(Admin.GtaPresetItem i) => new(
        Id:                  i.Id,
        Name:                i.Name,
        Description:         i.Description,
        Author:              i.Author,
        XmlUrl:              i.XmlUrl,
