    public Task<GtaPresetApplyResultDto> GtaSettingsWriteAsync(GtaSettingsModelDto model) => Task.Run(async () =>
    {
        var path = Core.Services.GtaSettingsApplier.GetSettingsPath();
        var coreModel = ToCore(model);

        System.Xml.Linq.XDocument doc;
        if (File.Exists(path))
        {
            try
            {
                doc = System.Xml.Linq.XDocument.Load(path);
            }
            catch
            {

                doc = System.Xml.Linq.XDocument.Parse(coreModel.ToXml());
            }
        }
        else
        {
            doc = System.Xml.Linq.XDocument.Parse(coreModel.ToXml());
        }

        coreModel.ApplyTo(doc);

        var applier = new Core.Services.GtaSettingsApplier();
        var result  = await applier.ApplyAsync(doc.ToString());
        return new GtaPresetApplyResultDto(
            result.Success,
            result.ErrorMessage,
            result.TargetPath,
            result.BackupPath,
            result.GameWasRunning);
    });

    private Admin.IOptimizationCatalogRepository? _optRepo;
    private Admin.IOptimizationCatalogRepository OptRepo
        => _optRepo ??= new Admin.SupabaseOptimizationCatalogRepository(_supabase);

    private readonly Core.Services.OptimizationApplyService _optApply = new();

    private const string GameGeneration = "gen8";

    private static string Pick(IReadOnlyDictionary<string, string> byLocale)
    {
        var lang = Core.I18n.Loc.Language;
        if (byLocale.TryGetValue(lang, out var s) && !string.IsNullOrWhiteSpace(s)) return s;
        if (byLocale.TryGetValue("en", out var en) && !string.IsNullOrWhiteSpace(en)) return en;
        return byLocale.Values.FirstOrDefault(v => !string.IsNullOrWhiteSpace(v)) ?? string.Empty;
    }

    public Task<OptimizationCatalogDto> OptimizationCatalogGetAsync() => Task.Run(async () =>
    {
        var catalog = await OptRepo.GetAsync();
        var groups = catalog.Groups
            .Where(g => (g.TouchesSettings
                         || g.Methods.Contains("mod", StringComparer.OrdinalIgnoreCase))
                        && g.SupportsGeneration(GameGeneration))
            .OrderBy(g => g.Position)
            .Select(g => new OptimizationGroupDto(
                Key:         g.Key,
                Style:       g.Style,
                Title:       Pick(g.Title),
                Description: Pick(g.Description),
                IconUrl:     g.IconUrl,
                ResetIndex:  g.ResetIndex,
                Beta:        g.Beta,
                Options:     g.Options.Select(o => new OptimizationOptionDto(
                                 o.Idx, Pick(o.Name), o.PreviewUrl, o.FpsLabel, o.Settings.Count)).ToList()))
            .ToList();
        return new OptimizationCatalogDto(groups, catalog.Validate());
    });

    public Task<OptimizationResolutionDto> OptimizationStateGetAsync() => Task.Run(async () =>
    {
        EmitScanProgress(0, "catalog");
        var catalog = await OptRepo.GetAsync();

        EmitScanProgress(20, "settings");
        var path = Core.Services.GtaSettingsApplier.GetSettingsPath();
        var model = File.Exists(path)
            ? Core.Services.GtaSettingsModel.FromXml(File.ReadAllText(path))
            : Core.Services.GtaSettingsModel.Defaults();
        var r = Core.Services.OptimizationPresetResolver.Resolve(model, catalog);

        var selections = new Dictionary<string, int?>(r.Selections, StringComparer.OrdinalIgnoreCase);
        var custom = new List<string>(r.CustomGroups);
        var markers = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        try
        {
            var gtaPath = await GetGtaPathAsync();

            var cleanFor = _backupService.GetCleanUpdateRpfPath() is { } cleanUpdate
                ? new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
                  { [@"update\update.rpf"] = cleanUpdate }
                : null;

            if (!string.IsNullOrWhiteSpace(gtaPath) && Directory.Exists(gtaPath))
            {
                EmitScanProgress(45, "archive", "update.rpf");
                foreach (var (key, idx) in Core.Services.OptimizationModStateResolver.Resolve(gtaPath, catalog, cleanFor))
                {
                    selections[key] = idx;
                    if (idx is null && !custom.Contains(key)) custom.Add(key);
                    if (idx is null) markers[key] = "custom";
                }

                var interiorGroups = catalog.Groups
                    .Where(x => x.Methods.Contains("interior", StringComparer.OrdinalIgnoreCase))
                    .ToList();
                if (interiorGroups.Count > 0)
                {
                    foreach (var g in interiorGroups) selections[g.Key] = null;
                    StartInteriorScan(gtaPath, interiorGroups);
                }
            }
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"[optimization] состояние модовых групп не прочитано: {ex.Message}");
        }

        EmitScanProgress(100, "done");
        return new OptimizationResolutionDto(selections, r.UnmappedKeys, custom,
                                             markers.Count > 0 ? markers : null);
    });

    private static string InteriorCachePath
        => Path.Combine(Core.System.AppDataRoot.DefaultCacheRoot, "interiors.json");

    private int _interiorScanRunning;

    private void StartInteriorScan(string gtaPath,
                                   IReadOnlyList<Core.Services.OptimizationGroup> groups)
    {
        if (Interlocked.Exchange(ref _interiorScanRunning, 1) == 1) return;

        _ = Task.Run(() =>
        {
            try
            {
                EmitScanProgress(70, "gamefiles", "архивы игры и DLC-паки");
                var report = Core.Services.InteriorClutterDetector.Detect(
                    gtaPath, cachePath: InteriorCachePath);

                foreach (var g in groups)
                {
                    int? idx;
                    string? marker = null;
                    switch (report.State)
                    {
                        case Core.Services.InteriorClutterDetector.State.Stripped:
                            idx = g.Options.FirstOrDefault(o => o.Idx != g.ResetIndex)?.Idx ?? 1;
                            break;
                        case Core.Services.InteriorClutterDetector.State.Vanilla:
                            idx = g.ResetIndex;
                            break;
                        case Core.Services.InteriorClutterDetector.State.Custom:
                            idx = null; marker = "custom";
                            break;
                        default:
                            idx = null; marker = "unknown";
                            break;
                    }
                    _emitEvent?.Invoke("optimization:interiorState",
                                       new OptimizationInteriorStateDto(g.Key, idx, marker));
                }
                EmitScanProgress(100, "done");
            }
            catch (Exception ex)
            {
                Debug.WriteLine($"[optimization] интерьеры не проверены: {ex.Message}");
                foreach (var g in groups)
                    _emitEvent?.Invoke("optimization:interiorState",
                                       new OptimizationInteriorStateDto(g.Key, null, "unknown"));
            }
            finally { Interlocked.Exchange(ref _interiorScanRunning, 0); }
        });
    }

    public Task<OptimizationApplyResultDto> OptimizationApplyAsync(
        IReadOnlyList<OptimizationSelectionDto> selections) => Task.Run(async () =>
    {
        var catalog = await OptRepo.GetAsync();
        var picks = selections
            .Select(s => new Core.Services.OptimizationApplyService.Selection(s.Key, s.OptionIdx))
            .ToList();

        var outcome = await _optApply.ApplyAsync(picks, catalog, GameGeneration, userTier: null);
        var warnings = new List<string>(outcome.Warnings);

        var modPicks = picks
            .Where(p => catalog.Find(p.GroupKey) is { Enabled: true } g
                        && g.Methods.Contains("mod", StringComparer.OrdinalIgnoreCase))
            .ToList();

        if (outcome.Success && modPicks.Count > 0)
        {
            var modOutcome = await ApplyOptimizationModsAsync(modPicks, catalog, warnings);
            if (!modOutcome.Success)
                return new OptimizationApplyResultDto(
                    false, modOutcome.ErrorMessage,
                    Array.Empty<OptimizationKeyChangeDto>(), warnings,
                    outcome.TargetPath, outcome.BackupPath,
                    outcome.GameWasRunning, outcome.BaselineCaptured);
        }

        return new OptimizationApplyResultDto(
            outcome.Success,
            outcome.ErrorMessage,
            outcome.Changes.Select(c => new OptimizationKeyChangeDto(c.Key, c.From, c.To, c.GroupKey)).ToList(),
            warnings,
            outcome.TargetPath,
            outcome.BackupPath,
            outcome.GameWasRunning,
            outcome.BaselineCaptured);
    });

    private async Task<Core.Services.OptimizationModApplyService.Outcome> ApplyOptimizationModsAsync(
        IReadOnlyList<Core.Services.OptimizationApplyService.Selection> picks,
        Core.Services.OptimizationCatalog catalog,
        List<string> warnings)
    {
        var gtaPath = await GetGtaPathAsync();
        if (string.IsNullOrWhiteSpace(gtaPath) || !Directory.Exists(gtaPath))
            return new Core.Services.OptimizationModApplyService.Outcome(
                false, "папка GTA не найдена", Array.Empty<string>(), Array.Empty<string>(), 0);

        var clean = _backupService.GetCleanUpdateRpfPath();
        if (clean is null)
            return new Core.Services.OptimizationModApplyService.Outcome(
                false,
                "нет чистой копии update.rpf - сделай резервную копию игры, " +
                "без неё правки лягут поверх чужих и снять их будет нечем",
                Array.Empty<string>(), Array.Empty<string>(), 0);

        using var _mtx = await MiamiGraphics.Shell.Services.UpdateRpfMutex.AcquireAsync("optimization-mods");

        var updateRpf = Path.Combine(gtaPath, "update", "update.rpf");
        var rollback = updateRpf + ".preinstall";

        if (!await _backupService.RestoreFromCleanAsync(gtaPath, CancellationToken.None))
            return new Core.Services.OptimizationModApplyService.Outcome(
                false, "не удалось восстановить чистый update.rpf",
                Array.Empty<string>(), Array.Empty<string>(), 0);

        try
        {
            await Task.Run(() => File.Copy(updateRpf, rollback, overwrite: true));
        }
        catch (Exception ex)
        {
            warnings.Add($"снимок перед инжектом не сделан: {ex.Message}");
        }

        var svc = new Core.Services.OptimizationModApplyService(gtaPath);
        var result = await svc.ApplyAsync(
            picks, catalog,
            new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
            {
                [@"update\update.rpf"] = clean,
            });

        if (!result.Success)
        {
            try
            {
                if (File.Exists(rollback))
                {
                    await Task.Run(() => File.Copy(rollback, updateRpf, overwrite: true));
                    warnings.Add("инжект не удался - архив возвращён к состоянию до установки");
                }
            }
            catch (Exception ex) { warnings.Add($"откат не удался: {ex.Message}"); }
        }

        warnings.AddRange(result.Skipped);
        try { if (File.Exists(rollback)) File.Delete(rollback); } catch { }

        return result;
    }

    public Task<OptimizationResolutionDto> OptimizationResolveFromPresetAsync(string presetId)
        => Task.Run(async () =>
    {
        var preset = await _gtaPresetsRepo.GetByIdAsync(presetId)
                     ?? throw new InvalidOperationException($"пресет '{presetId}' не найден");
        var xml = await new HttpClient().GetStringAsync(preset.XmlUrl);
        var catalog = await OptRepo.GetAsync();
        var r = Core.Services.OptimizationPresetResolver.Resolve(xml, catalog);
        return new OptimizationResolutionDto(r.Selections, r.UnmappedKeys, r.CustomGroups);
    });

