    private static Core.Services.GtaSettingsModel ToCore(GtaSettingsModelDto dto) => new()
    {
        ScreenWidth     = dto.Display.ScreenWidth,
        ScreenHeight    = dto.Display.ScreenHeight,
        RefreshRate     = dto.Display.RefreshRate,
        AspectRatio     = dto.Display.AspectRatio,
        Windowed        = dto.Display.Windowed,
        VSync           = dto.Display.VSync,

        TextureQuality  = dto.Quality.TextureQuality,
        ShaderQuality   = dto.Quality.ShaderQuality,
        WaterQuality    = dto.Quality.WaterQuality,
        ParticleQuality = dto.Quality.ParticleQuality,
        PostFx          = dto.Quality.PostFx,
        ShadowQuality   = dto.Quality.ShadowQuality,

