    public async Task<MirrorProbeResultDto> MirrorProbeAsync(string? choice)
    {

        var previousOverride = MiamiGraphics.Core.System.MirrorSelector.Current?.Name == "russian" ? "ru"
                            : MiamiGraphics.Core.System.MirrorSelector.Current?.Name == "primary" ? "eu"
                            : null;
        try
        {
            MiamiGraphics.Core.System.MirrorSelector.SetManualOverride(choice);

            using var http = HttpClientFactory.CreateFragmenting(TimeSpan.FromSeconds(15));
            var baseUri = choice == "ru"
                ? "http://ru.miamigraphicsstorage.uk"
                : "https://cdn.miamigraphicsstorage.uk";
            var sw = Stopwatch.StartNew();
            using var resp = await http.GetAsync($"{baseUri}/tools/tool.zip",
                HttpCompletionOption.ResponseHeadersRead);
            if (!resp.IsSuccessStatusCode)
                return new MirrorProbeResultDto(false, choice ?? "unknown", null,
                    $"HTTP {(int)resp.StatusCode}");
            await using var s = await resp.Content.ReadAsStreamAsync();
            var buf = new byte[64 * 1024];
            long got = 0;
            int n;
            while ((n = await s.ReadAsync(buf)) > 0 && got < 2L * 1024 * 1024)
                got += n;
            sw.Stop();
            var mbps = got / 1024.0 / 1024.0 / Math.Max(sw.Elapsed.TotalSeconds, 0.001);
            return new MirrorProbeResultDto(true, choice ?? "auto", mbps, null);
        }
        catch (Exception ex)
        {
            return new MirrorProbeResultDto(false, choice ?? "unknown", null, ex.Message);
        }
        finally
        {

            MiamiGraphics.Core.System.MirrorSelector.SetManualOverride(previousOverride);
        }
    }

