    public async Task<RendererTestRenderDto> RendererTestRenderAsync()
    {
        var sw = System.Diagnostics.Stopwatch.StartNew();
        var probe = MiamiGraphics.Shell.Services.RendererBootstrapper.Probe();
        if (!probe.IsUsable)
        {
            return new RendererTestRenderDto(
                false, sw.ElapsedMilliseconds, null, null, null, null,
                $"Renderer не готов: {probe.ActionableHint}");
        }

        var rendererDir = probe.RendererPath;
        var nodeExe = Path.Combine(rendererDir, "node.exe");
        var renderJs = Path.Combine(rendererDir, "render.js");
        var testGlb = FindTestGlbForRendererCheck() ?? GenerateMinimalTestGlb();
        var outPng = Path.Combine(Path.GetTempPath(), $"miami_render_test_{Guid.NewGuid():N}.png");

        try
        {
            var psi = new System.Diagnostics.ProcessStartInfo
            {
                FileName = nodeExe,
                WorkingDirectory = rendererDir,
                UseShellExecute = false,
                RedirectStandardOutput = true,
                RedirectStandardError = true,
                CreateNoWindow = true,
            };
            psi.Environment["PUPPETEER_CACHE_DIR"] = MiamiGraphics.Shell.Services.RendererBootstrapper.PuppeteerCacheDir;
            psi.ArgumentList.Add(renderJs);
            psi.ArgumentList.Add(testGlb);
            psi.ArgumentList.Add(outPng);
            psi.ArgumentList.Add("512");
            psi.ArgumentList.Add("256");

            using var proc = System.Diagnostics.Process.Start(psi);
            if (proc is null)
            {
                return new RendererTestRenderDto(
                    false, sw.ElapsedMilliseconds, null, null, null, null,
                    "Process.Start вернул null - antivirus заблокировал запуск node.exe?");
            }

            var stdoutSb = new System.Text.StringBuilder();
            var stderrSb = new System.Text.StringBuilder();
            var stdoutTask = Task.Run(async () => stdoutSb.Append(await proc.StandardOutput.ReadToEndAsync()));
            var stderrTask = Task.Run(async () => stderrSb.Append(await proc.StandardError.ReadToEndAsync()));

            var exited = proc.WaitForExit(60_000);
            if (!exited)
            {
                try { proc.Kill(entireProcessTree: true); } catch { }
                return new RendererTestRenderDto(
                    false, sw.ElapsedMilliseconds, null, null,
                    Tail(stdoutSb.ToString(), 800), Tail(stderrSb.ToString(), 800),
                    "Превысил 60s timeout - node.exe завис.");
            }
            await Task.WhenAll(stdoutTask, stderrTask);
            sw.Stop();

            var stdout = stdoutSb.ToString();
            var stderr = stderrSb.ToString();
            var exit = proc.ExitCode;
            long? bytes = null;
            try { if (File.Exists(outPng)) bytes = new FileInfo(outPng).Length; } catch { }

            if (exit == 0 && bytes.HasValue && bytes > 0)
            {
                return new RendererTestRenderDto(
                    true, sw.ElapsedMilliseconds, bytes, outPng,
                    Tail(stdout, 800), null, null);
            }

            return new RendererTestRenderDto(
                false, sw.ElapsedMilliseconds, bytes, outPng,
                Tail(stdout, 800), Tail(stderr, 800),
                $"node exit={exit}" + (bytes is null ? ", PNG не создан" : $", PNG={bytes} bytes"));
        }
        catch (Exception ex)
        {
            sw.Stop();
            return new RendererTestRenderDto(
                false, sw.ElapsedMilliseconds, null, null, null, null,
                $"{ex.GetType().Name}: {ex.Message}");
        }
        finally
        {
            try { if (File.Exists(outPng)) File.Delete(outPng); } catch { }
        }
    }

    private static string Tail(string s, int max)
    {
        if (string.IsNullOrEmpty(s)) return string.Empty;
        if (s.Length <= max) return s;
        return "…" + s.Substring(s.Length - max);
    }

