    private static string? FindTestGlbForRendererCheck()
    {
        var cacheRoot = Core.System.AppDataRoot.CacheRoot;
        var candidates = new[]
        {
            Path.Combine(cacheRoot, "gunpacks"),
            Path.Combine(cacheRoot, "armor"),
            Path.Combine(AppContext.BaseDirectory, "additionals", "test"),
        };
        foreach (var dir in candidates)
        {
            if (!Directory.Exists(dir)) continue;
            try
            {
                var glb = Directory.EnumerateFiles(dir, "*.glb", SearchOption.AllDirectories)
                    .OrderBy(p => new FileInfo(p).Length)
                    .FirstOrDefault();
                if (glb is not null) return glb;
            }
            catch { }
        }
        return null;
    }

    private static string GenerateMinimalTestGlb()
    {
        var path = Path.Combine(Path.GetTempPath(), "miami_renderer_smoke.glb");
        if (File.Exists(path)) return path;

        const string json = @"{""asset"":{""version"":""2.0""},""scenes"":[{""nodes"":[]}],""scene"":0}";
        var jsonBytes = System.Text.Encoding.UTF8.GetBytes(json);
        var pad = (4 - (jsonBytes.Length % 4)) % 4;
        if (pad > 0)
        {
            Array.Resize(ref jsonBytes, jsonBytes.Length + pad);
            for (int i = jsonBytes.Length - pad; i < jsonBytes.Length; i++) jsonBytes[i] = 0x20;
        }

        var totalLength = 12 + 8 + jsonBytes.Length;
        using var fs = File.Create(path);
        using var bw = new BinaryWriter(fs);
        bw.Write(0x46546C67);
        bw.Write(2);
        bw.Write(totalLength);
        bw.Write(jsonBytes.Length);
        bw.Write(0x4E4F534A);
        bw.Write(jsonBytes);
        return path;
    }

