    public async Task<ServerRegionPingDto> ServerRegionPingAsync()
    {

        using var http = new HttpClient(new Services.FragmentingHttpHandler())
        {
            Timeout = TimeSpan.FromSeconds(4),
        };

        var euTask = MeasureAsync(http, Services.ServerRegionConfig.PrimaryUrl(Services.ServerRegion.Eu));
        var ruTask = MeasureAsync(http, Services.ServerRegionConfig.PrimaryUrl(Services.ServerRegion.Ru));
        await Task.WhenAll(euTask, ruTask);
        return new ServerRegionPingDto(euTask.Result, ruTask.Result);

        static async Task<int?> MeasureAsync(HttpClient http, string baseUrl)
        {
            try
            {
                var sw = Stopwatch.StartNew();
                using var resp = await http.GetAsync($"{baseUrl}/rest/v1/");
                sw.Stop();

                return (int)sw.ElapsedMilliseconds;
            }
            catch
            {
                return null;
            }
        }
    }

