    public async Task<DownloadSourceEvalDto> DownloadSourceEvaluateEuAsync(string? zapretRootPath)
    {
        bool restarted = false;
        string? msg = null;

        var det = Services.ZapretIntegration.Detect(zapretRootPath);
        bool configured = det.ConfiguredForUs;
        if (det.DetectedRoot is { } root)
        {
            try
            {
                var apply = Services.ZapretIntegration.ApplyWhitelist(root);
                configured = configured || apply.Success;
                if (apply.Success && apply.DomainLinesAdded > 0)
                {
                    var rr = Services.ZapretIntegration.RestartRunning();
                    restarted = rr.Restarted;
                    if (!rr.Restarted) msg = rr.Message;
                }
            }
            catch (Exception ex) { msg = ex.Message; }
        }
        else
        {
            msg = "Запрет не найден. Установи/запусти его или укажи путь в настройках.";
        }

        double mbps = 0;
        try
        {
            using var http = HttpClientFactory.CreateFragmenting(TimeSpan.FromSeconds(14));
            const string probe = "https://cdn.miamigraphicsstorage.uk/gta_versions/1.0.3788.0/clean_update.rpf";
            using var req = new HttpRequestMessage(HttpMethod.Get, probe);
            req.Headers.Range = new System.Net.Http.Headers.RangeHeaderValue(0, 6L * 1024 * 1024 - 1);
            using var cts = new CancellationTokenSource(TimeSpan.FromSeconds(12));
            var sw = Stopwatch.StartNew();
            using var resp = await http.SendAsync(req, HttpCompletionOption.ResponseHeadersRead, cts.Token);
            resp.EnsureSuccessStatusCode();
            await using var s = await resp.Content.ReadAsStreamAsync(cts.Token);
            var buf = new byte[128 * 1024];
            long got = 0; int n;
            while (got < 6L * 1024 * 1024 && (n = await s.ReadAsync(buf, cts.Token)) > 0)
                got += n;
            sw.Stop();
            mbps = got / 1024.0 / 1024.0 / Math.Max(sw.Elapsed.TotalSeconds, 0.001);
        }
        catch (Exception ex)
        {
            msg ??= ex.Message;
            mbps = 0;
        }

        bool euWorks = mbps >= 1.0;
        return new DownloadSourceEvalDto(euWorks, mbps, configured, restarted, msg);
    }

    public Task<PcDiagReportDto> PcDiagReportAsync() => Task.Run(() =>
    {
        var sw = global::System.Diagnostics.Stopwatch.StartNew();
        string? gtaPath = null;
        try { gtaPath = new HardwareLocator().FindGtaPath(); } catch { }
        var snap = MiamiGraphics.Core.PcDiag.PcDiagSnapshotService.Take(
            string.IsNullOrWhiteSpace(gtaPath) ? null : gtaPath);
        var findings = MiamiGraphics.Core.PcDiag.PcDiagRules.Evaluate(snap);
        var rating = MiamiGraphics.Core.PcDiag.PcDiagCpuRating.Rate(snap.Cpu);
        var ramRating = MiamiGraphics.Core.PcDiag.PcDiagRamRating.Rate(snap);
        var diskRating = MiamiGraphics.Core.PcDiag.PcDiagDiskRating.Rate(snap);

        var findingDtos = findings.Select(f => new PcDiagFindingDto(
            f.Id, f.Severity.ToString(), f.Category.ToString(),
            new Dictionary<string, string>(f.Data),
            f.GainMinPercent, f.GainMaxPercent,
            f.AutoFixable && MiamiGraphics.Core.PcDiag.PcDiagApplier.CanApply(f.Id))).ToList();

        try
        {
            var settingsPath = MiamiGraphics.Core.Services.GtaSettingsService.GetSettingsPath();
            if (File.Exists(settingsPath))
            {
                var analysis = new MiamiGraphics.Core.Services.GtaSettingsAnalyzer().Analyze(File.ReadAllText(settingsPath));
                if (analysis.GainPercent >= 8)
                    findingDtos.Add(new PcDiagFindingDto(
                        "gta-settings-headroom", "Major", "Game",
                        new Dictionary<string, string> { ["gain"] = analysis.GainPercent.ToString() },
                        null, analysis.GainPercent, AutoFixable: false));
            }
        }
        catch {}

        sw.Stop();

        static int Gb(long bytes) => (int)Math.Round(bytes / (1024.0 * 1024 * 1024));

        var dto = new PcDiagReportDto(
            CpuName: snap.Cpu?.Name ?? "",
            CpuCores: snap.Cpu?.Cores ?? 0,
            CpuThreads: snap.Cpu?.Threads ?? 0,
            CpuL3Mb: (snap.Cpu?.L3CacheKb ?? 0) / 1024,
            CpuTier: rating.Tier.ToString(),
            CpuFamily: rating.FamilyLabel,
            CpuHybrid: rating.IsHybrid,
            CpuX3D: rating.IsX3D,
            CpuLaptop: rating.IsLaptop,
            RamTotalGb: Gb(snap.TotalRamBytes),
            RamSlotsTotal: snap.RamSlotsTotal,
            RamTier: ramRating.Tier.ToString(),
            RamTierNote: ramRating.Note,
            RamSticks: snap.RamSticks.Select(s => new PcDiagRamStickDto(
                Slot: s.SlotName.Length > 0 ? s.SlotName : RamSlotLabel(s.BankLabel, s.DeviceLocator),
                CapacityGb: Gb(s.CapacityBytes),
                RatedMt: s.RatedMt,
                ConfiguredMt: s.ConfiguredMt,
                MemType: s.SmbiosMemoryType switch { 26 => "DDR4", 34 => "DDR5", 24 => "DDR3", _ => "" })).ToList(),
            Disks: snap.Disks.Select(d => new PcDiagDiskDto(
                d.Model, d.Media.ToString(), d.Bus.ToString(), Gb(d.SizeBytes))).ToList(),
            Gpus: snap.Gpus.Select(g => new PcDiagGpuDto(
                g.Name, Gb(g.VramBytes), g.DriverVersion,
                g.DriverDate?.ToString("dd.MM.yyyy") ?? "", g.IsIntegrated)).ToList(),
            PowerScheme: snap.Power?.SchemeName ?? "",
            PowerKind: snap.Power?.Kind.ToString() ?? "",
            VbsRunning: snap.Security?.VbsRunning ?? false,
            GameDvrOn: (snap.GameDvr?.GameDvrEnabled ?? true) || (snap.GameDvr?.AppCaptureEnabled ?? true),
            HasBattery: snap.HasBattery,
            OsCaption: snap.Os?.Caption ?? "",
            DisplayWidth: snap.Display?.Width ?? 0,
            DisplayHeight: snap.Display?.Height ?? 0,
            DisplayCurrentHz: snap.Display?.CurrentHz ?? 0,
            DisplayMaxHz: snap.Display?.MaxHz ?? 0,
            Monitors: snap.Monitors.Select(m => new PcDiagMonitorDto(
                m.Name, m.DeviceName, m.Adapter, m.Width, m.Height, m.CurrentHz, m.MaxHz, m.IsPrimary)).ToList(),
            NetWired: snap.Network?.HasWiredActive ?? false,
            NetWireless: snap.Network?.HasWirelessActive ?? false,
            NetVpn: snap.Network?.HasVpnActive ?? false,
            GtaPath: snap.Game?.GtaPath ?? "",
            GtaDiskMedia: snap.Game?.Media.ToString() ?? "",
            DiskTier: diskRating.Tier.ToString(),
            DiskTierNote: diskRating.Note,
            Background: snap.HeavyProcesses.Select(h => new PcDiagBgDto(
                h.DisplayName, h.Count, Math.Round(h.WorkingSetBytes / (1024.0 * 1024 * 1024), 1))).ToList(),
            SensorErrors: snap.CollectorErrors.Keys.ToList(),
            Findings: findingDtos,
            ElapsedMs: sw.ElapsedMilliseconds);

        _lastReport = dto;
        _lastReportAtUtc = DateTime.UtcNow;
        return dto;
    });

    private static PcDiagReportDto? _lastReport;
    private static DateTime _lastReportAtUtc;

