    private async Task<PcDiagReportDto> ReportForAiAsync()
    {
        var last = _lastReport;
        if (last != null && DateTime.UtcNow - _lastReportAtUtc < TimeSpan.FromMinutes(15))
            return last;
        return await PcDiagReportAsync();
