    private static string RamSlotLabel(string bankLabel, string deviceLocator)
    {
        var bank = (bankLabel ?? "").Trim();
        var locator = (deviceLocator ?? "").Trim();

        var channel = global::System.Text.RegularExpressions.Regex.Match(
            bank, @"CHANNEL\s*([A-Z])", global::System.Text.RegularExpressions.RegexOptions.IgnoreCase);
        var letter = channel.Success ? channel.Groups[1].Value.ToUpperInvariant() : "";

        if (letter.Length > 0 && locator.Length > 0) return letter + " · " + locator;
        if (locator.Length > 0) return locator;
        if (bank.Length > 0) return bank;
        return "?";
    }

    public Task<PcDiagApplyResultDto> PcDiagApplyAsync(string findingId) => Task.Run(() =>
    {
        var r = MiamiGraphics.Core.PcDiag.PcDiagApplier.Apply(findingId);
        return new PcDiagApplyResultDto(r.Ok, r.Message, r.RequiresRestart);
    });

    public Task<PcDiagApplyResultDto> PcDiagRevertAsync(string findingId) => Task.Run(() =>
    {
        var r = MiamiGraphics.Core.PcDiag.PcDiagApplier.Revert(findingId);
        return new PcDiagApplyResultDto(r.Ok, r.Message, r.RequiresRestart);
    });

    public Task<List<PcDiagJournalEntryDto>> PcDiagJournalAsync() => Task.Run(() =>
        MiamiGraphics.Core.PcDiag.PcDiagApplier.ReadJournal()
            .Select(e => new PcDiagJournalEntryDto(e.Id, e.AppliedAtUtc.ToString("o"), e.Reverted))
            .ToList());

    public async Task<PcDiagAiResultDto> PcDiagAiAsync(string userId, string? question, List<PcDiagAiMsgDto>? history)
    {
        if (string.IsNullOrWhiteSpace(userId))
            return new PcDiagAiResultDto(false, "", "guest");
        try
        {
            var report = await ReportForAiAsync();

            var tweaks = await PcDiagTweaksAsync();
            var journal = await PcDiagJournalAsync();
            var applied = journal.Where(e => !e.Reverted).Select(e => e.Id).ToList();

            var gameSettings = report.Findings.FirstOrDefault(f => f.Id == "gta-settings-headroom");

            var payload = new
            {
                userId,
                report,
                tweaks = tweaks
                    .Where(x => x.State != "NotApplicable")
                    .Select(x => new { title = PcDiagTweakTitle(x.Id), grade = x.Grade, state = x.State })
                    .ToList(),
                applied = applied.Select(PcDiagTweakTitle).ToList(),
                gameSettingsHeadroomPercent = gameSettings != null
                    && gameSettings.Data.TryGetValue("gain", out var gain) ? gain : null,
                question = string.IsNullOrWhiteSpace(question) ? null : question,
                history = history?.Select(h => new { role = h.Role, text = h.Text }).ToList(),
            };
            return await _supabase.PcDiagAiAsync(payload);
        }
        catch (Exception ex)
        {
            global::System.Diagnostics.Debug.WriteLine($"[pcdiag-ai] {ex.Message}");
            return new PcDiagAiResultDto(false, "", "ai_failed");
        }
    }

    public Task<List<PcDiagTweakDto>> PcDiagTweaksAsync() => Task.Run(() =>
    {
        string? gtaPath = null;
        try { gtaPath = new HardwareLocator().FindGtaPath(); } catch { }
        return MiamiGraphics.Core.PcDiag.PcDiagTweakCatalog.List(
                string.IsNullOrWhiteSpace(gtaPath) ? null : gtaPath)
            .Select(x => new PcDiagTweakDto(x.Id, x.Grade, x.RequiresRestart, x.InAllSafe,
                x.State.ToString(), x.Data))
            .ToList();
    });
}
